  return isNaN(d) ? '' : 周几名[d.getDay()];
}
const 补零 = n => String(n).padStart(2, '0');
function 时刻转分(t) { const m = /^(\d{1,2}):(\d{2})$/.exec(String(t || '')); return m ? Number(m[1]) * 60 + Number(m[2]) : NaN; }
function 分转时刻(n) { return 补零(Math.floor(n / 60) % 24) + ':' + 补零(n % 60); }
function 时段名(时刻) {
  const n = 时刻转分(时刻);
  if (isNaN(n)) return '';
  if (n < 5 * 60) return '深夜';
  if (n < 10 * 60) return '早上';
  if (n < 16 * 60) return '白天';
  if (n < 19 * 60) return '傍晚';
  return '晚上';
}
// 「2020-04-17 周五 19:40」，全局数据表·当前时间的写法
function 当前时间串(日期, 时刻) {
  return [日期, 周几(日期), 时刻].filter(Boolean).join(' ');
}

const 随机取 = 列 => 列[Math.floor(Math.random() * 列.length)];
function 随机日期(年, 时节) {
  const 季 = 时节表.find(x => x.名 === 时节) || 时节表[0];
  const 起 = new Date(Number(年), Number(季.起.slice(0, 2)) - 1, Number(季.起.slice(3)));
  const 止 = new Date(Number(年), Number(季.止.slice(0, 2)) - 1, Number(季.止.slice(3)));
  const d = new Date(起.getTime() + Math.floor(Math.random() * ((止 - 起) / 864e5 + 1)) * 864e5);
  return d.getFullYear() + '-' + 补零(d.getMonth() + 1) + '-' + 补零(d.getDate());
}
function 随机时刻() {
  const 段 = 随机取(时段表);
  const a = 时刻转分(段.起), b = 时刻转分(段.止);
  return 分转时刻(a + Math.floor(Math.random() * ((b - a) / 10 + 1)) * 10);
}
// 日期落在哪个时节（自己改了日期以后，时节跟着对上）
// 片区写法不统一：0 层卡写「丰岛 · 池袋」「文京」，地图点位写「丰岛・池袋」「东京・文京」。去掉点和空格再比，对上结尾就算同一片
function 片区键(片区) { return String(片区 || '').replace(/[\s·・]/g, ''); }
function 同片区(甲, 乙) { const a = 片区键(甲), b = 片区键(乙); return !!a && !!b && (a === b || a.endsWith(b) || b.endsWith(a)); }
// 房价：方式「买」回买价，「租」回每月房租；户型单间、两居、独栋
function 房价(片区, 户型, 方式) {
  const 档 = 房价表.find(x => x.片区.some(p => 同片区(片区, p))) || 房价表[房价表.length - 1];
  const 买 = 档[户型];
  if (!买) return 0;
  return 方式 === '租' ? Math.round(档.租 * 买 / 档.单间 / 1000) * 1000 : 买;
}
function 日期的时节(日期) {
  const md = String(日期 || '').slice(5, 10);
  if (!/^\d{2}-\d{2}$/.test(md)) return '';
  // 照时节分界切：起点不晚于这一天的最后一季；比第一季还早（1 月到春的起点前）算上一年的冬
  let 季 = 时节分界[时节分界.length - 1];
  for (const x of 时节分界) if (x.起 <= md) 季 = x;
  return 季.名;
}

const 查人 = 名 => 名单.find(x => x.名 === 名) || null;
// 艺名、别名（角色条目的触发词，只收指向一个人的，构建时生成）、带括号的写法归到规范名；归不上返回空
function 归名(名) {
  const s = String(名 || '').trim();
  if (!s) return '';
  const 认 = t => {
    const 原 = String(t || '').trim(), k = 原.toLowerCase();
    if (!k) return '';
    const x = 名单.find(p => p.名 === 原)
      || 名单.find(p => (p.艺名 && p.艺名.toLowerCase() === k) || (p.别名 || []).some(a => a.toLowerCase() === k));
    return x ? x.名 : '';
  };
  const 直 = 认(s);
  if (直) return 直;
  // 「香澄（户山香澄）」「和奏瑞依（LAYER）」：去掉括号认一次，再认括号里的
  const 外 = s.replace(/[（(][^）)]*[）)]/g, '').trim();
  const 里 = (/[（(]([^）)]+)[）)]/.exec(s) || [])[1] || '';
  return (外 && 外 !== s && 认(外)) || (里 && 认(里)) || '';
}
// 物品按名字猜一类（规则在 数据.js 的 物品猜类），猜不出是「其他」
function 猜物品类(名) {
  const s = String(名 || '').trim();
  for (const [类, 规则] of 物品猜类) if (规则.test(s)) return 类;
  return '其他';
}
