// 整页塞进正则的话，流式输出时每吐一段字酒馆都要把它重新格式化一遍。
const 页面源 = {"开局卡":"<!DOCTYPE html>\n<html lang=\"zh-CN\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>开局<\/title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link href=\"https://fonts.googleapis.com/css2?family=Fredoka:wght@500;600;700&family=Noto+Sans+SC:wght@500;700;900&display=swap\" rel=\"stylesheet\">\n<style>\n/* 令牌：颜色、字体、阴影、曲线。数值照 DESIGN.md（取自角色面板 :root），0 层卡、1 楼回执、面板共用。 */\n:root{\n  --bg:#fdfaf7; --card:#ffffff; --card-2:#f6f2ee; --row:#f2eef8;\n  --ink:#3a3448; --ink-soft:#8b849c; --ink-dim:#c7c1d6; --line:#ece7f0;\n  --accent:#ff4d7d;\n  --accent-soft:color-mix(in srgb, var(--accent) 18%, #ffffff);\n  --accent-soft-2:color-mix(in srgb, var(--accent) 30%, #ffffff);\n  --accent-deep:color-mix(in srgb, var(--accent) 72%, #222222);\n  --accent-line:color-mix(in srgb, var(--accent) 35%, var(--line));\n  --accent-glow:color-mix(in srgb, var(--accent) 45%, transparent);\n  --ok:#3fae8c; --ok-soft:#e3f5ee; --ok-deep:#2c7a62;\n  --veil:rgba(40,30,60,.16);\n  --shadow:0 10px 28px rgba(70,50,90,.10), 0 2px 8px rgba(70,50,90,.06);\n  --shadow-float:0 18px 40px rgba(70,50,90,.18);\n  --font-display:'Fredoka','Arial Rounded MT Bold','Segoe UI',sans-serif;\n  --font-body:'Noto Sans SC','PingFang SC','Microsoft YaHei',sans-serif;\n  --ease:cubic-bezier(.22,1,.36,1);\n  --bounce:cubic-bezier(.34,1.56,.64,1);\n  --flip:cubic-bezier(.4,.1,.2,1);\n}\n*{box-sizing:border-box;}\nhtml,body{margin:0;padding:0;background:transparent;color:var(--ink);font-family:var(--font-body);}\nbody{font-size:14px;line-height:1.6;-webkit-font-smoothing:antialiased;}\nbutton,input,textarea,select{font:inherit;color:inherit;}\nbutton{cursor:pointer;border:none;background:none;padding:0;}\nbutton:disabled{cursor:default;}\n:focus{outline:none;}\n:focus-visible{outline:2px solid var(--accent);outline-offset:2px;}\n\n@keyframes thCardIn{from{opacity:0;transform:translateY(9px) scale(.97)}to{opacity:1;transform:none}}\n@keyframes thSheetIn{from{opacity:0;transform:scale(1.045)}to{opacity:1;transform:scale(1)}}\n@keyframes thResultIn{from{opacity:0;transform:translateY(-5px)}to{opacity:1;transform:none}}\n@keyframes thPinDrop{0%{opacity:0;transform:translateY(-26px) scale(.8)}65%{opacity:1;transform:translateY(0) scale(1.06)}100%{opacity:1;transform:none}}\n@keyframes pickPop{0%{transform:scale(1)}45%{transform:scale(1.045)}100%{transform:scale(1)}}\n@keyframes foldAway{from{opacity:1;transform:none}to{opacity:0;transform:translateY(-8px)}}\n@keyframes unfold{from{opacity:0;transform:translateY(-8px)}to{opacity:1;transform:none}}\n@keyframes wmSlide{from{opacity:0;transform:translateX(-40px)}to{opacity:1;transform:none}}\n\n.anim-card{animation:thCardIn .28s var(--ease) both;}\n.anim-sheet{animation:thSheetIn .46s var(--ease) both;}\n.anim-pick{animation:pickPop .24s var(--bounce);}\n.anim-done{animation:thPinDrop .38s cubic-bezier(.3,1.5,.5,1) both;}\n.anim-fold{animation:foldAway .32s var(--ease) both;}\n.anim-unfold{animation:unfold .32s var(--ease) both;}\n.anim-wm{animation:wmSlide .7s var(--flip) both;}\n.stagger > *{animation:thResultIn .22s ease both;}\n.stagger > *:nth-child(2){animation-delay:.06s;}\n.stagger > *:nth-child(3){animation-delay:.12s;}\n.stagger > *:nth-child(n+4){animation-delay:.18s;}\n\n@media (prefers-reduced-motion: reduce){\n  .anim-card,.anim-sheet,.anim-pick,.anim-done,.anim-fold,.anim-unfold,.anim-wm,.stagger > *{\n    animation:thResultIn .01s linear both !important;animation-delay:0s !important;}\n  .bar-fill i{transition:none !important;}\n}\n\n/* 组件：胶囊、输入框、小卡、锁、✦、🎲、按钮、状态签、分段、浮层。样子照 DESIGN.md 第 4 节，\n   从设计书 开局卡设计稿/_src/共用.css 搬过来，加上真能点的状态（悬停、聚焦、禁用）。 */\n\n/* 胶囊 */\n.chips{display:flex;flex-wrap:wrap;gap:8px;}\n.chip{display:inline-flex;align-items:center;gap:6px;min-height:36px;padding:7px 15px;border-radius:999px;background:var(--card-2);\n  font-size:13px;font-weight:700;color:var(--ink-soft);white-space:nowrap;transition:background .18s,color .18s,box-shadow .18s;}\n.chip:hover{color:var(--ink);}\n.chip.on{background:var(--accent);color:#fff;box-shadow:0 6px 16px var(--accent-glow);}\n.chip.off,.chip:disabled{opacity:.45;text-decoration:line-through;color:var(--ink-soft);}\n.chip.add{background:transparent;border:1.5px dashed var(--ink-dim);}\n.chip small{font-size:11px;font-weight:700;opacity:.8;}\n.chip .x{font-size:12px;opacity:.7;margin-left:2px;}\n\n/* 输入框：外层是一行（可带图标、随机签），里面的 input 透明 */\n.in{height:42px;border-radius:14px;background:var(--card-2);display:flex;align-items:center;padding:0 14px;\n  font-size:14px;font-weight:700;gap:8px;white-space:nowrap;overflow:hidden;border:2px solid transparent;transition:border-color .18s;}\n.in:focus-within{border-color:var(--accent-line);}\n.in input,.in select{flex:1;min-width:0;height:100%;border:none;background:transparent;font-weight:700;font-size:inherit;padding:0;}\n.in input::placeholder,.ta::placeholder,.fld textarea::placeholder{color:var(--ink-dim);font-weight:500;}\n.in .ic{flex:none;font-size:13px;opacity:.75;}\n.in .roll{flex:none;font-size:11px;font-weight:800;color:var(--accent-deep);background:var(--accent-soft);padding:1px 8px;border-radius:99px;}\n.in.roman input{font-family:var(--font-display);letter-spacing:.12em;text-transform:uppercase;}\n.in.sm{height:34px;border-radius:11px;font-size:12.5px;padding:0 10px;}\n.ta{display:block;width:100%;border-radius:14px;background:var(--card-2);padding:11px 14px;font-size:13px;line-height:1.7;min-height:64px;\n  border:2px solid transparent;resize:vertical;font-weight:500;transition:border-color .18s;}\n.ta:focus{border-color:var(--accent-line);}\n.ta.tall{min-height:120px;}\n\n/* ✦ AI、🎲 随机、锁 */\n.ai{display:inline-flex;align-items:center;gap:5px;min-height:26px;padding:4px 11px;border-radius:999px;border:1.5px solid var(--accent-line);\n  background:#fff;color:var(--accent-deep);font-size:11.5px;font-weight:800;white-space:nowrap;}\n.ai:hover{background:var(--accent-soft);}\n.ai:disabled{opacity:.45;background:#fff;}\n.ai.busy{opacity:.6;}\n.dice{display:inline-flex;align-items:center;gap:5px;min-height:26px;padding:4px 11px;border-radius:999px;background:var(--ink);color:#fff;\n  font-size:11.5px;font-weight:800;white-space:nowrap;}\n.dice i{font-style:normal;font-size:12px;}\n.lock{flex:none;display:inline-grid;place-items:center;width:22px;height:22px;border-radius:7px;background:var(--card-2);color:var(--ink-dim);}\n.lock:hover{color:var(--ink-soft);}\n.lock.on{background:var(--ink);color:#fff;}\n.lock svg{width:12px;height:12px;display:block;}\n.lock.sm{width:18px;height:18px;border-radius:6px;}\n.lock.sm svg{width:10px;height:10px;}\n\n/* 候选：✦ 给的几个选项 */\n.sugg{display:flex;flex-wrap:wrap;gap:6px;margin-top:8px;}\n.sugg button{padding:5px 12px;border-radius:12px;background:#fff;border:1.5px dashed var(--accent-line);font-size:12px;color:var(--ink);\n  text-align:left;white-space:normal;line-height:1.5;}\n.sugg button:hover{border-style:solid;}\n.sugg button b{color:var(--accent-deep);font-weight:900;margin-right:4px;}\n.sugg button.why{border:none;background:none;padding:5px 6px;font-size:11.5px;font-weight:800;color:var(--ink-soft);align-self:center;}\n.sugg button.why:hover{color:var(--ink);}\n\n/* 按钮 */\n.btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;padding:11px 30px;border-radius:999px;background:var(--accent);color:#fff;\n  font-weight:900;font-size:15px;box-shadow:0 8px 20px var(--accent-glow);white-space:nowrap;}\n.btn.dim,.btn:disabled{background:var(--ink-dim);box-shadow:none;}\n.btn.ghost{background:var(--card-2);color:var(--ink);box-shadow:none;font-size:13px;padding:9px 18px;}\n.btn.sm{padding:8px 18px;font-size:13px;}\n\n/* 状态签、缺项签 */\n.st{display:inline-flex;align-items:center;gap:5px;padding:3px 10px;border-radius:99px;font-size:11.5px;font-weight:800;white-space:nowrap;}\n.st.no{background:var(--card-2);color:var(--ink-soft);}\n.st.yes{background:var(--ok-soft);color:var(--ok-deep);}\n.miss{display:inline-flex;align-items:center;gap:5px;min-height:28px;padding:4px 11px;border-radius:999px;background:var(--accent-soft);color:var(--accent-deep);\n  font-size:12px;font-weight:800;white-space:nowrap;}\n.miss.none{background:var(--ok-soft);color:var(--ok-deep);}\n\n/* 三类切换 / 分段 */\n.seg2{display:inline-flex;background:var(--card-2);border-radius:999px;padding:3px;gap:2px;margin-bottom:10px;}\n.seg2 button{padding:6px 16px;min-height:32px;border-radius:999px;font-size:12.5px;font-weight:800;color:var(--ink-soft);}\n.seg2 button.on{background:#fff;color:var(--ink);box-shadow:0 2px 8px rgba(70,50,90,.12);}\n\n/* 五档水平 */\n.tier{display:flex;gap:6px;align-items:center;}\n.tier button{flex:1;height:22px;display:flex;align-items:center;}\n.tier button i{display:block;width:100%;height:8px;border-radius:99px;background:var(--line);transition:background .18s;}\n.tier button.on i{background:var(--accent);}\n.tier-lab{display:flex;justify-content:space-between;font-size:10.5px;color:var(--ink-soft);margin-top:5px;}\n.tier-lab .on{color:var(--accent-deep);font-weight:900;}\n\n/* 浮层（缺项单子等） */\n.pop{position:absolute;z-index:6;background:#fff;border-radius:16px;box-shadow:var(--shadow-float),0 2px 8px rgba(70,50,90,.08);padding:12px 14px;font-size:12.5px;}\n.pop h6{margin:0 0 6px;font-size:12px;font-weight:900;color:var(--ink-soft);}\n.pop .row{display:flex;justify-content:space-between;align-items:center;gap:16px;width:100%;padding:6px 0;border-top:1px solid var(--line);text-align:left;}\n.pop .row:first-of-type{border-top:none;}\n.pop .row span{flex:1;}\n.pop .row span.soft{color:var(--ink-soft);}\n.pop .row i{font-style:normal;font-weight:800;color:var(--accent-deep);white-space:nowrap;}\n\n/* 进度条 */\n.bar-fill{height:6px;border-radius:99px;background:var(--line);overflow:hidden;}\n.bar-fill i{display:block;height:100%;width:0;background:var(--accent);border-radius:99px;transition:width .9s var(--ease);}\n\n/* 0 层卡的版式。尺寸、圆角、字号照 DESIGN.md 第 2、3 节和文末「开局卡改版」；组件样子在 共用/组件.css。 */\n.wrap{padding:4px 0 8px;}\n\n/* 卡片 */\n.oc{position:relative;overflow:hidden;background:var(--card);border-radius:22px;box-shadow:var(--shadow);\n  padding:30px 34px 26px;color:var(--ink);font-size:13px;line-height:1.6;}\n.oc + .oc{margin-top:14px;}\n.oc-wm{position:absolute;left:16px;top:-26px;font-family:var(--font-display);font-weight:900;font-size:132px;letter-spacing:2px;\n  color:rgba(60,50,70,.06);white-space:nowrap;pointer-events:none;line-height:1.2;user-select:none;}\n.oc-wm.bleed{-webkit-mask-image:linear-gradient(90deg,#000 78%,transparent);mask-image:linear-gradient(90deg,#000 78%,transparent);}\n.oc-head{position:relative;display:flex;align-items:center;justify-content:space-between;gap:14px;margin-bottom:6px;}\n.oc-title{display:flex;align-items:baseline;gap:10px;}\n.oc-title b{font-size:26px;font-weight:900;}\n.oc-title em{font-style:normal;font-family:var(--font-display);font-weight:700;font-size:11px;letter-spacing:.3em;color:var(--ink-dim);}\n.oc-tools{display:flex;gap:6px;flex-wrap:wrap;justify-content:flex-end;}\n.oc-tool{height:30px;min-width:30px;padding:0 11px;border-radius:999px;background:var(--card-2);display:inline-flex;align-items:center;gap:6px;\n  font-size:12px;font-weight:700;color:var(--ink-soft);}\n.oc-tool:hover{color:var(--ink);}\n.oc-tools .dice{height:30px;}\n.oc-tool.open{background:var(--row);color:var(--ink);}\n.oc-tool .short{display:none;}\n.oc-sub{position:relative;color:var(--ink-soft);font-size:12px;margin:0 0 4px;}\n\n/* 曲目单：宽卡左栏一页一行（卡宽 ≤ 600px 折成横条，见下面） */\n.sl{position:relative;display:grid;grid-template-columns:150px minmax(0,1fr);gap:20px;margin-top:14px;align-items:start;}\n.sl-list{position:relative;display:flex;flex-direction:column;gap:2px;background:var(--card-2);border-radius:18px;padding:12px 8px;}\n.sl-cap{font-family:var(--font-display);font-weight:700;font-size:10.5px;letter-spacing:.24em;color:var(--ink-soft);padding:2px 10px 8px;}\n.sl-it{display:flex;gap:9px;align-items:center;width:100%;padding:7px 9px;border-radius:12px;text-align:left;color:var(--ink);transition:background .18s,box-shadow .18s;}\n.sl-it:hover{background:rgba(255,255,255,.6);}\n.sl-it .no{flex:none;width:22px;font-family:var(--font-display);font-weight:700;font-size:16px;color:var(--ink-dim);}\n.sl-it .nm{flex:1;min-width:0;}\n.sl-it b{display:flex;align-items:center;font-size:12.5px;font-weight:800;line-height:1.3;}\n.sl-it small{display:block;font-size:10.5px;color:var(--ink-soft);line-height:1.35;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}\n.sl-it.on{background:#fff;box-shadow:var(--shadow);}\n.sl-it.on .no{color:var(--accent);}\n.sl-it.done .no{color:var(--ok);}\n.sl-it.enc{margin-top:6px;padding-top:11px;border-top:2px dashed var(--ink-dim);border-radius:0 0 12px 12px;}\n.sl-it.enc .no{font-size:12px;}\n.sl-it .dotx{flex:none;width:7px;height:7px;border-radius:50%;background:var(--accent);margin-left:6px;}\n.sl-list.is-dragging{cursor:grabbing;user-select:none;}\n\n/* 页：一次只显示一页；换页从右（往后翻）或左（往前翻）滑进来 */\n.pg{display:none;min-width:0;}\n.pg.on{display:block;}\n.pg-in-r{animation:pgInR .35s var(--ease) both;}\n.pg-in-l{animation:pgInL .35s var(--ease) both;}\n@keyframes pgInR{from{opacity:0;transform:translateX(24px)}to{opacity:1;transform:none}}\n@keyframes pgInL{from{opacity:0;transform:translateX(-24px)}to{opacity:1;transform:none}}\n.pg-h{position:relative;display:flex;align-items:flex-end;gap:14px;margin:0 0 4px;}\n.pg-h .pg-no{flex:none;font-family:var(--font-display);font-weight:700;font-size:58px;line-height:.9;color:var(--accent-soft-2);}\n.pg-h .pg-t{min-width:0;}\n.pg-h .pg-t b{display:block;font-size:22px;font-weight:900;line-height:1.2;}\n.pg-h .pg-t > span{display:block;font-size:12px;color:var(--ink-soft);font-weight:500;}\n.pg-h .grow{flex:1;}\n.pg-h .ai{align-self:center;}\n.pg-nav{display:flex;justify-content:space-between;align-items:center;gap:10px;margin-top:18px;padding-top:10px;border-top:2px solid var(--line);}\n.pg-nav button{min-height:36px;font-size:12.5px;font-weight:800;color:var(--ink-soft);}\n.pg-nav button:hover{color:var(--ink);}\n.pg-nav button.next{margin-left:auto;color:var(--accent-deep);}\n.pg-nav button.next:hover{color:var(--accent);}\n\n/* 玩法条：01 世界顶上一行 */\n.mline{position:relative;display:flex;align-items:center;flex-wrap:wrap;gap:6px 12px;padding:10px 14px;border-radius:16px;background:#fff;border:1.5px dashed var(--accent-line);}\n.mline .k{font-family:var(--font-display);font-weight:700;font-size:10.5px;letter-spacing:.2em;color:var(--ink-soft);}\n.mline b{font-size:14px;font-weight:900;}\n.mline .s{min-width:0;font-size:12px;color:var(--ink-soft);}\n.mline .grow{flex:1;}\n\n/* 检查页 */\n/* 00 页的开局须知：已阅读、确认一行 */\n.ack-row{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-top:12px;padding-top:12px;border-top:2px solid var(--line);}\n.ack-row .chk{margin-top:0;}\n.sl-it:disabled{opacity:.4;cursor:default;}\n.pg-nav button:disabled{opacity:.4;cursor:default;}\n.check{display:grid;grid-template-columns:minmax(0,1fr);gap:6px;}\n.check .it{display:flex;align-items:center;gap:10px;width:100%;min-height:36px;padding:8px 12px;border-radius:12px;background:var(--card-2);font-size:12.5px;font-weight:700;text-align:left;}\n.check .it .grow{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}\n.check .it i{flex:none;width:18px;height:18px;border-radius:50%;display:grid;place-items:center;font-style:normal;font-size:10.5px;font-weight:900;background:var(--ok);color:#fff;}\n.check .it em{flex:none;font-style:normal;font-family:var(--font-display);font-weight:700;color:var(--ink-soft);}\n.check .it.bad{background:var(--accent-soft);color:var(--accent-deep);}\n.check .it.bad i{background:var(--accent);}\n.check .it.bad em{color:var(--accent-deep);}\n\n/* 角色存档浮层 */\n.oc-head .pfp{right:0;top:40px;width:330px;max-width:100%;}\n.pfp h6.gap{margin-top:12px;}\n.pfp .none{margin:2px 0 6px;font-size:12px;color:var(--ink-dim);}\n.pf{display:flex;align-items:center;gap:8px;padding:6px 0;border-top:1px solid var(--line);}\n.pfp h6 + .pf{border-top:none;}\n.pf .who{flex:1;min-width:0;}\n.pf .who b{font-size:13px;font-weight:900;}\n.pf .who em{font-style:normal;font-family:var(--font-display);font-weight:700;font-size:10.5px;letter-spacing:.12em;color:var(--ink-soft);margin-left:6px;text-transform:uppercase;}\n.pf .who small{display:block;font-size:11px;color:var(--ink-soft);font-weight:700;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}\n.pf .go{flex:none;min-height:32px;padding:0 6px;font-size:12px;font-weight:900;color:var(--accent-deep);}\n.pf .go:hover{color:var(--accent);}\n/* 圆形 × 看着 24px，能点的地方 32px */\n.pf .x{flex:none;width:32px;height:32px;border-radius:50%;display:grid;place-items:center;font-size:12px;font-weight:900;color:var(--ink-soft);\n  background:radial-gradient(circle,var(--card-2) 0 12px,transparent 12.5px);}\n.pf .x:hover{color:var(--ink);}\n.pf .x.sure{color:var(--accent-deep);background:radial-gradient(circle,var(--accent-soft) 0 12px,transparent 12.5px);}\n.pfp .add-row{display:flex;align-items:center;gap:8px;width:100%;margin:6px 0 2px;padding:8px 12px;border-radius:12px;border:1.5px dashed var(--accent-line);\n  color:var(--accent-deep);font-weight:900;font-size:12.5px;text-align:left;}\n.pfp .add-row:hover{border-style:solid;}\n.pfp .add-row small{margin-left:auto;font-size:11px;font-weight:500;color:var(--ink-soft);white-space:nowrap;}\n\n/* 身份：原作、通用两小段 */\n.sub-lab{font-size:11px;font-weight:900;color:var(--ink-dim);letter-spacing:.06em;margin:8px 0 5px;}\n.oc-lab + .sub-lab{margin-top:0;}\n.oc-hint.lead{margin:-4px 0 10px;}\n\n/* 初始好感信任：滑条，竖线是这个关系的默认值 */\n.why-b{display:inline-flex;align-items:center;min-height:26px;padding:3px 10px;border-radius:999px;background:var(--card-2);font-size:11.5px;font-weight:800;color:var(--ink);white-space:nowrap;}\n.why-b:disabled{color:var(--ink-dim);}\n.sld{display:flex;align-items:center;gap:10px;}\n.sld > span{flex:none;width:30px;font-size:12px;font-weight:800;color:var(--ink-soft);}\n.sld .tr{position:relative;flex:1;min-width:0;height:36px;display:flex;align-items:center;}\n.sld .tr::before{content:'';position:absolute;left:0;right:0;top:50%;height:8px;margin-top:-4px;border-radius:99px;\n  background:linear-gradient(90deg,var(--accent) 0 calc(10px + (100% - 20px) * var(--p)),var(--line) 0);}\n.sld .mk{position:absolute;top:50%;left:calc(10px + (100% - 20px) * var(--d));width:2px;height:18px;margin:-9px 0 0 -1px;border-radius:2px;background:var(--ink-dim);pointer-events:none;}\n.sld input[type=range]{position:relative;z-index:1;width:100%;height:36px;margin:0;background:transparent;-webkit-appearance:none;appearance:none;cursor:pointer;}\n.sld input[type=range]::-webkit-slider-runnable-track{height:36px;background:transparent;border:none;}\n.sld input[type=range]::-webkit-slider-thumb{-webkit-appearance:none;appearance:none;width:20px;height:20px;margin-top:8px;border-radius:50%;background:#fff;\n  border:2px solid var(--accent);box-shadow:0 2px 6px rgba(70,50,90,.18);}\n.sld input[type=range]::-moz-range-track{height:36px;background:transparent;border:none;}\n.sld input[type=range]::-moz-range-thumb{width:16px;height:16px;border-radius:50%;background:#fff;border:2px solid var(--accent);box-shadow:0 2px 6px rgba(70,50,90,.18);}\n.sld input[type=range]:focus-visible{outline:none;}\n.sld input[type=range]:focus-visible::-webkit-slider-thumb{outline:2px solid var(--accent);outline-offset:2px;}\n.sld input[type=range]:focus-visible::-moz-range-thumb{outline:2px solid var(--accent);outline-offset:2px;}\n.sld output{flex:none;width:50px;text-align:right;font-family:var(--font-display);font-weight:700;font-size:16px;font-variant-numeric:tabular-nums;}\n\n/* 组 */\n.oc-sec{position:relative;margin-top:20px;padding-top:18px;border-top:2px solid var(--line);}\n.oc-sec.first{border-top:none;padding-top:6px;margin-top:12px;}\n.oc-sec-h{display:flex;align-items:center;gap:10px;margin-bottom:10px;flex-wrap:wrap;}\n.oc-sec-h b{font-size:15px;font-weight:900;}\n.oc-sec-h > span{font-size:12px;color:var(--ink-soft);}\n.oc-sec-h .grow,.oc-lab .grow{flex:1;}\n.oc-hint{font-size:12px;color:var(--ink-soft);margin-top:8px;}\n.oc-hint.warn{color:var(--accent-deep);}\n/* 列的下限是 0：输入框、不换行的字不会把卡片撑宽（曲目单占了左边，正文窄了） */\n.oc-row{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:10px;}\n.oc-row.three{grid-template-columns:minmax(0,1fr) auto minmax(0,.8fr);}\n.oc-lab{font-size:12px;font-weight:800;color:var(--ink-soft);margin:10px 0 6px;display:flex;align-items:center;gap:8px;min-height:22px;}\n.oc-lab small{font-weight:500;}\n.oc-lab small.fill{flex:1;min-width:0;}\n.oc-lab .nw{white-space:nowrap;}\n.oc-row .oc-lab.top{margin-top:0;}\n\n/* 玩法 */\n.modes{display:grid;grid-template-columns:1fr 1fr;gap:12px;}\n.mode{position:relative;display:flex;flex-direction:column;justify-content:flex-start;width:100%;text-align:left;border-radius:18px;padding:16px 18px 14px;background:var(--card-2);border:2px solid transparent;overflow:hidden;}\n.mode .k{font-family:var(--font-display);font-weight:700;font-size:10.5px;letter-spacing:.2em;color:var(--ink-soft);}\n.mode b{display:block;font-size:19px;font-weight:900;margin:2px 0 6px;}\n.mode p{margin:0;font-size:12px;color:var(--ink-soft);line-height:1.65;}\n.mode.on{background:var(--accent-soft);border-color:var(--accent);}\n.mode.on .k,.mode.on p{color:var(--accent-deep);}\n.mode.soon{opacity:.6;cursor:not-allowed;}\n.mode .ribbon{position:absolute;top:12px;right:12px;padding:2px 10px;border-radius:99px;background:var(--ink);color:#fff;font-size:11px;font-weight:800;}\n.mode .subs{display:flex;gap:6px;margin-top:10px;flex-wrap:wrap;}\n#sec-配套 .oc-lab{margin-top:12px;}\n/* 窄屏放不下时折行、不截断：「· 没配」「· 冲击轮」这几个字是要看的 */\n#sec-配套 .check .it .grow{white-space:normal;overflow:visible;text-overflow:clip;line-height:1.45;}\n.pg-t .nw,#sec-配套 .nw{white-space:nowrap;}\n.check .it.anim-res{animation:thResultIn .22s ease both;}\n@media (prefers-reduced-motion: reduce){ .check .it.anim-res{animation:thResultIn .01s linear both !important;animation-delay:0s !important;} }\n.mode .subs span{padding:3px 10px;border-radius:99px;background:#fff;font-size:11px;font-weight:800;color:var(--ink-soft);}\n.tpl{display:flex;align-items:center;gap:12px;margin-top:12px;padding:12px 14px;border-radius:16px;background:#fff;border:1.5px dashed var(--accent-line);flex-wrap:wrap;}\n.tpl .ico{flex:none;width:36px;height:36px;border-radius:11px;background:var(--row);display:grid;place-items:center;font-family:var(--font-display);font-weight:700;color:var(--accent-deep);font-size:13px;}\n.tpl .txt{flex:1;min-width:180px;font-size:12.5px;line-height:1.5;}\n.tpl .txt b{display:block;font-size:13.5px;font-weight:900;}\n.tpl .txt span{color:var(--ink-soft);font-size:11.5px;}\n.tpl .bar-fill{flex-basis:100%;}\n\n/* 时间 */\n.years{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;}\n/* 四张放不下就两两一排，不排成 3 + 1 */\n@media (max-width:760px){ .years{grid-template-columns:repeat(2,minmax(0,1fr));} }\n.yc{display:flex;flex-direction:column;align-items:stretch;justify-content:flex-start;width:100%;text-align:left;background:var(--card-2);border:2px solid transparent;border-radius:16px;padding:12px 14px;}\n.yc b{display:block;font-family:var(--font-display);font-weight:700;font-size:23px;line-height:1.2;}\n.yc i{display:block;font-style:normal;font-size:11.5px;color:var(--ink-soft);margin-top:4px;line-height:1.55;}\n.yc.on{background:var(--accent-soft);border-color:var(--accent);}\n.yc.on i{color:var(--accent-deep);}\n.yc.custom{background:#fff;border:2px dashed var(--ink-dim);cursor:pointer;}\n.yc.custom.on{border-style:solid;border-color:var(--accent);background:var(--accent-soft);}\n.yc.custom b{font-size:19px;}\n.yc.custom .in{height:32px;font-size:12px;margin-top:8px;background:var(--card-2);padding:0 10px;border-radius:11px;}\n.in .wk{flex:none;font-size:12px;color:var(--ink-soft);font-weight:700;}\n.in input[type=date],.in input[type=time]{font-family:var(--font-body);}\n.in input::-webkit-calendar-picker-indicator{display:none;}\n.in:has(input[type=date]),.in:has(input[type=time]){cursor:pointer;}\n\n/* 自定义地点 */\n.custom-box{border:2px dashed var(--line);border-radius:16px;padding:12px 14px 14px;margin-top:12px;}\n.custom-box h6{margin:0 0 8px;font-size:13px;font-weight:900;display:flex;gap:8px;align-items:center;}\n.custom-box h6 span{font-size:11.5px;color:var(--ink-soft);font-weight:800;}\n.mini-form{display:grid;grid-template-columns:1fr 1fr auto;gap:8px;align-items:end;}\n.mini-form label.cap{display:block;font-size:11.5px;font-weight:800;color:var(--ink-soft);margin-bottom:4px;}\n\n/* 资料卡：分组、每组能收起 */\n.grp{border:2px solid var(--line);border-radius:16px;margin-top:10px;overflow:hidden;background:#fff;}\n.grp-h{display:flex;align-items:center;gap:10px;padding:9px 14px;background:var(--card-2);cursor:pointer;user-select:none;}\n.grp-h b{font-size:13.5px;font-weight:900;}\n.grp-h .hint{flex:0 1 auto;min-width:0;font-size:11.5px;font-weight:500;color:var(--ink-soft);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}\n.grp-h .cnt{font-family:var(--font-display);font-size:12px;color:var(--ink-soft);font-weight:700;}\n.grp-h .grow{flex:1;}\n.grp-h .chev{width:22px;height:22px;display:grid;place-items:center;font-size:12px;color:var(--ink-soft);transition:transform .32s var(--ease);}\n.grp.shut .chev{transform:rotate(-90deg);}\n.grp-b{display:grid;grid-template-columns:1fr 1fr;gap:8px 12px;padding:12px 14px 14px;}\n.grp.shut .grp-b{display:none;}\n.grp-b .full{grid-column:1 / -1;}\n.fld label{display:flex;align-items:center;gap:6px;font-size:11.5px;font-weight:800;color:var(--ink-soft);margin-bottom:4px;min-height:18px;}\n.fld label .grow{flex:1;}\n.fld label small{min-width:0;font-weight:500;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}\n.fld .v{display:block;width:100%;min-height:34px;border-radius:11px;background:var(--card-2);padding:7px 11px;font-size:12.5px;font-weight:700;line-height:1.5;\n  border:2px solid transparent;resize:none;overflow:hidden;transition:border-color .18s;}\n.fld .v:focus{border-color:var(--accent-line);}\n.fld.locked .v{background:#fff;border-color:var(--line);}\n\n/* 技能 */\n.tier-wrap{margin-top:12px;}\n/* 多样乐器各一条水平：左边乐器名，右边五档 */\n.tier-one{display:flex;align-items:center;gap:12px;margin-top:6px;}\n.tier-one .tier-name{flex:none;width:72px;font-size:12.5px;font-weight:800;}\n.tier-one .tier-name small{margin-left:4px;font-size:10.5px;color:var(--accent-deep);}\n.tier-one .tier-wrap{flex:1;min-width:0;margin-top:0;}\n.tier-wrap.off{opacity:.4;pointer-events:none;}\n\n/* 人际关系 */\n.avs{display:flex;flex-wrap:wrap;gap:8px;}\n.av{display:flex;align-items:center;gap:9px;padding:5px 12px 5px 5px;border-radius:999px;background:var(--card-2);border:2px solid transparent;text-align:left;}\n.av .avb{display:flex;align-items:center;gap:9px;text-align:left;}\n.av.add{padding-right:14px;}\n.av img,.av .ava,.av .ph{flex:none;width:34px;height:34px;border-radius:50%;object-fit:cover;background:var(--row);}\n.av .ph{display:grid;place-items:center;font-size:18px;color:var(--ink-soft);}\n.av b{font-size:13px;font-weight:800;display:block;line-height:1.3;}\n.av small{display:block;font-size:11px;color:var(--ink-soft);font-weight:700;line-height:1.3;}\n.av.on{background:#fff;border-color:var(--accent);box-shadow:0 4px 12px var(--accent-glow);}\n.av .rel{margin-left:4px;padding:2px 8px;border-radius:999px;background:var(--accent-soft);color:var(--accent-deep);font-size:11px;font-weight:800;}\n.av .del{margin-left:2px;width:20px;height:20px;border-radius:50%;display:grid;place-items:center;color:var(--ink-soft);font-size:13px;}\n.av .del:hover{background:var(--card-2);color:var(--ink);}\n.av.add{background:transparent;border:1.5px dashed var(--ink-dim);}\n.picker{margin-top:10px;border:2px solid var(--line);border-radius:16px;padding:10px 12px 12px;max-height:340px;overflow:auto;}\n.picker h6{margin:8px 0 6px;font-size:11px;font-weight:900;color:var(--ink-soft);letter-spacing:.06em;display:flex;gap:8px;}\n.picker h6:first-child{margin-top:0;}\n.picker h6 span{font-weight:700;color:var(--ink-dim);}\n.pk{display:grid;grid-template-columns:repeat(5,1fr);gap:6px;}\n.pk button{background:var(--card-2);border-radius:14px;padding:7px 4px 6px;text-align:center;border:2px solid transparent;}\n.pk button img,.pk button .ava{width:40px;height:40px;border-radius:50%;object-fit:cover;display:block;margin:0 auto 3px;background:var(--row);}\n.pk button b{font-size:11.5px;font-weight:800;display:block;line-height:1.3;}\n.pk button.on{background:#fff;border-color:var(--accent);}\n.pk button:disabled{opacity:.35;cursor:default;}\n.pk.dim button{opacity:.45;}\n\n/* 物品 */\n.bag{display:grid;grid-template-columns:1fr 1fr;gap:10px;}\n.bag > div{background:var(--card-2);border-radius:14px;padding:10px 12px;}\n.bag h5{margin:0 0 6px;font-size:12px;font-weight:900;color:var(--ink-soft);}\n.bag ul{list-style:none;margin:0 0 6px;padding:0;}\n.bag li{display:flex;justify-content:space-between;align-items:center;font-size:12.5px;font-weight:700;padding:2px 0;}\n.bag li button{width:22px;height:22px;border-radius:50%;color:var(--ink-soft);}\n.bag li button:hover{background:#fff;color:var(--ink);}\n.bag li.none{color:var(--ink-dim);font-weight:500;}\n.bag .in{height:32px;border-radius:10px;background:#fff;font-size:12.5px;padding:0 10px;}\n\n/* 第一层 */\n.chk{display:flex;align-items:center;gap:8px;margin-top:10px;font-size:12.5px;font-weight:800;color:var(--ink);cursor:pointer;user-select:none;}\n.chk input{position:absolute;opacity:0;pointer-events:none;}\n.chk .box{width:18px;height:18px;border-radius:6px;border:2px solid var(--ink-dim);display:inline-grid;place-items:center;color:#fff;font-size:11px;background:#fff;}\n.chk input:checked + .box{border-color:var(--accent);background:var(--accent);}\n.chk input:focus-visible + .box{outline:2px solid var(--accent);outline-offset:2px;}\n.prose-sugg{margin-top:8px;border:1.5px dashed var(--accent-line);border-radius:14px;padding:10px 12px;background:#fff;}\n.prose-sugg p{margin:0 0 8px;font-size:12.5px;line-height:1.8;white-space:pre-wrap;}\n.prose-sugg .acts{display:flex;gap:8px;justify-content:flex-end;}\n\n/* 底栏 */\n.bar{position:relative;margin:22px -34px -26px;padding:14px 34px;background:linear-gradient(180deg,rgba(255,255,255,.7),#fff 40%);\n  border-top:2px solid var(--line);display:flex;align-items:center;gap:14px;padding-bottom:calc(14px + env(safe-area-inset-bottom));}\n.bar .sum{flex:1;min-width:0;font-size:12px;color:var(--ink-soft);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}\n.bar .sum b{color:var(--ink);font-weight:900;}\n.bar .pop{right:120px;bottom:64px;width:320px;max-width:calc(100% - 24px);}\n\n/* 横幅：缺前置、出错 */\n.banner{position:relative;margin:10px 0 2px;padding:11px 14px;border-radius:14px;background:var(--accent-soft);color:var(--accent-deep);}\n.banner b{font-size:13.5px;font-weight:900;display:flex;align-items:center;gap:8px;}\n.banner b i{font-style:normal;width:20px;height:20px;border-radius:50%;background:var(--accent);color:#fff;display:grid;place-items:center;font-size:12px;}\n.banner .rows{display:grid;gap:4px;margin:6px 0 0 28px;}\n.banner .rows div{font-size:12.5px;font-weight:800;}\n.banner .rows span{font-weight:500;color:var(--ink-soft);}\n.tip{position:relative;margin:8px 0 0;padding:7px 12px;border-radius:12px;background:var(--card-2);color:var(--ink-soft);font-size:12px;font-weight:700;}\n.tip.bad{background:var(--accent-soft);color:var(--accent-deep);}\n\n/* 开局须知 */\n.notice{position:relative;overflow:hidden;background:var(--card);border-radius:22px;box-shadow:var(--shadow);padding:26px 30px 22px;margin-bottom:14px;}\n.notice h5{margin:0 0 4px;font-size:26px;font-weight:900;}\n.notice .en{font-family:var(--font-display);font-weight:700;font-size:10.5px;letter-spacing:.3em;color:var(--ink-dim);}\n.ntb{width:100%;border-collapse:separate;border-spacing:0;margin-top:12px;font-size:12.5px;}\n.ntb td{padding:8px 12px;border-top:1px solid var(--line);vertical-align:top;line-height:1.7;}\n.ntb tr:first-child td{border-top:none;}\n.ntb td.k{width:88px;font-weight:900;color:var(--ink-soft);white-space:nowrap;}\n.ntb tr.hot td{background:var(--accent-soft);}\n.ntb tr.hot td:first-child{border-radius:12px 0 0 12px;}\n.ntb tr.hot td:last-child{border-radius:0 12px 12px 0;}\n.ntb tr.hot td.k{color:var(--accent-deep);}\n.notice .ack{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-top:16px;padding-top:14px;border-top:2px solid var(--line);}\n.notice .ack .chk{margin-top:0;}\n.wait-lock{opacity:.45;pointer-events:none;filter:saturate(.6);user-select:none;}\n\n/* 开局进度 */\n.steps{display:grid;gap:6px;margin:14px 0 12px;}\n.steps div{display:flex;align-items:center;gap:10px;padding:8px 12px;border-radius:12px;background:var(--card-2);font-size:12.5px;font-weight:800;color:var(--ink-soft);}\n.steps div i{font-style:normal;width:20px;height:20px;border-radius:50%;display:grid;place-items:center;font-size:11px;background:#fff;color:var(--ink-dim);flex:none;}\n.steps div.on{color:var(--ink);}\n.steps div .sub{margin-left:auto;font-family:Fredoka,'Noto Sans SC',sans-serif;font-size:12px;font-weight:700;color:var(--ink-soft);font-variant-numeric:tabular-nums;}\n.steps div.on i{background:var(--accent);color:#fff;}\n.steps div.done i{background:var(--ok);color:#fff;}\n.steps div.bad{background:var(--accent-soft);color:var(--accent-deep);}\n.steps div.bad i{background:var(--accent);color:#fff;}\n\n/* 开局档案（已开局以后 0 楼只读） */\n.arch-name{position:relative;margin:6px 0 2px;font-size:22px;font-weight:900;}\n.arch-name small{font-family:var(--font-display);font-weight:700;font-size:13px;letter-spacing:.12em;color:var(--ink-soft);margin-left:8px;text-transform:uppercase;}\n.arch-line{position:relative;font-size:12.5px;color:var(--ink-soft);}\n.pills{position:relative;display:flex;flex-wrap:wrap;gap:6px;margin:12px 0 10px;}\n.pills span{padding:4px 11px;border-radius:999px;background:var(--card-2);font-size:12px;font-weight:800;}\n.pills span.hot{background:var(--accent-soft);color:var(--accent-deep);}\n.knows{position:relative;display:flex;gap:8px;flex-wrap:wrap;margin-bottom:6px;}\n.knows div{display:flex;align-items:center;gap:6px;padding:3px 10px 3px 3px;border-radius:999px;background:var(--card-2);font-size:12px;font-weight:800;}\n.knows img,.knows .ava{width:26px;height:26px;border-radius:50%;object-fit:cover;background:var(--row);}\n.knows em{font-style:normal;font-size:10.5px;color:var(--accent-deep);}\n.ro{display:grid;grid-template-columns:1fr 1fr;gap:6px 14px;padding:12px 14px 14px;}\n.ro div{font-size:12.5px;line-height:1.55;}\n.ro div span{display:block;font-size:11px;font-weight:800;color:var(--ink-soft);}\n.ro .full{grid-column:1 / -1;}\n\n/* 卡宽 ≤ 600px：曲目单折成标题下面一条横条，当前那页 --ink 底白字，不写摘要；没滑完的那一头渐隐（动作.js 挂 can-l / can-r） */\n@media (max-width:600px){\n  .sl{grid-template-columns:minmax(0,1fr);gap:10px;margin-top:10px;}\n  .sl-list{flex-direction:row;gap:6px;overflow-x:auto;background:none;border-radius:0;padding:2px 0 4px;scrollbar-width:none;}\n  .sl-list::-webkit-scrollbar{display:none;}\n  .sl-list.can-r{-webkit-mask-image:linear-gradient(90deg,#000 calc(100% - 32px),transparent);mask-image:linear-gradient(90deg,#000 calc(100% - 32px),transparent);}\n  .sl-list.can-l{-webkit-mask-image:linear-gradient(90deg,transparent,#000 32px);mask-image:linear-gradient(90deg,transparent,#000 32px);}\n  .sl-list.can-l.can-r{-webkit-mask-image:linear-gradient(90deg,transparent,#000 32px,#000 calc(100% - 32px),transparent);\n    mask-image:linear-gradient(90deg,transparent,#000 32px,#000 calc(100% - 32px),transparent);}\n  .sl-cap,.sl-it small{display:none;}\n  .sl-it{flex:none;width:auto;gap:5px;min-height:32px;padding:4px 11px;border-radius:999px;background:var(--card-2);color:var(--ink-soft);}\n  .sl-it:hover{background:var(--card-2);color:var(