' }, { 名: '编曲' }, { 名: '音响师' }, { 名: '街头艺人' }, { 名: '乐器修理' }],\n  自由职业: [{ 名: '插画师' }, { 名: '摄影师' }, { 名: '写手' }, { 名: '翻译' }, { 名: '视频主播', 起: 2006 }],\n  其他: [{ 名: '待业' }, { 名: '家里帮忙' }, { 名: '来东京旅居' }],\n};\nconst 通用在 = (项, 年) => !!项 && (!项.起 || (Number(年) || 0) >= 项.起);\nconst 默认职位 = { 打工: '店员', 上班: '职员' };\n// 旧草稿、旧开局档里的「工作人员」就是现在的「打工」\nconst 身份类名 = 类 => (类 === '工作人员' ? '打工' : 类);\nconst 住所表 = [\n  { 名: '池袋', 片区: '丰岛 · 池袋' },\n  { 名: '文京', 片区: '文京' },\n  { 名: '新宿', 片区: '新宿' },\n  { 名: '涩谷', 片区: '涩谷' },\n];\n// 自定义地点、住处要选在哪一片：钉子落在那一片的中间，画成虚线圈\nconst 片区表 = ['丰岛 · 池袋', '文京', '新宿', '涩谷', '千代田', '北区', '港区', '中央', '江东', '世田谷', '多摩'];\n// 买房、租房的价钱（2020 年东京，日元）。两居按不动产经济研究所 2020 年东京 23 区新建公寓均价 7,712 万定，其余按比例；\n// 「租」是单间每月房租，两居、独栋的房租按买价同比例放大；租房首付算三个月（押金、礼金、首月）。片区对不上哪一档的按「23 区其他」\nconst 房价表 = [\n  { 档: '都心', 片区: ['千代田', '中央', '港区'], 单间: 35000000, 两居: 110000000, 独栋: 140000000, 租: 120000 },\n  { 档: '多摩', 片区: ['多摩'], 单间: 15000000, 两居: 48000000, 独栋: 55000000, 租: 60000 },\n  { 档: '23 区其他', 片区: [], 单间: 25000000, 两居: 77000000, 独栋: 90000000, 租: 90000 },\n];\nconst 年级表 = ['高一', '高二', '高三', '大一', '大二', '大三', '大四'];\n\n// 好感、信任是千分制：-1000～1000 的整数，屏上显示成百分比（450 → 45%，-120 → -12%）。负的是讨厌、不信任\nconst 关系满分 = 1000;\nconst 百分 = n => { const v = Math.round(Number(n)) / 10; return (Number.isInteger(v) ? String(v) : v.toFixed(1)) + '%'; };\n\n// 七种关系 → 重要角色表的初值（千分制）。青梅竹马高，一面之缘低。\nconst 关系表 = {\n  '同班': { 阶段: '普通朋友', 好感: 450, 信任: 450 },\n  '邻居': { 阶段: '普通朋友', 好感: 500, 信任: 500 },\n  '青梅竹马': { 阶段: '在意的人', 好感: 700, 信任: 700 },\n  '打工同事': { 阶段: '普通朋友', 好感: 500, 信任: 500 },\n  '熟客': { 阶段: '普通朋友', 好感: 450, 信任: 400 },\n  '网友': { 阶段: '普通朋友', 好感: 450, 信任: 350 },\n  '一面之缘': { 阶段: '陌生人', 好感: 300, 信任: 300 },\n};\n\n// 关系阶段：和手账本同一套七档（常夜灯 2026-10-05 定）。前五档跟好感走，游戏引擎记账写回好感时一并写；\n// 情侣、夫妻要正文里真的确定了关系、填表 AI 写上才算，好感跌破在意的人那条线就退回按好感算的那一档。好感为负是讨厌的人\nconst 关系阶段们 = ['讨厌的人', '陌生人', '普通朋友', '在意的人', '挚友', '情侣', '夫妻'];\nconst 阶段界 = [[750, '挚友'], [550, '在意的人'], [350, '普通朋友'], [0, '陌生人']];   // 千分制；低于 0 是讨厌的人\nconst 剧情阶段 = ['情侣', '夫妻'];\nconst 剧情阶段线 = 550;   // 情侣、夫妻写得上、留得住的最低好感：吵一架掉几个点不退回去\nfunction 阶段之于(好感, 当前) {\n  const n = Number(好感);\n  if (!isFinite(n)) return '';\n  if (剧情阶段.includes(当前) && n >= 剧情阶段线) return 当前;\n  return (阶段界.find(([下]) => n >= 下) || [0, '讨厌的人'])[1];\n}\n\n// 乐器能选几样（上限 5），每样各有一个水平；第一样是主乐器（技能.乐器、技能.水平），其余在 技能.副乐器 [{名, 水平}]\nconst 乐器表 = ['吉他', '贝斯', '鼓', '键盘', '主唱', '钢琴', '木吉他', '合成器', '小提琴', '大提琴', '长笛', '萨克斯', '小号', '三味线', 'DJ', '零基础'];\n// 一个人会的全部乐器：[{名, 水平}]，主乐器在前；零基础、没选回空\nfunction 乐器们(j) {\n  j = j || {};\n  if (!j.乐器 || j.乐器 === '零基础') return [];\n  return [{ 名: j.乐器, 水平: Number(j.水平) || 1 }].concat((Array.isArray(j.副乐器) ? j.副乐器 : []).filter(x => x && x.名 && x.名 !== j.乐器)\n    .map(x => ({ 名: String(x.名), 水平: Number(x.水平) || 1 })));\n}\n// 「吉他（能合奏）、钢琴（弹整首）」\nconst 乐器串 = j => (j && j.乐器 === '零基础' ? '零基础' : 乐器们(j).map(x => x.名 + '（' + 水平名[x.水平 - 1] + '）').join('、'));\nconst 水平名 = ['摸索', '弹整首', '能合奏', '能登台', '能主导'];\nconst 乐队选项 = ['无', '招募中', '自组乐队', '支援乐手'];\nconst 特长池 = ['做饭', '画画', '跑步', '外语', '摄影', '游泳', '书法', '手工', '下棋', '编程'];\nconst 上限 = { 特长: 5, 人际: 5, 乐器: 5 };\n\n// 选了乐器、身份、学校，自动带上的东西（玩家能删）\nconst 自动物品 = {\n  乐器: {\n    '吉他': [['吉他', '家中'], ['拨片', '随身']],\n    '贝斯': [['贝斯', '家中'], ['拨片', '随身']],\n    '鼓': [['鼓棒', '随身']],\n    '键盘': [['电子琴', '家中']],\n    '主唱': [['润喉糖', '随身']],\n    '小提琴': [['小提琴', '家中'], ['松香', '随身']],\n    'DJ': [['DJ 控制器', '家中'], ['监听耳机', '随身']],\n    '木吉他': [['木吉他', '家中'], ['拨片', '随身']],\n    '合成器': [['合成器', '家中']],\n    '大提琴': [['大提琴', '家中'], ['松香', '随身']],\n    '长笛': [['长笛', '随身']],\n    '萨克斯': [['萨克斯', '家中'], ['簧片', '随身']],\n    '小号': [['小号', '家中']],\n    '三味线': [['三味线', '家中']],\n  },\n  身份: { '打工': [['员工证', '随身']], '上班': [['工作证', '随身']], '学生': [['学生证', '随身'], ['书包', '随身']] },\n};\n\n// 物品的类别（物品表「类别」一列）：类别定了东西怎么没的——吃的喝的放不过夜，消耗品用完就没，票过期就没，其余一直在。\n// 开局卡里玩家随手写的东西按名字猜一类（上面自动带的几样都猜得对），猜不出记「其他」；之后填表 AI 照表里的说明自己分。\n// 按顺序试，先中先得：「润喉糖」要落在消耗品、不落在食物，「吉他弦」要落在消耗品、不落在器材。\nconst 物品类别 = ['常备', '器材', '食物', '消耗品', '票券', '纪念品', '其他'];\nconst 物品猜类 = [\n  ['票券', /票|券/],\n  ['消耗品', /弦|电池|药|创可贴|绷带|纸巾|湿巾|润喉|松香|口罩|胶带|暖宝宝/],\n  ['食物', /便当|饭团|面包|三明治|蛋糕|饼干|巧克力|零食|布丁|点心|甜点|水果|果汁|牛奶|咖啡|奶茶|饮料|可乐|汽水|矿泉水|茶$|饭$|糖$/],\n  ['器材', /吉他|贝斯|鼓|琴|拨片|谱|效果器|调音器|节拍器|音箱|耳返|话筒|麦克风|变调夹|背带|线材|控制器|打碟/],\n  ['常备', /手机|钱包|钥匙|证$|卡$|耳机|书包|挎包|背包|伞/],\n  ['纪念品', /礼物|纪念|徽章|照片|挂件|吊坠|明信片|信$/],\n];\n\n// 🎲 随机只在这些里挑，不花模型；名字不随机。\nconst 随机池 = {\n  身高体型: ['170cm，偏瘦', '176cm，肩宽', '168cm，结实', '173cm，匀称', '181cm，高瘦'],\n  发型发色: ['黑色短发', '深棕色碎发，刘海略长', '黑发，后脑有一撮翘毛', '栗色短发，两侧推短', '黑色微卷短发'],\n  瞳色: ['深棕', '黑', '浅褐', '灰黑'],\n  常穿服装: ['灰色连帽衫，牛仔裤', '白衬衫，深色长裤', '黑色夹克，运动鞋', '格子衬衫，工装裤', '宽松卫衣，帆布鞋'],\n  外貌特征: ['左手指腹有茧', '右眉上有一道小疤', '笑起来有酒窝', '总戴一只旧手表', '耳后有颗痣'],\n  出身: ['本地人，在丰岛长大', '从地方城市搬来东京', '在文京长大', '从大阪搬过来'],\n  家庭: ['父母上班，独生子', '父母经营洗衣店，弟弟念初中', '和奶奶一起住', '父亲常驻外地，和母亲两个人住', '姐姐在念大学'],\n  成长经历: ['初中在轻音部待过一年，后来废部', '一直在社团打杂，没上过台', '小时候学过几年钢琴', '跟着表哥听摇滚长大'],\n  来历: ['春假起在 CiRCLE 打工，刚满一周', '看了一场演出以后来应聘', '亲戚介绍来的兼职', '为了攒钱买琴出来打工'],\n  知情人: ['CiRCLE 的月岛麻里奈', '同班的几个朋友', '家里人', '打工的前辈'],\n  核心性格: ['嘴硬心软，怕麻烦', '老实，认死理', '爱开玩笑，关键时候靠得住', '慢热，不擅长拒绝别人', '冷静，话少', '好奇心重，做事三分钟热度'],\n  社交方式: ['对生人冷淡，熟人面前话多', '跟谁都能聊两句', '习惯先听别人说', '话不多，但记得别人的事'],\n  说话习惯: ['句尾常带「吧」', '说话直，不绕弯子', '紧张时会重复对方的话', '爱用反问'],\n  日常习惯: ['熬夜，早上起不来', '每天早上跑步', '随身带耳机', '记账记得很细'],\n  喜欢: ['老唱片', '便利店的炸鸡', '下雨天', '猫'],\n  讨厌: ['排队', '香菜', '被催', '闷热的天'],\n  弱点软肋: ['怕被人看不起', '不会拒绝朋友', '一紧张就手抖', '对家里的事很敏感'],\n  反差: ['平时胆小，护人的时候豁得出去', '看着冷淡，其实很会照顾人', '长得凶，做饭很好吃'],\n  生理特点: ['体力差，容易晕车', '怕冷', '酒量为零', '视力不好，偶尔戴眼镜'],\n  心理状态: ['表面乐观，心里没底', '刚换环境，有点紧张', '想找件能坚持下去的事', '最近睡不好'],\n};\n\n// 资料卡的三组：格名照《玩家角色资料》，写进主角档案表的同名列\nconst 资料组 = {\n  外貌: ['身高体型', '发型发色', '瞳色', '常穿服装', '外貌特征'],\n  身世: ['出身', '家庭', '成长经历', '来历', '知情人', '与主线关系'],\n  性格: ['核心性格', '社交方式', '说话习惯', '日常习惯', '喜欢', '讨厌', '弱点软肋', '反差', '生理特点', '心理状态'],\n};\nconst 主线默认 = '无特殊关联，普通人';\n\n// ── 共用/工具.js ──\n// 小工具：转义、日期、随机。0 层卡、回执、核心共用。\n// 注意：两块 html 是经卡里的正则 → markdown 代码块 → 酒馆助手 iframe 上屏的，路上会：\n//   · 把「美元号接数字」当成捕获组、把双花括号当成酒馆宏换掉；\n//   · 把源码里写成字面的 HTML 实体（和号接 amp、quot 那种）解码成字符本身——字符串里的实体一变回引号，脚本就编译不过。\n// 这几样在源码里都不能出现（构建.py 会查），转义表因此用字符编码现拼。\n\nconst 转义 = s => String(s == null ? '' : s).replace(/[&<>\"']/g, c => '&#' + c.charCodeAt(0) + ';');\n\nconst 周几名 = ['周日', '周一', '周二', '周三', '周四', '周五', '周六'];\nfunction 周几(日期) {\n  const m = /^(\\d{4})-(\\d{2})-(\\d{2})$/.exec(String(日期 || ''));\n  if (!m) return '';\n  const d = new Date(Number(m[1]), Number(m[2]) - 1, Number(m[3]));\n  return isNaN(d) ? '' : 周几名[d.getDay()];\n}\nconst 补零 = n => String(n).padStart(2, '0');\nfunction 时刻转分(t) { const m = /^(\\d{1,2}):(\\d{2})$/.exec(String(t || '')); return m ? Number(m[1]) * 60 + Number(m[2]) : NaN; }\nfunction 分转时刻(n) { return 补零(Math.floor(n / 60) % 24) + ':' + 补零(n % 60); }\nfunction 时段名(时刻) {\n  const n = 时刻转分(时刻);\n  if (isNaN(n)) return '';\n  if (n < 5 * 60) return '深夜';\n  if (n < 10 * 60) return '早上';\n  if (n < 16 * 60) return '白天';\n  if (n < 19 * 60) return '傍晚';\n  return '晚上';\n}\n// 「2020-04-17 周五 19:40」，全局数据表·当前时间的写法\nfunction 当前时间串(日期, 时刻) {\n  return [日期, 周几(日期), 时刻].filter(Boolean).join(' ');\n}\n\nconst 随机取 = 列 => 列[Math.floor(Math.random() * 列.length)];\nfunction 随机日期(年, 时节) {\n  const 季 = 时节表.find(x => x.名 === 时节) || 时节表[0];\n  const 起 = new Date(Number(年), Number(季.起.slice(0, 2)) - 1, Number(季.起.slice(3)));\n  const 止 = new Date(Number(年), Number(季.止.slice(0, 2)) - 1, Number(季.止.slice(3)));\n  const d = new Date(起.getTime() + Math.floor(Math.random() * ((止 - 起) / 864e5 + 1)) * 864e5);\n  return d.getFullYear() + '-' + 补零(d.getMonth() + 1) + '-' + 补零(d.getDate());\n}\nfunction 随机时刻() {\n  const 段 = 随机取(时段表);\n  const a = 时刻转分(段.起), b = 时刻转分(段.止);\n  return 分转时刻(a + Math.floor(Math.random() * ((b - a) / 10 + 1)) * 10);\n}\n// 日期落在哪个时节（自己改了日期以后，时节跟着对上）\n// 片区写法不统一：0 层卡写「丰岛 · 池袋」「文京」，地图点位写「丰岛・池袋」「东京・文京」。去掉点和空格再比，对上结尾就算同一片\nfunction 片区键(片区) { return String(片区 || '').replace(/[\\s·・]/g, ''); }\nfunction 同片区(甲, 乙) { const a = 片区键(甲), b = 片区键(乙); return !!a && !!b && (a === b || a.endsWith(b) || b.endsWith(a)); }\n// 房价：方式「买」回买价，「租」回每月房租；户型单间、两居、独栋\nfunction 房价(片区, 户型, 方式) {\n  const 档 = 房价表.find(x => x.片区.some(p => 同片区(片区, p))) || 房价表[房价表.length - 1];\n  const 买 = 档[户型];\n  if (!买) return 0;\n  return 方式 === '租' ? Math.round(档.租 * 买 / 档.单间 / 1000) * 1000 : 买;\n}\nfunction 日期的时节(日期) {\n  const md = String(日期 || '').slice(5, 10);\n  if (!/^\\d{2}-\\d{2}$/.test(md)) return '';\n  // 照时节分界切：起点不晚于这一天的最后一季；比第一季还早（1 月到春的起点前）算上一年的冬\n  let 季 = 时节分界[时节分界.length - 1];\n  for (const x of 时节分界) if (x.起 <= md) 季 = x;\n  return 季.名;\n}\n\nconst 查人 = 名 => 名单.find(x => x.名 === 名) || null;\n// 艺名、别名（角色条目的触发词，只收指向一个人的，构建时生成）、带括号的写法归到规范名；归不上返回空\nfunction 归名(名) {\n  const s = String(名 || '').trim();\n  if (!s) return '';\n  const 认 = t => {\n    const 原 = String(t || '').trim(), k = 原.toLowerCase();\n    if (!k) return '';\n    const x = 名单.find(p => p.名 === 原)\n      || 名单.find(p => (p.艺名 && p.艺名.toLowerCase() === k) || (p.别名 || []).some(a => a.toLowerCase() === k));\n    return x ? x.名 : '';\n  };\n  const 直 = 认(s);\n  if (直) return 直;\n  // 「香澄（户山香澄）」「和奏瑞依（LAYER）」：去掉括号认一次，再认括号里的\n  const 外 = s.replace(/[（(][^）)]*[）)]/g, '').trim();\n  const 里 = (/[（(]([^）)]+)[）)]/.exec(s) || [])[1] || '';\n  return (外 && 外 !== s && 认(外)) || (里 && 认(里)) || '';\n}\n// 物品按名字猜一类（规则在 数据.js 的 物品猜类），猜不出是「其他」\nfunction 猜物品类(名) {\n  const s = String(名 || '').trim();\n  for (const [类, 规则] of 物品猜类) if (规则.test(s)) return 类;\n  return '其他';\n}\nconst 截 = (s, n) => { s = String(s || ''); return s.length > n ? s.slice(0, n) : s; };\nconst 深拷 = o => JSON.parse(JSON.stringify(o));\n\n// ── 共用/头像.js ──\n// 小头像：原图七八百像素，<img> 直接缩到二三十、四十像素时，浏览器的缩放会出锯齿和网点。\n// 改画在 canvas 上：按屏幕倍率算目标像素，先对半缩几次，最后一步用高质量插值缩到位、居中裁成正方形（和面板的头像一个做法）。\n// 同一张图、同一尺寸只缩一次，记在缓存里；屏重画时直接贴上去，不重新加载、不闪。\n// 用法：拼 HTML 时写 头像画布(地址, 尺寸)，塞进页面以后调 画头像们(容器)。\nconst 头像缓存 = new Map();   // 地址@像素 → 缩好的 canvas\nconst 头像等待 = new Map();   // 地址@像素 → 还在加载时等着贴的 canvas 们\n\nfunction 头像画布(地址, 尺寸) {\n  return '<canvas class=\"ava\" data-ava=\"' + 转义(地址) + '\" data-size=\"' + 尺寸 + '\" width=\"' + 尺寸 + '\" height=\"' + 尺寸 + '\" aria-hidden=\"true\"><\/canvas>';\n}\n\nfunction 缩头像(图, 像素) {\n  let 源 = 图, w = 图.naturalWidth, h = 图.naturalHeight;\n  // 对半缩到离目标两倍以内，每一步都只缩一半，插值不丢细节\n  while (Math.min(w, h) / 2 >= 像素 * 2) {\n    const c = document.createElement('canvas');\n    c.width = Math.round(w / 2); c.height = Math.round(h / 2);\n    const x = c.getContext('2d');\n    x.imageSmoothingEnabled = true;\n    if ('imageSmoothingQuality' in x) x.imageSmoothingQuality = 'high';\n    x.drawImage(源, 0, 0, c.width, c.height);\n    源 = c; w = c.width; h = c.height;\n  }\n  const 出 = document.createElement('canvas');\n  出.width = 像素; 出.height = 像素;\n  const x = 出.getContext('2d');\n  x.imageSmoothingEnabled = true;\n  if ('imageSmoothingQuality' in x) x.imageSmoothingQuality = 'high';\n  const 比 = Math.max(像素 / w, 像素 / h);\n  x.drawImage(源, (像素 - w * 比) / 2, (像素 - h * 比) / 2, w * 比, h * 比);\n  return 出;\n}\n\nfunction 贴头像(cv, 源) {\n  const x = cv.getContext('2d');\n  x.clearRect(0, 0, cv.width, cv.height);\n  x.drawImage(源, 0, 0);\n}\n\nfunction 画头像们(容器) {\n  const 倍 = Math.max(1, window.devicePixelRatio || 1);\n  (容器 || document).querySelectorAll('canvas[data-ava]').forEach(cv => {\n    if (cv.dataset.drawn) return;\n    cv.dataset.drawn = '1';\n    const 像素 = Math.max(1, Math.round((Number(cv.dataset.size) || 40) * 倍));\n    const 地址 = cv.dataset.ava, 键 = 地址 + '@' + 像素;\n    cv.width = 像素; cv.height = 像素;\n    const 有 = 头像缓存.get(键);\n    if (有) return 贴头像(cv, 有);\n    const 等着 = 头像等待.get(键);\n    if (等着) return 等着.push(cv);\n    头像等待.set(键, [cv]);\n    const 图 = new Image();\n    图.referrerPolicy = 'no-referrer';\n    图.onload = () => {\n      const 们 = 头像等待.get(键) || [];\n      头像等待.delete(键);\n      if (!图.naturalWidth) return;\n      const 好 = 缩头像(图, 像素);\n      头像缓存.set(键, 好);\n      们.forEach(c => { if (c.isConnected) 贴头像(c, 好); });\n    };\n    图.onerror = () => { 头像等待.delete(键); };\n    图.src = 地址;\n  });\n}\n\n// ── 开局/状态.js ──\n// 0 层卡的状态：档 = 玩家填的（存草稿、交给核心开局），界 = 界面上的临时东西（不存）。\n\nlet 核 = null;       // BanGCtl，核心的接口\nlet 核态 = null;     // 核心的 state()\nlet 档 = null;\nconst 界 = {\n  屏: '等',                  // 等 / 没脚本 / 须知 / 表单 / 进度 / 档案\n  页: '玩法',                // 表单当前那一页（画面.js 的页表）\n  收起: { 外貌: false, 身世: false, 性格: false },\n  候选: {},                  // 路径 → [候选]；'人际' → [{名, 关系, 一句}]；'开场白' → 文\n  忙: {},                    // ✦ 在等回话的按钮\n  人选开: false,\n  当前人: '',                // 人际关系里正在改关系的那位\n  自定义: '',                // 正在填自定义的那一处：地点 / 住所 / 工作 / 学校 / 特长\n  缺单开: false,\n  存档开: false,             // 「角色存档」浮层（这个聊天的草稿也在里面）\n  存档们: [],                // 浮层打开时向核心要的列表：[{名, 罗马音, 说, 时间}]\n  存档待确认: '',            // 再按一次才算：'覆:名' 覆盖同名、'删:名' 删掉、'清' 清空重填\n  导入中: false,\n  提示: null,                // {话, 坏}\n  进度: [],                  // 开局每一步：'' / 'on' / 'done' / 'bad'\n  进度细: '',                // 正在走的那一步走到哪了（写初值：「12 / 28」）\n  设置开: false,             // ⚙：表单、档案换成设置页\n  设置动: false,             // 设置页下一次画的时候播进场动画（只在刚打开时）\n  接口话: null,              // 设置页里帮填接口的结果：{话, 坏, 忙}\n  模型们: null,              // 拉到的模型列表\n  配套: null,                // 00 页「配套」：核心 setupState() 回的现状（数据库、手账本），没拿到是 null\n  配套忙: false,             // 「一键配好」在改\n  配套改了: [],              // 刚按「一键配好」改掉的那几项：只在这一次重画里播动画\n};\nconst 手机 = () => window.matchMedia('(max-width:480px)').matches;\n\nfunction 酒馆用户名() {\n  try { return String(window.parent.SillyTavern.getContext().name1 || '').trim(); } catch (e) { return ''; }\n}\n\nfunction 默认档() {\n  const 年 = 2020, 季 = '春 · 新学期';\n  return {\n    版: 2,           // 2：人际里挪过的好感、信任是千分制（1 是 0～100）\n    玩法: '正常内容',\n    时间: { 年, 自选: false, 自选年: '', 时节: 季, 日期: 随机日期(年, 季), 时刻: 随机时刻(), 日期随机: true, 时刻随机: true },\n    成立线: [],      // 从成立前开始的乐队：只收开局那一年已经在活动的\n    地点: { 类: 'Live House', 名: 'CiRCLE', 自定义: null },\n    基本: { 姓名: 酒馆用户名(), 罗马音: '', 称呼: '', 性别: '男', 年龄: '17' },\n    外貌: Object.fromEntries(资料组.外貌.map(k => [k, ''])),\n    住所: { 名: '', 自定义: null },\n    // 类：身份类表六选一。学生用学校、年级；打工、上班用工作地点、职位；音乐人、自由职业用职业；其他用一句说明\n    身份: { 类: '打工', 工作地点: 'CiRCLE', 工作自定义: null, 职位: '新手工作人员', 职业: '', 学校: '', 学校自定义: null, 年级: '', 其他: '' },\n    身世: Object.fromEntries(资料组.身世.map(k => [k, k === '与主线关系' ? 主线默认 : ''])),\n    性格: Object.fromEntries(资料组.性格.map(k => [k, ''])),\n    技能: { 乐器: '', 水平: 2, 副乐器: [], 乐队: '无', 乐队名: '', 特长: [] },\n    人际: [],        // [{名, 关系, 一句, 好感?, 信任?}]：好感、信任挪过才有，没挪过跟着关系走\n    物品: { 随身: ['员工证'], 家中: [], 金钱: '10000' },\n    第一层: { 人称: '第三人称', 篇幅: '标准', 开场白: '', 代写: false },\n    锁: { '身世.与主线关系': true },\n  };\n}\n\n// 草稿和默认档合并：以后档里加了格子，旧草稿也能读。\n// 类型对不上的格子不收（手改过的、旧版的草稿）：字的格子收进一个对象，查缺时 .trim() 就抛错，0 层卡从此白屏\nfunction 合档(底, 草) {\n  if (!草 || typeof 草 !== 'object') return 底;\n  if (草.身份 && 草.身份.类 === '工作人员') 草 = Object.assign({}, 草, { 身份: Object.assign({}, 草.身份, { 类: '打工' }) });\n  // 0.0.9 以前的草稿：人际里挪过的好感、信任是 0～100，换成千分制\n  if (Array.isArray(草.人际) && !(草.版 >= 2)) 草 = Object.assign({}, 草, { 人际: 草.人际.map(p => {\n    if (!p || typeof p !== 'object') return p;\n    const q = Object.assign({}, p);\n    for (const 项 of ['好感', '信任']) if (isFinite(Number(q[项])) && q[项] !== '' && q[项] != null) q[项] = Number(q[项]) * 10;\n    return q;\n  }) });\n  for (const k of Object.keys(底)) {\n    if (!(k in 草) || k === '版') continue;\n    const a = 底[k], b = 草[k];\n    // 锁是按格子路径记的，键不固定：草稿里锁过的每一格都收（只按默认档的键合并会把它们全丢掉，刷新后锁全没了）\n    if (k === '锁') { if (b && typeof b === 'object' && !Array.isArray(b)) for (const [路径, 锁着] of Object.entries(b)) if (typeof 锁着 === 'boolean') a[路径] = 锁着; continue; }\n    if (a && typeof a === 'object' && !Array.isArray(a)) { if (b && typeof b === 'object' && !Array.isArray(b)) 底[k] = 合档(a, b); }\n    else if (Array.isArray(a)) { if (Array.isArray(b)) 底[k] = b.filter(x => x != null); }\n    else if (typeof a === 'string') { if (typeof b === 'string' || typeof b === 'number') 底[k] = String(b); }\n    else if (typeof a === 'boolean') { if (typeof b === 'boolean') 底[k] = b; }\n    else if (b !== undefined) 底[k] = b;\n  }\n  return 底;\n}\n\nfunction 取(路径) { return 路径.split('.').reduce((o, k) => (o == null ? o : o[k]), 档); }\nfunction 设(路径, 值) {\n  const ks = 路径.split('.');\n  let o = 档;\n  for (const k of ks.slice(0, -1)) o = o[k];\n  o[ks[ks.length - 1]] = 值;\n}\nconst 锁着 = 路径 => !!档.锁[路径];\n\nlet 存草稿钟 = 0;\nfunction 存草稿() {\n  clearTimeout(存草稿钟);\n  存草稿钟 = setTimeout(() => { try { if (核 && 核.alive()) 核.saveDraft(档); } catch (e) { /* 核心不在，下次再存 */ } }, 600);\n}\n\nfunction 年份() {\n  const t = 档.时间;\n  const y = Number(t.自选 ? t.自选年 : t.年);\n  return y >= 1900 && y <= 2100 ? y : 0;\n}\nconst 这年 = () => 年份() || 2020;\nfunction 开局地点() {\n  const 地 = 档.地点;\n  if (地.自定义 && 地.自定义.名) return { 名: 地.自定义.名, 全名: 地.自定义.名, 片区: 地.自定义.片区, 自定义: true };\n  const 项 = (地点表[地.类] || []).find(x => x.名 === 地.名);\n  return 项 && 原作在(项, 这年(), 档.成立线) ? 项 : null;\n}\n// 打工、上班的地方：自定义的、这一年开着的原作的店、这一类的通用身份（通用的没有片区，不落据点）\nfunction 工作地点() {\n  const s = 档.身份;\n  if (s.类 !== '打工' && s.类 !== '上班') return null;\n  if (s.工作自定义 && s.工作自定义.名) return s.工作自定义;\n  const 原 = s.类 === '打工' && 工作地点表.find(x => x.名 === s.工作地点);\n  if (原) return 原作在(原, 这年(), 档.成立线) ? 原 : null;\n  const 通 = (通用身份[s.类] || []).find(x => x.名 === s.工作地点);\n  return 通 && 通用在(通, 这年()) ? { 名: 通.名, 全名: 通.名, 片区: '', 通用: true } : null;\n}\nfunction 学校名() {\n  const s = 档.身份;\n  if (s.学校自定义 && s.学校自定义.名) return s.学校自定义.名;\n  return s.学校 && s.学校 !== '不在学' ? s.学校 : '';\n}\n// 音乐人、自由职业选的那一样（通用的要这一年有；自定义的照写）\nfunction 职业名() {\n  const s = 档.身份;\n  const v = String(s.职业 || '').trim();\n  if (!v) return '';\n  const 通 = (通用身份[s.类] || []).find(x => x.名 === v);\n  return 通 && !通用在(通, 这年()) ? '' : v;\n}\n// 换了年份、成立线以后，这一年没有的原作的地方空出来；回空出来的名字，提示一句\nfunction 修可选() {\n  const 空 = [];\n  const 地 = 档.地点;\n  const 项 = !地.自定义 && (地点表[地.类] || []).find(x => x.名 === 地.名);\n  if (项 && !原作在(项, 这年(), 档.成立线)) { 空.push(项.名); 地.名 = ''; }\n  const s = 档.身份;\n  const 原 = !s.工作自定义 && 工作地点表.find(x => x.名 === s.工作地点);\n  if (原 && !原作在(原, 这年(), 档.成立线)) { if (!空.includes(原.名)) 空.push(原.名); s.工作地点 = ''; }\n  return 空;\n}\n// 男性不能选女子学园、女子大学\nconst 学校可选 = x => !(x.女校 && 档.基本.性别 === '男');\n\n// 缺项：拦着「开始」的；提示：不拦\nfunction 查缺() {\n  const 缺 = [], 提示 = [];\n  const b = 档.基本, s = 档.身份, j = 档.技能, f = 档.第一层;\n  if (!年份()) 缺.push({ 话: '时间 · 年份', 到: '时间' });\n  if (!档.时间.日期 || !档.时间.时刻) 缺.push({ 话: '时间 · 日期和时刻', 到: '时间' });\n  if (!开局地点()) 缺.push({ 话: '地点', 到: '地点' });\n  if (!b.姓名.trim()) 缺.push({ 话: '基本信息 · 姓名', 到: '基本信息', 格: '基本.姓名' });\n  if (!b.性别) 缺.push({ 话: '基本信息 · 性别', 到: '基本信息' });\n  if (!/^\\d{1,3}$/.test(String(b.年龄))) 缺.push({ 话: '基本信息 · 年龄（数字）', 到: '基本信息', 格: '基本.年龄' });\n  if ((s.类 === '打工' || s.类 === '上班') && !工作地点()) 缺.push({ 话: '身份 · ' + (s.类 === '打工' ? '打工地点' : '上班地点'), 到: '基本信息' });\n  if ((s.类 === '打工' || s.类 === '上班') && !s.职位.trim()) 缺.push({ 话: '身份 · 职位', 到: '基本信息', 格: '身份.职位' });\n  if (s.类 === '学生' && !学校名()) 缺.push({ 话: '身份 · 学校', 到: '基本信息' });\n  if (s.类 === '学生' && !s.年级 && s.学校 !== '复读') 缺.push({ 话: '身份 · 年级', 到: '基本信息' });\n  if ((s.类 === '音乐人' || s.类 === '自由职业') && !职业名()) 缺.push({ 话: '身份 · ' + s.类, 到: '基本信息' });\n  if (s.类 === '其他' && !s.其他.trim()) 缺.push({ 话: '身份 · 说明', 到: '基本信息', 格: '身份.其他' });\n  if (!档.性格.核心性格.trim()) 缺.push({ 话: '性格 · 核心性格', 到: '性格', 格: '性格.核心性格' });\n  if (!j.乐器) 缺.push({ 话: '技能 · 乐器（零基础也算）', 到: '技能' });\n  if (j.乐队 === '自组乐队' && !j.乐队名.trim()) 缺.push({ 话: '技能 · 乐队名', 到: '技能', 格: '技能.乐队名' });\n  if (!f.代写 && !f.开场白.trim()) 缺.push({ 话: '第一层 · 开场白（或勾选 AI 代写）', 到: '第一层', 格: '第一层.开场白' });\n  const 用户名 = 酒馆用户名();\n  if (用户名 && b.姓名.trim() && b.姓名.trim() !== 用户名) 提示.push({ 话: '提示 · 姓名与酒馆用户名「' + 用户名 + '」不一致', 到: '基本信息' });\n  const 差 = 配套差();\n  if (差) 提示.push({ 话: '配套 · 差 ' + 差 + ' 项 · 不拦开局', 到: '配套' });\n  return { 缺, 提示 };\n}\n\n// 给 ✦ 的「已填」：只含填了的格子\nfunction 已填摘要() {\n  const o = {};\n  const b = 档.基本;\n  if (年份()) o['年份'] = String(年份());\n  if (档.时间.时节) o['时节'] = 档.时间.时节;\n  if (档.成立线.length) o['成立线（这些乐队开局时还没成立）'] = 档.成立线.join('、');\n  const 地 = 开局地点();\n  if (地) o['开局地点'] = 地.片区 + ' · ' + 地.全名;\n  for (const k of ['姓名', '罗马音', '称呼', '性别', '年龄']) if (String(b[k] || '').trim()) o[k] = b[k];\n  for (const k of 资料组.外貌) if (档.外貌[k].trim()) o[k] = 档.外貌[k];\n  const s = 档.身份;\n  o['身份'] = 身份串();\n  if (学校名() && s.类 !== '学生') o['在读学校'] = 学校名();\n  for (const k of 资料组.身世) if (档.身世[k].trim()) o[k] = 档.身世[k];\n  for (const k of 资料组.性格) if (档.性格[k].trim()) o[k] = 档.性格[k];\n  const j = 档.技能;\n  if (j.乐器) o['乐器'] = 乐器串(j);\n  if (j.特长.length) o['特长'] = j.特长.join('、');\n  if (档.人际.length) o['人际关系'] = 档.人际.map(p => p.名 + '（' + p.关系 + '）').join('、');\n  return o;\n}\n\n// 身份一句话：「打工 · RiNG · 新手工作人员」「学生 · 羽丘 · 高一」「音乐人 · 作曲」（给 ✦ 和底栏摘要；写进表的那句核心照同样的规矩拼）\nfunction 身份串() {\n  const s = 档.身份;\n  if (s.类 === '学生') return ['学生', 学校名(), s.学校 === '复读' ? '' : s.年级].filter(Boolean).join(' · ');\n  if (s.类 === '打工' || s.类 === '上班') return [s.类, (工作地点() || {}).名, s.职位.trim()].filter(Boolean).join(' · ');\n  if (s.类 === '音乐人' || s.类 === '自由职业') return [s.类, 职业名()].filter(Boolean).join(' · ');\n  return s.其他.trim() || '其他';\n}\n// 人际里一个人的好感、信任（千分制）：挪过用挪过的，没挪过照关系表\nfunction 起点(p, 项) {\n  const 默 = (关系表[p.关系] || 关系表['一面之缘'])[项];\n  const n = Number(p[项]);\n  return p[项] === undefined || p[项] === null || p[项] === '' || !isFinite(n) ? 默 : Math.max(-关系满分, Math.min(关系满分, Math.round(n)));\n}\n\n// ── 开局/画面.js ──\n// 0 层卡的画面：照 DESIGN.md「开局卡改版」（曲目单）。每个函数只拼 HTML 字符串，事件在 动作.js 里统一接。\n\nconst 锁图 = '<svg viewBox=\"0 0 12 12\" aria-hidden=\"true\"><rect x=\"2\" y=\"5.5\" width=\"8\" height=\"5.5\" rx=\"1.5\" fill=\"currentColor\"/>'\n  + '<path d=\"M4 5.5V4a2 2 0 0 1 4 0v1.5\" stroke=\"currentColor\" stroke-width=\"1.4\" fill=\"none\"/><\/svg>';\n\n// 六页加一页检查。表单一次画全，只显示当前那一页：换页不重画，正在填的格子、✦ 候选都留着\n// 段 = 这一页里的组（画段的名字）；只有一组的页不画组标题，那组的 ✦ 挪到页头（钮）\nconst 页表 = [\n  { 键: '玩法', 号: '00', 说: '玩法 · 表格模板 · 配套 · 须知', 段: ['玩法', '模板', '配套', '须知'] },\n  { 键: '世界', 号: '01', 说: '时间 · 地点', 段: ['时间', '地点'] },\n  { 键: '主角', 号: '02', 说: '基本信息 · 身份 · 住所 · 外貌 · 开局后 AI 不改', 段: ['基本信息'], 钮: () => ai钮('组', '基本', '✦ 补全') },\n  { 键: '身世性格', 号: '03', 说: '身世背景 · 性格 · 开局后 AI 不改', 段: ['身世性格'], 钮: () => ai钮('组', '身世性格', '✦ 补全') },\n  { 键: '技能物品', 号: '04', 说: '乐器 · 乐队 · 特长 · 随身 · 家中', 段: ['技能', '物品'] },\n  { 键: '人际', 号: '05', 说: '原作角色 · 上限 5 人 · 可空', 段: ['人际关系'], 钮: () => ai钮('人际', '人际', '✦ 推荐') },\n  { 键: '第一层', 号: '06', 说: '1 楼开场白', 段: ['第一层'] },\n  { 键: '检查', 号: 'EN', 说: '开始之前', 段: ['检查'] },\n];\n// 组名（缺项的「到」、画段的名字）落在哪一页\nconst 组在页 = {\n  玩法: '玩法', 模板: '玩法', 配套: '玩法', 须知: '玩法', 时间: '世界', 成立线: '世界', 地点: '世界', 基本信息: '主角', 外貌: '主角',\n  身世背景: '身世性格', 身世: '身世性格', 性格: '身世性格', 身世性格: '身世性格',\n  技能: '技能物品', 物品: '技能物品', 人际关系: '人际', 第一层: '第一层', 检查: '检查',\n};\nconst 页之于 = 组 => 组在页[组] || '世界';\nconst 页项 = 键 => 页表.find(p => p.键 === 键) || 页表[0];\n\n// 表里的列名照《玩家角色资料》不变，屏上换个读得懂的叫法；格名后面的小字是提示\nconst 格名 = { 弱点软肋: '弱点／软肋', 来历: '近况', 与主线关系: '与原作剧情' };\nconst 标名 = k => 格名[k] || k;\nconst 格提示 = { 说话习惯: '第三人称才写进档案', 来历: '开局前这阵子 · 为什么在这一带', 知情人: '能证明身份的人', 反差: '平时一个样，要紧时另一个样', 与主线关系: '默认普通人' };\nconst 占位 = {\n  身高体型: '例：172cm，偏瘦', 发型发色: '例：黑色短发', 瞳色: '例：深棕', 常穿服装: '例：灰色连帽衫，牛仔裤', 外貌特征: '例：左手指腹有茧',\n  出身: '例：本地人，在丰岛长大', 家庭: '例：父母经营洗衣店', 成长经历: '例：初中轻音部待过一年', 来历: '例：春假起在 CiRCLE 打工',\n  知情人: '例：CiRCLE 的月岛麻里奈', 核心性格: '必填 · 例：嘴硬心软，怕麻烦', 社交方式: '例：对生人冷淡，熟人面前话多',\n  说话习惯: '例：句尾常带「吧」', 日常习惯: '例：熬夜、晚起', 反差: '例：平时胆小，护人时豁得出去',\n  生理特点: '例：体力差、容易晕车', 心理状态: '例：表面乐观，心里没底',\n};\nconst 全宽格 = ['外貌特征', '核心性格', '成长经历', '心理状态'];\nconst 演出提示 = 'Live House · 有舞台的小型演出场';\nconst 月日 = 时 => { const d = new Date(时); return isNaN(d) ? '' : 补零(d.getMonth() + 1) + '/' + 补零(d.getDate()); };\n\nconst 胶 = (act, v, on, 字, 附) => '<button type=\"button\" class=\"chip' + (on ? ' on' : '') + '\" data-act=\"' + act + '\" data-v=\"' + 转义(v) + '\"'\n  + (on ? ' aria-pressed=\"true\"' : '') + (附 || '') + '>' + 转义(字 == null ? v : 字) + '<\/button>';\n\nfunction 锁钮(路径, 小) {\n  const on = 锁着(路径);\n  // 锁用 data-lock 不用 data-k：data-k 只留给输入框，按 data-k 找格子（跳转、重画后还原焦点）才不会找到锁上\n  return '<button type=\"button\" class=\"lock' + (小 ? ' sm' : '') + (on ? ' on' : '') + '\" data-act=\"锁\" data-lock=\"' + 路径 + '\" aria-pressed=\"' + on\n    + '\" aria-label=\"' + (on ? '解锁' : '锁定') + '\" title=\"锁上 · 随机时不动\">' + 锁图 + '<\/button>';\n}\nfunction 输入(路径, 选) {\n  选 = 选 || {};\n  return '<label class=\"in' + (选.cls ? ' ' + 选.cls : '') + '\">' + (选.ic ? '<span class=\"ic\">' + 选.ic + '<\/span>' : '')\n    + '<input data-k=\"' + 路径 + '\" value=\"' + 转义(取(路径)) + '\" placeholder=\"' + 转义(选.ph || '') + '\"'\n    + (选.数 ? ' inputmode=\"numeric\"' : '') + (选.长 ? ' maxlength=\"' + 选.长 + '\"' : '') + ' aria-label=\"' + 转义(选.名 || 路径.split('.').pop()) + '\"><\/label>';\n}\nfunction 标签(名, 路径, 可锁, 右, 提) {\n  return '<div class=\"oc-lab\">' + 名 + (提 ? '<small>' + 提 + '<\/small>' : '') + '<span class=\"grow\"><\/span>' + (右 || '') + (可锁 ? 锁钮(路径) : '') + '<\/div>';\n}\nfunction 头像(人, 尺寸) {\n  return 人 && 人.头像 ? 头像画布(人.头像, 尺寸 || 40) : '<span class=\"ph\">·<\/span>';\n}\nfunction 能帮填() {\n  if (!核) return '总控没接上';\n  const 接 = 核态 && 核态.帮填接口;\n  return 接 && 接.配好 ? '' : '帮填接口没配 · ⚙ 设置';\n}\nfunction ai钮(种, 目标, 字) {\n  const 键 = 种 + ':' + 目标;\n  const 忙 = !!界.忙[键];\n  const 不能 = 能帮填();\n  const 续写空 = 种 === '开场白' && 目标 === '续写' && !档.第一层.开场白.trim();\n  return '<button type=\"button\" class=\"ai' + (忙 ? ' busy' : '') + '\" data-act=\"帮填\" data-kind=\"' + 种 + '\" data-v=\"' + 转义(目标) + '\"'\n    + (不能 || 忙 || 续写空 ? ' disabled' : '') + (不能 ? ' title=\"' + 转义(不能) + '\"' : '') + '>' + (忙 ? '✦ …' : 字) + '<\/button>';\n}\nfunction 候选区(路径) {\n  const 列 = 界.候选[路径];\n  if (!列 || !列.length) return '';\n  return '<div class=\"sugg stagger\">' + 列.map(c => '<button type=\"button\" data-act=\"采用\" data-k=\"' + 路径 + '\" data-v=\"' + 转义(c) + '\"><b>✦<\/b>' + 转义(c) + '<\/button>').join('')\n    + '<button type=\"button\" class=\"why\" data-act=\"清候选\" data-k=\"' + 路径 + '\">收起<\/button><\/div>';\n}\nfunction 自定义胶(域, 值) {\n  const 有 = 值 && (值.名 || 值.片区);\n  return (有 ? '<button type=\"button\" class=\"chip on\" data-act=\"自定义\" data-v=\"' + 域 + '\" aria-pressed=\"true\">' + 转义(值.名 || 值.片区) + '<span class=\"x\">✎<\/span><\/button>' : '')\n    + '<button type=\"button\" class=\"chip add\" data-act=\"自定义\" data-v=\"' + 域 + '\" aria-expanded=\"' + (界.自定义 === 域) + '\">＋ 自定义<\/button>';\n}\nfunction 画自定义框(域, 标题, 签, 值, 要片区) {\n  值 = 值 || {};\n  const 片 = '<select id=\"自定片\" aria-label=\"所属片区\"><option value=\"\">选一片<\/option>'\n    + 片区表.map(p => '<option' + (值.片区 === p ? ' selected' : '') + '>' + p + '<\/option>').join('') + '<\/select>';\n  return '<div class=\"custom-box anim-unfold\"><h6>' + 标题 + '<span>' + 签 + '<\/span><\/h6><div class=\"mini-form\"' + (要片区 ? '' : ' style=\"grid-template-columns:1fr auto\"') + '>'\n    + '<div><label class=\"cap\" for=\"自定名\">名称<\/label><label class=\"in sm\"><input id=\"自定名\" value=\"' + 转义(值.名 || '') + '\" maxlength=\"20\" placeholder=\"名称\"><\/label><\/div>'\n    + (要片区 ? '<div><label class=\"cap\" for=\"自定片\">所属片区<\/label><label class=\"in sm\">' + 片 + '<\/label><\/div>' : '')\n    + '<button type=\"button\" class=\"btn sm\" data-act=\"自定确定\" data-v=\"' + 域 + '\">确定<\/button><\/div><\/div>';\n}\n\nfunction 罗马名(罗马音) {\n  const 段 = String(罗马音 || '').trim().split(/\\s+/).filter(Boolean);\n  return 段.length ? 段[段.length - 1].toUpperCase() : '';\n}\nfunction 水印(罗马音) {\n  const 名 = 罗马名(罗马音);\n  return 名 ? '<div class=\"oc-wm\" aria-hidden=\"true\">' + 转义(名) + '<\/div>' : '';\n}\n\n// ── 屏：等核心、没脚本、须知 ──\nfunction 画等() {\n  return '<div class=\"oc anim-card\"><div class=\"oc-head\"><div class=\"oc-title\"><b>开局<\/b><em>NEW GAME<\/em><\/div><\/div><p class=\"oc-sub\">总控准备中<\/p><\/div>';\n}\nfunction 画没脚本() {\n  return '<div class=\"oc anim-card\"><div class=\"oc-head\"><div class=\"oc-title\"><b>开局<\/b><em>NEW GAME<\/em><\/div><\/div>'\n    + '<div class=\"banner\"><b><i>!<\/i>缺：角色脚本「BanG 总控」<\/b><div class=\"rows\">'\n    + '<div>开关位置 · <span>酒馆助手 → 脚本库 → 角色脚本 · 本卡那一栏<\/span><\/div>'\n    + '<div>开启后 · <span>这一楼自动刷新；不刷新时重开聊天<\/span><\/div><\/div><\/div><\/div>';\n}\nfunction 画须知(看过) {\n  return '<div class=\"notice anim-sheet\" id=\"须知\"><div class=\"en\">BEFORE YOU START<\/div><h5>开局须知<\/h5>'\n    + '<table class=\"ntb\"><tr class=\"hot\"><td class=\"k\">发布渠道<\/td><td>仅类脑社区。从其他渠道拿到本卡的——你被骗了~<\/td><\/tr>'\n    + '<tr><td class=\"k\">性质<\/td><td>免费同人作品，与官方无关；禁止商用、倒卖<\/td><\/tr><\/table>'\n    + '<div class=\"ack\">' + (看过\n      ? '<span><\/span><button type=\"button\" class=\"btn ghost\" data-act=\"关须知\">收起<\/button>'\n      : '<label class=\"chk\"><input type=\"checkbox\" id=\"已阅读\"><span class=\"box\">✓<\/span>已阅读<\/label><button type=\"button\" class=\"btn sm\" data-act=\"确认须知\" disabled>确认<\/button>')\n    + '<\/div><\/div>';\n}\n\n// ── 设置（⚙）：表单、档案换成这一页，「返回」回去 ──\n// 帮填接口只存在这台浏览器：密钥不回显，存过就只写「已存」\nfunction 画设置() {\n  const 接 = (核态 && 核态.帮填接口) || {};\n  const 话 = 界.接口话;\n  const 忙 = !!(话 && 话.忙);\n  const 状 = 话 ? '<div class=\"tip' + (话.坏 ? ' bad' : '') + '\">' + 转义(话.话) + '<\/div>'\n    : '<div class=\"tip\">' + (接.配好 ? '已配 · ' + 转义(接.模型) : '没配 · ✦ 补全、代写、推荐用不了') + '<\/div>';\n  const 列 = 界.模型们 && 界.模型们.length\n    ? '<label class=\"in sm\" style=\"margin-top:6px\"><select id=\"模型列表\" aria-label=\"选模型\"><option value=\"\">拉到 ' + 界.模型们.length + ' 个 · 选一个<\/option>'\n      + 界.模型们.map(m => '<option' + (m === 接.模型 ? ' selected' : '') + '>' + 转义(m) + '<\/option>').join('') + '<\/select><\/label>' : '';\n  // 进场动画只在打开时播一次；保存、测试、拉列表时重画不再播\n  const 动 = 界.设置动;\n  界.设置动 = false;\n  return '<div class=\"oc' + (动 ? ' anim-sheet' : '') + '\" id=\"卡\">'\n    + '<div class=\"oc-head\"><div class=\"oc-title\"><b>设置<\/b><em>SETTINGS<\/em><\/div><div class=\"oc-tools\">'\n    + '<button type=\"button\" class=\"oc-tool\" data-act=\"关设置\">返回<\/button><\/div><\/div>'\n    + '<div class=\"oc-sec-h\"><b>帮填接口<\/b><span>✦ 补全、代写、推荐 · 只存在这台浏览器<\/span><\/div>'\n    + '<div class=\"oc-row\"><div><label class=\"oc-lab\" for=\"接口地址\">接口地址<\/label><label class=\"in\"><input id=\"接口地址\" value=\"' + 转义(接.地址 || '') + '\" placeholder=\"https://…/v1\" autocomplete=\"off\" spellcheck=\"false\"><\/label><\/div>'\n    + '<div><label class=\"oc-lab\" for=\"接口密钥\">密钥<small>' + (接.有密钥 ? '已存 · 不改就空