;\n  return '<div class=\"pop pfp stagger\" role=\"dialog\" aria-label=\"角色存档\"><h6>角色存档 · 存在这台浏览器<\/h6>'\n    + (行 || '<p class=\"none\">还没有存档<\/p>')\n    + '<button type=\"button\" class=\"add-row\" data-act=\"存当前\"><span>' + (覆待 ? '再按一次：覆盖「' + 转义(名) + '」' : '＋ 存当前') + '<\/span><small>按姓名存 · 上限 20<\/small><\/button>'\n    + (档案屏 ? '' : '<h6 class=\"gap\">这个聊天的草稿<\/h6>'\n      + '<button type=\"button\" class=\"row\" data-act=\"导出草稿\"><span>导出成文件<\/span><i>↓<\/i><\/button>'\n      + '<button type=\"button\" class=\"row\" data-act=\"导入草稿\"><span>从文件导入<\/span><i>↑<\/i><\/button>'\n      + '<button type=\"button\" class=\"row\" data-act=\"清空草稿\"><span>' + (待 === '清' ? '再按一次：清空重填' : '清空重填') + '<\/span><i>×<\/i><\/button>'\n      + '<input type=\"file\" id=\"草稿文件\" accept=\".json,application/json\" hidden>')\n    + '<\/div>';\n}\nfunction 开局人名() {\n  const 快 = (核 && 核.snapshot && 核.snapshot()) || {};\n  const a = (快.主角 && 快.主角.档案) || {};\n  const 起 = (核态 && 核态.开局档) || null;\n  return String(a.姓名 || (起 && 起.基本 && 起.基本.姓名) || '').trim();\n}\nfunction 画工具(档案屏) {\n  return '<button type=\"button\" class=\"oc-tool' + (界.存档开 ? ' open' : '') + '\" data-act=\"存档\" aria-expanded=\"' + !!界.存档开 + '\" aria-label=\"角色存档\">'\n    + '<span class=\"full\">角色存档<\/span><span class=\"short\" aria-hidden=\"true\">档<\/span><\/button>'\n    + '<button type=\"button\" class=\"oc-tool\" data-act=\"设置\" aria-label=\"设置\">⚙<\/button>';\n}\n\n// 开局须知（00 页最后一组）：没读过时下面是「已阅读」和「确认」，别的页点不开；读过只留两行表\nfunction 段须知() {\n  const 等 = 界.屏 === '须知';\n  return '<div class=\"oc-sec-h\"><b>开局须知<\/b><span>' + (等 ? '读过才能往下填' : '发布渠道 · 性质') + '<\/span><\/div>'\n    + '<table class=\"ntb\"><tr class=\"hot\"><td class=\"k\">发布渠道<\/td><td>仅类脑社区。从其他渠道拿到本卡的——你被骗了~<\/td><\/tr>'\n    + '<tr><td class=\"k\">性质<\/td><td>免费同人作品，与官方无关；禁止商用、倒卖<\/td><\/tr><\/table>'\n    + (等 ? '<div class=\"ack-row\"><label class=\"chk\"><input type=\"checkbox\" id=\"已阅读\"><span class=\"box\">✓<\/span>已阅读<\/label>'\n      + '<button type=\"button\" class=\"btn sm\" data-act=\"确认须知\" disabled>确认<\/button><\/div>' : '');\n}\n\nfunction 画表单() {\n  const 等须知 = 界.屏 === '须知';\n  if (等须知) 界.页 = '玩法';\n  return (界.看须知 && !等须知 ? 画须知(true) : '')\n    + '<div class=\"oc anim-card\" id=\"卡\">'\n    + '<span id=\"水印\">' + 水印(档.基本.罗马音) + '<\/span>'\n    + '<div class=\"oc-head\"><div class=\"oc-title\"><b>开局<\/b><em>SETLIST<\/em><\/div><div class=\"oc-tools\">'\n    + '<button type=\"button\" class=\"dice\" data-act=\"全随机\" title=\"没填、没锁的格子随机填上，名字除外\"><i>🎲<\/i><span>随机<\/span><\/button>'\n    + 画工具(false) + '<\/div>' + (界.存档开 ? 画存档单(false) : '') + '<\/div>'\n    + '<p class=\"oc-sub\">灰字 = 选填 · 锁 = 随机时不动<\/p>'\n    + 画缺前置() + 画提醒() + 画提示()\n    + '<div class=\"sl\">' + 画曲目单() + '<div class=\"sl-pages\">' + 页表.map(画页).join('') + '<\/div><\/div>'\n    + 画底栏() + '<\/div>';\n}\n\n// ── 曲目单：一页一行，写着这一页填了什么；有缺项的挂红点 ──\nfunction 页缺(查, 键) {\n  return 键 === '检查' ? 查.缺 : 查.缺.filter(x => 页之于(x.到) === 键);\n}\nfunction 页填了(键) {\n  const f = 档.第一层;\n  return ({\n    世界: () => !!年份() && !!开局地点(),\n    玩法: () => !!(核态 && 核态.须知已读),\n    主角: () => !!档.基本.姓名.trim(),\n    身世性格: () => !!档.性格.核心性格.trim(),\n    技能物品: () => !!档.技能.乐器,\n    人际: () => 档.人际.length > 0,\n    第一层: () => f.代写 || !!f.开场白.trim(),\n  }[键] || (() => false))();\n}\nfunction 填了几格(组们) {\n  let 有 = 0, 共 = 0;\n  for (const 组 of 组们) for (const k of 资料组[组]) { 共 += 1; if (String(组数据(组)[k] || '').trim()) 有 += 1; }\n  return 有 + ' / ' + 共;\n}\nfunction 页摘要(键, 查) {\n  const 缺 = 页缺(查, 键);\n  if (键 === '检查') return 缺.length ? '缺 ' + 缺.length + ' 项' : '齐了';\n  if (缺.length) return '缺' + 缺.map(x => x.话.split(' · ').pop().replace(/（.*$/, '')).join('、');\n  const 季 = (档.时间.时节 || '').split(' · ')[0];\n  const j = 档.技能, f = 档.第一层;\n  const 写 = ({\n    玩法: () => (界.屏 === '须知' ? '先读开局须知' : 核态 && 核态.模板已导入 ? '正常内容 · 表格已导入' : '正常内容'),\n    世界: () => [年份() ? 年份() + ' ' + 季 : '', (开局地点() || {}).名].filter(Boolean).join(' · '),\n    主角: () => [档.基本.姓名.trim(), 身份短()].filter(Boolean).join(' · '),\n    身世性格: () => '填了 ' + 填了几格(['身世', '性格']),\n    技能物品: () => (j.乐器 ? (j.乐器 === '零基础' ? '零基础' : 乐器们(j).map(x => x.名).join('、')) : ''),\n    人际: () => (档.人际.length ? 档.人际.length + ' 人' : '可空'),\n    第一层: () => (f.代写 ? 'AI 代写' : f.开场白.trim() ? f.开场白.trim().length + ' 字' : ''),\n  }[键] || (() => ''))();\n  return 写 || '—';\n}\nfunction 画曲目单() {\n  const 查 = 查缺();\n  return '<nav class=\"sl-list\" id=\"曲目单\" aria-label=\"分页\"><div class=\"sl-cap\">SETLIST<\/div>'\n    + 页表.map(p => {\n      const 缺 = 页缺(查, p.键).length;\n      const on = p.键 === 界.页;\n      const 齐 = !on && p.键 !== '检查' && !缺 && 页填了(p.键);\n      const 锁页 = 界.屏 === '须知' && p.键 !== '玩法';\n      return '<button type=\"button\" class=\"sl-it' + (on ? ' on' : '') + (齐 ? ' done' : '') + (p.键 === '检查' ? ' enc' : '') + '\" data-act=\"页\" data-v=\"' + p.键 + '\"'\n        + (on ? ' aria-current=\"page\"' : '') + (锁页 ? ' disabled' : '') + '><span class=\"no\">' + p.号 + '<\/span><span class=\"nm\"><b>' + p.键\n        + (缺 && p.键 !== '检查' ? '<i class=\"dotx\" title=\"缺 ' + 缺 + ' 项\"><\/i>' : '') + '<\/b><small>' + 转义(页摘要(p.键, 查)) + '<\/small><\/span><\/button>';\n    }).join('') + '<\/nav>';\n}\n// 「a · b · c」这种提示：窄屏只在「 · 」处换行，一段里不拆开\nconst 分段 = s => String(s).split(' · ').map(x => '<span class=\"nw\">' + 转义(x) + '<\/span>').join(' · ');\nfunction 画页头(p) {\n  return '<div class=\"pg-h\" id=\"页头-' + p.键 + '\"><span class=\"pg-no\" aria-hidden=\"true\">' + p.号 + '<\/span><div class=\"pg-t\"><b>' + p.键 + '<\/b><span>' + 分段(p.说) + '<\/span><\/div>'\n    + (p.钮 ? '<span class=\"grow\"><\/span>' + p.钮() : '') + '<\/div>';\n}\nfunction 画页(p) {\n  const i = 页表.indexOf(p), 前 = 页表[i - 1], 后 = 页表[i + 1];\n  return '<section class=\"pg' + (p.键 === 界.页 ? ' on' : '') + '\" data-page=\"' + p.键 + '\" id=\"页-' + p.键 + '\" aria-label=\"' + p.号 + ' ' + p.键 + '\">'\n    + 画页头(p)\n    + p.段.map((n, j) => '<div class=\"oc-sec' + (j === 0 ? ' first' : '') + '\" id=\"sec-' + n + '\" data-sec=\"' + n + '\">' + 画段(n) + '<\/div>').join('')\n   