 尾: '一键改', 改: '最小长度' });\n    if (库态.剧本待刷新) 行.push({ 组: '数据库', 好: false, 字: '导演剧本 · 写好了 · 刷新页面生效', 尾: '刷新页面 →', act: '刷新页面' });\n    else if (库态.剧本排除 !== undefined) 行.push({ 组: '数据库', 好: 库态.剧本排除, 字: '导演剧本 · ' + (库态.剧本排除 ? '已排除' : '没排除'), 尾: '一键改', 改: '剧本排除' });\n  }\n  if (手.有) {\n    行.push({ 组: '手账本', 好: !!手.状态模型, 字: '状态模型 · ' + (手.状态模型 ? '已配' : '没填密钥'), 尾: '悬浮球 → 齿轮 → 模型' });\n    行.push({ 组: '手账本', 好: !!手.心理模型, 字: '心理模型 · ' + (手.心理模型 ? 手.心理模型.模板 + ' 本模板' : '没找到'), 尾: '导入后自动认' });\n    if (手.阻塞方式) 行.push({ 组: '手账本', 好: 手.阻塞方式 === '每轮', 字: '发送时等它 · ' + 手.阻塞方式, 尾: '一键改', 改: '阻塞方式' });\n  }\n  return 行;\n}\nfunction 配套差() {\n  const 行 = 配套行们();\n  return 行 ? 行.filter(x => !x.好).length : 0;\n}\nfunction 段配套() {\n  const 行 = 配套行们(), 动 = 界.配套改了 || [];\n  const 差 = 行 ? 行.filter(x => !x.好).length : 0, 能改 = 行 ? 行.filter(x => x.改 && !x.好).length : 0;\n  const 签 = !行 ? '<span class=\"st no\">查看中<\/span>' : 差 ? '<span class=\"st no\">差 ' + 差 + ' 项<\/span>'\n    : '<span class=\"st yes' + (动.length ? ' anim-done' : '') + '\">已配好 ✓<\/span>';\n  const 头 = '<div class=\"oc-sec-h\"><b>配套<\/b><span>数据库 · 手账本<\/span><\/div>'\n    + '<div class=\"tpl\"><span class=\"ico\">SET<\/span><div class=\"txt\"><b>推荐设置 · 4 项能一键改<\/b><span>' + 分段('数据库每层都填表 · 不读导演剧本 · 手账本每轮等它') + '<\/span><\/div>'\n    + 签 + '<button type=\"button\" class=\"btn ghost\" data-act=\"一键配好\"' + (!能改 || 界.配套忙 ? ' disabled' : '') + '>' + (界.配套忙 ? '改着' : '一键配好') + '<\/button><\/div>';\n  if (!行) return 头;\n  let 序 = 0;\n  const 画行 = x => {\n    const 新 = !!(x.改 && 动.includes(x.改));\n    const 延 = 新 ? Math.min(序++, 3) * 60 : 0;\n    const 段 = x.字.split(' · '), 字 = 转义(段[0]) + (段.length > 1 ? ' · <span class=\"nw\">' + 转义(段.slice(1).join(' · ')) + '<\/span>' : '');   // 窄屏折行时「没配」「冲击轮」不拆开\n    const 内 = '<i aria-hidden=\"true\"' + (新 ? ' class=\"anim-done\"' : '') + '>' + (x.好 ? '✓' : '!') + '<\/i><span class=\"grow\">' + 字 + '<\/span><em>' + (x.好 ? '' : 转义(x.尾 || '')) + '<\/em>';\n    const 类 = 'it' + (x.好 ? '' : ' bad') + (新 ? ' anim-res' : ''), 式 = 延 ? ' style=\"animation-delay:' + 延 + 'ms\"' : '';\n    return x.act && !x.好 ? '<button type=\"button\" class=\"' + 类 + '\" data-act=\"' + x.act + '\"' + 式 + '>' + 内 + '<\/button>' : '<div class=\"' + 类 + '\"' + 式 + '>' + 内 + '<\/div>';\n  };\n  const 组 = 名 => { const 列 = 行.filter(x => x.组 === 名); return 列.length ? '<div class=\"oc-lab\">' + 名 + '<\/div><div class=\"check\">' + 列.map(画行).join('') + '<\/div>' : ''; };\n  return 头 + 组('数据库') + 组('手账本') + '<p class=\"oc-hint\">' + 分段('数据库两项是全局设置 · 别的卡也跟着变') + '<\/p>'\n    + '<p class=\"oc-hint\">' + 分段('导演剧本 · 改完刷新一次页面才生效') + '<\/p>';\n}\n\nfunction 段时间() {\n  const t = 档.时间;\n  const 卡们 = 年份卡.map(c => '<button type=\"button\" class=\"yc' + (!t.自选 && Number(t.年) === c.年 ? ' on' : '') + '\" data-act=\"年\" data-v=\"' + c.年 + '\"><b>' + c.年 + '<\/b><i>' + 转义(c.说) + '<\/i><\/button>').join('')\n    + '<div class=\"yc custom' + (t.自选 ? ' on' : '') + '\" data-act=\"自选年\"><b>自选<\/b><i>任意年份 · 可早于 2018<\/i>'\n    + '<label class=\"in\"><span class=\"ic\">📅<\/span><input type=\"number\" inputmode=\"numeric\" min=\"1900\" max=\"2100\" placeholder=\"年份\" data-k=\"时间.自选年\" value=\"' + 转义(t.自选年) + '\" aria-label=\"自选年份\"><\/label><\/div>';\n  const 年 = 年份();\n  return '<div class=\"oc-sec-h\"><b>时间<\/b><span>可自选<\/span><span class=\"grow\"><\/span><button type=\"button\" class=\"dice\" data-act=\"段随机\" data-v=\"时间\"><i>🎲<\/i>随机<\/button><\/div>'\n    + '<div class=\"years\">' + 卡们 + '<\/div>'\n    + '<div class=\"oc-lab\">时节<small>季内随机日期<\/small><\/div>'\n    + '<div class=\"chips\">' + 时节表.map(x => 胶('时节', x.名, t.时节 === x.名)).join('') + '<\/div>'\n    + '<div class=\"oc-row\" style=\"margin-top:10px\">'\n    + '<label class=\"in\"><span class=\"ic\">📅<\/span><input type=\"date\" data-k=\"时间.日期\" value=\"' + 转义(t.日期) + '\" aria-label=\"日期\"><span class=\"wk\" id=\"周几\">' + 周几(t.日期) + '<\/span>' + (t.日期随机 ? '<span class=\"roll\">随机<\/span>' : '') + '<\/label>'\n    + '<label class=\"in\"><span class=\"ic\">🕘<\/span><input type=\"time\" step=\"600\" data-k=\"时间.时刻\" value=\"' + 转义(t.时刻) + '\" aria-label=\"时刻\"><span class=\"wk\" id=\"时段\">' + 时段名(t.时刻) + '<\/span>' + (t.时刻随机 ? '<span class=\"roll\">随机<\/span>' : '') + '<\/label>'\n    + '<\/div>' + '<div id=\"成立线组\">' + 画成立线() + '<\/div>'\n    + (年 && 年 < 2018 ? '<p class=\"oc-hint\">这一年原作乐队都还没登场，乐队表记成「未成立」；原作的店不列<\/p>' : '');\n}\n// 成立线：「时间」下面一组，只列开局那一年已经在活动的乐队（DESIGN「剧情开关」）；那一年还没有就不画\nfunction 画成立线() {\n  const 可 = 可选成立线(年份());\n  if (!可.length) return '';\n  return '<div class=\"oc-lab\">成立线<small>这支乐队从还没组队时演起 · 可多选<\/small><\/div>'\n    + '<div class=\"chips\">' + 可.map(队 => 胶('成立线', 队, 档.成立线.includes(队))).join('') + '<\/div>';\n}\n\nfunction 段地点() {\n  const 地 = 档.地点;\n  const 项们 = (地点表[地.类] || []).filter(x => 原作在(x, 这年(), 档.成立线));\n  const 当前 = 开局地点();\n  const 演 = 地.类 === 'Live House';\n  return '<div class=\"oc-sec-h\"><b>地点<\/b><span>初始位置 · 三类单选<\/span><span class=\"grow\"><\/span><button type=\"button\" class=\"dice\" data-act=\"段随机\" data-v=\"地点\"><i>🎲<\/i>随机<\/button><\/div>'\n    + '<div class=\"seg2\" role=\"group\" aria-label=\"地点类别\">' + ['学校', 'Live House', '街道'].map(c => '<button type=\"button\" class=\"' + (地.类 === c ? 'on' : '') + '\" data-act=\"地点类\" data-v=\"' + c + '\">' + c + '<\/button>').join('') + '<\/div>'\n    + (演 ? '<p class=\"oc-hint lead\">' + 演出提示 + '<\/p>' : '')\n    + '<div class=\"chips\">' + 项们.map(x => 胶('地点', x.名, !地.自定义 && 地.名 === x.名)).join('') + 自定义胶('地点', 地.自定义) + '<\/div>'\n    + (界.自定义 === '地点' ? 画自定义框('地点', '自定义地点', '地图外 · 钉子落在那一片中间', 地.自定义, true) : '')\n    + (演 && !项们.length ? '<p class=\"oc-hint\">原作的 Live House · 2018 年起<\/p>' : '')\n    + '<p class=\"oc-hint\">当前：' + (当前 ? 转义(当前.片区 + ' · ' + 当前.全名) : '未选') + '<\/p>';\n}\n\n// ── 身份：六类。学生、打工先列原作的地方再列通用的；每类都能自定义 ──\nfunction 学校胶们(带不在学) {\n  const s = 档.身份;\n  return 地点表['学校'].map(x => {\n    const 可 = 学校可选(x);\n    return 胶('学校', x.名, 可 && !s.学校自定义 && s.学校 === x.名, x.名, 可 ? '' : ' disabled title=\"性别「男」：女子学园、女子大学停用\"');\n  }).join('');\n}\nfunction 通用胶们(类, act, 当前) {\n  return (通用身份[类] || []).filter(x => 通用在(x, 这年())).map(x => 胶(act, x.名, 当前 === x.名)).join('');\n}\nfunction 画学生() {\n  const s = 档.身份;\n  const 通当前 = s.学校自定义 ? '' : s.学校;\n  return '<div class=\"oc-lab\">学校<\/div>'\n    + '<div class=\"sub-lab\">原作<\/div><div class=\"chips\">' + 学校胶们(false) + '<\/div>'\n    + '<div class=\"sub-lab\">通用<\/div><div class=\"chips\">' + 通用胶们('学生', '学校', 通当前) + 自定义胶('学校', s.学校自定义) + '<\/div>'\n    + (界.自定义 === '学校' ? 画自定义框('学校', '自定义学校', '地图外', s.学校自定义, true) : '')\n    + (s.学校 === '复读' && !s.学校自定义 ? '' : '<div class=\"oc-lab\">年级<\/div><div class=\"chips\">' + 年级表.map(x => 胶('年级', x, s.年级 === x)).join('') + '<\/div>');\n}\nfunction 画工作(类) {\n  const s = 档.身份;\n  const 原们 = 类 === '打工' ? 工作地点表.filter(x => 原作在(x, 这年(), 档.成立线)) : [];\n  const 当前 = s.工作自定义 ? '' : s.工作地点;\n  const 选 = 工作地点();\n  const 提 = [];\n  if (选 && 选.演出) 提.push(演出提示);\n  if (选 && 选.通用) 提.push('通用身份没有地图标记 · 地图上「设为工作」补');\n  if (类 === '打工' && 这年() < 2018) 提.push('原作的店 · 2018 年起');\n  return '<div class=\"oc-lab\">' + (类 === '打工' ? '打工地点' : '上班地点') + '<\/div>'\n    + (原们.length ? '<div class=\"sub-lab\">原作<\/div><div class=\"chips\">' + 原们.map(x => 胶('工作地点', x.名, 当前 === x.名)).join('') + '<\/div><div class=\"sub-lab\">通用<\/div>' : '')\n    + '<div class=\"chips\">' + 通用胶们(类, '工作地点', 当前) + 自定义胶('工作', s.工作自定义) + '<\/div>'\n    + (界.自定义 === '工作' ? 画自定义框('工作', '自定义' + (类 === '打工' ? '打工地点' : '上班地点'), '地图外 · 钉子落在那一片中间', s.工作自定义, true) : '')\n    + (提.length ? '<p class=\"oc-hint\">' + 转义(提.join(' · ')) + '<\/p>' : '')\n    + '<div class=\"oc-row\"><div>' + 标签('职位', '', false) + 输入('身份.职位', { ph: '例：' + 默认职位[类], 长: 16, 名: '职位' }) + '<\/div><\/div>';\n}\nfunction 画职业(类) {\n  const s = 档.身份;\n  const v = String(s.职业 || '').trim();\n  const 通 = (通用身份[类] || []).some(x => x.名 === v);\n  const 自 = v && !通 ? { 名: v } : null;\n  return '<div class=\"chips\">' + 通用胶们(类, '职业', 通 ? v : '') + 自定义胶('职业', 自) + '<\/div>'\n    + (界.自定义 === '职业' ? 画自定义框('职业', '自定义' + 类, '两到八个字', 自, false) : '');\n}\nfunction 画其他身份() {\n  const s = 档.身份;\n  return '<div class=\"chips\">' + 通用胶们('其他', '其他身份', s.其他.trim()) + '<\/div>'\n    + '<div style=\"margin-top:8px\">' + 输入('身份.其他', { ph: '一句说明 · 例：在老家的店里帮忙', 长: 24, 名: '身份说明' }) + '<\/div>';\n}\nfunction 画身份() {\n  const s = 档.身份, 类 = s.类;\n  return '<div class=\"oc-lab\">身份<\/div><div class=\"chips\" role=\"group\" aria-label=\"身份\">' + 身份类表.map(c => 胶('身份类', c, 类 === c)).join('') + '<\/div>'\n    + '<div class=\"id-box\">'\n    + (类 === '学生' ? 画学生() : 类 === '打工' || 类 === '上班' ? 画工作(类) : 类 === '音乐人' || 类 === '自由职业' ? 画职业(类) : 画其他身份())\n    + (类 !== '学生' ? '<div class=\"oc-lab\">在读学校<small>选填<\/small><\/div><div class=\"chips\">' + 学校胶们(true)\n      + 通用身份.学生.filter(x => x.名 !== '复读').map(x => 胶('学校', x.名, !s.学校自定义 && s.学校 === x.名)).join('')\n      + 胶('学校', '不在学', !s.学校自定义 && s.学校 === '不在学') + 自定义胶('学校', s.学校自定义) + '<\/div>'\n      + (界.自定义 === '学校' ? 画自定义框('学校', '自定义学校', '地图外', s.学校自定义, true) : '') : '')\n    + '<\/div>';\n}\nfunction 段基本() {\n  const b = 档.基本;\n  return '<div class=\"oc-row\"><div>' + 标签('姓名', '基本.姓名', true) + 输入('基本.姓名', { ph: '姓名', 长: 20, 名: '姓名' }) + '<\/div>'\n    + '<div>' + 标签('罗马音', '基本.罗马音', true, ai钮('格', '基本.罗马音', '✦ 补全'), '拉丁字母 · 面板水印用') + 输入('基本.罗马音', { ph: 'Tokoyo Akari', cls: 'roman', 长: 32, 名: '罗马音' }) + 候选区('基本.罗马音') + '<\/div><\/div>'\n    + '<div class=\"oc-row three\"><div>' + 标签('称呼', '基本.称呼', true) + 输入('基本.称呼', { ph: '别人怎么叫', 长: 12, 名: '称呼' }) + 候选区('基本.称呼') + '<\/div>'\n    + '<div><div class=\"oc-lab\">性别<\/div><div class=\"chips\">' + ['女', '男', '保密'].map(g => 胶('性别', g, b.性别 === g)).join('') + '<\/div><\/div>'\n    + '<div>' + 标签('年龄', '基本.年龄', true) + 输入('基本.年龄', { ph: '17', 数: true, 长: 3, 名: '年龄' }) + '<\/div><\/div>'\n    + 画身份()\n    + '<div class=\"oc-lab\">住所<small>选填<\/small><\/div><div class=\"chips\">'\n    + 住所表.map(x => 胶('住所', x.名, !档.住所.自定义 && 档.住所.名 === x.名)).join('') + 自定义胶('住所', 档.住所.自定义) + '<\/div>'\n    + (界.自定义 === '住所' ? 画自定义框('住所', '自定义住所', '街区或门牌 · 真实或虚构', 档.住所.自定义, true) : '')\n    + 画组('外貌')\n    + (b.性别 === '男' ? '<p class=\"oc-hint\">性别「男」：女子学园、女子大学停用<\/p>' : '');\n}\n\nfunction 组数据(组) { return 组 === '外貌' ? 档.外貌 : 组 === '身世' ? 档.身世 : 档.性格; }\nfunction 画组(组) {\n  const 格们 = 资料组[组];\n  const 源 = 组数据(组);\n  const 填 = 格们.filter(k => String(源[k] || '').trim()).length;\n  const 名 = { 外貌: '外貌', 身世: '身世背景', 性格: '性格' }[组];\n  const 提 = { 外貌: '选填', 身世: 'AI 照这些写身世，不另编', 性格: 'AI 替你说话、动作时照这些' }[组];\n  const 收 = !!界.收起[组];\n  return '<div class=\"grp' + (收 ? ' shut' : '') + '\" id=\"grp-' + 组 + '\" data-grp=\"' + 组 + '\">'\n    + '<div class=\"grp-h\" data-act=\"收\" data-v=\"' + 组 + '\" role=\"button\" tabindex=\"0\" aria-expanded=\"' + !收 + '\">'\n    + '<b>' + 名 + '<\/b><span class=\"hint\">' + 提 + '<\/span><span class=\"cnt\" id=\"计-' + 组 + '\">' + 填 + ' / ' + 格们.length + '<\/span>'\n    + '<span class=\"grow\"><\/span>' + ai钮('组', 组, '✦') + '<span class=\"chev\" aria-hidden=\"true\">▾<\/span><\/div>'\n    + '<div class=\"grp-b\">' + 格们.map(k => 画格(组, k)).join('') + '<\/div><\/div>';\n}\nfunction 画格(组, k) {\n  const 路 = 组 + '.' + k;\n  return '<div class=\"fld' + (全宽格.includes(k) ? ' full' : '') + (锁着(路) ? ' locked' : '') + '\" id=\"f-' + 路 + '\">'\n    + '<label for=\"i-' + 路 + '\">' + 标名(k) + (格提示[k] ? '<small>' + 格提示[k] + '<\/small>' : '') + '<span class=\"grow\"><\/span>' + 锁钮(路, true) + '<\/label>'\n    + '<textarea class=\"v\" rows=\"1\" maxlength=\"' + (全宽格.includes(k) ? 500 : 200) + '\" id=\"i-' + 路 + '\" data-k=\"' + 路 + '\" placeholder=\"' + 转义(占位[k] || '—') + '\">' + 转义(取(路)) + '<\/textarea>'\n    + 候选区(路) + '<\/div>';\n}\nfunction 段身世性格() {\n  return 画组('身世') + 画组('性格');\n}\n\nfunction 段技能() {\n  const j = 档.技能;\n  const 会的 = 乐器们(j);\n  const 选了 = x => (x === '零基础' ? j.乐器 === '零基础' : 会的.some(y => y.名 === x));\n  const 满乐器 = 会的.length >= 上限.乐器;\n  const 自定 = 会的.filter(x => !乐器表.includes(x.名));\n  const 特长们 = [...new Set(特长池.concat(j.特长))];\n  const 满 = j.特长.length >= 上限.特长;\n  return '<div class=\"oc-sec-h\"><b>技能<\/b><span>乐器 · 乐队 · 特长<\/span><\/div>'\n    + '<div class=\"oc-lab top\">乐器<small>可多选 · 上限 ' + 上限.乐器 + ' · 第一样是主乐器<\/small><\/div><div class=\"chips\">'\n    + 乐器表.map(x => 胶('乐器', x, 选了(x), x, !选了(x) && 满乐器 && x !== '零基础' ? ' disabled' : '')).join('')\n    + 自定.map(x => 胶('乐器', x.名, true)).join('') + (满乐器 ? '' : 自定义胶('乐器', null)) + '<\/div>'\n    + (界.自定义 === '乐器' ? 画自定义框('乐器', '自定义乐器', '两到六个字', null, false) : '')\n    + (会的.length ? '<div class=\"oc-lab\">水平<\/div>' + 会的.map((x, k) => '<div class=\"tier-one\"><span class=\"tier-name\">' + 转义(x.名) + (k === 0 ? '<small>主<\/small>' : '') + '<\/span>'\n      + '<div class=\"tier-wrap\"><div class=\"tier\">' + 水平名.map((n, i) => '<button type=\"button\" class=\"' + (i < x.水平 ? 'on' : '') + '\" data-act=\"水平\" data-v=\"' + (i + 1) + '\" data-i=\"' + k + '\" aria-label=\"' + 转义(x.名) + n + '\"><i><\/i><\/button>').join('')\n      + '<\/div><div class=\"tier-lab\">' + 水平名.map((n, i) => '<span class=\"' + (i + 1 === x.水平 ? 'on' : '') + '\">' + n + '<\/span>').join('') + '<\/div><\/div><\/div>').join('') : '')\n    + '<div class=\"oc-row\"><div><div class=\"oc-lab\">乐队<\/div><div class=\"chips\">' + 乐队选项.map(x => 胶('乐队', x, j.乐队 === x)).join('') + '<\/div>'\n    + (j.乐队 === '支援乐手' ? '<p class=\"oc-hint\">给别的乐队临时帮忙<\/p>' : '')\n    + (j.乐队 === '自组乐队' || j.乐队 === '招募中' ? '<div style=\"margin-top:8px\">' + 输入('技能.乐队名', { ph: j.乐队 === '自组乐队' ? '乐队名 · 必填' : '乐队名 · 选填', 长: 24, 名: '乐队名' }) + '<\/div>' : '') + '<\/div>'\n    + '<div><div class=\"oc-lab\">特长<small>上限 ' + 上限.特长 + '<\/small><span class=\"grow\"><\/span>' + ai钮('格', '技能.特长', '✦ 补全') + '<\/div><div class=\"chips\">'\n    + 特长们.map(x => { const on = j.特长.includes(x); return 胶('特长', x, on, x, !on && 满 ? ' disabled' : ''); }).join('') + 自定义胶('特长', null) + '<\/div>'\n    + (界.自定义 === '特长' ? 画自定义框('特长', '自定义特长', '两到四个字', null, false) : '')\n    + 候选区('技能.特长') + '<\/div><\/div>';\n}\n\nfunction 画人选() {\n  const 年 = 年份() || 2020;\n  const 工 = (工作地点() || {}).名;\n  const 先 = { 羽泽咖啡店: 'Afterglow', RiNG: 'MyGO!!!!!' }[工];\n  const 队们 = [...原作乐队].sort((a, b) => {\n    const 活 = x => (乐队状态(x, 年) === '活动中' ? 1 : 0);\n    return (活(b) - 活(a)) || ((b === 先) - (a === 先));\n  });\n  const 满 = 档.人际.length >= 上限.人际;\n  return '<div class=\"picker anim-unfold\" id=\"人选\">' + 队们.map(队 => {\n    const 活 = 乐队状态(队, 年) === '活动中';\n    return '<h6>' + 转义(队) + (活 ? '' : '<span>这一年还没登场<\/span>') + '<\/h6><div class=\"pk' + (活 ? '' : ' dim') + '\">'\n      + 名单.filter(x => x.队 === 队 && !x.人格).map(x => {   // 人格（墨缇丝）不单独选\n        const 已 = 档.人际.some(p => p.名 === x.名);\n        return '<button type=\"button\" class=\"' + (已 ? 'on' : '') + '\" data-act=\"加人\" data-v=\"' + 转义(x.名) + '\"' + (!活 || (!已 && 满) ? ' disabled' : '') + ' aria-pressed=\"' + 已 + '\">'\n          + 头像(x, 40) + '<b>' + 转义(x.名) + '<\/b><\/button>';\n      }).join('') + '<\/div>';\n  }).join('') + '<\/div>';\n}\n// 好感、信任的起点：一条 -100%～100% 的滑条（千分制 -1000～1000，一格 1%），竖线是这个关系的默认值（关系表）\nconst 滑位 = n => (Number(n) + 关系满分) / (2 * 关系满分);\nfunction 滑条(项, 值, 默) {\n  return '<div class=\"sld\"><span>' + 项 + '<\/span><div class=\"tr\" style=\"--p:' + 滑位(值) + ';--d:' + 滑位(默) + '\"><i class=\"mk\" aria-hidden=\"true\"><\/i>'\n    + '<input type=\"range\" min=\"' + -关系满分 + '\" max=\"' + 关系满分 + '\" step=\"10\" value=\"' + 值 + '\" data-rel=\"' + 项 + '\" aria-label=\"' + 项 + '起点\"><\/div><output>' + 百分(值) + '<\/output><\/div>';\n}\nfunction 段人际() {\n  const 选 = 档.人际;\n  const 当 = 选.find(p => p.名 === 界.当前人) || null;\n  const 荐 = 界.候选.人际 || [];\n  let 起点块 = '';\n  if (当) {\n    const 默 = 关系表[当.关系] || 关系表['一面之缘'];\n    const 挪过 = 当.好感 != null || 当.信任 != null;\n    起点块 = '<div class=\"oc-lab\">起点<small class=\"fill\" id=\"起点说明\">竖线 = ' + 转义(当.关系) + ' ' + 百分(默.好感) + (默.好感 !== 默.信任 ? ' / ' + 百分(默.信任) : '')\n      + ' <span class=\"nw\">· <span id=\"起点阶段\">' + 阶段之于(起点(当, '好感')) + '<\/span><\/span><\/small>'\n      + '<button type=\"button\" class=\"why-b\" data-act=\"照关系\"' + (挪过 ? '' : ' disabled') + '>照关系<\/button><\/div>'\n      + 滑条('好感', 起点(当, '好感'), 默.好感) + 滑条('信任', 起点(当, '信任'), 默.信任);\n  }\n  return '<div class=\"avs\">' + 选.map(p => {\n    const 人 = 查人(p.名) || {};\n    return '<div class=\"av' + (界.当前人 === p.名 ? ' on' : '') + '\"><button type=\"button\" class=\"avb\" data-act=\"选人\" data-v=\"' + 转义(p.名) + '\">' + 头像(人, 34)\n      + '<span><b>' + 转义(p.名) + '<\/b><small>' + 转义(人.队 || '') + '<\/small><\/span><span class=\"rel\">' + 转义(p.关系) + '<\/span><\/button>'\n      + '<button type=\"button\" class=\"del\" data-act=\"删人\" data-v=\"' + 转义(p.名) + '\" aria-label=\"去掉' + 转义(p.名) + '\">×<\/button><\/div>';\n  }).join('')\n    + (选.length < 上限.人际 ? '<button type=\"button\" class=\"av add\" data-act=\"开人选\" aria-expanded=\"' + 界.人选开 + '\"><span class=\"ph\" aria-hidden=\"true\"><\/span><span><b>' + (界.人选开 ? '收起' : '＋ 添加') + '<\/b><small>按年份、工作地点排序<\/small><\/span><\/button>' : '')\n    + '<\/div>'\n    + (荐.length ? '<div class=\"sugg stagger\">' + 荐.map((c, i) => '<button type=\"button\" data-act=\"采用人\" data-v=\"' + i + '\"><b>✦<\/b>' + 转义(c.名 + '（' + c.关系 + '）' + (c.一句 ? ' · ' + c.一句 : '')) + '<\/button>').join('')\n      + '<button type=\"button\" class=\"why\" data-act=\"清候选\" data-k=\"人际\">收起<\/button><\/div>' : '')\n    + (界.人选开 ? 画人选() : '')\n    + (当 ? '<div class=\"oc-lab\">与' + 转义(当.名) + '<\/div><div class=\"chips\">' + Object.keys(关系表).map(r => 胶('关系', r, 当.关系 === r)).join('') + '<\/div>'\n      + '<label class=\"in\" style=\"margin-top:8px\"><input data-k=\"人际一句\" value=\"' + 转义(当.一句 || '') + '\" maxlength=\"40\" placeholder=\"一句 · 例：CiRCLE 练习室常客，每次最早到\" aria-label=\"一句\"><\/label>'\n      + 起点块 : '')\n    + (选.length && !当 ? '<p class=\"oc-hint\">关系、一句、起点 · 在头像上改<\/p>' : '');\n}\n\nfunction 段物品() {\n  const w = 档.物品;\n  const 列 = 位 => '<div><h5>' + 位 + '<\/h5><ul>' + (w[位].length\n    ? w[位].map((x, i) => '<li><span>' + 转义(x) + '<\/span><button type=\"button\" data-act=\"删物\" data-v=\"' + 位 + '\" data-i=\"' + i + '\" aria-label=\"去掉' + 转义(x) + '\">×<\/button><\/li>').join('')\n    : '<li class=\"none\">—<\/li>') + '<\/ul><label class=\"in\"><input data-add=\"' + 位 + '\" maxlength=\"20\" enterkeyhint=\"done\" placeholder=\"＋ 添一样 · 回车\" aria-label=\"' + 位 + '添一样\"><\/label><\/div>';\n  return '<div class=\"oc-sec-h\"><b>物品<\/b><span>随身 · 家中 · 可空<\/span><\/div><div class=\"bag\">' + 列('随身') + 列('家中') + '<\/div>'\n    + '<div class=\"oc-row\" style=\"margin-top:10px\"><div><div class=\"oc-lab top\">持有金钱<\/div>' + 输入('物品.金钱', { ic: '¥', ph: '日元', 数: true, 长: 9, 名: '持有金钱' }) + '<\/div><\/div>'\n    + '<p class=\"oc-hint\">乐器、身份自动带上几样 · 可删 · 吃的喝的放不过夜<\/p>';\n}\n\nfunction 段第一层() {\n  const f = 档.第一层;\n  const 稿 = 界.候选.开场白;\n  return '<div class=\"oc-row\"><div><div class=\"oc-lab top\">人称<\/div><div class=\"chips\">' + ['第一人称', '第二人称', '第三人称'].map(x => 胶('人称', x, f.人称 === x)).join('') + '<\/div><\/div>'\n    + '<div><div class=\"oc-lab top\">篇幅<\/div><div class=\"chips\">' + ['短', '标准', '长'].map(x => 胶('篇幅', x, f.篇幅 === x)).join('') + '<\/div><\/div><\/div>'\n    + '<div class=\"oc-lab\">开场白<span class=\"grow\"><\/span>' + ai钮('开场白', '代写', '✦ 代写') + ai钮('开场白', '续写', '✦ 续写') + '<\/div>'\n    + '<textarea class=\"ta tall\" data-k=\"第一层.开场白\" maxlength=\"4000\" placeholder=\"开场白正文（可留空）\" aria-label=\"开场白\">' + 转义(f.开场白) + '<\/textarea>'\n    + (稿 ? '<div class=\"prose-sugg anim-unfold\"><p>' + 转义(稿.文) + '<\/p><div class=\"acts\"><button type=\"button\" class=\"btn ghost\" data-act=\"清候选\" data-k=\"开场白\">不用<\/button>'\n      + '<button type=\"button\" class=\"btn ghost\" data-act=\"采用开场白\">' + (稿.续写 ? '接在后面' : (f.开场白.trim() ? '替换' : '采用')) + '<\/button><\/div><\/div>' : '')\n    + '<label class=\"chk\"><input type=\"checkbox\" data-k=\"第一层.代写\"' + (f.代写 ? ' checked' : '') + '><span class=\"box\">✓<\/span>AI 代写（依据时间、地点、人际关系）<\/label>';\n}\n\n// 检查：一页一行写着填了什么；缺项那行点了跳到那一页那一格\nfunction 检查摘要(键) {\n  const b = 档.基本, j = 档.技能, f = 档.第一层, w = 档.物品;\n  const 地 = 开局地点();\n  return ({\n    世界: () => [当前时间串(档.时间.日期, 档.时间.时刻), 地 ? 地.全名 : '', 档.成立线.length ? '成立线 ' + 档.成立线.join('、') : ''].filter(Boolean).join(' · '),\n    主角: () => [b.姓名.trim(), b.性别, b.年龄, 身份串()].filter(Boolean).join(' · '),\n    身世性格: () => [档.性格.核心性格.trim(), '填了 ' + 填了几格(['身世', '性格'])].filter(Boolean).join(' · '),\n    技能物品: () => [乐器串(j), j.特长.length ? '特长 ' + j.特长.length + ' 项' : '',\n      '随身 ' + w.随身.length + ' 样'].filter(Boolean).join(' · '),\n    人际: () => (档.人际.length ? 档.人际.map(p => p.名).join('、') : '没加人'),\n    第一层: () => [f.代写 ? 'AI 代写' : f.开场白.trim().length + ' 字', f.人称, f.篇幅].join(' · '),\n  }[键] || (() => ''))();\n}\nfunction 段检查() {\n  const 查 = 查缺();\n  return '<div class=\"check\">' + 页表.filter(p => p.键 !== '检查').map(p => {\n    const 缺 = 页缺(查, p.键);\n    const 首 = 缺[0];\n    return '<button type=\"button\" class=\"it' + (缺.length ? ' bad' : '') + '\" data-act=\"跳\" data-v=\"' + p.键 + '\"' + (首 && 首.格 ? ' data-k=\"' + 首.格 + '\"' : '') + '>'\n      + '<i aria-hidden=\"true\">' + (缺.length ? '!' : '✓') + '<\/i><span class=\"grow\">' + 转义(p.键 + ' · '\n        + (缺.length ? '缺' + 缺.map(x => x.话.split(' · ').pop()).join('、') : 检查摘要(p.键))) + '<\/span><em>' + p.号 + (缺.length ? ' →' : '') + '<\/em><\/button>';\n  }).join('') + '<\/div>'\n    + 查.提示.map(x => '<p class=\"oc-hint\">' + 转义(x.话) + '<\/p>').join('')\n    + '<p class=\"oc-hint\">' + (查.缺.length ? '缺 ' + 查.缺.length + ' 项 · 补齐了才能开始' : '齐了 · 按「开始」写进数据库，发出 1 楼') + '<\/p>';\n}\n\nfunction 身份短() {\n  const s = 档.身份;\n  if (s.类 === '打工' || s.类 === '上班') return [(工作地点() || {}).名, s.职位.trim()].filter(Boolean).join(' ');\n  if (s.类 === '学生') return [学校名(), s.学校 === '复读' ? '' : s.年级].filter(Boolean).join(' ');\n  if (s.类 === '音乐人' || s.类 === '自由职业') return 职业名();\n  return s.其他.trim();\n}\nfunction 画底栏() {\n  const 查 = 查缺();\n  const b = 档.基本;\n  const 季 = (档.时间.时节 || '').split(' · ')[0];\n  const 摘 = [年份() ? 年份() + ' ' + 季 : '', 身份短(), 档.技能.乐器 && 档.技能.乐器 !== '零基础' ? 乐器们(档.技能).map(x => x.名).join('、') : ''].filter(Boolean).join(' · ');\n  const 缺库 = 库缺(), 没库 = !!缺库;\n  const 数 = 查.缺.length;\n  return '<div class=\"bar\" id=\"底栏\"><div class=\"sum\"><b>' + 转义(b.姓名.trim() || '未命名') + '<\/b>' + (b.罗马音.trim() ? '（' + 转义(b.罗马音.trim()) + '）' : '') + (摘 ? ' · ' + 转义(摘) : '') + '<\/div>'\n    + '<button type=\"button\" class=\"miss' + (数 ? '' : ' none') + '\" data-act=\"缺单\" aria-expanded=\"' + !!界.缺单开 + '\">' + (数 ? '缺 ' + 数 + ' 项' : 查.提示.length ? '提示 ' + 查.提示.length : '齐了') + '<\/button>'\n    + '<button type=\"button\" class=\"btn' + (没库 ? ' dim' : '') + '\" data-act=\"开始\"' + (没库 ? ' disabled title=\"' + (缺库.两份 ? '先把数据库只留一份' : 缺库.旧 ? '先把数据库更新到 1.2.4 或更新' : '先装龙血玄黄·数据库') + '\"' : '') + '>开始<\/button>'\n    + (界.缺单开 ? 画缺单(查) : '') + '<\/div>';\n}\nfunction 画缺单(查) {\n  const 行 = 查.缺.map(x => '<button type=\"button\" class=\"row\" data-act=\"跳\" data-v=\"' + 页之于(x.到) + '\" data-k=\"' + (x.格 || '') + '\"><span>' + 转义(x.话) + '<\/span><i>→<\/i><\/button>')\n    .concat(查.提示.map(x => '<button type=\"button\" class=\"row\" data-act=\"跳\" data-v=\"' + 页之于(x.到) + '\"><span class=\"soft\">' + 转义(x.话) + '<\/span><i>→<\/i><\/button>'));\n  return '<div class=\"pop stagger\" role=\"dialog\" aria-label=\"缺项\"><h6>' + (查.缺.length ? '缺项' : '都齐了') + '<\/h6>' + 行.join('') + '<\/div>';\n}\n\n// ── 屏：开局进度 ──\nconst 开局步骤名 = ['检查前置', '导入表格', '写初值', '锁格子', '发出第一层'];\nfunction 画进度() {\n  const k = (核态 && 核态.开局) || {};\n  const 出错 = k.状态 === '出错';\n  const 断了 = !出错 && k.状态 === '进行中' && !k.运行中 && !界.刚按开始;\n  let 完 = 0;\n  const 行 = 开局步骤名.map((n, i) => {\n    const 步 = i + 1;\n    let s = 界.进度[i] || '';\n    if (!s) s = 步 < (k.步 || 0) ? 'done' : 步 === k.步 ? (出错 ? 'bad' : 'on') : '';\n    if (s === 'done') 完 += 1;\n    return '<div class=\"' + s + '\"><i>' + (s === 'done' ? '✓' : s === 'bad' ? '!' : 步) + '<\/i>' + n\n      + (s === 'on' && 界.进度细 ? '<span class=\"sub\">' + 转义(界.进度细) + '<\/span>' : '') + '<\/div>';\n  }).join('');\n  return '<div class=\"oc anim-sheet\" id=\"卡\">' + 水印(档 && 档.基本.罗马音)\n    + '<div class=\"oc-head\