('anim-pick'); b.className = n.className; if (弹) b.classList.add('anim-pick'); }\n      if (b.innerHTML !== n.innerHTML) b.innerHTML = n.innerHTML;\n      if (n.hasAttribute('aria-current')) b.setAttribute('aria-current', 'page'); else b.removeAttribute('aria-current');\n    });\n  }\n  const 查el = document.getElementById('sec-检查');\n  if (查el) 查el.innerHTML = 段检查();\n}\nfunction 刷新水印() {\n  const el = document.getElementById('水印');\n  if (el) { el.innerHTML = 水印(档.基本.罗马音); 量水印(); }\n}\n// 水印字号不缩，真的超出卡片右缘才把尾巴化掉\nfunction 量水印() {\n  for (const wm of 根().querySelectorAll('.oc-wm')) {\n    const 卡 = wm.closest('.oc');\n    wm.classList.toggle('bleed', !!卡 && wm.offsetLeft + wm.scrollWidth > 卡.clientWidth - 8);\n  }\n}\nfunction 撑高(el) { el.style.height = 'auto'; el.style.height = el.scrollHeight + 'px'; }\n// 藏着的页量不出高度（scrollHeight 是 0），只撑看得见的；换页时再撑新的那一页\nfunction 撑看得见的() { for (const t of 根().querySelectorAll('textarea.v')) if (t.offsetParent) 撑高(t); }\nfunction 整理() {\n  画头像们(根());\n  撑看得见的();\n  量水印();\n  const 条 = document.getElementById('曲目单');\n  if (条) 目录条两头(条);\n}\nlet 提示钟 = 0;\nfunction 提示(话, 坏) {\n  界.提示 = { 话, 坏: !!坏 };\n  const el = document.getElementById('提示');\n  if (el) el.outerHTML = 画提示();\n  clearTimeout(提示钟);\n  提示钟 = setTimeout(() => { 界.提示 = null; const e2 = document.getElementById('提示'); if (e2) e2.innerHTML = ''; }, 4500);\n}\nfunction 变了(段) {\n  存草稿();\n  if (段) 重画段(段); else 刷新曲目单();\n  刷新底栏();\n  刷新计数();\n}\n\n// ── 在酒馆的聊天栏里滚动（0 楼的 iframe 自己不滚，滚的是外面的 #chat） ──\nfunction 聊天栏() { try { return window.parent.document.getElementById('chat'); } catch (e) { return null; } }\nfunction 滚到(el) {\n  const 框 = window.frameElement, 栏 = 聊天栏();\n  const 行为 = 少动() ? 'auto' : 'smooth';\n  if (!框 || !栏) { el.scrollIntoView({ behavior: 行为, block: 'start' }); return; }\n  const 距 = 框.getBoundingClientRect().top + el.getBoundingClientRect().top - 栏.getBoundingClientRect().top;\n  栏.scrollBy({ top: 距 - 14, behavior: 行为 });\n}\n// 换页以后，卡片顶要是滚出了视线，把聊天栏带回卡片顶；看得见就不动\nfunction 卡顶回来() {\n  const 卡 = document.getElementById('卡');\n  if (!卡) return;\n  const 框 = window.frameElement, 栏 = 聊天栏();\n  const 顶 = 框 && 栏 ? 框.getBoundingClientRect().top + 卡.getBoundingClientRect().top - 栏.getBoundingClientRect().top : 卡.getBoundingClientRect().top;\n  if (顶 < 0) 滚到(卡);\n}\n// 只横着滚曲目单横条自己，把这一页的按钮露出来。不能用 scrollIntoView：它连外面的聊天栏一起滚\nfunction 横着露出(条, b) {\n  if (条.scrollWidth - 条.clientWidth <= 1) return;\n  const 左 = b.offsetLeft - 条.offsetLeft, 右 = 左 + b.offsetWidth, 行为 = 少动() ? 'auto' : 'smooth';\n  if (左 < 条.scrollLeft) 条.scrollTo({ left: 左 - 12, behavior: 行为 });\n  else if (右 > 条.scrollLeft + 条.clientWidth) 条.scrollTo({ left: 右 - 条.clientWidth + 12, behavior: 行为 });\n}\n\n// ── 换页：不重画，换哪一页显示；往后翻新页从右边进，往前翻从左边进 ──\nfunction 换页(键, 不滚) {\n  const 旧 = 界.页;\n  if (!页表.some(p => p.键 === 键)) return;\n  界.页 = 键;\n  界.缺单开 = false;\n  const 序 = 页表.findIndex(p => p.键 === 键), 旧序 = 页表.findIndex(p => p.键 === 旧);\n  for (const el of 根().querySelectorAll('.pg')) {\n    const on = el.dataset.page === 键;\n    el.classList.toggle('on', on);\n    el.classList.remove('pg-in-r', 'pg-in-l');\n    if (on && 旧 !== 键 && !少动()) { void el.offsetWidth; el.classList.add(序 > 旧序 ? 'pg-in-r' : 'pg-in-l'); }\n  }\n  刷新曲目单();\n  刷新底栏();\n  看着配套();\n  撑看得见的();\n  const 条 = document.getElementById('曲目单');\n  const 钮 = 条 && 条.querySelector('.sl-it.on');\n  if (钮) 横着露出(条, 钮);\n  if (!不滚) 卡顶回来();\n}\n\n// ── 自动带上的东西 ──\nfunction 自动带(种, 值) {\n  for (const [名, 位] of ((自动物品[种] || {})[值] || [])) {\n    if (!档.物品.随身.includes(名) && !档.物品.家中.includes(名)) 档.物品[位].push(名);\n  }\n}\nfunction 同步日期年() {\n  const y = 年份();\n  if (!y || !档.时间.日期) return;\n  档.时间.日期 = String(y) + 档.时间.日期.slice(4);\n}\n// 换了年份：成立线只留那一年还能勾的\nfunction 修成立线() {\n  const 可 = 可选成立线(年份());\n  档.成立线 = 档.成立线.filter(队 => 可.includes(队));\n}\n// 只重画成立线那一组（自选年份正在输入时整段重画会丢焦点）；点的那颗补上选中回弹\nfunction 重画成立线(点的) {\n  const 组 = document.getElementById('成立线组');\n  if (!组) return;\n  组.innerHTML = 画成立线();\n  const 新 = 点的 != null && [...组.querySelectorAll('.chip')].find(c => c.dataset.v === 点的);\n  if (新) 新.classList.add('anim-pick');\n}\n// 年份、成立线变了：地点、打工地点按年份重列；这一年没有的原作的店空出来，提示一句。时间那一组由调用的人管\nfunction 年份变了() {\n  修成立线();\n  const 空 = 修可选();\n  存草稿();\n  重画段('地点');\n  重画段('基本信息');\n  if (界.人选开) 重画段('人际关系');\n  if (空.length) 提示(空.join('、') + ' 这一年没有，空出来了');\n}\n// 换身份类：上一类填的地方、职业对不上新的一类就空出来；职位是默认的那几个就跟着换\nconst 默认职位们 = ['新手工作人员', '店员', '职员'];\nfunction 定职位() {\n  const s = 档.身份;\n  if (s.类 !== '打工' && s.类 !== '上班') return;\n  const 地 = 工作地点();\n  const 该 = s.类 === '打工' && 地 && 地.演出 ? '新手工作人员' : 默认职位[s.类];\n  if (!s.职位.trim() || 默认职位们.includes(s.职位.trim())) s.职位 = 该;\n}\nfunction 换身份类(类) {\n  const s = 档.身份;\n  s.类 = 类;\n  if (类 === '打工' || 类 === '上班') {\n    const 在 = (类 === '打工' && 工作地点表.some(x => x.名 === s.工作地点)) || (通用身份[类] || []).some(x => x.名 === s.工作地点);\n    if (!在) s.工作地点 = '';\n    定职位();\n  }\n  if (类 === '音乐人' || 类 === '自由职业') {\n    const 别类 = 类 === '音乐人' ? '自由职业' : '音乐人';\n    if ((通用身份[别类] || []).some(x => x.名 === s.职业)) s.职业 = '';\n  }\n}\n\n// 点一样乐器：选上（第一样当主乐器，再选的进副乐器，上限 5）或去掉（去掉主乐器时下一样补上来）；零基础和别的互斥\nfunction 选乐器(名) {\n  const j = 档.技能;\n  if (!Array.isArray(j.副乐器)) j.副乐器 = [];\n  if (名 === '零基础') { j.乐器 = j.乐器 === '零基础' ? '' : '零基础'; j.副乐器 = []; return; }\n  const 会的 = 乐器们(j);\n  if (会的.some(x => x.名 === 名)) {\n    const 剩 = 会的.filter(x => x.名 !== 名);\n    j.乐器 = 剩.length ? 剩[0].名 : '';\n    if (剩.length) j.水平 = 剩[0].水平;\n    j.副乐器 = 剩.slice(1);\n    return;\n  }\n  if (会的.length >= 上限.乐器) return 提示('乐器上限 ' + 上限.乐器, true);\n  if (!会的.length) { j.乐器 = 名; j.水平 = j.水平 || 2; } else j.副乐器.push({ 名, 水平: 2 });\n  自动带('乐器', 名);\n}\n\n// ── 🎲 ──\nfunction 随时间() {\n  const 卡 = 随机取(年份卡);\n  Object.assign(档.时间, { 年: 卡.年, 自选: false, 时节: 随机取(时节表).名 });\n  档.时间.日期 = 随机日期(卡.年, 档.时间.时节);\n  档.时间.时刻 = 随机时刻();\n  档.时间.日期随机 = 档.时间.时刻随机 = true;\n}\nfunction 随地点() {\n  const 年 = 这年();\n  const 类们 = Object.keys(地点表).filter(类 => 地点表[类].some(x => 原作在(x, 年, 档.成立线)));\n  const 类 = 随机取(类们);\n  const 项 = 随机取(地点表[类].filter(x => 原作在(x, 年, 档.成立线)));\n  Object.assign(档.地点, { 类, 名: 项.名, 自定义: null });\n}\nfunction 全随机() {\n  let 数 = 0;\n  for (const 组 of ['外貌', '身世', '性格']) {\n    for (const k of 资料组[组]) {\n      const 路 = 组 + '.' + k;\n      if (!String(取(路) || '').trim() && !锁着(路) && 随机池[k]) { 设(路, 随机取(随机池[k])); 数 += 1; }\n    }\n  }\n  if (!档.住所.名 && !档.住所.自定义) { 档.住所.名 = 随机取(住所表).名; 数 += 1; }\n  if (!档.技能.乐器) { 档.技能.乐器 = 随机取(乐器表.slice(0, 5)); 自动带('乐器', 档.技能.乐器); 数 += 1; }\n  if (!档.技能.特长.length) { 档.技能.特长 = [随机取(特长池)]; 数 += 1; }\n  存草稿();\n  重画();\n  提示(数 ? '随机填上了 ' + 数 + ' 处；锁住的、名字没动' : '没有空着、没锁的格子');\n}\n\n// ── ✦ ──\nconst 组格 = {\n  基本: () => ['基本.罗马音', '基本.称呼'].concat(资料组.外貌.map(k => '外貌.' + k)),\n  外貌: () => 资料组.外貌.map(k => '外貌.' + k),\n  身世: () => 资料组.身世.map(k => '身世.' + k),\n  性格: () => 资料组.性格.map(k => '性格.' + k),\n  身世性格: () => 资料组.身世.map(k => '身世.' + k).concat(资料组.性格.map(k => '性格.' + k)),\n};\nconst 格说明 = {\n  '基本.罗马音': () => '姓名「' + 档.基本.姓名 + '」的日语罗马音，姓在前名在后，例如 Tokoyo Akari',\n  '基本.称呼': () => '别人平时怎么叫主角，两三个字',\n  '技能.特长': () => '主角会的一门特长，乐器以外的，两到四个字',\n  '身世.来历': () => '开局前这阵子主角在做什么、为什么在这一带',\n  '身世.知情人': () => '能证明主角身份的人',\n};\nconst 段之于 = 路 => (/^(基本|外貌)\\./.test(路) ? '基本信息' : /^(身世|性格)\\./.test(路) ? '身世性格' : 路 === '技能.特长' ? '技能' : '');\n\nasync function 帮填点(种, 目标) {\n  const 键 = 种 + ':' + 目标;\n  if (界.忙[键] || !核) return;\n  let 求, 段 = '', 空格们 = [];\n  if (种 === '格') {\n    const 名 = 目标.split('.').pop();\n    求 = { 类: '单格', 名: 名 === '特长' ? '特长' : 标名(名), 说明: (格说明[目标] || (() => ''))(), 限长: 目标 === '技能.特长' ? 6 : 24, 已填: 已填摘要() };\n    段 = 段之于(目标);\n  } else if (种 === '组') {\n    空格们 = (组格[目标] || (() => []))().filter(p => !String(取(p) || '').trim() && !锁着(p));\n    if (!空格们.length) { 提示('这一组没有空着、没锁的格子'); return; }\n    求 = { 类: '一组', 名们: 空格们.map(p => 标名(p.split('.').pop())), 已填: 已填摘要() };\n    段 = 目标 === '基本' || 目标 === '外貌' ? '基本信息' : '身世性格';\n  } else if (种 === '人际') {\n    求 = { 类: '人际', 年份: 年份() || 2020, 已选: 档.人际.map(p => p.名), 已填: 已填摘要() };\n    段 = '人际关系';\n  } else {\n    求 = { 类: '开场白', 人称: 档.第一层.人称, 篇幅: 档.第一层.篇幅, 续写: 目标 === '续写', 现有: 档.第一层.开场白, 已填: 已填摘要() };\n    段 = '第一层';\n  }\n  界.忙[键] = true;\n  重画段(段);\n  let r;\n  try { r = await 核.suggest(求); } catch (e) { r = { ok: false, 原因: String(e && e.message || e) }; }\n  界.忙[键] = false;\n  if (!r || !r.ok) {\n    重画段(段);\n    提示('✦ 没帮上：' + ((r && r.原因) || '没有回音'), true);\n    return;\n  }\n  if (种 === '格') 界.候选[目标] = r.候选;\n  else if (种 === '组') {\n    for (const p of 空格们) { const v = r.结果[标名(p.split('.').pop())]; if (v) 界.候选[p] = [v]; }\n    if (目标 === '外貌' || 目标 === '基本') 界.收起.外貌 = false;\n    if (目标 === '身世' || 目标 === '身世性格') 界.收起.身世 = false;\n    if (目标 === '性格' || 目标 === '身世性格') 界.收起.性格 = false;\n  } else if (种 === '人际') 界.候选.人际 = r.候选;\n  else 界.候选.开场白 = { 文: r.文, 续写: 目标 === '续写' };\n  重画段(段);\n}\n\n// ── 自定义（地点、住所、打工上班地点、学校、职业、特长、乐器） ──\nfunction 自定确定(域) {\n  const 名 = String((document.getElementById('自定名') || {}).value || '').trim();\n  const 片区 = String((document.getElementById('自定片') || {}).value || '');\n  if (域 === '乐器') {\n    if (!名) return 提示('乐器名空着', true);\n    选乐器(名);\n    界.自定义 = ''; 变了('技能'); return 重画段('物品');\n  }\n  if (域 === '特长') {\n    if (!名) return 提示('特长名空着', true);\n    if (!档.技能.特长.includes(名)) { if (档.技能.特长.length >= 上限.特长) return 提示('特长上限 ' + 上限.特长, true); 档.技能.特长.push(名); }\n    界.自定义 = ''; return 变了('技能');\n  }\n  if (域 === '职业') {\n    if (!名) return 提示('名称空着', true);\n    档.身份.职业 = 名;\n    界.自定义 = ''; return 变了('基本信息');\n  }\n  if (域 !== '住所' && !名) return 提示('名称空着', true);\n  if (!片区) return 提示('所属片区还没选', true);\n  const 值 = { 名, 片区, 全名: 名 };\n  if (域 === '地点') 档.地点.自定义 = 值;\n  else if (域 === '住所') 档.住所 = { 名: '', 自定义: 值 };\n  else if (域 === '工作') { 档.身份.工作自定义 = 值; 定职位(); }\n  else if (域 === '学校') { 档.身份.学校自定义 = 值; 档.身份.学校 = ''; }\n  界.自定义 = '';\n  变了(域 === '地点' ? '地点' : '基本信息');\n}\n\n// ── 草稿文件 ──\nfunction 导出草稿() {\n  const 文 = JSON.stringify({ 类: 'BanG 开局草稿', 版: 1, 档 }, null, 1);\n  try {\n    const a = document.createElement('a');\n    a.href = URL.createObjectURL(new Blob([文], { type: 'application/json' }));\n    a.download = 'BanG开局草稿_' + (档.基本.姓名 || '未命名') + '.json';\n    document.body.appendChild(a); a.click(); a.remove();\n    提示('草稿已导出');\n  } catch (e) {\n    提示('导出没成功：' + (e && e.message || e), true);\n  }\n}\nfunction 导入草稿(文件) {\n  const 读 = new FileReader();\n  读.onload = () => {\n    try {\n      const o = JSON.parse(String(读.result || ''));\n      if (!o || o.类 !== 'BanG 开局草稿' || !o.档) throw new Error('不是开局草稿');\n      档 = 合档(默认档(), o.档);\n      界.存档开 = false;\n      存草稿(); 重画(); 提示('草稿已导入');\n    } catch (e) { 提示('导入没成功：' + (e && e.message || e), true); }\n  };\n  读.readAsText(文件);\n}\n\n// ── 角色存档：存在核心那边（这台浏览器的 IndexedDB），换个聊天一键读入。核心的存档接口都是异步的 ──\nasync function 要存档们() {\n  try { 界.存档们 = 核 && typeof 核.profiles === 'function' ? await 核.profiles() : []; } catch (e) { 界.存档们 = []; }\n}\nasync function 存当前() {\n  if (!核 || typeof 核.saveProfile !== 'function') return 提示('总控没接上', true);\n  const 档案屏 = 界.屏 === '档案';\n  const 名 = 档案屏 ? 开局人名() : 档.基本.姓名.trim();\n  if (!名) return 提示('姓名空着，存不了', true);\n  if ((界.存档们 || []).some(x => x.名 === 名) && 界.存档待确认 !== '覆:' + 名) { 界.存档待确认 = '覆:' + 名; return 重画(); }\n  let r;\n  try { r = await (档案屏 ? 核.saveProfile() : 核.saveProfile(深拷(档))); } catch (e) { r = { ok: false, 原因: String(e && e.message || e) }; }\n  界.存档待确认 = '';\n  await 要存档们();\n  重画();\n  if (!r || !r.ok) return 提示('没存上：' + ((r && r.原因) || '没有回音'), true);\n  提示((r.覆盖 ? '覆盖了「' : '存好了「') + r.名 + '」');\n}\nasync function 读档(名) {\n  let 份 = null;\n  try { 份 = 核 ? await 核.profile(名) : null; } catch (e) { 份 = null; }\n  if (!份) return 提示('没找到这个存档', true);\n  // 这个人自己的几样换成存档里的；时间、地点、成立线、人际、第一层、锁照旧\n  档 = 合档(默认档(), Object.assign(深拷(档), 份));\n  const 空 = 修可选();\n  const 校 = 地点表['学校'].find(x => x.名 === 档.身份.学校);\n  if (校 && !学校可选(校)) { 档.身份.学校 = ''; 空.push(校.名); }\n  界.存档开 = false; 界.存档待确认 = ''; 界.候选 = {}; 界.自定义 = '';\n  存草稿();\n  重画();\n  提示('读入了「' + 名 + '」· 02 主角、03 身世性格、04 技能物品' + (空.length ? ' · ' + 空.join('、') + ' 这一年没有，空出来了' : ''));\n}\nasync function 删档(名) {\n  if (界.存档待确认 !== '删:' + 名) { 界.存档待确认 = '删:' + 名; return 重画(); }\n  let r;\n  try { r = await 核.deleteProfile(名); } catch (e) { r = { ok: false, 原因: String(e && e.message || e) }; }\n  界.存档待确认 = '';\n  await 要存档们();\n  重画();\n  提示(r && r.ok ? '删掉了「' + 名 + '」' : '没删掉：' + ((r && r.原因) || '没有回音'), !(r && r.ok));\n}\n\n// ── 开始 ──\nasync function 按开始() {\n  // 双击「开始」：折叠动画那 320ms 里再点一下会第二次开局，核心挡回来「已经在开局了」，屏上就弹一句假的出错\n  if (界.刚按开始) return;\n  const 查 = 查缺();\n  if (界.屏 === '须知') return 提示('先读开局须知 · 00 页最下面', true);\n  if (查.缺.length) { 界.缺单开 = true; 刷新底栏(); return; }\n  if (!核 || !核.alive()) return 提示('总控没接上，开始不了', true);\n  const 卡 = document.getElementById('卡');\n  界.刚按开始 = true;\n  界.进度 = [];\n  界.存档开 = false;\n  if (卡 && !少动()) { 卡.classList.add('anim-fold'); await new Promise(r => setTimeout(r, 320)); }\n  界.屏 = '进度';\n  核态 = Object.assign({}, 核态, { 开局: { 状态: '进行中', 步: 1, 运行中: true } });\n  重画();\n  存草稿();\n  const r = await 核.start(深拷(档));\n  界.刚按开始 = false;\n  if (!r || !r.ok) {\n    核态 = 核.state();\n    if (核态.状态 !== '开局中') { 界.屏 = 核态.须知已读 ? '表单' : '须知'; 重画(); }\n    else 重画();\n    提示('开局没走完：' + ((r && r.原因) || '没有回音'), true);\n  }\n}\n\n// ── 设置页：帮填接口 ──\n// 先把输入框里的存下（密钥空着就是不改），再做要做的：保存、测试连接、拉模型列表\nasync function 存接口(做) {\n  if (!核 || typeof 核.setApi !== 'function') return 提示('总控没接上', true);\n  const 取 = id => String((document.getElementById(id) || {}).value || '').trim();\n  const 改 = { 地址: 取('接口地址'), 模型: 取('接口模型') };\n  const 钥 = 取('接口密钥');\n  if (钥) 改.密钥 = 钥;\n  try { 核.setApi(改); } catch (x) { 界.接口话 = { 话: String(x && x.message || x), 坏: true }; return 重画(); }\n  核态 = 核.state();\n  // 有地址、没模型：存的时候顺手拉一次模型列表，拉到了从下拉里选，不用手抄模型名\n  if (做 === '保存' && 改.地址 && !改.模型) 做 = '拉列表';\n  if (做 === '保存') { 界.接口话 = { 话: 核态.帮填接口.配好 ? '存好了 · ' + 核态.帮填接口.模型 : '存好了 · 地址和模型都填了 ✦ 才能用' }; return 重画(); }\n  界.接口话 = { 话: 做 === '测试' ? '在连…' : '在拉…', 忙: true };\n  重画();\n  let r;\n  try { r = 做 === '测试' ? await 核