d;\n  if (!档.物品[位].includes(名)) 档.物品[位].push(名);\n  return true;\n}\n// 离开物品框时框里还有字，照样添上：很多手机输入法按回车时键码报 229（和拼字一样），这里不当回车认，\n// 浏览器照默认把焦点挪到下一个输入框，字就留在原来那一框里。添上以后「物品」这一组重画，焦点放回玩家去的那一框；\n// 去的是这一组里的按钮（× 去掉一样），不重画，等它自己重画，免得按钮没了点不上\nfunction 离开(e) {\n  const el = e.target;\n  if (!(el.dataset && el.dataset.add) || !el.value.trim()) return;\n  if (!添物(el)) return;\n  const 去 = e.relatedTarget, 组 = el.closest('[id^=\"sec-\"]');\n  if (去 && 组 && 组.contains(去) && !(去.dataset && (去.dataset.add || 去.dataset.k))) { 存草稿(); 刷新底栏(); 刷新计数(); return; }\n  const 去位 = 去 && 去.dataset && 去.dataset.add, 去格 = 去 && 去.dataset && 去.dataset.k;\n  变了('物品');\n  const 新 = 去位 ? 根().querySelector('[data-add=\"' + 去位 + '\"]') : 去格 ? 根().querySelector('[data-k=\"' + 去格 + '\"]') : null;\n  if (新) 新.focus();\n}\n\nfunction 键(e) {\n  const el = e.target;\n  // 输入法还在拼字时按的回车是「上屏」，不是「添一样」：不拦的话半截拼音会被当成物品加进去\n  if (e.isComposing || e.keyCode === 229) return;\n  if (e.key === 'Enter' && el.dataset && el.dataset.add) {\n    e.preventDefault();\n    const 位 = el.dataset.add;\n    if (!添物(el)) return;\n    变了('物品');\n    const 新 = 根().querySelector('[data-add=\"' + 位 + '\"]'); if (新) 新.focus();\n    return;\n  }\n  if (e.key === 'Enter' && el.id === '自定名') {\n    e.preventDefault();\n    const b = 根().querySelector('[data-act=\"自定确定\"]'); if (b) b.click();\n    return;\n  }\n  if ((e.key === 'Enter' || e.key === ' ') && el.getAttribute('role') === 'button') {\n    e.preventDefault();\n    el.click();\n    return;\n  }\n  if (e.key === 'Escape' && (界.缺单开 || 界.存档开)) { 界.缺单开 = false; 界.存档开 = false; 界.存档待确认 = ''; 重画(); }\n}\n\n// 窄屏的曲目单是一条藏了滚动条、只能横着滚的横条：手指滑没问题，鼠标的滚轮只会竖着滚、按住也拖不动。\n// 滚轮竖着滚换成横着走（到头就放行），鼠标按住能拖，拖过 5px 松手不算点了那一页；两头没滑完的挂 can-l / can-r 渐隐。\n// 宽卡上它是竖着的左栏，横向滚不动，这些都不起作用。卡片整块重画，所以挂在根上按 .sl-list 认。\nfunction 目录条两头(条) {\n  const 余 = 条.scrollWidth - 条.clientWidth;\n  条.classList.toggle('can-l', 余 > 1 && 条.scrollLeft > 1);\n  条.classList.toggle('can-r', 余 > 1 && 条.scrollLeft < 余 - 1);\n}\nfunction 绑目录条(r) {\n  