'Hello, Happy World!': 2018,\n  'Morfonica': 2019, 'RAISE A SUILEN': 2019, 'CRYCHIC': 2019, 'MyGO!!!!!': 2020, 'Ave Mujica': 2020,\n  '梦限大MewType': 2021, '妖精花束': 2021,\n};\n// 开局时直接算已解散的：CRYCHIC 2019 冬天的解散是「原作收尾」，2019 年开局不散，2020 年开局已经散了\nconst 乐队解散 = { 'CRYCHIC': 2020 };\n// CRYCHIC 不在名单里（成员后来分进 MyGO!!!!!、Ave Mujica），乐队表单独给它一行\nconst 旧乐队 = [{ 队: 'CRYCHIC', 成员: ['高松灯', '丰川祥子', '长崎爽世', '椎名立希', '若叶睦'] }];\nfunction 乐队状态(队, 年) {\n  const 起 = 乐队登场[队], 散 = 乐队解散[队];\n  if (!起 || Number(年) < 起) return '未成立';\n  return 散 && Number(年) >= 散 ? '已解散' : '活动中';\n}\n// 成立线：这支乐队从成立前开始。有成立经过的乐队才有这个开关；\n// 开局能勾的只有那一年已经在活动的（还没成立的，开局时自动打开，到成立那一年照常演）。\n// 梦限大MewType、妖精花束的成立剧情还在整理，先不给开关\nconst 成立线乐队 = Object.keys(乐队登场).filter(队 => 乐队登场[队] > 0 && 队 !== '梦限大MewType' && 队 !== '妖精花束');\nconst 可选成立线 = 年 => 成立线乐队.filter(队 => 乐队状态(队, 年) === '活动中');\n\nconst 年份卡 = [\n  { 年: 2018, 说: '登场：五支乐队' },\n  { 年: 2019, 说: '新增：Morfonica、RAISE A SUILEN · CRYCHIC 活动期' },\n  { 年: 2020, 说: '九支齐全 · CRYCHIC 已解散' },\n];\n\n// 时节分界：一年按这四个起点切开，任何一天都落在其中一季（1 月 1 日到春的起点之前算上一年的冬）。\n// 全卡一份：0 层卡按日期判时节、面板剧情页、游戏引擎的规则包都读 src/数据/时节.json（构建时嵌进来）\nconst 时节分界 = [{\"名\": \"春 · 新学期\", \"起\": \"03-26\"}, {\"名\": \"夏 · 暑假\", \"起\": \"07-21\"}, {\"名\": \"秋 · 文化祭\", \"起\": \"09-01\"}, {\"名\": \"冬 · 年末\", \"起\": \"12-01\"}];\n// 时节是快捷键：点一下在这一季里随机给一天一个时段（随机的范围都落在上面那一季里）\nconst 时节表 = [\n  { 名: '春 · 新学期', 起: '04-06', 止: '05-20' },\n  { 名: '夏 · 暑假', 起: '07-21', 止: '08-31' },\n  { 名: '秋 · 文化祭', 起: '09-20', 止: '11-10' },\n  { 名: '冬 · 年末', 起: '12-01', 止: '12-28' },\n];\nconst 时段表 = [\n  { 名: '早上', 起: '07:00', 止: '09:00' },\n  { 名: '白天', 起: '10:00', 止: '15:30' },\n  { 名: '傍晚', 起: '16:00', 止: '18:30' },\n  { 名: '晚上', 起: '19:00', 止: '22:00' },\n];\n\n// 地点。片区照表里的写法「区 · 街区」，区里没再分的只写区；位置取自面板地图的锚点。\n// 角色的家、同时是角色家里的店不列。原作的店只在它开着的年份出现（原作在()）：\n//   起 = 从哪一年起开着。CiRCLE 照卡里的时代锚定 2018 年已在；Galaxy、dub 2019 年剧情里有、2018 年没写，跟 CiRCLE 一起算；\n//   RiNG 2020 年剧情里 Poppin'Party 第一次在那儿演出，2018、2019 年的剧情里没有它（这三条是推出来的，常夜灯 2026-10-04 认可）。\n//   要成立线 = 那支乐队的成立线开着才有：SPACE 在 Poppin'Party 第一次登台以后不久闭店（世界书地点条目同一条规矩）。\n//   学校、街道不分年份。自选年早于 2018，原作的店都不列。\nconst 地点表 = {\n  'Live House': [\n    { 名: 'CiRCLE', 全名: 'LIVE HOUSE CiRCLE', 片区: '文京', 起: 2018 },\n    { 名: 'RiNG', 全名: 'LIVE HOUSE RiNG', 片区: '丰岛 · 池袋', 起: 2020 },\n    { 名: 'Galaxy', 全名: 'LIVE HOUSE Galaxy', 片区: '涩谷', 起: 2018 },\n    { 名: 'dub', 全名: 'dub MUSIC EXPERIMENT', 片区: '涩谷', 起: 2018 },\n    { 名: 'SPACE', 全名: 'LIVE HOUSE SPACE', 片区: '北区', 要成立线: \"Poppin'Party\" },\n  ],\n  '学校': [\n    { 名: '花咲川', 全名: '花咲川女子学园', 片区: '新宿', 女校: true },\n    { 名: '羽丘', 全名: '羽丘女子学园', 片区: '丰岛 · 池袋', 女校: true },\n    { 名: '月之森', 全名: '月之森女子学园', 片区: '丰岛 · 池袋', 女校: true },\n    { 名: '白八马', 全名: '神田白八马学院', 片区: '千代田' },\n    { 名: '庆鹏女大', 全名: '庆鹏女子大学', 片区: '多摩', 女校: true },\n    { 名: '四叶女大', 全名: '四叶女子大学', 片区: '多摩', 女校: true },\n  ],\n  '街道': [\n    { 名: '池袋站东口', 全名: '池袋站东口', 片区: '丰岛 · 池袋' },\n    { 名: '阳光城', 全名: '阳光城', 片区: '丰岛 · 池袋' },\n    { 名: '涩谷十字路口', 全名: '涩谷全向十字路口', 片区: '涩谷' },\n    { 名: '宫下公园', 全名: '宫下公园', 片区: '涩谷' },\n    { 名: '富士见坂', 全名: '富士见坂', 片区: '文京' },\n    { 名: '地藏通商店街', 全名: '江户川桥地藏通商店街', 片区: '文京' },\n  ],\n};\n// 原作的打工地点，年份规矩同上（羽泽咖啡店 2018 年的剧情里已有）。演出 = Live House：默认职位「新手工作人员」，带「Live House 是什么」那句提示\nconst 工作地点表 = [\n  { 名: 'CiRCLE', 全名: 'LIVE HOUSE CiRCLE', 片区: '文京', 起: 2018, 演出: true },\n  { 名: 'RiNG', 全名: 'LIVE HOUSE RiNG', 片区: '丰岛 · 池袋', 起: 2020, 演出: true },\n  { 名: 'Galaxy', 全名: 'LIVE HOUSE Galaxy', 片区: '涩谷', 起: 2018, 演出: true },\n  { 名: '羽泽咖啡店', 全名: '羽泽咖啡店', 片区: '文京', 起: 2018 },\n  { 名: 'SPACE', 全名: 'LIVE HOUSE SPACE', 片区: '北区', 要成立线: \"Poppin'Party\", 演出: true },\n];\n// 原作的地方这一年有没有（地点表、工作地点表里的一项）\nfunction 原作在(项, 年, 成立线) {\n  if (!项) return false;\n  if (项.要成立线) return (成立线 || []).includes(项.要成立线);\n  return !项.起 || (Number(年) || 0) >= 项.起;\n}\n\n// 身份六类。学生、打工先列原作的地方（学校、工作地点表），再列下面这些哪一年都有的通用身份；每类都能自定义。\n// 通用身份带「起」的，那一年以前不列：便利店 1974（日本第一家 7-Eleven 开在江东区丰洲）、家庭餐厅 1970（云雀一号店）、\n// 广播电台 1925（东京放送局开播）、视频主播 2006（ニコニコ動画上线）。通用身份没有地图坐标，不落据点。\nconst 身份类表 = ['学生', '打工', '上班', '音乐人', '自由职业', '其他'];\nconst 通用身份 = {\n  学生: [{ 名: '普通高中' }, { 名: '普通大学' }, { 名: '音乐大学' }, { 名: '专门学校' }, { 名: '复读' }],\n  打工: [{ 名: '咖啡店' }, { 名: '便利店', 起: 1974 }, { 名: '家庭餐厅', 起: 1970 }, { 名: '唱片行' }, { 名: '乐器行' }, { 名: '书店' }, { 名: '面包店' }, { 名: '花店' }],\n  上班: [{ 名: '普通公司' }, { 名: '唱片公司' }, { 名: '经纪公司' }, { 名: '音乐杂志社' }, { 名: '录音室' }, { 名: '广播电台', 起: 1925 }, { 名: '设计事务所' }],\n  音乐人: [{ 名: '录音乐手' }, { 名: '作曲' }, { 名: '编曲' }, { 名: '音响师' }, { 名: '街头艺人' }, { 名: '乐器修理' }],\n  自由职业: [{ 名: '插画师' }, { 名: '摄影师' }, { 名: '写手' }, { 名: '翻译' }, { 名: '视频主播', 起: 2006 }],\n  其他: [{ 名: '待业' }, { 名: '家里帮忙' }, { 名: '来东京旅居' }],\n};\nconst 通用在 = (项, 年) => !!项 && (!项.起 || (Number(年) || 0) >= 项.起);\nconst 默认职位 = { 打工: '店员', 上班: '职员' };\n// 旧草稿、旧开局档里的「工作人员」就是现在的「打工」\nconst 身份类名 = 类 => (类 === '工作人员' ? '打工' : 类);\nconst 住所表 = [\n  { 名: '池袋', 片区: '丰岛 · 池袋' },\n  { 名: '文京', 片区: '文京' },\n  { 名: '新宿', 片区: '新宿' },\n  { 名: '涩谷', 片区: '涩谷' },\n];\n// 自定义地点、住处要选在哪一片：钉子落在那一片的中间，画成虚线圈\nconst 片区表 = ['丰岛 · 池袋', '文京', '新宿', '涩谷', '千代田', '北区', '港区', '中央', '江东', '世田谷', '多摩'];\n// 买房、租房的价钱（2020 年东京，日元）。两居按不动产经济研究所 2020 年东京 23 区新建公寓均价 7,712 万定，其余按比例；\n// 「租」是单间每月房租，两居、独栋的房租按买价同比例放大；租房首付算三个月（押金、礼金、首月）。片区对不上哪一档的按「23 区其他」\nconst 房价表 = [\n  { 档: '都心', 片区: ['千代田', '中央', '港区'], 单间: 35000000, 两居: 110000000, 独栋: 140000000, 租: 120000 },\n  { 档: '多摩', 片区: ['多摩'], 单间: 15000000, 两居: 48000000, 独栋: 55000000, 租: 60000 },\n  { 档: '23 区其他', 片区: [], 单间: 25000000, 两居: 77000000, 独栋: 90000000, 租: 90000 },\n];\nconst 年级表 = ['高一', '高二', '高三', '大一', '大二', '大三', '大四'];\n\n// 好感、信任是千分制：-1000～1000 的整数，屏上显示成百分比（450 → 45%，-120 → -12%）。负的是讨厌、不信任\nconst 关系满分 = 1000;\nconst 百分 = n => { const v = Math.round(Number(n)) / 10; return (Number.isInteger(v) ? String(v) : v.toFixed(1)) + '%'; };\n\n// 七种关系 → 重要角色表的初值（千分制）。青梅竹马高，一面之缘低。\nconst 关系表 = {\n  '同班': { 阶段: '普通朋友', 好感: 450, 信任: 450 },\n  '邻居': { 阶段: '普通朋友', 好感: 500, 信任: 500 },\n  '青梅竹马': { 阶段: '在意的人', 好感: 700, 信任: 700 },\n  '打工同事': { 阶段: '普通朋友', 好感: 500, 信任: 500 },\n  '熟客': { 阶段: '普通朋友', 好感: 450, 信任: 400 },\n  '网友': { 阶段: '普通朋友', 好感: 450, 信任: 350 },\n  '一面之缘': { 阶段: '陌生人', 好感: 300, 信任: 300 },\n};\n\n// 关系阶段：和手账本同一套七档（常夜灯 2026-10-05 定）。前五档跟好感走，游戏引擎记账写回好感时一并写；\n// 情侣、夫妻要正文里真的确定了关系、填表 AI 写上才算，好感跌破在意的人那条线就退回按好感算的那一档。好感为负是讨厌的人\nconst 关系阶段们 = ['讨厌的人', '陌生人', '普通朋友', '在意的人', '挚友', '情侣', '夫妻'];\nconst 阶段界 = [[750, '挚友'], [550, '在意的人'], [350, '普通朋友'], [0, '陌生人']];   // 千分制；低于 0 是讨厌的人\nconst 剧情阶段 = ['情侣', '夫妻'];\nconst 剧情阶段线 = 550;   // 情侣、夫妻写得上、留得住的最低好感：吵一架掉几个点不退回去\nfunction 阶段之于(好感, 当前) {\n  const n = Number(好感);\n  if (!isFinite(n)) return '';\n  if (剧情阶段.includes(当前) && n >= 剧情阶段线) return 当前;\n  return (阶段界.find(([下]) => n >= 下) || [0, '讨厌的人'])[1];\n}\n\n// 乐器能选几样（上限 5），每样各有一个水平；第一样是主乐器（技能.乐器、技能.水平），其余在 技能.副乐器 [{名, 水平}]\nconst 乐器表 = ['吉他', '贝斯', '鼓', '键盘', '主唱', '钢琴', '木吉他', '合成器', '小提琴', '大提琴', '长笛', '萨克斯', '小号', '三味线', 'DJ', '零基础'];\n// 一个人会的全部乐器：[{名, 水平}]，主乐器在前；零基础、没选回空\nfunction 乐器们(j) {\n  j = j || {};\n  if (!j.乐器 || j.乐器 === '零基础') return [];\n  return [{ 名: j.乐器, 水平: Number(j.水平) || 1 }].concat((Array.isArray(j.副乐器) ? j.副乐器 : []).filter(x => x && x.名 && x.名 !== j.乐器)\n    .map(x => ({ 名: String(x.名), 水平: Number(x.水平) || 1 })));\n}\n// 「吉他（能合奏）、钢琴（弹整首）」\nconst 乐器串 = j => (j && j.乐器 === '零基础' ? '零基础' : 乐器们(j).map(x => x.名 + '（' + 水平名[x.水平 - 1] + '）').join('、'));\nconst 水平名 = ['摸索', '弹整首', '能合奏', '能登台', '能主导'];\nconst 乐队选项 = ['无', '招募中', '自组乐队', '支援乐手'];\nconst 特长池 = ['做饭', '画画', '跑步', '外语', '摄影', '游泳', '书法', '手工', '下棋', '编程'];\nconst 上限 = { 特长: 5, 人际: 5, 乐器: 5 };\n\n// 选了乐器、身份、学校，自动带上的东西（玩家能删）\nconst 自动物品 = {\n  乐器: {\n    '吉他': [['吉他', '家中'], ['拨片', '随身']],\n    '贝斯': [['贝斯', '家中'], ['拨片', '随身']],\n    '鼓': [['鼓棒', '随身']],\n    '键盘': [['电子琴', '家中']],\n    '主唱': [['润喉糖', '随身']],\n    '小提琴': [['小提琴', '家中'], ['松香', '随身']],\n    'DJ': [['DJ 控制器', '家中'], ['监听耳机', '随身']],\n    '木吉他': [['木吉他', '家中'], ['拨片', '随身']],\n    '合成器': [['合成器', '家中']],\n    '大提琴': [['大提琴', '家中'], ['松香', '随身']],\n    '长笛': [['长笛', '随身']],\n    '萨克斯': [['萨克斯', '家中'], ['簧片', '随身']],\n    '小号': [['小号', '家中']],\n    '三味线': [['三味线', '家中']],\n  },\n  身份: { '打工': [['员工证', '随身']], '上班': [['工作证', '随身']], '学生': [['学生证', '随身'], ['书包', '随身']] },\n};\n\n// 物品的类别（物品表「类别」一列）：类别定了东西怎么没的——吃的喝的放不过夜，消耗品用完就没，票过期就没，其余一直在。\n// 开局卡里玩家随手写的东西按名字猜一类（上面自动带的几样都猜得对），猜不出记「其他」；之后填表 AI 照表里的说明自己分。\n// 按顺序试，先中先得：「润喉糖」要落在消耗品、不落在食物，「吉他弦」要落在消耗品、不落在器材。\nconst 物品类别 = ['常备', '器材', '食物', '消耗品', '票券', '纪念品', '其他'];\nconst 物品猜类 = [\n  ['票券', /票|券/],\n  ['消耗品', /弦|电池|药|创可贴|绷带|纸巾|湿巾|润喉|松香|口罩|胶带|暖宝宝/],\n  ['食物', /便当|饭团|面包|三明治|蛋糕|饼干|巧克力|零食|布丁|点心|甜点|水果|果汁|牛奶|咖啡|奶茶|饮料|可乐|汽水|矿泉水|茶$|饭$|糖$/],\n  ['器材', /吉他|贝斯|鼓|琴|拨片|谱|效果器|调音器|节拍器|音箱|耳返|话筒|麦克风|变调夹|背带|线材|控制器|打碟/],\n  ['常备', /手机|钱包|钥匙|证$|卡$|耳机|书包|挎包|背包|伞/],\n  ['纪念品', /礼物|纪念|徽章|照片|挂件|吊坠|明信片|信$/],\n];\n\n// 🎲 随机只在这些里挑，不花模型；名字不随机。\nconst 随机池 = {\n  身高体型: ['170cm，偏瘦', '176cm，肩宽', '168cm，结实', '173cm，匀称', '181cm，高瘦'],\n  发型发色: ['黑色短发', '深棕色碎发，刘海略长', '黑发，后脑有一撮翘毛', '栗色短发，两侧推短', '黑色微卷短发'],\n  瞳色: ['深棕', '黑', '浅褐', '灰黑'],\n  常穿服装: ['灰色连帽衫，牛仔裤', '白衬衫，深色长裤', '黑色夹克，运动鞋', '格子衬衫，工装裤', '宽松卫衣，帆布鞋'],\n  外貌特征: ['左手指腹有茧', '右眉上有一道小疤', '笑起来有酒窝', '总戴一只旧手表', '耳后有颗痣'],\n  出身: ['本地人，在丰岛长大', '从地方城市搬来东京', '在文京长大', '从大阪搬过来'],\n  家庭: ['父母上班，独生子', '父母经营洗衣店，弟弟念初中', '和奶奶一起住', '父亲常驻外地，和母亲两个人住', '姐姐在念大学'],\n  成长经历: ['初中在轻音部待过一年，后来废部', '一直在社团打杂，没上过台', '小时候学过几年钢琴', '跟着表哥听摇滚长大'],\n  来历: ['春假起在 CiRCLE 打工，刚满一周', '看了一场演出以后来应聘', '亲戚介绍来的兼职', '为了攒钱买琴出来打工'],\n  知情人: ['CiRCLE 的月岛麻里奈', '同班的几个朋友', '家里人', '打工的前辈'],\n  核心性格: ['嘴硬心软，怕麻烦', '老实，认死理', '爱开玩笑，关键时候靠得住', '慢热，不擅长拒绝别人', '冷静，话少', '好奇心重，做事三分钟热度'],\n  社交方式: ['对生人冷淡，熟人面前话多', '跟谁都能聊两句', '习惯先听别人说', '话不多，但记得别人的事'],\n  说话习惯: ['句尾常带「吧」', '说话直，不绕弯子', '紧张时会重复对方的话', '爱用反问'],\n  日常习惯: ['熬夜，早上起不来', '每天早上跑步', '随身带耳机', '记账记得很细'],\n  喜欢: ['老唱片', '便利店的炸鸡', '下雨天', '猫'],\n  讨厌: ['排队', '香菜', '被催', '闷热的天'],\n  弱点软肋: ['怕被人看不起', '不会拒绝朋友', '一紧张就手抖', '对家里的事很敏感'],\n  反差: ['平时胆小，护人的时候豁得出去', '看着冷淡，其实很会照顾人', '长得凶，做饭很好吃'],\n  生理特点: ['体力差，容易晕车', '怕冷', '酒量为零', '视力不好，偶尔戴眼镜'],\n  心理状态: ['表面乐观，心里没底', '刚换环境，有点紧张', '想找件能坚持下去的事', '最近睡不好'],\n};\n\n// 资料卡的三组：格名照《玩家角色资料》，写进主角档案表的同名列\nconst 资料组 = {\n  外貌: ['身高体型', '发型发色', '瞳色', '常穿服装', '外貌特征'],\n  身世: ['出身', '家庭', '成长经历', '来历', '知情人', '与主线关系'],\n  性格: ['核心性格', '社交方式', '说话习惯', '日常习惯', '喜欢', '讨厌', '弱点软肋', '反差', '生理特点', '心理状态'],\n};\nconst 主线默认 = '无特殊关联，普通人';\n\n// ── 共用/工具.js ──\n// 小工具：转义、日期、随机。0 层卡、回执、核心共用。\n// 注意：两块 html 是经卡里的正则 → markdown 代码块 → 酒馆助手 iframe 上屏的，路上会：\n//   · 把「美元号接数字」当成捕获组、把双花括号当成酒馆宏换掉；\n//   · 把源码里写成字面的 HTML 实体（和号接 amp、quot 那种）解码成字符本身——字符串里的实体一变回引号，脚本就编译不过。\n// 这几样在源码里都不能出现（构建.py 会查），转义表因此用字符编码现拼。\n\nconst 转义 = s => String(s == null ? '' : s).replace(/[&<>\"']/g, c => '&#' + c.charCodeAt(0) + ';');\n\nconst 周几名 = ['周日', '周一', '周二', '周三', '周四', '周五', '周六'];\nfunction 周几(日期) {\n  const m = /^(\\d{4})-(\\d{2})-(\\d{2})$/.exec(String(日期 || ''));\n  if (!m) return '';\n  const d = new Date(Number(m[1]), Number(m[2]) - 1, Number(m[3]));\n  return isNaN(d) ? '' : 周几名[d.getDay()];\n}\nconst 补零 = n => String(n).padStart(2, '0');\nfunction 时刻转分(t) { const m = /^(\\d{1,2}):(\\d{2})$/.exec(String(t || '')); return m ? Number(m[1]) * 60 + Number(m[2]) : NaN; }\nfunction 分转时刻(n) { return 补零(Math.floor(n / 60) % 24) + ':' + 补零(n % 60); }\nfunction 时段名(时刻) {\n  const n = 时刻转分(时刻);\n  if (isNaN(n)) return '';\n  if (n < 5 * 60) return '深夜';\n  if (n < 10 * 60) return '早上';\n  if (n < 16 * 60) return '白天';\n  if (n < 19 * 60) return '傍晚';\n  return '晚上';\n}\n// 「2020-04-17 周五 19:40」，全局数据表·当前时间的写法\nfunction 当前时间串(日期, 时刻) {\n  return [日期, 周几(日期), 时刻].filter(Boolean).join(' ');\n}\n\nconst 随机取 = 列 => 列[Math.floor(Math.random() * 列.length)];\nfunction 随机日期(年, 时节) {\n  const 季 = 时节表.find(x => x.名 === 时节) || 时节表[0];\n  const 起 = new Date(Number(年), Number(季.起.slice(0, 2)) - 1, Number(季.起.slice(3)));\n  const 止 = new Date(Number(年), Number(季.止.slice(0, 2)) - 1, Number(季.止.slice(3)));\n  const d = new Date(起.getTime() + Math.floor(Math.random() * ((止 - 起) / 864e5 + 1)) * 864e5);\n  return d.getFullYear() + '-' + 补零(d.getMonth() + 1) + '-' + 补零(d.getDate());\n}\nfunction 随机时刻() {\n  const 段 = 随机取(时段表);\n  const a = 时刻转分(段.起), b = 时刻转分(段.止);\n  return 分转时刻(a + Math.floor(Math.random() * ((b - a) / 10 + 1)) * 10);\n}\n// 日期落在哪个时节（自己改了日期以后，时节跟着对上）\n// 片区写法不统一：0 层卡写「丰岛 · 池袋」「文京」，地图点位写「丰岛・池袋」「东京・文京」。去掉点和空格再比，对上结尾就算同一片\nfunction 片区键(片区) { return String(片区 || '').replace(/[\\s·・]/g, ''); }\nfunction 同片区(甲, 乙) { const a = 片区键(甲), b = 片区键(乙); return !!a && !!b && (a === b || a.endsWith(b) || b.endsWith(a)); }\n// 房价：方式「买」回买价，「租」回每月房租；户型单间、两居、独栋\nfunction 房价(片区, 户型, 方式) {\n  const 档 = 房价表.find(x => x.片区.some(p => 同片区(片区, p))) || 房价表[房价表.length - 1];\n  const 买 = 档[户型];\n  if (!买) return 0;\n  return 方式 === '租' ? Math.round(档.租 * 买 / 档.单间 / 1000) * 1000 : 买;\n}\nfunction 日期的时节(日期) {\n  const md = String(日期 || '').slice(5, 10);\n  if (!/^\\d{2}-\\d{2}$/.test(md)) return '';\n  // 照时节分界切：起点不晚于这一天的最后一季；比第一季还早（1 月到春的起点前）算上一年的冬\n  let 季 = 时节分界[时节分界.length - 1];\n  for (const x of 时节分界) if (x.起 <= md) 季 = x;\n  return 季.名;\n}\n\nconst 查人 = 名 => 名单.find(x => x.名 === 名) || null;\n// 艺名、别名（角色条目的触发词，只收指向一个人的，构建时生成）、带括号的写法归到规范名；归不上返回空\nfunction 归名(名) {\n  const s = String(名 || '').trim();\n  if (!s) return '';\n  const 认 = t => {\n    const 原 = String(t || '').trim(), k = 原.toLowerCase();\n    if (!k) return '';\n    const x = 名单.find(p => p.名 === 原)\n      || 名单.find(p => (p.艺名 && p.艺名.toLowerCase() === k) || (p.别名 || []).some(a => a.toLowerCase() === k));\n    return x ? x.名 : '';\n  };\n  const 直 = 认(s);\n  if (直) return 直;\n  // 「香澄（户山香澄）」「和奏瑞依（LAYER）」：去掉括号认一次，再认括号里的\n  const 外 = s.replace(/[（(][^）)]*[）)]/g, '').trim();\n  const 里 = (/[（(]([^）)]+)[）)]/.exec(s) || [])[1] || '';\n  return (外 && 外 !== s && 认(外)) || (里 && 认(里)) || '';\n}\n// 物品按名字猜一类（规则在 数据.js 的 物品猜类），猜不出是「其他」\nfunction 猜物品类(名) {\n  const s = String(名 || '').trim();\n  for (const [类, 规则] of 物品猜类) if (规则.test(s)) return 类;\n  return '其他';\n}\nconst 截 = (s, n) => { s = String(s || ''); return s.length > n ? s.slice(0, n) : s; };\nconst 深拷 = o => JSON.parse(JSON.stringify(o));\n\n// ── 共用/头像.js ──\n// 小头像：原图七八百像素，<img> 直接缩到二三十、四十像素时，浏览器的缩放会出锯齿和网点。\n// 改画在 canvas 上：按屏幕倍率算目标像素，先对半缩几次，最后一步用高质量插值缩到位、居中裁成正方形（和面板的头像一个做法）。\n// 同一张图、同一尺寸只缩一次，记在缓存里；屏重画时直接贴上去，不重新加载、不闪。\n// 用法：拼 HTML 时写 头像画布(地址, 尺寸)，塞进页面以后调 画头像们(容器)。\nconst 头像缓存 = new Map();   // 地址@像素 → 缩好的 canvas\nconst 头像等待 = new Map();   // 地址@像素 → 还在加载时等着贴的 canvas 们\n\nfunction 头像画布(地址, 尺寸) {\n  return '<canvas class=\"ava\" data-ava=\"' + 转义(地址) + '\" data-size=\"' + 尺寸 + '\" width=\"' + 尺寸 + '\" height=\"' + 尺寸 + '\" aria-hidden=\"true\"><\/canvas>';\n}\n\nfunction 缩头像(图, 像素) {\n  let 源 = 图, w = 图.naturalWidth, h = 图.naturalHeight;\n  // 对半缩到离目标两倍以内，每一步都只缩一半，插值不丢细节\n  while (Math.min(w, h) / 2 >= 像素 * 2) {\n    const c = document.createElement('canvas');\n    c.width = Math.round(w / 2); c.height = Math.round(h / 2);\n    const x = c.getContext('2d');\n    x.imageSmoothingEnabled = true;\n    if ('imageSmoothingQuality' in x) x.imageSmoothingQuality = 'high';\n    x.drawImage(源, 0, 0, c.width, c.height);\n    源 = c; w = c.width; h = c.height;\n  }\n  const 出 = document.createElement('canvas');\n  出.width = 像素; 出.height = 像素;\n  const x = 出.getContext('2d');\n  x.imageSmoothingEnabled = true;\n  if ('imageSmoothingQuality' in x) x.imageSmoothingQuality = 'high';\n  const 比 = Math.max(像素 / w, 像素 / h);\n  x.drawImage(源, (像素 - w * 比) / 2, (像素 - h * 比) / 2, w * 比, h * 比);\n  return 出;\n}\n\nfunction 贴头像(cv, 源) {\n  const x = cv.getContext('2d');\n  x.clearRect(0, 0, cv.width, cv.height);\n  x.drawImage(源, 0, 0);\n}\n\nfunction 画头像们(容器) {\n  const 倍 = Math.max(1, window.devicePixelRatio || 1);\n  (容器 || document).querySelectorAll('canvas[data-ava]').forEach(cv => {\n    if (cv.dataset.drawn) return;\n    cv.dataset.drawn = '1';\n    const 像素 = Math.max(1, Math.round((Number(cv.dataset.size) || 40) * 倍));\n    const 地址 = cv.dataset.ava, 键 = 地址 + '@' + 像素;\n    cv.width = 像素; cv.height = 像素;\n    const 有 = 头像缓存.get(键);\n    if (有) return 贴头像(cv, 有);\n    const 等着 = 头像等待.get(键);\n    if (等着) return 等着.push(cv);\n    头像等待.set(键, [cv]);\n    const 图 = new Image();\n    图.referrerPolicy = 'no-referrer';\n    图.onload = () => {\n      const 们 = 头像等待.get(键) || [];\n      头像等待.delete(键);\n      if (!图.naturalWidth) return;\n      const 好 = 缩头像(图, 像素);\n      头像缓存.set(键, 好);\n      们.forEach(c => { if (c.isConnected) 贴头像(c, 好); });\n    };\n    图.onerror = () => { 头像等待.delete(键); };\n    图.src = 地址;\n  });\n}\n\n// ── 回执/回执.js ──\n// 1 楼开局回执：读本楼原文里的 <开局>…<\/开局><开场白>…<\/开场白>，画成一张卡。\n// 模型、数据库、手账本读的都是原文；卡上这条正则只在显示时换成这张卡（仅格式显示）。\n\nfunction 本楼原文() {\n  try {\n    const id = getCurrentMessageId();\n    const 楼 = getChatMessages(id)[0];\n    return 楼 ? String(楼.message || '') : '';\n  } catch (e) {\n    return '';\n  }\n}\n\nfunction 解析(文) {\n  const 开 = /<开局>([\\s\\S]*?)<\\/开局>/.exec(文);\n  if (!开) return null;\n  const 项 = {};\n  for (const 行 of 开[1].split('\\n')) {\n    const m = /^\\s*([^：:]+)[：:]\\s*(.*)$/.exec(行);\n    if (m) 项[m[1].trim()] = m[2].trim();\n  }\n  const 白 = /<开场白>([\\s\\S]*?)<\\/开场白>/.exec(文);\n  return { 项, 开场白: 白 ? 白[1].trim() : '' };\n}\n\nfunction 画(文) {\n  const d = 解析(文);\n  if (!d) return '<div class=\"rcpt anim-card\"><div class=\"raw\">' + 转义(文) + '<\/div><\/div>';\n  const 项 = d.项;\n  const 主 = /^([^（(，,]+)(?:[（(]([^）)]*)[）)])?[，,]?(.*)$/.exec(项['主角'] || '') || [];\n  const 名 = (主[1] || '').trim();\n  const 罗马 = (主[2] || '').trim();\n  const 余 = (主[3] || '').split(/[，,]/).map(s => s.trim()).filter(Boolean);\n  const 身份 = 余.length >= 3 ? 余.slice(2).join('，') : '';\n  const 时 = /^(\\d{4})-(\\d{2})-(\\d{2})\\s*(周.)?\\s*(\\d{1,2}:\\d{2})?(?:（([^）]*)）)?/.exec(项['时间'] || '');\n  const 时间串 = 时 ? [时[1] + ' 年 ' + Number(时[2]) + ' 月 ' + Number(时[3]) + ' 日', 时[4], 时[5]].filter(Boolean).join(' · ') : (项['时间'] || '');\n  const 季 = 时 && 时[6] ? 时[6] : '';\n  const 地 = String(项['地点'] || '').split('/').map(s => s.trim()).filter(Boolean).pop() || '';\n  const 技 = String(项['技能'] || '').replace(/；/g, ' · ').replace(/^无$/, '');\n  const 人们 = String(项['人际关系'] || '').split('、').map(s => /^(.+?)（(.+?)）$/.exec(s.trim())).filter(Boolean);\n  const 代写 = /^（空着/.test(d.开场白);\n  const 水 = 罗马 ? 罗马.split(/\\s+/).filter(Boolean).pop().toUpperCase() : '';\n  return '<div class=\"rcpt anim-card\">' + (水 ? '<div class=\"wm anim-wm\" aria-hidden=\"true\">' + 转义(水) + '<\/div>' : '')\n    + '<span class=\"tag\">OPENING · ' + 转义(项['玩法'] || '正常内容') + '<\/span>'\n    + '<h5>' + 转义(名) + (罗马 ? '<small>' + 转义(罗马) + '<\/small>' : '') + '<\/h5>'\n    + '<div class=\"line\">' + 转义([身份, 技].filter(Boolean).join(' · ')) + '<\/div>'\n    + '<div class=\"pills\">' + (时间串 ? '<span class=\"hot\">' + 转义(时间串) + '<\/span>' : '') + (季 ? '<span>' + 转义(季) + '<\/span>' : '') + (地 ? '<span>' + 转义(地) + '<\/span>' : '') + '<\/div>'\n    + (人们.length ? '<div class=\"knows stagger\">' + 人们.map(m => {\n      const 人 = 查人(m[1]);\n      return '<div>' + (人 && 人.头像 ? 头像画布(人.头像, 26) : '<span class=\"ph\"><\/span>')\n        + '<span>' + 转义(m[1]) + '<\/span><em>' + 转义(m[2]) + '<\/em><\/div>';\n    }).join('') + '<\/div>' : '')\n    + (d.开场白 ? '<div class=\"prose' + (代写 ? ' soft' : '') + '\">' + 转义(代写 ? '开场白 · AI 代写' : d.开场白) + '<\/div>' : '')\n    + '<\/div>';\n}\n\ndocument.getElementById('app').innerHTML = 画(本楼原文());\n画头像们(document.getElementById('app'));\n\n})();\n\n<\/script>\n<\/body>\n<\/html>\n","面板":"<!DOCTYPE html>\n<html lang=\"zh-CN\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>角色面板<\/title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link href=\"https://fonts.googleapis.com/css2?family=Fredoka:wght@500;600;700&family=Noto+Sans+SC:wght@500;700;900&display=swap\" rel=\"stylesheet\">\n<style>\n*{margin:0;padding:0;box-sizing:border-box;}\n\n:root{\n  --bg:#fdfaf7;\n  --card:#ffffff;\n  --card-2:#f6f2ee;\n  --row:#f2eef8;\n  --ink:#3a3448;\n  --ink-soft:#8b849c;\n  --ink-dim:#c7c1d6;\n  --line:#ece7f0;\n  --shadow:0 10px 28px rgba(70,50,90,.10), 0 2px 8px rgba(70,50,90,.06);\n  --font-display:'Fredoka','Arial Rounded MT Bold','Segoe UI',sans-serif;\n  --font-heading:'Noto Sans SC','PingFang SC','Microsoft YaHei',sans-serif;\n  --font-body:'Noto Sans SC','PingFang SC','Microsoft YaHei',sans-serif;\n  /* 家、工作、学校的标记和快捷钮（DESIGN「出行与住处」），别处不用 */\n  --home:#d0577a;\n  --work:#6b7fc4;\n  --school:#5f9a72;\n}\n\nbody{font-family:var(--font-body);color:var(--ink);background:var(--bg);display:flex;justify-content:center;align-items:center;min-height:100vh;padding:20px;}\n\n/* ===== 图标通用 ===== */\n.th-icon{width:16px;height:16px;flex-shrink:0;fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round;color:#8a8598;filter:drop-shadow(0 1px 0 #fff);transition:transform .3s ease,color .25s ease;}\n.th-icon-xs{width:13px;height:13px;}\n.th-icon.flip{transform:rotate(180deg);}\n\n/* ===== 主容器：浅色舞台，配色随 --accent 联动 ===== */\n.th-wrapper{\n  --accent:#ff4d7d;\n  --accent-soft: color-mix(in srgb, var(--accent) 18%, #ffffff);\n  --accent-soft-2: color-mix(in srgb, var(--accent) 30%, #ffffff);\n  --accent-deep: color-mix(in srgb, var(--accent) 72%, #222222);\n  --accent-line: color-mix(in srgb, var(--accent) 35%, var(--line));\n  --accent-glow: color-mix(in srgb, var(--accent) 45%, transparent);\n  --accent-grad: linear-gradient(180deg, color-mix(in srgb,var(--accent) 85%,#fff), var(--accent));\n  max-width:1000px;width:100%;border-radius:26px;overflow:hidden;position:relative;\n  background-color:var(--bg);\n  background-image:radial-gradient(circle, rgba(120,100,150,.07) 1.4px, transparent 1.6px);\n  background-size:24px 24px;\n  border:1px solid var(--line);\n  box-shadow:0 26px 60px rgba(90,60,110,.16), 0 4px 16px rgba(90,60,110,.08);\n  transition:box-shadow .5s ease;\n}\n.th-note{position:absolute;pointer-events:none;color:var(--accent);opacity:.14;z-index:0;animation:noteFloat 15s ease-in-out infinite;}\n.th-note:nth-child(1){top:6%;left:4%;font-size:20px;animation-duration:13s;}\n.th-note:nth-child(2){top:14%;left:92%;font-size:15px;animation-duration:18s;animation-delay:-4s;}\n.th-note:nth-child(3){top:60%;left:2%;font-size:16px;animation-duration:16s;animation-delay:-8s;}\n.th-note:nth-child(4){top:78%;left:95%;font-size:19px;animation-duration:20s;animation-delay:-2s;}\n@keyframes noteFloat{0%,100%{transform:translateY(0) rotate(-6deg)}50%{transform:translateY(-12px) rotate(8deg)}}\n\n/* ===== 顶部信息栏：白色胶囊 + 折叠态「正在浏览」双色胶囊 ===== */\n.th-info-bar{height:auto;flex-shrink:0;display:flex;align-items:center;justify-content:space-between;padding:14px 22px;cursor:pointer;user-select:none;position:relative;z-index:1;}\n.th-info-bar::before{content:'';position:absolute;inset:0;pointer-events:none;z-index:-1;opacity:0;\n  background-image:\n    linear-gradient(90deg, color-mix(in srgb, var(--bar-a,transparent) 10%, transparent), transparent 30%),\n    linear-gradient(270deg, color-mix(in srgb, var(--bar-b,transparent) 10%, transparent), transparent 30%);\n  transition:opacity .35s ease;}\n.th-info-bar::after{content:'';position:absolute;left:0;right:0;bottom:0;height:3px;border-radius:3px;\n  background:var(--bar-grad, transparent);opacity:0;transition:opacity .35s ease,background .35s ease;pointer-events:none;}\n.th-info-bar.active-char::before{opacity:1;}\n.th-info-bar.active-char::after{opacity:1;}\n\n.th-info-bar-text{font-size:12.5px;color:var(--ink-soft);letter-spacing:.3px;display:flex;align-items:center;gap:10px;font-weight:500;position:relative;z-index:1;}\n.th-info-bar-text>span{background:var(--card);border-radius:20px;padding:6px 14px;box-shadow:var(--shadow);display:inline-flex;align-items:center;gap:6px;}\n\n.th-info-bar-right{display:flex;align-items:center;position:relative;z-index:1;}\n\n/* 折叠态「正在浏览」胶囊：仅在 .th-info-bar.active-char 时展开显示 */\n.th-now-playing{display:inline-flex;align-items:center;gap:9px;background:var(--card);border-radius:20px;box-shadow:var(--shadow);opacity:0;max-width:0;margin-right:0;padding:5px 0;overflow:hidden;pointer-events:none;white-space:nowrap;transition:opacity .35s ease,max-width .35s ease,padding .35s ease,margin-right .35s ease;}\n.th-info-bar.active-char .th-now-playing{opacity:1;max-width:260px;margin-right:10px;padding:5px 16px 5px 12px;pointer-events:auto;}\n.th-now-playing-emblem{height:20px;width:auto;object-fit:contain;display:none;flex-shrink:0;}\n.th-now-playing-divider{width:1px;height:16px;background:var(--line);flex-shrink:0;}\n.th-now-playing-name{display:flex;align-items:baseline;gap:6px;min-width:0;}\n.th-now-playing-name #th-now-playing-cn{font-size:12.5px;font-weight:700;color:var(--ink);letter-spacing:.2px;white-space:nowrap;}\n.th-now-playing-en{font-family:var(--font-display);font-size:10px;letter-spacing:.1em;color:var(--ink-soft);text-transform:uppercase;white-space:nowrap;}\n.th-now-playing-note{font-size:14px;line-height:1;flex-shrink:0;transition:color .3s ease;}\n.th-now-playing-star{color:#ffc93c;font-size:11px;line-height:1;flex-shrink:0;filter:drop-shadow(0 0 2px rgba(255,201,60,.6));}\n.th-info-bar-sep{display:none;}\n.th-info-bar-toggle{width:30px;height:30px;border-radius:50%;display:flex;align-items:center;justify-content:center;color:var(--accent-deep);background:var(--card);box-shadow:var(--shadow);transition:all 0.25s;flex-shrink:0;}\n.th-info-bar-toggle .th-icon{color:var(--accent-deep);filter:none;transition:color .3s ease;}\n.th-info-bar:hover .th-info-bar-toggle{transform:scale(1.08);}\n.th-info-bar.active-char .th-info-bar-toggle{color:var(--bar-a,var(--accent-deep));}\n.th-info-bar.active-char .th-info-bar-toggle .th-icon{color:var(--bar-a,var(--accent-deep));}\n\n/* ===== 折叠面板 ===== */\n.th-collapsible{display:grid;grid-template-rows:1fr;transition:grid-template-rows 0.35s ease,opacity 0.3s ease;opacity:1;}\n.th-collapsible.collapsed{grid-template-rows:0fr;opacity:0;}\n.th-collapsible-inner{overflow:hidden;min-height:0;}\n\n/* ===== 主内容区 ===== */\n.th-main{padding:6px 26px 28px;display:flex;flex-direction:column;position:relative;z-index:1;}\n\n/* ===== Tab 切换栏：PJSK 色块选中风 ===== */\n.th-tab-bar{display:flex;gap:8px;margin-bottom:20px;flex-wrap:wrap;}\n.th-tab-btn{padding:10px 18px;cursor:pointer;font-size:14px;font-weight:700;color:var(--ink-soft);letter-spacing:.3px;border-radius:14px;transition:all 0.25s;display:flex;align-items:center;gap:7px;}\n.th-tab-btn .th-icon{color:var(--ink-soft);filter:none;transition:color .25s ease;}\n.th-tab-btn:hover{color:var(--ink);background:var(--card);}\n.th-tab-btn:hover .th-icon{color:var(--ink);}\n.th-tab-btn.active{background:var(--accent-deep);color:#fff;text-shadow:0 1px 2px rgba(0,0,0,.2);box-shadow:0 6px 16px var(--accent-glow);transform:translateY(-1px);}\n.th-tab-btn.active .th-icon{color:#fff;}\n\n/* ===== 内容区容器：五个顶层 tab 之间切换时，容器高度跟内容一起过渡，\n   避免从矮的页面切到高的页面（比如剧情页）时整块区域瞬间跳一下 ===== */\n.th-content{position:relative;min-height:300px;overflow:hidden;transition:height .32s cubic-bezier(.22,1,.36,1);}\n\n/* ================================================================\n   主要角色页 — 严格按照线框图布局，单张白卡\n   ================================================================ */\n.th-affection-layout{\n  display:flex;align-items:center;justify-content:center;gap:46px;\n  min-height:300px;position:relative;overflow:hidden;\n  background:var(--card);border-radius:22px;padding:38px 44px;box-shadow:var(--shadow);\n}\n\n/* 姓名水印：随当前角色切换 */\n.th-name-watermark{position:absolute;top:-10px;left:16px;font-family:var(--font-display);font-weight:900;font-size:132px;letter-spacing:2px;text-transform:uppercase;color:rgba(60,50,70,.06);white-space:nowrap;pointer-events:none;z-index:0;line-height:1;}\n.th-name-watermark:empty{display:none;}\n\n/* ---- 左侧信息块 ---- */\n.th-affection-left{flex:0 1 360px;min-width:0;display:flex;flex-direction:column;justify-content:center;position:relative;z-index:1;}\n\n/* 乐队徽标：放大的圆角徽章 */\n.th-team-chip{display:inline-flex;align-items:center;justify-content:flex-start;margin-bottom:16px;}\n.th-team-chip:empty{display:none;}\n.th-team-logo-img{max-height:34px;width:auto;max-width:220px;object-fit:contain;display:none;}\n#th-team-chip .th-team-logo-fallback{font-size:15px;color:var(--ink);letter-spacing:.3px;display:none;font-weight:800;text-align:left;line-height:1.2;}\n\n.th-detail-name{font-size:32px;font-weight:900;letter-spacing:.3px;font-family:var(--font-heading);color:var(--ink);line-height:1.15;}\n.th-romaji{font-family:var(--font-display);font-size:12.5px;letter-spacing:.14em;color:var(--ink-soft);margin-top:5px;text-transform:uppercase;font-weight:600;}\n.th-romaji:empty{display:none;}\n\n.th-info-divider{height:2px;border-radius:2px;background:var(--line);margin:22px 0 20px;position:relative;overflow:visible;}\n.th-info-divider::before{content:'';position:absolute;left:0;top:0;width:34px;height:2px;border-radius:2px;background:var(--accent);box-shadow:0 0 8px var(--accent-glow);}\n\n.th-stat-grid{display:grid;grid-template-columns:1fr auto 1fr;gap:0 22px;}\n.th-stat-col{display:flex;flex-direction:column;gap:16px;}\n.th-stat-col-divider{width:2px;border-radius:2px;background:var(--line);}\n.th-field{display:flex;flex-direction:column;gap:6px;}\n.th-field-label{font-size:11px;color:var(--ink-dim);letter-spacing:1.5px;font-family:var(--font-display);font-weight:600;text-transform:uppercase;}\n.th-field-val{font-size:15px;color:var(--ink);font-weight:700;}\n.th-field-val.is-empty{color:#a8a2b5;}\n.th-field-val.th-field-rel{font-size:13.5px;line-height:1.55;}   /* 与主角的关系是一句话（≤ 20 字），比单个词小一号，折两行也不压人 */\n.th-field-val.th-pill{display:inline-flex;width:fit-content;background:var(--accent);color:#fff;text-shadow:0 1px 2px rgba(0,0,0,.25);padding:4px 14px;border-radius:999px;font-size:13.5px;letter-spacing:.15em;text-indent:.15em;transition:background .4s ease;}\n.th-field-val.th-strip{display:inline-flex;width:fit-content;background:var(--accent-deep);color:#fff;text-shadow:0 1px 2px rgba(0,0,0,.25);padding:5px 15px;border-radius:9px;font-family:var(--font-display);font-size:16px;letter-spacing:.03em;transition:background .4s ease;}\n.th-field-val.is-empty.th-pill,.th-field-val.is-empty.th-strip{background:#eee9f0;color:#a8a2b5;text-shadow:none;}\n/* 此刻在哪、她家（23）：资料格下面两行，格名同 th-field-label；有地图上的那一处时整行能点，右边一颗钉子 */\n.th-where{display:flex;flex-direction:column;gap:2px;margin-top:18px;padding-top:12px;border-top:2px solid var(--line);}\n.th-where-row{display:flex;align-items:center;gap:10px;width:100%;min-height:34px;padding:6px 10px;margin:0 -10px;box-sizing:content-box;border:none;border-radius:10px;background:none;font:inherit;text-align:left;cursor:pointer;transition:background .2s ease;}\n.th-where-row .th-field-label{flex:none;width:58px;}\n.th-where-val{flex:1;min-width:0;font-size:13.5px;font-weight:700;color:var(--ink);line-height:1.45;}\n.th-where-val.is-empty{color:#a8a2b5;}\n.th-where-go{width:15px;height:15px;color:var(--ink-dim);filter:none;}\n.th-where-row:hover:not(:disabled){background:var(--card-2);}\n.th-where-row:hover:not(:disabled) .th-where-go{color:var(--accent-deep);}\n.th-where-row:disabled{cursor:default;}\n.th-where-row:disabled .th-where-go{display:none;}\n\n/* ---- 右侧竖版立绘 (约 3:4) ---- */\n.th-affection-right{flex:0 1 266px;min-width:0;position:relative;z-index:1;}\n.th-char-img-wrap{width:100%;aspect-ratio:266/355;border-radius:22px;overflow:visible;position:relative;background:var(--card-2);cursor:pointer;border:3px solid #ffffff;box-shadow:var(--shadow),0 0 0 1px var(--line);transition:box-shadow .35s ease,transform .3s ease;}\n.th-char-img-wrap:hover{transform:translateY(-3px);box-shadow:0 16px 36px rgba(90,60,110,.2),0 0 0 1px var(--accent-line);}\n.th-char-img-placeholder{width:100%;height:100%;border-radius:19px;display:flex;align-items:center;justify-content:center;font-size:64px;font-weight:900;color:var(--ink-dim);transition:opacity 0.5s ease;font-family:var(--font-heading);background:var(--card-2);}\n.th-placeholder-icon{width:92px;height:92px;color:var(--ink-dim);filter:none;}\n.th-char-img-real{width:100%;height:100%;border-radius:19px;object-fit:cover;display:none;transition:opacity 0.5s ease;}\n.th-char-img-glow{position:absolute;inset:0;pointer-events:none;border-radius:19px;z-index:1;box-shadow:inset 0 -60px 50px -40px rgba(0,0,0,.18);}\n\n@keyframes emptyGlowPulse{0%,100%{opacity:0.55}50%{opacity:1}}\n.th-char-img-placeholder.th-empty-glow{animation:emptyGlowPulse 2.4s ease-in-out infinite;}\n\n/* 图片hover遮罩：相机图标改为遮罩SVG，避免使用 emoji */\n.th-img-overlay{position:absolute;inset:0;z-index:2;background:rgba(40,32,52,.6);display:flex;align-items:center;justify-content:center;flex-direction:column;gap:8px;opacity:0;transition:opacity 0.3s ease;border-radius:19px;cursor:pointer;color:#fff;font-size:13px;font-weight:700;letter-spacing:.5px;pointer-events:none;text-align:center;padding:10px;}\n.th-img-overlay::before{content:'';width:26px;height:22px;background-color:#fff;\n  -webkit-mask-image:url(\"data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='black' stroke-width='1.8' stroke-linecap='round' stroke-linejoin='round'><rect x='3' y='7' width='18' height='13' rx='3'/><path d='M8 7l2-3h4l2 3'/><circle cx='12' cy='13.5' r='3.5'/><\/svg>\");\n  mask-image:url(\"data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='black' stroke-width='1.8' stroke-linecap='round' stroke-linejoin='round'><rect x='3' y='7' width='18' height='13' rx='3'/><path d='M8 7l2-3h4l2 3'/><circle cx='12' cy='13.5' r='3.5'/><\/svg>\");\n  -webkit-mask-repeat:no-repeat;mask-repeat:no-repeat;-webkit-mask-size:contain;mask-size:contain;}\n.th-char-img-wrap:hover .th-img-overlay{opacity:1;pointer-events:auto;}\n.th-char-img-wrap.th-drawer-active .th-img-overlay{opacity:0!important;pointer-events:none!important;}\n\n/* 收藏星标：白底圆徽章，卡在右上角 */\n.th-fav-star{position:absolute;top:-14px;right:-14px;width:38px;height:38px;border-radius:50%;background:#ffffff;display:flex;align-items:center;justify-content:center;cursor:pointer;z-index:5;box-shadow:0 6px 16px rgba(90,60,110,.25);transition:box-shadow 0.25s ease,transform 0.2s ease;}\n.th-fav-star:hover{transform:scale(1.1) rotate(-8deg);}\n.th-fav-star svg{width:19px;height:19px;fill:none;stroke:var(--ink-dim);stroke-width:1.8;stroke-linejoin:round;transition:fill .3s ease,stroke .3s ease,filter .3s ease;}\n.th-fav-star.on svg{fill:var(--accent);stroke:var(--accent);filter:drop-shadow(0 0 5px var(--accent-glow));}\n.th-fav-star.on{box-shadow:0 6px 16px rgba(90,60,110,.25),0 0 14px var(--accent-glow);}\n\n/* 撕票根按钮：藏心声入口，卡在立绘左下角 */\n.th-seal-btn{position:absolute;bottom:-13px;left:24px;width:34px;height:34px;cursor:pointer;z-index:6;transition:filter .3s ease;}\n.th-seal-btn.th-hidden{display:none;}\n/* 人格切换（若叶睦 ↔ 墨缇丝）：立绘左上角，和右上角的收藏星对称；切到人格那一面时强调色实心 */\n.th-persona-btn{position:absolute;top:-14px;left:-14px;width:38px;height:38px;border-radius:50%;background:#ffffff;display:flex;align-items:center;justify-content:center;cursor:pointer;z-index:5;box-shadow:0 6px 16px rgba(90,60,110,.25);color:var(--ink-soft);transition:background .2s ease,color .2s ease;}\n.th-persona-btn svg{width:20px;height:20px;fill:none;stroke:currentColor;stroke-width:1.9;stroke-linecap:round;stroke-linejoin:round;}\n.th-persona-btn.on{background:var(--accent);color:#ffffff;}\n.th-persona-btn.th-hidden{display:none;}\n.th-persona-tag{display:inline-flex;align-self:flex-start;width:fit-content;margin-top:6px;padding:2px 9px;border-radius:99px;background:var(--card-2);color:var(--ink-soft);font-size:11px;font-weight:800;}\n.th-seal-half{position:absolute;inset:0;transition:transform .5s cubic-bezier(.34,1.56,.64,1),opacity .5s ease;}\n.th-seal-half.l{clip-path:inset(0 50% 0 0);}\n.th-seal-half.r{clip-path:inset(0 0 0 50%);}\n.th-seal-inner{position:absolute;inset:0;border-radius:50%;background:#ffffff;border:1.5px dashed var(--accent-line);display:flex;align-items:center;justify-content:center;box-shadow:0 4px 10px rgba(90,60,110,.18);}\n.th-seal-inner svg{width:15px;height:15px;stroke:var(--accent-deep);fill:none;stroke-width:1.7;stroke-linecap:round;stroke-linejoin:round;}\n.th-seal-btn:hover .th-seal-inner{box-shadow:0 4px 10px rgba(90,60,110,.18),0 0 10px var(--accent-glow);}\n.th-seal-btn.tearing .th-seal-half.l{transform:translate(-11px,6px) rotate(-30deg);opacity:0;}\n.th-seal-btn.tearing .th-seal-half.r{transform:translate(11px,6px) rotate(30deg);opacity:0;}\n\n/* 翻面动画：撕开票根后，资料卡整体翻转到背面显示心声 */\n.th-flip-stage{perspective:1800px;}\n.th-flip-inner{position:relative;transition:transform .7s cubic-bezier(.4,.1,.2,1);transform-style:preserve-3d;}\n.th-flip-inner.flipped{transform:rotateY(180deg);}\n.th-affection-layout{backface-visibility:hidden;-webkit-backface-visibility:hidden;}\n.th-flip-inner.flipped .th-affection-layout{pointer-events:none;}\n\n/* 内心页：撕开票根后显示，作为资料卡的背面 */\n.th-inner-profile{display:flex;min-height:300px;background:var(--card);border-radius:22px;padding:38px 44px;box-shadow:var(--shadow);position:absolute;inset:0;flex-direction:column;backface-visibility:hidden;-webkit-backface-visibility:hidden;transform:rotateY(180deg);pointer-events:none;}\n.th-flip-inner.flipped .th-inner-profile{pointer-events:auto;}\n/* 翻到侧对着的那一刻换面（.7s 这条缓动在 .23s 左右转到 90°）：Firefox 在整块翻转里有时不认 backface-visibility，\n   不藏的话正面会左右镜像着透到心声页上 */\n.th-affection-layout{transition:visibility 0s linear .23s;}\n.th-flip-inner.flipped .th-affection-layout{visibility:hidden;}\n.th-inner-profile{visibility:hidden;transition:visibility 0s linear .23s;}\n.th-flip-inner.flipped .th-inner-profile{visibility:visible;}\n.th-inner-back{align-self:flex-start;background:none;border:none;color:var(--ink-dim);font-size:12.5px;letter-spacing:.3px;cursor:pointer;display:flex;align-items:center;gap:6px;margin-bottom:18px;padding:4px 0;font-family:var(--font-body);}\n.th-inner-back .th-icon{color:var(--ink-dim);filter:none;transition:color .25s ease;}\n.th-inner-back:hover{color:var(--accent-deep);}\n.th-inner-back:hover .th-icon{color:var(--accent-deep);}\n.th-inner-header{display:flex;align-items:baseline;gap:12px;margin-bottom:22px;flex-wrap:wrap;}\n.th-inner-title{font-size:22px;font-weight:900;font-family:var(--font-heading);color:var(--ink);}\n.th-inner-sub{font-family:var(--font-display);font-size:11px;letter-spacing:.16em;color:var(--accent-deep);text-transform:uppercase;font-weight:700;transition:color .4s ease;}\n.th-inner-card{flex:1;display:flex;align-items:center;background:var(--row);border-radius:16px;padding:28px 32px;}\n.th-thought-text{color:var(--ink);font-size:16px;line-height:2;position:relative;padding-left:20px;font-weight:500;}\n.th-thought-text::before{content:'“';position:absolute;left:-6px;top:-18px;font-size:48px;color:var(--accent);opacity:.5;font-family:Georgia,serif;transition:color .4s ease;}\n.th-inner-empty{color:var(--ink-dim);font-size:14px;line-height:1.9;font-style:italic;}\n\n/* ---- 空状态 ---- */\n.th-empty-hint{font-size:12.5px;color:var(--ink-soft);line-height:1.8;margin-top:6px;max-width:320px;}\n\n/* ---- 角色切换动画 ---- */\n@keyframes charSwitchFade{0%{opacity:0;transform:translateY(6px)}100%{opacity:1;transform:translateY(0)}}\n.th-char-switch{animation:charSwitchFade 0.4s cubic-bezier(0.22,1,0.36,1);}\n\n/* ---- 挂在聊天楼层里，面板多半只有 560～860px 宽（桌面设计按 1000px 画的）：\n   构图不变，左边信息块和右边立绘按 360 : 266 一起缩（上面两块的 flex 基准），边距收一点 ---- */\n@media (max-width:860px){\n  .th-affection-layout{gap:28px;padding:30px 28px;}\n  .th-inner-profile{padding:30px 28px;}\n}\n/* ---- 手机（≤560px）的排法在 手机.css ---- */\n\n/* ================================================================\n   主角状态 / 地图 / 剧情 / 抽屉 — 统一浅色律动风\n   ================================================================ */\n.th-player-content{max-width:850px;margin:0 auto;width:100%;padding:4px 0;}\n.th-placeholder{color:var(--ink-dim);}\n.th-ph-label{color:var(--ink-soft);}\n\n.th-player-header{display:flex;justify-content:space-between;align-items:center;margin-bottom:18px;flex-wrap:wrap;gap:10px;}\n.th-player-identity{font-size:15px;font-weight:700;color:var(--ink);letter-spacing:.2px;}\n.th-player-location{font-size:12px;color:#fff;text-shadow:0 1px 2px rgba(0,0,0,.2);background:var(--accent-deep);padding:6px 14px;border-radius:20px;font-weight:700;}\n\n.th-player-bars{display:flex;gap:14px;margin-bottom:14px;}\n.th-player-bar-card{flex:1;padding:14px 16px;border-radius:16px;background:var(--card);box-shadow:var(--shadow);}\n.th-pbar-title{font-size:12.5px;color:var(--ink-soft);letter-spacing:.3px;margin-bottom:9px;display:flex;justify-content:space-between;font-weight:700;}\n.th-pbar-pct{color:var(--accent-deep);font-family:var(--font-display);letter-spacing:.03em;}\n.th-pbar-desc{font-size:11.5px;margin-top:8px;color:var(--ink-dim);}\n\n.th-bar-track{height:9px;background:var(--row);border-radius:5px;overflow:hidden;position:relative;}\n.th-bar-fill{height:100%;border-radius:5px;transition:width 0.6s cubic-bezier(0.22,1,0.36,1),background 0.4s ease;position:relative;}\n.th-bar-fill::after{content:'';position:absolute;inset:0;background:linear-gradient(180deg,rgba(255,255,255,.5),transparent 60%);}\n.th-bar-fill.hp{background:var(--accent-grad);}\n.th-bar-fill.sp{background:linear-gradient(180deg,color-mix(in srgb,var(--accent) 70%,#4dd0ff),color-mix(in srgb,var(--accent) 45%,#4dd0ff));}\n.th-bar-fill.attr{background:var(--accent-grad);}\n\n.th-player-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-bottom:14px;}\n.th-player-cell{padding:12px 15px;border-radius:16px;background:var(--card);box-shadow:var(--shadow);}\n.th-pcell-title{font-size:10.5px;color:var(--ink-dim);letter-spacing:1px;margin-bottom:6px;font-weight:700;text-transform:uppercase;font-family:var(--font-display);}\n.th-pcell-value{font-size:13px;color:var(--ink);word-break:break-all;line-height:1.6;font-weight:500;}\n\n.th-player-two-col{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-bottom:14px;}\n.th-player-task-card{padding:12px 15px;border-radius:16px;background:var(--accent-soft);box-shadow:var(--shadow);}\n\n.th-player-bag{padding:12px 15px;border-radius:16px;background:var(--card);box-shadow:var(--shadow);margin-bottom:14px;}\n.th-bag-tags{display:flex;flex-wrap:wrap;gap:8px;margin-top:6px;}\n.th-bag-tag{font-size:11.5px;color:var(--ink-soft);background:var(--row);padding:5px 13px;border-radius:20px;font-weight:600;}\n\n.th-player-ability{padding:16px 18px;border-radius:16px;background:var(--card);box-shadow:var(--shadow);}\n.th-ability-cols{display:grid;grid-template-columns:1fr 1fr;gap:24px;}\n.th-attr-row{display:grid;grid-template-columns:44px auto 1fr;gap:8px;align-items:center;margin-bottom:14px;}\n.th-attr-row .th-attr-bar{grid-column:1/-1;height:6px;}\n.th-attr-name{font-size:12.5px;color:var(--ink-soft);letter-spacing:.3px;font-weight:600;}\n.th-attr-badge{font-size:10px;color:#fff;text-shadow:0 1px 2px rgba(0,0,0,.2);background:var(--accent);padding:2px 9px;border-radius:8px;justify-self:start;font-family:var(--font-display);font-weight:600;}\n.th-attr-exp{font-size:10.5px;color:var(--ink-dim);font-family:var(--font-display);justify-self:end;font-weight:600;}\n\n.th-skill-group{margin-bottom:14px;}\n.th-skill-label{font-size:11px;color:var(--ink-dim);letter-spacing:.5px;margin-bottom:7px;font-weight:600;}\n.th-skill-tags{display:flex;flex-wrap:wrap;gap:6px;}\n.th-skill-tag{font-size:11.5px;padding:5px 11px;border-radius:9px;background:var(--row);color:var(--ink-soft);display:inline-flex;align-items:center;gap:6px;font-weight:600;}\n.th-skill-tag::before{font-family:monospace;letter-spacing:1px;font-size:10px;color:var(--accent-deep);}\n.th-skill-tag.lv1::before{content:'▮▯▯';}\n.th-skill-tag.lv2::before{content:'▮▮▯';}\n.th-skill-tag.lv3::before{content:'▮▮▮';}\n.th-skill-tag.lv3{background:var(--accent-soft);}\n\n/* 手风琴 */\n.th-acc{margin-bottom:14px;}\n.th-acc-header{display:flex;justify-content:space-between;align-items:center;padding:14px 18px;border-radius:16px;background:var(--card);box-shadow:var(--shadow);cursor:pointer;user-select:none;transition:transform 0.2s;}\n.th-acc-header:hover{transform:translateY(-1px);}\n.th-acc-title{font-size:13.5px;font-weight:700;color:var(--ink);letter-spacing:.2px;}\n.th-acc-arrow{color:var(--accent-deep);font-size:11px;font-weight:900;}\n.th-acc-body{display:grid;grid-template-rows:1fr;transition:grid-template-rows 0.35s ease,opacity 0.3s ease;}\n.th-acc-body.collapsed{grid-template-rows:0fr;opacity:0;}\n.th-acc-body-inner{overflow:hidden;min-height:0;padding-top:12px;}\n\n/* 地图页：按重要程度显示地点，信息面板浮在地图上 */\n.th-map-content{max-width:980px;margin:0 auto;width:100%;}\n.th-map-viewport{position:relative;height:560px;border-radius:20px;overflow:hidden;background:var(--card);box-shadow:var(--shadow);cursor:grab;\n  background-image:radial-gradient(circle, var(--line) 1.4px, transparent 1.7px);background-size:26px 26px;}\n.th-map-viewport.dragging{cursor:grabbing;}\n.th-map-canvas{position:absolute;top:0;left:0;width:100%;height:100%;transform-origin:0 0;will-change:transform;isolation:isolate;touch-action:none;}\n\n/* 剧情地与地标使用相同的标记结构 */\n.th-map-markers{position:absolute;inset:0;pointer-events:none;}\n.th-map-marker{padding:0;box-sizing:content-box;font:inherit;pointer-events:auto;position:absolute;z-index:2;width:18px;height:18px;border-radius:50%;background:var(--m-color,var(--accent));border:2.5px solid #fff;box-shadow:0 2px 6px rgba(0,0,0,.3);cursor:pointer;transform:translate(-50%,-50%);display:flex;align-items:center;justify-content:center;}\n.th-map-marker-icon{width:11px;height:11px;color:#fff;flex-shrink:0;pointer-events:none;}\n.th-map-marker:hover{z-index:6;}\n.th-map-marker.active{box-shadow:0 0 0 4px var(--accent-soft),0 3px 8px rgba(0,0,0,.32);z-index:8;}\n.th-map-marker.origin{box-shadow:0 0 0 4px rgba(62,207,106,.4),0 3px 8px rgba(0,0,0,.3);}\n/* 玩家所在地：呼吸光圈，和普通标记明显区分 */\n.th-map-marker.player{background:#3ecf6a;border-color:#fff;z-index:9;}\n.th-map-marker.player::after{content:'';position:absolute;left:50%;top:50%;width:18px;height:18px;margin:-9px 0 0 -9px;\n  border-radius:50%;border:2px solid #3ecf6a;animation:thPlayerPulse 2s ease-out infinite;pointer-events:none;}\n@keyframes thPlayerPulse{0%{transform:scale(1);opacity:.75}100%{transform:scale(2.6);opacity:0}}\n.th-map-marker.player .th-map-marker-label{color:#177f3d;background:rgba(255,255,255,.94);font-weight:800;}\n/* 导航面板 */\n.th-map-nav{position:absolute;left:12px;bottom:12px;width:min(290px,calc(100% - 66px));max-height:195px;overflow-y:auto;background:var(--card);border-radius:16px;\n  box-shadow:0 8px 26px rgba(0,0,0,.2);padding:12px 14px;z-index:13;}\n.th-map-nav-h{display:flex;align-items:center;justify-content:space-between;margin-bottom:8px;}\n.th-map-nav-t{font-size:12px;font-weight:800;color:var(--ink);}\n.th-map-nav-x{width:20px;height:20px;border-radius:50%;border:none;background:var(--row);color:var(--ink-dim);font-size:12px;cursor:pointer;line-height:1;}\n.th-map-nav-x:hover{color:var(--accent-deep);}\n.th-map-nav-leg{display:flex;align-items:baseline;gap:6px;font-size:11.5px;margin-bottom:3px;}\n.th-map-nav-leg .tag{font-size:9.5px;font-weight:800;padding:1px 6px;border-radius:999px;flex-shrink:0;}\n.th-map-nav-leg.from .tag{background:rgba(62,207,106,.16);color:#177f3d;}\n.th-map-nav-leg.to .tag{background:var(--accent-soft);color:var(--accent-deep);}\n.th-map-nav-leg .nm{font-weight:700;color:var(--ink);}\n.th-map-nav-sum{margin-top:8px;padding-top:8px;border-top:1px solid var(--line);font-size:12px;color:var(--ink-soft);}\n.th-map-nav-sum b{color:var(--ink);font-weight:800;}\n.th-map-nav-path{font-size:10.5px;color:var(--ink-dim);margin-top:4px;}\n.th-map-nav-btns{display:flex;gap:6px;margin-top:9px;}\n.th-map-nav-btns button{flex:1;height:26px;border:none;border-radius:8px;font-size:11px;font-weight:700;cursor:pointer;font-family:inherit;}\n.th-map-nav-go{background:var(--accent-grad);color:#fff;}\n.th-map-nav-alt{background:var(--row);color:var(--ink-soft);}\n.th-map-nav-btns button:hover{filter:brightness(1.05);}\n.th-map-nav-btns button:disabled{opacity:.5;cursor:default;}\n.th-map-nav-btns:empty{display:none;}\n.th-map-route-line{stroke-dasharray:7 5;animation:thRouteDash 1.1s linear infinite;}\n@keyframes thRouteDash{to{stroke-dashoffset:-24}}\n.th-map-marker-label{position:absolute;left:13px;top:50%;transform:translateY(-50%);white-space:nowrap;max-width:150px;overflow:hidden;text-overflow:ellipsis;font-size:9.5px;font-weight:700;color:var(--ink);background:rgba(255,255,255,.88);padding:1px 5px;border-radius:5px;pointer-events:none;opacity:0;transition:opacity .15s;}\n.th-map-marker.label-left .th-map-marker-label{left:auto;right:13px;}\n.th-map-marker.has-label:not(.label-hidden) .th-map-marker-label,.th-map-marker:hover .th-map-marker-label,.th-map-marker:focus-visible .th-map-marker-label{opacity:1;}\n.th-map-marker:focus-visible{outline:3px solid var(--ink);outline-offset:3px;z-index:10;}\n\n/* 浮层：搜索框 / 地点卡片 / 缩放按钮 / 当前位置 */\n/* 左上角一列：搜索框 → 搜索结果 → 面包屑。\n   之前搜索结果和面包屑都是 absolute 且都从 top:12/54 起算，展开结果时两者叠在一起，\n   面包屑被盖住一半，点「东京都」经常打在结果列表上。 */\n.th-map-topleft{position:absolute;left:12px;top:12px;width:min(310px,calc(100% - 24px));z-index:14;display:flex;flex-direction:column;align-items:flex-start;gap:6px;}\n/* 板签：当前在哪块图板 */\n.th-map-board-chip{display:flex;align-items:center;gap:7px;padding:5px 10px;border-radius:999px;\n  background:var(--panel-solid,#fffdfc);border:1px solid var(--line);box-shadow:0 2px 10px rgba(0,0,0,.10);\n  font-size:11.5px;line-height:1.5;max-width:min(78vw,340px);}\n.th-map-board-back{border:none;background:var(--accent-soft,#ffe8ef);color:var(--accent-deep);\n  width:20px;height:20px;border-radius:50%;cursor:pointer;font-size:12px;line-height:1;flex:0 0 auto;\n  display:flex;align-items:center;justify-content:center;padding:0;font-weight:700;}\n.th-map-board-back:hover{background:var(--accent);color:#fff;}\n.th-map-board-here{font-weight:800;color:var(--ink);white-space:nowrap;}\n.th-map-board-hint{color:var(--ink-dim);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}\n/* 窄屏把副标题收起来，否则幅签横贯整行，把右上角的计数条和「你在这里」压在下面 */\n@media (max-width:560px){ .th-map-board-hint{display:none;} }\n/* 子幅入口：当前图幅上通往下一级的「门」。\n   之前是整块虚线粉方框 + 白名牌，一屏三个盖掉半张地图。\n   改成：极淡的实线描边（只勾出范围，不遮底图）+ 一枚贴在左上角的小标签。 */\n.th-map-door{position:absolute;border:1px solid color-mix(in srgb,var(--accent) 45%,transparent);\n  border-radius:6px;cursor:pointer;z-index:5;background:transparent;\n  transition:background .14s,border-color .14s,box-shadow .14s;}\n.th-map-door:hover{border-color:var(--accent);\n  background:color-mix(in srgb,var(--accent) 7%,transparent);\n  box-shadow:0 0 0 1px color-mix(in srgb,var(--accent) 25%,transparent);}\n.th-map-door-tag{position:absolute;left:0;display:inline-flex;align-items:baseline;gap:5px;\n  white-space:nowrap;pointer-events:none;transform:translateY(-50%);\n  background:color-mix(in srgb,var(--panel-solid,#fffdfc) 92%,transparent);\n  border:1px solid color-mix(in srgb,var(--accent) 35%,transparent);\n  border-radius:5px;padding:2px 7px;box-shadow:0 1px 4px rgba(0,0,0,.08);}\n.th-map-door:hover .th-map-door-tag{background:var(--panel-solid,#fffdfc);border-color:var(--accent);}\n.th-map-door-tag b{font-size:11px;color:var(--ink);font-weight:700;}\n.th-map-door-tag span{font-size:9.5px;color:var(--accent-deep);font-weight:700;}\n/* 大区切换条：关东 / 关西 / 东海 */\n.th-map-rgbar{display:flex;gap:6px;padding:8px 10px 4px;}\n.th-map-rgbtn{flex:1;display:flex;align-items:center;justify-content:center;gap:5px;\npadding:7px 4px;border:1px solid var(--line);border-radius:9px;background:rgba(255,255,255,.7);\nfont-size:11.5px;font-weight:700;color:var(--ink-dim);cursor:pointer;transition:all .15s;}\n.th-map-rgbtn:hover{border-color:var(--accent);color:var(--ink);}\n.th-map-rgbtn.is-on{background:var(--accent-grad);color:#fff;border-color:transparent;}\n.th-map-rgbtn > span{font-size:9.5px;font-weight:600;opacity:.72;}\n\n/* 地图册 */\n.th-map-book-btn{border:none;background:transparent;color:var(--ink-dim);cursor:pointer;\n  font-size:12px;line-height:1;padding:2px 3px;flex:0 0 auto;}\n.th-map-book-btn:hover{color:var(--accent-deep);}\n.th-map-book{display:none;flex-direction:column;min-height:0;overflow:hidden;width:100%;}\n.th-map-book.open{display:flex;}\n.th-map-book-h{display:flex;align-items:center;justify-content:space-between;padding:8px 10px;\n  border-bottom:1px solid var(--line);font-size:12px;font-weight:800;color:var(--ink);}\n.th-map-book-x{border:none;background:transparent;font-size:15px;line-height:1;cursor:pointer;color:var(--ink-dim);padding:0 2px;}\n.th-map-book-b{overflow-y:auto;padding:4px 0;}\n.th-map-book-grp{display:flex;align-items:baseline;justify-content:space-between;gap:8px;\n  padding:7px 10px 3px;font-size:10px;font-weight:800;color:var(--accent-deep);\n  letter-spacing:.04em;border-top:1px solid var(--line);margin-top:3px;}\n.th-map-book-b > .th-map-book-grp:first-child{border-top:none;margin-top:0;}\n.th-map-book-grp span{font-size:9.5px;font-weight:600;color:var(--ink-dim);letter-spacing:0;}\n.th-map-book-row{display:flex;align-items:baseline;gap:6px;width:100%;border:none;background:transparent;\n  cursor:pointer;text-align:left;padding:5px 10px;font-family:inherit;}\n.th-map-book-row:hover{background:var(--accent-soft,#ffe8ef);}\n.th-map-book-row.is-current{background:var(--accent-soft,#ffe8ef);}\n.th-map-book-row.is-current .nm{color:var(--accent-deep);}\n.th-map-book-row .nm{font-size:11.5px;font-weight:700;color:var(--ink);white-space:nowrap;}\n.th-map-book-row .mt{font-size:9.5px;color:var(--ink-dim);flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}\n.th-map-book-row .ct{font-size:9.5px;color:var(--ink-dim);font-weight:700;}\n.th-map-book-area .nm{font-size:12.5px;font-weight:800;}\n.th-map-book-mark{padding-left:22px;}\n.th-map-book-mark .nm{font-size:11px;font-weight:600;color:var(--ink-dim);}\n.th-map-book-mark:hover .nm{color:var(--ink);}\n.th-map-book-mark::before{content:'↳';position:absolute;left:10px;color:var(--line);font-size:10px;}\n.th-map-book-mark{position:relative;}\n.th-map-book-off .nm{font-size:11px;font-weight:600;color:var(--ink-dim);}\n.th-map-card-admin .nomap{color:#c96;font-weight:800;}\n.th-map-search{width:100%;}\n.th-map-board-chip{width:100%;}\n.th-map-explorer{width:100%;display:flex;flex-direction:column;overflow:hidden;border-radius:14px;background:var(--card);box-shadow:0 8px 26px rgba(0,0,0,.18);border:1px solid var(--line);}\n.th-map-explorer[hidden]{display:none;}\n.th-map-explorer-tabs{display:flex;gap:6px;padding:7px;border-bottom:1px solid var(--line);flex-shrink:0;}\n.th-map-explorer-tabs button{border:0;border-radius:8px;padding:7px 10px;font:inherit;font-size:12px;font-weight:700;background:transparent;color:var(--ink-soft);cursor:pointer;}\n.th-map-explorer-tabs button[aria-pressed=\"true\"]{background:var(--accent-soft);color:var(--accent-deep);}\n#th-map-explorer-close{margin-left:auto;}\n.th-map-explorer .th-map-book-h,.th-map-explorer .th-map-dir-head{display:none;}\n.th-map-explorer .th-map-book,.th-map-explorer .th-map-dir{flex:1;}\n.th-map-book-b{min-height:0;}\n.th-map-topleft{max-width:calc(100% - 24px);}\n.th-map-search-results,.th-map-card,.th-map-nav,.th-map-book-b,.th-map-dir-body{overscroll-behavior:contain;}\n.th-map-nav-leg .nm,.th-map-card-name{overflow-wrap:anywhere;min-width:0;}\n.th-map-viewport button:focus-visible,.th-map-layer-row:focus-visible{outline:2px solid var(--accent-deep);outline-offset:2px;}\n.th-map-search input{width:100%;height:34px;border:none;border-radius:10px;background:var(--card);box-shadow:0 3px 12px rgba(0,0,0,.14);\n  padding:0 12px;font-size:12.5px;color:var(--ink);font-family:inherit;outline:none;}\n.th-map-search input::placeholder{color:var(--ink-dim);}\n.th-map-search-cats{display:flex;flex-wrap:wrap;gap:4px;margin-top:6px;padding:5px;border-radius:10px;background:var(--card);box-shadow:0 3px 12px rgba(0,0,0,.14);}\n.th-map-search-cats button{border:0;border-radius:7px;padding:4px 8px;font:inherit;font-size:11px;color:var(--ink-soft);background:transparent;cursor:pointer;}\n.th-map-search-cats button[aria-pressed=\"true\"]{color:var(--accent-deep);background:var(--accent-soft);font-weight:700;}\n.th-map-search-results{margin-top:6px;background:var(--card);border-radius:12px;box-shadow:0 6px 20px rgba(0,0,0,.16);overflow:hidden;max-height:250px;overflow-y:auto;}\n.th-map-search-results:empty{display:none;}\n.th-map-result{display:block;width:100%;padding:7px 12px;text-align:left;font:inherit;background:transparent;border:0;cursor:pointer;border-bottom:1px solid var(--line);}\n.th-map-result:last-child{border-bottom:none;}\n.th-map-result:hover{background:var(--row);}\n.th-map-result-name{display:block;font-size:12px;font-weight:700;color:var(--ink);}\n.th-map-result-meta{display:block;font-size:10px;color:var(--ink-dim);margin-top:1px;}\n.th-map-search-status{padding:8px 12px;font-size:10px;color:var(--ink-dim);line-height:1.6;}\n.th-map-search-more{color:var(--accent-deep);text-align:center;font-size:11px;font-weight:700;}\n\n.th-map-card{position:absolute;left:12px;top:110px;bottom:auto;width:min(290px,calc(100% - 24px));max-height:260px;overflow-y:auto;background:var(--card);border-radius:16px;\n  box-shadow:0 8px 26px rgba(0,0,0,.2);padding:14px 16px;z-index:13;border:1px solid var(--line);border-top:3px solid var(--accent);}\n.th-map-card-close{position:absolute;right:10px;top:9px;width:20px;height:20px;border-radius:50%;background:var(--row);color:var(--ink-dim);\n  display:flex;align-items:center;justify-content:center;font-size:12px;cursor:pointer;border:none;line-height:1;}\n.th-map-card-close:hover{color:var(--accent-deep);}\n.th-map-card-name{font-size:14.5px;font-weight:800;color:var(--ink);margin-bottom:2px;padding-right:22px;line-height:1.35;}\n.th-map-card-name-orig{font-size:11px;color:var(--ink-dim);margin-bottom:6px;}\n.th-map-card-tags{display:flex;flex-wrap:wrap;gap:5px;margin-bottom:8px;}\n.th-map-tag{font-size:10px;font-weight:700;padding:2px 8px;border-radius:999px;background:var(--row);color:var(--ink-dim);}\n.th-map-tag.band{background:color-mix(in srgb, var(--m-color,var(--accent)) 16%, #ffffff);color:var(--m-color,var(--accent));}\n.th-map-tag.fictional{background:var(--accent-soft);color:var(--accent-deep);}\n.th-map-tag.offsite{background:#eef2f6;color:#5b7a94;}\n.th-map-tag-type{display:inline-flex;align-items:center;gap:3px;}\n.th-map-tag-icon{width:11px;height:11px;color:currentColor;}\n.th-map-card-desc{font-size:11.5px;color:var(--ink-soft);line-height:1.75;}\n.th-map-scenes{margin-top:10px;padding-top:9px;border-top:1px solid var(--line);}\n.th-map-scenes-h{font-size:10px;font-weight:800;color:var(--ink-dim);margin-bottom:5px;}\n.th-map-scene{display:flex;align-items:baseline;gap:5px;padding:2px 0 2px 8px;font-size:11px;color:var(--ink-soft);}\n.th-map-scene.lv2{padding-left:20px;}\n.th-map-scene .dot{width:3px;height:3px;border-radius:50%;background:var(--accent);flex-shrink:0;transform:translateY(-2px);}\n.th-map-scene .nm{font-weight:700;color:var(--ink);}\n.th-map-scene .q{color:var(--ink-dim);font-size:10px;}\n.th-map-scene .jump{color:var(--accent-deep);cursor:pointer;font-size:10px;font-weight:700;}\n.th-map-scene .jump:hover{text-decoration:underline;}\n\n.th-map-route{margin-top:10px;padding-top:10px;border-top:1px solid var(--line);font-size:11.5px;color:var(--ink-soft);line-height:1.7;}\n.th-map-route b{color:var(--ink);font-weight:800;}\n.th-map-route-hint{color:var(--ink-dim);}\n.th-map-origin-btn{margin-top:9px;width:100%;height:28px;border:none;border-radius:9px;background:var(--accent-grad);color:#fff;font-size:11.5px;font-weight:700;cursor:pointer;font-family:inherit;}\n.th-map-origin-btn:hover{filter:brightness(1.06);}\n.th-map-origin-btn.is-origin{background:var(--row);color:var(--ink-dim);cursor:default;}\n.th-map-setfrom{margin-top:5px;background:var(--row);color:var(--ink-soft);}\n\n.th-map-zoom{position:absolute;right:12px;bottom:12px;display:flex;flex-direction:column;gap:6px;z-index:12;}\n.th-map-zoom-btn{width:30px;height:30px;border:none;border-radius:9px;background:var(--card);box-shadow:0 3px 9px rgba(0,0,0,.16);color:var(--ink-soft);font-size:15px;font-weight:800;cursor:pointer;display:flex;align-items:center;justify-content:center;transition:all .18s;font-family:var(--font-display);}\n.th-map-zoom-btn:hover{color:var(--accent-deep);transform:translateY(-1px);}\n.th-map-badge{position:absolute;right:12px;top:12px;display:flex;flex-direction:column;align-items:flex-end;gap:5px;z-index:11;pointer-events:none;}\n.th-map-chip{font-size:10.5px;color:var(--ink-dim);background:rgba(255,255,255,.86);padding:3px 10px;border-radius:999px;font-weight:600;white-space:nowrap;}\n.th-map-chip b{color:var(--accent-deep);font-weight:800;}\n/* 底图署名：ODbL 要求底图可见时署名也必须可见 */\n.th-map-attrib{pointer-events:auto;text-decoration:none;color:var(--ink-dim);font-size:9.5px;}\n.th-map-attrib:hover{color:var(--accent-deep);text-decoration:underline;}\n.th-map-nocover{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);font-size:11px;color:var(--ink-dim);background:rgba(255,255,255,.9);padding:5px 14px;border-radius:999px;pointer-events:none;z-index:4;font-weight:600;box-shadow:0 2px 8px rgba(0,0,0,.08);}\n\n/* 底图图片层：按四角经纬度贴的插画底图，压在所有东西最下面 */\n/* 一屏一张图，不再需要边缘羽化（那是多张矩形拼接时期的东西） */\n.th-map-basemaps{position:absolute;inset:0;z-index:0;pointer-events:none;}\n/* 酒馆助手给楼里的 iframe 加载 Tailwind，它的基础样式让所有 img「最宽 100%」。底图的宽常常是视口的十几倍，\n   被压成视口宽以后左边一片露白、右边竖着拉长，所以这里把最宽、最高都解开 */\n.th-map-basemap{position:absolute;pointer-events:none;z-index:0;user-select:none;image-rendering:auto;max-width:none;max-height:none;}\n/* 没过 K=1.8 提亮曲线的底图补上同一条曲线，和旧图同一套色调 */\n.th-map-basemap.tone-raw{filter:url(#th-map-lut18);}\n\n/* 图层开关面板 */\n.th-map-layers{position:absolute;right:50px;bottom:12px;z-index:13;background:var(--card);border-radius:12px;\n  box-shadow:0 6px 20px rgba(0,0,0,.18);padding:8px 6px;min-width:132px;\n  transform:translateY(8px);opacity:0;pointer-events:none;transition:transform .2s cubic-bezier(.4,0,.2,1),opacity .18s;}\n.th-map-layers.open{transform:translateY(0);opacity:1;pointer-events:auto;}\n.th-map-layers-title{font-size:10px;font-weight:800;color:var(--ink-dim);padding:0 8px 5px;}\n.th-map-layer-row{display:flex;align-items:center;gap:7px;padding:5px 8px;border-radius:8px;cursor:pointer;transition:background .15s;}\n.th-map-layer-row:hover{background:var(--row);}\n.th-map-layer-row.is-off .nm{color:var(--ink-dim);}\n.th-map-layer-row.is-empty{cursor:default;opacity:.45;}\n.th-map-layer-row.is-empty:hover{background:none;}\n.th-map-layer-row .bx{width:13px;height:13px;border-radius:4px;border:1.5px solid var(--line);flex-shrink:0;\n  display:flex;align-items:center;justify-content:center;font-size:9px;color:#fff;transition:all .16s;}\n.th-map-layer-row.is-on .bx{background:var(--accent-grad);border-color:transparent;}\n.th-map-layer-row .nm{font-size:11.5px;font-weight:700;color:var(--ink);}\n.th-map-layer-row .tag{margin-left:auto;font-size:9px;color:var(--ink-dim);font-weight:600;}\n.th-map-zoom-btn.is-open{color:var(--accent-deep);background:var(--accent-soft);}\n\n/* 底图层：行政区块色斑 + 铁道/河流。放在标记下面，纯装饰不吃事件 */\n.th-map-underlay{position:absolute;left:0;top:0;pointer-events:none;z-index:1;overflow:visible;}\n/* 铁道线：灰蓝细线，车站是空心圆点。用真实 N02 线形，比原来手绘的准 */\n.th-rail{stroke:#8fa3b8;stroke-opacity:.55;fill:none;stroke-linecap:round;stroke-linejoin:round;}\n.th-rail-st{fill:#fff;stroke:#8fa3b8;stroke-width:1.6;stroke-opacity:.9;}\n.th-map-underlay .area-fill{stroke-width:1.2;stroke-linejoin:round;}\n.th-map-underlay .route{fill:none;stroke-linecap:round;stroke-linejoin:round;}\n\n/* ===== 行政层级：日本 → 都道府县 → 市区町村 → 町丁目 ===== */\n/* 面包屑：显示当前视野落在哪一级，点任意一段回到那一级的范围 */\n.th-map-crumb{display:flex;align-items:center;gap:2px;flex-wrap:wrap;max-width:260px;\n  background:rgba(255,255,255,.9);border-radius:999px;padding:3px 8px;box-shadow:0 3px 10px rgba(0,0,0,.12);}\n.th-map-crumb:empty{display:none;}\n.th-map-crumb-seg{font-size:10.5px;font-weight:700;color:var(--ink-dim);padding:2px 6px;border-radius:999px;cursor:pointer;white-space:nowrap;transition:all .16s;border:none;background:none;font-family:inherit;}\n.th-map-crumb-seg:hover{background:var(--accent-soft);color:var(--accent-deep);}\n.th-map-crumb-seg.is-current{color:var(--accent-deep);background:var(--accent-soft);cursor:default;}\n.th-map-crumb-sep{font-size:9px;color:var(--ink-dim);opacity:.55;}\n\n/* 地区目录：和角色 / 剧情一样的抽屉式层级浏览，只是浮在地图上 */\n.th-map-dir-btn.is-open{color:var(--accent-deep);background:var(--accent-soft);}\n.th-map-dir{display:none;flex-direction:column;min-height:0;overflow:hidden;width:100%;}\n.th-map-dir.open{display:flex;}\n.th-map-dir-head{display:flex;align-items:center;justify-content:space-between;padding:11px 14px 9px;border-bottom:1px solid var(--line);}\n.th-map-dir-title{font-size:12.5px;font-weight:800;color:var(--ink);}\n.th-map-dir-close{width:20px;height:20px;border-radius:50%;border:none;background:var(--row);color:var(--ink-dim);font-size:12px;cursor:pointer;line-height:1;}\n.th-map-dir-close:hover{color:var(--accent-deep);}\n.th-map-dir-body{flex:1;overflow-y:auto;padding:6px 6px 10px;}\n.th-map-dir-row{display:flex;align-items:center;gap:6px;padding:5px 8px;border-radius:9px;cursor:pointer;transition:background .15s;}\n.th-map-dir-row:hover{background:var(--row);}\n.th-map-dir-row .tw{width:12px;flex-shrink:0;font-size:9px;color:var(--ink-dim);transition:transform .2s;}\n.th-map-dir-row.open .tw{transform:rotate(90deg);}\n.th-map-dir-row .nm{flex:1;font-size:11.5px;font-weight:700;color:var(--ink);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}\n.th-map-dir-row .ct{font-size:9.5px;font-weight:700;color:var(--ink-dim);background:var(--row);padding:1px 6px;border-radius:999px;flex-shrink:0;}\n.th-map-dir-row.lv2{padding-left:20px;}\n.th-map-dir-row.lv3{padding-left:34px;}\n.th-map-dir-row.lv4{padding-left:48px;}\n.th-map-dir-row.lv4 .nm{font-weight:600;font-size:11px;color:var(--ink-soft);}\n.th-map-dir-row.lv4.is-sel .nm{color:var(--accent-deep);font-weight:800;}\n/* 场景库：剧情里出现过但地图上没有坐标的场景 */\n.th-map-dir-sep{margin:8px 8px 4px;padding-top:8px;border-top:1px solid var(--line);font-size:9.5px;font-weight:800;color:var(--ink-dim);}\n.th-map-dir-row .band{font-size:9px;font-weight:700;padding:0 5px;border-radius:999px;flex-shrink:0;\n  background:color-mix(in srgb, var(--b-color,var(--accent)) 15%, #ffffff);color:var(--b-color,var(--accent));}\n.th-map-dir-row .q{font-size:9.5px;color:var(--ink-dim);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:96px;}\n.th-map-dir-row.has-pt .nm{color:var(--accent-deep);}\n.th-map-dir-row.has-pt .nm::after{content:' ↗';font-size:9px;}\n.th-map-card-admin{font-size:10.5px;color:var(--ink-dim);margin-bottom:7px;font-weight:600;}\n.th-map-card-admin b{color:var(--accent-deep);font-weight:800;}\n\n/* ================================================================\n   地图动效层 —— 对标谷歌地图的「镜头感」\n   分三类，互不纠缠，出问题可以单独摘掉：\n   A. 相机：飞行 / 惯性 / 平滑缩放，由 JS 的 rAF 驱动，这里只放过渡与落地态\n   B. 图层：底图淡入、换幅呼吸、加载骨架\n   C. 元素：标记入场、选中涟漪、聚合爆开、路线绘制、卡片入场\n   全部受 prefers-reduced-motion 约束，文件末尾统一关。\n   ================================================================ */\n\n/* —— A. 相机 —— */\n/* 飞行途中整张画布做一次 transform（translate+scale），标记跟着底图一起缩放，\n   缩放比超过阈值再落地重排。和 Leaflet 的 zoomAnimation 同一个路子：\n   一帧只改一个合成层属性，而不是把两三百个绝对定位元素重新算一遍。 */\n.th-map-canvas{backface-visibility:hidden;}\n.th-map-viewport.th-flying{cursor:default;}\n.th-map-viewport.th-flying .th-map-marker{pointer-events:none;}\n\n/* —— B. 图层 —— */\n/* 底图淡入：高清层压上来时是渐显而不是「啪」地盖住 */\n.th-map-basemap{opacity:0;transition:opacity .5s ease;}\n.th-map-basemap.is-loaded{opacity:1;}\n/* 换图幅：整层轻微放大着淡入，替代生硬瞬切 */\n@keyframes thSheetIn{from{opacity:0;transform:scale(1.045)}to{opacity:1;transform:scale(1)}}\n.th-map-basemaps.sheet-in{animation:thSheetIn .46s cubic-bezier(.22,1,.36,1);}\n/* 底图还在路上时，视口铺一层扫光，替代一片空白 */\n@keyframes thMapShimmer{from{background-position:-150% 0}to{background-position:250% 0}}\n.th-map-viewport::after{content:'';position:absolute;inset:0;z-index:1;pointer-events:none;opacity:0;\n  transition:opacity .3s;background:linear-gradient(100deg,transparent 38%,rgba(255,255,255,.55) 50%,transparent 62%);\n  background-size:220% 100%;}\n.th-map-viewport.th-loading::after{opacity:1;animation:thMapShimmer 1.25s linear infinite;}\n\n/* —— C. 元素 —— */\n/* 标记入场：只在「镜头停稳后」这一次渲染里给新出现的点加，飞行/拖动途中不放，\n   否则每次落地重排都会满屏乱蹦 */\n@keyframes thMarkerIn{\n  from{opacity:0;transform:translate(-50%,-50%) scale(.8);}\n  to{opacity:1;transform:translate(-50%,-50%) scale(1);}\n}\n.th-map-marker{transition:transform .18s cubic-bezier(.34,1.32,.5,1),box-shadow .18s ease;}\n.th-map-marker.is-new{animation:thMarkerIn .22s cubic-bezier(.25,.1,.25,1) backwards;animation-delay:var(--d,0ms);}\n.th-map-marker:hover{transform:translate(-50%,-50%) scale(1.3);}\n.th-map-marker.active{transform:translate(-50%,-50%) scale(1.24);}\n/* 选中涟漪：点开一个地点时向外荡两圈，和谷歌地图点 POI 的反馈同义。\n   只在「这一次选中」的那一帧挂上去 —— 挂在 .active 上的话，选中期间每次\n   落地重排都会重播一遍，拖着地图就一直在冒圈。 */\n@keyframes thPingRing{0%{transform:translate(-50%,-50%) scale(.55);opacity:.8}100%{transform:translate(-50%,-50%) scale(3.6);opacity:0}}\n.th-map-marker.ping::before{content:'';position:absolute;left:50%;top:50%;width:18px;height:18px;border-radius:50%;\n  border:2px solid var(--m-color,var(--accent));animation:thPingRing .9s ease-out 2;pointer-events:none;}\n/* 玩家位置：呼吸圈之外再加一圈静态柔光，就是谷歌那颗蓝点的「精度圈」 */\n.th-map-marker.player{box-shadow:0 0 0 7px rgba(62,207,106,.16),0 2px 8px rgba(0,0,0,.3);}\n/* 沿路定位（补丁 20）：人停在两个锚点之间时，钉子画在算出来的坐标上。\n   和锚点上那颗玩家点同一个绿，但小一圈、带方向箭头，一眼能看出「在路上，不是到了」。 */\n.th-map-onroute{position:absolute;z-index:9;width:16px;height:16px;margin:-8px 0 0 -8px;border-radius:50%;\n  background:#3ecf6a;border:2.5px solid #fff;box-shadow:0 0 0 6px rgba(62,207,106,.14),0 2px 8px rgba(0,0,0,.3);\n  cursor:default;}\n.th-map-onroute::after{content:'';position:absolute;left:50%;top:50%;width:14px;height:14px;margin:-7px 0 0 -7px;\n  border-radius:50%;border:2px solid #3ecf6a;animation:thPingRing 2.4s ease-out infinite;pointer-events:none;}\n.th-map-onroute-label{position:absolute;left:14px;top:50%;transform:translateY(-50%);white-space:nowrap;\n  font-size:9.5px;font-weight:700;color:#177f3d;background:rgba(255,255,255,.94);padding:1px 5px;\n  border-radius:5px;pointer-events:none;}\n/* 定位中间人（补丁 18）：钉子按可信度分三态，别让错钉子和对钉子长得一样。\n   存疑 = 位置照改但跨度可疑，琥珀色 + 精度圈改虚线；\n   保留 / 冻结 = 这一楼没能确认，位置停在上一个可信点，褪成灰色且不再呼吸。 */\n.th-map-marker.player.loc-weak{background:#e8a13a;box-shadow:0 0 0 7px rgba(232,161,58,.18),0 2px 8px rgba(0,0,0,.3);}\n.th-map-marker.player.loc-weak::after{border-style:dashed;}\n.th-map-marker.player.loc-weak .th-map-marker-label{color:#8a5200;}\n.th-map-marker.player.loc-held,.th-map-marker.player.loc-frozen{background:#98a2ac;\n  box-shadow:0 0 0 7px rgba(152,162,172,.16),0 2px 8px rgba(0,0,0,.25);}\n.th-map-marker.player.loc-held::after,.th-map-marker.player.loc-frozen::after{animation:none;opacity:.45;}\n.th-map-marker.player.loc-held .th-map-marker-label,\n.th-map-marker.player.loc-frozen .th-map-marker-label{color:#586169;}\n\n/* 路线：第一次画出来时沿线生长，之后交回给流动虚线 */\n@keyframes thRouteDraw{from{stroke-dashoffset:var(--len,2000)}to{stroke-dashoffset:0}}\n.th-map-route-line.is-drawing{stroke-dasharray:var(--len,2000);animation:thRouteDraw .95s cubic-bezier(.33,.9,.4,1) forwards;}\n\n/* 地点卡片 / 搜索结果 / 导航面板：入场 */\n@keyframes thCardIn{from{opacity:0;transform:translateY(9px) scale(.97)}to{opacity:1;transform:none}}\n\n.th-map-nav.is-in{animation:thCardIn .28s cubic-bezier(.22,1,.36,1);}\n@keyframes thResultIn{from{opacity:0;transform:translateY(-5px)}to{opacity:1;transform:none}}\n.th-map-result{animation:thResultIn .22s ease backwards;animation-delay:var(--d,0ms);}\n/* 缩放按钮：按下去有回弹 */\n.th-map-zoom-btn{transition:transform .16s cubic-bezier(.34,1.3,.5,1),color .16s,background .16s,box-shadow .16s;}\n.th-map-zoom-btn:active{transform:scale(.88);}\n/* 「回到我的位置」：没有解析到玩家位置时置灰 */\n.th-map-locate-btn.is-off{opacity:.4;cursor:default;}\n.th-map-locate-btn.is-on{color:#177f3d;background:rgba(62,207,106,.16);}\n\n/* —— 比例尺：谷歌地图右下角那根，和 m/px 芯片互补（一个给尺度感，一个给精度） —— */\n.th-map-scale{position:absolute;right:50px;bottom:12px;z-index:11;pointer-events:none;\n  display:flex;flex-direction:column;align-items:flex-end;gap:2px;}\n.th-map-scale-bar{height:6px;min-width:24px;border:1.5px solid rgba(80,92,110,.55);border-top:none;\n  background:rgba(255,255,255,.5);transition:width .12s linear;}\n.th-map-scale-txt{font-size:9.5px;font-weight:700;color:var(--ink-dim);\n  background:rgba(255,255,255,.85);padding:0 5px;border-radius:4px;line-height:1.5;}\n\n/* —— 落点图钉：点地图空白处丢一个钉子，读出经纬度（谷歌的 dropped pin）—— */\n.th-map-droppin{position:absolute;z-index:10;width:26px;height:36px;margin:0;cursor:pointer;\n  transform:translate(-50%,-100%);filter:drop-shadow(0 3px 4px rgba(0,0,0,.35));}\n.th-map-droppin svg{width:100%;height:100%;display:block;}\n.th-map-droppin .body{fill:#4a5568;}\n.th-map-droppin .hole{fill:#fff;}\n@keyframes thPinDrop{\n  0%  {opacity:0;transform:translate(-50%,-100%) translateY(-26px) scale(.8);}\n  65% {opacity:1;transform:translate(-50%,-100%) translateY(0) scale(1.06);}\n  100%{opacity:1;transform:translate(-50%,-100%) translateY(0) scale(1);}\n}\n.th-map-droppin.is-new{animation:thPinDrop .38s cubic-bezier(.3,1.5,.5,1);}\n.th-map-pincard{position:absolute;left:50%;bottom:34px;transform:translateX(-50%);z-index:13;\n  width:min(330px,calc(100% - 24px));background:var(--card);border-radius:14px;padding:10px 12px;\n  border:1px solid var(--line);border-top:3px solid #4a5568;box-shadow:0 8px 26px rgba(0,0,0,.2);}\n.th-map-pincard[hidden]{display:none;}\n.th-map-pincard .h{display:flex;align-items:center;gap:6px;margin-bottom:5px;}\n.th-map-pincard .t{font-size:12.5px;font-weight:800;color:var(--ink);}\n.th-map-pincard .x{margin-left:auto;border:none;background:var(--row);color:var(--ink-dim);\n  width:20px;height:20px;border-radius:50%;font-size:12px;line-height:1;cursor:pointer;}\n.th-map-pincard .x:hover{color:var(--accent-deep);}\n.th-map-pincard .ll{font-family:ui-monospace,'SFMono-Regular',Consolas,monospace;font-size:12.5px;\n  color:var(--ink);user-select:all;cursor:text;}\n.th-map-pincard .meta{font-size:10.5px;color:var(--ink-dim);margin-top:4px;line-height:1.7;}\n.th-map-pincard .meta b{color:var(--ink-soft);font-weight:700;}\n.th-map-pincard .copy{margin-top:7px;width:100%;height:26px;border:none;border-radius:8px;\n  background:var(--row);color:var(--ink-soft);font:inherit;font-size:11px;font-weight:700;cursor:pointer;}\n.th-map-pincard .copy:hover{background:var(--accent-soft);color:var(--accent-deep);}\n/* —— 无障碍：系统开了「减少动态效果」就整块关掉，只留位移本身 —— */\n@media (prefers-reduced-motion: reduce){\n  .th-map-basemaps.sheet-in,.th-map-marker.is-new,.th-map-marker.ping::before,\n  .th-map-route-line,.th-map-route-line.is-drawing,\n  .th-map-card.is-in,.th-map-nav.is-in,.th-map-result,\n  .th-map-viewport.th-loading::after,.th-map-marker.player::after,\n  .th-map-droppin.is-new{animation:none!important;}\n  .th-map-basemap{transition:none;}\n  .th-map-scale-bar{transition:none;}\n}\n\n/* 剧情页：主屏是\"当前时间线\"仪表盘，完整的 年份→乐队/联动→事件 归档\n   放在右侧抽屉里浏览（与角色版块\"乐队→成员\"抽屉同款交互，彼此独立） */\n.th-story-band-mark{display:flex;align-items:center;justify-content:center;width:100%;height:100%;font-family:var(--font-display);font-weight:800;font-size:15px;color:var(--accent-deep);background:var(--accent-soft);border-radius:12px;letter-spacing:.5px;}\n.th-story-node{padding:14px 18px;background:var(--card);border-radius:16px;margin-bottom:12px;transition:all 0.25s;cursor:default;box-shadow:var(--shadow);}\n.th-story-node:hover{transform:translateX(4px);}\n.th-story-node:last-child{margin-bottom:0;}\n.th-story-node-num{display:inline-flex;align-items:center;justify-content:center;width:22px;height:22px;border-radius:8px;background:var(--accent-deep);color:#fff;font-size:11px;font-weight:700;font-family:var(--font-display);margin-right:9px;flex-shrink:0;}\n.th-story-node-header{display:flex;align-items:center;margin-bottom:6px;}\n.th-story-node-title{font-size:14px;font-weight:700;color:var(--ink);}\n.th-story-node-desc{font-size:12.5px;color:var(--ink-soft);line-height:1.7;padding-left:31px;min-height:2.8em;}\n\n.th-archive-crumb-back{display:inline-flex;align-items:center;gap:2px;font-size:13px;font-weight:700;color:var(--ink-dim);cursor:pointer;white-space:nowrap;margin-bottom:14px;}\n.th-archive-crumb-back:hover{color:var(--accent-deep);}\n.th-archive-crumb-back .th-icon{color:inherit;filter:none;}\n\n.th-archive-empty{padding:30px 10px;text-align:center;color:var(--ink-dim);font-size:13px;line-height:1.8;}\n.th-archive-detail-title{font-size:19px;font-weight:900;color:var(--ink);margin-bottom:4px;}\n.th-archive-detail-band{font-size:12px;font-weight:700;margin-bottom:18px;}\n\n#page-story{position:relative;overflow:hidden;transition:height .32s cubic-bezier(.22,1,.36,1);}\n.th-story-dash, .th-story-event-view{max-width:700px;margin:0 auto;width:100%;}\n\n.th-story-time-card{background:var(--card);border-radius:16px;box-shadow:var(--shadow);border-left:5px solid var(--accent);padding:14px 18px;margin-bottom:22px;}\n.th-story-time-label{font-size:11px;color:var(--accent-deep);letter-spacing:.5px;font-weight:700;margin-bottom:4px;}\n.th-story-time-text{font-size:15px;color:var(--ink);font-weight:700;}\n\n.th-story-timeline{position:relative;margin:0 10px 26px;padding-top:4px;}\n.th-story-timeline-line{position:absolute;top:15px;left:0;right:0;height:3px;background:var(--line);border-radius:2px;}\n.th-story-timeline-fill{position:absolute;top:15px;left:0;height:3px;background:var(--accent-grad);border-radius:2px;transition:width .3s;}\n.th-story-timeline-points{display:flex;justify-content:space-between;position:relative;}\n.th-story-timeline-point{display:flex;flex-direction:column;align-items:center;gap:6px;}\n.th-story-timeline-dot{width:11px;height:11px;border-radius:50%;background:var(--line);}\n.th-story-timeline-point.past .th-story-timeline-dot{background:var(--accent);}\n.th-story-timeline-point.current .th-story-timeline-dot{width:15px;height:15px;background:var(--accent);box-shadow:0 0 0 4px var(--accent-soft);}\n.th-story-timeline-year{font-size:12px;font-weight:700;color:var(--ink-dim);}\n.th-story-timeline-point.current .th-story-timeline-year{color:var(--accent-deep);font-weight:800;}\n.th-story-timeline-now{font-size:10px;color:var(--accent-deep);font-weight:700;}\n\n/* 当前年份远离内容范围时（比如从 1942 或 2042 开始玩）的压缩时间线 */\n.th-story-timeline-compressed{display:flex;align-items:flex-start;gap:10px;}\n.th-story-timeline-gap{flex:1;display:flex;flex-direction:column;align-items:center;gap:4px;padding-top:7px;min-width:0;}\n.th-story-timeline-gap-line{width:100%;height:3px;border-radius:2px;background-repeat:repeat-x;}\n.th-story-timeline-gap-line.muted{background-image:repeating-linear-gradient(90deg,var(--line) 0,var(--line) 4px,transparent 4px,transparent 8px);}\n.th-story-timeline-gap-line.accent{background-image:repeating-linear-gradient(90deg,var(--accent) 0,var(--accent) 4px,transparent 4px,transparent 8px);}\n.th-story-timeline-gap-label{font-size:10.5px;color:var(--ink-dim);font-weight:700;white-space:nowrap;}\n.th-story-timeline-note{text-align:center;font-size:11.5px;color:var(--ink-dim);margin-top:10px;}\n\n.th-story-bands-label{font-size:11px;color:var(--ink-dim);letter-spacing:1px;font-weight:700;margin-bottom:10px;}\n.th-story-bands-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-bottom:18px;}\n.th-story-band-tile{background:var(--card);border-radius:14px;box-shadow:var(--shadow);padding:10px 8px;text-align:center;position:relative;cursor:pointer;transition:transform .2s,box-shadow .2s;}\n.th-story-band-tile:hover{transform:translateY(-3px);box-shadow:0 8px 18px rgba(90,60,110,.14);}\n.th-story-band-tile:active{transform:translateY(-1px) scale(.97);}\n\n.th-page, .th-story-dash, .th-story-event-view{transition:opacity .22s ease, transform .22s ease;opacity:1;transform:scale(1);transform-origin:top center;}\n.th-page.th-view-shr