-transform:uppercase;font-family:var(--font-display);}\n.th-activity-section-title .th-icon{color:var(--ink-dim);filter:none;}\n.th-activity-sub{font-family:var(--font-body);letter-spacing:0;text-transform:none;font-weight:600;font-size:11.5px;color:var(--ink-soft);margin-left:4px;}\n/* 「清空」：最近动态标题右边，一次删掉现在列着的全部（DESIGN「动态页写上原因」） */\n.th-activity-clear{margin-left:auto;font-family:var(--font-body);letter-spacing:0;text-transform:none;font-size:11.5px;font-weight:800;color:var(--ink-soft);background:none;border:0;border-radius:999px;padding:4px 10px;cursor:pointer;transition:background .2s ease,color .2s ease;}\n.th-activity-clear:hover,.th-activity-clear:focus-visible{background:var(--card-2);color:var(--accent-deep);outline:none;}\n.th-activity-clear[hidden]{display:none;}\n\n.th-presence-strip{display:flex;flex-wrap:wrap;gap:16px;background:var(--card);border-radius:16px;box-shadow:var(--shadow);padding:16px;min-height:20px;}\n.th-presence-empty{color:var(--ink-dim);font-size:13px;padding:6px 2px;}\n.th-presence-chip{display:flex;flex-direction:column;align-items:center;gap:6px;cursor:pointer;width:60px;transition:transform .2s ease;}\n.th-presence-chip:hover{transform:translateY(-3px);}\n.th-presence-avatar{position:relative;width:44px;height:44px;border-radius:50%;background:#ffffff;border:2px solid var(--p-color,var(--accent));display:flex;align-items:center;justify-content:center;box-shadow:0 3px 8px rgba(0,0,0,.12);overflow:hidden;}\n.th-presence-avatar .th-instrument-icon{color:var(--p-color,var(--ink));filter:none;}\n.th-presence-avatar-img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;border-radius:50%;}\n.th-presence-dot{position:absolute;bottom:-1px;right:12px;width:10px;height:10px;border-radius:50%;background:#3ecf6a;border:2px solid #fff;animation:presencePulse 2s ease-in-out infinite;z-index:1;}\n@keyframes presencePulse{0%,100%{box-shadow:0 0 0 0 rgba(62,207,106,.5)}50%{box-shadow:0 0 0 4px rgba(62,207,106,0)}}\n.th-presence-name{font-size:11px;color:var(--ink-soft);font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:60px;}\n\n.th-activity-feed{display:flex;flex-direction:column;gap:8px;}\n/* 一行两层：上层名字 + 涨跌签，下层原因 + 时段；横着滑留给手指（竖着照常滚） */\n.th-activity-item{position:relative;display:flex;align-items:center;gap:12px;background:var(--card);border-radius:14px;box-shadow:var(--shadow);padding:10px 14px;cursor:pointer;transition:transform .2s ease;touch-action:pan-y;}\n.th-activity-item:hover{transform:translateX(3px);}\n.th-activity-avatar{position:relative;flex:0 0 auto;width:32px;height:32px;border-radius:10px;display:flex;align-items:center;justify-content:center;background:#ffffff;border:1.5px solid var(--line);box-shadow:0 2px 5px rgba(0,0,0,.08);overflow:hidden;}\n.th-activity-avatar .th-instrument-icon{width:16px;height:16px;color:#3a3a46;filter:none;}\n.th-activity-avatar-img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;border-radius:8px;}\n.th-activity-main{flex:1;display:flex;flex-direction:column;gap:2px;min-width:0;}\n.th-activity-line{display:flex;align-items:center;gap:10px;min-width:0;}\n.th-activity-name{font-size:13px;font-weight:700;color:var(--ink);white-space:nowrap;}\n.th-activity-delta{font-size:11.5px;font-weight:700;color:#fff;padding:3px 10px;border-radius:20px;text-shadow:0 1px 2px rgba(0,0,0,.2);white-space:nowrap;flex-shrink:0;}\n/* 不带数的变化：灰签「初次见面」「记事」，和涨跌签同尺寸 */\n.th-activity-tag{background:var(--card-2);color:var(--ink-soft);text-shadow:none;}\n.th-activity-meta{display:flex;align-items:baseline;gap:10px;min-width:0;}\n.th-activity-why{flex:1;min-width:0;font-size:12px;font-weight:500;color:var(--ink-soft);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}\n.th-activity-time{flex:none;margin-left:auto;font-size:11px;font-weight:600;color:var(--ink-dim);white-space:nowrap;}\n/* 好感跨了七档的分界：第三层一枚小签「关系 普通朋友 → 在意的人」，应援色 14% 混白的底 */\n.th-activity-stage{margin-top:4px;}\n.th-activity-stage span{display:inline-flex;a