,visibility 0s .14s;}\n/* 收起：卡片宽度收到 68px，内容淡出、窄轨淡入 */\n.th-map-content.side-collapsed .th-map-side{width:68px;}\n.th-map-content.side-collapsed .th-map-side-main{opacity:0;transform:translateX(-24px);visibility:hidden;pointer-events:none;\n  transition:opacity .14s ease,transform .34s cubic-bezier(.22,1,.36,1),visibility 0s .34s;}\n.th-map-content.side-collapsed .th-map-side-rail{opacity:1;visibility:visible;pointer-events:auto;transition:opacity .24s ease .1s,visibility 0s;}\n\n/* 标题区：Fredoka 小标 + 淡水印大字 */\n.th-map-side-head{position:relative;display:flex;align-items:flex-start;justify-content:space-between;gap:8px;flex-shrink:0;}\n.th-map-side-wm{position:absolute;right:0;bottom:-10px;font-family:var(--font-display);font-weight:700;font-size:36px;letter-spacing:2px;\n  color:rgba(60,50,70,.05);white-space:nowrap;line-height:1;pointer-events:none;user-select:none;}\n.th-map-side-titles{position:relative;display:flex;flex-direction:column;gap:3px;min-width:0;}\n.th-map-side-kicker{display:inline-flex;align-items:center;gap:3px;align-self:flex-start;border:0;background:none;padding:0;cursor:pointer;\n  font-family:var(--font-display)!important;font-size:11px;font-weight:700;letter-spacing:.16em;color:var(--accent-deep);}\n.th-map-side-kicker svg{width:12px;height:12px;}\n.th-map-side-kicker:hover{opacity:.72;}\n.th-map-side-title{font-size:20px;font-weight:900;color:var(--ink);line-height:1.3;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}\n.th-map-side .th-map-crumb{display:flex;flex-wrap:nowrap;align-items:center;gap:4px;max-width:100%;overflow:hidden;background:none;box-shadow:none;\n  border-radius:0;padding:0;font-size:11.5px;color:var(--ink-soft);white-space:nowrap;}\n.th-map-side .th-map-crumb:empty{display:none;}\n.th-map-side .th-map-crumb button{flex:0 1 auto;min-width:0;border:0;background:none;padding:0;font-size:11.5px;font-weight:500;color:var(--ink-soft);\n  cursor:pointer;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}\n.th-map-side .th-map-crumb button:hover{color:var(--accent-deep);}\n.th-map-side .th-map-crumb span{color:var(--ink-dim);flex-shrink:0;}\n.th-map-side-fold{flex-shrink:0;display:flex;align-items:center;justify-content:center;width:32px;height:32px;border:0;border-radius:10px;\n  background:var(--row);color:var(--ink-soft);cursor:pointer;transition:color .15s,background .15s;}\n.th-map-side-fold svg{width:17px;height:17px;}\n.th-map-side-fold:hover{color:var(--accent-deep);background:var(--accent-soft);}\n\n/* 搜索框 */\n.th-map-side .th-map-search{display:flex;flex-direction:column;gap:10px;min-height:0;flex-shrink:0;width:auto;}\n.th-map-side .th-map-search:has(.th-map-search-results:not(:empty)){flex:1 1 auto;}\n.th-map-side .th-map-search-field{display:flex;align-items:center;gap:9px;height:40px;box-sizing:border-box;padding:0 4px 0 12px;\n  border-radius:12px;background:var(--card);border:1.5px solid var(--line);flex-shrink:0;transition:border-color .15s;}\n.th-map-side .th-map-search-field:focus-within{border-color:color-mix(in srgb,var(--accent) 45%,var(--line));}\n.th-map-side .th-map-search-field>svg{position:static;width:16px;height:16px;flex-shrink:0;}\n.th-map-side .th-map-search input{flex:1;min-width:0;width:auto;height:100%;padding:0;border:0;border-radius:0;background:transparent;box-shadow:none;font-size:13px;}\n.th-map-side .th-map-search input:hover,.th-map-side .th-map-search input:focus{box-shadow:none;}\n.th-map-side .th-map-search input:focus-visible{outline:none;}\n.th-map-side #th-map-search-clear{position:static;width:30px;height:30px;font-size:18px;flex-shrink:0;}\n\n/* 分类：一行横滑；还没滑完的那一头渐隐（14 里按滚动位置挂 can-l / can-r），鼠标拖的时候不选字 */\n.th-map-side .th-map-search-cats{display:flex;flex-wrap:nowrap;gap:6px;margin:0;padding:2px 0;overflow-x:auto;scrollbar-width:none;background:none;\n  box-shadow:none;border-radius:0;flex-shrink:0;}\n.th-map-side .th-map-search-cats.can-r{-webkit-mask-image:linear-gradient(90deg,#000 calc(100% - 36px),transparent);mask-image:l