ap-side .th-map-book-mark{padding:6px 10px 6px 28px;}\n.th-map-side .th-map-book-mark::before{content:'';position:absolute;left:15px;top:50%;width:6px;height:6px;margin-top:-3px;border-radius:50%;\n  background:var(--line);transition:background .15s;}\n.th-map-side .th-map-book-mark:hover::before{background:var(--accent);}\n.th-map-side .th-map-book-mark .nm{font-size:12.5px;font-weight:600;color:var(--ink-soft);}\n.th-map-side .th-map-book-mark:hover .nm{color:var(--ink);}\n.th-map-side .th-map-book-mark .mt{display:none;}\n.th-map-side .th-map-book-off .nm{color:var(--ink-dim);}\n.th-map-side .th-map-dir-body{padding:0 2px 8px;}\n.th-map-side .th-map-dir-row{gap:8px;padding:8px;border-radius:10px;}\n.th-map-side .th-map-dir-row:hover{background:#f8f5fb;}\n.th-map-side .th-map-dir-row .tw{font-size:9px;color:var(--ink-soft);}\n.th-map-side .th-map-dir-row .nm{font-size:13px;font-weight:700;}\n.th-map-side .th-map-dir-row.lv2 .nm{font-size:12.5px;font-weight:600;}\n.th-map-side .th-map-dir-row.lv3 .nm{font-size:12.5px;font-weight:500;color:var(--ink-soft);}\n.th-map-side .th-map-dir-row.lv4 .nm{font-size:12px;}\n.th-map-side .th-map-dir-row .ct{font-family:var(--font-display);font-size:11px;font-weight:600;color:var(--ink-soft);background:var(--row);padding:1px 8px;}\n\n/* 收起：68px 窄轨 */\n.th-map-side-rail .th-map-side-fold{width:36px;height:36px;}\n.th-map-side-rail .th-map-side-kicker{align-self:center;font-size:10px;letter-spacing:.12em;}\n.th-map-side-railbtn{display:flex;align-items:center;justify-content:center;width:40px;height:40px;box-sizing:border-box;border-radius:12px;\n  border:1.5px solid var(--line);background:var(--card);color:var(--ink-soft);cursor:pointer;flex-shrink:0;}\n.th-map-side-railbtn svg{width:17px;height:17px;}\n.th-map-side-divider{width:30px;height:1px;background:var(--line);flex-shrink:0;}\n.th-map-side-railcats{display:flex;flex-direction:column;gap:2px;}\n.th-map-side-railcats button{display:flex;flex-direction:column;align-items:center;gap:3px;width:58px;padding:3px 0;border:0;background:none;cursor:pointer;}\n.th-map-side-railcats .th-map-side-tile{width:32px;height:32px;}\n.th-map-side-railcats .th-map-side-tile svg{width:16px;height:16px;}\n.th-map-side-railcats button>span:last-child{font-size:10.5px;font-weight:700;color:var(--ink-soft);}\n.th-map-side-railcats button[aria-pressed=\"true\"] .th-map-side-tile{background:var(--accent-soft);color:var(--accent-deep);}\n.th-map-side-railcats button[aria-pressed=\"true\"]>span:last-child{color:var(--accent-deep);}\n\n/* 收起后，选中的地点留一张小卡在窄轨右边 */\n.th-map-mini{position:absolute;left:var(--side-x);bottom:14px;z-index:13;width:min(316px,calc(100% - 180px));box-sizing:border-box;padding:12px;\n  border-radius:16px;background:var(--card);box-shadow:0 8px 26px rgba(0,0,0,.18);display:flex;flex-direction:column;gap:10px;\n  animation:thCardIn .26s cubic-bezier(.22,1,.36,1);}\n.th-map-mini[hidden],.th-map-content:not(.side-collapsed) .th-map-mini,.th-map-content.is-compact .th-map-mini{display:none;}\n.th-map-mini-row{display:flex;align-items:center;gap:10px;min-width:0;}\n\n/* 地图上的控件：图层在右上，比例尺、导航面板跟着侧栏右边缘走 */\n.th-map-content .th-map-layer-control{left:auto;right:14px;top:14px;bottom:auto;padding-top:0;}\n.th-map-content .th-map-layer-thumb{width:40px;height:40px;border:0;border-radius:12px;background:var(--card);box-shadow:0 2px 8px rgba(0,0,0,.16);\n  display:flex;align-items:center;justify-content:center;color:var(--ink);}\n.th-map-content .th-map-layer-thumb img,.th-map-content .th-map-layer-thumb>span{display:none!important;}\n.th-map-layer-ic{width:18px;height:18px;}\n.th-map-content .th-map-layer-thumb.is-open{outline:none;background:var(--accent-soft);color:var(--accent-deep);}\n.th-map-content .th-map-layers{left:auto;right:0;top:calc(100% + 8px);bottom:auto;}\n.th-map-zoom-btn svg{width:18px;height:18px;}\n.th-map-content .th-map-scale{left:var(--side-x);bottom:14px;transition:left .34s cubic-bezier(.22,1,.36,1);}\n.th-map-content.side-collapsed