ld{height:46px;border-radius:23px;}\n.th-map-content.is-compact .th-map-side .th-map-search input{font-size:14px;}\n.th-map-content.is-compact .th-map-side .th-map-search-cats button{height:36px;padding:0 13px;font-size:12.5px;}\n.th-map-content.is-compact.sheet-peek .th-map-side-body{display:none;}\n.th-map-content.is-compact.sheet-peek .th-map-side-peek{display:block;}\n.th-map-content.is-compact .th-map-side-row{min-height:56px;}\n.th-map-content.is-compact .th-map-side-tile{width:40px;height:40px;border-radius:13px;}\n.th-map-content.is-compact .th-map-side-tile svg{width:19px;height:19px;}\n.th-map-content.is-compact .th-map-side-texts .nm{font-size:14.5px;}\n.th-map-content.is-compact .th-map-side-acts button{height:44px;border-radius:12px;font-size:14px;}\n.th-map-side-peekcard{display:flex;align-items:center;gap:10px;padding:8px 8px 8px 10px;border-radius:16px;background:var(--card);border:1px solid var(--line);\n  box-shadow:0 4px 14px rgba(70,50,90,.10);animation:thCardIn .26s cubic-bezier(.22,1,.36,1);}\n.th-map-side-peekcard .th-map-side-row{padding:0;min-height:0;flex:1;min-width:0;}\n.th-map-side-peekcard .th-map-side-row:hover{background:none;}\n.th-map-side-peekgo{flex-shrink:0;display:flex;align-items:center;justify-content:center;width:46px;height:46px;border:0;border-radius:23px;\n  background:var(--accent-grad);color:#fff;cursor:pointer;}\n.th-map-side-peekgo svg{width:20px;height:20px;}\n/* 缩放按钮留在 OSM 署名上面（宽屏也是这样让开的）。不挂过渡：抽屉动画时 --map-dock 每帧都在变，按钮逐帧跟着抽屉走，\n   挂了过渡反而每帧重新起跑，会落后抽屉一截、被压住 */\n.th-map-viewport.is-compact .th-map-zoom{bottom:calc(32px + var(--map-dock));right:12px;}\n.th-map-content.is-compact:not(.sheet-peek) #th-map-zoom-in,.th-map-content.is-compact:not(.sheet-peek) #th-map-zoom-out{display:none;}\n.th-map-content.is-compact:not(.sheet-peek) #th-map-locate{margin-bottom:0;}\n.th-map-viewport.is-compact .th-map-scale{left:12px;bottom:calc(14px + var(--map-dock));}\n.th-map-content.is-compact:not(.sheet-peek) .th-map-scale{visibility:hidden;}\n.th-map-viewport.is-compact .th-map-badge{bottom:calc(5px + var(--map-dock));}\n.th-map-viewport.is-compact .th-map-layer-control{top:12px;right:12px;bottom:auto;}\n.th-map-content.is-compact .th-map-nav{top:10px;left:10px;right:62px;width:auto;bottom:auto;max-height:40%;border-radius:16px;}\n\n/* 切换动画：详情从右边滑进来，地图册从下面浮上来，回到列表从左边回来 */\n@keyframes thSideIn{from{opacity:0;transform:translateX(16px)}to{opacity:1;transform:none}}\n@keyframes thSideUp{from{opacity:0;transform:translateY(12px)}to{opacity:1;transform:none}}\n@keyframes thSideBack{from{opacity:0;transform:translateX(-12px)}to{opacity:1;transform:none}}\n@keyframes thSideFade{from{opacity:0}to{opacity:1}}\n.th-map-side .th-map-detail.is-open{animation:thSideIn .3s cubic-bezier(.22,1,.36,1);}\n.th-map-side .th-map-explorer:not([hidden]){animation:thSideUp .3s cubic-bezier(.22,1,.36,1);}\n.th-map-side .th-map-book.open,.th-map-side .th-map-dir.open{animation:thSideFade .22s ease;}\n.th-map-side.view-list .th-map-side-list{animation:thSideBack .26s cubic-bezier(.22,1,.36,1);}\n.th-map-side-card.is-new{animation:thCardIn .26s cubic-bezier(.22,1,.36,1);}\n.th-map-side .th-map-search-results:not(:empty){animation:thSideFade .18s ease;}\n@media (prefers-reduced-motion: reduce){\n  .th-map-side,.th-map-side *,.th-map-mini,.th-map-content .th-map-scale,.th-map-content .th-map-nav{animation:none!important;transition:none!important;}\n}\n\n/* ===== 补丁 19：主角状态页 = 资料卡 + 把手翻面 ===================== */\n.th-pc-stage{perspective:1800px;max-width:980px;margin:0 auto;width:100%;}\n/* 高度由正面的资料卡撑，背面比正面矮，塞得进；写死 min-height 底下会多一截空白 */\n.th-pc-flip{position:relative;transform-style:preserve-3d;transition:transform .7s cubic-bezier(.4,.1,.2,1);}\n.th-pc-flip.flipped{transform:rotateY(180deg);}\n.th-pc-front,.th-pc-back{backface-visibility:hidden;-webkit-backface-visibility:hidden;}\n.th-pc-flip.flipped .th-pc-front{pointer-events:none;}\n.th-pc-back{position:absolute;inset:0;transform:rotateY(180deg);background:var(--card);border-radius:22px;\n  box-shadow:var(--shadow);padding:26px 32px 30px;display:flex;flex-direction:column;pointer-events:none;}\n.th-pc-flip.flipped .th-pc-back{pointer-events:auto;}\n/* 同主要角色页的翻面：转到侧对着的那一刻换面，Firefox 上正面不会镜像透到背面 */\n.th-pc-front{transition:visibility 0s linear .23s;}\n.th-pc-flip.flipped .th-pc-front{visibility:hidden;}\n.th-pc-back{visibility:hidden;transition:visibility 0s linear .23s;}\n.th-pc-flip.flipped .th-pc-back{visibility:visible;}\n\n.th-pc-card{position:relative;overflow:hidden;display:flex;align-items:center;gap:44px;background:var(--card);\n  border-radius:22px;box-shadow:var(--shadow);padding:36px 44px;}\n/* 水印：永远 132px，放不下才加 .bleed 把尾巴化掉 */\n.th-pc-wm{position:absolute;top:-10px;left:16px;font-family:var(--font-display);font-weight:900;font-size:132px;\n  letter-spacing:2px;text-transform:uppercase;color:color-mix(in srgb,var(--ink) 9%,transparent);\n  white-space:nowrap;pointer-events:none;z-index:0;line-height:1;}\n.th-pc-wm:empty{display:none;}\n.th-pc-wm.bleed{-webkit-mask-image:linear-gradient(90deg,#000 62%,rgba(0,0,0,0) 97%);\n  mask-image:linear-gradient(90deg,#000 62%,rgba(0,0,0,0) 97%);}\n/* 把手：照 .th-toggle-sidebar 的尺寸和渐变 */\n.th-pc-handle{position:absolute;top:26px;right:18px;z-index:25;width:36px;height:36px;border-radius:50%;\n  background:var(--accent-grad);border:none;color:#fff;cursor:pointer;display:flex;align-items:center;\n  justify-content:center;box-shadow:0 6px 16px var(--accent-glow);transition:transform .35s ease;}\n.th-pc-handle:hover{transform:scale(1.08);}\n.th-pc-handle .th-icon{color:#fff;filter:none;}\n\n.th-pc-left{position:relative;flex:1 1 452px;min-width:0;display:flex;flex-direction:column;}\n.th-pc-tags{display:flex;flex-wrap:wrap;gap:6px;margin-bottom:16px;min-height:22px;}\n.th-pc-tag{font-size:12px;color:var(--ink-soft);background:var(--row);padding:4px 12px;border-radius:20px;font-weight:600;}\n.th-pc-tag.lead{color:var(--accent-deep);background:var(--accent-soft);font-weight:700;}\n.th-pc-name{font-size:32px;font-weight:900;letter-spacing:.3px;color:var(--ink);line-height:1.15;}\n.th-pc-romaji{font-family:var(--font-display);font-size:12.5px;letter-spacing:.14em;color:var(--ink-soft);\n  margin-top:5px;font-weight:600;min-height:17px;}\n.th-pc-rule{position:relative;height:2px;border-radius:2px;background:var(--line);margin:22px 0 20px;}\n.th-pc-rule i{position:absolute;left:0;top:0;width:34px;height:2px;border-radius:2px;background:var(--accent);\n  box-shadow:0 0 8px var(--accent-glow);}\n.th-pc-grid{display:grid;grid-template-columns:minmax(0,1fr) 2px minmax(0,1fr);column-gap:22px;}\n.th-pc-col{display:flex;flex-direction:column;gap:16px;}\n.th-pc-vline{width:2px;border-radius:2px;background:var(--line);}\n.th-pc-field{display:flex;flex-direction:column;gap:6px;}\n.th-pc-label{font-size:11px;color:var(--ink-dim);letter-spacing:1.5px;font-weight:700;}\n.th-pc-hp{display:flex;align-items:center;gap:10px;}\n.th-pc-hp .th-bar-track{flex-grow:1;}\n.th-pc-hppct{font-family:var(--font-display);font-size:13px;color:var(--accent-deep);font-weight:700;flex-shrink:0;}\n.th-pc-conds{display:flex;flex-wrap:wrap;gap:6px;}\n.th-pc-cond{display:inline-flex;background:var(--row);color:var(--ink-soft);padding:4px 14px;border-radius:999px;\n  font-size:13px;letter-spacing:.1em;font-weight:700;}\n.th-pc-cond.hot{background:var(--accent);color:#fff;text-shadow:0 1px 2px rgba(0,0,0,.25);}\n.th-pc-money{display:inline-flex;width:fit-content;background:var(--accent-deep);color:#fff;\n  text-shadow:0 1px 2px rgba(0,0,0,.25);padding:5px 15px;border-radius:9px;font-family:var(--font-display);\n  font-size:16px;letter-spacing:.03em;font-weight:600;}\n.th-pc-wear{font-size:14px;color:var(--ink);font-weight:700;line-height:1.5;}\n.th-pc-next{display:flex;align-items:center;gap:10px;background:var(--card-2);border-radius:12px;\n  padding:10px 14px;margin-top:22px;}\n.th-pc-next .th-icon{color:var(--accent-deep);filter:none;}\n.th-pc-next-k{font-size:11px;color:var(--ink-soft);font-weight:700;letter-spacing:1px;}\n.th-pc-next-k,.th-pc-next-t{flex:none;white-space:nowrap;}   /* 卡窄了只让事项折行，「接下来」和时间不拆开 */\n.th-pc-next-t{font-family:var(--font-display);font-size:12.5px;color:var(--accent-deep);font-weight:700;}\n.th-pc-next-v{font-size:12.5px;color:var(--ink);font-weight:600;}\n.th-pc-right{position:relative;flex:0 1 266px;min-width:0;}\n.th-pc-portrait{width:100%;aspect-ratio:266/355;border-radius:22px;background:var(--card-2);border:3px solid var(--card);\n  box-shadow:var(--shadow),0 0 0 1px var(--line);display:flex;flex-direction:column;align-items:center;\n  justify-content:center;gap:12px;cursor:pointer;}\n.th-pc-portrait .th-icon{width:92px;height:92px;color:var(--ink-dim);filter:none;}\n.th-pc-portrait span{font-size:12.5px;color:var(--ink-soft);font-weight:600;letter-spacing:.5px;}\n.th-pc-portrait img{width:100%;height:100%;object-fit:cover;border-radius:19px;}\n\n/* —— 背面：返回 + 分段条 + 两屏横滑 —— */\n.th-pc-backhead{display:flex;align-items:center;justify-content:space-between;margin-bottom:18px;flex-shrink:0;}\n.th-pc-return{background:none;border:none;color:var(--ink-soft);font-size:12.5px;cursor:pointer;display:flex;\n  align-items:center;gap:6px;padding:4px 0;font-family:var(--font-body);font-weight:600;}\n.th-pc-return:hover{color:var(--accent-deep);}\n.th-pc-return .th-icon{color:currentColor;filter:none;}\n.th-pc-seg{display:flex;align-items:center;gap:4px;background:var(--row);border-radius:16px;padding:4px;}\n.th-pc-seg button{display:inline-flex;align-items:center;gap:7px;border:none;cursor:pointer;\n  font-family:var(--font-body);border-radius:14px;padding:8px 16px;font-size:12.5px;font-weight:700;\n  background:transparent;color:var(--ink-soft);transition:background .25s ease,color .25s ease,box-shadow .25s ease;}\n.th-pc-seg button .th-icon{color:currentColor;filter:none;}\n.th-pc-seg button.on{background:var(--accent-deep);color:#fff;text-shadow:0 1px 2px rgba(0,0,0,.2);\n  box-shadow:0 6px 16px var(--accent-glow);}\n.th-pc-viewport{flex:1;overflow:hidden;min-height:0;}\n.th-pc-levels{display:flex;width:200%;height:100%;transition:transform .35s cubic-bezier(.22,1,.36,1);}\n.th-pc-levels.level-1{transform:translateX(-50%);}\n.th-pc-level{width:50%;flex-shrink:0;height:100%;}\n/* 背面和正面一样高：技能、物品多了在屏里滚，标题「技能 / 物品」钉在上面 */\n.th-pc-screen{background:var(--card-2);border-radius:16px;padding:24px 28px;height:100%;display:flex;flex-direction:column;}\n#th-pc-skills,#th-pc-items{flex:1;min-height:0;overflow-y:auto;overscroll-behavior:contain;margin-right:-12px;padding-right:12px;padding-bottom:20px;\n  scrollbar-width:thin;scrollbar-color:var(--ink-dim) transparent;\n  -webkit-mask-image:linear-gradient(180deg,#000 calc(100% - 22px),transparent);mask-image:linear-gradient(180deg,#000 calc(100% - 22px),transparent);}\n/* 底下留 20px 空、最后 22px 渐隐：没滚到底时露出来的半行是淡的，提示还有；滚到底时淡掉的只是那段空白（手机上滚动条平时不显示） */\n#th-pc-skills::-webkit-scrollbar,#th-pc-items::-webkit-scrollbar{width:6px;}\n#th-pc-skills::-webkit-scrollbar-thumb,#th-pc-items::-webkit-scrollbar-thumb{background:var(--ink-dim);border-radius:999px;}\n#th-pc-skills::-webkit-scrollbar-track,#th-pc-items::-webkit-scrollbar-track{background:transparent;}\n.th-pc-shead{display:flex;align-items:baseline;gap:12px;margin-bottom:20px;flex-shrink:0;}\n.th-pc-shead b{display:inline-flex;align-items:center;gap:9px;font-size:20px;font-weight:900;color:var(--ink);}\n.th-pc-shead b .th-icon{color:var(--ink-soft);filter:none;}\n.th-pc-shead i{font-family:var(--font-display);font-size:11px;letter-spacing:.16em;color:var(--accent-deep);\n  font-weight:700;font-style:normal;}\n/* 技能一行一条：左边名字说明，右边档位和五段条。条子定宽，不跟着整宽拉长 */\n.th-pc-skill{display:flex;align-items:flex-start;gap:28px;}\n.th-pc-skill + .th-pc-skill{margin-top:18px;padding-top:18px;border-top:2px solid var(--line);}\n.th-pc-sk-l{flex:1 1 0;min-width:0;}\n.th-pc-sk-n{font-size:15px;font-weight:800;color:var(--ink);}\n.th-pc-sk-d{font-size:12.5px;color:var(--ink-soft);line-height:1.7;margin-top:8px;}\n.th-pc-sk-r{width:320px;flex-shrink:0;}\n.th-pc-sk-m{text-align:right;font-size:11.5px;color:var(--ink-soft);font-weight:600;margin-bottom:8px;}\n.th-pc-sk-m b{color:var(--accent-deep);font-weight:700;}\n.th-pc-tiers{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:5px;}\n.th-pc-tier{height:6px;border-radius:3px;background:var(--row);}\n.th-pc-tier.past{background:color-mix(in srgb,var(--accent) 78%,#fff);}\n.th-pc-tier.now{background:var(--accent);box-shadow:0 0 6px var(--accent-glow);}\n/* 物品：随身 / 家里两组 */\n.th-pc-group + .th-pc-group{margin-top:18px;}\n.th-pc-ghead{display:flex;align-items:center;gap:8px;margin-bottom:8px;}\n.th-pc-ghead span{font-size:11px;color:var(--ink-dim);letter-spacing:1.5px;font-weight:700;}\n.th-pc-ghead em{font-size:10.5px;color:var(--ink-dim);font-style:normal;font-weight:600;}\n.th-pc-ghead i{flex-grow:1;height:2px;border-radius:2px;background:var(--line);}\n.th-pc-items{display:flex;flex-wrap:wrap;gap:7px;}\n.th-pc-item{display:inline-flex;align-items:center;gap:5px;font-size:11.5px;color:var(--ink-soft);\n  background:var(--row);padding:5px 12px;border-radius:20px;font-weight:600;}\n.th-pc-item.star{color:var(--accent-deep);background:var(--accent-soft);font-weight:700;}\n.th-pc-item.away{background:var(--card);border:1px dashed color-mix(in srgb,var(--ink-dim) 60%,var(--card));\n  padding:4px 11px;}\n.th-pc-borrow{display:inline-flex;align-items:center;justify-content:center;min-width:15px;height:15px;\n  padding:0 4px;border-radius:5px;background:var(--accent-soft);color:var(--accent-deep);font-size:9.5px;\n  font-weight:800;}\n.th-pc-empty{font-size:12.5px;color:var(--ink-dim);}\n/* 资料卡和主要角色页同一条：聊天栏宽度里构图不变、按 452 : 266 一起缩（手机 ≤560px 的排法在 手机.css）；\n   背面的技能一行放不下「名字 + 五格进度」，≤760px 就上下叠 */\n@media (max-width:860px){\n  .th-pc-card{gap:28px;padding:30px 28px;}\n}\n@media (max-width:760px){\n  .th-pc-back{padding:20px 20px 24px;}\n  .th-pc-skill{flex-direction:column;gap:12px;}\n  .th-pc-sk-r{width:100%;}\n  .th-pc-sk-m{text-align:left;}\n}\n\n/* 挂在聊天楼层里（引导.js 给 html 加 th-in-chat）：酒馆助手按内容撑高 iframe，\n   不再按一整屏高度上下居中，否则面板上下各空出大半屏；底色透明，面板像 0 层卡一样直接浮在聊天背景上 */\nhtml.th-in-chat,html.th-in-chat body{background:transparent;}\nhtml.th-in-chat body{min-height:0;align-items:flex-start;padding:6px 10px 12px;}\n\n\n/* ===== 出行与住处（DESIGN.md「出行与住处」，代码在 21）===================== */\n/* 家、工作、学校的标记：比普通地点大一号，白描边加阴影，名字签常驻；用 margin 定锚，transform 留给落钉动画 */\n.th-map-base{position:absolute;z-index:7;display:flex;align-items:center;gap:4px;margin:-14px 0 0 -14px;padding:0;border:0;background:none;\n  font:inherit;cursor:pointer;transform-origin:14px 14px;}\n.th-map-base i{flex:none;width:28px;height:28px;border-radius:50%;display:grid;place-items:center;color:#fff;background:var(--b-color);\n  box-shadow:0 0 0 3px #ffffff,0 4px 10px rgba(0,0,0,.18);}\n.th-map-base i svg{width:15px;height:15px;}\n.th-map-base span{max-width:180px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;background:#ffffff;border-radius:7px;padding:1px 7px;\n  font-size:10.5px;font-weight:900;color:var(--b-color);box-shadow:0 2px 6px rgba(0,0,0,.12);}\n.th-map-base:focus-visible{outline:none;}\n.th-map-base:focus-visible i{box-shadow:0 0 0 3px #ffffff,0 0 0 5px var(--b-color);}\n/* = thPinDrop（下落 26px、0.8 → 1.06 → 1），不带落点图钉那份的锚点位移 */\n@keyframes thBasePinDrop{0%{opacity:0;transform:translateY(-26px) scale(.8)}65%{opacity:1;transform:translateY(0) scale(1.06)}100%{opacity:1;transform:none}}\n.th-map-base.is-drop{animation:thBasePinDrop .38s cubic-bezier(.3,1.5,.5,1) both;}\n.th-map-marker.under-base{visibility:hidden;pointer-events:none;}\n/* 普通点位 z 2、选中 8、你在这里 9：标记压住普通点位，绿点还在它上面 */\n.th-map-marker.on-base .th-map-marker-label{display:none;}\n\n/* 快捷钮：搜索框下面一排胶囊，同分类条的胶囊 */\n.th-map-quick{display:flex;flex-wrap:wrap;gap:6px;}\n.th-map-quick[hidden]{display:none;}\n.th-map-quick button{display:inline-flex;align-items:center;gap:5px;height:30px;box-sizing:border-box;padding:0 11px 0 6px;border-radius:999px;\n  border:1px solid var(--line);background:var(--card);color:var(--ink);font:inherit;font-size:12px;font-weight:700;cursor:pointer;}\n.th-map-quick button i{width:18px;height:18px;border-radius:50%;display:grid;place-items:center;color:#fff;background:var(--b-color);}\n.th-map-quick button i svg{width:11px;height:11px;}\n.th-map-quick button:hover{border-color:color-mix(in srgb,var(--b-color) 45%,var(--line));}\n.th-map-quick button:active{transform:scale(.97);}\n.th-map-context button[hidden]{display:none;}\n\n/* 地点卡上的「设为工作」「设为学校」：和「导航」「地点介绍」两两一排 */\n.th-map-side-note{margin:0;font-size:11.5px;font-weight:700;color:var(--accent-deep);}\n\n/* 导航卡：交通工具一排（横滑、两头渐隐 30px），详情块，出发 */\n.th-map-trip{display:flex;flex-direction:column;gap:8px;margin-top:8px;}\n.th-map-trip-modes{display:flex;gap:6px;overflow-x:auto;scrollbar-width:none;padding:1px 0;}\n.th-map-trip-modes::-webkit-scrollbar{display:none;}\n.th-map-trip-modes.can-r{-webkit-mask-image:linear-gradient(90deg,#000 calc(100% - 30px),transparent);mask-image:linear-gradient(90deg,#000 calc(100% - 30px),transparent);}\n.th-map-trip-modes.can-l{-webkit-mask-image:linear-gradient(90deg,transparent,#000 30px);mask-image:linear-gradient(90deg,transparent,#000 30px);}\n.th-map-trip-modes.can-l.can-r{-webkit-mask-image:linear-gradient(90deg,transparent,#000 30px,#000 calc(100% - 30px),transparent);\n  mask-image:linear-gradient(90deg,transparent,#000 30px,#000 calc(100% - 30px),transparent);}\n.th-map-trip-modes.is-dragging{cursor:grabbing;user-select:none;}\n.th-map-trip-mode{flex:none;display:flex;flex-direction:column;align-items:center;gap:1px;min-width:54px;padding:6px 8px;box-sizing:border-box;\n  border-radius:12px;border:1px solid var(--line);background:var(--card);color:var(--ink-soft);font:inherit;font-size:10.5px;font-weight:700;\n  line-height:1.35;cursor:pointer;white-space:nowrap;}\n.th-map-trip-mode svg{width:16px;height:16px;}\n.th-map-trip-mode b{font-family:var(--font-display);font-size:12.5px;font-weight:700;color:var(--ink);}\n.th-map-trip-mode.on{background:var(--accent-soft);border-color:transparent;color:var(--accent-deep);}\n.th-map-trip-mode.on b{color:var(--accent-deep);}\n.th-map-trip-mode.off{opacity:.45;}\n.th-map-trip-mode small,.th-m-only{display:none;}   /* 手机上才露出来（手机.css）：交通工具那一行的小字、钮字里的方式名 */\n.th-map-trip-detail{background:var(--card-2);border-radius:12px;padding:9px 11px;display:flex;flex-direction:column;gap:3px;}\n.th-map-trip-big{font-family:var(--font-display);font-size:20px;font-weight:700;color:var(--accent-deep);line-height:1.3;}\n.th-map-trip-big small{font-family:var(--font-body);font-size:12px;font-weight:600;color:var(--ink-soft);margin-left:6px;}\n.th-map-trip-detail p{margin:0;font-size:12px;font-weight:700;color:var(--ink-soft);}\n.th-map-trip-detail p.err{color:var(--accent-deep);}\n.th-map-trip-act[hidden]{display:none;}\n/* 出发是这张卡里唯一的实心钮：有它的时候「看整条路线」降成 ghost；有交通工具一排时，原来那句估算由详情块替掉 */\n.th-map-nav.has-go .th-map-nav-go{background:var(--row);color:var(--ink-soft);}\n.th-map-nav.has-trip .th-map-nav-sum{display:none;}\n\n/* 实心钮、ghost、灰钮（出发、买下、租下、再看看、钱不够） */\n.th-map-btn{display:flex;flex:1;align-items:center;justify-content:center;gap:6px;width:100%;min-height:38px;padding:0 14px;border:0;border-radius:999px;\n  background:var(--accent);color:#fff;font:inherit;font-size:13px;font-weight:900;box-shadow:0 6px 14px var(--accent-glow);cursor:pointer;}\n.th-map-btn svg{width:16px;height:16px;}\n.th-map-btn.ghost{background:var(--card-2);color:var(--ink);box-shadow:none;}\n.th-map-btn.off{background:var(--card-2);color:var(--ink-dim);box-shadow:none;cursor:default;}\n.th-map-btn:not(.off):not(.ghost):disabled{opacity:.5;cursor:default;}\n.th-map-btn.ghost:disabled{cursor:default;}\n.th-map-btn:not(:disabled):active{transform:scale(.97);}\n\n/* 选中回弹：方块、分段选中那一下 */\n@keyframes pickPop{0%{transform:scale(1)}45%{transform:scale(1.045)}100%{transform:scale(1)}}\n.th-map-trip-mode.is-pop,.th-map-house .th-set-seg button.is-pop{animation:pickPop .24s cubic-bezier(.34,1.56,.64,1);}\n\n/* 「住这里」卡：样子同导航卡（300px、浮层阴影、18px 圆角），开着时导航卡让开 */\n.th-map-house{position:absolute;z-index:14;left:var(--side-x,12px);top:14px;width:min(300px,calc(100% - var(--side-x,12px) - 70px));\n  max-height:calc(100% - 28px);overflow-y:auto;overscroll-behavior:contain;box-sizing:border-box;padding:14px;display:flex;flex-direction:column;gap:10px;\n  background:var(--card);border-radius:18px;box-shadow:0 18px 40px rgba(70,50,90,.18);}\n.th-map-house[hidden]{display:none;}\n.th-map-house.is-in{animation:thSheetIn .46s cubic-bezier(.22,1,.36,1);}\n.th-map-viewport.has-house .th-map-nav{display:none!important;}\n.th-map-house-h{display:flex;align-items:center;gap:8px;}\n.th-map-house-h b{font-size:15px;font-weight:900;color:var(--ink);}\n.th-map-house-x{margin-left:auto;width:28px;height:28px;border-radius:50%;border:0;background:var(--card-2);color:var(--ink-soft);font:inherit;\n  font-size:15px;font-weight:700;line-height:1;cursor:pointer;}\n.th-map-house-x:hover{color:var(--accent-deep);}\n.th-map-house-where{margin-top:-6px;font-size:11.5px;color:var(--ink-soft);}\n.th-map-house .th-set-seg{display:flex;width:100%;box-sizing:border-box;}\n.th-map-house .th-set-seg button{flex:1;}\n.th-map-house-door{display:flex;align-items:center;gap:8px;background:var(--card);border:1px solid var(--line);border-radius:10px;padding:0 10px;min-height:36px;cursor:text;}\n.th-map-house-door:focus-within{border-color:var(--accent-line);}\n.th-map-house-door span{flex:none;font-size:11px;color:var(--ink-soft);}\n.th-map-house-door input{flex:1;min-width:0;height:34px;border:0;padding:0;background:transparent;color:var(--ink);font:inherit;font-size:12.5px;font-weight:700;}\n.th-map-house-door input:focus{outline:none;}\n.th-map-house-door small{flex:none;font-size:10.5px;font-weight:700;color:var(--ink-dim);}\n.th-map-house-price{background:var(--card-2);border-radius:12px;padding:9px 11px;display:flex;flex-direction:column;gap:3px;}\n.th-map-house-price .kv{display:flex;justify-content:space-between;gap:10px;