play:grid;place-items:center;color:var(--ink-soft);cursor:pointer;}\n.th-set-x{margin-left:auto;}\n.th-set-back{color:var(--ink);}\n.th-set-status{display:flex;align-items:center;gap:10px;padding:11px 14px;border-radius:14px;background:var(--ok-soft);color:var(--ok-deep);font-weight:900;font-size:14px;}\n.th-set-status .dotok{width:22px;height:22px;border-radius:50%;background:var(--ok);color:#fff;display:grid;place-items:center;font-size:12px;flex:none;}\n.th-set-status small{font-weight:600;font-size:12px;color:#4f9a82;margin-left:auto;white-space:nowrap;}\n.th-set-status.bad{background:var(--accent-soft);color:var(--accent-deep);flex-wrap:wrap;}\n.th-set-status.bad .dotok{background:var(--accent);}\n.th-set-miss{width:100%;margin:4px 0 2px 32px;display:grid;gap:5px;}\n.th-set-miss div{display:flex;gap:8px;align-items:baseline;flex-wrap:wrap;font-size:12.5px;font-weight:800;color:var(--accent-deep);}\n.th-set-miss span{font-weight:500;color:var(--ink-soft);}\n.th-set-tip{margin:10px 0 0;padding:7px 12px;border-radius:12px;background:var(--card-2);color:var(--ink-soft);font-size:12px;font-weight:700;}\n.th-set-tip.bad{background:var(--accent-soft);color:var(--accent-deep);}\n.th-set-grp{margin-top:18px;}\n.th-set-grp-h{display:flex;align-items:baseline;gap:8px;margin:0 0 8px;font-size:15px;font-weight:900;}\n.th-set-grp-h em{font-family:var(--font-display);font-style:normal;font-weight:700;font-size:10.5px;letter-spacing:.25em;color:var(--ink-dim);}\n.th-set-list{border:2px solid var(--line);border-radius:16px;overflow:hidden;background:#fff;}\n.th-set-row{display:flex;align-items:center;gap:12px;padding:11px 14px;min-height:50px;width:100%;border:none;background:#fff;text-align:left;font:inherit;color:inherit;}\nbutton.th-set-row{cursor:pointer;}\nbutton.th-set-row:hover{background:#fcfbfd;}\n.th-set-row + .th-set-row,.th-set-row + .th-set-more,.th-set-more + .th-set-row{border-top:2px solid var(--line);}\n.th-set-tile{width:32px;height:32px;border-radius:10px;bac