background:var(--ink);color:#fff;}\n.th-set-lock svg{width:10px;height:10px;display:block;}\n.th-set-fold{display:flex;align-items:center;gap:10px;padding:10px 14px;border:2px solid var(--line);border-radius:14px;margin-top:10px;\n  width:100%;background:#fff;font:inherit;font-weight:900;color:var(--ink);text-align:left;cursor:pointer;}\n.th-set-fold small{font-weight:600;font-size:12px;color:var(--ink-soft);min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}\n.th-set-fold .n{margin-left:auto;font-family:var(--font-display);font-weight:700;color:var(--ink-soft);font-size:13px;}\n.th-set-fold .th-set-ic{color:var(--ink-dim);transition:transform .32s cubic-bezier(.22,1,.36,1);}\n.th-set-fold.open .th-set-ic{transform:rotate(180deg);}\n.th-set-fold-b{padding:12px 2px 2px;animation:thSetFold .32s cubic-bezier(.22,1,.36,1) both;}\n.th-set-foot{display:flex;justify-content:flex-end;align-items:center;gap:10px;margin-top:16px;}\n.th-set-foot small{margin-right:auto;font-size:12px;color:var(--ink-soft);}\n.th-set-page{animation:thSetSlide .35s cubic-bezier(.22,1,.36,1) both;}\n.th-set-page.back{animation-name:thSetSlideBack;}\n.th-set-stagger > *{animation:thSetRow .22s ease both;}\n.th-set-stagger > *:nth-child(2){animation-delay:.06s;}\n.th-set-stagger > *:nth-child(3){animation-delay:.12s;}\n.th-set-stagger > *:nth-child(n+4){animation-delay:.18s;}\n@keyframes thSetIn{from{opacity:0;transform:scale(1.045)}to{opacity:1;transform:none}}\n@keyframes thSetConfirm{from{opacity:0;transform:translate(-50%,-50%) scale(1.045)}to{opacity:1;transform:translate(-50%,-50%)}}\n@keyframes thSetUp{from{transform:translateY(100%)}to{transform:none}}\n@keyframes thSetRow{from{opacity:0;transform:translateY(-5px)}to{opacity:1;transform:none}}\n@keyframes thSetFold{from{opacity:0;transform:translateY(-8px)}to{opacity:1;transform:none}}\n@keyframes thSetSlide{from{opacity:0;transform:translateX(40px)}to{opacity:1;transform:none}}\n@keyframes thSetSlideBack{from{opacity:0;transform:translateX(-40px)}to{opacity:1;transform:none}}\n\n/* 聊天栏里（≤ 660px）：五个页签加 ⚙ 一行放不下会折成两行，页签左右内边距、间距收一点 */\n@media (max-width:660px){\n  .th-tab-bar{gap:4px;}\n  .th-tab-btn{padding:10px 12px;}\n}\n/* 手机（≤ 560px）：页签栏钉在面板底下、⚙ 挪到顶栏、设置在窗里换成下一页，见 手机.css */\n.th-tab-short{display:none;}\n@keyframes thSetFade{from{opacity:0}to{opacity:1}}\n@media (prefers-reduced-motion: reduce){\n  /* 只淡入、不动位置（确认框靠 transform 居中，别让动画把它覆盖掉） */\n  .th-set,.th-set-confirm,.th-set-more,.th-set-fold-b,.th-set-page,.th-set-stagger > *{animation:thSetFade .01s linear both !important;animation-delay:0s !important;}\n}\n\n/* ===== 面板在手机上（DESIGN.md 第 7 节，照「面板手机稿」版一 · 定高小窗）=====\n   面板宽 ≤ 560px：外框定高 520px，顶上时间地点和 ⚙，中间页面在窗里滚（底部 26px 渐隐），页签栏钉在窗底；\n   选角色、剧情档案、设置在窗里换成「下一页」，不盖抽屉、浮层；地图 200px 高，卡片和列表接在图下面。\n   手机才有的元素（下一页的头、角色页一排头像、图下那一格、「双指拖动」）由 22 加；电脑上它们不显示。\n   这份放在 样式.css、设置.css 后面，同一断点里盖住前两份的电脑排法 */\n.th-push-head,.th-m-avs,.th-m-mapdock,.th-m-maphint{display:none;}\n\n@media (max-width:560px){\n  /* ---- 外框：定高小窗 ---- */\n  html.th-in-chat body{padding:4px 0 10px;}\n  .th-wrapper{--m-nav:59px;height:520px;display:flex;flex-direction:column;border-radius:20px;}\n  .th-info-bar{flex:none;gap:8px;padding:12px 12px 8px 14px;cursor:default;}\n  .th-info-bar::before,.th-info-bar::after{display:none;}\n  .th-info-bar-text{flex:1;min-width:0;flex-direction:column;align-items:stretch;gap:1px;}\n  .th-info-bar-text>span{display:block;min-width:0;padding:0;border-radius:0;background:none;box-shadow:none;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}\n  .th-info-bar-text>span:first-child{font-family:var(--font-display);font-size:13px;font-weight:600;color:var(--ink);letter-spacing:0;}\n  .th-info-bar-text>span:last-child{font-size:11px;font-weight:700;color:var(--ink-soft);letter-spacing:0;}\n  .th-info-bar-text .th-icon{display:none;}\n  .th-now-playing,.th-info-bar-toggle{display:none!important;}\n  .th-info-bar-right .th-gear{width:34px;height:34px;margin:0;}\n  .th-collapsible,.th-collap