:var(--shadow);color:var(--ink);text-align:left;}\n\n  /* ---- 动态：登场头像一排、变化一行一条 ---- */\n  .th-activity-section{margin-bottom:12px;}\n  .th-activity-section-title{flex-wrap:wrap;gap:4px 6px;margin-bottom:8px;font-size:11px;}\n  .th-activity-sub{margin-left:0;font-size:10.5px;}\n  .th-presence-strip{gap:8px;padding:10px;border-radius:14px;}\n  .th-presence-chip{width:44px;gap:3px;}\n  .th-presence-chip:hover{transform:none;}\n  .th-presence-avatar{width:34px;height:34px;}\n  .th-presence-dot{right:0;width:9px;height:9px;}\n  .th-presence-name{max-width:44px;font-size:10px;}\n  .th-presence-empty{font-size:12px;}\n  .th-activity-item{gap:8px;padding:7px 10px;border-radius:12px;}\n  .th-activity-item:hover{transform:none;}\n  .th-activity-avatar{width:28px;height:28px;}\n  .th-activity-line{justify-content:space-between;gap:6px;}\n  .th-activity-meta{gap:6px;}\n  .th-activity-name{min-width:0;overflow:hidden;text-overflow:ellipsis;font-size:12.5px;}\n  .th-activity-delta{font-size:10.5px;padding:1px 8px;}\n  .th-activity-why{font-size:11px;}\n  .th-activity-time{font-size:10px;}\n  .th-activity-stage span{font-size:10.5px;padding:1px 8px;}\n  .th-activity-day{font-size:10.5px;}\n  /* 「清空」点按区不小于 36px，字的位置不变 */\n  .th-activity-clear{font-size:10.5px;min-height:36px;margin:-12px 0;padding:0 8px;}\n}\n\n/* 手指在地图上：只给触屏看这一句 */\n@media (max-width:560px) and (pointer:coarse){\n  .th-m-maphint{display:block;position:absolute;left:8px;top:8px;z-index:11;pointer-events:none;padding:1px 7px;border-radius:6px;\n    background:rgba(255,255,255,.88);color:var(--ink-soft);font-size:9.5px;font-weight:700;}\n}\n\n@media (max-width:560px) and (prefers-reduced-motion:reduce){\n  .th-set,.th-pc-level{animation:thSetFade .01s linear both!important;}\n  .th-drawer-overlay{transition:opacity .01s linear;}\n}\n\n/* 聊天栏窄（561～700px）：页签六格加 ⚙ 要一行放得下，前两格写「角色」「主角」，左右内边距 14px；639px 以下内边距 8px、间距 6px */\n@media (min-width:561px) and (max-width:700px){\n  .th-tab-full{display:none;}\n  .th-tab-short{display:inline;white-space:nowrap;}\n  .th-tab-btn{padding:10px 14px;}\n}\n@media (min-width:561px) and (max-width:639px){\n  .th-tab-bar{gap:6px;}\n  .th-tab-btn{padding:10px 8px;}\n}\n\n/* ---- 表格页（手机）：表名换成一排横着滑的签，格子排一列；点按区不小于 36px ---- */\n@media (max-width:560px){\n  .th-tb{display:block;}\n  .th-tb-list{display:none;}\n  .th-tb-chips{display:flex;gap:6px;overflow-x:auto;scrollbar-width:none;margin:0 0 10px;padding:2px 0;}\n  .th-tb-chips::-webkit-scrollbar{display:none;}\n  .th-tb-chip{flex:none;border:1px solid var(--line);border-radius:999px;background:var(--card);font:inherit;font-size:11px;font-weight:800;color:var(--ink-soft);padding:4px 10px;white-space:nowrap;cursor:pointer;}\n  .th-tb-chip small{font-family:var(--font-display);font-weight:600;color:var(--ink-dim);}\n  .th-tb-chip.on{background:var(--accent-soft);color:var(--accent-deep);border-color:transparent;}\n  .th-tb-chip.on small{color:var(--accent-deep);}\n  .th-tb-head b{font-size:14px;}\n  .th-tb-head small{font-size:11px;}\n  .th-tb-add{font-size:11px;padding:0 10px;min-height:36px;margin:-6px 0;}\n  .th-tb-card{padding:8px 10px;border-radius:12px;}\n  .th-tb-top{min-height:24px;}\n  .th-tb-top b{font-size:12.5px;}\n  .th-tb-top span{font-size:11px;}\n  .th-tb-form{grid-template-columns:1fr;gap:8px;}\n  .th-tb-in{font-size:12px;min-height:30px;}\n  .th-tb-btn,.th-tb-del{min-height:36px;}\n  .th-tb .th-set-lock{position:relative;}\n  .th-tb .th-set-lock::after{content:'';position:absolute;inset:-9px;}\n}\n\n/* ---- 纪要、去过、顶栏提示签（手机） ---- */\n@media (max-width:560px){\n  .th-jy{margin-bottom:12px;}\n  .th-jy-card{padding:8px 10px;border-radius:12px;}\n  .th-jy-h{gap:6px;font-size:10px;}\n  .th-jy-code{font-size:9.5px;}\n  .th-jy-gist{font-size:12px;}\n  .th-jy-full{font-size:11.5px;}\n  .th-jy-dhead{display:none;}\n  .th-jy-all{padding:2px 12px 8px;}\n  .th-jy-more{min-height:36px;}\n  .th-db-tag{font-family:var(--font-body);font-size:10px;padding:1px 7px;gap:3px;margin-left:6px;vertical-align:1px;}