空间 -->\n      <div class=\"th-page\" id=\"page-map\" style=\"display:none\">\n        <div class=\"th-map-content\" id=\"th-map-layout\">\n          <!-- 侧栏（补丁 17）：宽屏是左侧卡片，能收起成窄轨；窄屏是底部抽屉 -->\n          <aside class=\"th-map-side view-list\" id=\"th-map-side\" aria-label=\"地点\">\n            <button type=\"button\" class=\"th-map-side-grip\" id=\"th-map-side-grip\" aria-label=\"拖动或点击，调整抽屉高度\"><\/button>\n            <div class=\"th-map-side-rail\" id=\"th-map-side-rail\">\n              <button type=\"button\" class=\"th-map-side-fold\" data-side-toggle aria-label=\"展开侧栏\" title=\"展开侧栏\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"m6 7 5 5-5 5M12 7l5 5-5 5\"/><\/svg><\/button>\n              <button type=\"button\" class=\"th-map-side-kicker\" data-side-region aria-label=\"切换地区\"><span data-side-rgid>KANTO<\/span><\/button>\n              <button type=\"button\" class=\"th-map-side-railbtn\" data-side-search aria-label=\"搜索地点\" title=\"搜索地点\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><circle cx=\"10.5\" cy=\"10.5\" r=\"6.5\"/><path d=\"m15.5 15.5 5 5\"/><\/svg><\/button>\n              <div class=\"th-map-side-divider\"><\/div>\n              <div class=\"th-map-side-railcats\" id=\"th-map-side-railcats\" role=\"group\" aria-label=\"按地点类别筛选\"><\/div>\n            <\/div>\n            <div class=\"th-map-side-main\">\n              <div class=\"th-map-side-head\">\n                <div class=\"th-map-side-wm\" id=\"th-map-side-wm\" aria-hidden=\"true\"><\/div>\n                <div class=\"th-map-side-titles\">\n                  <button type=\"button\" class=\"th-map-side-kicker\" data-side-region aria-label=\"切换地区，打开地图册\"><span data-side-rgid>KANTO<\/span><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"m6 9 6 6 6-6\"/><\/svg><\/button>\n                  <div class=\"th-map-side-title\" id=\"th-map-side-title\"><\/div>\n                  <div class=\"th-map-crumb\" id=\"th-map-crumb\"><\/div>\n                <\/div>\n                <button type=\"button\" class=\"th-map-side-fold\" id=\"th-map-side-fold\" data-side-toggle aria-label=\"收起侧栏\" title=\"收起侧栏\" aria-expanded=\"true\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"m12 7-5 5 5 5M18 7l-5 5 5 5\"/><\/svg><\/button>\n              <\/div>\n              <div class=\"th-map-search\">\n                <div class=\"th-map-search-field\">\n                  <button type=\"button\" class=\"th-map-side-rgchip\" data-side-region aria-label=\"切换地区\"><span data-side-rgname>关东<\/span><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"m6 9 6 6 6-6\"/><\/svg><\/button>\n                  <svg aria-hidden=\"true\" viewBox=\"0 0 24 24\"><circle cx=\"10\" cy=\"10\" r=\"6.5\"><\/circle><path d=\"m15 15 5 5\"><\/path><\/svg>\n                  <input type=\"text\" id=\"th-map-search-input\" placeholder=\"搜索地点、角色、乐队\" aria-label=\"搜索地图\" autocomplete=\"off\">\n                  <button type=\"button\" id=\"th-map-search-clear\" aria-label=\"清除搜索\" hidden>×<\/button>\n                <\/div>\n                <div class=\"th-map-quick\" id=\"th-map-quick\" role=\"group\" aria-label=\"家、工作、学校\" hidden><\/div>\n                <div class=\"th-map-search-cats\" id=\"th-map-search-cats\" role=\"group\" aria-label=\"按地点类别筛选\"><\/div>\n                <div class=\"th-map-search-results\" id=\"th-map-search-results\"><\/div>\n              <\/div>\n              <div class=\"th-map-side-peek\" id=\"th-map-side-peek\"><\/div>\n              <div class=\"th-map-side-body\">\n                <div class=\"th-map-side-list\" id=\"th-map-side-list\" aria-live=\"polite\"><\/div>\n                <div class=\"th-map-explorer\" id=\"th-map-explorer\" hidden>\n                  <div class=\"th-map-explorer-head\">\n                    <button type=\"button\" class=\"th-map-detail-back\" id=\"th-map-explorer-close\" aria-label=\"返回地点列表\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"m15 6-6 6 6 6\"/><\/svg><\/button>\n                    <div class=\"th-map-explorer-tabs\" aria-label=\"地图浏览\">\n                      <button type=\"button\" data-map-view=\"book\">地图册<\/button>\n                      <button type=\"button\" data-map-view=\"directory\">地区目录<\/button>\n                    <\/div>\n                    <button type=\"button\" class=\"th-map-explorer-reset\" id=\"th-map-zoom-reset\" title=\"重置本图视野\">重置视野<\/button>\n                  <\/div>\n                  <div class=\"th-map-mobile-actions\"><button type=\"button\" id=\"th-map-dir-btn\" title=\"地区目录\">地区目录<\/button><\/div>\n                  <div class=\"th-map-book\" id=\"th-map-book\"><\/div>\n                  <div class=\"th-map-dir\" id=\"th-map-dir\">\n                    <div class=\"th-map-dir-head\">\n                      <div class=\"th-map-dir-title\">日本 · 地区目录<\/div>\n                      <button class=\"th-map-dir-close\" id=\"th-map-dir-close\">×<\/button>\n                    <\/div>\n                    <div class=\"th-map-dir-body\" id=\"th-map-dir-body\"><\/div>\n                  <\/div>\n                <\/div>\n                <div class=\"th-map-card th-map-detail\" id=\"th-map-card\" role=\"dialog\" aria-label=\"地点介绍\" aria-hidden=\"true\" inert><\/div>\n                <div class=\"th-map-pincard th-map-detail\" id=\"th-map-pincard\" role=\"dialog\" aria-label=\"地点信息\" aria-hidden=\"true\" inert><\/div>\n              <\/div>\n            <\/div>\n          <\/aside>\n          <div class=\"th-map-viewport\" id=\"th-map-viewport\" tabindex=\"0\" role=\"application\" aria-label=\"地图：方向键平移，加号 / 减号缩放，0 回到全景\">\n            <div class=\"th-map-canvas\" id=\"th-map-canvas\"><\/div>\n\n            <div class=\"th-map-topleft\" hidden>\n              <div class=\"th-map-board-chip\" id=\"th-map-board-chip\"><\/div>\n            <\/div>\n            <div class=\"th-map-mini\" id=\"th-map-mini\" hidden><\/div>\n\n            <div class=\"th-map-badge\">\n              <div class=\"th-map-chip\" id=\"th-map-chip-count\"><\/div>\n              <div class=\"th-map-chip\" id=\"th-map-chip-origin\"><\/div>\n              <a class=\"th-map-chip th-map-attrib\" id=\"th-map-attrib\" target=\"_blank\" rel=\"noopener\" style=\"display:none\"><\/a>\n            <\/div>\n\n            <div class=\"th-map-nav\" id=\"th-map-nav\" style=\"display:none\"><\/div>\n\n            <div class=\"th-map-layer-control\">\n              <button type=\"button\" class=\"th-map-layer-thumb\" id=\"th-map-layers-btn\" title=\"图层\" aria-label=\"图层\" aria-expanded=\"false\" aria-controls=\"th-map-layers\">\n                <img id=\"th-map-layer-preview\" alt=\"\" hidden><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" class=\"th-map-layer-ic\"><path d=\"m12 3 9 5-9 5-9-5 9-5Z\"/><path d=\"m3 13 9 5 9-5\"/><\/svg><span>图层<\/span>\n              <\/button>\n              <div class=\"th-map-layers\" id=\"th-map-layers\" inert>\n                <div id=\"th-map-layers-body\" role=\"group\" aria-label=\"地图图层\"><\/div>\n              <\/div>\n            <\/div>\n            <div class=\"th-map-context\" id=\"th-map-context\" role=\"menu\" aria-label=\"地图操作\" hidden>\n              <button type=\"button\" role=\"menuitem\" data-map-context=\"info\">此处是什么<\/button>\n              <button type=\"button\" role=\"menuitem\" data-map-context=\"measure\">从此处测距<\/button>\n              <button type=\"button\" role=\"menuitem\" data-map-context=\"house\" hidden>住这里<\/button>\n            <\/div>\n            <div class=\"th-map-measure\" id=\"th-map-measure\" hidden>\n              <output id=\"th-map-measure-total\" aria-live=\"polite\"><\/output>\n              <button type=\"button\" id=\"th-map-measure-clear\">结束测距<\/button>\n            <\/div>\n\n            <div class=\"th-map-nocover\" id=\"th-map-nocover\" style=\"display:none\">这一带还没有底图 · 仅显示点位<\/div>\n            <!-- 比例尺：取一个能填满 ~92px 的整数距离（1/2/5 × 10^n），\n                 和右上角的 m/px 互补：一个给尺度感，一个给底图精度 -->\n            <div class=\"th-map-scale\" id=\"th-map-scale\" aria-hidden=\"true\">\n              <div class=\"th-map-scale-txt\" id=\"th-map-scale-txt\"><\/div>\n              <div class=\"th-map-scale-bar\" id=\"th-map-scale-bar\"><\/div>\n            <\/div>\n            <div class=\"th-map-zoom\">\n              <button class=\"th-map-zoom-btn th-map-locate-btn is-off\" id=\"th-map-locate\" title=\"回到你所在的位置\" aria-label=\"回到你所在的位置\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"3.5\"/><path d=\"M12 2.5v3M12 18.5v3M2.5 12h3M18.5 12h3\"/><circle cx=\"12\" cy=\"12\" r=\"7.5\"/><\/svg><\/button>\n              <button class=\"th-map-zoom-btn\" id=\"th-map-zoom-in\" title=\"放大\" aria-label=\"放大\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M12 5v14M5 12h14\"/><\/svg><\/button>\n              <button class=\"th-map-zoom-btn\" id=\"th-map-zoom-out\" title=\"缩小\" aria-label=\"缩小\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M5 12h14\"/><\/svg><\/button>\n            <\/div>\n          <\/div>\n        <\/div>\n      <\/div>\n\n      <!-- 剧情页：主屏是\"当前时间线\"仪表盘（现在几年、已成立哪些乐队），\n           完整的 年份→乐队/联动→事件 归档通过右侧抽屉浏览，与角色版块的\n           \"乐队→成员\"抽屉同一套交互模式，但彼此独立、互不影响 -->\n      <div class=\"th-page\" id=\"page-story\" style=\"display:none\">\n        <button class=\"th-toggle-sidebar\" id=\"th-story-toggle-sidebar\"><svg class=\"th-icon\"><use href=\"#icon-chevron-left\"><\/use><\/svg><\/button>\n\n        <div class=\"th-story-dash\" id=\"th-story-dash\">\n          <div class=\"th-story-time-card\">\n            <div class=\"th-story-time-label\">⏰ 当前时间线<\/div>\n            <div class=\"th-story-time-text\" id=\"th-story-time-text\"><\/div>\n          <\/div>\n\n          <div class=\"th-story-timeline\" id=\"th-story-timeline\"><\/div>\n\n          <!-- 纪要：这一局发生过的事，最近三条 + 全部纪要（26_纪要.js） -->\n          <div class=\"th-jy\" id=\"th-jy\"><\/div>\n\n          <div class=\"th-story-bands-label\" id=\"th-story-bands-label\"><\/div>\n          <div class=\"th-story-bands-grid\" id=\"th-story-bands-grid\"><\/div>\n\n          <button type=\"button\" class=\"th-story-dash-hint\" id=\"th-story-dash-hint\">剧情档案 · 完整年份、乐队、事件<svg class=\"th-icon\"><use href=\"#icon-chevron-left\"><\/use><\/svg><\/button>\n        <\/div>\n\n        <div class=\"th-story-event-view\" id=\"th-story-event-view\" style=\"display:none\">\n          <div class=\"th-archive-crumb-back\" id=\"th-story-event-back\"><svg class=\"th-icon th-icon-xs\"><use href=\"#icon-chevron-left\"><\/use><\/svg>返回时间线<\/div>\n          <div class=\"th-archive-detail\" id=\"th-story-event-detail\"><\/div>\n        <\/div>\n      <\/div>\n\n      <!-- 动态页：在场角色 + 好感/信任变化 -->\n      <div class=\"th-page\" id=\"page-activity\" style=\"display:none\">\n        <div class=\"th-activity-content\">\n          <div class=\"th-activity-section\">\n            <div class=\"th-activity-section-title\"><svg class=\"th-icon th-icon-xs\"><use href=\"#icon-person\"><\/use><\/svg> 当前登场<span class=\"th-activity-sub\">主角身边的人<\/span><\/div>\n            <div class=\"th-presence-strip\" id=\"th-presence-strip\"><\/div>\n          <\/div>\n          <div class=\"th-activity-section\">\n            <div class=\"th-activity-section-title\"><svg class=\"th-icon th-icon-xs\"><use href=\"#icon-activity\"><\/use><\/svg> 最近动态<span class=\"th-activity-sub\">好感、信任的涨跌和原因<\/span><button class=\"th-activity-clear\" id=\"th-activity-clear\" type=\"button\" hidden>清空<\/button><\/div>\n            <div class=\"th-activity-feed\" id=\"th-activity-feed\"><\/div>\n          <\/div>\n        <\/div>\n      <\/div>\n\n      <!-- 表格页：数据库每张表能看能改，改了锁上（25_表格页.js） -->\n      <div class=\"th-page\" id=\"page-tables\" style=\"display:none\">\n        <div class=\"th-tb\" id=\"th-tb\"><\/div>\n      <\/div>\n    <\/div>\n  <\/div>\n  <\/div>\n\n  <!-- ===== 右侧浮层抽屉（覆盖式，两级结构） ===== -->\n  <div class=\"th-drawer-overlay\" id=\"th-drawer\">\n    <div class=\"th-drawer-viewport\">\n      <div class=\"th-drawer-levels\" id=\"th-drawer-levels\">\n        <!-- 第0级：乐队选择 -->\n        <div class=\"th-drawer-level\">\n          <div class=\"th-drawer-header\">— 选择乐队 —<\/div>\n          <div class=\"th-team-list\" id=\"th-team-list\"><\/div>\n        <\/div>\n        <!-- 第1级：成员选择 -->\n        <div class=\"th-drawer-level\">\n          <div class=\"th-drawer-header-nav\">\n            <button class=\"th-drawer-back\" id=\"th-drawer-back\"><svg class=\"th-icon th-icon-xs\"><use href=\"#icon-chevron-left\"><\/use><\/svg> 返回<\/button>\n            <span class=\"th-drawer-team-name\" id=\"th-current-team-name\"><\/span>\n          <\/div>\n          <div class=\"th-member-list\" id=\"th-member-list\"><\/div>\n        <\/div>\n      <\/div>\n    <\/div>\n  <\/div>\n\n  <!-- ===== 剧情抽屉（时间 → 季节 → 乐队/联动 → 事件，四级结构，与上面的角色抽屉完全独立） ===== -->\n  <div class=\"th-drawer-overlay\" id=\"th-story-drawer\">\n    <div class=\"th-drawer-viewport\">\n      <div class=\"th-story-drawer-levels\" id=\"th-story-drawer-levels\">\n        <!-- 第0级：年份选择 -->\n        <div class=\"th-drawer-level\">\n          <div class=\"th-drawer-header\">— 选择年份 —<\/div>\n          <div class=\"th-drawer-list\" id=\"th-story-drawer-years\"><\/div>\n        <\/div>\n        <!-- 第1级：季节选择 -->\n        <div class=\"th-drawer-level\">\n          <div class=\"th-drawer-header-nav\">\n            <button class=\"th-drawer-back\" id=\"th-story-drawer-back-1\"><svg class=\"th-icon th-icon-xs\"><use href=\"#icon-chevron-left\"><\/use><\/svg> 返回<\/button>\n            <span class=\"th-drawer-team-name\" id=\"th-story-drawer-year-label\"><\/span>\n          <\/div>\n          <div class=\"th-drawer-list\" id=\"th-story-drawer-seasons\"><\/div>\n        <\/div>\n        <!-- 第2级：乐队/联动选择 -->\n        <div class=\"th-drawer-level\">\n          <div class=\"th-drawer-header-nav\">\n            <button class=\"th-drawer-back\" id=\"th-story-drawer-back-2\"><svg class=\"th-icon th-icon-xs\"><use href=\"#icon-chevron-left\"><\/use><\/svg> 返回<\/button>\n            <span class=\"th-drawer-team-name\" id=\"th-story-drawer-season-label\"><\/span>\n          <\/div>\n          <div class=\"th-drawer-list\" id=\"th-story-drawer-groups\"><\/div>\n        <\/div>\n        <!-- 第3级：事件选择 -->\n        <div class=\"th-drawer-level\">\n          <div class=\"th-drawer-header-nav\">\n            <button class=\"th-drawer-back\" id=\"th-story-drawer-back-3\"><svg class=\"th-icon th-icon-xs\"><use href=\"#icon-chevron-left\"><\/use><\/svg> 返回<\/button>\n            <span class=\"th-drawer-team-name\" id=\"th-story-drawer-group-label\"><\/span>\n          <\/div>\n          <div class=\"th-drawer-list\" id=\"th-story-drawer-events\"><\/div>\n        <\/div>\n      <\/div>\n    <\/div>\n  <\/div>\n\n  <!-- ===== 全部纪要（26_纪要.js）：电脑上是右边的抽屉，手机上是窗里的下一页 ===== -->\n  <div class=\"th-drawer-overlay th-jy-drawer\" id=\"th-jy-drawer\">\n    <div class=\"th-jy-dhead\"><b>全部纪要<\/b><small id=\"