orySeasons = ['春', '夏', '秋', '冬'];\n\n\nvar storyArchive = 面板静态.storyArchive;\n\n// storyYears 不再手写维护——直接从 storyArchive 里出现过的年份去重排序推导。\n// 以后往 storyArchive 加新年份的条目，仪表盘时间线和抽屉的年份选择会自动跟上，\n// 不需要再单独维护这个数组。\nvar storyYears = Array.from(new Set(storyArchive.map(function(e){ return e.year; })))\n  .sort(function(a, b){ return a - b; });\n\n// ===== 乐队\"已成立\"状态的手动覆盖（后门） =====\n// 默认按 storyArchive 里该乐队最早一条记录的年份自动推断\"已成立\"；\n// 如果剧情出现非线性跳跃（回忆过去 / 提前解禁 / 乐队解散又重组等），\n// 或者像 Ave Mujica 这样\"人设上已经成立、但正式内容还没写出来\"，\n// 在这里显式写一条 乐队名: 年份，即可覆盖/补充自动推断，不用去改 storyArchive 本身。\nvar bandActiveOverride = {};\n// 解散年份：过了这一年，乐队不再出现在剧情仪表盘上。\n// CRYCHIC 2019 年春成立、同年冬解散，五人拆成 Ave Mujica 与 MyGO!!!!! 的班底，\n// 所以它只在 2019 这一年可见——这正是玩家回到 2019 才看得到的那条前身线。\nvar bandDisbandOverride = {\n  'CRYCHIC': 2019\n};\n// 前身/临时乐队：只在剧情版块出现，不进 teams（teams 驱动角色页的 45 人分组）\nvar storyExtraBands = [\n  {name:'CRYCHIC', logo:'', note:'MyGO!!!!! / Ave Mujica 的前身'}\n];\nfunction storyDashBands(){ return teams.concat(storyExtraBands); }\n\n// ===== 乐队表状态、剧情开关（18 接数据时填；独立预览版没有，按上面的年份推） =====\n// storyBandStatus：{乐队: 状态}，数据库乐队表的「状态」——玩家改变了谁散没散，剧情页跟着变。null 时按年份推\n// storySwitches：{开关名: '开' | '关'}，数据库剧情开关表。null 时开关行按默认「关」画，点了只在这一页记\nvar storyBandStatus = null;\nvar storySwitches = null;\n// 剧情名 = 标题去掉「主线・」「活动・」「联动・」；开关名靠它和世界书对上（总控 核心/剧情.js 同一条规则）\nfunction storyArcName(e){ return String(e.title || '').replace(/^(主线|活动|联动)・/, ''); }\nfunction storyBandState(teamName, year){\n  if(storyBandStatus && storyBandStatus.hasOwnProperty(teamName)) return storyBandStatus[teamName] || '未成立';\n  if(bandDisbandOverride.hasOwnProperty(teamName) && year > bandDisbandOverride[teamName]) return '已解散';\n  return isBandActiveInYear(teamName, year) ? '活动中' : '未成立';\n}\nfunction isBandActiveInYear(teamName, year){\n  if(bandDisbandOverride.hasOwnProperty(teamName) && year > bandDisbandOverride[teamName]) return false;\n  if(bandActiveOverride.hasOwnProperty(teamName)) return bandActiveOverride[teamName] <= year;\n  var earliest = storyArchive.filter(function(e){ return e.kind !== 'crossover' && e.team === teamName; })\n    .reduce(function(min, e){ return Math.min(min, e.year); }, Infinity);\n  return earliest <= year;\n}\n\n// ===== 角色专属主题色（收藏后驱动全局配色）：原有 45 人、梦限大MewType 五人照萌百的代表色，薇欧拉取立绘的发色（军绿；萌百写的深绿不对），墨缇丝同睦 =====\nvar charColors = 面板静态.应援色.角色;   // 数据在 src/数据/应援色.json：总控给手账本挂的脸（__BANG_FACE__）也读这一份\n\n// ===== 罗马音对照表 =====\nvar romajiMap = {\n  '户山香澄':'Toyama Kasumi','花园多惠':'Hanazono Tae','牛込里美':'Ushigome Rimi','山吹沙绫':'Yamabuki Saaya','市谷有咲':'Ichigaya Arisa',\n  '美竹兰':'Mitake Ran','青叶摩卡':'Aoba Moca','上原绯玛丽':'Uehara Himari','宇田川巴':'Udagawa Tomoe','羽泽鸫':'Hazawa Tsugumi',\n  '凑友希那':'Minato Yukina','冰川纱夜':'Hikawa Sayo','今井莉莎':'Imai Lisa','宇田川亚子':'Udagawa Ako','白金燐子':'Shirokane Rinko',\n  '弦卷心':'Tsurumaki Kokoro','濑田薰':'Seta Kaoru','北泽育美':'Kitazawa Hagumi','松原花音':'Matsubara Kanon','奥泽美咲':'Okusawa Misaki',\n  '丸山彩':'Maruyama Aya','冰川日菜':'Hikawa Hina','白鹭千圣':'Shirasagi Chisato','大和麻弥':'Yamato Maya','若宫伊芙':'Wakamiya Eve',\n  '和奏瑞依（LAYER）':'Wakana Rei','朝日六花（LOCK）':'Asahi Rokka','佐藤益木（MASKING）':'Sato Masuki','鳰原令王那（PAREO）':'Nyubara Reona','珠手知由（CHU²）':'Tamade Chiyu',\n  '仓田真白':'Kurata Mashiro','桐谷透子':'Kirigaya Toko','广町七深':'Hiromachi Nanami','二叶筑紫':'Futaba Tsukushi','八潮瑠唯':'Yashio Rui',\n  '高松灯':'Takamatsu Tomori','千早爱音':'Chihaya Anon','要乐奈':'Kaname Raana','长崎爽世':'Nagasaki Soyo','椎名立希':'Shiina Taki',\n  '三角初华':'Misumi Uika','祐天寺若麦':'Yutenji Nyamu','八幡海铃':'Yahata Umiri','若叶睦':'Wakaba Mutsumi','丰川祥子':'Toyokawa Sakiko',\n  '仲町阿拉蕾':'Nakamachi Arale','宫永野乃花':'Miyanaga Nonoka','藤都子':'Fuji Miyako','千石由乃':'Sengoku Yuno','峰月律':'Minetsuki Ritsu',\n  '薇欧拉':'Viola','墨缇丝':'Mortis'\n};\n\n// ===== 姓名水印对照表 =====\nvar watermarkMap = {\n  '户山香澄':'KASUMI','花园多惠':'TAE','牛込里美':'RIMI','山吹沙绫':'SAAYA','市谷有咲':'ARISA',\n  '美竹兰':'RAN','青叶摩卡':'MOCA','上原绯玛丽':'HIMARI','宇田川巴':'TOMOE','羽泽鸫':'TSUGUMI',\n  '凑友希那':'YUKINA','冰川纱夜':'SAYO','今井莉莎':'LISA','宇田川亚子':'AKO','白金燐子':'RINKO',\n  '弦卷心':'KOKORO','濑田薰':'KAORU','北泽育美':'HAGUMI','松原花音':'KANON','奥泽美咲':'MI