drums','白金燐子':'keys',\n  '弦卷心':'vocal','濑田薰':'guitar','北泽育美':'bass','松原花音':'drums','奥泽美咲':'dj',\n  '丸山彩':'vocal','冰川日菜':'guitar','白鹭千圣':'bass','大和麻弥':'drums','若宫伊芙':'keys',\n  '和奏瑞依（LAYER）':'vocal','朝日六花（LOCK）':'guitar','佐藤益木（MASKING）':'drums',\n  '鳰原令王那（PAREO）':'keys','珠手知由（CHU²）':'dj',\n  '仓田真白':'vocal','桐谷透子':'guitar','广町七深':'bass','二叶筑紫':'drums','八潮瑠唯':'violin',\n  '高松灯':'vocal','千早爱音':'guitar','要乐奈':'guitar','长崎爽世':'bass','椎名立希':'drums',\n  '三角初华':'vocal','祐天寺若麦':'drums','八幡海铃':'bass','若叶睦':'guitar','丰川祥子':'keys',\n  '仲町阿拉蕾':'vocal','宫永野乃花':'guitar','藤都子':'keys','千石由乃':'dj','峰月律':'guitar',\n  '薇欧拉':'person','墨缇丝':'guitar'\n};\n\n// ===== 单一「推し」收藏（全局主题） =====\nvar favoriteName = '';\ntry { favoriteName = localStorage.getItem('th-favorite') || ''; } catch(e) { favoriteName = ''; }\n\n// ===== 应用全局主题色（与当前查看的角色无关，只看 favoriteName） =====\nfunction applyTheme(){\n  var color = (favoriteName && charColors[favoriteName]) ? charColors[favoriteName] : '#ff4d7d';\n  document.querySelector('.th-wrapper').style.setProperty('--accent', color);\n  // 手账本票根皮肤跟着推し换色：总控挂在酒馆主窗口的 __BANG_FACE__（核心/手账本.js）\n  try { var face = window.parent && window.parent.__BANG_FACE__; if(face && face.v === 1) face.accent = color; }catch(e){}\n}\n\nvar cur = -1; // -1 = 未选择角色，展示默认引导界面\n// 存储每个角色的自定义图片（base64），键为角色名\nvar charImages = {};\nvar imgPlaceholder = document.getElementById('th-img-placeholder');\nvar imgReal = document.getElementById('th-img-real');\nvar imgWrap = document.getElementById('th-img-wrap');\nvar fileInput = document.getElementById('th-file-input');\nvar favStar = document.getElementById('th-fav-star');\nvar sealBtn = document.getElementById('th-seal-btn');\nvar personaBtn = document.getElementById('th-persona-btn');\nvar personaTag = document.getElementById('th-persona-tag');\nvar innerBackBtn = document.getElementById('th-inner-back');\nvar innerName = document.getElementById('th-inner-name');\nvar thoughtEl = document.getElementById('th-thought');\nvar thoughtText = document.getElementById('th-thought-text');\nvar innerEmpty = document.getElementById('th-inner-empty');\nvar nameEl = document.getElementById('th-name');\nvar nameWatermark = document.getElementById('th-name-watermark');\nvar romajiEl = document.getElementById('th-romaji');\nvar condVal = document.getElementById('th-cond-val');\nvar moodVal = document.getElementById('th-mood-val');\nvar loveVal = document.getElementById('th-love-val');\nvar trustVal = document.getElementById('th-trust-val');\nvar loveTh = document.getElementById('th-love-th');\nvar trustTh = document.getElementById('th-trust-th');\nvar loveGap = document.getElementById('th-love-gap');\nvar loveHb = document.getElementById('th-love-hb');\nvar trustHb = document.getElementById('th-trust-hb');\nvar infoBar = document.getElementById('th-info-bar');\nvar nowPlayingEmblemEl = document.getElementById('th-now-playing-emblem');\nvar nowPlayingCnEl = document.getElementById('th-now-playing-cn');\nvar nowPlayingEnEl = document.getElementById('th-now-playing-en');\nvar nowPlayingNoteEl = document.getElementById('th-now-playing-note');\nvar nowPlayingStarEl = document.getElementById('th-now-playing-star');\nvar teamLogoImg = document.getElementById('th-team-logo-img');\nvar teamLogoFallback = document.getElementById('th-team-logo-fallback');\nvar emptyHint = document.getElementById('th-empty-hint');\nvar imgOverlayText = document.getElementById('th-img-overlay-text');\nvar affectionLeft = document.querySelector('.th-affection-left');\nvar affectionRight = document.querySelector('.th-affection-right');\n\nvar tabBtns = document.querySelectorAll('.th-tab-btn');\nvar pageAff = document.getElementById('page-affection');\nvar pagePlayer = document.getElementById('page-player');\nvar pageStory = document.getElementById('page-story');\nvar pageMap = document.getElementById('page-map');\nvar pageActivity = document.getElementById('page-activity');\nvar pageTables = document.getElementById('page-tables');\n\nvar drawer = document.getElementById('th-drawer');\nvar drawerLevels = document.getElementById('th-drawer-levels');\nvar teamList = document.getElementById('th-team-list');\nvar memberList = document.getElementById('th-member-list');\nvar currentTeamName = document.getElementById('th-current-team-name');\nvar drawerBack = document.getElementById('th-drawer-back');\nvar toggleBtn = document.getElementById('th-toggle-sidebar');\n\nvar drawerLevel = 0;      // 0=乐队页, 1=成员页\nvar currentTeamIndex = -1;\n\nvar currentTab = 'affection';\n\n// ===== 抽屉开关（角色抽屉） =====\nvar drawerActiveTimer = null;\nfunction openDrawer(){\n  drawer.classList.add('open');\n  toggleBtn.classList.add('shifted');\n  toggleBtn.querySelector('.th-icon').classList.add('flip');\n  panelClearDelay(drawerActiveTimer);\n  imgWrap.classList.add('th-drawer-active'); // 抽屉打开时立绘悬浮换图提示同步隐藏\n  syncDrawerTop(drawer);\n  goToLevel(0); // 打开时总是重置为第一级\n}\nfunction closeDrawer(){\n  drawer.classList.remove('open');\n  toggleBtn.classList.remove('shifted');\n  toggleBtn.querySelector('.th-icon').classList.remove('flip');\n  // 等抽屉滑出动画（0.35s）播完再解除立绘的悬浮提示抑制；否则鼠标停在原处，\n  // 抽屉一让开立绘就会立刻被判定为“悬浮”，换图提示会跟着抽屉关闭动画一起闪现出来\n  panelClearDelay(drawerActiveTimer);\n  drawerActiveTimer = panelDelay(function(){\n    imgWrap.classList.remove('th-drawer-active');\n  }, 380);\n}\n// 抽屉顶部对齐内容区（信息栏+标签栏下方），避免遮住标签栏导致点击标签却关不掉抽屉\n// 两个抽屉（角色/剧情）共用同一套对齐逻辑，传入哪个元素就同步哪个\nfunction syncDrawerTop(drawerEl){\n  // 手机上两个抽屉是窗里的「下一页」，从窗顶一直盖到页签栏上沿（手机.css），不跟内容区对齐\n  if(thIsMobile()){ (drawerEl || drawer).style.top = ''; return; }\n  var wrapperRect = document.getElementById('th-wrapper').getBoundingClientRect();\n  var contentRect = document.getElementById('th-content').getBoundingClientRect();\n  var top = Math.max(0, contentRect.top - wrapperRect.top);\n  (drawerEl || drawer).style.top = top + 'px';\n}\npanelOn(window, 'resize', function(){\n  syncDrawerTop(drawer);\n  syncDrawerTop(storyDrawer);\n  if(currentTab === 'map') renderMapPage(); // 视口宽高变了要重新贴合地区包围盒\n});\nif(document.fonts && document.fonts.ready){ document.fonts.ready.then(panelGuard(function(){\n  syncDrawerTop(drawer);\n  syncDrawerTop(storyDrawer);\n})); }\npanelOn(toggleBtn, 'click', function(){\n  if(drawer.classList.contains('open')){\n    closeDrawer();\n  } else {\n    openDrawer();\n  }\n});\n\n// ===== 抽屉开关（剧情抽屉：时间 → 季节 → 乐队/联动 → 事件，与角色抽屉完全独立的状态） =====\nvar storyDrawer = document.getElementById('th-story-drawer');\nvar storyDrawerLevelsEl = document.getElementById('th-story-drawer-levels');\nvar storyToggleBtn = document.getElementById('th-story-toggle-sidebar');\nvar storyDrawerYearsEl = document.getElementById('th-story-drawer-years');\nvar storyDrawerSeasonsEl = document.getElementById('th-story-drawer-seasons');\nvar storyDrawerGroupsEl = document.getElementById('th-story-drawer-groups');\nvar storyDrawerEventsEl = document.getElementById('th-story-drawer-events');\nvar storyDrawerYearLabelEl = document.getElementById('th-story-drawer-year-label');\nvar storyDrawerSeasonLabelEl = document.getElementById('th-story-drawer-season-label');\nvar storyDrawerGroupLabelEl = document.getElementById('th-story-drawer-group-label');\nvar storyDrawerBack1 = document.getElementById('th-story-drawer-back-1');\nvar storyDrawerBack2 = document.getElementById('th-story-drawer-back-2');\nvar storyDrawerBack3 = document.getElementById('th-story-drawer-back-3');\n\nvar storyDrawerLevel = 0;   // 0=年份页 1=季节页 2=乐队/联动页 3=事件页\nvar storyDrawerYear = null;\nvar storyDrawerSeason = null;\nvar storyDrawerGroup = null; // 乐队名，或 'CROSSOVER'\nvar currentStoryEventId = null; // 当前主屏正在展示的事件（驱动抽屉里事件行的高亮）\n\nfunction goToStoryDrawerLevel(level){\n  storyDrawerLevel = level;\n  storyDrawerLevelsEl.classList.remove('level-1', 'level-2', 'level-3');\n  if(level > 0) storyDrawerLevelsEl.classList.add('level-' + level);\n}\n// 剧情页底下那一行「剧情档案」：点了打开剧情抽屉（原来只是一行字，看着能点却点不开）\nvar storyDashHint = document.getElementById('th-story-dash-hint');\nif(storyDashHint) panelOn(storyDashHint, 'click', function(){ openStoryDrawer(); });\nfunction openStoryDrawer(){\n  storyDrawer.classList.add('open');\n  storyToggleBtn.classList.add('shifted');\n  storyToggleBtn.querySelector('.th-icon').classList.add('flip');\n  syncDrawerTop(storyDrawer);\n  renderStoryDrawerYears();\n  goToStoryDrawerLevel(0); // 打开时总是重置为第一级\n}\nfunction closeStoryDrawer(){\n  storyDrawer.classList.remove('open');\n  storyToggleBtn.classList.remove('shifted');\n  storyToggleBtn.querySelector('.th-icon').classList.remove('flip');\n}\npanelOn(storyToggleBtn, 'click', function(){\n  if(storyDrawer.classList.contains('open')){\n    closeStoryDrawer();\n  } else {\n    openStoryDrawer();\n  }\n});\npanelOn(storyDrawerBack1, 'click', function(){ goToStoryDrawerLevel(0); });\npanelOn(storyDrawerBack2, 'click', function(){ goToStoryDrawerLevel(1); });\npanelOn(storyDrawerBack3, 'click', function(){ goToStoryDrawerLevel(2); });\n\n// ===== Tab 切换：五个顶层页面之间也用「缩小消失 → 放大出现」+ 容器高度过渡，\n// 跟剧情页内部（仪表盘⇄事件详情）用的是同一套动画手法，感觉是一致的交互语言 =====\nvar thContent = document.getElementById('th-content');\nvar pagesByTab = {affection: pageAff, player: pagePlayer, map: pageMap, story: pageStory, activity: pageActivity, tables: pageTables};\nvar mainViewSwapping = false;\nfunction swapMainPage(fromEl, toEl, revealFn){\n  if(mainViewSwapping) return;\n  mainViewSwapping = true;\n  // 手机上面板是定高的小窗、页面在窗里滚：不量也不改容器高度，换过去的页从顶上看起\n  var mobile = thIsMobile();\n\n  if(!mobile){\n    var startHeight = thContent.getBoundingClientRect().height;\n    thContent.style.height = startHeight + 'px';\n    void thContent.offsetHeight; // 强制回流，确保先定住当前高度再开始播过渡\n  }\n\n  fromEl.classList.add('th-view-shrink-out');\n  panelDelay(function(){\n    fromEl.style.display = 'none';\n    fromEl.classList.remove('th-view-shrink-out');\n    toEl.style.display = 'block';\n    if(mobile) thContent.scrollTop = 0;\n    if(revealFn) revealFn();\n    panelSboxAll(toEl);\n    toEl.classList.add('th-view-grow-in');\n\n    if(!mobile){\n      var endHeight = toEl.scrollHeight;\n      void thContent.offsetHeight; // 再强制回流一次，让下面这行设置的目标高度被当成新的过渡终点\n      thContent.style.height = endHeight + 'px';\n    }\n\n    void toEl.offsetHeight;\n    toEl.classList.remove('th-view-grow-in');\n\n    panelDelay(function(){\n      if(!mobile) thContent.style.height = ''; // 动画播完交还给自然高度\n      mainViewSwapping = false;\n    }, 320);\n  }, 220);\n}\n\ntabBtns.forEach(function(btn){\n  panelOn(btn, 'click', function(){\n    var tab = btn.dataset.tab;\n    if(tab === currentTab || mainViewSwapping) return;\n    var fromEl = pagesByTab[currentTab];\n    var toEl = pagesByTab[tab];\n    currentTab = tab;\n    closeInnerProfile();\n    tabBtns.forEach(function(b){b.classList.remove('active');});\n    btn.classList.add('active');\n\n    // 离开当前 tab 时两个抽屉都收起，各自的入口按钮先默认隐藏，\n    // 由下面命中的分支决定要不要重新显示\n    closeDrawer();\n    closeStoryDrawer();\n    toggleBtn.classList.add('hidden');\n    storyToggleBtn.classList.add('hidden');\n\n    swapMainPage(fromEl, toEl, function(){\n      if(tab === 'affection'){\n        toggleBtn.classList.remove('hidden');\n      } else if(tab === 'story'){\n        storyToggleBtn.classList.remove('hidden');\n        syncDrawerTop(storyDrawer);\n        showStoryDashboardView();\n        renderStoryDashboard();\n      } else if(tab === 'map'){\n        renderMapPage(); // 依赖视口实际尺寸，必须等页面 display 出来之后再渲染\n        // 从角色页「此刻」「她家」点过来的（23）：地图量好尺寸再飞过去\n        if(mapFocusOnShow){ var focus = mapFocusOnShow; mapFocusOnShow = null; focus(); }\n      } else if(tab === 'tables'){\n        renderTablesPage();   // 表格页（25）：每次切过来照现在的表重画\n      }\n    });\n  });\n});\n\n// ===== 图片上传 =====\npanelOn(imgWrap, 'click', function(e){\n  if(drawer.classList.contains('open')) return; // 抽屉打开时立绘不响应点击，避免与选角色冲突\n  if(cur === -1){ openDrawer(); return; } // 未选择角色时点立绘区 = 打开选择抽屉\n  // 避免点击遮罩时触发两次\n  if(e.target.closest('.th-img-overlay') || e.target === imgWrap || e.target.id === 'th-img-placeholder'){\n    fileInput.click();\n  }\n});\npanelOn(fileInput, 'change', function(e){\n  var file = e.target.files[0];\n  if(!file) return;\n  var reader = new FileReader();\n  panelOn(reader, 'load', function(ev){\n    var c = chars[cur];\n    if(!c) return;\n    charImages[c.name] = ev.target.result;\n    renderChar();\n  });\n  reader.readAsDataURL(file);\n  fileInput.value = '';\n});\n\n// ===== 收藏星标点击（单一全局收藏，点击即转移/清除） =====\npanelOn(favStar, 'click', function(e){\n  e.stopPropagation();\n  if (cur === -1) return;\n  var c = chars[cur]; if (!c) return;\n  favoriteName = (favoriteName === c.name) ? '' : c.name;\n  try { localStorage.setItem('th-favorite', favoriteName); } catch(e2){}\n  applyTheme();\n  favStar.classList.toggle('on', favoriteName === c.name);\n  renderMemberList(currentTeamIndex); // 刷新抽屉里的星标\n  updateNowPlayingPill();\n});\n\n// ===== 撕票根 → 卡片翻面显示内心页 =====\nvar innerOpen = false;\nvar flipInner = document.getElementById('th-flip-inner');\nfunction closeInnerProfile(){\n  innerOpen = false;\n  sealBtn.classList.remove('tearing');\n  flipInner.classList.remove('flipped');\n}\nfunction toggleInnerProfile(){\n  if(cur === -1) return;\n  innerOpen = !innerOpen;\n  if(innerOpen){ closeDrawer(); } // 翻到心声面时抽屉一并收起，避免叠在卡片上\n  sealBtn.classList.toggle('tearing', innerOpen);\n  flipInner.classList.toggle('flipped', innerOpen);\n}\npanelOn(sealBtn, 'click', function(e){\n  e.stopPropagation();\n  toggleInnerProfile();\n});\npanelOn(innerBackBtn, 'click', function(){\n  closeInnerProfile();\n});\n\n// ===== 第 5 节「展开、收起」：.32s，淡入淡出、上下 8px、高度（表格页的行卡、剧情页的纪要卡）=====\n// 展开：从 0 高长到内容的高度，播完交还自然高度；淡入、下落 8px 交给元素自己的进场动画。\n// 收起：从现在的高度收到 0，淡出、上移 8px，收完回调。减弱动态效果时都不播（收起直接回调）\nvar PANEL_FOLD_EASE = 'cubic-bezier(.22,1,.36,1)';\nvar PANEL_FOLD_PROPS = ['height', 'padding-top', 'padding-bottom', 'margin-top', 'margin-bottom', 'border-top-width'];\nfunction panelFoldReduced(){ try { return window.matchMedia('(prefers-reduced-motion: reduce)').matches; } catch(e){ return false; } }\nfunction panelFoldFlat(el){\n  el.style.height = '0px'; el.style.paddingTop = '0px'; el.style.paddingBottom = '0px';\n  el.style.marginTop = '0px'; el.style.marginBottom = '0px'; el.style.borderTopWidth = '0px';\n}\nfunction panelFoldOpen(el){\n  if(!el || panelFoldReduced()) return;\n  var full = el.getBoundingClientRect().height;\n  el.style.boxSizing = 'border-box'; el.style.overflow = 'hidden';\n  panelFoldFlat(el);\n  void el.offsetHeight;\n  el.style.transition = PANEL_FOLD_PROPS.map(function(p){ return p + ' .32s ' + PANEL_FOLD_EASE; }).join(', ');\n  el.style.height = full + 'px';\n  el.style.paddingTop = el.style.paddingBottom = el.style.marginTop = el.style.marginBottom = el.style.borderTopWidth = '';\n  panelDelay(function(){ el.style.boxSizing = el.style.overflow = el.style.height = el.style.transition = ''; }, 340);\n}\nfunction panelFoldClose(el, done){\n  if(!el || panelFoldReduced()){ if(done) done(); return; }\n  el.style.boxSizing = 'border-box'; el.style.overflow = 'hidden';\n  el.style.height = el.getBoundingClientRect().height + 'px';\n  el.style.animation = 'none';\n  void el.offsetHeight;\n  el.style.transition = PANEL_FOLD_PROPS.concat(['opacity', 'transform']).map(function(p){ return p + ' .32s ' + PANEL_FOLD_EASE; }).join(', ');\n  panelFoldFlat(el);\n  el.style.opacity = '0'; el.style.transform = 'translateY(-8px)';\n  panelDelay(function(){ if(done) done(); }, 320);\n}\n\n// ===== 超长字（DESIGN「超长字」）：一段话的格限高、框里滚 =====\n// 带 th-sbox 的格：字超过 --sb-n 行（签区按 --sb-row 当一行的高）就挂 is-more：限高、在框里滚、滚动条藏起来、\n// 下面还有字时最后半行淡掉；没超就照字的高。--sb-n 是 0 的不限。看不见的格（那一页没开）量不出，先不动，\n// 切到那一页、数据重画、窗口变宽变窄时再量\nfunction panelSboxFit(el){\n  if(!el || !el.isConnected) return;\n  var cs = getComputedStyle(el), n = parseFloat(cs.getPropertyValue('--sb-n')) || 0;\n  if(!n){ el.classList.remove('is-more'); return; }\n  if(!el.offsetParent) return;\n  var row = parseFloat(cs.getPropertyValue('--sb-row')) || parseFloat(cs.lineHeight) || parseFloat(cs.fontSize) * 1.5;\n  var cap = Math.round(row * n);\n  el.classList.remove('is-more');\n  el.style.setProperty('--sb-h', cap + 'px');\n  if(el.scrollHeight > cap + 22) el.classList.add('is-more');\n}\nfunction panelSboxAll(root){\n  if(!root) return;\n  if(root.classList && root.classList.contains('th-sbox')) panelSboxFit(root);\n  root.querySelectorAll('.th-sbox').forEach(panelSboxFit);\n}\nvar panelSboxTimer = 0;\npanelOn(window, 'resize', function(){\n  panelClearDelay(panelSboxTimer);\n  panelSboxTimer = panelDelay(function(){ panelSboxAll(document.body); }, 150);\n});// 好感、信任是千分制（-1000～1000），屏上写百分比：450 → 45%，655 → 65.5%，-120 → -12%\nfunction thPct(n){ var v = Math.round(Number(n)) / 10; return (v % 1 === 0 ? String(v) : v.toFixed(1)) + '%'; }\n\n// ===== 渲染角色（cur === -1 时渲染「未选择角色」默认界面） =====\nfunction renderChar(){\n  closeInnerProfile();\n  // 每次切换都重播一次淡入位移动画\n  [nameEl, affectionRight].forEach(function(el){\n    if(!el) return;\n    el.classList.remove('th-char-switch');\n    void el.offsetWidth; // 强制重排，让动画能重新触发\n    el.classList.add('th-char-switch');\n  });\n\n  if(cur === -1){\n    imgReal.style.display = 'none';\n    imgPlaceholder.style.display = 'flex';\n    imgPlaceholder.classList.add('th-empty-glow');\n    imgPlaceholder.style.opacity = 1;\n    imgPlaceholder.textContent = '?';   // 半角：全角「？」在中文字体里画在字框左半边，居中了看着也往左歪\n    imgPlaceholder.style.background = 'var(--card-2)';\n    imgOverlayText.textContent = '点击选择角色';\n    nameEl.innerHTML = '<span class=\"th-placeholder\">尚未选择角色<\/span>';\n    nameWatermark.textContent = '';\n    romajiEl.textContent = '';\n    emptyHint.style.display = 'block';\n    condVal.textContent = '——'; condVal.classList.add('is-empty');\n    moodVal.textContent = '——'; moodVal.classList.add('is-empty');\n    loveVal.textContent = '——'; loveVal.classList.add('is-empty');\n    trustVal.textContent = '——'; trustVal.classList.add('is-empty');\n    thermoSet(loveTh, null, 'rel'); thermoSet(trustTh, null, 'rel');\n    if(loveGap) loveGap.innerHTML = '';\n    thermoHbPaint(null);\n    teamLogoImg.style.display = 'none';\n    teamLogoFallback.style.display = 'none';\n    favStar.style.display = 'none';\n    sealBtn.classList.add('th-hidden');\n    personaBtn.classList.add('th-hidden');\n    personaTag.style.display = 'none';\n    renderWhere(null);\n    applyTheme();\n    updateNowPlayingPill();\n    return;\n  }\n\n  imgPlaceholder.classList.remove('th-empty-glow');\n  imgOverlayText.textContent = '点击更换图片';\n  emptyHint.style.display = 'none';\n  favStar.style.display = 'flex';\n  sealBtn.classList.remove('th-hidden');\n\n  var c = chars[cur];\n  if(!c) return;\n  var instrumentIcon = instrumentMap[c.name] || 'vocal';\n  var customImg = charImages[c.name];\n  var presetUrl = c.imgUrl || '';\n  if(customImg){\n    imgReal.src = customImg;\n    imgReal.style.display = 'block';\n    imgReal.style.opacity = 0;\n    panelDelay(function(){ imgReal.style.opacity = 1; }, 50);\n    imgPlaceholder.style.display = 'none';\n  } else if(presetUrl){\n    imgReal.src = presetUrl;\n    imgReal.style.display = 'block';\n    imgReal.style.opacity = 0;\n    imgReal.onload = panelGuard(function(){ imgReal.style.opacity = 1; });\n    imgReal.onerror = panelGuard(function(){\n      imgReal.style.display = 'none';\n      imgPlaceholder.style.display = 'flex';\n      imgPlaceholder.innerHTML = '<svg class=\"th-icon th-placeholder-icon\"><use href=\"#icon-'+instrumentIcon+'\"><\/use><\/svg>';\n      imgPlaceholder.style.background = 'var(--card-2)';\n    });\n    imgPlaceholder.style.display = 'none';\n  } else {\n    imgReal.style.display = 'none';\n    imgPlaceholder.style.display = 'flex';\n    imgPlaceholder.style.opacity = 0;\n    panelDelay(function(){\n      imgPlaceholder.innerHTML = '<svg class=\"th-icon th-placeholder-icon\"><use href=\"#icon-'+instrumentIcon+'\"><\/use><\/svg>';\n      imgPlaceholder.style.background = 'var(--card-2)';\n      imgPlaceholder.style.opacity = 1;\n    }, 200);\n  }\n\n  // 队伍徽标（贴纸色随乐队品牌色，与 --accent 无关）\n  var teamObj = teams.find(function(t){ return t.name === c.team; });\n  if(teamObj && teamObj.logo){\n    teamLogoImg.onerror = panelGuard(function(){\n      teamLogoImg.style.display = 'none';\n      teamLogoFallback.style.display = 'inline';\n      teamLogoFallback.textContent = c.team || '';\n    });\n    teamLogoImg.onload = panelGuard(function(){\n      teamLogoImg.style.display = 'block';\n      teamLogoFallback.style.display = 'none';\n    });\n    teamLogoImg.src = teamObj.logo;\n  } else {\n    teamLogoImg.style.display = 'none';\n    teamLogoFallback.style.display = 'inline';\n    teamLogoFallback.textContent = c.team || '';\n  }\n\n  nameEl.textContent = c.name;\n  nameWatermark.textContent = watermarkMap[c.name] || '';\n  romajiEl.textContent = romajiMap[c.name] || '';\n  // 人格：若叶睦 ↔ 墨缇丝。立绘左上角的面具钮切到另一张卡（另一套数）；切到人格那一面时钮是强调色，名字下面挂小签\n  var partner = personaPartner(c);\n  personaBtn.classList.toggle('th-hidden', !partner);\n  personaBtn.classList.toggle('on', !!c.persona);\n  personaBtn.title = c.persona ? '切回' + c.persona : (partner ? '切到' + partner : '');\n  personaBtn.setAttribute('aria-label', personaBtn.title);\n  personaBtn.setAttribute('aria-pressed', c.persona ? 'true' : 'false');\n  personaTag.style.display = c.persona ? '' : 'none';\n  personaTag.textContent = c.persona ? c.persona + '的另一个人格' : '';\n  fillCharData(c);\n\n  favStar.classList.toggle('on', favoriteName === c.name);\n  applyTheme();\n  updateNowPlayingPill();\n}\n\n// 数据位：与主角的关系、关系阶段、好感、信任、心声。切换角色时 renderChar 调；数据库填完一轮表时\n// 接数据只调 refreshChar：不重播切换动画、不重载立绘、不把正在看的心声页合上\nfunction fillCharData(c){\n  // 这两格读重要角色表的「与主角的关系」（一句话）和「关系阶段」（陌生 / 相识 / 熟人 / 朋友 / 好友 / 挚友）\n  condVal.textContent = c.relation || '——'; condVal.classList.toggle('is-empty', !c.relation);\n  moodVal.textContent = c.rel || '——'; moodVal.classList.toggle('is-empty', !c.rel);\n  // 接了数据库以后，还没和主角来往的人（重要角色表里没有她）好感、信任是 null，显示「——」\n  var hasLove = typeof c.love === 'number', hasTrust = typeof c.trust === 'number';\n  // 好感、信任是千分制（-1000～1000），屏上写成百分比；温度计的液柱、好感下面那一行见 29\n  loveVal.textContent = hasLove ? thPct(c.love) : '——'; loveVal.classList.toggle('is-empty', !hasLove);\n  trustVal.textContent = hasTrust ? thPct(c.trust) : '——'; trustVal.classList.toggle('is-empty', !hasTrust);\n  thermoSet(loveTh, hasLove ? c.love : null, 'rel');\n  thermoSet(trustTh, hasTrust ? c.trust : null, 'rel');\n  if(loveGap) loveGap.innerHTML = thermoGapHtml(hasLove ? c.love : null, c.rel);\n  thermoHbPaint(c);   // 手账本里她对主角的好感底色、信任落点（29）\n\n  innerName.textContent = c.name;\n  if(c.thought){\n    thoughtEl.style.display = 'block';\n    thoughtText.textContent = c.thought;\n    innerEmpty.style.display = 'none';\n  } else {\n    thoughtEl.style.display = 'none';\n    innerEmpty.style.display = 'block';\n  }\n  renderWhere(c);   // 此刻、她家（23）\n  panelSboxAll(pageAff);   // 关系、此刻、心声限高框里滚（05）\n}\nfunction refreshChar(){\n  var c = cur === -1 ? null : chars[cur];\n  if(c) fillCharData(c);\n}\n\n// ===== 抽屉两级切换 =====\nfunction goToLevel(level, teamIndex){\n  drawerLevel = level;\n  if(level === 0){\n    currentTeamIndex = -1;\n    drawerLevels.classList.remove('level-1');\n    renderTeamList();\n  } else {\n    currentTeamIndex = teamIndex;\n    drawerLevels.classList.add('level-1');\n    renderMemberList(teamIndex);\n  }\n}\n\n// ===== 第一级：乐队列表 =====\nfunction renderTeamList(){\n  teamList.innerHTML = teams.map(function(t,i){\n    // 没有 logo 的一组（「特殊」、logo 还没到的乐队）画成文字卡\n    if(!t.logo) return '<div class=\"th-team-card is-text\" data-i=\"'+i+'\"><b class=\"th-team-text\">'+escapeMapText(t.name)+'<\/b><\/div>';\n    return '<div class=\"th-team-card\" data-i=\"'+i+'\">' +\n      '<img class=\"th-team-logo\" src=\"'+t.logo+'\" alt=\"'+t.name+'\" ' +\n      'onerror=\"this.style.display=\\'none\\';this.nextElementSibling.style.display=\\'block\\';\">' +\n      '<span class=\"th-team-logo-fallback\" style=\"display:none\">'+(t.name.charAt(0))+'<\/span>' +\n    '<\/div>';\n  }).join('');\n  teamList.querySelectorAll('.th-team-card').forEach(function(el){\n    panelOn(el, 'click', function(){\n      goToLevel(1, parseInt(el.dataset.i));\n    });\n  });\n}\n\n// 人格对：带 persona 的那张卡（墨缇丝）和它的本体（若叶睦）。没有就回空\nfunction personaPartner(c){\n  if(!c) return '';\n  if(c.persona) return c.persona;\n  var p = chars.find(function(x){ return x.persona === c.name; });\n  return p ? p.name : '';\n}\nfunction switchPersona(){\n  var i = chars.findIndex(function(x){ return x.name === personaPartner(chars[cur]); });\n  if(i < 0) return;\n  cur = i;\n  renderChar();\n  if(typeof currentTeamIndex === 'number' && currentTeamIndex >= 0) renderMemberList(currentTeamIndex);\n}\npanelOn(personaBtn, 'click', function(e){ e.stopPropagation(); switchPersona(); });\npanelOn(personaBtn, 'keydown', function(e){ if(e.key === 'Enter' || e.key === ' '){ e.preventDefault(); e.stopPropagation(); switchPersona(); } });\n\n// ===== 第二级：成员列表 =====\nfunction renderMemberList(teamIndex){\n  var team = teams[teamIndex];\n  if(!team) return;\n  currentTeamName.textContent = team.name;\n\n  if(team.members.length === 0){\n    memberList.innerHTML = '<div class=\"th-empty\">暂无成员<\/div>';\n    return;\n  }\n\n  memberList.innerHTML = team.members.map(function(memberName){\n    var i = chars.findIndex(function(c){ return c.name === memberName; });\n    if(i === -1) return '';\n    var ch = chars[i];\n    var active = i === cur ? ' active' : '';\n    var favStarHtml = (favoriteName === ch.name) ? '<span class=\"th-char-favstar\">★<\/span>' : '';\n    var iconId = instrumentMap[ch.name] || 'vocal';\n    return '<div class=\"th-char-tab' + active + '\" data-i=\"'+i+'\">' +\n      '<div class=\"th-char-avatar\"><svg class=\"th-icon th-instrument-icon\"><use href=\"#icon-'+iconId+'\"><\/use><\/svg>' +\n        (ch.avatarUrl ? '<canvas class=\"th-char-avatar-img\" data-avatar-url=\"'+ch.avatarUrl+'\" data-avatar-size=\"36\"><\/canvas>' : '') +\n      '<\/div>' +\n      '<div class=\"th-char-info\">' +\n        '<span class=\"th-char-name\">' + ch.name + favStarHtml + '<\/span>' +\n        '<span class=\"th-char-rel-tag\">' + escapeMapText(ch.rel) + '<\/span>' +   // 关系阶段是填表 AI 写的字，当纯文本画\n      '<\/div>' +\n    '<\/div>';\n  }).join('');\n  renderAvatarCanvases(memberList);\n  memberList.querySelectorAll('.th-char-tab').forEach(function(el){\n    panelOn(el, 'click', function(){\n      cur = parseInt(el.dataset.i);\n      renderChar();\n      renderMemberList(currentTeamIndex); // 保持在第二级，更新高亮\n      // 不关闭抽屉，让用户连续切换\n    });\n  });\n}\n\npanelOn(drawerBack, 'click', function(){\n  goToLevel(0);\n});\n\n// ===== 动态页：在场角色 + 好感/信任变化流水（DESIGN「动态页写上原因」）=====\n// 以下是演示数据：独立预览（没有核心）就画这些，接上核心以后 18 换成真的。\n// onSceneDemo：当前在场角色名单。activityLog：新的在上，一条是一次变化：\n//   { key, name, type: love | trust | note, delta, note: 初次见面 | 记事, reason, day: '2020-04-06', week: '周一', seg: '傍晚', stage: '普通朋友 → 在意的人' }\n// activityToday：剧情里的今天（天标题写「今天」「昨天」）；activityHiddenLocal：这一楼面板里删掉的键（核心那边也存一份）\nvar onSceneDemo = ['户山香澄', '美竹兰', '丸山彩'];\nvar activityToday = '2020-04-06';\nvar activityHiddenLocal = {};\nvar activityLog = [\n  {key:'d1', name:'户山香澄', type:'love', delta:30, reason:'约好一起去乐器店', day:'2020-04-06', week:'周一', seg:'傍晚', stage:'普通朋友 → 在意的人'},\n  {key:'d2', name:'美竹兰', type:'note', note:'初次见面', reason:'在 CiRCLE 门口撞上', day:'2020-04-06', week:'周一', seg:'傍晚', stage:''},\n  {key:'d3', name:'冰川纱夜', type:'trust', delta:-20, reason:'练习迟到了', day:'2020-04-06', week:'周一', seg:'下午', stage:''},\n  {key:'d4', name:'丸山彩', type:'love', delta:50, reason:'陪她练了新舞步', day:'2020-04-05', week:'周日', seg:'晚上', stage:''},\n  {key:'d5', name:'椎名立希', type:'note', note:'记事', reason:'约好周六去录音室', day:'2020-04-05', week:'周日', seg:'下午', stage:''},\n  {key:'d6', name:'三角初华', type:'trust', delta:40, reason:'', day:'2020-04-04', week:'周六', seg:'中午', stage:''}\n];\n\nvar presenceStrip = document.getElementById('th-presence-strip');\nvar activityFeed = document.getElementById('th-activity-feed');\nvar activityClearBtn = document.getElementById('th-activity-clear');\n\n// 从动态页点击某位角色时，跳回她的主要角色卡\nfunction jumpToChar(name){\n  var i = chars.findIndex(function(c){ return c.name === name; });\n  if(i === -1) return;\n  cur = i;\n  renderChar();\n  var affBtn = document.querySelector('.th-tab-btn[data-tab=\"affection\"]');\n  if(affBtn) affBtn.click();\n}\n\nfunction renderPresence(){\n  if(onSceneDemo.length === 0){\n    presenceStrip.innerHTML = '<div class=\"th-presence-empty\">主角身边现在没有人 · 不在身边的人看「角色」页<\/div>';\n    return;\n  }\n  presenceStrip.innerHTML = onSceneDemo.map(function(name){\n    var c = chars.find(function(x){ return x.name === name; });\n    if(!c) return '';\n    var icon = instrumentMap[c.name] || 'vocal';\n    var color = charColors[c.name] || '#ff4d7d';\n    return '<div class=\"th-presence-chip\" data-name=\"'+c.name+'\" style=\"--p-color:'+color+'\">' +\n      '<div class=\"th-presence-avatar\"><svg class=\"th-icon th-instrument-icon\"><use href=\"#icon-'+icon+'\"><\/use><\/svg>' +\n        (c.avatarUrl ? '<canvas class=\"th-presence-avatar-img\" data-avatar-url=\"'+c.avatarUrl+'\" data-avatar-size=\"44\"><\/canvas>' : '') +\n        '<span class=\"th-presence-dot\"><\/span><\/div>' +\n      '<span class=\"th-presence-name\">'+c.name+'<\/span>' +\n    '<\/div>';\n  }).join('');\n  renderAvatarCanvases(presenceStrip);\n  presenceStrip.querySelectorAll('.th-presence-chip').forEach(function(el){\n    panelOn(el, 'click', function(){ jumpToChar(el.dataset.name); });\n  });\n}\n\n// 天标题：「今天 · 4月6日 周一」「昨天 · 4月5日 周日」，再早只写日子；没有时间的那段叫「更早」\nfunction activityDayLabel(e){\n  var m = /^(\\d{4})-(\\d{2})-(\\d{2})$/.exec(e.day || '');\n  if(!m) return '更早';\n  var date = Number(m[2]) + '月' + Number(m[3]) + '日' + (e.week ? ' ' + escapeMapText(e.week) : '');\n  var t = /^(\\d{4})-(\\d{2})-(\\d{2})$/.exec(activityToday || '');\n  var d = t ? (Date.UTC(+t[1], +t[2] - 1, +t[3]) - Date.UTC(+m[1], +m[2] - 1, +m[3])) / 864e5 : NaN;\n  if(d === 0) return '<b>今天<\/b> · ' + date;\n  if(d === 1) return '<b>昨天<\/b> · ' + date;\n  return date;\n}\n\n// 一行两层：上层名字、涨跌签（不带数的写灰签「初次见面」「记事」）；下层原因、时段；好感跨档的再加一枚阶段小签。\n// 原因、时段是模型写的字，一律转义\nfunction activityRowHtml(e, c){\n  var icon = instrumentMap[c.name] || 'vocal';\n  var color = charColors[c.name] || '#ff4d7d';\n  var chip;\n  if(e.type === 'note'){\n    chip = '<span class=\"th-activity-delta th-activity-tag\">' + escapeMapText(e.note || '记事') + '<\/span>';\n  } else {\n    chip = '<span class=\"th-activity-delta\" style=\"background:color-mix(in srgb, ' + color + ' 72%, #222222)\">' +\n      (e.delta > 0 ? '▲ +' : '▼ -') + thPct(Math.abs(e.delta)) + ' ' + (e.type === 'love' ? '好感' : '信任') + '<\/span>';\n  }\n  var why = e.reason ? '<span class=\"th-activity-why\">' + escapeMapText(e.reason) + '<\/span>' : '';\n  var time = e.seg ? '<span class=\"th-activity-time\">' + escapeMapText(e.seg) + '<\/span>' : '';\n  return '<div class=\"th-activity-item\" data-name=\"' + escapeMapText(c.name) + '\" data-key=\"' + escapeMapText(e.key) + '\" style=\"--p-color:' + color + '\">' +\n    '<div class=\"th-activity-avatar\"><svg class=\"th-icon th-instrument-icon\"><use href=\"#icon-' + icon + '\"><\/use><\/svg>' +\n      (c.avatarUrl ? '<canvas class=\"th-activity-avatar-img\" data-avatar-url=\"' + c.avatarUrl + '\" data-avatar-size=\"32\"><\/canvas>' : '') +\n    '<\/div>' +\n    '<div class=\"th-activity-main\">' +\n      '<div class=\"th-activity-line\"><span class=\"th-activity-name\">' + escapeMapText(c.name) + '<\/span>' + chip + '<\/div>' +\n      (why || time ? '<div class=\"th-activity-meta\">' + why + time + '<\/div>' : '') +\n      (e.stage ? '<div class=\"th-activity-stage\"><span><i>关系<\/i>' + escapeMapText(e.stage) + '<\/span><\/div>' : '') +\n    '<\/div>' +\n    '<button class=\"th-activity-x\" type=\"button\" aria-label=\"删掉这一条\" title=\"删掉\"><svg class=\"th-icon\"><use href=\"#icon-x\"><\/use><\/svg><\/button>' +\n  '<\/div>';\n}\n\nfunction renderActivity(){\n  var drawn = [];\n  activityLog.forEach(function(e){\n    var c = chars.find(function(x){ return x.name === e.name; });\n    if(c && !activityHiddenLocal[e.key]) drawn.push({ e: e, c: c });   // 名单外的人不画\n  });\n  if(activityClearBtn) activityClearBtn.hidden = drawn.length === 0;\n  if(drawn.length === 0){\n    activityFeed.innerHTML = '<div class=\"th-empty\">最近没有好感、信任的涨跌 · 有了会记在这里<\/div>';\n    return;\n  }\n  var days = drawn.some(function(x){ return x.e.day; }), lastDay = null, html = '';\n  drawn.forEach(function(x){\n    if(days && x.e.day !== lastDay){ lastDay = x.e.day; html += '<div class=\"th-activity-day\">' + activityDayLabel(x.e) + '<\/div>'; }\n    html += activityRowHtml(x.e, x.c);\n  });\n  activityFeed.innerHTML = html;\n  activityDrag = null;   // 正滑着的那一行被换掉了\n  renderAvatarCanvases(activityFeed);\n}\n\n// ===== 删动态：手机上横着滑走、电脑上点 ×、标题右边「清空」=====\n// 删的是这一条在面板上的显示，不动数据；键存进核心（这个聊天的变量），下一楼的面板照样不显示。\nvar activityCore = (function(){ try { return window.BanGCtl || (window.parent && window.parent.BanGCtl) || null; } catch(e){ return null; } })();\nvar ACT_EASE = 'cubic-bezier(.22,1,.36,1)';\nfunction activityReduced(){ try { return window.matchMedia('(prefers-reduced-motion: reduce)').matches; } catch(e){ return false; } }\nfunction activityForget(keys){\n  keys.forEach(function(k){ activityHiddenLocal[k] = 1; });\n  activityLog = activityLog.filter(function(e){ return !activityHiddenLocal[e.key]; });\n  try { if(activityCore && typeof activityCore.hideActivity === 'function') activityCore.hideActivity(keys); } catch(e){ /* 存不上：这一楼照样不显示 */ }\n}\n// 收起：高度、上下内边距收到 0，连同下面那道 8px 间距一起（最后一条收上面那道）\nfunction activityCollapse(el){\n  el.style.height = el.offsetHeight + 'px';\n  el.style.overflow = 'hidden';\n  void el.offsetHeight;\n  el.style.transition = 'height .32s ' + ACT_EASE + ', padding .32s ' + ACT_EASE + ', margin .32s ' + ACT_EASE + ', opacity .22s ease';\n  el.style.height = '0px';\n  el.style.paddingTop = '0px';\n  el.style.paddingBottom = '0px';\n  el.style.opacity = '0';\n  el.style[el.nextElementSibling ? 'marginBottom' : 'marginTop'] = '-8px';\n}\n// 删几条：顺着方向（点 × 的往右）滑出、淡出 .22s，接着收起 .32s；一起删的逐个晚 60ms，最多错开 4 个。这一天删空了，天标题一起收\nfunction activityDismiss(items, dir){\n  items = items.filter(function(el){ return el && el.parentNode && !el._gone; });\n  if(!items.length) return;\n  items.forEach(function(el){ el._gone = true; });\n  activityForget(items.map(function(el){ return el.dataset.key; }).filter(Boolean));\n  var heads = [];\n  activityFeed.querySelectorAll('.th-activity-day').forEach(function(h){\n    for(var n = h.nextElementSibling; n && !n.classList.contains('th-activity-day'); n = n.nextElementSibling){\n      if(!n._gone) return;\n    }\n    heads.push(h);\n  });\n  var lag = Math.min(items.length - 1, 3) * 60;\n  function done(){\n    items.concat(heads).forEach(function(el){ if(el.parentNode) el.parentNode.removeChild(el); });\n    if(!activityFeed.querySelector('.th-activity-item')) renderActivity();   // 删光了：换成空的那句，「清空」藏起来\n  }\n  if(activityReduced()){ done(); return; }\n  items.forEach(function(el, i){\n    var d = Math.min(i, 3) * 60;\n    el.style.pointerEvents = 'none';\n    el.style.transition = 'transform .22s ease ' + d + 'ms, opacity .22s ease ' + d + 'ms';\n    el.style.transform = 'translateX(' + (dir < 0 ? '-' : '') + '110%)';\n    el.style.opacity = '0';\n    panelDelay(function(){ activityCollapse(el); }, d + 220);\n  });\n  heads.forEach(function(h){ panelDelay(function(){ activityCollapse(h); }, lag + 220); });\n  panelDelay(done, lag + 220 + 340);\n}\n\n// 点：× 删这一条；别处跳回她的角色卡（刚滑过的那一下不算点）\npanelOn(activityFeed, 'click', function(ev){\n  var el = ev.target.closest('.th-activity-item');\n  if(!el) return;\n  if(ev.target.closest('.th-activity-x')){ activityDismiss([el], 1); return; }\n  if(el._dragged){ el._dragged = false; return; }\n  jumpToChar(el.dataset.name);\n});\nif(activityClearBtn) panelOn(activityClearBtn, 'click', function(){\n  activityDismiss(Array.prototype.slice.call(activityFeed.querySelectorAll('.th-activity-item')), 1);\n});\n\n// 滑：只认手指（和笔），鼠标照常点。横着划过 10px 才算滑，竖着划让给滚动（行上 touch-action: pan-y）；\n// 松手时划过这一行宽的 35%，或者甩得快（每毫秒 0.5px 以上、划过 40px），就删；不然弹回原处\nvar activityDrag = null;\npanelOn(activityFeed, 'pointerdown', function(ev){\n  if(ev.pointerType === 'mouse') return;\n  var el = ev.target.closest('.th-activity-item');\n  if(!el || el._gone || ev.target.closest('.th-activity-x')) return;\n  activityDrag = { el: el, id: ev.pointerId, x: ev.clientX, y: ev.clientY, dx: 0, px: 0, pt: ev.timeStamp, v: 0, on: false, w: el.offsetWidth || 1 };\n});\npanelOn(activityFeed, 'pointermove', function(ev){\n  var d = activityDrag;\n  if(!d || ev.pointerId !== d.id) return;\n  var dx = ev.clientX - d.x, dy = ev.clientY - d.y;\n  if(!d.on){\n    if(Math.abs(dy) > 10 && Math.abs(dy) >= Math.abs(dx)){ activityDrag = null; return; }\n    if(Math.abs(dx) < 10) return;\n    d.on = true;\n    try { d.el.setPointerCapture(d.id); } catch(e){ /* 抓不住也能滑，只是手指出了这一行就停 */ }\n    d.el.style.transition = 'none';\n  }\n  var dt = ev.timeStamp - d.pt;\n  if(dt > 0){ d.v = (dx - d.px) / dt; d.px = dx; d.pt = ev.timeStamp; }\n  d.dx = dx;\n  d.el.style.transform = 'translateX(' + dx + 'px)';\n  d.el.style.opacity = String(Math.max(0.2, 1 - Math.abs(dx) / d.w));\n});\nfunction activityDragEnd(ev){\n  var d = activityDrag;\n  if(!d || ev.pointerId !== d.id) return;\n  activityDrag = null;\n  if(!d.on) return;\n  d.el._dragged = true;\n  panelDelay(function(){ d.el._dragged = false; }, 400);\n  var far = Math.abs(d.dx) > d.w * 0.35, fling = Math.abs(d.dx) > 40 && Math.abs(d.v) > 0.5 && (d.v > 0) === (d.dx > 0);\n  if(ev.type !== 'pointercancel' && (far || fling)){ activityDismiss([d.el], d.dx < 0 ? -1 : 1); return; }\n  // 弹回：选中回弹那条曲线；弹完把过渡交还给样式表（悬停那一下）\n  var el = d.el;\n  el.style.transition = activityReduced() ? 'none' : 'transform .24s cubic-bezier(.34,1.56,.64,1), opacity .24s ease';\n  el.style.transform = '';\n  el.style.opacity = '';\n  panelDelay(function(){ if(!el._gone && (!activityDrag || activityDrag.el !== el)) el.style.transition = ''; }, 260);\n}\npanelOn(activityFeed, 'pointerup', activityDragEnd);\npanelOn(activityFeed, 'pointercancel', activityDragEnd);\n\n// ===== 剧情页主屏：当前时间线仪表盘 =====\nvar storyDashEl = document.getElementById('th-story-dash');\nvar storyEventViewEl = document.getElementById('th-story-event-view');\nvar storyTimeTextEl = document.getElementById('th-story-time-text');\nvar storyTimelineEl = document.getElementById('th-story-timeline');\nvar storyBandsLabelEl = document.getElementById('th-story-bands-label');\nvar storyBandsGridEl = document.getElementById('th-story-bands-grid');\nvar storyEventDetailEl = document.getElementById('th-story-event-detail');\nvar storyEventBackEl = document.getElementById('th-story-event-back');\n\n// 主屏「时间线仪表盘」⇄「事件/主线详情」之间的切换，不带动画的即时版——\n// 用于切 tab 时的强制重置，这种场合不需要、也不应该播动画\nfunction showStoryDashboardView(){\n  currentStoryEventId = null;\n  storyEventViewEl.style.display = 'none';\n  storyDashEl.style.display = '';\n  refreshStoryDrawerEventHighlight();\n}\nfunction showStoryEventView(){\n  storyDashEl.style.display = 'none';\n  storyEventViewEl.style.display = '';\n}\n\n// 同一对视图之间的\"缩小消失 → 放大出现\"过渡，点乐队 logo / 抽屉里的事件 / 返回时间线\n// 这三个入口共用这一套动画，感觉是同一层交互而不是三种不同效果。\n// 仪表盘和事件详情页高度差很多（时间线卡片 vs 七个剧情节点），只淡入淡出内容本身\n// 的话，#page-story 的高度会在 display:none/'' 切换的瞬间硬生生跳一下——所以这里\n// 额外把 #page-story 的高度也从旧内容的高度过渡到新内容的高度，跟内容淡入淡出同步播。\nvar storyViewSwapping = false;\nfunction swapStoryView(fromEl, toEl, renderFn){\n  if(storyViewSwapping) return;\n  storyViewSwapping = true;\n\n  var startHeight = pageStory.getBoundingClientRect().height;\n  pageStory.style.height = startHeight + 'px';\n  void pageStory.offsetHeight; // 强制回流，确保先定住当前高度再开始播过渡\n\n  fromEl.classList.add('th-view-shrink-out');\n  panelDelay(function(){\n    fromEl.style.display = 'none';\n    fromEl.classList.remove('th-view-shrink-out');\n    if(renderFn) renderFn();\n    toEl.style.display = '';\n    toEl.classList.add('th-view-grow-in');\n\n    var endHeight = toEl.scrollHeight;\n    void pageStory.offsetHeight; // 再强制回流一次，让下面这行设置的目标高度被当成新的过渡终点\n    pageStory.style.height = endHeight + 'px';\n\n    void toEl.offsetHeight;\n    toEl.classList.remove('th-view-grow-in');\n\n    panelDelay(function(){\n      pageStory.style.height = ''; // 动画播完交还给自然高度，避免卡在固定像素值上\n      storyViewSwapping = false;\n    }, 320);\n  }, 220);\n}\n\npanelOn(storyEventBackEl, 'click', function(){\n  swapStoryView(storyEventViewEl, storyDashEl, function(){\n    currentStoryEventId = null;\n    refreshStoryDrawerEventHighlight();\n  });\n});\n\n// 当前年份超出内容年份范围多少年，还按\"挨着展示\"处理——超过这个阈值就压缩成一段留白\nvar STORY_TIMELINE_COMPRESS_THRESHOLD = 1;\n\nfunction renderStoryDashboard(){\n  storyTimeTextEl.textContent = globalStory.time;\n\n  var year = globalStory.year;\n  var contentMin = storyYears[0];\n  var contentMax = storyYears[storyYears.length - 1];\n  var farBefore = year < contentMin - STORY_TIMELINE_COMPRESS_THRESHOLD;\n  var farAfter = year > contentMax + STORY_TIMELINE_COMPRESS_THRESHOLD;\n\n  if(farBefore || farAfter){\n    renderStoryTimelineCompressed(year, contentMin, contentMax, farBefore);\n  } else {\n    renderStoryTimelineInline(year);\n  }\n\n  // 格子：这一年照原作该在的乐队，加上乐队表里不是「未成立」的（解散了的 CRYCHIC、提前成立的）。\n  // 状态读乐队表：不在活动的半透明、右上角挂状态签；标题只数活动中的\n  var tiles = storyDashBands().map(function(t){ return { t: t, state: storyBandState(t.name, year) }; })\n    .filter(function(o){ return isBandActiveInYear(o.t.name, year) || o.state !== '未成立'; });\n  var activeCount = tiles.filter(function(o){ return o.state === '活动中'; }).length;\n  storyBandsLabelEl.textContent = '已成立乐队 · ' + activeCount + ' 支';\n  if(tiles.length === 0){\n    storyBandsGridEl.innerHTML = '<div class=\"th-archive-empty\">这一年还没有任何乐队成立～<\/div>';\n  } else {\n    storyBandsGridEl.innerHTML = tiles.map(function(o){\n      var t = o.t, out = o.state !== '活动中';\n      return '<div class=\"th-story-band-tile' + (out ? ' is-out' : '') + '\" data-team=\"' + t.name + '\">' +\n        (out ? '<span class=\"th-story-band-override\">' + escapeMapText(o.state) + '<\/span>' : '') +\n        '<div class=\"th-story-band-logo\">' + (t.logo ? '<img src=\"' + t.logo + '\" alt=\"\">' : '<span class=\"th-story-band-mark\">' + escapeMapText(t.name.slice(0, 2)) + '<\/span>') + '<\/div>' +\n        '<div class=\"th-story-band-name\">' + t.name + '<\/div>' +\n      '<\/div>';\n    }).join('');\n    storyBandsGridEl.querySelectorAll('.th-story-band-tile').forEach(function(el){\n      panelOn(el, 'click', function(){ showBandMainForCurrentYear(el.dataset.team); });\n    });\n  }\n}\n\n// 年份紧贴内容范围（或就在范围内）时：原来的逐年打点时间线\nfunction renderStoryTimelineInline(year){\n  var displayYears = storyYears.indexOf(year) === -1\n    ? storyYears.concat([year]).sort(function(a, b){ return a - b; })\n    : storyYears;\n  storyTimelineEl.innerHTML =\n    '<div class=\"th-story-timeline-line\"><\/div>' +\n    '<div class=\"th-story-timeline-fill\" id=\"th-story-timeline-fill\"><\/div>' +\n    '<div class=\"th-story-timeline-points\">' +\n    displayYears.map(function(y){\n      var cls = y === year ? 'current' : (y < year ? 'past' : 'future');\n      var nowTag = y === year ? '<span class=\"th-story-timeline-now\">现在<\/span>' : '';\n      return '<div class=\"th-story-timeline-point ' + cls + '\">' +\n        '<div class=\"th-story-timeline-dot\"><\/div>' +\n        '<span class=\"th-story-timeline-year\">' + y + '<\/span>' +\n        nowTag +\n      '<\/div>';\n    }).join('') +\n    '<\/div>';\n  var idx = displayYears.indexOf(year);\n  var pct = idx <= 0 ? 0 : (idx >= displayYears.length - 1 ? 100 : (idx / (displayYears.length - 1)) * 100);\n  document.getElementById('th-story-timeline-fill').style.width = pct + '%';\n}\n\n// 年份远离内容范围（比如从 1942 或 2042 开始玩）：压缩成\"现在\" — 留白 — \"内容区间\" 两端\nfunction renderStoryTimelineCompressed(year, contentMin, contentMax, farBefore){\n  var gap = farBefore ? (contentMin - year) : (year - contentMax);\n  var clusterLabel = contentMin === contentMax ? (contentMin + '起') : (contentMin + '-' + contentMax);\n  var nowPoint =\n    '<div class=\"th-story-timeline-point current\">' +\n      '<div class=\"th-story-timeline-dot\"><\/div>' +\n      '<span class=\"th-story-timeline-year\">' + year + '<\/span>' +\n      '<span class=\"th-story-timeline-now\">现在<\/span>' +\n    '<\/div>';\n  var clusterPoint =\n    '<div class=\"th-story-timeline-point' + (farBefore ? '' : ' past') + '\">' +\n      '<div class=\"th-story-timeline-dot\"><\/div>' +\n      '<span class=\"th-story-timeline-year\">' + clusterLabel + '<\/span>' +\n    '<\/div>';\n  var gapEl =\n    '<div class=\"th-story-timeline-gap\">' +\n      '<div class=\"th-story-timeline-gap-line ' + (farBefore ? 'muted' : 'accent') + '\"><\/div>' +\n      '<span class=\"th-story-timeline-gap-label\">相隔 ' + gap + ' 年<\/span>' +\n    '<\/div>';\n  storyTimelineEl.innerHTML = '<div class=\"th-story-timeline-compressed\">' +\n    (farBefore ? nowPoint + gapEl + clusterPoint : clusterPoint + gapEl + nowPoint) +\n    '<\/div>' +\n    '<div class=\"th-story-timeline-note\">' +\n      (farBefore ? '乐队的时代还未到来' : '剧情尚未书写到这里・沿用 ' + contentMax + ' 年名单') +\n    '<\/div>';\n}\n\n// ===== 剧情抽屉：三级列表渲染 =====\nfunction renderStoryDrawerYears(){\n  storyDrawerYearsEl.innerHTML = storyYears.map(function(y){\n    var items = storyArchive.filter(function(e){ return e.year === y; });\n    // 一支乐队一年可以有两条主线（CRYCHIC 2019 春、冬），按乐队数，不按条数\n    var mains = items.filter(function(e){ return e.kind === 'main'; });\n    var mainCount = mains.map(function(e){ return e.team; }).filter(function(t, i, a){ return a.indexOf(t) === i; }).length;\n    var eventCount = items.length - mains.length;\n    return '<div class=\"th-story-drawer-year-row\" data-year=\"' + y + '\">' +\n      '<div class=\"th-story-drawer-year-num\">' + y + '<\/div>' +\n      '<div class=\"th-story-drawer-year-meta\">' + mainCount + ' 支乐队更新主线・' + eventCount + ' 个事件<\/div>' +\n    '<\/div>';\n  }).join('');\n  storyDrawerYearsEl.querySelectorAll('.th-story-drawer-year-row').forEach(function(el){\n    panelOn(el, 'click', function(){\n      storyDrawerYear = parseInt(el.dataset.year, 10);\n      storyDrawerYearLabelEl.textContent = storyDrawerYear + '年';\n      renderStoryDrawerSeasons();\n      goToStoryDrawerLevel(1);\n    });\n  });\n}\n\nfunction renderStoryDrawerSeasons(){\n  var items = storyArchive.filter(function(e){ return e.year === storyDrawerYear; });\n  storyDrawerSeasonsEl.innerHTML = storySeasons.map(function(s){\n    var count = items.filter(function(e){ return e.season === s; }).length;\n    var disabled = count === 0 ? ' disabled' : '';\n    var meta = count === 0 ? '暂无内容' : (count + ' 条剧情');\n    return '<div class=\"th-story-drawer-season-row' + disabled + '\" data-season=\"' + s + '\">' +\n      '<span class=\"th-story-drawer-season-name\">' + s + '<\/span>' +\n      '<span class=\"th-story-drawer-season-meta\">' + meta + '<\/span>' +\n    '<\/div>';\n  }).join('');\n  storyDrawerSeasonsEl.querySelectorAll('.th-story-drawer-season-row:not(.disabled)').forEach(function(el){\n    panelOn(el, 'click', function(){\n      storyDrawerSeason = el.dataset.season;\n      storyDrawerSeasonLabelEl.textContent = storyDrawerYear + '年・' + storyDrawerSeason;\n      renderStoryDrawerGroups();\n      goToStoryDrawerLevel(2);\n    });\n  });\n}\n\nfunction renderStoryDrawerGroups(){\n  // 主线不再走抽屉——只在主屏点乐队 logo 才能看，所以这里统计\"条数\"时把 main 排除掉，\n  // 一支乐队如果这年只有主线、没有支线事件，在抽屉里就会正确显示成\"暂无内容\"\n  var items = storyArchive.filter(function(e){ return e.year === storyDrawerYear && e.season === storyDrawerSeason && e.kind !== 'main'; });\n  var rows = teams.map(function(t){\n    var count = items.filter(function(e){ return e.kind !== 'crossover' && e.team === t.name; }).length;\n    return {key:t.name, label:t.name, logo:t.logo, count:count};\n  });\n  var crossCount = items.filter(function(e){ return e.kind === 'crossover'; }).length;\n  rows.push({key:'CROSSOVER', label:'乐队联动', logo:null, count:crossCount, isCross:true});\n\n  storyDrawerGroupsEl.innerHTML = rows.map(function(r){\n    var disabled = r.count === 0 ? ' disabled' : '';\n    var logoHtml = r.isCross ? '🤝' : (r.logo ? '<img src=\"' + r.logo + '\" alt=\"\">' : '');\n    var meta = r.count === 0 ? '暂无内容' : (r.count + ' 条剧情');\n    return '<div class=\"th-story-drawer-group-row' + disabled + '\" data-key=\"' + r.key + '\">' +\n      '<div class=\"th-story-drawer-group-logo\">' + logoHtml + '<\/div>' +\n      '<div>' +\n        '<div class=\"th-story-drawer-group-name\">' + r.label + '<\/div>' +\n        '<div class=\"th-story-drawer-group-meta\">' + meta + '<\/div>' +\n      '<\/div>' +\n    '<\/div>';\n  }).join('');\n  storyDrawerGroupsEl.querySelectorAll('.th-story-drawer-group-row:not(.disabled)').forEach(function(el){\n    panelOn(el, 'click', function(){\n      storyDrawerGroup = el.dataset.key;\n      storyDrawerGroupLabelEl.textContent = storyDrawerGroup === 'CROSSOVER' ? '乐队联动' : storyDrawerGroup;\n      renderStoryDrawerEvents();\n      goToStoryDrawerLevel(3);\n    });\n  });\n}\n\nfunction renderStoryDrawerEvents(){\n  // 主线专属入口在主屏（点乐队 logo），抽屉这里只列支线事件 / 联动\n  var list = storyDrawerGroup === 'CROSSOVER'\n    ? storyArchive.filter(function(e){ return e.year === storyDrawerYear && e.season === storyDrawerSeason && e.kind === 'crossover'; })\n    : storyArchive.filter(function(e){ return e.year === storyDrawerYear && e.season === storyDrawerSeason && e.team === storyDrawerGroup && e.kind !== 'crossover' && e.kind !== 'main'; });\n  if(list.length === 0){\n    storyDrawerEventsEl.innerHTML = '<div class=\"th-archive-empty\">这里还没有剧情内容～<\/div>';\n    return;\n  }\n  storyDrawerEventsEl.innerHTML = list.map(function(e){\n    var color = e.kind === 'crossover' ? '#ff4d7d' : (bandColors[e.team] || '#ff4d7d');\n    var badge = storyEventBadge(e);\n    var active = e.id === currentStoryEventId ? ' active' : '';\n    return '<div class=\"th-story-drawer-event-row' + active + '\" data-id=\"' + e.id + '\" style=\"--e-color:' + color + '\">' +\n      '<div class=\"th-story-drawer-event-title\">' + e.title + '<\/div>' +\n      '<div class=\"th-story-drawer-event-badges\"><span class=\"th-archive-event-badge' + (badge.on ? ' on' : '') + '\">' + badge.text + '<\/span><\/div>' +\n    '<\/div>';\n  }).join('');\n  storyDrawerEventsEl.querySelectorAll('.th-story-drawer-event-row').forEach(function(el){\n    panelOn(el, 'click', function(){ showStoryEvent(el.dataset.id); });\n  });\n}\n// 抽屉里事件行的高亮跟主屏当前展示的事件保持同步（比如点了\"返回时间线\"之后）\nfunction refreshStoryDrawerEventHighlight(){\n  storyDrawerEventsEl.querySelectorAll('.th-story-drawer-event-row').forEach(function(el){\n    el.classList.toggle('active', el.dataset.id === currentStoryEventId);\n  });\n}\n\n// ===== 主屏事件/主线详情：开幕～终章节点列表 =====\nfunction renderStoryEventDetailContent(e){\n  var color = e.kind === 'crossover' ? '#ff4d7d' : (bandColors[e.team] || '#ff4d7d');\n  var bandLabel = e.kind === 'crossover' ? e.teams.join(' × ') : e.team;\n  var nodesHtml = e.nodes.map(function(n, i){\n    var desc = n.desc || '剧情描述内容待填写……';\n    return '<div class=\"th-story-node\">' +\n      '<div class=\"th-story-node-header\">' +\n        '<span class=\"th-story-node-num\" style=\"background:' + color + '\">' + (i + 1) + '<\/span>' +\n        '<span class=\"th-story-node-title\">' + n.label + '<\/span>' +\n      '<\/div>' +\n      '<div class=\"th-story-node-desc\">' + desc + '<\/div>' +\n    '<\/div>';\n  }).join('');\n  var sw = storySwitchFor(e);\n  storySwitchErr = '';\n  storyEventDetailEl.innerHTML =\n    '<div class=\"th-archive-detail-title\">' + e.title + '<\/div>' +\n    '<div class=\"th-archive-detail-band\" style=\"color:' + color + '\">' + bandLabel + ' ｜ ' + e.year + ' 年' + e.season + '<\/div>' +\n    (sw ? storySwitchRow(sw, false) : '') +\n    nodesHtml;\n}\n\n// ===== 开关行（DESIGN「剧情开关」）：活动、联动是「收录」，标了原作收尾的主线、活动是「原作收尾」，成立经过的主线没有 =====\n// 改开关交给总控（核心/剧情.js 写进数据库剧情开关表，世界书的条件块认它）；独立预览版没有总控，只在这一页记\nvar storySwitchErr = '';\n// 收录的时间（和总控 核心/剧情.js 同一条规矩）：这一季的起点到下一学年春天的起点（不含）。\n// '未到' | '可以' | '已过'；没有故事时间（独立预览、还没开局）算可以\nfunction storyTiming(e){\n  var today = globalStory.date || '', cuts = 面板静态.时节分界 || [];\n  var start = (cuts.find(function(x){ return String(x.名).charAt(0) === e.season; }) || {}).起;\n  var spring = (cuts.find(function(x){ return String(x.名).charAt(0) === '春'; }) || {}).起;\n  if(!today || !start || !spring || !e.year) return '可以';\n  if(today < e.year + '-' + start) return '未到';\n  return today >= (e.year + 1) + '-' + spring ? '已过' : '可以';\n}\n// 抽屉里活动、联动那一行右边的签：没到季节写几时起，过了写已过去，能收录的写收没收；\n// 标了原作收尾的活动不看季节：原作收尾开着写「原作线」，关着写「分歧线」\nfunction storyEventBadge(e){\n  if(e.收尾开关){\n    var end = storySwitchOn('原作收尾·' + storyArcName(e));\n    return { text: end ? '原作线' : '分歧线', on: end };\n  }\n  var t = storyTiming(e);\n  if(t === '未到') return { text: e.year + ' ' + e.season + '起', on: false };\n  if(t === '已过') return { text: '已过去', on: false };\n  var sw = storySwitchFor(e);\n  var on = !!(sw && storySwitchOn(sw.name));\n  return { text: on ? '已收录' : '未收录', on: on };\n}\nfunction storySwitchFor(e){\n  if(e.收尾开关) return { name: '原作收尾·' + storyArcName(e), label: '原作收尾', hint: e.收尾开关 + ' · 默认关' };\n  if(e.kind === 'event' || e.kind === 'crossover'){\n    var t = storyTiming(e);\n    var hint = t === '未到' ? e.year + ' 年' + e.season + '起可收录' : t === '已过' ? '这一学年已经过去' : '进这一年的故事 · 默认关';\n    return { name: '收录·' + storyArcName(e), label: '收录', hint: hint, locked: t !== '可以' };\n  }\n  // 乐队主线：默认开、随时能关（常夜灯 2026-10-06 定）；成立经过归开局卡的成立线，这里不出开关\n  if(e.kind === 'main' && !e.成立) return { name: '主线·' + storyArcName(e), label: '主线', hint: '这一年的乐队主线 · 默认开' };\n  return null;\n}\n// 表里没有这一行：乐队主线算开，收录、原作收尾算关\nfunction storySwitchOn(name){\n  var v = storySwitches ? storySwitches[name] : undefined;\n  return /^主线·/.test(name) ? v !== '关' : v === '开';\n}\nfunction storySwitchRow(sw, pop){\n  var on = storySwitchOn(sw.name);\n  return '<div class=\"th-story-switch-wrap\"><div class=\"th-story-switch' + (sw.locked ? ' is-locked' : '') + '\">' +\n    '<div class=\"th-story-switch-text\"><b>' + sw.label + '<\/b><span>' + escapeMapText(sw.hint) + '<\/span><\/div>' +\n    '<div class=\"th-set-seg\" role=\"group\" aria-label=\"' + sw.label + '\">' + ['关', '开'].map(function(v){\n      var sel = (v === '开') === on;\n      return '<button type=\"button\" data-switch=\"' + v + '\" aria-pressed=\"' + sel + '\"' + (sel ? ' class=\"on' + (pop ? ' is-pop' : '') + '\"' : '') + (sw.locked ? ' disabled' : '') + '>' + v + '<\/button>';\n    }).join('') + '<\/div><\/div>' +\n    (storySwitchErr ? '<p class=\"th-story-switch-err\" role=\"status\">' + escapeMapText(storySwitchErr) + '<\/p>' : '') + '<\/div>';\n}\n// 开关、故事时间变了：抽屉里那一列的签跟着换（列表开着才有行）\nfunction refreshStoryDrawerBadges(){\n  storyDrawerEventsEl.querySelectorAll('.th-story-drawer-event-row').forEach(function(el){\n    var e = storyArchive.find(function(x){ return x.id === el.dataset.id; });\n    var b = e && storyEventBadge(e), s = el.querySelector('.th-archive-event-badge');\n    if(b && s){ s.textContent = b.text; s.classList.toggle('on', b.on); }\n  });\n}\n// 只换开关那一行，节点列表不重画\nfunction refreshStorySwitchRow(pop){\n  var el = storyEventDetailEl.querySelector('.th-story-switch-wrap');\n  var e = el && storyArchive.find(function(x){ return x.id === currentStoryEventId; });\n  var sw = e && storySwitchFor(e);\n  if(sw) el.outerHTML = storySwitchRow(sw, pop);\n}\npanelOn(storyEventDetailEl, 'click', function(ev){\n  var b = ev.target.closest('[data-switch]');\n  var e = b && storyArchive.find(function(x){ return x.id === currentStoryEventId; });\n  var sw = e && storySwitchFor(e);\n  if(!sw || sw.locked) return;\n  var want = b.dataset.switch === '开';\n  if(want === storySwitchOn(sw.name)) return;\n  var before = storySwitches ? storySwitches[sw.name] : undefined;\n  storySwitches = Object.assign({}, storySwitches || {});\n  storySwitches[sw.name] = want ? '开' : '关';   // 先画出来；总控没写进去再退回\n  storySwitchErr = '';\n  refreshStorySwitchRow(true);\n  var core = mapCore();\n  if(!core || typeof core.setSwitch !== 'function') return;\n  Promise.resolve(core.setSwitch(sw.name, want)).then(function(r){\n    if(r && r.ok){ if(r.开关) storySwitches = r.开关; storySwitchErr = ''; }\n    else { storySwitches[sw.name] = before; storySwitchErr = (r && r.原因) || '没改成'; }\n  }, function(err){\n    storySwitches[sw.name] = before; storySwitchErr = String(err && err.message || err || '没改成');\n  }).then(function(){ if(currentStoryEventId === e.id) refreshStorySwitchRow(false); refreshStoryDrawerBadges(); });\n});\n\n// 支线事件 / 联动：从抽屉里点进来\nfunction showStoryEvent(id){\n  var e = storyArchive.find(function(x){ return x.id === id; });\n  if(!e) return;\n  currentStoryEventId = id;\n  refreshStoryDrawerEventHighlight();\n  swapStoryView(storyDashEl, storyEventViewEl, function(){ renderStoryEventDetailContent(e); });\n}\n\n// 主线：从主屏点乐队 logo 进来，只看\"当前年份\"这一支乐队的那一章——\n// CRYCHIC 这种解散了的乐队自然就只有它存在的那一年能点出内容，\n// 之后的年份点进来会是下面这个\"这一年还没有主线\"的空状态，不会往前/往后找别的年份顶替。\n// 同一年有两条（CRYCHIC 2019 春「找到彼此」、冬「雨中散开」）时按现在的季节挑：到了冬天就是冬那一章；季节读不出来给第一章\nvar STORY_SEASONS = ['春', '夏', '秋', '冬'];\n// 现在是这一年的第几季：顶栏时间以时节开头（「春・4 月 18 日・…」）就用它；没有时节按日期照全卡的时节分界（数据/时节.json）算。\n// 春的起点之前（1 月到 3 月下旬）还没到这一年的春天，算 -1：冬那一章说的是年底\nfunction storySeasonNow(){\n  var t = String(globalStory.time || ''), s = STORY_SEASONS.indexOf((t.match(/^[春夏秋冬]/) || [''])[0]);\n  if(s >= 0) return s;\n  var m = /(\\d{1,2})\\s*月\\s*(\\d{1,2})\\s*日/.exec(t);\n  if(!m) return -1;\n  var md = ('0' + m[1]).slice(-2) + '-' + ('0' + m[2]).slice(-2), at = -1;\n  (面板静态.时节分界 || []).forEach(function(x){ if(x.起 <= md) at = STORY_SEASONS.indexOf(String(x.名).charAt(0)); });\n  return at;\n}\nfunction showBandMainForCurrentYear(teamName){\n  var year = globalStory.year;\n  var mains = storyArchive.filter(function(e){ return e.kind === 'main' && e.team === teamName && e.year === year; })\n    .sort(function(a, b){ return STORY_SEASONS.indexOf(a.season) - STORY_SEASONS.indexOf(b.season); });\n  var now = storySeasonNow();\n  var reached = now < 0 ? [] : mains.filter(function(e){ return STORY_SEASONS.indexOf(e.season) <= now; });\n  var entry = reached.length ? reached[reached.length - 1] : mains[0];\n  currentStoryEventId = entry ? entry.id : null;\n  refreshStoryDrawerEventHighlight();\n  swapStoryView(storyDashEl, storyEventViewEl, function(){\n    if(entry){\n      renderStoryEventDetailContent(entry);\n    } else {\n      var color = bandColors[teamName] || '#ff4d7d';\n      storyEventDetailEl.innerHTML =\n        '<div class=\"th-archive-detail-title\">' + teamName + '<\/div>' +\n        '<div class=\"th-archive-detail-band\" style=\"color:' + color + '\">' + year + ' 年<\/div>' +\n        '<div class=\"th-archive-empty\">这一年还没有 ' + teamName + ' 的主线内容～<\/div>';\n    }\n  });\n}\n\n// ===== 地图页：所有地区合并成一张连续地图 =====\n// 全部 242 个点位放在同一套 Web Mercator 世界坐标里，k=1 时刚好看全（大阪～千叶）。\n// 缩放靠\"网格聚合\"切换详略：网格按世界坐标划分、格边长 = 固定屏幕尺寸 / k，\n// 所以放大时格子变小、聚合自动裂开成散点，缩小时重新并回气泡——只有缩放会改变\n// 聚合结果，平移不会，因此拖动时只改 CSS transform，不重排 DOM。\nvar mapViewportEl = document.getElementById('th-map-viewport');\nvar mapCanvasEl = document.getElementById('th-map-canvas');\nvar mapCardEl = document.getElementById('th-map-card');\nvar mapLayoutEl = document.getElementById('th-map-layout');\nvar mapSideEl = document.getElementById('th-map-side');          // 侧栏（补丁 17）\nvar mapSideListEl = document.getElementById('th-map-side-list');\nvar mapSideMiniEl = document.getElementById('th-map-mini');\nvar mapSidePeekEl = document.getElementById('th-map-side-peek');\n// 窄屏抽屉 peek / half / full；mapSheetBack 记着详情打开前的档位，关详情时退回去\nvar mapSideCollapsed = false, mapSheetState = 'peek', mapSheetBack = '', mapPinDetailOpen = false, mapSideSig = '', mapSideSelKey = '', mapSideSelSeen = '';\nvar mapSideHadOverlay = false;   // 按下的那一刻地图册或搜索结果开着没有，点空白处时用\ntry{ mapSideCollapsed = localStorage.getItem('th-map-side-collapsed') === '1'; }catch(err){}\nvar mapSearchInput = document.getElementById('th-map-search-input');\nvar mapSearchResultsEl = document.getElementById('th-map-search-results');\nvar mapChipCountEl = document.getElementById('th-map-chip-count');\nvar mapChipOrigin