n// 谷歌地图也允许超采样一点（瓦片放大一级），但绝不会到 41 倍。\nvar MAP_OVERZOOM = 1.5;\n// Check the full viewport against the union of available rectangles.\n// Tile seams no longer require one image to contain the entire viewport.\nfunction mapRasterRect(x,y,w,h){\n  var ratio=typeof devicePixelRatio==='number'?Math.max(1,devicePixelRatio):1;\n  var left=Math.floor(x*ratio)/ratio,top=Math.floor(y*ratio)/ratio;\n  return {x:left,y:top,w:Math.ceil((x+w)*ratio)/ratio-left,h:Math.ceil((y+h)*ratio)/ratio-top};\n}\n// 藏起来的底图留几张备用（拖回来不用重新解码）。手机显存紧：最多 2 张、1200 万像素；桌面 8 张、4800 万\nvar MAP_CACHE_TOUCH = (function(){ try{ return matchMedia('(pointer: coarse)').matches; }catch(err){ return false; } })();\nfunction mapTrimRasterCache(root){\n  var hidden=Array.from(root.children).filter(function(img){return img.style.display==='none';});\n  hidden.sort(function(a,b){return Number(b.dataset.lastShown||0)-Number(a.dataset.lastShown||0);});\n  var pixels=0,kept=0,maxN=MAP_CACHE_TOUCH?2:8,maxPx=MAP_CACHE_TOUCH?12000000:48000000;\n  hidden.forEach(function(img){\n    var size=(img.naturalWidth||Number(img.dataset.nativeWidth)||0)*(img.naturalHeight||Number(img.dataset.nativeHeight)||0);\n    if(img.complete && img.naturalWidth && kept<maxN && pixels+size<=maxPx){pixels+=size;kept++;return;}\n    img.remove();\n    img.removeAttribute('src');\n  });\n}\nfunction mapRectUnionCovers(view, rectangles){\n  var eps = Math.max(view[2]-view[0],view[3]-view[1],1) * 1e-9;\n  var clipped = rectangles.map(function(r){\n    return [Math.max(view[0],r[0]),Math.max(view[1],r[1]),Math.min(view[2],r[2]),Math.min(view[3],r[3])];\n  }).filter(function(r){return r[2]-r[0]>eps && r[3]-r[1]>eps;});\n  if(!clipped.length) return false;\n  var cuts = [view[0],view[2]];\n  clipped.forEach(function(r){cuts.push(r[0],r[2]);});\n  cuts.sort(function(a,b){return a-b;});\n  for(var i=1;i<cuts.length;i++){\n    if(cuts[i]-cuts[i-1]<=eps) continue;\n    var x=(cuts[i]+cuts[i-1])/2;\n    var spans=clipped.filter(function(r){return r[0]<=x+eps && r[2]>=x-eps;})\n      .map(function(r){return [r[1],r[3]];}).sort(function(a,b){return a[0]-b[0];});\n    var edge=view[1];\n    for(var j=0;j<spans.length;j++){\n      if(spans[j][0]>edge+eps) return false;\n      edge=Math.max(edge,spans[j][1]);\n      if(edge>=view[3]-eps) break;\n    }\n    if(edge<view[3]-eps) return false;\n  }\n  return true;\n}\nfunction mapCeilK(cx,cy,k,ax,ay){\n  if(!mapSheet || !mapProj) return 1;\n  if(cx==null){cx=(mapProj.vw/2-mapTx)/mapK;cy=(mapProj.vh/2-mapTy)/mapK;}\n  if(ax==null){ax=mapProj.vw/2;ay=mapProj.vh/2;}\n  var floor=mapFitK(),anchor=mapDetailNativeK(cx,cy)*MAP_OVERZOOM;\n  var layers=[],limits=[];\n  MAP_SHEETS.forEach(function(sh){sh.layers.forEach(function(L){\n    if(!L.url || L.url==='TODO_UPLOAD') return;\n    var a=mapLLToWorld(L.bbox[0],L.bbox[3]),b=mapLLToWorld(L.bbox[2],L.bbox[1]);\n    var native=mapLayerNativeK(L)*MAP_OVERZOOM;\n    var size=MAP_COVER_MAX/Math.max(b[0]-a[0],b[1]-a[1]);\n    layers.push({rect:[a[0],a[1],b[0],b[1]],native:native,size:size});\n    var limit=Math.min(native,size);\n    if(limit>floor && limit<=anchor+1e-9) limits.push(limit);\n  });});\n  limits.sort(function(a,b){return b-a;});\n  var previous=Infinity;\n  for(var i=0;i<limits.length;i++){\n    var limit=limits[i];\n    if(Math.abs(previous-limit)<1e-7) continue;\n    previous=limit;\n    var view=[cx-ax/limit,cy-ay/limit,cx+(mapProj.vw-ax)/limit,cy+(mapProj.vh-ay)/limit];\n    var rectangles=layers.filter(function(L){return L.native+1e-9>=limit && L.size+1e-9>=limit;})\n      .map(function(L){return L.rect;});\n    if(mapRectUnionCovers(view,rectangles)) return limit;\n  }\n  return floor;\n}\nfunction mapConstrainViewToCoverage(){\n  if(!mapProj || !mapSheet || !mapFit || !(mapK>0)) return;\n  var cx=(mapProj.vw/2-mapTx)/mapK,cy=(mapProj.vh/2-mapTy)/mapK;\n  var limit=Math.max(mapMinK(),mapCeilK(cx,cy,mapK));\n  if(mapK>limit*(1+1e-7)){\n    mapK=limit;mapTx=mapProj.vw/2-cx*mapK;mapTy=mapProj.vh/2-cy*mapK;\n    updateMap