ained.push(i);\n    // 表里常写简称（「CiRCLE 前台」）：某一段至少 3 个字、被地点名字包含\n    else if(names.some(function(n){ return parts.some(function(t){ return t.length >= 3 && n.indexOf(t) >= 0; }); })) within.push(i);\n    var scene = mapSceneNames(mapScenesByPoint[mapPointIds[i]]).find(function(n){ return n === raw || parts.indexOf(n) >= 0; });\n    if(scene) scenes.push({i:i, name:scene});\n  }\n  var hits = exact.length ? exact : contained.length ? contained : within;\n  if(hits.length === 1){\n    var scoped = scenes.find(function(s){ return s.i === hits[0]; });\n    return {i:hits[0], scene:scoped ? scoped.name : ''};\n  }\n  // 名字对不上，但子场景名唯一命中（「天台」这种）时才认；命中多个说明有歧义，不猜。\n  if(!hits.length && scenes.length === 1) return {i:scenes[0].i, scene:scenes[0].name};\n  return null;\n}\n\n// 闸二 · 边界：候选点必须落在某一块图幅里，不然就是地图管不着的地方。\nfunction mapLocInSheets(ll){\n  for(var i = 0; i < MAP_SHEETS.length; i++){\n    var b = MAP_SHEETS[i].bbox;\n    if(ll[0] >= b[0] && ll[0] <= b[2] && ll[1] >= b[1] && ll[1] <= b[3]) return true;\n  }\n  return false;\n}\n\n// 定位中间人：正文提交证据，这里裁决钉子动不动。\n// 关键约定——除了裁定通过，任何一条路径都不许改 mapPlayerIndex / mapPlayerScene。\n// 改版前是一进函数就归 -1，解析失败钉子当场消失；现在失败只是「保留上一个」。\n// 候选：{story:下标, scene} 或 {lon, lat, name, engine}。\n// 先问游戏引擎认这段字（三千多个带坐标的地点，加上交给它的家、工作、学校），认出的是剧情点就落剧情点；\n// 引擎认不出（或没装）再按面板的剧情点名字认，最后认家、工作、学校的叫法\nvar MAP_HOME_WORDS = ['家', '自己家', '自家', '家里', '家中', '主角家', '我家'];\nfunction mapLocFind(raw){\n  var core = typeof mapCore === 'function' ? mapCore() : null, w = null;\n  if(core && typeof core.whereNow === 'function'){\n    try{ w = core.whereNow(raw); }catch(err){ w = null; }\n  }\n  // 在路上（游戏引擎按最近这一趟算的，表里写「电车上」「去某处的路上」这类）\n  if(w && w.在路上 && w.从经纬 && w.到经纬) return {onroute:w};\n  if(w && w.id && w.经纬 && w.经纬.length === 2){\n    var lon = +w.经纬[0], lat = +w.经纬[1], story = -1, best = 400;\n    for(var i = 0; i < mapPointsData.length; i++){\n      var p = mapPointsData[i];\n      if(mapPrimaryName(p) !== w.id && p[2] !== w.id) continue;\n      var d = mapHaversine(lon, lat, p[0], p[1]);\n      if(d <= best){ best = d; story = i; }\n    }\n    if(story >= 0){\n      var sc = mapLocCandidate(raw);\n      return {story:story, scene:sc && sc.i === story ? sc.scene : ''};\n    }\n    var base = mapBases.filter(function(b){ return b.engine === w.id || (b.type === '家' && w.id === '家'); })[0];\n    return {lon:lon, lat:lat, name:base ? base.label : w.id, engine:w.id};\n  }\n  var c = mapLocCandidate(raw);\n  if(c) return {story:c.i, scene:c.scene};\n  var bare = raw.replace(/[\\s・·]/g, '');\n  for(var k = 0; k < mapBases.length; k++){\n    var b2 = mapBases[k];\n    var hit = b2.type === '家' ? MAP_HOME_WORDS.indexOf(bare) >= 0 || (!!b2.door && bare === String(b2.door).replace(/[\\s・·]/g, ''))\n      : !!b2.name && bare === b2.name.replace(/[\\s・·]/g, '');\n    if(hit) return {lon:b2.lon, lat:b2.lat, name:b2.label, engine:b2.engine};\n  }\n  return null;\n}\nfunction resolvePlayerLocation(){\n  var raw = typeof globalStory.location === 'string' ? globalStory.location.trim() : '';\n  if(raw === '——') raw = '';   // 接数据时地点格是空的，顶栏写占位「——」\n  var alt = typeof globalStory.locationAlt === 'string' ? globalStory.locationAlt.trim() : '';   // 详细地点认不出时退到区、街区\n  var year = typeof globalStory.year === 'number' ? globalStory.year : null;\n  var had = mapEndOK(mapPlayerIndex);\n  // 没确认过位置就谈不上保留，状态只能是 none\n  function stay(kind, why){ mapLoc.state = had ? kind : 'none'; mapLoc.reason = why; }\n\n  // 闸零 · 场景类型（接数据库以后才有这一格）：正文在写回忆、梦、想象、别人的视角，人没动。\n  // 只拦「挪动」：面板每楼新建，还没确认过位置时照地点格先落一次（模板要求这时地点格写的是现实里所在的位置）\n  var scene = globalStory.scene;\n  if(scene && scene !== '现实' && had){\n    stay('frozen', '正文在写' + scene + '，位置停在最后确认的地方');\n    return;\n  }\n\n  // 闸一 · 回忆：年份比最后一次确认时小，说明正文退回过去了，人没动。\n  // 这里不更新 mapLoc.year，所以回忆结束、年份回到现在时能自动解冻。\n  if(year !== null && mapLoc.year !== null && year < mapLoc.year){\n    stay('frozen', '正文在回忆 ' + year + ' 年，位置停在最后确认的地方');\n    return;\n  }\n  if(!raw){ stay('held', '剧情里还没写出你在哪'); return; }\n\n  var cand = mapLocFind(raw), rou