((0.5 - yn) * 2 * Math.PI)) * 180 / Math.PI];\n}\nfunction mapScreenToLL(sx, sy){\n  return mapWorldToLL((sx - mapTx) / mapK, (sy - mapTy) / mapK);\n}\nfunction mapLLToScreen(lon, lat){\n  var w = mapLLToWorld(lon, lat);\n  return [w[0] * mapK + mapTx, w[1] * mapK + mapTy];\n}\n\n// 凸包（Andrew monotone chain）：给一组屏幕点算出最外围轮廓\nfunction mapConvexHull(pts){\n  if(pts.length < 3) return pts.slice();\n  var p = pts.slice().sort(function(a, b){ return a[0] - b[0] || a[1] - b[1]; });\n  function cross(o, a, b){ return (a[0]-o[0])*(b[1]-o[1]) - (a[1]-o[1])*(b[0]-o[0]); }\n  var lo = [], hi = [], i;\n  for(i = 0; i < p.length; i++){\n    while(lo.length >= 2 && cross(lo[lo.length-2], lo[lo.length-1], p[i]) <= 0) lo.pop();\n    lo.push(p[i]);\n  }\n  for(i = p.length - 1; i >= 0; i--){\n    while(hi.length >= 2 && cross(hi[hi.length-2], hi[hi.length-1], p[i]) <= 0) hi.pop();\n    hi.push(p[i]);\n  }\n  lo.pop(); hi.pop();\n  return lo.concat(hi);\n}\n// 把轮廓向外撑开一圈，再用二次贝塞尔磨圆，做出\"地块\"而不是\"多边形\"的观感\nfunction mapBlobPath(pts, pad){\n  var cx = 0, cy = 0, i;\n  for(i = 0; i < pts.length; i++){ cx += pts[i][0]; cy += pts[i][1]; }\n  cx /= pts.length; cy /= pts.length;\n  var ex = pts.map(function(p){\n    var dx = p[0] - cx, dy = p[1] - cy, d = Math.hypot(dx, dy) || 1;\n    return [p[0] + dx / d * pad, p[1] + dy / d * pad];\n  });\n  if(ex.length === 1){\n    var r = Math.min(pad, 26);\n    return 'M' + (ex[0][0]-r) + ',' + ex[0][1] + 'a' + r + ',' + r + ' 0 1,0 ' + (r*2) + ',0a' + r + ',' + r + ' 0 1,0 ' + (-r*2) + ',0';\n  }\n  if(ex.length === 2){\n    var mx = (ex[0][0]+ex[1][0])/2, my = (ex[0][1]+ex[1][1])/2;\n    var rr = Math.hypot(ex[0][0]-mx, ex[0][1]-my) + Math.min(pad, 20);\n    return 'M' + (mx-rr) + ',' + my + 'a' + rr + ',' + rr + ' 0 1,0 ' + (rr*2) + ',0a' + rr + ',' + rr + ' 0 1,0 ' + (-rr*2) + ',0';\n  }\n  var d = '', n = ex.length;\n  for(i = 0; i < n; i++){\n    var cur = ex[i], nxt = ex[(i+1)%n];\n    var mid = [(cur[0]+nxt[0])/2, (cur[1]+nxt[1])/2];\n    if(i === 0) d += 'M' + mid[0].toFixed(1) + ',' + mid[1].toFixed(1);\n    var nn = ex[(i+2)%n];\n    var mid2 = [(nxt[0]+nn[0])/2, (nxt[1]+nn[1])/2];\n    d += 'Q' + nxt[0].toFixed(1) + ',' + nxt[1].toFixed(1) + ' ' + mid2[0].toFixed(1) + ',' + mid2[1].toFixed(1);\n  }\n  return d + 'Z';\n}\n// 一组点位里出场最多的乐队 —— 决定这块地的底色\nfunction mapGroupColor(items){\n  var c = {}, best = null, bn = 0;\n  for(var a = 0; a < items.length; a++){\n    var bands = (mapPointsData[items[a].i][6] || '').split('/');\n    for(var b = 0; b < bands.length; b++){\n      if(!bands[b]) continue;\n      c[bands[b]] = (c[bands[b]] || 0) + 1;\n      if(c[bands[b]] > bn){ bn = c[bands[b]]; best = bands[b]; }\n    }\n  }\n  return bandColors[best] || '#ff4d7d';\n}\n\n// 地区轮廓沿同一町丁目的剧情点生成，仅用于地区范围图层。\n// 路线折线的像素长度，给 stroke-dasharray 用（SVG 的 getTotalLength 要先入 DOM，这里直接算）\nvar mapRouteKey = '';\nfunction mapPathLength(d){\n  var pts = d.slice(1).split(/[ML]/), total = 0, px = 0, py = 0;\n  for(var i = 0; i < pts.length; i++){\n    var xy = pts[i].split(',');\n    var x = parseFloat(xy[0]), y = parseFloat(xy[1]);\n    if(!isFinite(x) || !isFinite(y)) continue;\n    if(i) total += Math.hypot(x - px, y - py);\n    px = x; py = y;\n  }\n  return total;\n}\nfunction renderMapUnderlay(groups){\n  if(!mapProj || !mapFit) return '';\n  var vw = mapProj.vw, vh = mapProj.vh;\n  var body = '';\n\n  // 1) 行政区块色斑\n  for(var o = 0; mapLayers.areas && o < groups.length; o++){\n    var g = groups[o];\n    if(g.level === 9) continue;                 // 像素网格分出来的组不画地块\n    var pts = g.items.map(function(t){ return [t.sx, t.sy]; });\n    var hull = mapConvexHull(pts);\n    // 留白按这块地在屏幕上的实际大小走：点少 ≠ 该画个大圆\n    var sx0 = Infinity, sx1 = -Infinity, sy0 = Infinity, sy1 = -Infinity;\n    for(var q = 0; q < pts.length; q++){\n      if(pts[q][0] < sx0) sx0 = pts[q][0];\n      if(pts[q][0] > sx1) sx1 = pts[q][0];\n      if(pts[q][1] < sy0) sy0 = pts[q][1];\n      if(pts[q][1] > sy1) sy1 = pts[q][1];\n    }\n    var pad = Math.max(14, Math.min(46, Math.max(sx1 - sx0, sy1 - sy0) * 0.16 + 14));\n    var color = mapGroupColor(g.items);\n    // 点少但摊得很开的区（比如爱知只有名古屋+知多两点）底色压淡些，\n    // 不然一个大空圆会比真正的密集区还抢眼\n    var op = g.items.length >= 5 ? 0.09 : 0.05;\n    // 一块地大到看不见轮廓时，它就不再是\"区块\"而是一片糊在屏幕上的色 —— 随尺寸淡出。\n    // 高倍率下尤其明显：町丁目的凸包会轻松铺满整屏。\n    // 撑到视口对角线的 55% 就开始淡，100% 时彻底不画：轮廓一旦跑到屏幕外，\n    // 这块色就不再传达\"范围\"，只剩一片糊在画面上的颜色。\n    var diag = Math.hypot(vw, vh);\n    var blobSize = Math.max(sx1 - sx0, sy1 - sy0) + pad * 2;\n    if(blobSize > diag * 0.55){\n      var f = 1 - (blobSize - diag * 0.55) / (diag * 0.45);\n      if(f <= 0.05) continue;\n      op *= f;\n    }\n    body += '<path class=\"area-fill\" d=\"' + mapBlobPath(hull, pad) + '\" fill=\"' + color +\n      '\" fill-opacity=\"' + op + '\" stroke=\"' + color + '\" stroke-opacity=\"' + (op * 2.4).toFixed(2) + '\"/>';\n  }\n\n  // 1.5) 导航路线：优先画真实街道折线，路网没覆盖到才退回直线\n  var nf = mapNavFrom(), nwa = mapEndWorld(nf), nwb = mapEndWorld(mapNavTo);\n  if(mapEndOK(mapNavTo) && mapEndOK(nf) && nf !== mapNavTo && nwa && nwb){\n    var rt = mapCurrentRoute(), rline = mapRailLine(nf, mapNavTo) || (rt && rt.line);\n    var dd = '';\n    if(rline && rline.length > 1){\n      for(var q2 = 0; q2 < rline.length; q2++){\n        var sp2 = mapLLToScreen(rline[q2][0], rline[q2][1]);\n        dd += (q2 ? 'L' : 'M') + sp2[0].toFixed(1) + ',' + sp2[1].toFixed(1);\n      }\n    } else {\n      var a = [nwa.wx * mapK + mapTx, nwa.wy * mapK + mapTy];\n      var b2 = [nwb.wx * mapK + mapTx, nwb.wy * mapK + mapTy];\n      dd = 'M' + a[0].toFixed(1) + ',' + a[1].toFixed(1) + 'L' + b2[0].toFixed(1) + ',' + b2[1].toFixed(1);\n    }\n    // 换了一条新路线才播「沿线生长」，同一条路线的重排不重播，\n    // 否则一边拖地图一边看着线反复从头长出来\n    var routeKey = nf + '>' + mapNavTo + '|' + mapRouteMode(nf, mapNavTo);\n    var routeCls = 'route th-map-route-line', routeStyle = '';\n    if(routeKey !== mapRouteKey){\n      mapRouteKey = routeKey;\n      var len = Math.ceil(mapPathLength(dd));\n      if(len > 0){ routeCls += ' is-drawing'; routeStyle = ' style=\"--len:' + len + 'px\"'; }\n    }\n    body += '<path class=\"' + routeCls + '\"' + routeStyle + ' d=\"' + dd +\n      '\" stroke=\"var(--accent-deep)\" stroke-opacity=\"0.8\" stroke-width=\"3\"/>';\n  }\n\n  // 2) 铁道线路 + 车站（N02 真实线形）\n  //    线越细的图幅画得越粗，缩得很小的时候只画线不画站，免得糊成一片圆点\n  if(mapLayers.routes && mapRail){\n    var mppNow = mapMppHere();\n    var lw = mppNow > 8 ? 1.4 : (mppNow > 2 ? 2.2 : 3.2);\n    // 只保留和视口（加一圈余量）相交的线段。\n    // 原来是不管在不在画面里，1168 个顶点全部投影 + toFixed + 字符串拼接，\n    // 街道级下 99% 的顶点在几十公里外，纯属白烧 CPU，SVG 也白白胖了几十 KB。\n    var CL = -MAP_MARGIN - 400, CR = vw + MAP_MARGIN + 400,\n        CT = -MAP_MARGIN - 400, CB = vh + MAP_MARGIN + 400;\n    function inBox(p){ return p[0] >= CL && p[0] <= CR && p[1] >= CT && p[1] <= CB; }\n    for(var r = 0; r < mapRail.lines.length; r++){\n      var ln = mapRail.lines[r], d = '', pen = false, prev = null, drawn = 0;\n      for(var i = 0; i < ln.g.length; i++){\n        var sp = mapLLToScreen(ln.g[i][0], ln.g[i][1]);\n        // 当前点或上一个点沾边就画这一段，跨屏的长边才不会被整段丢掉\n        var keep = inBox(sp) || (prev && inBox(prev));\n        if(keep){\n          if(!pen && prev){ d += 'M' + Math.round(prev[0]) + ',' + Math.round(prev[1]); pen = true; }\n          d += (pen ? 'L' : 'M') + Math.round(sp[0]) + ',' + Math.round(sp[1]);\n          pen = true; drawn++;\n        } else {\n          pen = false;\n        }\n        prev = sp;\n      }\n      if(!drawn) continue;\n      body += '<path class=\"route th-rail\" d=\"' + d + '\" stroke-width=\"' + lw.toFixed(1) + '\"/>';\n    }\n    // 车站：地面分辨率细到一定程度才画，否则 294 个圆点会把地图糊掉\n    if(mppNow <= 6){\n      for(var t2 = 0; t2 < mapRail.stations.length; t2++){\n        var st = mapRail.stations[t2];\n        var sp2 = mapLLToScreen(st.c[0], st.c[1]);\n        if(sp2[0] < CL || sp2[0] > CR || sp2[1] < CT || sp2[1] > CB) continue;\n        body += '<circle class=\"th-rail-st\" cx=\"' + Math.round(sp2[0]) + '\" cy=\"' + Math.round(sp2[1]) +\n                '\" r=\"' + (mppNow <= 1 ? 4 : 3) + '\"><title>' + escapeMapText(st.n) + '<\/title><\/circle>';\n      }\n    }\n  }\n\n  // 画布往四周各撑 MAP_MARGIN 像素，viewBox 跟着挪，屏幕坐标系保持不变。\n  // 于是平移时这张 SVG 早就把边缘之外画好了，不用一动就重建。\n  var M = MAP_MARGIN, W = vw + M * 2, H = vh + M * 2;\n  return '<svg class=\"th-map-underlay\" width=\"' + W + '\" height=\"' + H +\n         '\" viewBox=\"' + (-M) + ' ' + (-M) + ' ' + W + ' ' + H +\n         '\" style=\"left:' + (-M) + 'px;top:' + (-M) + 'px\">' + body + '<\/svg>';\n}\n\n// —— 点位渲染 ——\n// 同一帧内的多次拖动只刷新一次，立即渲染时会取消排队。\nvar mapNodesRaf = 0;\nfunction scheduleMapNodes(){\n  if(panelLife.events.signal.aborted) return;\n  if(mapNodesRaf) return;\n  mapNodesRaf = requestAnimationFrame(function(){ mapNodesRaf = 0; renderMapNodes(); });\n}\n// 左上角幅签：当前在哪一幅 + 上一级按钮 + 打开地图册\nfunction renderMapSheetChip(){\n  var el = document.getElementById('th-map-board-chip');\n  if(!el || !mapSheet) return;\n  el.innerHTML =\n    '<span class=\"th-map-board-here\">' + escapeMapText(mapSheet.name) + '<\/span>' +\n    '<span class=\"th-map-board-hint\">' + escapeMapText(mapSheet.sub) + '<\/span>' +\n    '<button class=\"th-map-book-btn\" title=\"地图册 / 地区目录\" aria-label=\"打开地图浏览\" aria-expanded=\"' + !!mapExplorerMode + '\">▤<\/button>';\n  panelOn(el.querySelector('.th-map-book-btn'), 'click', function(e){\n    e.stopPropagation(); toggleMapBook();\n  });\n}\n\n// 接力只在允许重排时检查；动画/手势仍持有旧坐标时不换世界。\nvar mapRelayAt = -Infinity;\nfunction mapMaybeRelay(){\n  if(mapAnim || mapZoomAnim || mapPinch || mapDragging || mapNow()-mapRelayAt < 400) return;\n  var ll = mapWorldToLL((mapProj.vw/2-mapTx)/mapK,(mapProj.vh/2-mapTy)/mapK);\n  var pick = null, area = Infinity, current = mapSheet;\n  var currentArea = (current.bbox[2]-current.bbox[0])*(current.bbox[3]-current.bbox[1]);\n  MAP_SHEETS.forEach(function(sh){\n    if(sh === current || !mapSheetHas(sh,ll[0],ll[1])) return;\n    var b=sh.bbox, a=(b[2]-b[0])*(b[3]-b[1]), f=mapFloor(sh);\n    var nativeScale=f.px/(mapLonToX(b[2])-mapLonToX(b[0]));\n    var k