\n  });\n}\n\n// 把某个行政单元（前 level 段路径相同的全部点位）框进视口。\n// 跨幅时先切到整批点都装得下的最细一幅。\nfunction zoomMapToAdmin(level, key){\n  if(!mapProj) return;\n  var hits = [];\n  for(var i = 0; i < mapPointsData.length; i++)\n    if(mapAdminSlice(mapPointsData[i], level)[0] === key) hits.push(i);\n  if(!hits.length) return;\n  var lo0 = Infinity, la0 = Infinity, lo1 = -Infinity, la1 = -Infinity;\n  for(var h = 0; h < hits.length; h++){\n    var p = mapPointsData[hits[h]];\n    lo0 = Math.min(lo0, p[0]); lo1 = Math.max(lo1, p[0]);\n    la0 = Math.min(la0, p[1]); la1 = Math.max(la1, p[1]);\n  }\n  var best = null, ba = Infinity;\n  for(var q = 0; q < MAP_SHEETS.length; q++){\n    var sh = MAP_SHEETS[q], b = sh.bbox;\n    if(!(b[0] <= lo0 && b[2] >= lo1 && b[1] <= la0 && b[3] >= la1)) continue;\n    var a = (b[2] - b[0]) * (b[3] - b[1]);\n    if(a < ba){ ba = a; best = sh; }\n  }\n  if(best && best !== mapSheet) enterMapSheet(best.id);\n  if(!mapSheet) return;\n  var c0 = mapLLToWorld(lo0, la1), c1 = mapLLToWorld(lo1, la0);\n  zoomMapToWorldBox([c0[0], c0[1], c1[0], c1[1]], true);\n}\n\n// 把一块图片像素矩形框进视口。缩放照样锁在 铺满↔1:1。\n// inset：地图上浮着的卡片挡住的那几边（像素，{l,t,r,b}），取景只用剩下那一块，框进来的东西不落在卡片底下\nfunction zoomMapToWorldBox(box, fitOnly, inset){\n  if(!mapProj || !mapSheet) return;\n  var g = inset || {l:0, t:0, r:0, b:0};\n  var vw = mapProj.vw, vh = mapProj.vh;\n  var fw = Math.max(vw - g.l - g.r, 1), fh = Math.max(vh - g.t - g.b, 1), pad = Math.min(70, fw / 5, fh / 5);\n  var w = Math.max(box[2] - box[0], 1e-6), h = Math.max(box[3] - box[1], 1e-6);\n  var k = Math.min((fw - pad * 2) / w, (fh - pad * 2) / h);\n  if(!fitOnly){\n    // 一次点击最多往下钻一级，别一步冲到底\n    k = Math.max(k, mapK * 1.8);\n    k = Math.min(k, mapK * 5);\n  }\n  var cx = (box[0] + box[2]) / 2, cy = (box[1] + box[3]) / 2;\n  k = Math.max(mapMinK(), Math.min(mapCeilK(cx, cy, k), k));\n  // 空出来那一块的中心不在视口正中：相机往反方向挪，框的中心落在空处的正中\n  mapCameraTo(cx - (g.l - g.r) / 2 / k, cy - (g.t - g.b) / 2 / k, k);\n}\n// 浮在地图上的东西（侧栏或收起后的窄栏、导航卡、底下的地点卡、住这里）各挡住哪一边。窄屏上这些卡接在地图下面，不压地图，量出来是 0。\n// 挡掉以后剩下的宽或高不到三成五，就不让那一边（卡太大，让了反而什么都看不清）\nfunction mapOverlayInset(){\n  var g = {l:0, t:0, r:0, b:0};\n  if(!mapViewportEl || !mapProj) return g;\n  var vp = mapViewportEl.getBoundingClientRect();\n  if(!vp.width || !vp.height) return g;\n  var els = [typeof mapSideEl !== 'undefined' ? mapSideEl : null, document.getElementById('th-map-nav'), document.getElementById('th-map-house'),\n    typeof mapSidePeekEl !== 'undefined' ? mapSidePeekEl : null, typeof mapSideMiniEl !== 'undefined' ? mapSideMiniEl : null];\n  for(var i = 0; i < els.length; i++){\n    var el = els[i];\n    if(!el || el.hidden || el.style.display === 'none' || !el.offsetParent) continue;\n    var r = el.getBoundingClientRect();\n    if(!r.width || !r.height || r.right <= vp.left || r.left >= vp.right || r.bottom <= vp.top || r.top >= vp.bottom) continue;\n    if(r.top - vp.top > vp.height * 0.5) g.b = Math.max(g.b, vp.bottom - r.top + 8);\n    else if(r.left - vp.left < vp.width * 0.5) g.l = Math.max(g.l, r.right - vp.left + 8);\n    else g.r = Math.max(g.r, vp.right - r.left + 8);\n  }\n  if(vp.width - g.l - g.r < vp.width * 0.35){ g.l = 0; g.r = 0; }\n  if(vp.height - g.t - g.b < vp.height * 0.35){ g.t = 0; g.b = 0; }\n  return g;\n}\n// 定位落点：底图有多细就落多细，在 0.5～2 m/px 之间取。\n// 原来一律落在 2 m/px —— 在有 0.2 m/px 特写的地方等于白瞎了素材。\nvar MAP_FLY_MPP = 2, MAP_FLY_MPP_MIN = 0.5;\nfunction mapFlyK(k, cx, cy){\n  if(!k){\n    var nat = cx == null ? 0 : mapNativeMppAt(cx, cy);\n    var want = nat > 0 ? Math.min(MAP_FLY_MPP, Math.max(MAP_FLY_MPP_MIN, nat * 1.2)) : MAP_FLY_MPP;\n    k = mapFloorMpp() / want;\n  }\n  return Math.max(mapMinK(), Math.min(mapCeilK(cx, cy, k), k));\n}\nfunction flyToMapLL(lon, lat, k){\n  if(!mapProj) return;\n  var want = mapDeepestSheet(lon, lat);\n  if(!want) return;\n  if(!mapSheet || want.id !== mapSheet.id) enterMapSheet(want.id, null, null, true);\n  var w = mapLLToWorld(lon, lat), kk = mapFlyK(k, w[0], w[1]), fc = mapFreeCenter();\n  mapCameraTo(w[0] - (fc.x - mapProj.vw / 2) / kk, w[1] - (fc.y - mapProj.vh / 2) / kk, kk);\n}\n// 导航端点：剧情点照旧，别的按经纬飞\nfunction flyToMapEnd(h, k){\n  if(h >= 0){ flyToMapPoint(h, k); return; }\n  var ll = mapEndLL(h);\n  if(ll) flyToMapLL(ll[0], ll[1], k);\n}\nfunction flyToMapPoint(idx, k){\n  if(!mapProj || !mapWorld[idx]) return;\n  var p = mapPointsData[idx];\n  var want = mapDeepestSheet(p[0], p[1]);\n  // 当前 172 个点均有图幅；为后续新增的幅外点保留兜底\n  if(!want) return;\n  if(!mapSheet || want.id !== mapSheet.id){\n    enterMapSheet(want.id, idx, k);\n    return;\n  }\n  // 镜头中心往回挪半个侧栏（窄屏是半个抽屉），点落在露出来那块的正中\n  var kk = mapFlyK(k, mapWorld[idx].wx, mapWorld[idx].wy), fc = mapFreeCenter();\n  mapCameraTo(mapWorld[idx].wx - (fc.x - mapProj.vw / 2) / kk, mapWorld[idx].wy - (fc.y - mapProj.vh / 2) / kk, kk);\n}\n\n// —— 地区目录：日本 → 都道府县 → 市区町村 → 町丁目 → 点位，和角色/剧情同一套抽屉交互 ——\nvar mapDirOpen = {};   // 展开状态，key 为行政路径\nfunction buildMapAdminTree(){\n  var root = {};\n  for(var i = 0; i < mapPointsData.length; i++){\n    var a = mapAdminOf(mapPointsData[i]);\n    var p1 = a[0] || '其他', p2 = a[1] || '其他', p3 = a[2] || '（未细分）';\n    if(!root[p1]) root[p1] = {n:0, kids:{}};\n    root[p1].n++;\n    if(!root[p1].kids[p2]) root[p1].kids[p2] = {n:0, kids:{}};\n    root[p1].kids[p2].n++;\n    if(!root[p1].kids[p2].kids[p3]) root[p1].kids[p2].kids[p3] = {n:0, idxs:[]};\n    root[p1].kids[p2].kids[p3].n++;\n    root[p1].kids[p2].kids[p3].idxs.push(i);\n  }\n  return root;\n}\n// 场景库的一行：能跳到地图点位的标成可点，其余只展示原文引证\nfunction renderSceneRow(node, key, lv){\n  var n = countScenes(node) - 1;\n  var band = (node.b && node.b[0]) || '';\n  var open = mapDirOpen[key];\n  var h = '<div class=\"th-map-dir-row lv' + lv + (open ? ' open' : '') + (node.p ? ' has-pt' : '') +\n    '\" data-sk=\"' + escapeMapText(key) + '\"' + (node.p ? ' data-spt=\"' + escapeMapText(node.p) + '\"' : '') + '>' +\n    (node.c ? '<span class=\"tw\">▶<\/span>' : '<span class=\"tw\"><\/span>') +\n    '<span class=\"nm\">' + escapeMapText(node.n) + '<\/span>' +\n    (band ? '<span class=\"band\" style=\"--b-color:' + (bandColors[band] || 'var(--accent)') + '\">' +\n       escapeMapText(band.replace('Hello, Happy World!', 'HHW').replace('RAISE A SUILEN', 'RAS')) + '<\/span>' : '') +\n    (node.q && lv > 1 ? '<span class=\"q\">' + escapeMapText(node.q) + '<\/span>' : '') +\n    (n ? '<span class=\"ct\">' + n + '<\/span>' : '') + '<\/div>';\n  if(open && node.c){\n    for(var i = 0; i < node.c.length; i++){\n      h += renderSceneRow(node.c[i], key + '/' + i, Math.min(4, lv + 1));\n    }\n  }\n  return h;\n}\nfunction countScenes(n){\n  var t = 1;\n  if(n.c) for(var i = 0; i < n.c.length; i++) t += countScenes(n.c[i]);\n  return t;\n}\nfunction findSceneByKey(key){\n  var parts = key.split('/');\n  var node = mapScenesFloating[parseInt(parts[0].slice(3), 10)];\n  for(var i = 1; i < parts.length && node; i++) node = (node.c || [])[parseInt(parts[i], 10)];\n  return node;\n}\n\nfunction renderMapDirectory(){\n  var tree = buildMapAdminTree();\n  var html = '';\n  function row(cls, key, label, count, lv, dataAttr){\n    return '<div class=\"th-map-dir-row ' + cls + (mapDirOpen[key] ? ' open' : '') + '\" data-key=\"' + escapeMapText(key) + '\" ' + dataAttr + '>' +\n      (lv < 4 ? '<span class=\"tw\">▶<\/span>' : '<span class=\"tw\"><\/span>') +\n      '<span class=\"nm\">' + escapeMapText(label) + '<\/span>' +\n      (count ? '<span class=\"ct\">' + count + '<\/span>' : '') + '<\/div>';\n  }\n  Object.keys(tree).sort(function(a, b){ return tree[b].n - tree[a].n; }).forEach(function(p1){\n    var k1 = p1;\n    html += row('lv1', k1, p1, tree[p1].n, 1, 'data-zoom=\"1\" data-zk=\"' + escapeMapText(p1) + '\"');\n    if(!mapDirOpen[k1]) return;\n    Object.keys(tree[p1].kids).sort(function(a, b){ return tree[p1].kids[b].n - tree[p1].kids[a].n; }).forEach(function(p2){\n      var k2 = p1 + '/' + p2;\n      html += row('lv2', k2, p2, tree[p1].kids[p2].n, 2, 'data-zoom=\"2\" data-zk=\"' + escapeMapText(k2) + '\"');\n      if(!mapDirOpen[k2]) return;\n      Object.keys(tree[p1].kids[p2].kids).sort(function(a, b){ return tree[p1].kids[p2].kids[b].n - tree[p1].kids[p2].kids[a].n; }).forEach(function(p3){\n        var k3 = k2 + '/' + p3;\n        var leaf = tree[p1].kids[p2].kids[p3];\n        html += row('lv3', k3, p3, leaf.n, 3, 'data-zoom=\"3\" data-zk=\"' + escapeMapText(p3 === '（未细分）' ? k2 + '/' : k3) + '\"');\n        if(!mapDirOpen[k3]) return;\n        leaf.idxs.forEach(function(i){\n          html += '<div class=\"th-map-dir-row lv4' + (i === mapSelectedIndex ? ' is-sel' : '') + '\" data-pt=\"' + i + '\">' +\n            '<span class=\"tw\"><\/span><span class=\"nm\">' + escapeMapText(mapPrimaryName(mapPointsData[i])) + '<\/span><\/div>';\n        });\n      });\n    });\n  });\n  // 异地场景（度假地、海外、旅行）在地图上没有坐标，不列进地区目录（补丁 17，09-14 用户要求拿掉）\n  mapDirBodyEl.innerHTML = html || '<div class=\"th-map-dir-row\"><span class=\"nm\">暂无点位<\/span><\/div>';\n\n  mapDirBodyEl.querySelectorAll('.th-map-dir-row[data-key]').forEach(function(el){\n    panelOn(el, 'click', function(){\n      var k = el.dataset.key;\n      mapDirOpen[k] = !mapDirOpen[k];\n      if(mapDirOpen[k] && el.dataset.zk) zoomMapToAdmin(parseInt(el.dataset.zoom, 10), el.dataset.zk);\n      renderMapDirectory();\n    });\n  });\n  mapDirBodyEl.querySelectorAll('.th-map-dir-row[data-sk]').forEach(function(el){\n    panelOn(el, 'click', function(e){\n      e.stopPropagation();\n      var k = el.dataset.sk;\n      // 这个场景本身也是地图上的点 —— 直接跳过去，否则只做展开/收起\n      if(el.dataset.spt){\n        var pi = mapPointIds.indexOf(el.dataset.spt);\n        if(pi >= 0){ flyToMapPoint(pi); selectMapPoint(pi); }\n      }\n      var node = findSceneByKey(k);\n      if(node && node.c) mapDirOpen[k] = !mapDirOpen[k];\n      renderMapDirectory();\n    });\n  });\n  mapDirBodyEl.querySelectorAll('.th-map-dir-row[data-pt]').forEach(function(el){\n    panelOn(el, 'click', function(){\n      var i = parseInt(el.dataset.pt, 10);\n      flyToMapPoint(i);\n      selectMapPoint(i);\n      renderMapDirectory();\n    });\n  });\n}\n// —— 图层开关面板 ——\nvar mapLayersEl = document.getElementById('th-map-layers');\nvar mapLayersBodyEl = document.getElementById('th-map-layers-body');\nvar mapLayersBtn = document.getElementById('th-map-layers-btn');\nvar MAP_LAYER_DEFS = [\n  {key:'basemap', name:'插画底图'},\n  {key:'areas',   name:'地区范围（示意）'},\n  {key:'routes',  name:'铁道 / 车站'},\n  {key:'markers', name:'地点 / 地标'},\n  {key:'estate',  name:'住宅区'}\n];\nfunction mapLmViewState(){\n  var states = mapLmForView().map(function(s){ return mapLm[s.id] ? mapLm[s.id].state : ''; });\n  return states.indexOf('loading') >= 0 ? '地标加载中…' : states.indexOf('off') >= 0 ? '部分地标未加载' : '';\n}\nfunction mapLayerAvailable(key){\n  if(!mapSheet) return false;\n  if(key==='basemap') return mapSheet.layers.some(function(L){return !!L.url && L.url!=='TODO_UPLOAD';});\n  if(key==='markers') return mapPointsData.length > 0 || mapPoiUsable();\n  if(key==='areas') return mapSheetAllPts(mapSheet).length > 0;\n  if(key==='estate') return !!mapCore() && typeof mapEstate === 'function' && !!mapEstate();\n  if(key!=='routes' || !mapRail) return false;\n  if(mapRail.stations.some(function(st){return mapSheetHas(mapSheet,st.c[0],st.c[1]);})) return true;\n  // Liang–Barsky: a segment may cross the bbox with both endpoints outside.\n  var b=mapSheet.bbox;\n  function crosses(a,z){\n    var dx=z[0]-a[0],dy=z[1]-a[1],p=[-dx,dx,-dy,dy],q=[a[0]-b[0],b[2]-a[0],a[1]-b[1],b[3]-a[1]],lo=0,hi=1;\n    for(var i=0;i<4;i++){if(p[i]===0){if(q[i]<0)return false;}else{var t=q[i]/p[i];if(p[i]<0)lo=Math.max(lo,t);else hi=Math.min(hi,t);if(lo>hi)return false;}}\n    return true;\n  }\n  return mapRail.lines.some(function(ln){for(var i=1;i<ln.g.length;i++)if(crosses(ln.g[i-1],ln.g[i]))return true;return false;});\n}\nfunction renderMapLayersPanel(){\n  var focused = document.activeElement && document.activeElement.dataset.k;\n  var lmView = mapLmViewState();\n  mapLayersBodyEl.innerHTML = MAP_LAYER_DEFS.map(function(d)