ase 'ArrowLeft':  mapPanBy(step, 0); break;\n    case 'ArrowRight': mapPanBy(-step, 0); break;\n    case 'ArrowUp':    mapPanBy(0, step); break;\n    case 'ArrowDown':  mapPanBy(0, -step); break;\n    case '+': case '=': zoomMapAt(mapK * 1.8, mapProj.vw / 2, mapProj.vh / 2); break;\n    case '-': case '_': zoomMapAt(mapK / 1.8, mapProj.vw / 2, mapProj.vh / 2); break;\n    case '0': enterMapSheet(mapSheet.id); break;\n    default: ok = false;\n  }\n  if(ok) e.preventDefault();\n});\n\n// 视口尺寸变化（页面刚显示、面板折叠/展开、窗口缩放）时补渲染，尺寸没真变就不重画\nvar mapResizeObserver = null;\nif(window.ResizeObserver){\n  mapResizeObserver = new ResizeObserver(panelGuard(function(){\n    var vw = mapViewportEl.clientWidth, vh = mapViewportEl.clientHeight;\n    if(!vw || !vh) return;\n    if(mapProj && mapProj.vw === vw && mapProj.vh === vh) return;\n    renderMapPage();\n  }));\n  mapResizeObserver.observe(mapViewportEl);\n}\n\nrenderChar();\nrenderTeamList();\nrenderPresence();\nrenderActivity();\nrenderStoryDashboard();\nsyncDrawerTop(drawer);\n// 首次打开且未选择角色时，自动展开抽屉引导选择；手机上抽屉是整窗的下一页，不自己弹，角色页顶上那排头像就是入口\nif(cur === -1 && !thIsMobile()){ openDrawer(); }\n\n// ===== 补丁 19：主角状态页 =====\n// 字段留空，等状态栏填；空的渲染成占位提示，和 chars 一个待遇。\n// skills[].now 是五档里的第几档（1–5）：摸索 / 弹整首 / 能合奏 / 能登台 / 能主导。\n// items 分「随身 / 家里」——只按「在哪」这一个轴分组；借来的挂 borrow 标记，\n// 因为「是谁的」是另一个轴，硬塞进分组会和「家里」打架。\nvar player = {\n  name: '', romaji: '', tags: [],\n  hp: null, money: '', conds: [], wear: '',\n  next: { time: '', text: '' },\n  portrait: '',\n  skills: [],          // {name, meta, tier, now, note}\n  items: { carry: [], home: [] }   // {name, star?, borrow?}\n};\n\n// 水印：字号永远 132px 不缩，只有会被硬切时才加 .bleed 把尾巴化掉。\n//\n// 「会被硬切」的位置是卡片右缘——卡片是 overflow:hidden，水印从 left:16px 起跑，\n// 跑过右缘就被齐刷刷剪断，那才难看。中途从立绘背后穿过没关系：立绘不透明，\n// 水印本来就是 6% 的淡色，主要角色页那张一直就是这么跑的。\n// 所以可用宽是「卡片宽减去自己的 left」，不去扣立绘——扣了的话 850px 宽的卡上\n// 连 HARUKA（527px）都会被判渐隐，明显过严。\nvar PC_WM_LEFT = 16;\nfunction pcWatermark(){\n  var el = document.getElementById('th-pc-wm'), card = document.querySelector('.th-pc-card');\n  if(!el) return;\n  // 取「名」不取姓、全大写，和 watermarkMap 的规矩一致（户山香澄 → KASUMI）\n  var parts = String(player.romaji || '').trim().split(/\\s+/).filter(Boolean);\n  el.textContent = parts.length ? parts[parts.length - 1].toUpperCase() : '';\n  el.classList.remove('bleed');\n  if(!el.textContent || !card) return;\n  var room = Math.max(160, card.clientWidth - PC_WM_LEFT);\n  if(el.scrollWidth > room) el.classList.add('bleed');\n}\n\nfunction pcText(el, val, hint){\n  if(!el) return;\n  el.textContent = val || hint || '';\n  el.classList.toggle('th-placeholder', !val);\n}\n\nfunction renderPlayerCard(){\n  var tags = document.getElementById('th-pc-tags');\n  if(!tags) return;\n  tags.innerHTML = (player.tags || []).map(function(t, i){\n    return '<span class=\"th-pc-tag' + (i === 0 ? ' lead' : '') + '\">' + escapeMapText(t) + '<\/span>';\n  }).join('') || '<span class=\"th-pc-tag th-placeholder\">身份待填写<\/span>';\n\n  pcText(document.getElementById('th-pc-name'), player.name, '主角');\n  pcText(document.getElementById('th-pc-romaji'), player.romaji, '');\n\n  var hp = typeof player.hp === 'number' ? Math.max(0, Math.min(100, player.hp)) : null;\n  var pct = document.getElementById('th-pc-hppct');\n  thermoSet(document.getElementById('th-pc-hp-th'), hp, 'hp');   // 温度计（29）\n  if(pct){ pct.textContent = hp === null ? '——' : String(hp); pct.classList.toggle('th-placeholder', hp === null); }\n\n  var conds = document.getElementById('th-pc-conds');\n  if(conds) conds.innerHTML = (player.conds || []).map(function(c, i){\n    var t = typeof c === 'string' ? c : c.text;\n    var hot = typeof c === 'object' && c.hot;\n    return '<span class=\"th-pc-cond' + (hot || i === 0 ? ' hot' : '') + '\"><span class=\"th-pc-txt\">' + escapeMapText(t) + '<\/span><\/span>';\n  }).join('') || '<span class=\"th-pc-cond th-placeholder\">——<\/span>';\n\n  pcText(document.getElementById('th-pc-money'), player.money, '——');\n  pcText(document.getElementById('th-pc-wear'), player.wear, '待填写');\n\n  var next = document.getElementById('th-pc-next');\n  if(next){\n    var n = player.next || {};\n    next.innerHTML = '<svg class=\"th-icon\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"8.5\"><\/circle><path d=\"M12 7.5v4.8l3.4 2\"><\/path><\/svg>'\n      + '<span class=\"th-pc-next-k\">接下来<\/span>'\n      + (n.time ? '<span class=\"th-pc-next-t\">' + escapeMapText(n.time) + '<\/span>' : '')\n      + '<span class=\"th-pc-next-v' + (n.text ? '' : ' th-placeholder') + '\">' + escapeMapText(n.text || '剧情里还没写出下一步') + '<\/span>';\n  }\n\n  var por = document.getElementById('th-pc-portrait');\n  if(por && player.portrait){\n    por.innerHTML = '<img src=\"' + escapeMapText(player.portrait) + '\" alt=\"主角立绘\">';\n  }\n\n  var sk = document.getElementById('th-pc-skills');\n  if(sk) sk.innerHTML = (player.skills || []).map(function(s){\n    var tiers = '';\n    for(var i = 1; i <= 5; i++){\n      tiers += '<div class=\"th-pc-tier' + (i < s.now ? ' past' : (i === s.now ? ' now' : '')) + '\"><\/div>';\n    }\n    return '<div class=\"th-pc-skill\"><div class=\"th-pc-sk-l\">'\n      + '<div class=\"th-pc-sk-n\">' + escapeMapText(s.name) + '<\/div>'\n      + '<div class=\"th-pc-sk-d th-sbox\">' + escapeMapText(s.note || '') + '<\/div><\/div>'\n      + '<div class=\"th-pc-sk-r\"><div class=\"th-pc-sk-m\">' + escapeMapText(s.meta || '')\n      + (s.tier ? ' · <b>' + escapeMapText(s.tier) + '<\/b>' : '') + '<\/div>'\n      + '<div class=\"th-pc-tiers\">' + tiers + '<\/div><\/div><\/div>';\n  }).join('') || '<div class=\"th-pc-empty\">还没练出什么来。<\/div>';\n\n  var it = document.getElementById('th-pc-items');\n  if(it){\n    var g = player.items || {};\n    function group(label, note, list, away){\n      if(!list || !list.length) return '';\n      return '<div class=\"th-pc-group\"><div class=\"th-pc-ghead\"><span>' + label + '<\/span>'\n        + (note ? '<em>' + note + '<\/em>' : '') + '<i><\/i><\/div><div class=\"th-pc-items\">'\n        + list.map(function(x){\n            var o = typeof x === 'string' ? { name: x } : x;\n            return '<span class=\"th-pc-item' + (away ? ' away' : '') + (o.star ? ' star' : '') + '\">'\n              + (o.borrow ? '<span class=\"th-pc-borrow\">借<\/span>' : '')\n              + '<span class=\"th-pc-txt\">' + escapeMapText(o.name) + '<\/span><\/span>';\n          }).join('') + '<\/div><\/div>';\n    }\n    it.innerHTML = (group('随身', '今天带着', g.carry, false) + group('家里', '', g.home, true))\n      || '<div class=\"th-pc-empty\">身上什么都没有。<\/div>';\n  }\n  pcWatermark();\n  panelSboxAll(pagePlayer);   // 状况签、穿着、技能进展限高框里滚（05）\n}\n\n// 上传的立绘先缩到 600×800 以内再存：原图动辄几 MB，存进聊天会把聊天文件撑大。\n// 能出 webp 就用 webp（留透明、体积小），出不了的浏览器 PNG、GIF 存 PNG，别的存 JPG\nfunction pcShrink(f, done){\n  var r = new FileReader();\n  r.onload = function(){\n    var img = new Image();\n    img.onload = function(){\n      var k = Math.min(1, 600 / img.width, 800 / img.height);\n      var w = Math.max(1, Math.round(img.width * k)), h = Math.max(1, Math.round(img.height * k));\n      var c = document.createElement('canvas');\n      c.width = w; c.height = h;\n      c.getContext('2d').drawImage(img, 0, 0, w, h);\n      var out = c.toDataURL('image/webp', 0.86);\n      if(out.indexOf('data:image/webp') !== 0) out = /png|gif/.test(f.type) ? c.toDataURL('image/png') : c.toDataURL('image/jpeg', 0.86);\n      done(out);\n    };\n    img.onerror = function(){ done(''); };\n    img.src = r.result;\n  };\n  r.onerror = function(){ done(''); };\n  r.readAsDataURL(f);\n}\n\n// —— 翻面与切换：动效参数和主要角色页、地图侧栏同源 ——\n(function(){\n  var flip = document.getElementById('th-pc-flip'), levels = document.getElementById('th-pc-levels');\n  var handle = document.getElementById('th-pc-handle'), ret = document.getElementById('th-pc-return');\n  var seg = document.getElementById('th-pc-seg');\n  if(!flip) return;\n  if(handle) panelOn(handle, 'click', function(){ flip.classList.add('flipped'); panelSboxAll(document.getElementById('th-pc-skills')); });\n  if(ret) panelOn(ret, 'click', function(){ flip.classList.remove('flipped'); });\n  if(seg) panelOn(seg, 'click', function(e){\n    var b = e.target.closest('button[data-seg]');\n    if(!b) return;\n    seg.querySelectorAll('button').forEach(function(x){ x.classList.toggle('on', x === b); });\n    levels.classList.toggle('level-1', b.dataset.seg === '1');\n  });\n  // 主角立绘：上传的图缩好交给总控存进这个聊天，每一楼的面板打开时读回来（mapCore 在 21，函数声明提前可用）。\n  // 独立预览版没有总控，只在这一页里换\n  var por = document.getElementById('th-pc-portrait'), file = document.getElementById('th-pc-file');\n  if(por && file){\n    panelOn(por, 'click', function(){ file.click(); });\n    panelOn(file, 'change', function(){\n      var f = file.files && file.files[0];\n      file.value = '';\n      if(!f) return;\n      pcShrink(f, panelGuard(function(src){\n        if(!src) return;\n        player.portrait = src;\n        renderPlayerCard();\n        var core = mapCore();\n        if(core && typeof core.setPortrait === 'function') core.setPortrait(src);\n      }));\n    });\n  }\n  var core0 = mapCore();\n  if(core0 && typeof core0.portrait === 'function'){\n    try { player.portrait = core0.portrait() || player.portrait; } catch(err){ /* 读不出来就当没传过 */ }\n  }\n  renderPlayerCard();\n  panelOn(window, 'resize', pcWatermark);\n})();\n\n// ===== 顶部信息栏：数据 + 折叠交互 =====\ndocument.getElementById('th-info-time').textContent = globalStory.time;\ndocument.getElementById('th-info-location').textContent = globalStory.location;\n\nvar infoToggle = document.getElementById('th-info-toggle');\n// ===== 主角状态手风琴区块 =====\ndocument.querySelectorAll('.th-acc-header').forEach(function(head){\n  panelOn(head, 'click', function(){\n    var body = document.getElementById(head.dataset.acc);\n    if(!body) return;\n    body.classList.toggle('collapsed');\n    var arrow = head.querySelector('.th-acc-arrow');\n    if(arrow) arrow.textContent = body.classList.contains('collapsed') ? '▼' : '▲';\n  });\n});\n\nvar collapsible = document.getElementById('th-collapsible');\nvar isCollapsed = false;\n\n// ===== 折叠态「正在浏览」胶囊 + 双色底纹：仅在折叠且已选中角色时激活 =====\n// 时间/地点胶囊任何状态下都保持可见，此函数只负责胶囊内容与 .active-char 状态类\nfunction updateNowPlayingPill(){\n  var show = isCollapsed && cur !== -1;\n  infoBar.classList.toggle('active-char', show);\n  if(!show) return;\n\n  var c = chars[cur];\n  var iconUrl = bandIconMap[c.team] || '';\n  nowPlayingEmblemEl.onerror = panelGuard(function(){ nowPlayingEmblemEl.style.display = 'none'; });\n  if(iconUrl){\n    nowPlayingEmblemEl.src = iconUrl;\n    nowPlayingEmblemEl.style.display = 'inline-block';\n  } else {\n    nowPlayingEmblemEl.style.display = 'none';\n  }\n  nowPlayingCnEl.textContent = c.name;\n  nowPlayingEnEl.textContent = watermarkMap[c.name] || '';\n  var personal = charColors[c.name] || '#ff4d7d';\n  nowPlayingNoteEl.style.color = personal;\n  nowPlayingNoteEl.textContent = '♪';\n  nowPlayingStarEl.style.display = (favoriteName === c.name) ? 'inline' : 'none';\n\n  var primary = bandColors[c.team] || personal;\n  var extras = bandColorsExtra[c.team] || [];\n  var stops = [personal, primary].concat(extras);\n  infoBar.style.setProperty('--bar-a', personal);\n  infoBar.style.setProperty('--bar-b', primary);\n  infoBar.style.setProperty('--bar-grad', 'linear-gradient(90deg, ' + stops.join(', ') + ')');\n}\n\npanelOn(infoBar, 'click', function(){\n  // 手机上面板是定高小窗，顶栏只是时间地点和 ⚙，不收起\n  if(thIsMobile()) return;\n  isCollapsed = !isCollapsed;\n  var infoToggleIcon = infoToggle.querySelector('.th-icon');\n  if(isCollapsed){\n    closeDrawer(); // 折叠时右侧抽屉一起隐藏\n    collapsible.classList.add('collapsed');\n    if(infoToggleIcon) infoToggleIcon.classList.add('flip');\n  } else {\n    collapsible.classList.remove('collapsed');\n    if(infoToggleIcon) infoToggleIcon.classList.remove('flip');\n    syncDrawerTop();\n  }\n  updateNowPlayingPill();\n});\n\n\n// ===== 接数据：此刻的数据从总控核心来（snapshot()），填进面板原来那几个数据位 =====\n// 独立预览版没有核心，这一节什么都不做，面板保持原来的演示数据（冒烟测试、跑分照旧）。\n// 表 → 面板：\n//   全局数据表 → globalStory：顶栏时间、地点，剧情页年份，地图钉子；场景类型写进 globalStory.scene，\n//              不是「现实」时地点不改、定位中间人的闸零把钉子停住，不跟着回忆、梦跑。\n//   重要角色表 → chars[i] 的好感、信任、关系阶段、心声；表里没有的人好感、信任显示「——」。\n//              是否离场 → 动态页的在场角色；最近变化（「好感 +20 · 一起修琴」）→ 动态页的变化流水。\n//              是否离场、此刻所在、最近见面 → 角色页「此刻」那一行（23）。\n//   主角档案表 + 主角现况表 + 技能表 + 物品表 + 日程表 → 主角页（player）。\n//   据点表 → 地图上家、工作、学校的标记和快捷钮（21）。\n// 数据库每填完一轮表，核心发 BanGCtl:data，这里攒 300ms 再整体重画一次。\n(function(){\n  var core = window.BanGCtl || (window.parent && window.parent.BanGCtl);\n  if(window.面板内嵌静态 || !core || typeof core.snapshot !== 'function') return;\n\n  var STAGES = ['讨厌的人', '陌生人', '普通朋友', '在意的人', '挚友', '情侣', '夫妻'];   // 和手账本同一套七档\n  var SKILL_TIERS = ['摸索', '弹整首', '能合奏', '能登台', '能主导'];   // 乐器、歌唱的五档，和 0 层卡、主角页同名\n\n  // 好感、信任是千分制：-1000～1000\n  function clampNum(v){ return typeof v === 'number' && isFinite(v) ? Math.max(-1000, Math.min(1000, Math.round(v))) : null; }\n\n  // 面板名单里 RAISE A SUILEN 五人写成「和奏瑞依（LAYER）」这种带艺名的全名，表里（核心按 名单.py 归一过）只写本名：\n  // 去掉括号再对，对上了换回面板里的写法；对不上的原样留着，面板找不到这个人就不画\n  var PANEL_NAME = {};\n  chars.forEach(function(c){ PANEL_NAME[c.name.replace(/（.*?）|\\(.*?\\)/g, '').trim()] = c.name; });\n  function panelName(n){ return PANEL_NAME[n] || n; }\n\n  // 「2020-04-18 周六 16:10」+「春 · 新学期」→「春・4 月 18 日・周六 16:10」（顶栏和剧情页原来就是这个样子）\n  function timeText(snap){\n    var m = /^(\\d{4})-(\\d{1,2})-(\\d{1,2})\\s*(周.)?\\s*(\\d{1,2}:\\d{2})?/.exec(String(snap.当前时间 || '').trim());\n    var season = String(snap.时节 || '').split(/\\s*·\\s*/)[0];\n    if(!m) return snap.当前时间 || season || '——';\n    return [season, Number(m[2]) + ' 月 ' + Number(m[3]) + ' 日', [m[4], m[5]].filter(Boolean).join(' ')].filter(Boolean).join('・');\n  }\n\n  function applyStory(snap){\n    globalStory.time = timeText(snap);\n    // 故事里的今天（「2019-04-15」）：剧情页按它判收录能不能开\n    var ymd = /^(\\d{4})-(\\d{1,2})-(\\d{1,2})/.exec(String(snap.当前时间 || '').trim());\n    globalStory.date = ymd ? ymd[1] + '-' + ('0' + ymd[2]).slice(-2) + '-' + ('0' + ymd[3]).slice(-2) : '';\n    var y = parseInt(String(snap.年份 || ''), 10);   // 「2020年」也认\n    if(y) globalStory.year = y;\n    // 场景类型交给定位中间人的闸零（resolvePlayerLocation）：不是「现实」钉子就不动。\n    // 地点照读：模板要求回忆、梦里地点三列也保持现实里所在的位置；面板每楼新建，不读就一直是演示用的「教学楼・天台」\n    globalStory.scene = String(snap.场景类型 || '').trim() || '现实';\n    var place = snap.地点 && (snap.地点.详细 || snap.地点.次要);\n    globalStory.location = place ? String(place).trim() : '——';\n    // 详细地点在地图上认不出时，定位中间人退到区、街区（11 resolvePlayerLocation）\n    globalStory.locationAlt = snap.地点 && snap.地点.详细 && snap.地点.次要 ? String(snap.地点.次要).trim() : '';\n  }\n\n  // 乐队表的状态、剧情开关 → 剧情页（03、07）：乐队格子照状态画，详情里的开关行读开关\n  function applyStoryState(snap){\n    var bands = snap.乐队 || [];\n    storyBandStatus = bands.length ? {} : null;\n    bands.forEach(function(r){ var n = String(r.乐队 || '').trim(); if(n) storyBandStatus[n] = String(r.状态 || '').trim() || '未成立'; });\n    storySwitches = snap.开关 || null;\n    // 纪要表 → 剧情页「纪要」（26）\n    storyChronicle = Array.isArray(snap.纪要) ? snap.纪要 : null;   // null：这一局没有纪要表，剧情页不出这一块\n  }\n\n  // ===== 动态页的流水（DESIGN「动态页写上原因」）=====\n  // 游戏引擎装着时以引擎记上的为准：它按单楼上限夹（「好感 +80」只记 +50），表里的数也是它写的。\n  // 从最新一楼往回看 40 楼，每一次变化一条（同一楼好感、信任各一条），新的在上，最多 30 条；\n  // 剧情里过了三天的自动不要（只留今天、昨天、前天）。玩家删掉的（滑走、点 ×、清空）按键滤掉，键存在核心那边。\n  // 原因：接线把「最近变化」整句交给引擎（「好感 +20 · 一起修琴」），这里去掉数，剩「一起修琴」。\n  // 变化 0 的那笔是接线记的不带数的变化：原因以「初次见面」开头的是新认识的人，别的是一件事（「约好周六去乐器店」）。\n  // 时间：引擎记录里这一楼过完时的时间 now（「2020-04-08 周三 16:40 傍晚」，引擎 0.3.1 起有）；\n  // 更早的引擎没有 now，就看同一楼时间那一项的「现在」，那一楼时间没动沿用前一楼的。\n  var ACT_FLOORS = 40, ACT_MAX = 30, ACT_DAYS = 3;\n  var actNowDay = '';   // 引擎最新一楼过完时是哪天：表里当前时间写坏了（只写「傍晚」）时拿它当今天\n  var ACT_NUM = /(好感|信任)度?\\s*[:：]?\\s*[+\\-−＋－]?\\s*\\d+(?:\\.\\d+)?\\s*%?/g;\n  var ACT_EMPTY = /^(无|暂无|没有|没变|无变化|没有变化|不变|持平|维持|none|null|n\\/a|[—－\\-\\/／]+)$/i;   // 和接线认的空话一样\n  function actHash(s){ var h = 5381; s = String(s); for(var i = 0; i < s.length; i++) h = ((h << 5) + h + s.charCodeAt(i)) | 0; return (h >>> 0).toString(36); }\n  // 「好感 +20 · 一起修琴」→「一起修琴」；引擎把同一楼的几句用「；」连起来，一句一句收拾；新认识的人连「初次见面」也去掉（签上已经写了）\n  function actReason(text, firstMeet){\n    return String(text || '').split(/[；;]/).map(function(s){\n      s = s.replace(ACT_NUM, ' ');\n      if(firstMeet) s = s.replace(/初次见面/g, ' ');\n      return s.replace(/\\s+/g, ' ').replace(/(\\s*[·・]\\s*){2,}/g, ' · ')\n        .replace(/^[\\s·・,，、:：\\-—]+|[\\s·・,，、:：\\-—。]+$/g, '');\n    }).filter(Boolean).join('；');\n  }\n  // 「2020-04-08 周三 16:40 傍晚」→ { day: '2020-04-08', week: '周三', seg: '傍晚' }；没有时段就用钟点\n  function actTime(t){\n    var m = /^(\\d{4})-(\\d{1,2})-(\\d{1,2})\\s*(周.)?\\s*(\\d{1,2}:\\d{2})?\\s*(\\S+)?/.exec(String(t || '').trim());\n    if(!m) return null;\n    return { day: m[1] + '-' + ('0' + m[2]).slice(-2) + '-' + ('0' + m[3]).slice(-2), week: m[4] || '', seg: m[6] || m[5] || '' };\n  }\n  function actDayNum(d){ var x = /^(\\d{4})-(\\d{2})-(\\d{2})$/.exec(d || ''); return x ? Date.UTC(+x[1], +x[2] - 1, +x[3]) / 864e5 : NaN; }\n  // 好感跨了七档的分界：前后各落在哪一档（和接线写「关系阶段」同一套）；情侣、夫妻是剧情里定的，不跟好感走，不画\n  function actStage(name, now, delta, rows){\n    if(typeof core.stageOf !== 'function' || typeof now !== 'number' || !delta) return '';\n    var row = rows[name];\n    if(row && (row.关系阶段 === '情侣' || row.关系阶段 === '夫妻')) return '';\n    var a = core.stageOf(now - delta), b = core.stageOf(now);\n    return a && b && a !== b ? a + ' → ' + b : '';\n  }\n  // 删掉的滤掉；知道今天是哪天就只留三天内的（记时间以前那几楼的也不要了）；最多 30 条\n  function actFinish(list, today){\n    var hidden = {};\n    try { (typeof core.activityHidden === 'function' ? core.activityHidden() : []).forEach(function(k){ hidden[k] = 1; }); } catch(e){ /* 读不到就都显示 */ }\n    var t = actDayNum(today);\n    return list.filter(function(e){\n      if(hidden[e.key] || activityHiddenLocal[e.key]) return false;\n      if(isNaN(t)) return true;\n      var d = t - actDayNum(e.day);\n      return !(d >= ACT_DAYS) && !isNaN(d);   // 时间往回拨过（比今天晚）的照留\n    }).slice(0, ACT_MAX);\n  }\n\n  // 装着游戏引擎时从引擎的记录里取；没装回 null，照旧读「最近变化」\n  function engineActivity(rows, today){\n    var GE = null, last = null;\n    try { GE = window.parent && window.parent.__GE__; } catch(e){ return null; }\n    if(!GE || !GE.ready || typeof GE.getRecord !== 'function') return null;\n    try { last = GE.getRecord(); } catch(e){ return null; }\n    if(!last) return [];\n    // 从旧到新走一遍，记下每一楼过完时是几点；窗口前面多看 20 楼，只为接上时间\n    var from = last.floor - ACT_FLOORS + 1, recs = [], when = null;\n    for(var f = Math.max(0, from - 20); f <= last.floor; f++){\n      var r = null;\n      try { r = f === last.floor ? last : GE.getRecord(f); } catch(e){ /* 这一楼没有记录 */ }\n      if(!r) continue;\n      if(r.now !== undefined) when = actTime(r.now);\n      else (r.results || []).forEach(function(x){ if(x.项 === '时间' && x.现在){ var t = actTime(x.现在); if(t) when = t; } });\n      if(f >= from) recs.push({ r: r, t: when });\n    }\n    var out = [];\n    for(var i = recs.length - 1; i >= 0; i--){\n      var r2 = recs[i].r, t2 = recs[i].t || { day: '', week: '', seg: '' };\n      (r2.results || []).forEach(function(x){\n        if(x.项 !== '关系' || (x.状态 !== '成立' && x.状态 !== '夹取')) return;\n        var why = String(x.原因 || ''), e = { name: panelName(x.角色), floor: r2.floor, day: t2.day, week: t2.week, seg: t2.seg, stage: '' };\n        if(!x.变化){\n          if(!why.trim()) return;   // 变化 0 又没说为什么（夹到头的那种）：不画\n          var meet = /^\\s*初次见面/.test(why);\n          e.type = 'note'; e.note = meet ? '初次见面' : '记事'; e.reason = actReason(why, meet);\n        } else {\n          e.type = x.维度 === '好感' ? 'love' : 'trust'; e.delta = x.变化; e.reason = actReason(why, false);\n          if(x.维度 === '好感') e.stage = actStage(e.name, x.现值, x.变化, rows);\n        }\n        e.key = 'f' + r2.floor + ':' + actHash([x.角色, x.维度, x.变化, why].join('|'));\n        out.push(e);\n      });\n    }\n    // 一楼都不知道是几点（还没设时间）：不按天筛\n    var anyTime = recs.some(function(x){ return x.t; });\n    actNowDay = (when && when.day) || '';\n    return actFinish(out, anyTime ? (today || (when && when.day) || '') : '');\n  }\n\n  // 没装引擎：每人只有一句「最近变化」，没有时间，不分天\n  function tableActivity(snap){\n    var out = [];\n    (snap.角色 || []).forEach(function(p){\n      var text = String(p.最近变化 || '').trim();\n      if(p.其他 || !text) return;\n      var name = panelName(p.姓名), re = /(好感|信任)度?\\s*[:：]?\\s*([+\\-−＋－]?\\s*\\d+)/g, m, any = false;   // 「好感 +20」「好感度：+20」都认\n      while((m = re.exec(text))){\n        var n = Number(m[2].replace(/[\\s＋]/g, '').replace(/[−－]/g, '-'));\n        if(!n) continue;\n        any = true;\n        out.push({ key: 'b:' + actHash([p.姓名, m[1], text].join('|')), name: name, type: m[1] === '好感' ? 'love' : 'trust', delta: n,\n          reason: actReason(text, false), day: '', week: '', seg: '', stage: '' });\n      }\n      if(any || ACT_EMPTY.test(text.replace(/[\\s。.！!]/g, ''))) return;\n      var meet = /初次见面/.test(text);\n      out.push({ key: 'b:' + actHash([p.姓名, 'note', text].join('|')), name: name, type: 'note', note: meet ? '初次见面' : '记事',\n        reason: actReason(text, meet), day: '', week: '', seg: '', stage: '' });\n    });\n    return actFinish(out, '');\n  }\n\n  function applyChars(snap){\n    var rows = {};\n    (snap.角色 || []).forEach(function(p){ if(!p.其他) rows[panelName(p.姓名)] = p; });\n    chars.forEach(function(c){\n      var r = rows[c.name];\n      if(r){\n        c.love = clampNum(r.好感数);\n        c.trust = clampNum(r.信任数);\n        c.rel = STAGES.indexOf(r.关系阶段) >= 0 ? r.关系阶段 : (r.关系阶段 || '陌生人');\n        c.relation = r.与主角的关系 || '';\n        c.thought = r.心声 || '';\n        // 此刻、她家（23）：在不在主角身边、此刻所在、最近见面\n        c.known = true; c.away = !!r.离场; c.where = r.此刻所在 || ''; c.lastMet = r.最近见面 || '';\n      } else {\n        c.love = null; c.trust = null; c.rel = '陌生人'; c.relation = ''; c.thought = '';\n        c.known = false; c.away = true; c.where = ''; c.lastMet = '';\n      }\n    });\n    onSceneDemo = (snap.角色 || []).filter(function(p){ return !p.其他 && !p.离场; }).map(function(p){ return panelName(p.姓名); });\n    // 剧情里的今天：天标题写「今天」「昨天」、过了三天的自动不要都照它\n    var today = ymd(snap.当前时间);\n    actNowDay = '';\n    activityLog = engineActivity(rows, today) || tableActivity(snap);\n    activityToday = today || actNowDay;\n  }\n\n  // 日期、钟点补成两位再比：「2020-4-8」「9:30」直接拿字比，会排到「2020-04-18」「16:10」后面去\n  function ymd(t){ var m = /^(\\d{4})-(\\d{1,2})-(\\d{1,2})/.exec(String(t || '').trim()); return m ? m[1] + '-' + ('0' + m[2]).slice(-2) + '-' + ('0' + m[3]).slice(-2) : ''; }\n  function hhmm(t){ var m = /(\\d{1,2}):(\\d{2})/.exec(String(t || '')); return m ? ('0' + m[1]).slice(-2) + ':' + m[2] : ''; }\n  function nextPlan(snap){\n    // 时间格子不是「年-月-日」开头（填表 AI 只写了「傍晚」这种）就不按现在筛：拿字直接比，所有约定都会被当成过去了\n    var cur = String(snap.当前时间 || ''), day = ymd(cur);\n    var now = day ? day + ' ' + (hhmm(cur.replace(/^\\s*\\d{4}-\\d{1,2}-\\d{1,2}/, '')) || '00:00') : '';\n    var plans = (snap.日程 || []).filter(function(s){ return s.状态 === '约定'; }).map(function(s){\n      return { key: (ymd(s.日期) || String(s.日期 || '')) + ' ' + (hhmm(s.时刻) || '99:99'), s: s };\n    }).filter(function(x){ return !now || x.key >= now; }).sort(function(a, b){ return a.key < b.key ? -1 : 1; });\n    if(!plans.length) return { time: '', text: '' };\n    var s = plans[0].s, m = /^\\d{4}-(\\d{2})-(\\d{2})$/.exec(ymd(s.日期));\n    return {\n      time: (m ? Number(m[1]) + ' 月 ' + Number(m[2]) + ' 日' : (s.日期 || '')) + (s.时刻 && s.时刻 !== '未定' ? ' ' + s.时刻 : ''),\n      text: s.事项 + (s.地点 && s.地点 !== '未定' ? ' · ' + s.地点 : ''),\n    };\n  }\n\n  // 持有金钱：填表 AI 写什么样的都有——「11000」「12,000円」「约 3 万日元」「1.5万」「-500」。\n  // 认得出一个数（带万、千、负号）就写成「¥ 12,000」；认不出（「一万二千円」）原样给，不拿「——」盖掉\n  function moneyText(v){\n    var t = String(v == null ? '' : v).trim();\n    if(!t) return '';\n    var m = /([-−－]|负|欠)?\\s*(\\d[\\d,，]*(?:\\.\\d+)?)\\s*(万|千)?/.exec(t);\n    if(!m) return t;\n    var n = Number(m[2].replace(/[,，]/g, '')) * (m[3] === '万' ? 10000 : m[3] === '千' ? 1000 : 1);\n    if(!isFinite(n)) return t;\n    return (m[1] ? '−' : '') + '¥ ' + Math.round(n).toLocaleString('ja-JP');\n  }\n\n  function applyPlayer(snap){\n    var a = (snap.主角 && snap.主角.档案) || {}, x = (snap.主角 && snap.主角.现况) || {};\n    player.name = a.姓名 || '';\n    player.romaji = a.罗马音 || '';\n    player.tags = [];\n    var who = String(x.身份 || '').replace(/^(工作人员|打工|上班|音乐人|自由职业)\\s*·\\s*/, '');\n    if(who) player.tags.push(who);\n    if(x.所属乐队 && x.所属乐队 !== '无') player.tags.push(x.所属乐队);\n    var age = String(a.年龄 || '').trim().replace(/\\s*岁$/, '');   // ⚙ 档案里写成「17岁」也只带一个「岁」\n    if(age) player.tags.push(age + ' 岁');\n    player.money = moneyText(x.持有金钱);\n    player.conds = String(x.状况 || '').split(/\\s*[·、,，]\\s*/).filter(Boolean);\n    // 体力：主角现况表「体力」一格，0～100；旧局的表没有这一列（重新导入表格模板才有），读不到就空着\n    var hp = parseInt(String(x.体力 == null ? '' : x.体力).replace(/[^\\d-]/g, ''), 10);\n    player.hp = isNaN(hp) ? null : Math.max(0, Math.min(100, hp));\n    player.wear = x.穿着 || '';\n    player.next = nextPlan(snap);\n    // 没名字的行（填表 AI 留下的空行）不画：画出来只有一条空的档位条\n    function named(k){ return function(r){ return String(r[k] || '').trim(); }; }\n    player.skills = (snap.技能 || []).filter(named('技能')).map(function(s){\n      var now = Math.max(0, Math.min(5, parseInt(s.档位, 10) || 0));\n      var music = s.类别 === '乐器' || s.类别 === '歌唱';\n      return { name: s.技能, meta: s.类别 || '', tier: music && now ? SKILL_TIERS[now - 1] : '', now: now, note: s.进展 || '' };\n    });\n    function item(i){ var n = parseInt(i.数量, 10); return { name: i.物品 + (n > 1 ? ' ×' + n : ''), borrow: i.来源 === '借用' }; }\n    // 分组照旧只按「在哪」（随身 / 家里）；组里按类别排，同一类挨着：常备、器材在前，吃的、票在后\n    var ORDER = ['常备', '器材', '消耗品', '食物', '票券', '纪念品', '其他'];\n    function rank(i){ var k = ORDER.indexOf(i.类别); return k < 0 ? ORDER.length : k; }\n    var items = (snap.物品 || []).filter(named('物品')).map(function(i, n){ return { i: i, n: n }; })\n      .sort(function(a, b){ return rank(a.i) - rank(b.i) || a.n - b.n; }).map(function(x){ return x.i; });\n    player.items = {\n      carry: items.filter(function(i){ return i.位置 === '随身'; }).map(item),\n      home: items.filter(function(i){ return i.位置 !== '随身'; }).map(item),\n    };\n  }\n\n  function repaint(){\n    refreshChar();\n    if(drawerLevel === 1 && currentTeamIndex >= 0) renderMemberList(currentTeamIndex);\n    renderPresence();\n    renderActivity();\n    renderStoryDashboard();\n    if(currentStoryEventId) refreshStorySwitchRow(false);\n    refreshStoryDrawerBadges();\n    document.getElementById('th-info-time').textContent = globalStory.time;\n    document.getElementById('th-info-location').textContent = globalStory.location;\n    renderPlayerCard();\n    // 「你在这里」胶囊和导航的起点跟着新位置走（胶囊里顺带刷定位钮）；不刷的话要等切页签、改窗口大小才变\n    if(mapProj){ resolvePlayerLocation(); updateMapOriginChip(); renderMapNav(); renderMapNodes(); }\n  }\n\n  // 没装数据库（snapshot 回 null）：演示数据一律清掉换成占位，别拿假数冒充此刻\n  var EMPTY = { 年份: '', 时节: '', 当前时间: '', 场景类型: '现实', 地点: {}, 主角: {}, 角色: [], 技能: [], 物品: [], 日程: [] };\n\n  function apply(snap){\n    if(!snap){\n      snap = EMPTY;\n      globalStory.location = '——';\n    }\n    applyStory(snap);\n    applyStoryState(snap);\n    applyChars(snap);\n    applyPlayer(snap);\n    mapBasesApply(snap.据点);   // 家、工作、学校（21）；顺带作废导航卡问引擎的缓存，时间和钱跟着这一轮的表\n    mapBeenApply(snap.足迹);    // 足迹表 → 地图「去过」（27）：认地名要用上面刚换的家、工作、学校\n    repaint();\n  }\n\n  var pending = 0;\n  function later(snap){\n    if(pending) panelClearDelay(pending);\n    pending = panelDelay(function(){ pending = 0; apply(snap || core.snapshot()); }, 300);\n  }\n\n  apply(core.snapshot());\n  eventOn('BanGCtl:data', panelGuard(function(d){ later(d && d.快照); }));\n  eventOn('BanGCtl:state', panelGuard(function(){ later(null); }));\n})();\n\n// ===== 设置（面板 ⚙）：照 开局卡设计稿/设置.html。只在卡里（接了总控核心）才有，独立预览版没有 =====\n// 最上面一行运行状态；本局（表格是旧版时的升级、档案、新的一局、备份、恢复）；关于（开局须知、版本、自动更新）；高级（帮填接口、表格模板，默认收起）。\n// 真要清数据的只有「重新导入」，收在高级里、点了还要确认；「新的一局」不清东西，但会把人带去别的聊天，也先确认。\n// 读写全走核心：state / snapshot / locks / lock / unlock / editRow / backup / newRun / reimport / upgrade / restore / setApi / testApi /\n// checkUpdate / applyUpdate / rollbackUpdate / setSetting。版本展开是自动更新的现状（核心 更新.js），更新、退回旧版都先确认。\n// 升级、恢复会把整局表格重写一遍，都先确认；恢复的来源是备份文件，或升级前核心在这台浏览器里自动留的那份。\n// 帮填接口是卡自己的（核心 接口.js），只存在这台浏览器：密钥不回显，存过就只写「已存」。\n(function(){\n  var core = window.BanGCtl || (window.parent && window.parent.BanGCtl);\n  if(window.面板内嵌静态 || !core || typeof core.state !== 'function') return;\n  var bar = document.querySelector('.th-tab-bar'), wrap = document.querySelector('.th-wrapper');\n  if(!bar || !wrap) return;\n\n  var PATHS = {\n    gear: '<circle cx=\"12\" cy=\"12\" r=\"3\"/><path d=\"M19.4 15a1.65 1.65 0 0 0 .33 1.82l.06.06a2 2 0 1 1-2.83 2.83l-.06-.06a1.65 1.65 0 0 0-1.82-.33 1.65 1.65 0 0 0-1 1.51V21a2 2 0 1 1-4 0v-.09A1.65 1.65 0 0 0 9 19.4a1.65 1.65 0 0 0-1.82.33l-.06.06a2 2 0 1 1-2.83-2.83l.06-.06A1.65 1.65 0 0 0 4.68 15a1.65 1.65 0 0 0-1.51-1H3a2 2 0 1 1 0-4h.09A1.65 1.65 0 0 0 4.6 9a1.65 1.65 0 0 0-.33-1.82l-.06-.06a2 2 0 1 1 2.83-2.83l.06.06A1.65 1.65 0 0 0 9 4.68a1.65 1.65 0 0 0 1-1.51V3a2 2 0 1 1 4 0v.09a1.65 1.65 0 0 0 1 1.51 1.65 1.65 0 0 0 1.82-.33l.06-.06a2 2 0 1 1 2.83 2.83l-.06.06A1.65 1.65 0 0 0 19.4 9a1.65 1.65 0 0 0 1.51 1H21a2 2 0 1 1 0 4h-.09a1.65 1.65 0 0 0-1.51 1z\"/>',\n    x: '<path d=\"M18 6 6 18M6 6l12 12\"/>',\n    right: '<path d=\"m9 6 6 6-6 6\"/>', down: '<path d=\"m6 9 6 6 6-6\"/>', up: '<path d=\"m6 15 6-6 6 6\"/>', left: '<path d=\"m15 6-6 6 6 6\"/>',\n    person: '<circle cx=\"12\" cy=\"8\" r=\"4\"/><path d=\"M4 21a8 8 0 0 1 16 0\"/>',\n    plus: '<path d=\"M12 5v14M5 12h14\"/>',\n    download: '<path d=\"M12 4v11M7 10l5 5 5-5M5 20h14\"/>',\n    info: '<circle cx=\"12\" cy=\"12\" r=\"9\"/><path d=\"M12 11v6M12 7.5v.5\"/>',\n    tag: '<path d=\"M3 12V4h8l10 10-8 8z\"/><circle cx=\"7.5\" cy=\"8.5\" r=\"1.3\"/>',\n    sliders: '<path d=\"M4 7h10M18 7h2M4 17h4M12 17h8\"/><circle cx=\"16\" cy=\"7\" r=\"2\"/><circle cx=\"10\" cy=\"17\" r=\"2\"/>',\n    sparkle: '<path d=\"M12 3l1.8 5.2L19 10l-5.2 1.8L12 17l-1.8-5.2L5 10l5.2-1.8z\"/>',\n    