Level(storyDrawerLevel - 1); else closeStoryDrawer();\n  });\n  function syncStoryHead(){\n    var labels = [null, storyDrawerYearLabelEl, storyDrawerSeasonLabelEl, storyDrawerGroupLabelEl];\n    var t = storyDrawerLevel > 0 && labels[storyDrawerLevel] ? labels[storyDrawerLevel].textContent : '';\n    setHead(storyHead, t || '剧情档案', storyDrawerLevel > 0 ? '' : 'ARCHIVE');\n  }\n  var goStoryOrig = goToStoryDrawerLevel;\n  goToStoryDrawerLevel = function(level){\n    goStoryOrig(level);\n    syncStoryHead();\n    panelDelay(syncStoryHead, 0);   // 有的入口先换层、后写这一层的标题\n  };\n  // 手机上在档案里点开一段剧情：收起档案，详情在剧情页里看\n  var showStoryEventOrig = showStoryEvent;\n  showStoryEvent = function(id){ if(thIsMobile()) closeStoryDrawer(); showStoryEventOrig(id); };\n  // 剧情页里时间线 ⇄ 详情换过去以后，窗从顶上看起（换的那一下在 220ms 处）\n  var swapStoryViewOrig = swapStoryView;\n  swapStoryView = function(fromEl, toEl, renderFn){\n    swapStoryViewOrig(fromEl, toEl, renderFn);\n    if(thIsMobile()) panelDelay(function(){ thContent.scrollTop = 0; }, 230);\n  };\n\n  // —— 手机上点页签先把开着的下一页收掉（点的就是当前页也收）；点 ⚙ 先收两个抽屉 ——\n  function closePushed(keepSettings){\n    if(drawer.classList.contains('open')) closeDrawer();\n    if(storyDrawer.classList.contains('open')) closeStoryDrawer();\n    if(!keepSettings && thSetClose) thSetClose();\n  }\n  panelOn(tabBar, 'click', function(e){ if(thIsMobile() && e.target.closest('.th-tab-btn')) closePushed(); }, true);\n  panelOn(document, 'click', function(e){ if(thIsMobile() && e.target.closest('.th-gear')) closePushed(true); }, true);\n\n  // —— 角色页顶上一排头像：在场的人（绿点），认识的人，末尾「选人」——\n  var avBox = document.createElement('div');\n  avBox.className = 'th-m-avs';\n  avBox.innerHTML = '<div class=\"th-m-sec\">在场 · 认识的人<\/div><div class=\"th-m-avrow\"><\/div>';\n  pageAff.insertBefore(avBox, pageAff.firstChild);\n  var avRow = avBox.querySelector('.th-m-avrow');\n  var AV_MAX = 12, avSig = '';\n  function avName(n){ return String(n).replace(/（.*?）|\\(.*?\\)/g, '').trim(); }\n  function avList(){\