 '\" data-tb-col=\"' + esc(key) + '\" value=\"' + esc(val) + '\" maxlength=\"500\"'\n        + (c.数字 ? ' inputmode=\"decimal\"' : '') + '>';\n    }\n    return '<div class=\"th-tb-fld' + (c.长 ? ' full' : '') + '\"><label for=\"' + id + '\"><span>' + esc(key) + '<\/span>' + tag + '<\/label>' + input + '<\/div>';\n  }\n  function footHtml(row, isNew){\n    var b = busy(), can = !view.只读;\n    if(!can) return '';\n    return (tbState.err ? '<div class=\"th-tb-err\">' + esc(tbState.err) + '<\/div>' : '')\n      + (tbState.tip ? '<div class=\"th-tb-tip\">' + esc(tbState.tip) + '<\/div>' : '')\n      + '<div class=\"th-tb-foot\">'\n      + (row && !isNew && view.能删 ? '<button type=\"button\" class=\"th-tb-del\" data-tb-act=\"del\">删掉这一行<\/button>' : '')\n      + '<small>' + (b.忙 ? esc(b.原因) : isNew ? view.主列 + '要填' : '改过的格子自动锁住') + '<\/small>'\n      + '<button type=\"button\" class=\"th-tb-btn ghost\" data-tb-act=\"cancel\">取消<\/button>'\n      + '<button type=\"button\" class=\"th-tb-btn solid\" data-tb-act=\"save\"' + (b.忙 ? ' disabled' : '') + '>保存<\/button><\/div>';\n  }\n  function formHtml(row, isNew){\n    var cols = (view.列 || []).filter(function(c){ return !isNew || !(c.只读 || view.只读); });\n    return '<div class=\"th-tb-form\">' + cols.map(function(c){ return fieldHtml(row, c, isNew); }).join('') + '<\/div>' + footHtml(row, isNew);\n  }\n  function cardHtml(row){\n    var open = tbState.open === row._行;\n    var main = String(row.值[view.主列] || '').trim() || '（空）';\n    var pre = view.前缀 ? String(row.值[view.前缀] || '').trim() : '';\n    var peek = view.露.map(function(c){ return String(row.值[c] || '').trim(); }).filter(Boolean).join(' · ');\n    var nLock = Object.keys(row.锁).filter(function(k){ var c = colOf(k); return row.锁[k] && c && !c.只读; }).length;\n    return '<div class=\"th-tb-card' + (open ? ' open' : '') + '\" data-tb-row=\"' + row._行 + '\">'\n      + '<div class=\"th-tb-top\" data-tb-act=\"toggle\"><b>' + (pre ? '<i class=\"th-tb-pre\">' + esc(pre) + '