\n    } else if(kindNow){\n      // 淡出 .2s 再藏起来\n      tag.classList.add('is-out');\n      panelClearDelay(outTimer);\n      outTimer = panelDelay(function(){ tag.hidden = true; tag.classList.remove('is-out'); }, 200);\n    }\n    kindNow = kind;\n  }\n\n  var s = null;\n  try { s = core.snapshot(); } catch(e){ s = null; }\n  if(s){ filling = !!s.填表中; unsaved = s.已存 === false; if(filling) fillAt = Date.now(); }\n  eventOn('BanGCtl:filling', panelGuard(function(){\n    filling = true; fillAt = Date.now(); paint();\n    panelClearDelay(expTimer);\n    expTimer = panelDelay(paint, FILL_MAX + 500);\n  }));\n  eventOn('BanGCtl:data', panelGuard(function(d){\n    filling = false;\n    unsaved = !!(d && d.已存 === false);\n    paint();\n  }));\n  panelOn(window, 'resize', function(){ place(); tag.__html = ''; paint(); });\n  place();\n  paint();\n})();\n\n// ===== 温度计（DESIGN「温度计」）：角色卡的好感、信任，主角页的体力 =====\n// 左边圆泡，右边一根管，液柱从泡里长出来。好感、信任是千分制 -1000～1000，管子正中是 0；体力 0～100。\n// 好感在七档关系的分界上画刻度：同 共用/数据.js 的阶段界、手账本的七档——0 陌生人、350 普通朋友、550 在意的人、750 挚友，\n// 低于 0 是讨厌的人；情侣、夫妻照手账本的规矩由事件定下（契约事件），不看好感，不上刻度。低于 0 液柱换冷色。\n// 分界写在函数里：06 在面板一打开就画角色卡、叫到这里，那时这个文件下面的赋值还没跑到\nfunction thermoTiers(){ return [[0, '陌生人'], [350, '普通朋友'], [550, '在意的人'], [750, '挚友']]; }\nfunction thermoSet(th, v, kind){\n  if(!th) return;\n  var has = typeof v === 'number' && isFinite(v);\n  var ratio = !has ? 0 : kind === 'hp' ? Math.max(0, Math.min(100, v)) / 100 : (Math.max(-1000, Math.min(1000, v)) + 1000) / 2000;\n  var fill = th.querySelector('.th-thermo-fill');\n  if(fill) fill.style.transform = 'scaleX(' + ratio.toFixed(4) + ')';\n  th.classList.toggle('is-empty', !has);\n  th.classList.toggle('is-cold', has && kind !== 'hp' && v < 0);\n}\n// 好感下面那一行：离下一档还差多少；已到挚友不写；情侣、夫妻写由事件定下\nfunction thermoGapHtml(v, stage){\n  if(stage === '情侣' || stage === '夫妻') return '<b>' + escapeMapText(stage) + '<\/b> · 由事件定下，不看好感';\n  if(typeof v !== 'number' || !isFinite(v)) return '';\n  var tiers = thermoTiers(), next = null;\n  for(var i = 0; i < tiers.length; i++){ if(v < tiers[i][0]){ next = tiers[i]; break; } }\n  return next ? '离<b>' + next[1] + '<\/b>还差 ' + thPct(next[0] - v) : '';\n}\n// 刻度：好感 0 和三档分界，信任只有 0\n(function(){\n  function ticks(th, at){\n    var tube = th && th.querySelector('.th-thermo-tube');\n    if(!tube || tube.querySelector('.th-thermo-tick')) return;\n    at.forEach(function(v){\n      var i = document.createElement('i');\n      i.className = 'th-thermo-tick' + (v === 0 ? ' zero' : '');\n      i.style.setProperty('--at', ((v + 1000) / 20) + '%');\n      tube.appendChild(i);\n    });\n  }\n  ticks(loveTh, thermoTiers().map(function(x){ return x[0]; }));\n  ticks(trustTh, [0]);\n})();\n\n// 手账本里她对主角的好感底色、信任落点：好感下面一行「底色」，信任下面一行「落点」。核心 handbookRelation 现读，\n// 没装手账本、这个聊天还没记到她就不出。手账本记完不发事件：角色页开着、选了人时每 10 秒现读一次，变了才重画\nvar thermoHbSig = '';\nfunction thermoHbRead(c){\n  try {\n    var core = window.BanGCtl || (window.parent && window.parent.BanGCtl);\n    return c && core && typeof core.handbookRelation === 'function' ? core.handbookRelation(c.name) : null;\n  } catch(e){ return null; }\n}\nfunction thermoHbPaint(c){\n  var r = thermoHbRead(c), tone = r && r.底色 ? String(r.底色) : '', trust = r && r.落点 ? String(r.落点) : '';\n  if(loveHb) loveHb.innerHTML = tone ? '<em>底色<\/em>' + escapeMapText(tone) : '';\n  if(trustHb) trustHb.innerHTML = trust ? '<em>落点<\/em>' + escapeMapText(trust) : '';\n  thermoHbSig = (c ? c.name : '') + '|' + tone + '|' + trust;\n}\n(function(){\n  function tick(){\n    panelDelay(tick, 10000);\n    if(typeof currentTab === 'undefined' || currentTab !== 'affection' || cur === -1 || document.hidden) return;\n    var c = chars[cur], r = thermoHbRead(c);\n    if((c ? c.name : '') + '|' + ((r && r.底色) || '') + '|' + ((r && r.落点) || '') !== thermoHbSig) thermoHbPaint(c);\n  }\n  panelDelay(tick, 10000);\n})();\n\n<\/script>\n<script>\n// 面板的引导：先拿到静态数据（地图、路网、剧情档……），再跑面板代码。\n//   卡里：数据在总控核心里（staticData().面板），等核心起来；\n//   独立预览版：构建时把数据内嵌在 window.面板内嵌静态，不用核心（冒烟测试、跑分用它）。\n// 面板代码放在 <script type=\"text/plain\"> 里，拿到数据以后原样塞进一个新的 <script> 跑：\n// 这样它还是在全局作用域里跑，和拆出来之前一模一样（测试工具直接读 mapProj 这些全局变量）。\n(function () {\n  var 已跑 = false;\n  var 我楼 = -1;\n\n  function 跑(静态) {\n    if (已跑) return;\n    已跑 = true;\n    window.面板静态 = 静态;\n    var s = document.createElement('script');\n    s.textContent = document.getElementById('面板代码').textContent;\n    document.body.appendChild(s);\n  }\n  function 核心() {\n    var 核 = window.BanGCtl || (window.parent && window.parent.BanGCtl);\n    return 核 && typeof 核.alive === 'function' && 核.alive() ? 核 : null;\n  }\n  var 条样式 = 'margin:6px 0 10px;padding:9px 14px;border-radius:14px;background:#fff;color:#8b849c;font:700 12.5px/1.6 \"Noto Sans SC\",sans-serif;box-shadow:0 2px 8px rgba(70,50,90,.08)';\n  function 条(字) {\n    var el = document.getElementById('面板提示') || document.body.insertBefore(document.createElement('div'), document.body.firstChild);\n    el.id = '面板提示';\n    el.style.cssText = 条样式;\n    el.textContent = 字;\n  }\n  // 旧楼层的面板：最新一楼有了新面板，这一个收成一行。\n  // 酒馆助手画的那一整块（.TH-render：iframe 加一份藏起来的面板源码 <pre>，四十多万字）换成外层页面里的一行字，\n  // 不只是清空内容：只清 DOM 的话这一楼的面板代码、数据和那份源码都还在内存里（测试酒馆实测每楼约 3.6 MB，一百楼三百多 MB）。\n  // iframe 拿掉时酒馆助手在 pagehide 里把这一楼注册的 eventOn 全摘了，这一整套就能回收。\n  // 放到下一轮事件循环再换：收起是在 BanGCtl:latest 的派发里调的，当场拆框会动到正在派发的监听表\n  var 已收 = false;\n  function 收起(新楼) {\n    if (已收) return;\n    已收 = true;\n    if (typeof window.thDestroyPanel === 'function') { try { window.thDestroyPanel(); } catch (e) { /* 已经放过了 */ } }\n    document.body.innerHTML = '';\n    条('面板在最新一楼（' + 新楼 + ' 楼）');\n    setTimeout(function () {\n      try {\n        var 框 = window.frameElement;\n        if (!框 || !框.parentNode) return;\n        var 行 = 框.ownerDocument.createElement('div');\n        行.className = 'bang-panel-moved';\n        行.style.cssText = 条样式;\n        行.textContent = '面板在最新一楼（' + 新楼 + ' 楼）';\n        (框.closest('.TH-render') || 框).replaceWith(行);\n      } catch (e) { /* 拿不到外层就留着这一行 */ }\n    }, 0);\n  }\n  function 试() {\n    if (已跑) return true;\n    var 核 = 核心();\n    var 静 = 核 && 核.staticData && 核.staticData().面板;\n    if (!静) return false;\n    var 旧条 = document.getElementById('面板提示');\n    if (旧条) 旧条.remove();\n    跑(静);\n    try {\n      我楼 = getCurrentMessageId();\n      eventOn('BanGCtl:latest', function (d) { if (d && d.楼 > 我楼) 收起(d.楼); });\n      var 最新 = 核.hello(我楼);\n      if (最新 > 我楼) 收起(最新);\n    } catch (e) { /* 不在楼层里（预览页）就不报到 */ }\n    return true;\n  }\n\n  if (window.面板内嵌静态) return 跑(window.面板内嵌静态);\n  document.documentElement.classList.add('th-in-chat');\n  if (试()) return;\n  try { eventOn('global_BanGCtl_initialized', 试); } catch (e) { /* 不在酒馆助手里 */ }\n  try { waitGlobalInitialized('BanGCtl').then(试); } catch (e) { /* 同上 */ }\n  setTimeout(function () { if (!试()) 条('面板要总控核心给数据 · 缺：角色脚本「BanG 总控」（酒馆助手 → 脚本库 → 角色脚本）'); }, 5000);\n})();\n\n<\/script>\n\n<\/body>\n<\/html>\n"};

// ── 核心/事件.js ──
// 核心对外的事件。两块屏（0 层卡、面板）只靠这些事件和 BanGCtl 接口跟核心说话，互相不直接碰。
const 事件 = {
  状态: 'BanGCtl:state',      // 状态变了，带 state()
  数据: 'BanGCtl:data',       // 表更新了，带 snapshot() 和这次改动存没存进聊天
  填表: 'BanGCtl:filling',    // 数据库开始填表
  进度: 'BanGCtl:progress',   // 开局做到第几步
  最新: 'BanGCtl:latest',     // 最新面板换楼了，旧的收起
  出错: 'BanGCtl:error',      // 出错，带一句给人看的话
};

function 发(名, 数据) {
  try { eventEmit(名, 数据); } catch (e) { console.warn('[BanG 总控] 事件没发出去', 名, e); }
}
function 报错(话, 细节) {
  console.warn('[BanG 总控]', 话, 细节 || '');
  发(事件.出错, { 话 });
}

// ── 核心/存取.js ──
// 存取：聊天变量 BanGCtl（这一局：开局记录、须知已读、建档草稿、模板导没导），脚本变量（这张卡的设置）。
const 局键 = 'BanGCtl';

function 读局() {
  try { return 深拷((getVariables({ type: 'chat' }) || {})[局键] || {}); } catch (e) { return {}; }
}
function 写局(改) {
  updateVariablesWith(vars => {
    vars[局键] = Object.assign({}, vars[局键] || {}, 改);
    return vars;
  }, { type: 'chat' });
}

// 主角立绘（面板主角页上传的那张）：单放一个聊天变量，跟着这个聊天走，每一楼的面板都读回来。
// 图有一两百 KB，不放进上面那一包，免得每次读局都跟着深拷
const 立绘键 = 'BanGCtl·主角立绘';
const 立绘上限 = 1000000;   // 字符数；面板交过来之前已经缩到 600×800 以内
function 读立绘() {
  try { const v = (getVariables({ type: 'chat' }) || {})[立绘键]; return typeof v === 'string' ? v : ''; } catch (e) { return ''; }
}
function 存立绘(图) {
  const s = String(图 || '');
  if (s && !/^data:image\/(png|jpeg|webp|gif);base64,/.test(s)) return { ok: false, 原因: '不是图片' };
  if (s.length > 立绘上限) return { ok: false, 原因: '图片太大' };
  insertOrAssignVariables({ [立绘键]: s }, { type: 'chat' });
  return { ok: true };
}

// 动态页删掉的那几条（手机上滑走、电脑上点 ×、清空）：存每一条的键，跟着这个聊天走，每一楼的面板都读回来。
// 只留最近 400 个键；面板只往回看 40 楼，更早的键用不上了
const 动态删键 = 'BanGCtl·动态删掉';
function 读动态删掉() {
  try { const v = (getVariables({ type: 'chat' }) || {})[动态删键]; return Array.isArray(v) ? v.filter(k => typeof k === 'string') : []; } catch (e) { return []; }
}
function 删动态(键们) {
  const 新 = (Array.isArray(键们) ? 键们 : [键们]).map(k => String(k || '')).filter(Boolean);
  if (!新.length) return 读动态删掉();
  const 留 = 读动态删掉().filter(k => !新.includes(k)).concat(新).slice(-400);
  insertOrAssignVariables({ [动态删键]: 留 }, { type: 'chat' });
  return 留;
}

// 帮填接口不在这里：它带密钥，脚本变量会跟着卡导出，接口存在浏览器里（接口.js）
const 默认设置 = { 自动更新: true };   // 自动更新：关了只提醒（更新.js）
function 读设置() {
  try { return Object.assign({}, 默认设置, getVariables({ type: 'script' }) || {}); } catch (e) { return Object.assign({}, 默认设置); }
}
function 写设置(键, 值) {
  if (!(键 in 默认设置)) throw new Error('没有这项设置：' + 键);
  insertOrAssignVariables({ [键]: 值 }, { type: 'script' });
}

function 酒馆() {
  try { return window.parent.SillyTavern.getContext(); } catch (e) { return null; }
}
function 当前聊天() {
  const c = 酒馆();
  try { return c ? String(c.getCurrentChatId() || '') : ''; } catch (e) { return ''; }
}
function 当前卡() {
  const c = 酒馆();
  return c && c.characters ? c.characters[c.characterId] || null : null;
}

// ── 核心/数据库.js ──
// 龙血玄黄·数据库（1.2.4 起，前置.js 查版本）的读写。接口挂在酒馆主窗口 AutoCardUpdaterAPI 上，每次现取、不缓存函数引用
// （数据库切聊天、重载时会换掉运行时，缓存下来的引用会指向旧的）。
