 TEXT, -- 年龄\n  build TEXT, -- 身高体型\n  hair TEXT, -- 发型发色\n  eyes TEXT, -- 瞳色\n  usual_clothes TEXT, -- 常穿服装\n  features TEXT, -- 外貌特征\n  residence TEXT, -- 住所\n  origin TEXT, -- 出身\n  family TEXT, -- 家庭\n  upbringing TEXT, -- 成长经历\n  backstory TEXT, -- 来历\n  witness TEXT, -- 知情人\n  mainline_tie TEXT, -- 与主线关系\n  core_personality TEXT, -- 核心性格\n  social_style TEXT, -- 社交方式\n  speech_habit TEXT, -- 说话习惯\n  daily_habit TEXT, -- 日常习惯\n  likes TEXT, -- 喜欢\n  dislikes TEXT, -- 讨厌\n  weakness TEXT, -- 弱点软肋\n  contrast TEXT, -- 反差\n  physical_trait TEXT, -- 生理特点\n  mental_state TEXT -- 心理状态\n);"}, "content": [["row_id", "姓名", "罗马音", "称呼", "性别", "年龄", "身高体型", "发型发色", "瞳色", "常穿服装", "外貌特征", "住所", "出身", "家庭", "成长经历", "来历", "知情人", "与主线关系", "核心性格", "社交方式", "说话习惯", "日常习惯", "喜欢", "讨厌", "弱点软肋", "反差", "生理特点", "心理状态"]], "updateConfig": {"uiSentinel": -1, "contextDepth": -1, "updateFrequency": -1, "batchSize": -1, "skipFloors": -1, "groupId": -1}, "exportConfig": {"enabled": true, "splitByRow": false, "entryName": "主角档案表", "entryType": "constant", "keywords": "", "preventRecursion": true, "injectionTemplate": "<主角设定>\n$1\n</主角设定>", "extraIndexEnabled": false, "extraIndexEntryName": "主角档案表-索引", "extraIndexColumns": [], "extraIndexColumnModes": {}, "extraIndexInjectionTemplate": "", "sqlInjectionTemplate": "", "entryPlacement": {"position": "at_depth_as_system", "depth": 2, "order": 10000}, "extraIndexPlacement": {"position": "at_depth_as_system", "depth": 2, "order": 10010}, "fixedEntryPlacement": {"position": "at_depth_as_system", "depth": 2, "order": 99990}, "fixedIndexPlacement": {"position": "at_depth_as_system", "depth": 2, "order": 99991}}}, "sheet_EmU0wzme": {"uid": "sheet_EmU0wzme", "name": "主角现况表", "orderNo": 2, "sourceData": {"note": "主角此刻会变的那部分：身份、所属乐队、穿着、钱、状况、体力。本表只有一行。（列号为 0 基，与表格数据中的列标一致）\n- 列0: 身份 - 主角此刻的身份。工作人员写「工作人员 · 工作地点 · 职位」，学生写「学校 · 年级」。开局默认「工作人员 · CiRCLE · 新手工作人员」。身份变了才改。\n- 列1: 所属乐队 - 主角所在乐队的名字，和乐队表里的乐队名一字不差；没加入乐队写「无」。\n- 列2: 穿着 - 主角此刻的穿着，不超过 20 字。换了衣服就更新。\n- 列3: 持有金钱 - 由游戏引擎记账写入并锁住，不用填。\n- 列4: 状况 - 伤病、心情、累不累，用短词，不超过 20 字，例如「有点累 · 手指磨破」。\n- 列5: 体力 - 主角此刻的体力，0 到 100，满是 100。由游戏引擎记账写入并锁住，不用填：睡着按睡了多久往回加，醒着慢慢往下掉，都由引擎按时间算；别的变化写进本表「体力变化」。\n- 列6: 体力变化 - 这一轮体力除了睡觉、醒着以外的变化和原因，格式「体力 -15 · 排练三小时」，一次一般 ±5～±30，最多 ±50。熬夜、长时间排练或打工、跑远路、淋雨生病往下扣；吃饭、午睡、泡澡、歇一会儿往回加。晚上睡一觉、白天醒着的消耗由引擎按时间算，不写进这里。没有这类变化就不改。\n\n- 本表只写主角。本表只记正文里写到、看得见的事实，不写心理活动、动机推测和性格评价。", "initNode": "开局时由开局卡写入这一行，填表时不再新建。", "deleteNode": "本表不删除行。", "updateNode": "主角的身份、乐队、穿着、状况在正文里变了时，更新对应的格子；体力有睡觉、醒着以外的变化时写「体力变化」。\nSQL示例: UPDATE protagonist_status SET identity = '示例身份' WHERE row_id = 0;", "insertNode": "禁止。本表固定一行，由开局卡写入，填表时不插入新行。", "ddl": "CREATE TABLE protagonist_status ( -- 主角现况表\n  row_id INTEGER PRIMARY KEY, -- 行号\n  identity TEXT, -- 身份\n  band TEXT, -- 所属乐队\n  outfit TEXT, -- 穿着\n  money TEXT, -- 持有金钱\n  condition TEXT, -- 状况\n  stamina TEXT, -- 体力\n  stamina_change TEXT -- 体力变化\n);"}, "content": [["row_id", "身份", "所属乐队", "穿着", "持有金钱", "状况", "体力", "体力变化"]], "updateConfig": {"uiSentinel": -1, "contextDepth": -1, "updateFrequency": -1, "batchSize": -1, "skipFloors": -1, "groupId": -1}, "exportConfig": {"enabled": false, "splitByRow": false, "entryName": "主角现况表", "entryType": "constant", "keywords": "", "preventRecursion": true, "injectionTemplate": "", "extraIndexEnabled": false, "extraIndexEntryName": "主角现况表-索引", "extraIndexColumns": [], "extraIndexColumnModes": {}, "extraIndexInjectionTemplate": "", "sqlInjectionTemplate": "", "entryPlacement": {"position": "at_depth_as_system", "depth": 2, "order": 10000}, "extraIndexPlacement": {"position": "at_depth_as_system", "depth": 2, "order": 10010}, "fixedEntryPlacement": {"position": "at_depth_as_system", "depth": 2, "order": 99990}, "fixedIndexPlacement": {"position": "at_depth_as_system", "depth": 2, "order": 99991}}}, "sheet_xSspmIQX": {"uid": "sheet_xSspmIQX", "name": "重要角色表", "orderNo": 3, "sourceData": {"note": "记录和主角有来往的原作角色：两人是什么关系、关系到了哪一步、好感和信任、最近的变化、共同经历。（列号为 0 基，与表格数据中的列标一致）\n- 列0: 姓名 - 只能写名单里的规范名，一字不差；名单外的人（路人、店员、家人）不入本表，玩家扮演的主角也不入本表。若叶睦的另一个人格墨缇丝出面时，单独记一行，姓名写「墨缇丝」，好感、信任、心声都跟若叶睦那一行分开。名单：户山香澄、花园多惠、牛込里美、山吹沙绫、市谷有咲、美竹兰、青叶摩卡、上原绯玛丽、宇田川巴、羽泽鸫、丸山彩、冰川日菜、白鹭千圣、大和麻弥、若宫伊芙、凑友希那、冰川纱夜、今井莉莎、宇田川亚子、白金燐子、弦卷心、濑田薰、北泽育美、松原花音、奥泽美咲、仓田真白、桐谷透子、广町七深、二叶筑紫、八潮瑠唯、和奏瑞依、朝日六花、佐藤益木、鳰原令王那、珠手知由、高松灯、千早爱音、要乐奈、长崎爽世、椎名立希、三角初华、祐天寺若麦、八幡海铃、若叶睦、丰川祥子、仲町阿拉蕾、宫永野乃花、藤都子、千石由乃、峰月律、薇欧拉、墨缇丝。\n- 列1: 与主角的关系 - 两人是什么关系，一句话，不超过 20 字，例如「CiRCLE 的常客，常来借练习室」。\n- 列2: 关系阶段 - 七档之一：讨厌的人 / 陌生人 / 普通朋友 / 在意的人 / 挚友 / 情侣 / 夫妻。前五档由游戏引擎按好感度写，不用填；只有两人在正文里确定成了恋人、结了婚，才写「情侣」「夫妻」（好感度不到 550 写了不算）。\n- 列3: 好感度 - 千分制，-1000～1000，负的是讨厌。由游戏引擎记账写入并锁住，不用填。变化写进本表「最近变化」。\n- 列4: 信任度 - 千分制，-1000～1000，负的是不信任。由游戏引擎记账写入并锁住，不用填。变化写进本表「最近变化」。\n- 列5: 心声 - 她此刻心里的一句话，用她自己的口吻，不超过 30 字。\n- 列6: 最近变化 - 这一轮好感、信任、关系阶段的变化和原因，格式「好感 +20 · 一起修琴」（千分制，一次一般 ±5～±30，最多 ±50），不超过 20 字；没有变化就不改。\n- 列7: 最近见面 - 最近一次和主角见面的日期和地点，格式「YYYY-MM-DD · 地点」。\n- 列8: 是否离场 - 只填「是」或「否」：她此刻不在主角身边填「是」，在场填「否」。\n- 列9: 此刻所在 - 她不在主角身边时，她此刻在哪、在做什么，格式「YYYY-MM-DD HH:MM · 地点 · 在做什么」，例如「2020-04-28 16:30 · CiRCLE · 乐队练习」；时间写正文交代她在那里的那一刻。正文写到或提到她在哪时改：她和主角分开时写她去了哪，打电话、发消息里说了，别人提起。她在主角身边时不用改。地点只用正文里出现过的名字；正文没交代就不改，不要猜。\n- 列10: 共同经历 - 她和主角一起经历过的关键的事，按时间顺序，不超过 3 句，只写事实。有新的就追加，超过 3 句时把最早的压缩掉。\n\n- 本表不写人物的性格和类型标签（温柔、傲娇、高冷……）。\n- 同一个人只占一行，不用昵称或艺名另开一行。\n\n【手账本·拼表开始】\n【分工】人物的心理、情绪、动机由「常夜灯的手账本」插件单独记录，本表不记录。\n本表只记正文里明确写到、可以核对的事实：人物做了什么、说了什么、去了哪里、什么东西变了。\n不写心理活动和动机推测（「她心里」「她其实」「她想要」「她害怕」这类句子删掉）。\n不写性格评价和类型标签（温柔、傲娇、腹黑、高冷……）。\n正文没写到的不补、不推测。\n本表的列说明里专门要求写人物认知、关系、心理、性格的那几列，照那几列自己的说明写；上面几条只管其余的列。\n【手账本·拼表结束】", "initNode": "开局时由开局卡写入主角认识的人；填表时不重复插入表里已有的人。", "deleteNode": "禁止。人物离开故事时把「是否离场」改成「是」，不删除。", "updateNode": "她和主角的关系、好感、信任、心声、见面、在不在场、此刻所在、共同经历变了时，更新对应的格子。\nSQL示例: UPDATE important_characters SET relation = '示例与主角的关系' WHERE name = '示例姓名';", "insertNode": "名单里的角色第一次和主角有来往、而表里还没有她时，插入一行。\nSQL示例: INSERT INTO important_characters (name, relation, stage, affection, trust, inner_voice, recent_change, last_met, is_absent, whereabouts, shared_history) VALUES ('示例姓名', '示例与主角的关系', '示例关系阶段', '示例好感度', '示例信任度', '示例心声', '示例最近变化', '示例最近见面', '示例是否离场', '示例此刻所在', '示例共同经历');", "ddl": "CREATE TABLE important_characters ( -- 重要角色表\n  row_id INTEGER PRIMARY KEY, -- 行号\n  name TEXT, -- 姓名\n  relation TEXT, -- 与主角的关系\n  stage TEXT, -- 关系阶段\n  affection TEXT, -- 好感度\n  trust TEXT, -- 信任度\n  inner_voice TEXT, -- 心声\n  recent_change TEXT, -- 最近变化\n  last_met TEXT, -- 最近见面\n  is_absent TEXT, -- 是否离场\n  whereabouts TEXT, -- 此刻所在\n  shared_history TEXT -- 共同经历\n);"}, "content": [["row_id", "姓名", "与主角的关系", "关系阶段", "好感度", "信任度", "心声", "最近变化", "最近见面", "是否离场", "此刻所在", "共同经历"]], "updateConfig": {"uiSentinel": -1, "contextDepth": -1, "updateFrequency": -1, "batchSize": -1, "skipFloors": -1, "groupId": -1}, "exportConfig": {"enabled": false, "splitByRow": false, "entryName": "重要角色表", "entryType": "constant", "keywords": "", "preventRecursion": true, "injectionTemplate": "", "extraIndexEnabled": false, "extraIndexEntryName": "重要角色表-索引", "extraIndexColumns": [], "extraIndexColumnModes": {}, "extraIndexInjectionTemplate": "", "sqlInjectionTemplate": "", "entryPlacement": {"position": "at_depth_as_system", "depth": 2, "order": 10000}, "extraIndexPlacement": {"position": "at_depth_as_system", "depth": 2, "order": 10010}, "fixedEntryPlacement": {"position": "at_depth_as_system", "depth": 2, "order": 99990}, "fixedIndexPlacement": {"position": "at_depth_as_system", "depth": 2, "order": 99991}}}, "sheet_kaxt5Hjv": {"uid": "sheet_kaxt5Hjv", "name": "乐队表", "orderNo": 4, "sourceData": {"note": "记录故事里的乐队：还在不在活动、成员是谁、最近在忙什么、下一场演出、和主角的关系。（列号为 0 基，与表格数据中的列标一致）\n- 列0: 乐队 - 乐队名，一支乐队只占一行。原作乐队只能写这些：Poppin'Party、Afterglow、Pastel·Palettes、Roselia、Hello, Happy World!、Morfonica、RAISE A SUILEN、MyGO!!!!!、Ave Mujica、梦限大MewType、妖精花束、CRYCHIC；玩家自己的乐队写玩家起的名字。\n- 列1: 状态 - 只能从这四个里选一个：活动中 / 休止 / 已解散 / 未成立。\n- 列2: 成员 - 成员的规范名，用顿号隔开，例如「户山香澄、花园多惠」。\n- 列3: 近况 - 乐队最近在忙什么，一句话，不超过 30 字。\n- 列4: 下一场演出 - 下一场演出的日期和场地，格式「YYYY-MM-DD · 场地」；没有就写「无」。\n- 列5: 与主角的关系 - 只能从这四个里选一个：无 / 相识 / 支援 / 成员。\n\n- 状态只跟着正文改：正文写到乐队结成、休止、重新开始、解散时才改，不按原作的年份自己改。开局写下的「未成立」，正文没写到结成就一直是「未成立」。", "initNode": "开局时由开局卡按年份和成立线写入原作乐队。", "deleteNode": "禁止。乐队解散时把状态改成「已解散」，不删除。", "updateNode": "乐队的状态、成员、近况、演出、和主角的关系变了时，更新对应的格子。\nSQL示例: UPDATE bands SET status = '示例状态' WHERE band = '示例乐队';", "insertNode": "出现新的乐队（包括玩家组的乐队）、而表里没有时，插入一行。\nSQL示例: INSERT INTO bands (band, status, members, recent, next_live, relation) VALUES ('示例乐队', '示例状态', '示例成员', '示例近况', '示例下一场演出', '示例与主角的关系');", "ddl": "CREATE TABLE bands ( -- 乐队表\n  row_id INTEGER PRIMARY KEY, -- 行号\n  band TEXT, -- 乐队\n  status TEXT, -- 状态\n  members TEXT, -- 成员\n  recent TEXT, -- 近况\n  next_live TEXT, -- 下一场演出\n  relation TEXT -- 与主角的关系\n);"}, "content": [["row_id", "乐队", "状态", "成员", "近况", "下一场演出", "与主角的关系"]], "updateConfig": {"uiSentinel": -1, "contextDepth": -1, "updateFrequency": -1, "batchSize": -1, "skipFloors": -1, "groupId": -1}, "exportConfig": {"enabled": true, "splitByRow": true, "entryName": "乐队表", "entryType": "keyword", "keywords": "乐队", "preventRecursion": true, "injectionTemplate": "<乐队近况>\n$1\n</乐队近况>", "extraIndexEnabled": false, "extraIndexEntryName": "乐队表-索引", "extraIndexColumns": [], "extraIndexColumnModes": {}, "extraIndexInjectionTemplate": "", "sqlInjectionTemplate": "", "entryPlacement": {"position": "at_depth_as_system", "depth": 2, "order": 10000}, "extraIndexPlacement": {"position": "at_depth_as_system", "depth": 2, "order": 10010}, "fixedEntryPlacement": {"position": "at_depth_as_system", "depth": 2, "order": 99990}, "fixedIndexPlacement": {"position": "at_depth_as_system", "depth": 2, "order": 99991}}}, "sheet_UaohIqlJ": {"uid": "sheet_UaohIqlJ", "name": "日程表", "orderNo": 5, "sourceData": {"note": "记录主角和别人说定了的事：什么时候、在哪、和谁、做什么，最后有没有做到。（列号为 0 基，与表格数据中的列标一致）\n- 列0: 日期 - 格式「YYYY-MM-DD」。\n- 列1: 时刻 - 格式「HH:MM」；没说定时刻写「未定」。\n- 列2: 事项 - 要做的事，不超过 20 字，例如「和香澄去乐器店」。\n- 列3: 地点 - 在哪做，写店、学校、车站这一级的名字；没说定写「未定」。\n- 列4: 参与者 - 一起的人，规范名，用顿号隔开；主角写「主角」。\n- 列5: 状态 - 只能从这四个里选一个：约定 / 完成 / 取消 / 爽约。\n\n- 只记说定了的事，随口一提的不记。", "initNode": "开局时不预填；故事里说定了事再插入。", "deleteNode": "状态已经是完成、取消或爽约，而且日期在故事当前时间七天以前的，删除这一行，表里只留近期的事。\nSQL示例: DELETE FROM schedule WHERE item = '示例事项';", "updateNode": "事情有了结果时，把状态改成完成、取消或爽约；时间、地点改了也更新。\nSQL示例: UPDATE schedule SET time = '示例时刻' WHERE item = '示例事项';", "insertNode": "主角和别人说定了一件事、而表里没有时，插入一行，状态写「约定」。\nSQL示例: INSERT INTO schedule (date, time, item, place, people, status) VALUES ('示例日期', '示例时刻', '示例事项', '示例地点', '示例参与者', '示例状态');", "ddl": "CREATE TABLE schedule ( -- 日程表\n  row_id INTEGER PRIMARY KEY, -- 行号\n  date TEXT, -- 日期\n  time TEXT, -- 时刻\n  item TEXT, -- 事项\n  place TEXT, -- 地点\n  people TEXT, -- 参与者\n  status TEXT -- 状态\n);"}, "content": [["row_id", "日期", "时刻", "事项", "地点", "参与者", "状态"]], "updateConfig": {"uiSentinel": -1, "contextDepth": -1, "updateFrequency": -1, "batchSize": -1, "skipFloors": -1, "groupId": -1}, "exportConfig": {"enabled": false, "splitByRow": false, "entryName": "日程表", "entryType": "constant", "keywords": "", "preventRecursion": true, "injectionTemplate": "", "extraIndexEnabled": false, "extraIndexEntryName": "日程表-索引", "extraIndexColumns": [], "extraIndexColumnModes": {}, "extraIndexInjectionTemplate": "", "sqlInjectionTemplate": "", "entryPlacement": {"position": "at_depth_as_system", "depth": 2, "order": 10000}, "extraIndexPlacement": {"position": "at_depth_as_system", "depth": 2, "order": 10010}, "fixedEntryPlacement": {"position": "at_depth_as_system", "depth": 2, "order": 99990}, "fixedIndexPlacement": {"position": "at_depth_as_system", "depth": 2, "order": 99991}}}, "sheet_iACudc6Z": {"uid": "sheet_iACudc6Z", "name": "技能表", "orderNo": 6, "sourceData": {"note": "记录主角会的技能：乐器、歌唱、特长、学业、生活，练到了哪一档。（列号为 0 基，与表格数据中的列标一致）\n- 列0: 技能 - 技能名，例如「贝斯」「做饭」。\n- 列1: 类别 - 只能从这五个里选一个：乐器 / 歌唱 / 特长 / 学业 / 生活。\n- 列2: 档位 - 1 到 5 的整数。乐器和歌唱：1 摸索、2 弹整首、3 能合奏、4 能登台、5 能主导；其他技能：1 入门到 5 精通。练出来了才升，一次只升一档。\n- 列3: 进展 - 最近练到哪了，一句话，不超过 20 字。\n- 列4: 最近练习 - 最近一次练习的日期，格式「YYYY-MM-DD」。\n\n- 只记主角的技能。", "initNode": "开局时由开局卡写入主角的乐器、歌唱和特长。", "deleteNode": "禁止。放下不练的技能保留在表里，不删除。", "updateNode": "练习了、有进步了，更新进展、最近练习；真正练出来了才把档位升一档。\nSQL示例: UPDATE skills SET category = '示例类别' WHERE skill = '示例技能';", "insertNode": "主角开始学一样新技能时，插入一行。\nSQL示例: INSERT INTO skills (skill, category, tier, progress, last_practice) VALUES ('示例技能', '示例类别', '示例档位', '示例进展', '示例最近练习');", "ddl": "CREATE TABLE skills ( -- 技能表\n  row_id INTEGER PRIMARY KEY, -- 行号\n  skill TEXT, -- 技能\n  category TEXT, -- 类别\n  tier TEXT, -- 档位\n  progress TEXT, -- 进展\n  last_practice TEXT -- 最近练习\n);"}, "content": [["row_id", "技能", "类别", "档位", "进展", "最近练习"]], "updateConfig": {"uiSentinel": -1, "contextDepth": -1, "updateFrequency": -1, "batchSize": -1, "skipFloors": -1, "groupId": -1}, "exportConfig": {"enabled": false, "splitByRow": false, "entryName": "技能表", "entryType": "constant", "keywords": "", "preventRecursion": true, "injectionTemplate": "", "extraIndexEnabled": false, "extraIndexEntryName": "技能表-索引", "extraIndexColumns": [], "extraIndexColumnModes": {}, "extraIndexInjectionTemplate": "", "sqlInjectionTemplate": "", "entryPlacement": {"position": "at_depth_as_system", "depth": 2, "order": 10000}, "extraIndexPlacement": {"position": "at_depth_as_system", "depth": 2, "order": 10010}, "fixedEntryPlacement": {"position": "at_depth_as_system", "depth": 2, "order": 99990}, "fixedIndexPlacement": {"position": "at_depth_as_system", "depth": 2, "order": 99991}}}, "sheet_suKJMGYr": {"uid": "sheet_suKJMGYr", "name": "物品表", "orderNo": 7, "sourceData": {"note": "记录主角的东西：属于哪一类、有几个、放在哪、哪来的。类别决定东西怎么没的：吃的喝的放不过夜，消耗品用完就没，票过期就没，其余的一直留着。（列号为 0 基，与表格数据中的列标一致）\n- 列0: 物品 - 东西的名字。\n- 列1: 类别 - 只能从这七个里选一个：常备 / 器材 / 食物 / 消耗品 / 票券 / 纪念品 / 其他。常备是天天带着的（手机、钱包、钥匙、证件、书包）；器材是乐器和练习、演出用的东西（吉他、拨片、谱子）；食物是吃的喝的；消耗品是用一次少一点的（琴弦、电池、药、创可贴）；票券是演出票、车票、优惠券；纪念品是别人送的、有纪念意义的东西。\n- 列2: 数量 - 只写数字。\n- 列3: 位置 - 只能从这三个里选一个：随身 / 家中 / 寄存。\n- 列4: 来源 - 只能从这四个里选一个：购买 / 赠送 / 借用 / 拾得。\n- 列5: 借用对象 - 借来的东西写是谁借给主角的（规范名或称呼）；不是借的写「无」。\n- 列6: 说明 - 不超过 20 字。票券写上日期和场地，例如「2020-05-02 · RiNG」。\n\n- 只记主角的东西，而且是正文里提到、以后可能用到的；零碎的东西（一张纸巾、一个塑料袋）不记。\n- 食物放不过夜：正文里吃掉、喝完就删；故事里的日期（全局数据表的当前时间）到了第二天还没吃完的，也删掉，当作吃掉或坏了。\n- 消耗品用一次数量减一，减到 0 删掉；票券用过、或者过了上面写的日期，删掉。\n- 常备的东西一直算随身，不用跟着改位置；其他东西正文写到放下、带上时才改位置。", "initNode": "开局时由开局卡写入主角开局带着的东西。", "deleteNode": "东西吃掉、用完、送人、还掉、丢了时删除这一行；食物到了第二天、票券过了日期、数量减到 0，也删除。\nSQL示例: DELETE FROM items WHERE item = '示例物品';", "updateNode": "数量、位置变了时更新；消耗品用了一次，数量减一。\nSQL示例: UPDATE items SET category = '示例类别' WHERE item = '示例物品';", "insertNode": "主角得到一样值得记的东西时，插入一行，类别照上面七类选一个。\nSQL示例: INSERT INTO items (item, category, count, location, source, lender, note) VALUES ('示例物品', '示例类别', '示例数量', '示例位置', '示例来源', '示例借用对象', '示例说明');", "ddl": "CREATE TABLE items ( -- 物品表\n  row_id INTEGER PRIMARY KEY, -- 行号\n  item TEXT, -- 物品\n  category TEXT, -- 类别\n  count TEXT, -- 数量\n  location TEXT, -- 位置\n  source TEXT, -- 来源\n  lender TEXT, -- 借用对象\n  note TEXT -- 说明\n);"}, "content": [["row_id", "物品", "类别", "数量", "位置", "来源", "借用对象", "说明"]], "updateConfig": {"uiSentinel": -1, "contextDepth": -1, "updateFrequency": -1, "batchSize": -1, "skipFloors": -1, "groupId": -1}, "exportConfig": {"enabled": true, "splitByRow": false, "entryName": "物品表", "entryType": "constant", "keywords": "", "preventRecursion": true, "injectionTemplate": "<主角的东西>\n$1\n</主角的东西>", "extraIndexEnabled": false, "extraIndexEntryName": "物品表-索引", "extraIndexColumns": [], "extraIndexColumnModes": {}, "extraIndexInjectionTemplate": "", "sqlInjectionTemplate": "", "entryPlacement": {"position": "at_depth_as_system", "depth": 2, "order": 10000}, "extraIndexPlacement": {"position": "at_depth_as_system", "depth": 2, "order": 10010}, "fixedEntryPlacement": {"position": "at_depth_as_system", "depth": 2, "order": 99990}, "fixedIndexPlacement": {"position": "at_depth_as_system", "depth": 2, "order": 99991}}}, "sheet_D12P1sB8": {"uid": "sheet_D12P1sB8", "name": "足迹表", "orderNo": 8, "sourceData": {"note": "记录主角去过的地方：第一次什么时候去的、最近一次、去了几次、和谁去的。地图上的「去过」读这张表。（列号为 0 基，与表格数据中的列标一致）\n- 列0: 地点 - 去过的地方，写店、学校、车站这一级的名字，和全局数据表的当前详细地点写法一致。\n- 列1: 片区 - 所在的区和街区，格式「区 · 街区」，例如「丰岛 · 池袋」。\n- 列2: 首次到访 - 第一次去的日期，格式「YYYY-MM-DD」。\n- 列3: 最近到访 - 最近一次去的日期，格式「YYYY-MM-DD」。\n- 列4: 到访次数 - 去了几次，只写数字。\n- 列5: 同行者 - 最近一次一起去的人，规范名，用顿号隔开；一个人去写「无」。\n\n- 只记场景类型是「现实」时主角真的去了的地方；回忆、梦境、想象、他人视角里的地方不记。", "initNode": "开局时由开局卡写入开局所在的地方。", "deleteNode": "禁止。去过的地方不删除。", "updateNode": "主角再次到一个地方时，更新最近到访、到访次数、同行者。\nSQL示例: UPDATE footprints SET area = '示例片区' WHERE place = '示例地点';", "insertNode": "主角第一次到一个地方时，插入一行。\nSQL示例: INSERT INTO footprints (place, area, first_visit, last_visit, visits, companions) VALUES ('示例地点', '示例片区', '示例首次到访', '示例最近到访', '示例到访次数', '示例同行者');", "ddl": "CREATE TABLE footprints ( -- 足迹表\n  row_id INTEGER PRIMARY KEY, -- 行号\n  place TEXT, -- 地点\n  area TEXT, -- 片区\n  first_visit TEXT, -- 首次到访\n  last_visit TEXT, -- 最近到访\n  visits TEXT, -- 到访次数\n  companions TEXT -- 同行者\n);"}, "content": [["row_id", "地点", "片区", "首次到访", "最近到访", "到访次数", "同行者"]], "updateConfig": {"uiSentinel": -1, "contextDepth": -1, "updateFrequency": -1, "batchSize": -1, "skipFloors": -1, "groupId": -1}, "exportConfig": {"enabled": false, "splitByRow": false, "entryName": "足迹表", "entryType": "constant", "keywords": "", "preventRecursion": true, "injectionTemplate": "", "extraIndexEnabled": false, "extraIndexEntryName": "足迹表-索引", "extraIndexColumns": [], "extraIndexColumnModes": {}, "extraIndexInjectionTemplate": "", "sqlInjectionTemplate": "", "entryPlacement": {"position": "at_depth_as_system", "depth": 2, "order": 10000}, "extraIndexPlacement": {"position": "at_depth_as_system", "depth": 2, "order": 10010}, "fixedEntryPlacement": {"position": "at_depth_as_system", "depth": 2, "order": 99990}, "fixedIndexPlacement": {"position": "at_depth_as_system", "depth": 2, "order": 99991}}}, "sheet_GnJvgids": {"uid": "sheet_GnJvgids", "name": "纪要表", "orderNo": 9, "sourceData": {"note": "轮次日志。每一轮交互结束后，必须插入一条新记录，记下这一轮发生了什么。这张表是整个故事的「事实账本」：以后想知道「之前发生过什么」，都来这里查。所以它必须客观、完整、可以核对。（列号为 0 基，与表格数据中的列标一致）\n- 列0: 时间跨度 - 本轮事件在故事世界里发生的时间范围。格式固定为「YYYY-MM-DD HH:MM ~ YYYY-MM-DD HH:MM」，例如「2020-04-08 16:20 ~ 2020-04-08 16:45」。正文没写具体时间时，按上一条记录的时间和本轮经过的时长推算，不要留空。\n- 列1: 地点 - 本轮事件发生的地点，从大到小写，用「·」隔开，例如「学校·三楼·音乐教室」。只用正文里出现过的名字；正文里没有专有名词的，用普通说法（「她家楼下」「车站前」），不要自己编店名和地名。\n- 列2: 纪要 - 以第三方视角、按时间顺序客观记录本轮发生的事：谁在场、谁做了什么、谁说了什么（关键台词可以直接引用原话）、结果是什么、有什么东西发生了变化。不超过 200 字。只写发生了的事和说出口的话，不写任何人的心理活动、动机猜测、情绪判断；不写「他们的关系更近了一步」这种总结；结尾不升华、不点题、不评论。\n- 列3: 概览 - 一句话概括本轮纪要，不超过 30 字。写事件本身（谁、做了什么），不写评价。例如「放学后两人在音乐教室收谱架，被值日生打断」这种形态。\n- 列4: 编码索引 - 本条记录的编号，格式为 AM 加四位数字，从 AM0001 开始逐条递增，不得跳号，不得与已有编号重复。插入前先看表里最大的编号，新编号是它加一。\n\n- 【纪要表专用】每一轮都必须插入且只插入一条新记录，不修改、不删除旧记录。\n- 【纪要表专用】主角的行动也要记，但只记主角做了什么、说了什么，不写主角的心理。\n\n【手账本·拼表开始】\n【分工】人物的心理、情绪、动机由「常夜灯的手账本」插件单独记录，本表不记录。\n本表只记正文里明确写到、可以核对的事实：人物做了什么、说了什么、去了哪里、什么东西变了。\n不写心理活动和动机推测（「她心里」「她其实」「她想要」「她害怕」这类句子删掉）。\n不写性格评价和类型标签（温柔、傲娇、腹黑、高冷……）。\n正文没写到的不补、不推测。\n本表的列说明里专门要求写人物认知、关系、心理、性格的那几列，照那几列自己的说明写；上面几条只管其余的列。\n【手账本·拼表结束】", "initNode": "故事开始时，插入一条新记录，记录开场的情形：谁在哪里、在做什么、发生了什么。", "deleteNode": "禁止。已经写下的纪要是事实记录，不删除。", "updateNode": "禁止。已经写下的纪要是事实记录，不修改。", "insertNode": "每一轮交互结束后，插入一条新记录。\n时间跨度格式必须为 YYYY-MM-DD HH:MM ~ YYYY-MM-DD HH:MM。\n编码索引必须是表中最大编号加一。\nSQL示例: INSERT INTO chronicle (time_span, location, chronicle_text, summary, code_index) VALUES ('示例时间跨度', '示例地点', '示例纪要', '示例概览', '示例编码索引');", "ddl": "CREATE TABLE chronicle ( -- 纪要表\n  row_id INTEGER PRIMARY KEY, -- 行号\n  time_span TEXT, -- 时间跨度\n  location TEXT, -- 地点\n  chronicle_text TEXT, -- 纪要\n  summary TEXT, -- 概览\n  code_index TEXT -- 编码索引\n);"}, "content": [["row_id", "时间跨度", "地点", "纪要", "概览", "编码索引"]], "updateConfig": {"uiSentinel": -1, "contextDepth": -1, "updateFrequency": -1, "batchSize": -1, "skipFloors": -1, "groupId": -1}, "exportConfig": {"enabled": true, "splitByRow": true, "entryName": "纪要", "entryType": "keyword", "keywords": "编码索引", "preventRecursion": true, "injectionTemplate": "<记忆回溯>\n$1\n</记忆回溯>", "extraIndexEnabled": true, "extraIndexEntryName": "纪要索引", "extraIndexColumns": ["概览", "编码索引"], "extraIndexColumnModes": {"概览": "index_only", "编码索引": "both"}, "extraIndexInjectionTemplate": "<已发生的事件概览>\n$1\n</已发生的事件概览>", "sqlInjectionTemplate": "", "entryPlacement": {"position": "at_depth_as_system", "depth": 999, "order": 10000}, "extraIndexPlacement": {"position": "at_depth_as_system", "depth": 1000, "order": 10010}, "fixedEntryPlacement": {"position": "at_depth_as_system", "depth": 999, "order": 99990}, "fixedIndexPlacement": {"position": "at_depth_as_system", "depth": 1000, "order": 99991}}}, "sheet_onNRw5xq": {"uid": "sheet_onNRw5xq", "name": "据点表", "orderNo": 10, "sourceData": {"note": "主角的家、工作地点、学校，一行一处。地图按这里的经纬度画家、工作、学校的标记，从这里开导航。（列号为 0 基，与表格数据中的列标一致）\n- 列0: 类型 - 只能写这四个之一：家 / 工作 / 学校 / 房产。房产是买下了但不住的房子。\n- 列1: 地点 - 这一处的名字：店名、学校名，或者家所在那一带的叫法。\n- 列2: 片区 - 所在的区和街区，格式「区 · 街区」。\n- 列3: 经度 - 经度，小数；不知道就留空。\n- 列4: 纬度 - 纬度，小数；不知道就留空。\n- 列5: 门牌 - 家和房产的门牌、楼名、房号，真实的、虚构的都行；工作、学校不填。\n- 列6: 来历 - 只能写这四个之一：开局 / 买下 / 租下 / 设定。\n- 列7: 价格 - 买下的房价或每月房租，只写数字，单位日元；其余不填。\n- 列8: 日期 - 定下来的日期，格式「YYYY-MM-DD」。\n\n- 家、工作、学校各只留一行：搬家、换工作、转学时改那一行，不另加。\n- 面板上买房、租房、设定写进来的行是锁住的，不要改。", "initNode": "开局时由开局卡写入住处、工作地点、学校。", "deleteNode": "正文写到主角辞掉工作、退学时，删掉那一行；家不删。\nSQL示例: DELETE FROM bases WHERE kind = '示例类型';", "updateNode": "正文写到主角搬家、换工作、转学时，改对应那一行的地点、片区；经纬度、门牌不知道就清空。\nSQL示例: UPDATE bases SET place = '示例地点' WHERE kind = '示例类型';", "insertNode": "正文写到主角第一次有了工作地点或学校时，插入一行。\nSQL示例: INSERT INTO bases (kind, place, area, lon, lat, house_no, origin, price, date) VALUES ('示例类型', '示例地点', '示例片区', '示例经度', '示例纬度', '示例门牌', '示例来历', '示例价格', '示例日期');", "ddl": "CREATE TABLE bases ( -- 据点表\n  row_id INTEGER PRIMARY KEY, -- 行号\n  kind TEXT, -- 类型\n  place TEXT, -- 地点\n  area TEXT, -- 片区\n  lon TEXT, -- 经度\n  lat TEXT, -- 纬度\n  house_no TEXT, -- 门牌\n  origin TEXT, -- 来历\n  price TEXT, -- 价格\n  date TEXT -- 日期\n);"}, "content": [["row_id", "类型", "地点", "片区", "经度", "纬度", "门牌", "来历", "价格", "日期"]], "updateConfig": {"uiSentinel": -1, "contextDepth": -1, "updateFrequency": -1, "batchSize": -1, "skipFloors": -1, "groupId": -1}, "exportConfig": {"enabled": false, "splitByRow": false, "entryName": "据点表", "entryType": "constant", "keywords": "", "preventRecursion": true, "injectionTemplate": "", "extraIndexEnabled": false, "extraIndexEntryName": "据点表-索引", "extraIndexColumns": [], "extraIndexColumnModes": {}, "extraIndexInjectionTemplate": "", "sqlInjectionTemplate": "", "entryPlacement": {"position": "at_depth_as_system", "depth": 2, "order": 10000}, "extraIndexPlacement": {"position": "at_depth_as_system", "depth": 2, "order": 10010}, "fixedEntryPlacement": {"position": "at_depth_as_system", "depth": 2, "order": 99990}, "fixedIndexPlacement": {"position": "at_depth_as_system", "depth": 2, "order": 99991}}}, "sheet_h2p2elJ4": {"uid": "sheet_h2p2elJ4", "name": "剧情开关表", "orderNo": 11, "sourceData": {"note": "剧情开关：哪些乐队从成立前开始、哪些乐队主线和活动收进故事、哪些原作收尾照原作发生。开局卡和面板写入，整张锁住；表里没有的开关，乐队主线算「开」，其余算「关」。（列号为 0 基，与表格数据中的列标一致）\n- 列0: 开关 - 开关名，格式「成立线·乐队名」「主线·剧情名」「收录·剧情名」「原作收尾·剧情名」。\n- 列1: 类型 - 只能写这四个之一：成立线 / 主线 / 收录 / 原作收尾。\n- 列2: 状态 - 只能写「开」或「关」。\n\n- 本表由开局卡和面板写入并锁住，填表时不修改、不插入、不删除。", "initNode": "开局时由开局卡写入十支乐队的成立线；乐队主线由面板在第一次关掉时补一行，收录、原作收尾由面板在第一次打开时补一行。", "deleteNode": "禁止。", "updateNode": "禁止。开关只由面板改。", "insertNode": "禁止。开关只由开局卡和面板写入。", "ddl": "CREATE TABLE story_switches ( -- 剧情开关表\n  row_id INTEGER PRIMARY KEY, -- 行号\n  switch_name TEXT, -- 开关\n  kind TEXT, -- 类型\n  state TEXT -- 状态\n);"}, "content": [["row_id", "开关", "类型", "状态"]], "updateConfig": {"uiSentinel": -1, "contextDepth": -1, "updateFrequency": 0, "batchSize": -1, "skipFloors": -1, "groupId": -1}, "exportConfig": {"enabled": false, "splitByRow": false, "entryName": "剧情开关表", "entryType": "constant", "keywords": "", "preventRecursion": true, "injectionTemplate": "", "extraIndexEnabled": false, "extraIndexEntryName": "剧情开关表-索引", "extraIndexColumns": [], "extraIndexColumnModes": {}, "extraIndexInjectionTemplate": "", "sqlInjectionTemplate": "", "entryPlacement": {"position": "at_depth_as_system", "depth": 2, "order": 10000}, "extraIndexPlacement": {"position": "at_depth_as_system", "depth": 2, "order": 10010}, "fixedEntryPlacement": {"position": "at_depth_as_system", "depth": 2, "order": 99990}, "fixedIndexPlacement": {"position": "at_depth_as_system", "depth": 2, "order": 99991}}}, "sheet_oI9AKIMJ": {"uid": "sheet_oI9AKIMJ", "name": "手账本·知情表", "orderNo": 12, "sourceData": {"note": "记录剧情里需要保密、或者只有一部分人知道的事：谁已经知道，谁还不知道。每件事占一行。（列号为 0 基，与表格数据中的列标一致）\n- 列0: 事项 - 被知道或被瞒着的那件事，一句话写清，不超过 40 字，例如「若叶睦还在弹吉他」。\n- 列1: 知情人 - 已经知道这件事的人物名字，多人用「、」隔开。只写正文里明确得知的人。\n- 列2: 不知情人 - 和这件事有关、但正文里明确还不知道的人物名字，多人用「、」隔开。没有就写「无」。\n- 列3: 得知方式 - 知情人是怎么知道的，例如「本人告知」「偷听到」「看到聊天记录」。几个人得知方式不同就分开写。\n- 列4: 是否公开 - 只填「是」或「否」。有关的人都已经知道时填「是」。\n\n- 【知情表专用】只记正文里明确写到的得知和隐瞒，不按人物性格推测谁可能知道。\n- 【知情表专用】有人新得知时，把名字从「不知情人」移到「知情人」，补上得知方式；所有人都知道后把「是否公开」改成「是」。\n- 【知情表专用】已经公开、而且纪要表里记下了公开经过的事，删掉这一行，表里只留还瞒着人的事。\n\n【手账本·拼表开始】\n【分工】人物的心理、情绪、动机由「常夜灯的手账本」插件单独记录，本表不记录。\n本表只记正文里明确写到、可以核对的事实：人物做了什么、说了什么、去了哪里、什么东西变了。\n不写心理活动和动机推测（「她心里」「她其实」「她想要」「她害怕」这类句子删掉）。\n不写性格评价和类型标签（温柔、傲娇、腹黑、高冷……）。\n正文没写到的不补、不推测。\n本表的列说明里专门要求写人物认知、关系、心理、性格的那几列，照那几列自己的说明写；上面几条只管其余的列。\n【手账本·拼表结束】", "initNode": "故事开始时，设定或开场里有明确要保密的事，每件插入一行。", "deleteNode": "「是否公开」已经是「是」，并且纪要表里已经记下了这件事公开的经过时，删除这一行。还有人不知道的不删。\nSQL示例: DELETE FROM hb_knowledge WHERE item = '示例事项';", "updateNode": "有人新得知、或者事情公开时，更新这一行的知情人、不知情人、得知方式、是否公开。\nSQL示例: UPDATE hb_knowledge SET knowers = '示例知情人' WHERE item = '示例事项';", "insertNode": "正文里出现新的保密的事，或者某件事第一次只被一部分人知道时，插入一行。\nSQL示例: INSERT INTO hb_knowledge (item, knowers, unaware, how_known, is_public) VALUES ('示例事项', '示例知情人', '示例不知情人', '示例得知方式', '示例是否公开');", "ddl": "CREATE TABLE hb_knowledge ( -- 手账本·知情表\n  row_id INTEGER PRIMARY KEY, -- 行号\n  item TEXT, -- 事项\n  knowers TEXT, -- 知情人\n  unaware TEXT, -- 不知情人\n  how_known TEXT, -- 得知方式\n  is_public TEXT -- 是否公开\n);"}, "content": [["row_id", "事项", "知情人", "不知情人", "得知方式", "是否公开"]], "updateConfig": {"uiSentinel": -1, "contextDepth": -1, "updateFrequency": -1, "batchSize": -1, "skipFloors": -1, "groupId": -1}, "exportConfig": {"enabled": false, "splitByRow": false, "entryName": "手账本·知情表", "entryType": "constant", "keywords": "", "preventRecursion": true, "injectionTemplate": "", "extraIndexEnabled": false, "extraIndexEntryName": "手账本·知情表-索引", "extraIndexColumns": [], "extraIndexColumnModes": {}, "extraIndexInjectionTemplate": "", "sqlInjectionTemplate": "", "entryPlacement": {"position": "at_depth_as_system", "depth": 2, "order": 10000}, "extraIndexPlacement": {"position": "at_depth_as_system", "depth": 2, "order": 10010}, "fixedEntryPlacement": {"position": "at_depth_as_system", "depth": 2, "order": 99990}, "fixedIndexPlacement": {"position": "at_depth_as_system", "depth": 2, "order": 99991}, "injectIntoWorldbook": false}}, "sheet_2Fzrwz1r": {"uid": "sheet_2Fzrwz1r", "name": "手账本·约定表", "orderNo": 13, "sourceData": {"note": "记录人物之间说出口的约定、答应过的事、接受了的请求，以及它们后来怎样了。每个约定占一行。（列号为 0 基，与表格数据中的列标一致）\n- 列0: 发起人 - 提出或答应这件事的人物名字。\n- 列1: 对象 - 约定的另一方，多人用「、」隔开。\n- 列2: 约定内容 - 约了什么、答应了什么，一句话，不超过 40 字，例如「周六一起去看演出」。\n- 列3: 约定时间 - 约好什么时候兑现，例如「本周六下午」「演出前」。正文没说就写「未定」。\n- 列4: 状态 - 只填「未到期」「已兑现」「已违约」「已取消」之一。\n\n- 【约定表专用】只记正文里明确说出口的约定和答应，不记人物心里的打算。\n- 【约定表专用】约定兑现、违约或取消时先改「状态」；纪要表里记下了这件事以后，删掉这一行，表里只留还没了结的约定。\n\n【手账本·拼表开始】\n【分工】人物的心理、情绪、动机由「常夜灯的手账本」插件单独记录，本表不记录。\n本表只记正文里明确写到、可以核对的事实：人物做了什么、说了什么、去了哪里、什么东西变了。\n不写心理活动和动机推测（「她心里」「她其实」「她想要」「她害怕」这类句子删掉）。\n不写性格评价和类型标签（温柔、傲娇、腹黑、高冷……）。\n正文没写到的不补、不推测。\n本表的列说明里专门要求写人物认知、关系、心理、性格的那几列，照那几列自己的说明写；上面几条只管其余的列。\n【手账本·拼表结束】", "initNode": "故事开始时，设定或开场里有明确的约定，每个插入一行。", "deleteNode": "「状态」已经是「已兑现」「已违约」或「已取消」，并且纪要表里已经记下了这件事时，删除这一行。「未到期」的不删。\nSQL示例: DELETE FROM hb_promises WHERE content = '示例约定内容';", "updateNode": "约定兑现、违约、取消，或者约定时间改了时，更新这一行。\nSQL示例: UPDATE hb_promises SET promisee = '示例对象' WHERE content = '示例约定内容';", "insertNode": "正文里有人明确约定、答应或接受请求时，插入一行，状态填「未到期」。\nSQL示例: INSERT INTO hb_promises (promiser, promisee, content, due, status) VALUES ('示例发起人', '示例对象', '示例约定内容', '示例约定时间', '示例状态');", "ddl": "CREATE TABLE hb_promises ( -- 手账本·约定表\n  row_id INTEGER PRIMARY KEY, -- 行号\n  promiser TEXT, -- 发起人\n  promisee TEXT, -- 对象\n  content TEXT, -- 约定内容\n  due TEXT, -- 约定时间\n  status TEXT -- 状态\n);"}, "content": [["row_id", "发起人", "对象", "约定内容", "约定时间", "状态"]], "updateConfig": {"uiSentinel": -1, "contextDepth": -1, "updateFrequency": -1, "batchSize"