 "故事开始时，设定或开场里写明关系的配角，每一对插入一行。", "deleteNode": "禁止。关系断了就在当前状态里写明，不删除。", "updateNode": "两人之间又发生了关键的事、或者相处状态变了时，更新交往经过和当前状态。\nSQL示例: UPDATE hb_npc_relations SET person_b = '示例人物B' WHERE person_a = '示例人物A';", "insertNode": "正文里两个配角第一次有了实质来往时，插入一行。\nSQL示例: INSERT INTO hb_npc_relations (person_a, person_b, history, status) VALUES ('示例人物A', '示例人物B', '示例交往经过', '示例当前状态');", "ddl": "CREATE TABLE hb_npc_relations ( -- 手账本·配角关系表\n  row_id INTEGER PRIMARY KEY, -- 行号\n  person_a TEXT, -- 人物A\n  person_b TEXT, -- 人物B\n  history TEXT, -- 交往经过\n  status TEXT -- 当前状态\n);"}, "content": [["row_id", "人物A", "人物B", "交往经过", "当前状态"]], "updateConfig": {"uiSentinel": -1, "contextDepth": -1, "updateFrequency": -1, "batchSize": -1, "skipFloors": -1, "groupId": -1}, "exportConfig": {"enabled": false, "splitByRow": false, "entryName": "手账本·配角关系表", "entryType": "constant", "keywords": "", "preventRecursion": true, "injectionTemplate": "", "extraIndexEnabled": false, "extraIndexEntryName": "手账本·配角关系表-索引", "extraIndexColumns": [], "extraIndexColumnModes": {}, "extraIndexInjectionTemplate": "", "sqlInjectionTemplate": "", "entryPlacement": {"position": "at_depth_as_system", "depth": 2, "order": 10000}, "extraIndexPlacement": {"position": "at_depth_as_system", "depth": 2, "order": 10010}, "fixedEntryPlacement": {"position": "at_depth_as_system", "depth": 2, "order": 99990}, "fixedIndexPlacement": {"position": "at_depth_as_system", "depth": 2, "order": 99991}, "injectIntoWorldbook": false}}};        // 总控/表格/正常内容.json，构建时嵌进来
const 模板版本 = '5016ad8286';   // 模板内容的指纹，换了模板就变

function 库() {
  try { return window.parent.AutoCardUpdaterAPI || null; } catch (e) { return null; }
}
const 有库 = () => { const a = 库(); return !!(a && typeof a.initGameSession === 'function'); };

// {表名: {键, 列: [...], 行: [[...]]}}；没装数据库返回 null
function 读全部表() {
  const a = 库();
  if (!a || typeof a.exportTableAsJson !== 'function') return null;
  let 全;
  try { 全 = a.exportTableAsJson() || {}; } catch (e) { return null; }
  const 出 = {};
  for (const 键 of Object.keys(全)) {
    const t = 全[键];
    if (!t || !t.name || !Array.isArray(t.content)) continue;
    出[t.name] = {
      键,
      列: (t.content[0] || []).slice(1).map(String),
      行: t.content.slice(1).map(r => (r || []).slice(1).map(v => (v == null ? '' : String(v)))),
    };
  }
  return 出;
}
function 行对象(表, i) {
  const o = {};
  if (!表 || !表.行[i]) return null;
  表.列.forEach((列, j) => { o[列] = 表.行[i][j] || ''; });
  return o;
}

// 开局第 2、3 步：导入本卡模板，再把它设成这个聊天的模板。
// 只走第 2 步的话，数据库填表时拿的还是旧模板，同一次会话里第一次自动填表会报「表身份重绑定失败」。
// 数据库找不到能写初始存档点的 AI 楼层时回这句（它在自己看到的聊天里找不是玩家发的那一楼，0 楼开场白就是）
const 没认出零楼 = /checkpoint 的 AI 楼层/;
// 数据库还在把上一个模板套到这个聊天上时回这句（导完模板以后它自己会切一次，切完才放下一个）：等它切完再设
const 切换中 = /切换正在进行中/;
// 数据库眼里的这个聊天：0 楼有字，它的 getStoryContext 却读出空的，就是它根本看不到这个聊天（读到的是空聊天）。
// 插件版每次现取酒馆的聊天，不会这样；见过的是装成脚本、装了两份的
function 库看不见聊天() {
  const a = 库(), c = 酒馆();
  if (!a || typeof a.getStoryContext !== 'function' || !c) return false;
  if (!(c.chat || []).some(m => m && !m.is_user && String(m.mes || '').trim())) return false;
  try { return a.getStoryContext(1) === ''; } catch (e) { return false; }
}
// 开局停住时附在报错后面的一行：酒馆、酒馆助手、数据库各是哪一版、怎么装的。玩家截一张图就够查
function 环境() {
  const 段 = [];
  try { 段.push('酒馆 ' + getTavernVersion()); } catch (e) { /* 酒馆助手太旧 */ }
  try { 段.push('酒馆助手 ' + getTavernHelperVersion()); } catch (e) { /* 酒馆助手太旧 */ }
  let 份们 = [];
  try { 份们 = 数据库们(); } catch (e) { /* 读不了 */ }
  段.push('数据库 ' + (份们.length ? 份们.map(x => x.字 + '（' + x.装法 + '版）').join(' + ') : (库版本().字 || '读不出版本')));
  return 段.join(' · ');
}

async function 导入模板() {
  const a = 库();
  if (!有库()) throw new Error('没装龙血玄黄·数据库');
  const 导 = () => a.initGameSession(null, {
    templateData: 深拷(本卡模板), templatePresetName: 模板预设名, loadPreset: false, resetExistingTableData: true,
  });
  let r = await 导();
  const 话 = x => (x && (x.message || x.warning)) || '没有回音';
  // 没认出 0 楼：聊天刚换过、还在重载时数据库看到的是空聊天，等一下再导一次
  if ((!r || !r.success) && 没认出零楼.test(话(r))) {
    await new Promise(ok => setTimeout(ok, 1500));
    r = await 导();
  }
  if (!r || !r.success) {
    if (没认出零楼.test(话(r)) && 库看不见聊天()) {
