  return j >= 0 && !!库().lockTableCell(t.键, 行, j, 锁);
}
// 一行的每一格分别锁上（不用行锁：行锁解不开其中一格，面板「档案」要能一格一格还给填表 AI）
function 锁满一行(表名, 行) {
