  if (!t.行.length) return true;   // 空表没有格子要锁
  const 格 = [];
  t.行.forEach((_, i) => t.列.forEach((_, j) => 格.push(i + ':' + j)));
  return !!库().setTableLockState(t.键, { cells: 格 }, { merge: true });
}
