    们.push({ 装法: '脚本', 字: 版 && !名.includes(版) ? 名 + ' ' + 版 : 名 });
  });
  try { const 脚本库 = (es.tavern_helper || {}).script || {}; if (!脚本库.enabled || 脚本库.enabled.global !== false) 扫(脚本库.scripts); } catch (e) { /* 酒馆助手太旧 */ }
  try { 扫((((当前卡() || {}).data || {}).extensions || {}).tavern_helper?.scripts); } catch (e) { /* 没选卡 */ }
