  const 行 = {};

  行.全局数据表 = [{
    模式: '0', 年份: String(年), 时节: t.时节 || 日期的时节(t.日期), 当前时间: 当前时间串(t.日期, t.时刻),
    经过的时间: '开局', 天气: '', 场景类型: '现实',
    当前主要地区: '东京都', 当前次要地区: 地.片区, 当前详细地点: 地.全名,
  }];

  const 档案 = { 姓名: 主角名, 罗马音: b.罗马音 || '', 称呼: b.称呼 || '', 性别: b.性别 || '', 年龄: String(b.年龄 || ''), 住所: 档住所(档) };
  for (const k of 资料组.外貌) 档案[k] = String((档.外貌 || {})[k] || '').trim();
  for (const k of 资料组.身世) 档案[k] = String((档.身世 || {})[k] || '').trim();
  for (const k of 资料组.性格) 档案[k] = String((档.性格 || {})[k] || '').trim();
  // 说话习惯只在第三人称时写进档案：第一、第二人称里主角的话由玩家自己说，写进去正文模型会替主角开口（抢话）
  if ((档.第一层 || {}).人称 && 档.第一层.人称 !== '第三人称') 档案.说话习惯 = '';
  行.主角档案表 = [档案];

  const 金钱 = String(((档.物品 || {}).金钱 || '')).replace(/[^\d]/g, '');
  行.主角现况表 = [{
    身份: 档身份串(档), 所属乐队: 档乐队名(档) || '无', 穿着: 档案.常穿服装 || '',
    持有金钱: 金钱 || '0', 状况: '', 体力: '100',
  }];

  const 认识 = (档.人际 || []).filter(p => 查人(p.名)).slice(0, 上限.人际);
  // 好感、信任：0 层卡里挪过的用挪过的（千分制 -1000～1000），没挪过照关系表；关系阶段照好感算
  const 起点数 = (v, 默) => { const n = Number(v); return v === undefined || v === null || v === '' || !isFinite(n) ? 默 : Math.max(-关系满分, Math.min(关系满分, Math.round(n))); };
  行.重要角色表 = 认识.map(p => {
    const 关 = 关系表[p.关系] || 关系表['一面之缘'];
    const 一句 = String(p.一句 || '').trim();
    const 合 = 一句 ? p.关系 + ' · ' + 一句 : p.关系;
    const 放得下 = 合.length <= 20;
    return {
      姓名: p.名, 与主角的关系: 放得下 ? 合 : p.关系, 关系阶段: 阶段之于(起点数(p.好感, 关.好感)) || 关.阶段,
      好感度: String(起点数(p.好感, 关.好感)), 信任度: String(起点数(p.信任, 关.信任)), 心声: '', 最近变化: '', 最近见面: '',
      是否离场: '是', 共同经历: 放得下 ? '' : 一句,
    };
  });

  // 成立线勾了的乐队开局写「未成立」，它的成立经过在世界书里照常出现；CRYCHIC 不在名单里，单给一行
  const 勾的 = 档成立线(档);
  const 认识的队 = new Set(认识.map(p => (查人(p.名) || {}).队));
  const 认识的人 = new Set(认识.map(p => p.名));
  行.乐队表 = 原作乐队.map(队 => ({ 队, 成员: 名单.filter(x => x.队 === 队 && !x.人格).map(x => x.名), 相识: 认识的队.has(队) }))
    .concat(旧乐队.map(o => ({ 队: o.队, 成员: o.成员, 相识: o.成员.some(名 => 认识的人.has(名)) })))
    .map(o => ({
      乐队: o.队, 状态: 勾的.includes(o.队) ? '未成立' : 乐队状态(o.队, 年), 成员: o.成员.join('、'),
      近况: '', 下一场演出: '无', 与主角的关系: o.相识 ? '相识' : '无',
    }));
  const 自己的队 = 档乐队名(档);
  if (自己的队) {
    行.乐队表.push({
      乐队: 自己的队, 状态: j.乐队 === '自组乐队' ? '活动中' : '未成立', 成员: 主角名,
      近况: j.乐队 === '招募中' ? '在招成员' : '', 下一场演出: '无', 与主角的关系: '成员',
    });
  }

  行.技能表 = [];
  for (const x of 乐器们(j).slice(0, 上限.乐器)) {
    行.技能表.push({ 技能: x.名, 类别: x.名 === '主唱' ? '歌唱' : '乐器', 档位: String(x.水平 || 1), 进展: '', 最近练习: '' });
  }
  for (const 长 of (j.特长 || []).slice(0, 上限.特长)) {
    行.技能表.push({ 技能: 长, 类别: '特长', 档位: '3', 进展: '', 最近练习: '' });
  }

  const 物 = 档.物品 || {};
  行.物品表 = [];
  for (const 位置 of ['随身', '家中']) {
    for (const 名 of 物[位置] || []) {
      if (String(名).trim()) 行.物品表.push({ 物品: String(名).trim(), 类别: 猜物品类(名), 数量: '1', 位置, 来源: '购买', 借用对象: '无', 说明: '' });
    }
  }

  行.足迹表 = [{ 地点: 地.全名, 片区: 地.片区, 首次到访: t.日期, 最近到访: t.日期, 到访次数: '1', 同行者: '无' }];
  行.据点表 = 开局据点(档, t.日期);
  行.剧情开关表 = 建剧情开关(年, 勾的);
  return 行;
}

function 开局原文(档) {
  const 年 = 档年份(档);
  const 地 = 档地点(档);
  const t = 档.时间 || {}, b = 档.基本 || {}, j = 档.技能 || {}, f = 档.第一层 || {};
  const 名 = String(b.姓名 || '').trim();
  const 主角 = 名 + (b.罗马音 ? '（' + b.罗马音 + '）' : '') + '，' + [b.性别, b.年龄, 档身份短(档)].filter(Boolean).join('，');
  const 技 = [];
  if (j.乐器 === '零基础') 技.push('乐器零基础');
  else if (j.乐器) 技.push(乐器串(j));
  if ((j.特长 || []).length) 技.push('特长 ' + j.特长.join('、'));
  const 乐队 = 档乐队名(档);
  if (乐队) 技.push((j.乐队 === '自组乐队' ? '乐队 ' : '在招成员的乐队 ') + 乐队);
  const 人 = (档.人际 || []).filter(p => 查人(p.名)).map(p => p.名 + '（' + p.关系 + '）').join('、') || '无';
  const 行们 = [
    '<开局>',
    '玩法：' + (档.玩法 || '正常内容'),
    '时间：' + 当前时间串(t.日期, t.时刻) + '（' + (t.时节 || 日期的时节(t.日期)) + '）' + (年 && String(t.日期 || '').slice(0, 4) !== String(年) ? '，' + 年 + ' 年' : ''),
    '地点：东京 / ' + 地.片区 + ' / ' + 地.全名,
    '主角：' + 主角,
    '技能：' + (技.join('；') || '无'),
    '人际关系：' + 人,
    ...(档成立线(档).length ? ['成立线：' + 档成立线(档).join('、') + '（从成立前开始）'] : []),
    '人称：' + (f.人称 || '第三人称') + '　篇幅：' + (f.篇幅 || '标准'),
    '</开局>',
    '<开场白>',
    f.代写 && !String(f.开场白 || '').trim()
      ? '（空着。请依据上面的时间、地点、人际关系写开场。）'
      : String(f.开场白 || '').trim(),
    '</开场白>',
  ];
  return 行们.join('\n');
}

// ── 核心/快照.js ──
// 快照：把数据库里的表整理成两块屏直接能画的一份。
// 名字按名单归一（艺名归本名），归不上的标「其他」；「85/100」这类数字能解析就解析；同一个人两行取后面那行。
// 屏拿到的全是纯文本，HTML、Markdown 一律当字画，由屏自己转义。

let 正在填表 = false;
let 填表起 = 0;        // 数据库说开始填表的那一刻：两分钟没等到表更新（填表失败）就当没在填
let 最近已存 = true;
const 填表超时 = 120000;
function 在填表() { return 正在填表 && Date.now() - 填表起 < 填表超时; }

// 数据库这一轮填表忙不忙：引擎写回、收录对时这些自己写表的先问这里。填表时数据库拒绝别人写表（日志里记一条「已拒绝外部表格写入」），
// 它刚抄下表、还没把自己标成在填的那一下有人写进去，它填完时版本对不上，这一轮整轮作废。三种算忙：
//   填表   数据库说了开始填表（不静默的自动填表、手动填表），到表更新为止
//   等填表 新的一楼落地、数据库的自动更新开着：等它把这一轮的表存进那一楼（消息上的 TavernDB_ACU_IsolatedData 有了或换了），
//          有上限（自动填表等多久）。填完之前它不发「表更新了」，填完存进那一楼紧接着发
//   刚填完 数据库填完先通知「表更新了」，半秒后才放下自己「在填」的标记、再通知一次：它填完的通知后 1.5 秒内
// 我们自己写表引起的「表更新了」不算（自写中）
let 等填表起 = 0;
let 等填表限 = 0;
let 等填表楼 = -1;
let 等填表基;
let 库通知于 = 0;
let 自写中 = 0;
const 通知后让 = 1500;
function 库在忙() {
  if (在填表()) return '填表';
  const 现 = Date.now();
  if (等填表起 && 现 - 等填表起 < 等填表限) return '等填表';
  if (现 - 库通知于 < 通知后让) return '刚填完';
  return '';
}
// 某一楼消息上存的这一轮的表（数据库填完存进去）
function 楼上的表(楼) {
  try { const c = 酒馆(), m = c && c.chat && c.chat[楼]; return m ? m.TavernDB_ACU_IsolatedData : undefined; } catch (e) { return undefined; }
}
// 新的一楼落地，等数据库填它最多等多久（0 = 不等）：自动更新开着就当会填。每楼都填、这一楼过了最小长度，最多等 90 秒；
// 隔几楼才填、这一楼不够长的不一定填，最多等 20 秒。最小长度按字数估
function 自动填表等多久(楼) {
  try {
    const 设 = 库设置();
    if (!设 || 设.autoUpdateEnabled === false || !填表接口已配()) return 0;
    const p = 库().getUpdateConfigParams(), 最小 = Number(p.autoUpdateTokenThreshold) || 0;
    const c = 酒馆(), m = c && c.chat && c.chat[楼], 长 = m ? String(m.mes || '').length : 0;
    return Number(p.autoUpdateFrequency) === 1 && 长 >= 最小 ? 90000 : 20000;
  } catch (e) {
    return 0;
  }
}

function 取数(v) {
  const m = /-?\d+(\.\d+)?/.exec(String(v == null ? '' : v));
  return m ? Number(m[0]) : null;
}
// 好感、信任是千分制。没装引擎时填表 AI 偶尔写成「85/100」「85%」：按比例折成千分制；「很高」这种认不出的给 null，面板照原文显示
function 取关系数(v) {
  const s = String(v == null ? '' : v);
  let m = /(-?\d+(?:\.\d+)?)\s*[\/／]\s*(\d+(?:\.\d+)?)/.exec(s);
  if (m && Number(m[2]) > 0) return Math.round(Number(m[1]) / Number(m[2]) * 1000);
  m = /(-?\d+(?:\.\d+)?)\s*[%％]/.exec(s);
  if (m) return Math.round(Number(m[1]) * 10);
  return 取数(s);
}

function 快照() {
  const 全 = 读全部表();
  if (!全) return null;
  const 一行 = 名 => (全[名] ? 行对象(全[名], 0) : null);
  const 多行 = 名 => (全[名] ? 全[名].行.map((_, i) => Object.assign({ _行: i }, 行对象(全[名], i))) : []);
  const g = 一行('全局数据表') || {};

  const 按人 = new Map();
  for (const r of 多行('重要角色表')) {
    const 规范 = 归名(r.姓名);
    const 人 = Object.assign({}, r, {
      姓名: 规范 || String(r.姓名 || '').trim(),
      其他: !规范,
      好感数: 取关系数(r.好感度),
      信任数: 取关系数(r.信任度),
      离场: /^是/.test(String(r.是否离场 || '')),
      头像: 规范 ? (查人(规范) || {}).头像 || '' : '',
      队: 规范 ? (查人(规范) || {}).队 || '' : '',
    });
    if (人.姓名) 按人.set(人.姓名, 人);
  }

  return {
    模式: g.模式 || '0',
    年份: g.年份 || '', 时节: g.时节 || '', 当前时间: g.当前时间 || '', 天气: g.天气 || '',
    经过的时间: g.经过的时间 || '', 场景类型: g.场景类型 || '现实',
    地点: { 主要: g.当前主要地区 || '', 次要: g.当前次要地区 || '', 详细: g.当前详细地点 || '' },
    主角: { 档案: 一行('主角档案表'), 现况: 一行('主角现况表') },
    角色: [...按人.values()],
    乐队: 多行('乐队表'), 日程: 多行('日程表'), 技能: 多行('技能表'), 物品: 多行('物品表'),
    // 足迹、纪要：这一局没有这张表（很早的模板）给 null，面板不出那两块
    足迹: 全['足迹表'] ? 多行('足迹表') : null, 纪要: 全['纪要表'] ? 多行('纪要表') : null, 据点: 多行('据点表'),
    开关: 开关表(全['剧情开关表']),
    填表中: 在填表(), 已存: 最近已存,
  };
}

function 档案表有人() {
  const 全 = 读全部表();
  const t = 全 && 全['主角档案表'];
  return !!(t && t.行[0] && String(t.行[0][0] || '').trim());
}

// ── 核心/接口.js ──
// 帮填接口：卡自己的，不借数据库的。✦ 补全、代写、推荐都走它。
// 经酒馆后端的自定义接口转发（chat_completion_source: 'custom'），和手账本同一个做法：
//   · 浏览器直连很多接口会被跨域拦下，经后端转一手就没这个问题；
//   · 密钥放在自定义请求头里，不动酒馆主连接的任何设置；
//   · 回答写到一半（finish_reason 是 length）看得出来，调用方加大上限重发。
// 地址、模型、密钥只存在这台浏览器的 localStorage 里：不进聊天、不进卡的脚本变量，导出卡、分享聊天都带不走。
// 对外只报「有没有密钥」，密钥本身不交出去。
const 接口键 = 'BanG.帮填接口';
const 生成地址 = '/api/backends/chat-completions/generate';
const 列表地址 = '/api/backends/chat-completions/status';

function 读接口() {
  try {
    const o = JSON.parse(主窗().localStorage.getItem(接口键) || 'null');
    return o && typeof o === 'object' ? o : {};
  } catch (e) {
    return {};
  }
}
function 接口概况() {
  const c = 读接口();
  return { 地址: c.地址 || '', 模型: c.模型 || '', 有密钥: !!c.密钥, 配好: !!(c.地址 && c.模型) };
}
// 给了哪项改哪项；密钥给空串就是删掉，不给（undefined）就留着原来的
function 改接口(改) {
  const c = 读接口();
  for (const k of ['地址', '模型', '密钥']) if (改 && typeof 改[k] === 'string') c[k] = 改[k].trim();
  try { 主窗().localStorage.setItem(接口键, JSON.stringify(c)); } catch (e) { throw new Error('浏览器不让存：' + (e && e.message || e)); }
  发(事件.状态, 状态());
  return 接口概况();
}

function yaml引号(s) {
  return '"' + String(s).replace(/\\/g, '\\\\').replace(/"/g, '\\"') + '"';
}
function 请求头(c) {
  return c.密钥 ? 'Authorization: ' + yaml引号('Bearer ' + c.密钥) : '';
}
// 报错里不带请求体（请求体里有密钥），只截接口回的那一句
function 接口报错(状态码, 原话) {
  const 话 = String(原话 || '').replace(/\s+/g, ' ').slice(0, 160);
  if (状态码 === 401 || 状态码 === 403 || /Unauthorized|Forbidden|invalid.{0,12}key/i.test(话)) return new Error('密钥不对或没有权限');
  if (状态码 === 404 || /Not Found/i.test(话)) return new Error('接口地址或模型名不对');
  if (状态码 === 429 || /Too Many|rate limit/i.test(话)) return new Error('接口限流了，等一会儿再试');
  return new Error('接口报错' + (状态码 ? ' ' + 状态码 : '') + (话 ? '：' + 话 : ''));
}

// 发一次。回 {文, 截断}；没配、报错、超时都抛错
async function 问接口(消息们, 上限, 秒) {
  const c = 读接口();
  if (!c.地址) throw new Error('帮填接口没填地址');
  if (!c.模型) throw new Error('帮填接口没填模型');
  const 酒 = 酒馆();
  if (!酒 || typeof 酒.getRequestHeaders !== 'function') throw new Error('拿不到酒馆');
  const 窗 = 主窗();
  const 限 = (秒 || 90) * 1000;
  const 控 = new 窗.AbortController();
  const 钟 = setTimeout(() => 控.abort(), 限);
  try {
    const r = await 窗.fetch(窗.location.origin + 生成地址, {
      method: 'POST', headers: 酒.getRequestHeaders(), signal: 控.signal,
      body: JSON.stringify({
        chat_completion_source: 'custom', custom_url: c.地址, custom_include_headers: 请求头(c),
        model: c.模型, messages: 消息们, max_tokens: 上限, temperature: 1, stream: false,
      }),
    });
    const 原 = await r.text();
    let j = null;
    try { j = JSON.parse(原); } catch (e) { /* 下面统一报错 */ }
    if (!r.ok || !j || j.error) throw 接口报错(r.ok ? 0 : r.status, j && j.error ? (j.error.message || JSON.stringify(j.error)) : 原);
    const 选 = j.choices && j.choices[0];
    const 文 = 选 && 选.message && typeof 选.message.content === 'string' ? 选.message.content : '';
    return { 文, 截断: !!(选 && 选.finish_reason === 'length') };
  } catch (e) {
    if (e && e.name === 'AbortError') throw new Error('帮填接口 ' + Math.round(限 / 1000) + ' 秒没回');
    throw e;
  } finally {
    clearTimeout(钟);
  }
}

// 接口给的模型列表（OpenAI 兼容的 /models），同样经后端转。回 {ok, 模型们} 或 {ok:false, 原因}
async function 列模型() {
  const c = 读接口();
  if (!c.地址) return { ok: false, 原因: '先填接口地址' };
  const 酒 = 酒馆();
  if (!酒 || typeof 酒.getRequestHeaders !== 'function') return { ok: false, 原因: '拿不到酒馆' };
  try {
    const 窗 = 主窗();
    const r = await 窗.fetch(窗.location.origin + 列表地址, {
      method: 'POST', headers: 酒.getRequestHeaders(),
      body: JSON.stringify({ chat_completion_source: 'custom', custom_url: c.地址, custom_include_headers: 请求头(c) }),
    });
    const j = await r.json().catch(() => null);
    const 原 = j && Array.isArray(j.data) ? j.data : (j && j.data && Array.isArray(j.data.data) ? j.data.data : []);
    const 们 = [...new Set(原.map(m => String((m && (m.id || m.name)) || '').trim()).filter(Boolean))].sort();
    return 们.length ? { ok: true, 模型们: 们 } : { ok: false, 原因: r.ok ? '这个接口没给模型列表，手填模型名' : '接口报错 ' + r.status };
  } catch (e) {
    return { ok: false, 原因: String(e && e.message || e) };
  }
}

// 测试连接：发一句很短的。思考把字数用完了（截断、没字）也算连上了
async function 测接口() {
  try {
    const r = await 问接口([{ role: 'user', content: '只回一个字：好' }], 256, 45);
    if (r.文.trim()) return { ok: true, 话: '连上了 · ' + 读接口().模型 };
    return r.截断 ? { ok: true, 话: '连上了 · 这个模型会先思考，回答可能慢一点' } : { ok: false, 原因: '接口回了空的' };
  } catch (e) {
    return { ok: false, 原因: String(e && e.message || e) };
  }
}

// 别的脚本（游戏引擎的副模型）借卡的帮填接口问一句：直连酒馆后端，不发酒馆的生成事件。
// 借数据库的 callAI 不行：数据库走主接口时它经酒馆助手的 generateRaw，会发出「生成开始」事件，
// 开着剧情推进的数据库会把它当成玩家又发了一句，真正那条回复的自动填表就时有时无（测试酒馆实测）。
// 回 {ok, 文} / {ok:false, 原因}
async function 旁问(消息们, 选项) {
  if (!接口概况().配好) return { ok: false, 原因: '帮填接口没配' };
  try {
    const r = await 问接口(消息们, (选项 && 选项.max_tokens) || 1200, (选项 && 选项.秒) || 60);
    if (r.文.trim()) return { ok: true, 文: r.文, 截断: r.截断 };
    return { ok: false, 原因: r.截断 ? '回答被截断' : '接口回了空的' };
  } catch (e) {
    return { ok: false, 原因: String(e && e.message || e) };
  }
}

// ── 核心/帮填.js ──
// AI 帮填（✦）：走卡自己的帮填接口（接口.js），不借数据库的。
// 四种请求，屏上交来的「已填」是 {格名: 值}，只含填了的格子：
//   单格   {类:'单格', 名, 说明?, 限长?, 个数?, 已填}           → {ok, 候选:[…]}
//   一组   {类:'一组', 名们:[…], 已填}                          → {ok, 结果:{格名: 值}}
//   人际   {类:'人际', 年份, 已选:[名…], 已填}                  → {ok, 候选:[{名, 关系, 一句}]}
//   开场白 {类:'开场白', 人称, 篇幅, 现有?, 续写?, 已填}         → {ok, 文}
// 连不上、没配接口时返回 {ok:false, 原因}，屏上把 ✦ 灰掉、说一句为什么，不耽误手填。
// 上限：第一次给 4096（开场白 8192）；回答写到一半（接口报 length，或者 JSON、标签没收尾）就加倍再发一次。
// 会思考的模型（Gemini 3 系等）把思考也算进上限，给小了回答写一半就被截断。

const 帮填系统词 = [
  '你在帮玩家填一张角色扮演游戏的开局卡。世界是《BanG Dream!》原作世界：东京，少女乐队群像；玩家扮演其中一个普通人。',
  '按玩家已经填好的设定去想，不要和已填的内容矛盾。',
  '写具体的事和东西，口语，短；不写「温柔」「高冷」这类性格标签，不堆形容词。',
  '只输出要求的格式，不解释。',
].join('\n');

const 篇幅字数 = { 短: '150 到 250 字', 标准: '300 到 500 字', 长: '600 到 900 字' };

function 已填行(已填) {
  const 行们 = Object.keys(已填 || {}).filter(k => String(已填[k] || '').trim()).map(k => k + '：' + String(已填[k]).trim());
  return 行们.length ? 行们.join('\n') : '（还没填）';
}

function 帮填提示(求) {
  const 头 = ['【开局卡帮填】', '类型：' + 求.类, '已填：', 已填行(求.已填)];
  let 尾;
  if (求.类 === '单格') {
    const n = 求.个数 || 3;
    尾 = [
      '要填：' + 求.名 + (求.说明 ? '（' + 求.说明 + '）' : ''),
      '给 ' + n + ' 个互不相同的候选，每个不超过 ' + (求.限长 || 20) + ' 字。',
      '输出：{"候选":["…","…","…"]}',
    ];
  } else if (求.类 === '一组') {
    尾 = [
      '要填（每格一个）：' + 求.名们.join('、'),
      '每格不超过 20 字。',
      '输出：{' + 求.名们.map(k => '"' + k + '":"…"').join(',') + '}',
    ];
  } else if (求.类 === '人际') {
    const 年 = Number(求.年份) || 2020;
    const 可选 = 名单.filter(x => !x.人格 && 乐队状态(x.队, 年) === '活动中' && !(求.已选 || []).includes(x.名));
    尾 = [
      '年份：' + 年,
      '已经认识：' + ((求.已选 || []).join('、') || '无'),
      '只能从这些人里挑：' + 可选.map(x => x.名 + '（' + x.队 + '）').join('、'),
      '关系只能是：' + Object.keys(关系表).join('、'),
      '给 3 个候选，每人一种关系，再写一句两人怎么认识的，不超过 20 字。',
      '输出：{"候选":[{"名":"…","关系":"…","一句":"…"}]}',
    ];
  } else {
    尾 = [
      '人称：' + (求.人称 || '第三人称') + '；篇幅：' + (篇幅字数[求.篇幅] || 篇幅字数.标准),
    ];
    if (求.续写 && String(求.现有 || '').trim()) {
      尾.push('接着下面这段往下写，不要重复已有的内容：', String(求.现有).trim());
    }
    尾.push(
      '写小说的开头：从一个具体的时刻和动作写起，人物说的话用引号。',
      '只写日常的开场，不写色情、暴力。不写旁白总结，不升华，结尾停在一个动作或一句话上。',
      '输出：<开场白>正文</开场白>',
    );
  }
  return [
    { role: 'system', content: 帮填系统词 },
    { role: 'user', content: 头.concat(尾).join('\n') },
  ];
}

function 抠JSON(文) {
  const s = String(文 || '');
  const a = s.indexOf('{'), b = s.lastIndexOf('}');
  if (a < 0 || b <= a) return null;
  try { return JSON.parse(s.slice(a, b + 1)); } catch (e) { return null; }
}

function 解析帮填(求, 文) {
  if (求.类 === '开场白') {
    const m = /<开场白>([\s\S]*?)<\/开场白>/.exec(文);
    const 正文 = (m ? m[1] : 文).trim();
    return 正文 ? { ok: true, 文: 正文 } : { ok: false, 原因: '没写出东西' };
  }
  const o = 抠JSON(文);
  if (!o) return { ok: false, 原因: '回的不是约定的格式' };
  if (求.类 === '一组') {
    const 结果 = {};
    for (const k of 求.名们) if (o[k] && String(o[k]).trim()) 结果[k] = 截(String(o[k]).trim(), 40);
    return Object.keys(结果).length ? { ok: true, 结果 } : { ok: false, 原因: '没写出东西' };
  }
  const 列 = Array.isArray(o.候选) ? o.候选 : [];
  if (求.类 === '人际') {
    const 见 = new Set(求.已选 || []);
    const 候选 = [];
    for (const c of 列) {
      const 名 = 归名(c && c.名);
      if (!名 || 见.has(名) || !关系表[c.关系]) continue;   // 名单外的人、七种以外的关系，直接丢
      见.add(名);
      候选.push({ 名, 关系: c.关系, 一句: 截(String(c.一句 || '').trim(), 20) });
    }
    return 候选.length ? { ok: true, 候选 } : { ok: false, 原因: '挑出来的人都不在名单里' };
  }
  const 候选 = [...new Set(列.map(x => 截(String(x || '').trim(), (求.限长 || 20) + 10)).filter(Boolean))];
  return 候选.length ? { ok: true, 候选 } : { ok: false, 原因: '没写出东西' };
}

async function 帮填(求) {
  if (!接口概况().配好) return { ok: false, 原因: '帮填接口没配：⚙ 设置里填' };
  if (!求 || !['单格', '一组', '人际', '开场白'].includes(求.类)) return { ok: false, 原因: '不认识的帮填请求' };
  if (求.类 === '一组' && !(求.名们 || []).length) return { ok: false, 原因: '这一组没有空着的格子' };
  let 上限 = 求.类 === '开场白' ? 8192 : 4096;
  for (let 次 = 0; 次 < 2; 次++) {
    let r;
    try { r = await 问接口(帮填提示(求), 上限, 120); } catch (e) { return { ok: false, 原因: String(e && e.message || e) }; }
    if (!r.截断 && !被截断(求, r.文)) {
      if (!r.文.trim()) return { ok: false, 原因: '接口回了空的' };
      return 解析帮填(求, r.文);
    }
    上限 *= 2;
  }
  return { ok: false, 原因: '回答被截断：模型把字数花在思考上了，换个不思考的模型试试' };
}

// 回答写到一半：开场白只有开头标签没有结尾；JSON 有开头、解析不出来
function 被截断(求, 文) {
  const s = String(文 || '');
  if (求.类 === '开场白') return s.includes('<开场白>') && !s.includes('</开场白>');
  return s.indexOf('{') >= 0 && !抠JSON(s);
}

// ── 核心/开局.js ──
// 开局：核心做，0 层卡只点「开始」、看进度。步骤照联动规格「开局流程」。
// 为什么放在核心里：数据库导入模板时会让楼层重画，楼层里的 iframe 会被销毁；核心是常驻脚本，不受影响。
// 每一步做完记进聊天变量，页面刷新后屏上能看出停在哪；「继续」从导入表格那步重来（导入会清空表，不会写两遍初值）。

const 开局步骤 = ['检查前置', '导入表格', '写初值', '锁格子', '发出第一层'];
let 正在开局 = false;

// 细：这一步里走到哪了（写初值时是「12 / 28」行）。数据库每插一行都要存好几样东西，手机上一行几秒，不报行数像卡死了
function 报进度(步, 名, 完, 细) {
  发(事件.进度, { 步, 共: 开局步骤.length, 名, 完: !!完, 细: 细 || '' });
}

// 一键导入：玩家在「玩法」那组先导好；开始时见到同一版模板已经导过，就跳过导入
async function 一键导入() {
  if (正在开局) return { ok: false, 原因: '正在开局' };
  if (档案表有人()) return { ok: false, 原因: '这个聊天已经开过局了' };
  try {
    const r = await 导入模板();
    写局({ 模板: { 名: 模板预设名, 版: 模板版本, 于: Date.now(), 聊天: 当前聊天() } });
    发(事件.状态, 状态());
    return { ok: true, 提醒: r.提醒 };
  } catch (e) {
    报错('模板没导进去：' + (e && e.message || e));
    return { ok: false, 原因: String(e && e.message || e) };
  }
}

async function 开局(档) {
  if (正在开局) return { ok: false, 原因: '已经在开局了' };
  const 局 = 读局();
  // 上一次走到一半断了（出错、刷新），表里可能已经写了一部分：这次从导入重来，导入会把表清空
  const 断过 = !!(局.开局 && (局.开局.状态 === '进行中' || 局.开局.状态 === '出错'));
  if ((局.开局 && 局.开局.状态 === '完成') || (档案表有人() && !断过)) return { ok: false, 原因: '这个聊天已经开过局了' };
  const 缺项 = 档缺项(档 || {});
  if (缺项.length) return { ok: false, 原因: '还缺：' + 缺项.join('、') };

  const 聊天 = 当前聊天();
  正在开局 = true;
  let 步 = 0;
  const 记 = (n, 状) => { 步 = n; 写局({ 开局: { 状态: 状 || '进行中', 步: n, 档案: 档, 聊天, 于: Date.now() } }); };
  const 还在原聊天 = () => { if (当前聊天() !== 聊天) throw new Error('聊天换了，开局停在这里'); };
  try {
    记(1);
    发(事件.状态, 状态());
    报进度(1, 开局步骤[0]);
    const 缺 = 查前置().filter(x => x.项 === '数据库');
    if (缺.length) throw new Error(缺[0].说);
    报进度(1, 开局步骤[0], true);

    记(2);
    报进度(2, 开局步骤[1]);
    const 已导 = !断过 && 局.模板 && 局.模板.版 === 模板版本 && 局.模板.聊天 === 聊天;
    if (!已导) {
      await 导入模板();
      写局({ 模板: { 名: 模板预设名, 版: 模板版本, 于: Date.now(), 聊天 } });
    }
    还在原聊天();
    报进度(2, 开局步骤[1], true);

    记(3);
    报进度(3, 开局步骤[2]);
    const 初值 = 建初值(档);
    const 共行 = Object.values(初值).reduce((n, 行们) => n + 行们.length, 0);
    let 已行 = 0;
    for (const 表名 of Object.keys(初值)) {
      for (const 行 of 初值[表名]) {
        await 插行(表名, 行);
        已行 += 1;
        报进度(3, 开局步骤[2], false, 已行 + ' / ' + 共行);
      }
    }
    还在原聊天();
    报进度(3, 开局步骤[2], true);

    记(4);
    报进度(4, 开局步骤[3]);
    // 主角档案表每一格都锁上：玩家写定的设定，填表 AI 改不动；以后在面板「档案」里能一格一格解开
    if (!锁满一行('主角档案表', 0)) throw new Error('主角档案表锁不上');
    // 剧情开关整张锁上：开关只由开局和面板改，填表 AI 改不动
    if (!锁满整表('剧情开关表')) throw new Error('剧情开关表锁不上');
    报进度(4, 开局步骤[3], true);

    记(5);
    报进度(5, 开局步骤[4]);
    // 不拼 /send 命令：开场白里有半角「|」会被当成命令分隔符截断
    await createChatMessages([{ role: 'user', message: 开局原文(档) }], { refresh: 'affected' });
    记(5, '完成');
    报进度(5, 开局步骤[4], true);
    发(事件.状态, 状态());
    await triggerSlash('/trigger');
    return { ok: true };
  } catch (e) {
    const 话 = String(e && e.message || e);
    写局({ 开局: { 状态: '出错', 步, 档案: 档, 聊天, 错误: 话, 于: Date.now() } });
    报错('开局停在「' + (开局步骤[步 - 1] || '开始') + '」：' + 话, e);
    发(事件.状态, 状态());
    return { ok: false, 原因: 话 };
  } finally {
    正在开局 = false;
  }
}

// 开局中途出错或页面刷新以后，用存下的档案从头再走一遍（导入会清空这一局的表）
async function 继续开局() {
  const k = 读局().开局;
  if (!k || !k.档案) return { ok: false, 原因: '没有存下的档案' };
  if (k.状态 === '完成') return { ok: false, 原因: '已经开过局了' };
  // 1 楼已经发出去了（断在最后记账之前）：不再重来，免得发两遍
  const c = 酒馆();
  if (c && (c.chat || []).some((m, i) => i > 0 && m && m.is_user && /<开局>/.test(m.mes || ''))) {
    写局({ 开局: Object.assign({}, k, { 状态: '完成', 于: Date.now() }) });
    发(事件.状态, 状态());
    return { ok: true };
  }
  return 开局(k.档案);
}

// ── 核心/本局.js ──
// 本局：面板 ⚙ 设置里那几件事——改档案（改完锁住）、锁 / 解锁一格、备份、新的一局、重新导入表格模板。升级、恢复在 升级.js

// 改一格：锁着的先解开，写进去，再锁上（数据库的 updateCell 碰到锁着的格子会拒写）。
// 玩家改过的格子锁住，下一轮填表 AI 改不回去。
async function 改一格(表名, 行, 列名, 值) {
  if (锁状态(表名, 行)[列名]) 锁格(表名, 行, 列名, false);
  try {
    await 改格(表名, 行, 列名, 值);
  } finally {
    锁格(表名, 行, 列名, true);
  }
  return true;
}

// 一次改一行里的好几格（面板「档案」的保存）：只改真变了的格子；改完的格子锁住
async function 改一行(表名, 行, 改动) {
  const t = 表键(表名);
  if (!t || !t.行[行]) throw new Error(表名 + '没有第 ' + (行 + 1) + ' 行');
  const 改了 = [];
  for (const 列名 of Object.keys(改动 || {})) {
    const j = t.列.indexOf(列名);
    if (j < 0) continue;
    const 新 = String(改动[列名] == null ? '' : 改动[列名]).trim();
    if (新 === (t.行[行][j] || '')) continue;
    await 改一格(表名, 行, 列名, 新);
    改了.push(列名);
  }
  return 改了;
}

// 备份：这一局的表格原样导出（数据库自己的 exportTableAsJson），带上锁和开局记录（升级.js 备份内容），
// 文件名带角色卡和时间。设置里的「恢复」读的就是它
function 备份() {
  const a = 库();
  if (!a || typeof a.exportTableAsJson !== 'function') return { ok: false, 原因: '没装龙血玄黄·数据库' };
  const 卡 = 当前卡();
  const d = new Date();
  const 时 = d.getFullYear() + 补零(d.getMonth() + 1) + 补零(d.getDate()) + '_' + 补零(d.getHours()) + 补零(d.getMinutes());
  return {
    ok: true,
    文件名: 'BanG表格备份_' + ((卡 && 卡.name) || '本局') + '_' + 时 + '.json',
    文本: JSON.stringify(备份内容(), null, 1),
  };
}

// 新的一局：另开一个聊天，从 0 楼重新建档；这一局原样保留
async function 新的一局() {
  await triggerSlash('/newchat');
  return { ok: true };
}

// 重新导入：清掉这一局的表格按模板重建；有开局时的档案就把初值和档案锁一起补回去，免得主角设定跟着丢了。
// 聊天记录不动。
async function 重新导入() {
  if (正在开局) return { ok: false, 原因: '正在开局' };
  try {
    const 旧开关 = 读开关();   // 玩家在剧情页改过的开关（开着的收录、原作收尾，关掉的乐队主线），重建以后照旧
    await 导入模板();
    写局({ 模板: { 名: 模板预设名, 版: 模板版本, 于: Date.now(), 聊天: 当前聊天() } });
    const k = 读局().开局;
    if (k && k.档案 && !档缺项(k.档案).length) {
      const 初值 = 建初值(k.档案);
      for (const [名, 态] of Object.entries(旧开关)) {
        if (!/^成立线·/.test(名) && (态 === '开') !== 默认开(名)) 初值.剧情开关表.push({ 开关: 名, 类型: 名.split('·')[0], 状态: 态 });
      }
      for (const 表名 of Object.keys(初值)) for (const 行 of 初值[表名]) await 插行(表名, 行);
      锁满一行('主角档案表', 0);
      锁满整表('剧情开关表');
    }
    发(事件.状态, 状态());
    return { ok: true };
  } catch (e) {
    报错('重新导入没做完：' + (e && e.message || e));
    return { ok: false, 原因: String(e && e.message || e) };
  }
}

