const 新楼让路 = 10000;   // AI 回复落地后多久之内先不存：数据库自动填表多半是静默的，正填着时写进去会让它这一轮整轮作废

let 表格落楼 = 0;
// AI 回复落地：表格页先让 10 秒；数据库的自动更新开着的话，引擎写回这些等它把这一楼填完（快照.js 库在忙）
function 记落楼(楼) {
