  if (!Number.isInteger(i)) { try { i = 酒馆().chat.length - 1; } catch (e) { i = -1; } }
  const 限 = i >= 0 ? 自动填表等多久(i) : 0;
  if (限) { 等填表起 = 表格落楼; 等填表限 = 限; 等填表楼 = i; 等填表基 = 楼上的表(i); }
}

// 模板里这一列的说明 → {选项, 数字, 长}：「只能从这四个里选一个：A / B」「只填「是」或「否」」「七档之一：…」「只写数字」
const 列说明缓存 = {};
function 列说明(表名) {
  if (列说明缓存[表名]) return 列说明缓存[表名];
  const 出 = {};
  const t = Object.values(本卡模板).find(x => x && x.name === 表名);
  const 注 = String(((t && t.sourceData) || {}).note || '');
  注.split('\n').forEach(行 => {
    const m = /^- 列\d+:\s*(\S+)\s*-\s*(.*)$/.exec(行.trim());
    if (!m) return;
    const 名 = m[1], 字 = m[2], 记 = {};
    const 选 = /(?:只能从这.{1,3}个里选一个|只能写这.{1,3}个之一|七档之一)：([^。]+)。/.exec(字);
    if (选) 记.选项 = 选[1].split('/').map(s => s.trim()).filter(Boolean);
    const 二 = /只(?:填|能写)「([^」]+)」或「([^」]+)」/.exec(字);
    if (!记.选项 && 二) 记.选项 = [二[1], 二[2]];
    if (/只写数字/.test(字)) 记.数字 = true;
    const 限 = /不超过\s*(\d+)\s*字/.exec(字);
    if (限 && Number(限[1]) >= 30) 记.长 = true;
    出[名] = 记;
  });
  // 表的说明：第一句（「（列号为 0 基…」前面那段的头一句）
  const 头 = 注.split('（列号')[0].trim();
  出.$说明 = (/^[^。！]*[。！]?/.exec(头) || [''])[0];
  return (列说明缓存[表名] = 出);
}

function 表格只读(表名) { return 别处管[表名] || ''; }
// 引擎没装：「引擎」那几格照普通格子，能改能锁（装了、这个聊天还没接上，照样归引擎）
function 引擎装了() { try { return !!主窗().__GE__; } catch (e) { return false; } }
function 格子只读(表名, 列) {
  if (别处管[表名]) return '别处管';
  if ((引擎列[表名] || []).includes(列) && 引擎装了()) return '引擎';
  if ((只读列[表名] || []).includes(列)) return '只读';
  return '';
}

// 左边的表名列：这一局有的表，按三组排，带行数
function 表格目录() {
  const 全 = 读全部表();
  if (!全) return null;
  return 表格分组.map(([组, 名们]) => ({
    组,
    表: 名们.filter(名 => 全[名]).map(名 => ({
      名, 行数: 全[名].行.length, 只读: !!别处管[名], 去哪改: 别处管[名] || '',
      能加: 能加表.includes(名), 能删: 能删表.includes(名),
    })),
  })).filter(g => g.表.length);
}

// 一张表：列（带只读、选项）、每一行的值和锁
function 表格内容(表名) {
  const 全 = 读全部表();
  const t = 全 && 全[表名];
  if (!t) return null;
  const 说 = 列说明(表名);
  let 锁态 = {};
  try { 锁态 = 库().getTableLockState(t.键) || {}; } catch (e) { /* 锁读不到就当全开 */ }
  const 格锁 = new Set(锁态.cells || []), 行锁 = new Set(锁态.rows || []), 列锁 = new Set(锁态.cols || []);
  return {
    名: 表名, 说明: 说.$说明 || '', 只读: !!别处管[表名], 去哪改: 别处管[表名] || '',
    能加: 能加表.includes(表名), 能删: 能删表.includes(表名),
    主列: t.列.includes(主列表[表名]) ? 主列表[表名] : t.列[0], 露: (露列表[表名] || []).filter(c => t.列.includes(c)),
    前缀: t.列.includes(前缀列[表名]) ? 前缀列[表名] : '',
    列: t.列.map(名 => {
      const 记 = 说[名] || {};
      return { 名, 只读: 格子只读(表名, 名), 选项: 记.选项 || null, 数字: !!记.数字, 长: !!记.长 || 长列.includes(名) };
    }),
    行: t.行.map((r, i) => {
      const 值 = {}, 锁 = {};
      t.列.forEach((列, j) => { 值[列] = r[j] || ''; 锁[列] = 行锁.has(i) || 列锁.has(j) || 格锁.has(i + ':' + j); });
      return { _行: i, 值, 锁 };
    }),
  };
}

// 现在能不能存：数据库说了在填表、或者 AI 回复刚落地，先等一等
function 表格忙() {
  const 库忙 = 库在忙();
  if (库忙 === '填表' || 库忙 === '刚填完') return { 忙: true, 原因: '数据库在填表 · 填完再存' };
  const 剩 = 表格落楼 + 新楼让路 - Date.now();
  if (剩 > 0) return { 忙: true, 原因: '等这一楼填表 · 还要 ' + Math.ceil(剩 / 1000) + ' 秒', 剩: 剩 };
  return { 忙: false, 原因: '' };
}
function 查能写(表名, 列们) {
  const 忙 = 表格忙();
  if (忙.忙) throw new Error(忙.原因);
  if (别处管[表名]) throw new Error(表名 + '不在这里改：' + 别处管[表名]);
  const 坏 = (列们 || []).filter(c => 格子只读(表名, c));
  if (坏.length) throw new Error(坏.join('、') + '只能看，不能改');
}

// 改一行：只改真变了的格子，改完锁上（本局.js 改一行）；返回改了哪几格
async function 表格改行(表名, 行, 改动) {
  查能写(表名, Object.keys(改动 || {}));
  return 改一行(表名, 行, 改动);
}
// 加一行：主列不能空；写进去的格子锁上
async function 表格加行(表名, 对象) {
  if (!能加表.includes(表名)) throw new Error(表名 + '不能在这里加行');
  const t = 表键(表名);
  if (!t) throw new Error('这一局没有' + 表名);
  const 主 = t.列.includes(主列表[表名]) ? 主列表[表名] : t.列[0];
  const 值 = {};
  Object.keys(对象 || {}).forEach(c => { if (t.列.includes(c)) 值[c] = String(对象[c] == null ? '' : 对象[c]).trim(); });
  if (!值[主]) throw new Error(主 + '要填');
  查能写(表名, Object.keys(值).filter(c => 值[c]));
  const 行 = await 插行(表名, 值);
  Object.keys(值).forEach(c => { if (值[c]) 锁格(表名, 行, c, true); });
  return 行;
}
// 删一行：先把这一行的锁解开（数据库不让删带锁的行）
async function 表格删行(表名, 行) {
  if (!能删表.includes(表名)) throw new Error(表名 + '不能删行');
  查能写(表名, []);
  const t = 表键(表名);
  if (!t || !t.行[行]) throw new Error(表名 + '没有第 ' + (行 + 1) + ' 行');
  try { 库().lockTableRow(t.键, 行, false); } catch (e) { /* 没有行锁 */ }
  t.列.forEach((_, j) => { try { 库().lockTableCell(t.键, 行, j, false); } catch (e) { /* 没有格锁 */ } });
  if (await 自己写(() => 库().deleteRow(表名, 行 + 1)) === false) throw new Error(表名 + '第 ' + (行 + 1) + ' 行删不掉');
  return true;
}
// 锁、解一格：别处管的、引擎的格子不动
function 表格锁格(表名, 行, 列, 锁) {
  if (格子只读(表名, 列)) return false;
  return 锁格(表名, 行, 列, !!锁);
}

// ── 核心/剧情.js ──
// 剧情开关：数据库「剧情开关表」，整张锁住，面板剧情页在这里读、改。
// 表里只放和默认不一样的行：乐队主线默认开（2026-10-06 常夜灯定），第一次关掉时补一行；
// 开局写打开的成立线，收录、原作收尾默认关，第一次打开时补一行。
// 不写默认值的行是为了开局快：数据库每插一行都要把聊天、设置、世界书各存一遍，手机上一行就要几秒。
// 世界书的条件块：默认关的写一对 == 开 / != 开，乐队主线写 != 关；查不到的格子 == 为假、!= 为真（数据库 evaluateCellExpression_ACU）。

// 剧情名 = 剧情档标题去掉「主线・」「活动・」「联动・」；开关名、世界书条目名都靠它对上
const 剧情名 = 段 => String((段 && 段.title) || '').replace(/^(主线|活动|联动)・/, '');

// 开局写的成立线：开局勾了的、开局那一年还没成立的（到成立那一年照常演）打开；其余是关，不写行
function 建剧情开关(年, 勾的) {
  return 成立线乐队
    .filter(队 => (勾的 || []).includes(队) || 乐队状态(队, 年) === '未成立')
    .map(队 => ({ 开关: '成立线·' + 队, 类型: '成立线', 状态: '开' }));
}
// 收录的时间（2026-10-05 常夜灯定：没到季节开关是灰的）：从这一段那一季的起点，开到下一学年春天的起点（不含）。
// 没到这一季、过了这一学年都不能开；开着的过了这一学年自动收起。世界书的活动、联动条目不按年份包，开没开只看这一格
function 收录窗口(段) {
  const 年 = Number(段 && 段.year), 季 = String((段 && 段.season) || '');
  const 起 = (时节分界.find(x => String(x.名).charAt(0) === 季) || {}).起;
  const 春 = (时节分界.find(x => String(x.名).charAt(0) === '春') || {}).起;
  return 年 && 季 && 起 && 春 ? { 起: 年 + '-' + 起, 止: (年 + 1) + '-' + 春 } : null;
}
// 故事里的今天：全局数据表的当前时间（引擎写的「2019-04-15 周一 07:20」）取年月日；没有就回空
function 故事今天(照) {
  const m = /^(\d{4}-\d{2}-\d{2})/.exec(String(((照 || 快照() || {}).当前时间) || '').trim());
  return m ? m[1] : '';
}
// '未到' | '可以' | '已过'；还没有故事时间（没开局、引擎没写回）算可以
function 收录时机(段, 今) {
  const 窗 = 收录窗口(段);
  if (!窗 || !今) return '可以';
  return 今 < 窗.起 ? '未到' : 今 >= 窗.止 ? '已过' : '可以';
}
// 标了原作收尾的活动（讲的是乐队散了、人格换了的那几段）只认原作收尾开关，没有收录
const 收录段 = 名 => (面板静态数据.storyArchive || []).find(段 =>
  (段.kind === 'event' || 段.kind === 'crossover') && !段.收尾开关 && 名 === '收录·' + 剧情名(段)) || null;

// 面板能改的开关：活动、联动的收录，标了原作收尾的主线和活动，其余乐队主线（成立经过归成立线，不算）
function 能改的开关(名) {
  return (面板静态数据.storyArchive || []).some(段 =>
    ((段.kind === 'event' || 段.kind === 'crossover') && !段.收尾开关 && 名 === '收录·' + 剧情名(段)) || (段.收尾开关 && 名 === '原作收尾·' + 剧情名(段))
    || (段.kind === 'main' && !段.成立 && !段.收尾开关 && 名 === '主线·' + 剧情名(段)));
}
// 表里没有这一行时算开还是关：乐队主线算开，其余算关
const 默认开 = 名 => /^主线·/.test(String(名 || ''));

// {开关名: '开' | '关'}
function 开关表(t) {
  const 出 = {};
  if (!t) return 出;
  const i名 = t.列.indexOf('开关'), i态 = t.列.indexOf('状态');
  for (const r of t.行) if (r[i名]) 出[r[i名]] = r[i态] === '开' ? '开' : '关';
  return 出;
}
function 读开关() {
  const 全 = 读全部表();
  return 开关表(全 && 全['剧情开关表']);
}

// 面板改开关：改收录、原作收尾、乐队主线；成立线开局以后不能改。改一格会先解锁、写完再锁回去
async function 改开关(名, 开) {
  名 = String(名 || '');
  if (/^成立线·/.test(名)) return { ok: false, 原因: '这个开关开局以后不能改' };
  if (!能改的开关(名)) return { ok: false, 原因: '没有这个开关：' + 名 };
  if (开 && /^收录·/.test(名)) {
    const 段 = 收录段(名), 时 = 收录时机(段, 故事今天());
    if (时 === '未到') return { ok: false, 原因: 段.year + ' 年' + 段.season + '才能收录' };
    if (时 === '已过') return { ok: false, 原因: '这一段已经过去了' };
  }
  const t = 表键('剧情开关表');
  if (!t) return { ok: false, 原因: '还没开局' };
  const i名 = t.列.indexOf('开关'), i态 = t.列.indexOf('状态');
  const i = t.行.findIndex(r => r[i名] === 名);
  const 值 = 开 ? '开' : '关';
  if (i < 0 && 开 === 默认开(名)) return { ok: true, 开关: 读开关() };   // 没有这一行就是默认那样
  if (i >= 0 && t.行[i][i态] === 值) return { ok: true, 开关: 读开关() };
  // 数据库填表时拒绝外部写入：等它填完再写，最多等 90 秒
  for (let 次 = 0; ; 次++) {
    if (库在忙() && 次 < 90) { await new Promise(r => setTimeout(r, 1000)); continue; }
    try {
      if (i >= 0) await 改一格('剧情开关表', i, '状态', 值);
      else 锁满一行('剧情开关表', await 插行('剧情开关表', { 开关: 名, 类型: 名.split('·')[0], 状态: 值 }));
      break;
    } catch (e) {
      const 话 = String(e && e.message || e);
      const 在填 = /填表正在进行|拒绝外部表格写入/.test(话) || (i < 0 && 库在忙());
      if (在填 && 次 < 90) { await new Promise(r => setTimeout(r, 1000)); continue; }
      return { ok: false, 原因: 在填 ? '数据库一直在填表，等它填完再改' : 话 };
    }
  }
  发(事件.数据, { 快照: 快照(), 已存: true });
  return { ok: true, 开关: 读开关() };
}

// 时间外开着的收录收起来：表每更新一次看一次（填表、引擎写回时间都走到这里）。
// 收起来要改一格，改完又会触发一次表更新，用「对时中」挡住；数据库在填表时写不进去，下次更新再收
let 对时中 = false;
async function 收录对时(照) {
  if (对时中 || 库在忙()) return;
  const 今 = 故事今天(照);
  const t = 今 && 表键('剧情开关表');
  if (!t) return;
  const i名 = t.列.indexOf('开关'), i态 = t.列.indexOf('状态');
  const 要关 = [];
  t.行.forEach((r, i) => { if (r[i态] === '开' && /^收录·/.test(r[i名]) && 收录时机(收录段(r[i名]), 今) !== '可以') 要关.push(i); });
  if (!要关.length) return;
  对时中 = true;
  try {
    for (const i of 要关) await 改一格('剧情开关表', i, '状态', '关');
  } catch (e) {
    return;
  } finally {
    对时中 = false;
  }
  发(事件.数据, { 快照: 快照(), 已存: true });
}

// ── 核心/剧情预筛.js ──
// 剧情条目预筛：剧情档案、剧情总览三百多条，靠队名、人名触发，原文里一大半是条件块。
// 数据库到拼好提示词时才展开条件块，酒馆却按展开前的原文算世界书预算，一轮能触发几十万字，预算不够时角色条目会被挤掉。
// 酒馆扫描前（worldinfo_entries_loaded，条目是这一轮新拷的一份）先照数据库同一套规矩把这些条目的条件块算掉：
// 算完是空的拿走，不空的换成算完的字。算不了的（seed、cond、db、sql、<else>、$v: 变量）原样留给数据库。
const 预筛头 = /<if\s+(seed|cell|cond|db|sql)\s*=\s*"([^"]*)"\s*>/i;
const 预筛尾 = /<\/if>/i;
const 预筛条目 = /^剧情(总览)?：/;
const 预筛态 = { 次: 0, 拿走: 0, 换字: 0, 留着: 0, 毫秒: 0, 错: '' };

// 下面三个照数据库 1.2.4 的 compareValue_ACU、getCellValue_ACU、evaluateCellExpression_ACU 写，一处都不改规矩
function 预筛比(值, 符, 目) {
  const 数 = parseFloat(目);
  if (!isNaN(数) && isFinite(数) && typeof 值 === 'number') {
    return 符 === '>' ? 值 > 数 : 符 === '<' ? 值 < 数 : 符 === '>=' ? 值 >= 数 : 符 === '<=' ? 值 <= 数 : 符 === '==' ? 值 === 数 : 符 === '!=' ? 值 !== 数 : false;
  }
  const a = String(值), b = String(目);
  return 符 === '==' ? a === b : 符 === '!=' ? a !== b : 符 === '>' ? a > b : 符 === '<' ? a < b : 符 === '>=' ? a >= b : 符 === '<=' ? a <= b : false;
}
function 预筛找表(全, 名) {
  return Object.values(全).filter(t => t && typeof t === 'object' && t.name && t.content).find(t => String(t.name || '').trim() === 名.trim());
}
function 预筛取格(全, 表名, 行标, 列名) {
  const t = 预筛找表(全, 表名);
  if (!t || !Array.isArray(t.content) || t.content.length < 1 || !Array.isArray(t.content[0])) return null;
  const 列 = t.content[0].findIndex(x => String(x || '').trim() === 列名.trim());
  if (列 < 0) return null;
  const 标 = String(行标 || '').trim();
  const 行 = t.content.slice(1).find(r => Array.isArray(r) && r.some(x => String(x || '').trim() === 标));
  if (!行) return null;
  const 原 = 行[列], 数 = parseFloat(原);
  return { 值: !isNaN(数) && isFinite(数) ? 数 : String(原 || '') };
}
function 预筛算格(式, 全) {
  const s = String(式).replace(/＞/g, '>').replace(/＜/g, '<').replace(/＝/g, '==').replace(/≥/g, '>=').replace(/≦/g, '<=').replace(/≤/g, '<=').replace(/≠/g, '!=');
  let 符 = null, 左 = '', 右 = '';
  for (const x of ['>=', '<=', '!=', '==', '>', '<']) {
    const i = s.indexOf(x);
    if (i !== -1) { 左 = s.slice(0, i).trim(); 右 = s.slice(i + x.length).trim(); 符 = x; break; }
  }
  if (!符) return false;
  const 段 = 左.split('/').map(x => x.trim()).filter(x => x);
  if (段.length < 2 || 段.length > 3) return false;
  const t = 预筛找表(全, 段[0]);
  if (!t || !Array.isArray(t.content) || t.content.length < 1) return 符 === '!=';
  const 头 = t.content[0], 行们 = t.content.slice(1);
  if (!Array.isArray(头)) return false;
  if (段.length === 3) {
    const 格 = 预筛取格(全, 段[0], 段[1], 段[2]) || 预筛取格(全, 段[0], 段[2], 段[1]);
    return 格 ? 预筛比(格.值, 符, 右) : 符 === '!=';
  }
  let 有 = false;
  const 行 = 行们.find(r => Array.isArray(r) && String(r[0] || '').trim() === 段[1].trim());
  if (行) {
    有 = true;
    for (let i = 1; i < 行.length; i++) if (预筛比(行[i], 符, 右)) return true;
  }
  const 列 = 头.findIndex(x => String(x || '').trim() === 段[1].trim());
  if (列 !== -1) {
    有 = true;
    for (const r of 行们) if (Array.isArray(r) && 预筛比(r[列], 符, 右)) return true;
  }
  return !有 && 符 === '!=';
}
// 照数据库 parseIfBlocksInContent_ACU 的走法展开；碰到算不了的回 null
function 预筛展开(文, 全) {
  let 出 = '', i = 0;
  while (i < 文.length) {
    const m = 文.slice(i).match(预筛头);
    if (!m) { 出 += 文.slice(i); break; }
    if (m[1].toLowerCase() !== 'cell') return null;
    const 起 = i + m.index, 内起 = 起 + m[0].length;
    出 += 文.slice(i, 起);
    // 找配对的 </if>
    let 层 = 1, j = 内起, 止 = -1;
    while (j < 文.length && 层 > 0) {
      const 余 = 文.slice(j), a = 余.match(预筛头), b = 余.match(预筛尾);
      if (!b) break;
      if (a && a.index < b.index) { 层++; j += a.index + a[0].length; } else { 层--; if (层 === 0) 止 = j + b.index; j += b.index + b[0].length; }
    }
    if (止 < 0) { 出 += m[0]; i = 内起; continue; }   // 没配上：数据库也是原样留下开头这一截
    if (预筛算格(m[2], 全)) {
      const 里 = 预筛展开(文.slice(内起, 止), 全);
      if (里 === null) return null;
      出 += 里;
    }
    i = j;
  }
  return 出;
}

// 一段条目文字照现在的表格算掉条件块：卡里的小手机拼私聊提示词时借用（它读世界书原文，不经过数据库展开）。
// 算不了的（<else>、$v:、cell 以外的条件）、读不到表时回原文
function 条件块算好(文) {
  const 字 = String(文 == null ? '' : 文);
  if (!/<if\s/i.test(字)) return 字;
  try {
    const a = 库();
    if (作废 || !a || typeof a.exportTableAsJson !== 'function' || /<else>|\$v:/i.test(字)) return 字;
    const 全 = a.exportTableAsJson();
    if (!全 || typeof 全 !== 'object') return 字;
    const 出 = 预筛展开(字, 全);
    return 出 === null ? 字 : 出;
  } catch (e) {
    return 字;
  }
}

function 剧情预筛(参) {
  const 起 = Date.now();
  try {
    const a = 库();
    if (作废 || !参 || !a || typeof a.exportTableAsJson !== 'function') return;
    const 全 = a.exportTableAsJson();
    if (!全 || typeof 全 !== 'object') return;
    let 拿走 = 0, 换字 = 0, 留着 = 0;
    for (const 组 of [参.globalLore, 参.characterLore, 参.chatLore, 参.personaLore]) {
      if (!Array.isArray(组)) continue;
      for (let i = 组.length - 1; i >= 0; i--) {
        const e = 组[i], 字 = e && typeof e.content === 'string' ? e.content : '';
        if (!e || e.disable || !预筛条目.test(String(e.comment || '')) || !/<if\s+cell\s*=/i.test(字)) continue;
        if (/<else>|\$v:/i.test(字)) { 留着++; continue; }
        const 出 = 预筛展开(字, 全);
        if (出 === null) { 留着++; continue; }
        if (!出.trim()) { 组.splice(i, 1); 拿走++; } else { e.content = 出; 换字++; }
      }
    }
    Object.assign(预筛态, { 次: 预筛态.次 + 1, 拿走, 换字, 留着, 错: '' });
  } catch (e) {
    预筛态.错 = String((e && e.message) || e);   // 出错就什么都不动，交给数据库照常展开
  } finally {
    预筛态.毫秒 = Date.now() - 起;
  }
}

