// 交规则包：带上这个聊天的据点。交过的是同一份（同名、据点没变）就什么都不做；正在交的时候又要交，交完再交一次
let 正在交 = false, 再交 = false, 已交签名 = '';
function 交规则包() {
  if (作废 || !引擎规则包) return false;
  if (正在交) { 再交 = true; return true; }
  const GE = 引擎();
  if (!GE || typeof GE.usePack !== 'function') return false;
  let 加 = [];
  try { 加 = 据点节点(); } catch (e) { /* 数据库还没好：先不带据点 */ }
  const 签名 = JSON.stringify(加);
  let 现 = null;
  try { 现 = GE.packInfo(); } catch (e) { /* 老版本没有 packInfo */ }
  if (现 && 现.source === '宿主' && 现.name === 引擎规则包.名称 && 签名 === 已交签名) return true;
  const 包 = 加.length
    ? Object.assign({}, 引擎规则包, { 地图: Object.assign({}, 引擎规则包.地图, { 节点: 引擎规则包.地图.节点.concat(加) }) })
    : 引擎规则包;
  正在交 = true;
  Promise.resolve(GE.usePack(包))
    .then(信息 => {
      已交签名 = 签名;
      console.info('[BanG 总控] 规则包交给引擎了', 信息 && 信息.name, 加.length ? '据点 ' + 加.map(x => x.id).join('、') : '', 信息 && 信息.errs && 信息.errs.length ? 信息.errs : '');
      同步住处();   // 引擎账上还没有住处、据点表里有家：照表登记过去（住处.js）
    })
    .catch(e => console.warn('[BanG 总控] 规则包没交上：', e))
    .finally(() => { 正在交 = false; if (再交) { 再交 = false; 交规则包(); } });
  return true;
}
// 引擎和总控谁先起来不一定：开头两分钟每两秒看一眼，交上就停
