// ── 落钉那一处在哪：「住这里」卡上那一行和算房价的片区 ──
// 区、町取 1.5 km 内最近的剧情地点的行政名；片区（算房价）取 5 km 内最近的那个的片区，只留后半（「丰岛・池袋」→「池袋」）；
// 车站取规则包里 3 km 内最近的车站。只到町名和车站这一级，不反查门牌
function 米距(经1, 纬1, 经2, 纬2) {
  const r = Math.PI / 180, a = Math.sin((纬2 - 纬1) * r / 2) ** 2 + Math.cos(纬1 * r) * Math.cos(纬2 * r) * Math.sin((经2 - 经1) * r / 2) ** 2;
  return 2 * 6371000 * Math.asin(Math.min(1, Math.sqrt(a)));
}
function 落点信息(经度, 纬度) {
  经度 = +经度; 纬度 = +纬度;
  if (!Number.isFinite(经度) || !Number.isFinite(纬度)) return null;
  let 近 = null, 近距 = Infinity;
  for (const p of 地图点位()) { const d = 米距(经度, 纬度, p[0], p[1]); if (d < 近距) { 近距 = d; 近 = p; } }
  const 行政 = (近 && 近距 <= 1500 && ((面板静态数据 && 面板静态数据.mapAdminPaths) || [])[近[9]]) || [];
  const 站们 = (引擎规则包 && 引擎规则包.地图 && 引擎规则包.地图.铁道 && 引擎规则包.地图.铁道.车站) || [];
  let 站 = null, 站距 = Infinity;
  for (const s of 站们) { const d = 米距(经度, 纬度, s.坐标[0], s.坐标[1]); if (d < 站距) { 站距 = d; 站 = s; } }
  return {
    区: 行政[1] || '', 町: 行政[2] || '',
    片区: 近 && 近距 <= 5000 ? String(近[3] || '').split(/[・·]/).pop().trim() : '',
    车站: 站 && 站距 <= 3000 ? (站.节点 || 站.名 + '站') : '',
  };
}

// 旧接口 moveIn：按坐标落到最近的住宅区（没给坐标按片区对应的那一处），交给住处模块
