// ── 照引擎的账写表 ──
const 来历名 = { 开局: '开局', 租: '租下', 买: '买下', 借住: '借住' };
function 据点行内容(类型, h) {
  return {
    类型, 地点: h.区 || h.门牌 || h.节点 || '', 片区: 片区短(h.片区),
    经度: h.坐标 ? String(h.坐标[0]) : '', 纬度: h.坐标 ? String(h.坐标[1]) : '',
    门牌: h.门牌 || '', 来历: 来历名[h.方式] || h.方式 || '',
    价格: h.方式 === '买' ? String(h.价 || '') : h.方式 === '租' ? String(h.月租 || '') : '', 日期: h.起 || '',
  };
}
// 一行一次写完：数据库的 updateRow 一次写好几格（一格一格写每格都要存一遍聊天，很慢）；锁也一次设好（每改一格的锁也要存一遍）
function 行锁(表名, 行, 锁) {
  const t = 表键(表名), a = 库();
  if (!t) return false;
  if (锁) return !!a.setTableLockState(t.键, { cells: t.列.map((_, j) => 行 + ':' + j) }, { merge: true });
  const st = a.getTableLockState(t.键) || {}, 前 = 行 + ':';
  return !!a.setTableLockState(t.键, { rows: (st.rows || []).filter(r => r !== 行), cols: st.cols || [], cells: (st.cells || []).filter(c => !String(c).startsWith(前)) }, { merge: false });
}
async function 写整行(表名, 行, 改动) {
  const t = 表键(表名);
  if (!t || !t.行[行]) throw new Error(表名 + '没有第 ' + (行 + 1) + ' 行');
  const 变 = {};
  for (const 列名 of Object.keys(改动 || {})) {
    const j = t.列.indexOf(列名), 新 = String(改动[列名] == null ? '' : 改动[列名]).trim();
    if (j >= 0 && 新 !== (t.行[行][j] || '')) 变[列名] = 新;
  }
  if (!Object.keys(变).length) return false;
  行锁(表名, 行, false);
  try {
    if (await 库().updateRow(表名, 行 + 1, 变) === false) throw new Error(表名 + '第 ' + (行 + 1) + ' 行写不进去');
  } finally {
    行锁(表名, 行, true);
  }
  return true;
}
async function 删整行(表名, 行) {
  行锁(表名, 行, false);
  if (await 自己写(() => 库().deleteRow(表名, 行 + 1)) === false) throw new Error(表名 + '第 ' + (行 + 1) + ' 行删不掉');
}

// 一次写完再写下一次：连着办几件事时，每次都照办完那一刻的账整张对一遍（没变的行不碰），调用的人等到自己那一次写完
let 写表链 = Promise.resolve();
function 照账写据点() {
  写表链 = 写表链.catch(() => {}).then(写一遍据点);
  return 写表链;
}
async function 写一遍据点() {
  const v = 房产();
  // 引擎账上一处房子都没有（还没登记、删楼删到登记以前）：不动表，等照表登记
  if (!v || !表键('据点表') || (!v.住 && !v.房.length)) return false;
  const 要 = [];
  if (v.住) 要.push(据点行内容('家', v.住));
  for (const h of v.房) if (!h.住着 && h.方式 === '买') 要.push(据点行内容('房产', h));
  const 旧 = 据点行们().filter(r => r.类型 === '家' || r.类型 === '房产');
  // 一行对一行改；多出来的从后往前删（行号不乱），少的插进去，写完锁满
  for (let i = 0; i < Math.min(旧.length, 要.length); i++) {
    await 写整行('据点表', 旧[i]._行, 要[i]);
  }
  for (const r of 旧.slice(要.length).sort((a, b) => b._行 - a._行)) await 删整行('据点表', r._行);
  for (const x of 要.slice(旧.length)) { const i = await 插行('据点表', x); 行锁('据点表', i, true); }
  // 主角档案表·住所：片区 · 门牌（没写门牌写住宅区）
  const 住所 = v.住 ? [片区短(v.住.片区), v.住.门牌 || v.住.区 || v.住.住处].filter(Boolean).join(' · ') : '';
  const 档 = 表键('主角档案表');
  if (住所 && 档 && 档.行[0] && 行对象(档, 0).住所 !== 住所) await 改一格('主角档案表', 0, '住所', 住所);
  return true;
}

// ── 交给引擎一件事 ──
async function 住处事项(事项) {
  const GE = 引擎();
  if (!GE || typeof GE.estate !== 'function') return { ok: false, 原因: '没装游戏引擎，住处记不上' };
  if (库在忙()) return { ok: false, 原因: '数据库在填表，等它填完' };
  let 记 = null;
  try { 记 = GE.applyEvents({ house: [事项] }, { path: 'host' }); } catch (e) { return { ok: false, 原因: '引擎没接住：' + ((e && e.message) || e) }; }
  const 果 = ((记 && 记.results) || []).filter(x => x.项 === '住处' && (x.来源 === 'host' || x.来源 === undefined) && x.动作 === 事项.动作).pop();
  if (!果 || !/^成立/.test(果.状态 || '')) {
    return { ok: false, 原因: 果 ? String(果.状态 || '').replace(/^未结算：/, '') : '引擎没有回音', 还差: 果 && 果.还差, 要付: 果 && 果.要付 };
  }
  // 账记上了就回话：表要一格一格写，慢，放在后面照账写；写完再让引擎、面板照新表走一遍（家的标记、交给引擎的「家」）。
  // 面板先照引擎的账画（数据事件），不等表
  后台写表(() => 照账写据点());
  发(事件.数据, { 快照: 快照(), 已存: true });
  return { ok: true, 果 };
}
// 写表排进同一条链：照账写据点、钥匙这类都在后面一件一件写，写完 据点换了()
let 后台链 = Promise.resolve();
function 后台写表(做) {
  后台链 = 后台链.catch(() => {}).then(做).then(() => 据点换了()).catch(e => console.warn('[BanG 总控] 住处的表没写完：', e));
  return 后台链;
}

// 同住的人：现在一起住的照原来确认过的带过去，新来的（邀请过、答应了的）按这次勾的「家里同意」。
// 没给名单就不写，引擎默认现在同住的人都跟着搬（住不下就不成立）
function 同住名单(名们, 家里同意) {
  if (名们 === undefined || 名们 === null) return undefined;
  const 现 = ((房产() || {}).住 || {}).同住 || [];
  return [].concat(名们 || []).map(名 => {
    const 旧 = 现.find(m => m.名 === 名);
    return 旧 ? { ...旧 } : { 名, 未成年: 名单里有(名), 家里同意: !!家里同意 };
  });
}

// ── 租、买：住这里卡的确认 ──
// 选：{ 区, 户型, 门牌, 坐标: [经, 纬]（图钉才有）, 设施: [], 同住: [名], 家里同意 }
async function 搬进(选, 方式) {
  选 = 选 || {};
  const 区 = 住宅区(选.区);
  if (!区) return { ok: false, 原因: '没有这个住宅区' };
  const 事项 = { 动作: 方式, 区: 区.id, 户型: 选.户型, 门牌: String(选.门牌 || '').trim(), 设施: [].concat(选.设施 || []) };
  const 同住 = 同住名单(选.同住, 选.家里同意);
  if (同住) 事项.同住 = 同住;
  if (Array.isArray(选.坐标) && 选.坐标.length === 2) 事项.坐标 = 选.坐标.map(Number);
  const r = await 住处事项(事项);
  if (!r.ok) return r;
  const 住着的人 = (((房产() || {}).住 || {}).同住 || []).map(m => m.名);
  清邀请(住着的人);
  // 钥匙：物品表里有家的钥匙就改说明，没有就加一把（排在写表后面，记不上不挡住处）
  const 说明 = [区.id, 事项.门牌].filter(Boolean).join(' ');
  后台写表(async () => {
    const t = 表键('物品表');
    const i = t ? t.行.findIndex((_, k) => /^(新家的|家的)钥匙$/.test(String(行对象(t, k).物品 || '').trim())) : -1;
    if (i >= 0) await 写整行('物品表', i, { 说明, 来源: 方式 === '买' ? '购买' : '借用', 借用对象: 方式 === '买' ? '无' : '房东' });
    else await 插行('物品表', { 物品: '家的钥匙', 类别: '常备', 数量: '1', 位置: '随身', 来源: 方式 === '买' ? '购买' : '借用', 借用对象: 方式 === '买' ? '无' : '房东', 说明 });
  });
  const 和谁 = 住着的人.length ? '，和' + 住着的人.map(去艺名).join('、') + '一起住' : '';
  const 句 = '在' + 区.id + (方式 === '买' ? '买下了' : '租下了') + (事项.门牌 || 选.户型) + 和谁 + '。';
  try { await triggerSlash('/setinput ' + 句.replace(/\|/g, '｜')); } catch (e) { /* 输入框填不进去不挡结算 */ }
  return { ...r, 句 };
}

// ── 我的住处上的钮 ──
const 搬回 = 房 => 住处事项({ 动作: '搬回', 房 });
const 退租 = 房 => 住处事项({ 动作: '退租', 房 });
const 卖房 = 房 => 住处事项({ 动作: '卖', 房 });
