  const GE = 引擎();
  let 节点 = null;
  try { const w = GE && typeof GE.locate === 'function' ? GE.locate(String(家.名 || '')) : null; 节点 = w && w.id ? w.id : null; } catch (e) { 节点 = null; }
  const 事项 = { 动作: '借住', 谁, 未成年: 名单里有(谁), 家里同意: !!家里同意, 门牌: String(家.名 || '').trim() };
