// ── 邀请同住：填输入框，记在这一局 ──
const 邀请方式 = ['她搬进来', '一起租', '住进她家'];
function 读邀请() { return (读局().邀请 || []).filter(x => x && x.谁 && 邀请方式.includes(x.方式)); }
function 清邀请(名们) {
  const 去 = new Set([].concat(名们 || []));
  const 旧 = 读邀请();
  if (旧.some(x => 去.has(x.谁))) 写局({ 邀请: 旧.filter(x => !去.has(x.谁)) });
}
async function 邀请同住(谁, 方式) {
  谁 = String(谁 || '').trim();
  if (!谁 || !邀请方式.includes(方式)) return { ok: false, 原因: '缺人或方式' };
  const 名 = 去艺名(谁), 住 = (房产() || {}).住;
  const 家里 = 名单里有(谁) ? '，先问过她家里' : '';
  const 句 = 方式 === '她搬进来' ? '邀请' + 名 + '搬来' + (住 ? (住.门牌 || 住.区 || '我家') : '我家') + '一起住' + 家里 + '。'
    : 方式 === '一起租' ? '邀请' + 名 + '一起租房子住' + 家里 + '。'
    : '想借住在' + 名 + '家，先问问她' + (家里 ? '和她家里' : '') + '。';
  try { await triggerSlash('/setinput ' + 句.replace(/\|/g, '｜')); } catch (e) { return { ok: false, 原因: '输入框填不进去' }; }
  写局({ 邀请: 读邀请().filter(x => x.谁 !== 谁).concat([{ 谁, 方式, 时: Date.now() }]) });
  发(事件.数据, { 快照: 快照(), 已存: true });
  return { ok: true, 句 };
}
function 邀请作废(谁) { 清邀请([谁]); 发(事件.数据, { 快照: 快照(), 已存: true }); return { ok: true }; }

// ── 给面板的一览：引擎的账 + 到学校、工作的通勤 + 邀请 ──
let 通勤缓存 = null;
function 通勤(到) {
  const GE = 引擎();
  if (!GE || typeof GE.estateCommute !== 'function' || !到) return null;
  const t = ((GE.getState() || {}).clock || {}).t;
  const 键 = 到 + '|' + (Number.isFinite(t) ? Math.floor(t / 1440) : '');   // 按当天早上 8 点算，同一天算一次
  if (通勤缓存 && 通勤缓存.键 === 键) return 通勤缓存.值;
  let 值 = null;
  try { 值 = GE.estateCommute(到); } catch (e) { 值 = null; }
  通勤缓存 = { 键, 值 };
  return 值;
}
function 住处一览() {
  const v = 房产();
  if (!v) return null;
  const 据 = 据点行们();
  const 学校 = 据.find(r => r.类型 === '学校'), 工作 = 据.find(r => r.类型 === '工作');
  const 算 = r => (r && r.地点 ? { 到: r.地点, 每处: 通勤(r.地点) || {} } : null);
  v.通勤 = { 学校: 算(学校), 工作: 学校 && 工作 && 学校.地点 === 工作.地点 ? null : 算(工作) };
  v.邀请 = 读邀请();
  v.邀请.forEach(x => { x.未成年 = 名单里有(x.谁); });
  return v;
}

// ── 旧局、新开局：引擎账上还没有住处、据点表里有家，就照表登记过去 ──
// 开局的家不留片区正中那一处：按片区落到对应的住宅区；买的、租的留原来的位置，记到最近的住宅区名下
function 旧行转登记(r) {
  const 经 = parseFloat(r.经度), 纬 = parseFloat(r.纬度), 有坐标 = Number.isFinite(经) && Number.isFinite(纬);
  const 方式 = r.类型 === '房产' || r.来历 === '买下' ? '买' : r.来历 === '租下' ? '租' : r.来历 === '借住' ? '借住' : '开局';
  const 价 = parseFloat(String(r.价格 || '').replace(/[^\d.]/g, '')) || 0;
  let 区 = null, 坐标 = 有坐标 ? [经, 纬] : null;
  if (方式 === '开局') {
    区 = 住宅区(r.地点) || 开局住宅区(r.片区) || (有坐标 ? 最近住宅区(经, 纬) : null);
    if (区 && !住宅区(r.地点)) 坐标 = 区.坐标.slice();
  } else if (方式 !== '借住') 区 = 住宅区(r.地点) || (有坐标 ? 最近住宅区(经, 纬) : null);
  const x = { 动作: '登记', 方式, 坐标, 门牌: String(r.门牌 || '').trim(), 当前: r.类型 === '家' };
  if (区) x.区 = 区.id;
  if (方式 === '买') x.价 = 价;
  if (方式 === '租') { x.月租 = 价; x.押金 = 价; }
  return x;
}
let 同步中 = false;
async function 同步住处() {
  if (同步中 || 库在忙() || 作废) return false;
  const GE = 引擎(), v = 房产();
  if (!GE || !v || v.住 || v.房.length) return false;
  const 行们 = 据点行们().filter(r => r.类型 === '家' || r.类型 === '房产');
  if (!行们.length) return false;
  同步中 = true;
  try {
    const 事项们 = 行们.sort((a, b) => (a.类型 === '家' ? 1 : 0) - (b.类型 === '家' ? 1 : 0)).map(旧行转登记);
    GE.applyEvents({ house: 事项们 }, { path: 'host' });
    发(事件.数据, { 快照: 快照(), 已存: true });
    await 后台写表(() => 照账写据点());
    return true;
  } catch (e) {
    console.warn('[BanG 总控] 住处没登记上：', e);
    return false;
  } finally {
    同步中 = false;
  }
}

// ── 核心/存档.js ──
// 角色存档：写好的主角存在这台浏览器（主窗口的 IndexedDB），换个聊天一键读入，不用再填一遍。
// 只存这个人自己的事：基本信息、外貌、身世、性格、身份、住所、技能、物品；
// 时间、地点、成立线、人际、第一层每一局都不一样，不存（人际跟年份走，换一年可能有人还没登场）。
// 和帮填接口一样不进聊天、不进卡：导出卡、分享聊天都带不走；换电脑用 0 层卡的「导出成文件」带过去再存。
// 以前存在 localStorage：那里一个网址合用 5 MB，酒馆和别的插件把它占满时就存不进（QuotaExceededError）。
// 读的时候见到 localStorage 里还有旧的那份，并进 IndexedDB（同名的留时间新的），并好删掉旧的。
// 浏览器不给 IndexedDB（有的隐私模式）才退回 localStorage。接口都是异步的
const 存档键 = 'BanG.角色存档';
const 存档上限 = 20;
const 存档项 = ['基本', '外貌', '住所', '身份', '身世', '性格', '技能', '物品'];
const 存档库名 = 'BanG', 存档表 = '角色存档', 存档条 = '列';

let 存档库 = null;   // 打开着的库（Promise）；打不开时清回 null，下次再试
function 开存档库() {
  if (存档库) return 存档库;
  存档库 = new Promise((好, 坏) => {
    let 源 = null;
    try { 源 = 主窗().indexedDB; } catch (e) { 源 = null; }
    if (!源) return 坏(new Error('浏览器不给 IndexedDB'));
    const 请 = 源.open(存档库名, 1);
    请.onupgradeneeded = () => { const db = 请.result; if (!db.objectStoreNames.contains(存档表)) db.createObjectStore(存档表); };
    请.onsuccess = () => 好(请.result);
    请.onerror = () => 坏(请.error || new Error('IndexedDB 打不开'));
    请.onblocked = () => 坏(new Error('IndexedDB 被别的页面占着'));
  });
  存档库.catch(() => { 存档库 = null; });
  return 存档库;
}
// 一次读写：动(表) 回一个请求，它的结果就是这次的结果
async function 存档办(模式, 动) {
  const db = await 开存档库();
  return new Promise((好, 坏) => {
    const 事 = db.transaction(存档表, 模式);
    const 请 = 动(事.objectStore(存档表));
    事.oncomplete = () => 好(请 ? 请.result : undefined);
    事.onerror = 事.onabort = () => 坏(事.error || new Error('IndexedDB 没写成'));
  });
}

const 整理存档 = 列 => (Array.isArray(列) ? 列 : []).filter(x => x && typeof x.名 === 'string' && x.名 && x.档 && typeof x.档 === 'object');
function 读旧存档() {
  try { return 整理存档(JSON.parse(主窗().localStorage.getItem(存档键) || '[]')); } catch (e) { return []; }
}
function 有旧存档() {
  try { return 主窗().localStorage.getItem(存档键) !== null; } catch (e) { return false; }
}
// 同名的留时间新的，新的在前
function 并存档(甲, 乙) {
  const 按名 = new Map();
  for (const x of 甲.concat(乙)) {
    const 有 = 按名.get(x.名);
    if (!有 || String(x.时间 || '') > String(有.时间 || '')) 按名.set(x.名, x);
  }
  return [...按名.values()].sort((a, b) => String(b.时间 || '').localeCompare(String(a.时间 || ''))).slice(0, 存档上限);
}

async function 读存档() {
  let 列;
  try {
    列 = 整理存档(await 存档办('readonly', 表 => 表.get(存档条)));
  } catch (e) {
    return 读旧存档();
  }
  if (有旧存档()) {
    const 并 = 并存档(列, 读旧存档());
    try {
      await 存档办('readwrite', 表 => 表.put(并, 存档条));
      try { 主窗().localStorage.removeItem(存档键); } catch (e) { /* 删不掉下次再并一次，同名的不会重复 */ }
      列 = 并;
    } catch (e) { /* 并不进去就先照 IndexedDB 里的用，旧的那份留着 */ }
  }
  return 列;
}
async function 写存档(列) {
  try {
    await 存档办('readwrite', 表 => 表.put(列, 存档条));
    return;
  } catch (e) {
    if (开存档库失败(e)) {
      try { 主窗().localStorage.setItem(存档键, JSON.stringify(列)); return; } catch (e2) { throw new Error('浏览器不让存：' + (e2 && e2.message || e2)); }
    }
    throw new Error('浏览器不让存：' + (e && e.message || e));
  }
}
const 开存档库失败 = e => /IndexedDB/.test(String(e && e.message || e));

// 浮层里那一行小字：「学生 · 羽丘 · 高一 · 吉他（能合奏）」
function 存档说(份) {
  const j = 份.技能 || {};
  const 乐 = !j.乐器 ? '' : 乐器串(j);
  return [档身份短(份), 乐].filter(Boolean).join(' · ');
}
async function 存档们() {
  return (await 读存档()).map(x => ({ 名: x.名, 罗马音: String((x.档.基本 || {}).罗马音 || ''), 说: 存档说(x.档), 时间: x.时间 || '' }));
}
// 开局以后存：开局时交来的那份档，基本信息、外貌、身世、性格换成主角档案表里现在的（面板 ⚙ 档案里改过的也算）
function 这局的角色() {
  const k = 读局().开局;
  const 起 = k && k.档案 ? JSON.parse(JSON.stringify(k.档案)) : null;
  if (!起) return null;
  const a = 快照().主角.档案 || {};
  起.基本 = 起.基本 || {};
  for (const 列 of ['姓名', '罗马音', '称呼', '性别', '年龄']) if (String(a[列] || '').trim()) 起.基本[列] = String(a[列]).trim();
  for (const [组, 列们] of [['外貌', 资料组.外貌], ['身世', 资料组.身世], ['性格', 资料组.性格]]) {
    起[组] = 起[组] || {};
    for (const 列 of 列们) if (a[列] !== undefined) 起[组][列] = String(a[列] || '');
  }
  return 起;
}
// 档不给就存这一局的主角。同名的覆盖（屏上已经让玩家按了第二次）
async function 存角色(档) {
  const 源 = 档 || 这局的角色();
  if (!源) return { ok: false, 原因: '还没有能存的档案' };
  const 份 = {};
  for (const k of 存档项) if (源[k] !== undefined) 份[k] = JSON.parse(JSON.stringify(源[k]));
  const 名 = String((份.基本 || {}).姓名 || '').trim();
  if (!名) return { ok: false, 原因: '姓名空着，存不了' };
  const 列 = await 读存档();
  const 旧 = 列.findIndex(x => x.名 === 名);
  if (旧 >= 0) 列.splice(旧, 1);
  else if (列.length >= 存档上限) return { ok: false, 原因: '存满 ' + 存档上限 + ' 个了，先删一个' };
  列.unshift({ 名, 档: 份, 时间: new Date().toISOString() });
  await 写存档(列);
  return { ok: true, 名, 覆盖: 旧 >= 0 };
}
async function 取角色(名) {
  const x = (await 读存档()).find(x => x.名 === 名);
  return x ? JSON.parse(JSON.stringify(x.档)) : null;
}
async function 删角色(名) {
  const 列 = await 读存档();
  const 剩 = 列.filter(x => x.名 !== 名);
  if (剩.length === 列.length) return { ok: false, 原因: '没有这个存档' };
  await 写存档(剩);
  return { ok: true };
}

// ── 核心/升级.js ──
// 升级与恢复：换了新版卡、表格模板变了，这一局的数据照表名、列名搬进新模板，进度不丢；备份文件写回来也走同一条路。
// 搬法：先导入本卡模板（这个聊天的模板换成新的、表清空），再把搬好的整份表用数据库的 importTableAsJson 一次写回，
// 锁住的格子按表名、行、列名照锁。新加的列填默认值。
// 表键照数据库导入以后的：它按表名给每张表重新起键（sheet_quan_ju_shu_ju_biao 这种），和模板文件里的键不一样，
// 写回时用了模板文件的键，当下看着对，下一轮填表就认不出这些表、整局表变空（测试酒馆实测）。
// 本卡模板里没有的表（玩家自己加的）不搬：搬进去的表这个聊天的模板里没有，同样会让填表认不出；它们留在升级前的备份里。
// 升级前在这台浏览器（IndexedDB，和角色存档同一个库）留一份备份，恢复里能选回来。

const 本局备份条 = '本局备份';
const 本局备份上限 = 5;
// 新加的列：开局时的初值（初值.js）不是空的，搬的时候照填
const 新列默认 = { 主角现况表: { 体力: '100' } };
// 剧情档换过稿：剧情开关表里旧段名的那几行换成新段名（工具/转剧情段.py 出的对照，只收开关同一种的）
const 剧情改名 = 面板静态数据.剧情改名 || {};
function 剧情开关有旧名() {
  try { return Object.keys(读开关()).some(名 => Object.prototype.hasOwnProperty.call(剧情改名, 名)); } catch (e) { return false; }
}
let 正在搬表 = false;

// 表的提示词（填表 AI 读的说明、何时插改删）：列没变、只改了说明的版本也要升级
const 提示词指纹 = sd => JSON.stringify(['note', 'initNode', 'insertNode', 'updateNode', 'deleteNode'].map(k => String((sd || {})[k] || '')));

// 这一局的表和本卡模板对不上的表名：缺表、列不一样、提示词不一样
function 结构差() {
  let 全;
  try { 全 = 库().exportTableAsJson() || {}; } catch (e) { return []; }
  const 现 = {};
  for (const k of Object.keys(全)) { const t = 全[k]; if (k.startsWith('sheet_') && t && t.name && Array.isArray(t.content)) 现[t.name] = t; }
  const 差 = [];
  for (const k of Object.keys(本卡模板)) {
    const t = 本卡模板[k], 有 = t && t.name ? 现[t.name] : null;
    if (!k.startsWith('sheet_') || !t || !t.name) continue;
    if (!有 || (有.content[0] || []).slice(1).join('|') !== t.content[0].slice(1).join('|') || 提示词指纹(有.sourceData) !== 提示词指纹(t.sourceData)) 差.push(t.name);
  }
  return 差;
}

// 旧版：开过局，表和本卡模板对不上，或者局里记的模板指纹不是这一版，或者剧情开关还是旧段名。
// 两样都要看：1.2.4 打开旧局时表照旧局自己的模板显示，看表就认得出；更新一点的数据库会照全局那份模板预设显示，
// 换过新卡、别处导入过新模板以后，旧局的表看着已经是新的，只剩局里记的指纹还是旧的
function 本局旧版() {
  if (正在搬表 || !有库() || !档案表有人()) return false;
  const 局 = 读局();
  if (局.模板 && 局.模板.版 && 局.模板.版 !== 模板版本) return true;
  return 结构差().length > 0 || 剧情开关有旧名();
}

// 每张表的锁：{表名: {rows, cols, cells}}（cells 是「行:列」，列号是数据列从 0 数）
function 读全部锁(原) {
  const a = 库(), 出 = {};
  for (const 键 of Object.keys(原 || {})) {
    const t = 原[键];
    if (!t || !t.name || !键.startsWith('sheet_')) continue;
    try { const s = a.getTableLockState(键); if (s) 出[t.name] = { rows: s.rows || [], cols: s.cols || [], cells: s.cells || [] }; } catch (e) { /* 读不到就不搬锁 */ }
  }
  return 出;
}

// 旧数据（数据库 exportTableAsJson 的原样）→ 本卡模板的结构。锁的列号按列名换
// 底：导入本卡模板以后数据库里那份空表（数据库起的键、表头）；没给就用本卡模板
function 搬进模板(旧, 旧锁, 底) {
  旧 = 旧 || {};
  旧锁 = 旧锁 || {};
  const 新 = 深拷(底 && Object.keys(底).some(k => k.startsWith('sheet_')) ? 底 : 本卡模板);
  const 旧按名 = {};
  for (const 键 of Object.keys(旧)) {
    const t = 旧[键];
    if (键.startsWith('sheet_') && t && t.name && Array.isArray(t.content)) 旧按名[t.name] = { 键, t };
  }
  const 报 = { 表: 0, 行: 0, 新列: [], 丢列: [], 新表: [], 没搬: [], 改名: 0 };
  const 锁 = {};
  const 用了 = new Set();
  for (const 键 of Object.keys(新)) {
    const t = 新[键];
    if (!键.startsWith('sheet_') || !t || !t.name) continue;
    const 有 = 旧按名[t.name];
    if (!有) { 报.新表.push(t.name); continue; }
    用了.add(t.name);
    const 新列 = t.content[0].slice(1).map(String), 旧列 = (有.t.content[0] || []).slice(1).map(String);
    const 默认 = 新列默认[t.name] || {};
    新列.forEach(c => { if (!旧列.includes(c)) 报.新列.push(t.name + '·' + c); });
    旧列.forEach(c => { if (!新列.includes(c)) 报.丢列.push(t.name + '·' + c); });
    const 行们 = 有.t.content.slice(1).filter(Array.isArray).map(r => [r[0] == null ? null : r[0]].concat(新列.map(c => {
      const j = 旧列.indexOf(c);
      if (j < 0) return 默认[c] !== undefined ? 默认[c] : '';
      const v = r[j + 1];
      return v == null ? '' : v;
    })));
    if (t.name === '剧情开关表') {
      const j = 新列.indexOf('开关') + 1;
      const 有了 = new Set(行们.map(r => String(r[j])));
      行们.forEach(r => {
        const 新名 = 剧情改名[String(r[j])];
        if (j > 0 && 新名 && !有了.has(新名)) { 有了.add(新名); r[j] = 新名; 报.改名 += 1; }
      });
    }
    // 行号：旧行照搬；空的、重复的按最大的往上分
    const 见过 = new Set();
    let 大 = 0;
    行们.forEach(r => { const n = Number(r[0]); if (Number.isSafeInteger(n) && n > 大) 大 = n; });
    行们.forEach(r => {
      const id = r[0] == null ? '' : String(r[0]).trim();
      if (!id || 见过.has(id)) r[0] = String(++大); else r[0] = id;
      见过.add(r[0]);
    });
    t.content = [t.content[0]].concat(行们);
    报.表 += 1;
    报.行 += 行们.length;
    const 旧态 = 旧锁[t.name];
    if (旧态) {
      const 换列 = j => 新列.indexOf(旧列[j]);
      const cols = (旧态.cols || []).map(换列).filter(j => j >= 0);
      const cells = (旧态.cells || []).map(x => {
        const m = /^(\d+):(\d+)$/.exec(String(x));
        if (!m) return null;
        const j = 换列(Number(m[2]));
        return j >= 0 ? m[1] + ':' + j : null;
      }).filter(Boolean);
      锁[键] = { rows: (旧态.rows || []).slice(), cols, cells };
    }
  }
  for (const 名 of Object.keys(旧按名)) if (!用了.has(名)) 报.没搬.push(名);
  return { 数据: 新, 锁, 报 };
}

// 搬好的表写进这个聊天：导入本卡模板（清空），整份写回，锁照上
async function 写回表格(旧, 旧锁) {
  const a = 库();
  if (!有库()) throw new Error('没装龙血玄黄·数据库');
  if (typeof a.importTableAsJson !== 'function') throw new Error('数据库太旧，没有整表写回的接口');
  正在搬表 = true;
  let 搬;
  try {
    await 导入模板();
    搬 = 搬进模板(旧, 旧锁, 深拷(a.exportTableAsJson() || {}));
    const ok = await 自己写(() => a.importTableAsJson(JSON.stringify(搬.数据)));
    if (!ok) throw new Error('数据库没收下搬好的表格 · 设置 → 本局 → 恢复，选「升级前」那份再试');
    写局({ 模板: { 名: 模板预设名, 版: 模板版本, 于: Date.now(), 聊天: 当前聊天() } });
    // 指纹马上存进聊天：聊天变量隔一会儿才落盘，这中间重载会回到旧指纹，又被认成旧版
    try { const c = 酒馆(); if (c && typeof c.saveMetadata === 'function') await c.saveMetadata(); } catch (e) { /* 存不上下次存档时再存 */ }
    for (const [键, 态] of Object.entries(搬.锁)) {
      if (!(态.rows.length || 态.cols.length || 态.cells.length)) continue;
      if (!a.setTableLockState(键, 态, { merge: false })) throw new Error('锁没搬过去');
    }
  } finally {
    正在搬表 = false;
  }
  发(事件.状态, 状态());
  return 搬.报;
}

// ---- 这台浏览器里的本局备份（升级前自动存一份） ----
async function 本局备份们(聊天) {
  let 列 = [];
  try { 列 = await 存档办('readonly', 表 => 表.get(本局备份条)); } catch (e) { return []; }
  列 = Array.isArray(列) ? 列 : [];
  return 聊天 ? 列.filter(x => x.聊天 === 聊天) : 列;
}
async function 存本局备份(档, 原因) {
  const 条 = { id: Date.now().toString(36), 聊天: 档.聊天, 卡: 档.卡 || '', 时间: 档.时间, 原因, 文本: JSON.stringify(档) };
  const 列 = [条].concat(await 本局备份们()).slice(0, 本局备份上限);
  await 存档办('readwrite', 表 => 表.put(列, 本局备份条));
  return 条.id;
}

// 备份文件的内容（本局.js 的「备份」、升级前的自动备份都用它）
function 备份内容() {
  const a = 库();
  const 表格 = 深拷(a.exportTableAsJson() || {});
  const 局 = 读局();
  const 卡 = 当前卡();
  return {
    类: 'BanG 表格备份', 格式: 2, 版本, 模板版: (局.模板 && 局.模板.版) || '', 卡: (卡 && 卡.name) || '',
    聊天: 当前聊天(), 时间: new Date().toISOString(),
    表格, 锁: 读全部锁(表格), 局: { 开局: 局.开局 || null, 须知已读: !!局.须知已读 },
  };
}

function 解析备份(文本) {
  let 档;
  try { 档 = typeof 文本 === 'string' ? JSON.parse(文本) : 文本; } catch (e) { throw new Error('不是备份文件：读不出 JSON'); }
  if (!档 || 档.类 !== 'BanG 表格备份' || !档.表格 || !Object.keys(档.表格).some(k => k.startsWith('sheet_'))) throw new Error('不是这张卡的表格备份');
  return 档;
}
function 备份概况(档) {
  const 表们 = Object.keys(档.表格).filter(k => k.startsWith('sheet_')).map(k => 档.表格[k]).filter(t => t && Array.isArray(t.content));
  return {
    时间: 档.时间 || '', 卡: 档.卡 || '', 同一聊天: 档.聊天 === 当前聊天(),
    表数: 表们.length, 行数: 表们.reduce((n, t) => n + Math.max(0, t.content.length - 1), 0),
    旧版: !!(档.模板版 && 档.模板版 !== 模板版本),
  };
}

// 升级：先存一份升级前的备份，再搬
async function 升级本局() {
  if (正在开局 || 正在搬表) return { ok: false, 原因: '正在忙' };
  if (!有库()) return { ok: false, 原因: '没装龙血玄黄·数据库' };
  if (库在忙()) return { ok: false, 原因: '数据库正在填表 · 填完再升级' };
  if (!档案表有人()) return { ok: false, 原因: '还没开局' };
  try {
    const 档 = 备份内容();
    try { await 存本局备份(档, '升级前'); } catch (e) { return { ok: false, 原因: '升级前的备份没存上：' + (e && e.message || e) }; }
    const 报 = await 写回表格(档.表格, 档.锁);
    return { ok: true, 报 };
  } catch (e) {
    报错('升级没做完：' + (e && e.message || e));
    return { ok: false, 原因: String(e && e.message || e) };
  }
}

// 恢复：{文本} 是备份文件，{id} 是这台浏览器里的本局备份。只看不写时（看 = true）回概况
async function 取备份(来源) {
  if (来源 && 来源.id) {
    const 条 = (await 本局备份们()).find(x => x.id === 来源.id);
    if (!条) throw new Error('这份备份不在了');
    return 解析备份(条.文本);
  }
  return 解析备份(来源 && 来源.文本);
}
async function 看备份(来源) {
  try { return { ok: true, 概况: 备份概况(await 取备份(来源)) }; } catch (e) { return { ok: false, 原因: String(e && e.message || e) }; }
}
async function 恢复备份(来源) {
  if (正在开局 || 正在搬表) return { ok: false, 原因: '正在忙' };
  if (!有库()) return { ok: false, 原因: '没装龙血玄黄·数据库' };
  if (库在忙()) return { ok: false, 原因: '数据库正在填表 · 填完再恢复' };
  try {
    const 档 = await 取备份(来源);
    const 报 = await 写回表格(档.表格, 档.锁 || {});
    // 第一版的备份不带锁：开局时锁上的两张表照锁
    if (!档.锁) { 锁满一行('主角档案表', 0); 锁满整表('剧情开关表'); }
    // 恢复进一个还没开局的聊天：开局记录也补上，0 层卡照「已开局」画
    const 局 = 读局(), 原 = 档.局 || {};
    const 改 = {};
    if (原.开局 && !(局.开局 && 局.开局.状态 === '完成')) 改.开局 = Object.assign({}, 原.开局, { 状态: '完成', 聊天: 当前聊天(), 于: Date.now() });
    if (原.须知已读 && !局.须知已读) 改.须知已读 = true;
    if (Object.keys(改).length) 写局(改);
    发(事件.状态, 状态());
    return { ok: true, 报 };
  } catch (e) {
    报错('恢复没做完：' + (e && e.message || e));
    return { ok: false, 原因: String(e && e.message || e) };
  }
}

// 打开旧版的局时提醒一次（同一个聊天这次开酒馆只提一次）
const 提过旧版 = new Set();
function 提醒旧版() {
  const 聊天 = 当前聊天();
  if (!聊天 || 提过旧版.has(聊天) || !本局旧版()) return;
  提过旧版.add(聊天);
  try { toastr.info('面板 ⚙ → 本局 → 升级 · 进度照搬', '这一局的表格是旧版', { timeOut: 8000 }); } catch (e) { /* 没有 toastr */ }
}

// ── 核心/手账本.js ──
// 卡里带的手账本：替这张卡设两样默认。
//   · 导演稿开「只接管记忆」：数据库写进世界书的记忆由手账本收走，写成一份导演稿交给正文。没配密钥时不开（写不成每轮都弹一次「没写成」），
//     玩家之后配上了，切聊天、发消息时再看一眼。
//   · 发送的时候每轮都等它记完（阻塞方式「每轮」）。手账本 0.8.2 起默认就是每轮，可以前用过手账本的玩家，新装时会从旧设置的备份
//     搬回当时自动写下的「冲击轮」，所以这里再设一次。
// 都不在卡里预置：手账本新装时，脚本变量里一项设置都没有才会从玩家以前的备份搬设置，预置了就搬不回来了。
// 卡里预置的只有「角色档案」（组装卡.py 挪进去的，不算设置），所以认手账本起来没有，看它有没有写下设置项（阻塞方式），不看变量空不空。
// 每样只设一次：本机记个标记，玩家之后自己改了就不再动。
const 导演稿标记 = 'BanG.手账本导演稿已开过';
const 每轮标记 = 'BanG.手账本每轮已设过';
// 读写别的脚本的变量要用主窗口上的酒馆助手：脚本 iframe 里的 getVariables / insertOrAssignVariables 会把脚本 id 换成自己的
const 助手 = () => { try { return 主窗().TavernHelper || null; } catch (e) { return null; } };

function 找手账本脚本() {
  const 找 = 列 => {
    for (const x of (列 || [])) {
      if (!x) continue;
      if (x.type === 'folder') { const y = 找(x.scripts); if (y) return y; }
      else if (/^常夜灯的手账本/.test(x.name || '')) return x;
    }
    return null;
  };
  const TH = 助手();
  try { return TH && typeof TH.getScriptTrees === 'function' ? 找(TH.getScriptTrees({ type: 'character' })) : null; } catch (e) { return null; }
}

// 手账本起来了、搬完设置、写下了默认值：回 { TH, 条, 变 }；还没好回 null
function 手账本就绪() {
  const 条 = 找手账本脚本();
  if (!条 || !主窗().__DYN_HB__) return null;
  const TH = 助手();
  if (!TH) return null;
  let 变 = {};
  try { 变 = TH.getVariables({ type: 'script', script_id: 条.id }) || {}; } catch (e) { return null; }
  return 变.阻塞方式 === undefined ? null : { TH, 条, 变 };
}

// 设一样：标记在就不动；返回 true = 不用再试（设好了、设过了、没有手账本），false = 过一会儿再试
function 设一次(标记, 设) {
  const 窗 = 主窗();
  try { if (窗.localStorage.getItem(标记)) return true; } catch (e) { return true; }
  if (!找手账本脚本()) return true;
  const 好 = 手账本就绪();
  if (!好) return false;
  try {
    const 改 = 设(好.变);
    if (改 === null) return false;                // 条件还不够（没配密钥）
    if (Object.keys(改).length) 好.TH.insertOrAssignVariables(改, { type: 'script', script_id: 好.条.id });
    窗.localStorage.setItem(标记, '1');
  } catch (e) {
    return false;
  }
  return true;
}

function 开手账本导演稿() {
  return 设一次(导演稿标记, 变 => {
    let 有钥 = false;
    try { 有钥 = !!String(主窗().localStorage.getItem('dyn_hb.apikey') || '').trim(); } catch (e) { 有钥 = false; }
    if (!有钥) return null;
    return 变.导演稿 === undefined || 变.导演稿 === '关' ? { 导演稿: '只接管记忆' } : {};
  });
}
function 设手账本每轮() {
  return 设一次(每轮标记, 变 => (变.阻塞方式 === '每轮' ? {} : { 阻塞方式: '每轮' }));
}
function 设手账本() {
  const 甲 = 设手账本每轮(), 乙 = 开手账本导演稿();
  return 甲 && 乙;
}

function 等着开导演稿() {
  if (设手账本()) return;
  let n = 0;
  const t = setInterval(() => { if (设手账本() || ++n >= 60 || 作废) clearInterval(t); }, 2000);
}
// 玩家后来才给手账本配上密钥：切聊天、发消息时再试（设过一次以后直接返回，几乎不花时间）
function 再试导演稿() { if (!作废) 设手账本(); }

// ── 手账本「票根」皮肤要的脸：window.__BANG_FACE__（名字常夜灯同意了），手账本只读、每次重画现读 ──
// { v: 1, accent: 面板现在的强调色（推し的应援色，没有推し是默认粉）, people: { 主名: { avatar?, color?, team, aliases? } } }
// 头像、乐队照名单，应援色照 src/数据/应援色.json（和面板同一份）；艺名、面板上带艺名的全名放进 aliases。
// 总控启动时挂一次；推し换了面板直接改 accent（04 applyTheme），别的标签页换的靠 storage 事件跟上；
// 总控卸载（换了别的卡）时撤掉，手账本那边没有这个对象就整套默认
const 默认强调色 = '#ff4d7d';
let 脸 = null;
function 强调色(推) {
  const 色 = (面板静态数据.应援色 || {}).角色 || {};
  return (推 && 色[推]) || 默认强调色;
}
function 挂脸() {
  const 色 = 面板静态数据.应援色 || { 角色: {}, 乐队: {} };
  const 人 = {};
  for (const x of 名单) {
    const 全名 = x.艺名 ? x.名 + '（' + x.艺名 + '）' : x.名;
    const 本色 = 色.角色[x.名] || 色.角色[全名] || 色.乐队[x.队] || '';
    const 别 = [x.艺名, 全名 !== x.名 ? 全名 : ''].filter(Boolean);
    const 一 = { team: x.队 };
    if (x.头像) 一.avatar = x.头像;
    if (本色) 一.color = 本色;
    if (别.length) 一.aliases = 别;
    人[x.名] = 一;
  }
  let 推 = '';
  try { 推 = localStorage.getItem('th-favorite') || ''; } catch (e) { /* 存储关着 */ }
  脸 = { v: 1, accent: 强调色(推), people: 人 };
  try { 主窗().__BANG_FACE__ = 脸; } catch (e) { 脸 = null; return; }
  window.addEventListener('storage', e => { if (脸 && e.key === 'th-favorite') 脸.accent = 强调色(e.newValue || ''); });
}
function 撤脸() {
  try { if (脸 && 主窗().__BANG_FACE__ === 脸) delete 主窗().__BANG_FACE__; } catch (e) { /* 酒馆在关 */ }
  脸 = null;
}

// ── 手账本里她对主角的关系：阶段、好感底色、信任落点（面板温度计下面那两行）──
// 手账本按楼存在聊天变量里，没有正式的读取接口，借它挂在 __DYN_HB__.debug 上的 latestState / loadStore 现读；
// 主角在它的关系里写的是酒馆的玩家名，比对用它自己的 sameName（汉字写法不同也认）。没装、这个聊天还没记到她，回 null
function 手账本关系(名) {
  try {
    const d = (主窗().__DYN_HB__ || {}).debug;
    if (!d || typeof d.latestState !== 'function' || typeof d.loadStore !== 'function') return null;
    const st = d.latestState(d.loadStore(), null);
    const 人们 = st && st.chars;
    if (!人们 || typeof 人们 !== 'object') return null;
    const 规 = 归名(名) || String(名 || '').trim();
    const 键 = Object.keys(人们).find(k => k === 规 || 归名(k) === 规);
    const 关系 = 键 && 人们[键] && 人们[键].rel;
    if (!关系) return null;
    const 玩家 = String((酒馆() || {}).name1 || '').trim();
    const 同名 = typeof d.sameName === 'function' ? d.sameName : (a, b) => a === b;
    const 对 = 玩家 ? Object.keys(关系).find(k => 同名(k, 玩家)) : '';
    const r = 对 ? 关系[对] : null;
    if (!r) return null;
    return { 阶段: String(r.stage || ''), 底色: String(r.tone || ''), 落点: String(r.trust || '') };
  } catch (e) {
    return null;
  }
}

// ── 核心/配套.js ──
// 0 层卡「配套」：数据库每层都填表、手账本每轮等它；改不了的查出来写明去哪改。
// 数据库 1.2.4 不让别的脚本存它的接口、密钥，也不开放自动更新的开关：这两样只查，玩家点「打开设置」进它自己的设置页。
// 「自动填表频率」「AI 回复最小长度」是数据库的全局设置（别的卡也跟着变），所以只在玩家按「一键配好」时改，不悄悄改。

// 咩咩的心理模型世界书：找法照手账本（设置里写了书名就看那本；没写先看挂在全局的，再看名字像的，再挨个看，最多 40 本），
// 有 <acg_archetype: 的条目就算。挨本读世界书费时间，结果记 60 秒
let 心理模型记 = { 于: 0, 值: undefined, 跑: null };
async function 找心理模型书() {
  let 名们 = [];
  const 设 = String((手账本变量() || {}).性格模板世界书 || '').trim();
  if (设) 名们 = [设];
  else {
    let 全 = [], 全局 = [];
    try { 全 = getWorldbookNames() || []; } catch (e) { 全 = []; }
    try { 全局 = getGlobalWorldbookNames() || []; } catch (e) { 全局 = []; }
    名们 = 全局.concat(全.filter(n => /心理模型|acg/i.test(n)), 全).filter((n, i, a) => n && a.indexOf(n) === i).slice(0, 40);
  }
  for (const 名 of 名们) {
    let 条们 = [];
    try { 条们 = await getWorldbook(名); } catch (e) { continue; }
    const n = (Array.isArray(条们) ? 条们 : []).filter(e => /<acg_archetype:/.test(String((e && e.content) || ''))).length;
    if (n) return { 书: 名, 模板: n };
  }
  return null;
}
function 心理模型(重查) {
  if (!重查 && 心理模型记.值 !== undefined && Date.now() - 心理模型记.于 < 60000) return Promise.resolve(心理模型记.值);
  if (心理模型记.跑) return 心理模型记.跑;
  心理模型记.跑 = 找心理模型书().catch(() => null).then(v => { 心理模型记 = { 于: Date.now(), 值: v, 跑: null }; return v; });
  return 心理模型记.跑;
}

function 手账本变量() {
  const 条 = 找手账本脚本(), TH = 助手();
  if (!条 || !TH) return null;
  try { return TH.getVariables({ type: 'script', script_id: 条.id }) || {}; } catch (e) { return null; }
}
function 手账本有钥() {
  try { return !!String(主窗().localStorage.getItem('dyn_hb.apikey') || '').trim(); } catch (e) { return false; }
}

// 填表时数据库读整楼：导演类预设（奏明！序曲）一楼里的剧本（story_driver）、平行线思考（parallel_line_drive）也在里面，
// 没拍的镜头、只写给导演看的话会被填进纪要和心声。数据库 1.2.4 在「填表工作台 → 标签筛选 → 排除规则」里存成一对对起止边界；
// 旧的标签字符串只在一条规则都没有时才认（数据库自己的规矩）。设了「提取规则」的，只读提取出来的那几段，剧本本来就进不来。
// 它的对外接口改不了这一项：「一键配好」直接写进它存在酒馆设置里的那份（库设置位），它要等页面刷新、重新读设置才用上
const 填表要排除的块 = ['story_driver', 'parallel_line_drive'];
function 边界们(规则, 旧标签) {
  const 出 = [];
  (Array.isArray(规则) ? 规则 : []).forEach(r => {
    if (!r) return;
    if (typeof r === 'string') { const i = r.indexOf('|'); if (i > 0) 出.push({ 始: r.slice(0, i), 终: r.slice(i + 1) }); return; }
    const 始 = r.start != null ? r.start : (r.begin != null ? r.begin : r.open);
    const 终 = r.end != null ? r.end : (r.close != null ? r.close : r.finish);
    if (始 != null && 终 != null) 出.push({ 始: String(始), 终: String(终) });
  });
  if (!出.length) {
    String(旧标签 || '').split(/[,，\s]+/).map(t => t.replace(/[<>]/g, '').trim()).filter(Boolean)
      .forEach(t => 出.push({ 始: '<' + t, 终: '</' + t + '>' }));
  }
  return 出.filter(b => b.始.trim() && b.终.trim());
}
// true 排除了、false 没排除；读不到设置回 undefined（屏上不画这一行）
function 剧本已排除(设) {
  if (!设) return undefined;
  const 提 = 边界们(设.tableContextExtractRules, 设.tableContextExtractTags);
  const 排 = 边界们(设.tableContextExcludeRules, 设.tableContextExcludeTags);
  const 头 = b => b.始.trim().toLowerCase().replace(/>$/, '');
  return 填表要排除的块.every(块 => (提.length
    ? !提.some(b => 头(b) === '<' + 块)
    : 排.some(b => 头(b) === '<' + 块 && b.终.trim().toLowerCase() === '</' + 块 + '>')));
}

// 写进去了、页面还没刷新：数据库手上那份还是旧的。核心跟着页面一起重来，所以这个记号刷新以后自然没了
let 剧本排除待刷新 = false;
// 把两对边界补进排除规则。原来只写了旧标签字符串的，先照数据库自己的规矩转成边界一起写进去（有了规则它就不认字符串了）
function 写剧本排除() {
  const 位 = 库设置位();
  if (!位 || !位.值 || typeof 位.值 !== 'object') return false;
  const o = 位.值;
  const 有 = 边界们(o.tableContextExcludeRules, o.tableContextExcludeTags);
  const 规则 = 有.map(b => ({ start: b.始, end: b.终 }));
  const 头 = b => String(b.start).trim().toLowerCase().replace(/>$/, '');
  for (const 块 of 填表要排除的块) {
    if (!规则.some(b => 头(b) === '<' + 块 && String(b.end).trim().toLowerCase() === '</' + 块 + '>')) 规则.push({ start: '<' + 块 + '>', end: '</' + 块 + '>' });
  }
  o.tableContextExcludeRules = 规则;
  位.存[位.键] = 位.串 ? JSON.stringify(o) : o;
  try { 酒馆().saveSettingsDebounced(); } catch (e) { return false; }
  剧本排除待刷新 = true;
  return true;
}
// 「刷新页面」：酒馆存设置有一秒的防抖，等它存进去再刷新，不然刚写的规则丢在半路
function 存好再刷新() {
  try { 酒馆().saveSettingsDebounced(); } catch (e) { /* 存不了也照样刷新 */ }
  setTimeout(() => { try { 主窗().location.reload(); } catch (e) { /* 刷新不了玩家自己刷 */ } }, 2000);
  return true;
}

// { 库: {有, 自动更新, 接口, 频率, 最小长度, 剧本排除, 剧本待刷新}, 手账本: {有, 状态模型, 心理模型: {书, 模板} | null, 阻塞方式} }
// 读不到的那一项是 undefined（屏上不催）
async function 配套状态(重查) {
  const 库态 = { 有: 有库() };
  if (库态.有) {
    const 设 = 库设置();
    库态.自动更新 = 设 ? 设.autoUpdateEnabled !== false : undefined;
    库态.接口 = 填表接口已配();
    库态.剧本排除 = 剧本已排除(设);
    库态.剧本待刷新 = 库态.剧本排除 === true && 剧本排除待刷新;
    try {
      const p = 库().getUpdateConfigParams();
      库态.频率 = Number(p.autoUpdateFrequency);
      库态.最小长度 = Number(p.autoUpdateTokenThreshold);
    } catch (e) { /* 旧版没有这个接口 */ }
  }
  const 变 = 手账本变量();
  const 手态 = { 有: !!找手账本脚本() };
  if (手态.有) {
    手态.状态模型 = 手账本有钥();
    手态.阻塞方式 = 变 ? 变.阻塞方式 : undefined;
    手态.心理模型 = await 心理模型(重查);
  }
  return { 库: 库态, 手账本: 手态 };
}

// 一键配好：改数据库那两项、写排除导演剧本的规则、手账本的阻塞方式，回 {ok, 改了: [...], 状态}。
// 排除规则最后写：前面改数据库那两项时，它会把手上那份设置整份存回去
async function 一键配套() {
  const 改了 = [];
  const a = 库();
  if (有库() && typeof a.setUpdateConfigParams === 'function') {
    let p = {};
    try { p = a.getUpdateConfigParams() || {}; } catch (e) { p = {}; }
    const 要 = {};
    if (Number(p.autoUpdateFrequency) !== 1) 要.autoUpdateFrequency = 1;
    if (Number(p.autoUpdateTokenThreshold) !== 0) 要.autoUpdateTokenThreshold = 0;
    if (Object.keys(要).length) {
      if (!a.setUpdateConfigParams(要)) return { ok: false, 原因: '数据库没收下这次改动', 状态: await 配套状态(true) };
      if (要.autoUpdateFrequency) 改了.push('频率');
      if (要.autoUpdateTokenThreshold !== undefined) 改了.push('最小长度');
    }
  }
  const 好 = 手账本就绪();
  if (好 && 好.变.阻塞方式 !== '每轮') {
    try {
      好.TH.insertOrAssignVariables({ 阻塞方式: '每轮' }, { type: 'script', script_id: 好.条.id });
      改了.push('阻塞方式');
    } catch (e) { return { ok: false, 原因: '手账本的设置没改成', 状态: await 配套状态(true) }; }
  }
  if (有库() && 剧本已排除(库设置()) === false) {
    if (!写剧本排除()) return { ok: false, 原因: '数据库的设置没写进去', 状态: await 配套状态(true) };
    改了.push('剧本排除');
  }
  return { ok: true, 改了, 状态: await 配套状态(true) };
}

// 打开数据库自己的设置页（接口、自动更新都在里面）
function 开数据库设置() {
  const a = 库();
  if (!a || typeof a.openSettings !== 'function') return false;
  Promise.resolve(a.openSettings()).catch(() => {});
  return true;
}

// ── 核心/更新.js ──
// 自动更新：卡在原地换成新版——脚本、正则、卡自带的世界书条目、版本号、简介、开场白；聊天、表格、存档都不动，不用重新导卡。
// 新版放在 bangicon 仓库的 card-update/（发版工具 总控/发布更新.py），几个镜像一起问，取验得过的里面版本最高的那份：
//   latest.json 写最新版本、包的位置、大小、sha256；latest.sig 是作者私钥对 latest.json 原文签的名。
// 卡里只认下面这把公钥签过的清单（WebCrypto ECDSA P-256 + SHA-256），包再按清单里的大小、sha256 对一遍：仓库或镜像被人动了也装不进来。
// 浏览器只在安全的页面给验签（https 或本机地址打开的酒馆）：别的设备用局域网地址打开时不自动更新，
// 在装酒馆的那台电脑上打开一次就行（卡存在酒馆里，更新一次所有设备都是新的）。
// 换法：
//   世界书：卡历来发过的条目名都在包里（registry），书里叫这些名字的是卡自带的，整批换成新版的（同名的沿用原来的 uid），
//          数据库、小手机、手账本写的和玩家自己加的条目不动；条目照酒馆导卡的 convertCharacterBook 转，用 saveWorldInfo 存
//   脚本：照 id 或去掉版本号的名字认（酒馆助手导卡时 id 和全局、预设里的脚本撞了会换一个新的），认出来的换内容、沿用原来的 id；
//         玩家关掉的照样关着；脚本里存的数据留着，卡给的那几项（手账本的角色档案）换成新的；玩家自己加的脚本、文件夹留着
//   正则：卡的换成新的（玩家关掉的照样关着），玩家自己加的留着
// 卡文件按头像文件名写（/api/characters/merge-attributes，一次写完）：酒馆助手的 updateCharacterWith 按卡名找卡、写进「卡名.png」，
