  for (const r of 们) {
    if (r.status === 'fulfilled') { if (!最好 || 比版本(r.value.j.版本, 最好.j.版本) > 0) 最好 = r.value; }
    else { const m = String((r.reason && r.reason.message) || r.reason); if (!错 || /签名|格式/.test(m)) 错 = m; }
  }
  更新.忙 = '';
  if (!最好) { 更新.状态 = '检查失败'; 更新.错 = 错 || '更新源都没回音'; 发(事件.状态, 状态()); return 更新概况(); }
  更新.清单 = 最好.j; 更新.源 = 最好.s; 更新.状态 = 定状态(最好.j, 当前卡());
  写更新存({ 上次检查: Date.now(), 清单: 最好.j, 源: 最好.s });
  发(事件.状态, 状态());
  return 更新概况();
}

async function 下包(清单, 源) {
  let 错 = '';
  for (const s of [源].concat(更新源们.filter(x => x !== 源))) {
    try {
      const 文 = await 取文本(s + 清单.包, 180000);
      if (字节(文).length !== Number(清单.大小)) { 错 = '包的大小不对'; continue; }
      if ((await 摘要(文)) !== 清单.sha256) { 错 = '包的指纹不对'; continue; }
      const 包 = JSON.parse(文);
      if (包.格式 !== 1 || 包.版本 !== 清单.版本 || 包.卡 !== 清单.卡) { 错 = '包和清单对不上'; continue; }
      return 包;
    } catch (e) { 错 = String((e && e.message) || e); }
  }
  throw new Error(错 || '包下不下来');
}

// 忙着的时候不做：自动那条路半分钟后再看，不报错
function 忙错(忙, 做) { const e = new Error(忙 + ' · 等一下再' + 做); e.忙 = true; return e; }

const 状态说 = { 已是最新: '已经是最新版', 要手动: '这张卡太旧 · 重新导一次新版卡', 卡不对: '更新不是给这张卡的', 测试卡: '测试卡不更新', 不能验签: '这个地址验不了签 · 用装酒馆那台电脑打开', 酒馆太旧: '酒馆版本太旧 · 重新导一次新版卡' };

// 装：手动（设置里点「更新」）不管退回过、跳过的版本，也不等对话停
async function 用更新(手动) {
  if (更新.忙) return { ok: false, 原因: 更新.忙 };
  let 卡 = 当前卡();
  if (!卡) return { ok: false, 原因: '没打开这张卡' };
  const 头像 = 卡.avatar;
  if (!能写卡(酒馆())) return { ok: false, 原因: 状态说.酒馆太旧 };
  if (手动 || !更新.清单) await 查更新(手动);
  更新.忙 = '更新中'; 更新.错 = ''; 更新.失败 = ''; 发(事件.状态, 状态());
  let 备份id = '';
  try {
    await 刷新卡(头像);   // 别的设备可能已经更新过
    卡 = 当前卡();
    if (!卡 || 卡.avatar !== 头像) throw new Error('换卡了');
    const 清单 = 更新.清单, 态 = 定状态(清单, 卡);
    if (态 !== '有新版') { 更新.忙 = ''; 更新.状态 = 态 || 更新.状态; 发(事件.状态, 状态()); return { ok: false, 原因: 状态说[态] || 更新.错 || '没查到新版' }; }
    if (!手动 && 卡记(头像).跳过 === 清单.版本) { 更新.忙 = ''; 发(事件.状态, 状态()); return { ok: false, 原因: '这一版退回过 · 不自动装' }; }
    let 忙 = 空闲(手动);
    if (忙) throw 忙错(忙, '更新');
    const 包 = await 下包(清单, 更新.源 || 更新源们[0]);
    忙 = 空闲(手动);
    if (忙) throw 忙错(忙, '更新');
    if (作废) return { ok: false, 原因: '总控重载了' };
    卡 = 当前卡();
    if (!卡 || 卡.avatar !== 头像) throw new Error('换卡了');
    const ctx = 酒馆(), 书名 = 绑的书(), 旧版 = 卡版本(卡), 名单 = 包.名单 || {};
    const 旧书 = 书名 ? 深拷(await ctx.loadWorldInfo(书名)) : null;
    const 旧树 = getScriptTrees({ type: 'character' });
    const 旧正则 = 深拷(((卡.data || {}).extensions || {}).regex_scripts || []);
    const 卡给的数据键 = {};   // 按去掉版本号的脚本名记：退回时认得出 id 换过的那条
    (包.脚本 || []).forEach(s => { 卡给的数据键[脚本本名(s.name)] = Object.keys(s.data || {}); });
    备份id = String(Date.now());
    await 存更新备份({
      id: 备份id, 头像, 卡名: 卡.name, 从: 旧版, 到: 包.版本, 时间: new Date().toISOString(),
      书名, 世界书: 旧书, 字段: 取字段(卡), 正则: 旧正则, 脚本: 旧树, 卡给的数据键, 名单,
    });
    更新.上一版 = 旧版;
    const 新书 = 书名 && 旧书 ? 合世界书(旧书, Object.values(ctx.convertCharacterBook(深拷(包.世界书 || { entries: [] })).entries), 名单.条目) : null;
    写卡记(头像, { 待完成: { 从: 旧版, 到: 包.版本, 说明: 包.说明 || '', 于: Date.now() } });
    await 换卡(头像, 包.版本, 包.角色 || {}, 书名, 新书, 旧书, 合正则(旧正则, 包.正则 || [], 名单.正则), 合脚本(旧树, 包.脚本 || [], 名单));
    更新.忙 = '';
    // 总控的内容没变（一般不会）就不重载：5 秒后还在的话自己报
    setTimeout(() => { if (!作废) 报更新结果(); }, 5000);
    return { ok: true, 到: 包.版本 };
  } catch (e) {
    const 是忙 = !!(e && e.忙);
    更新.忙 = ''; 更新.错 = String((e && e.message) || e); 更新.失败 = 是忙 && !手动 ? '' : '更新';
    if (卡记(头像).待完成) 写卡记(头像, { 待完成: null });
    // 没换成：这次留的备份不算（卡还是原来那版）
    if (备份id) { await 删更新备份(备份id).catch(() => {}); 更新.上一版 = ((await 更新备份们(头像).catch(() => []))[0] || {}).从 || ''; }
    if (手动 && !是忙) 报错('更新没做完：' + 更新.错);
    发(事件.状态, 状态());
    return { ok: false, 原因: 更新.错, 忙: 是忙 };
  }
}

// 回到上一版：拿这张卡最近一份更新前的备份，世界书里卡自带的条目换回去，正则、脚本、简介、版本号写回去。
// 退回成了（报更新结果里对过版本号）才删这份备份、把退掉的那一版记成跳过，以后不再自动装
async function 回到上一版() {
  if (更新.忙) return { ok: false, 原因: 更新.忙 };
  const 卡 = 当前卡();
  if (!卡) return { ok: false, 原因: '没打开这张卡' };
  const 头像 = 卡.avatar;
  const 份 = (await 更新备份们(头像).catch(() => []))[0];
  if (!份) return { ok: false, 原因: '这台浏览器里没有更新前的备份' };
  const 忙 = 空闲(true);
  if (忙) return { ok: false, 原因: 忙 + ' · 等一下再退回', 忙: true };
  更新.忙 = '退回中'; 更新.错 = ''; 更新.失败 = ''; 发(事件.状态, 状态());
  try {
    const ctx = 酒馆(), 现版 = 卡版本(卡), 名单 = 份.名单 || {};
    const 卡的 = new Set(名单.条目 || []);
    const 书名 = 份.书名 && 份.书名 === 绑的书() ? 份.书名 : '';
    const 现书 = 书名 ? 深拷(await ctx.loadWorldInfo(书名)) : null;
    const 新书 = 书名 && 份.世界书 && 现书 ? 合世界书(现书, Object.values(份.世界书.entries || {}).filter(e => 卡的.has(String(e.comment || ''))), 名单.条目) : null;
    // 脚本换回旧版：现在的开关、玩家数据留着，卡给的那几项换回旧的（旧版没有的删掉）
    const 卡键 = 份.卡给的数据键 || {};
    const 树 = 合脚本(getScriptTrees({ type: 'character' }), 平铺脚本(份.脚本).filter(s => 卡的脚本(s, 名单)), 名单, (现, s) => {
      const 数据 = Object.assign({}, (现 && 现.data) || {});
      (卡键[脚本本名(s.name)] || []).forEach(k => { if (s.data && k in s.data) 数据[k] = s.data[k]; else delete 数据[k]; });
      return 数据;
    });
    const 旧正则 = (份.正则 || []).filter(r => (名单.正则 || []).includes(r.id));
    写卡记(头像, { 待完成: { 从: 现版, 到: 份.从, 回退: true, 备份: 份.id, 于: Date.now() } });
    await 换卡(头像, 份.从, 份.字段 || {}, 书名, 新书, 现书, 合正则((((当前卡() || {}).data || {}).extensions || {}).regex_scripts || [], 旧正则, 名单.正则), 树);
    更新.忙 = '';
    setTimeout(() => { if (!作废) 报更新结果(); }, 5000);
    return { ok: true, 到: 份.从 };
  } catch (e) {
    更新.忙 = ''; 更新.错 = String((e && e.message) || e); 更新.失败 = '退回';
    if (卡记(头像).待完成) 写卡记(头像, { 待完成: null });
    报错('退回没做完：' + 更新.错);
    发(事件.状态, 状态());
    return { ok: false, 原因: 更新.错 };
  }
}

// 写卡前记下的那一笔：重载以后的总控对一下卡的版本，报更新（或退回）成没成，成了重开一次聊天
function 报更新结果() {
  const 卡 = 当前卡();
  if (!卡) return;
  const 待 = 卡记(卡.avatar).待完成;
  if (!待) return;
  写卡记(卡.avatar, { 待完成: null });
  const 版 = 卡版本(卡), 成 = 比版本(版, 待.到) === 0;
  if (待.回退) 提示(成 ? 'success' : 'warning', 成 ? '已回到 ' + 待.到 : '退回没写完 · 卡现在是 ' + 版);
  if (成 && 待.回退) {
    写卡记(卡.avatar, { 跳过: 待.从 });
    Promise.resolve(待.备份 ? 删更新备份(待.备份) : null).then(() => 更新备份们(卡.avatar))
      .then(列 => { 更新.上一版 = (列[0] || {}).从 || ''; 发(事件.状态, 状态()); }).catch(() => {});
  }
  else 提示(成 ? 'success' : 'warning', 成 ? '已更新到 ' + 待.到 + (待.说明 ? ' · ' + 待.说明 : '') : '更新没写完 · 卡现在是 ' + 版 + ' · 面板 ⚙ → 关于 → 版本', 成 ? 10 : 15);
  if (!成) return;
  更新.状态 = 定状态(更新.清单 || 读更新存().清单, 卡);
  发(事件.状态, 状态());
  const ctx = 酒馆();
  if (ctx && typeof ctx.reloadCurrentChat === 'function' && !在生成()) Promise.resolve(ctx.reloadCurrentChat()).catch(() => {});
}

// 自动：打开卡 20 秒后查一次，之后每半小时看一眼（6 小时内不重复查）；有新版就挑空闲的时候装，忙就半分钟后再看
let 自动定时 = null;
async function 自动更新() {
  clearTimeout(自动定时);
  if (作废) return 更新概况();
  自动定时 = setTimeout(自动更新, 30 * 60 * 1000);
  try {
    const 概 = await 查更新(false);
    if (概.状态 !== '有新版' || 作废) return 概;
    const 卡 = 当前卡(), 记 = 卡 ? 卡记(卡.avatar) : {};
    if (!概.自动) {
      if (卡 && 记.提过 !== 概.最新) { 提示('info', '新版本 ' + 概.最新 + ' · 面板 ⚙ → 关于 → 版本 → 更新', 12); 写卡记(卡.avatar, { 提过: 概.最新 }); }
      return 概;
    }
    if (记.跳过 === 概.最新) return 概;
    if (空闲(false)) { clearTimeout(自动定时); 自动定时 = setTimeout(自动更新, 30000); return 概; }
    提示('info', '新版本 ' + 概.最新 + ' · 正在更新', 6);
    const r = await 用更新(false);
    if (!r.ok && r.忙 && !作废) { clearTimeout(自动定时); 自动定时 = setTimeout(自动更新, 30000); }
    else if (!r.ok && !作废) 提示('warning', '新版本 ' + 概.最新 + ' 没装上 · ' + r.原因, 12);
  } catch (e) { console.warn('[BanG 总控] 自动更新', e); }
  return 更新概况();
}

function 启动更新() {
  const 动 = () => { 最近动静 = Date.now(); };
  try {
    eventOn(tavern_events.GENERATION_STARTED, (类型, 参数, 试算) => { if (!试算) 动(); });
    eventOn(tavern_events.GENERATION_ENDED, 动);
    eventOn(tavern_events.GENERATION_STOPPED, 动);
    eventOn(tavern_events.MESSAGE_SENT, 动);
    eventOn(tavern_events.MESSAGE_RECEIVED, 动);
  } catch (e) { /* 没有事件就只看停止钮 */ }
  const 卡 = 当前卡();
  if (卡) 更新备份们(卡.avatar).then(列 => { 更新.上一版 = (列[0] || {}).从 || ''; }).catch(() => {});
  setTimeout(() => { if (!作废) 报更新结果(); }, 2000);
  setTimeout(() => { if (!作废) 自动更新(); }, 20000);
}

// ── 核心/入口.js ──
// 入口：拼出 BanGCtl 接口共享出去，挂数据库回调，跟着换聊天。
// 共享用酒馆助手的 initializeGlobal：接口挂在酒馆主窗口上，屏那边 waitGlobalInitialized('BanGCtl') 拿到的是取值器，
// 核心重载时自动换成新的。旧的那份靠 alive() 认出来。
const 版本 = '0.13.0';
const 实例 = Date.now().toString(36);
let 作废 = false;
let 最新楼 = -1;

function 状态() {
  const 局 = 读局();
  const 缺 = 查前置();
  const k = 局.开局 || null;
  let 态;
  if (k && k.状态 === '完成') 态 = '已开局';
  else if (k && (k.状态 === '进行中' || k.状态 === '出错')) 态 = '开局中';
  else if (档案表有人()) 态 = '已开局';
  else 态 = 缺.length ? '缺前置' : '未开局';
  return {
    状态: 态, 缺, 须知已读: !!局.须知已读,
    模板已导入: !!(局.模板 && 局.模板.版 === 模板版本 && 局.模板.聊天 === 当前聊天()),
    本局旧版: 态 === '已开局' && 本局旧版(),   // 开过局、表格是旧版模板：设置里出「升级」（升级.js）
    开局: k ? { 状态: k.状态, 步: k.步, 共: 开局步骤.length, 错误: k.错误 || '', 运行中: 正在开局 } : null,
    开局档: (k && k.档案) || null,     // 开局时交来的那份档案：0 楼的开局档案屏照它画开局那一刻
    聊天: 当前聊天(), 版本,
    表数: Object.keys(本卡模板).filter(k => k !== 'mate').length,   // 0 层卡「正常内容模板 · N 张表」
    帮填接口: 接口概况(),          // {地址, 模型, 有密钥, 配好}：✦ 能不能用、设置页显示什么
    提醒: 查提醒(),                // 不拦开局的提醒（开得了局、但会出问题的设置）
    数据库版本: 有库() ? 库版本().字 : '',   // 「龙血玄黄·数据库 1.2.4」；读不出来是空的
    更新: 更新概况(),              // 自动更新（更新.js）：卡的版本、查到的新版、现在在做什么；设置「关于 → 版本」照它画
  };
}

