// ===== 01 历法 =====
// 时间一律是整数分钟 t，自历元起算；日数 day = floor(t / 1440)。
// 公历以 1970-01-01 为第 0 天，用整数日数算法换算年月日，不用 Date，避开时区和夏令时。
// 自定义历法：每周天数与星期名、各月名称与天数、历元的星期，没有闰规则。

GE.cal = (() => {
  const DAY = 1440;
  const WEEK_ZH = ['一', '二', '三', '四', '五', '六', '日'];

  function daysFromCivil(y, m, d) {
    y -= m <= 2 ? 1 : 0;
    const era = Math.floor(y / 400);
    const yoe = y - era * 400;
    const mp = (m + 9) % 12;
    const doy = Math.floor((153 * mp + 2) / 5) + d - 1;
    const doe = yoe * 365 + Math.floor(yoe / 4) - Math.floor(yoe / 100) + doy;
    return era * 146097 + doe - 719468;
  }

  function civilFromDays(z) {
    z += 719468;
    const era = Math.floor(z / 146097);
    const doe = z - era * 146097;
    const yoe = Math.floor((doe - Math.floor(doe / 1460) + Math.floor(doe / 36524) - Math.floor(doe / 146096)) / 365);
    const doy = doe - (365 * yoe + Math.floor(yoe / 4) - Math.floor(yoe / 100));
    const mp = Math.floor((5 * doy + 2) / 153);
    const d = doy - Math.floor((153 * mp + 2) / 5) + 1;
    const m = mp < 10 ? mp + 3 : mp - 9;
    return { y: yoe + era * 400 + (m <= 2 ? 1 : 0), m, d };
  }

  const isLeap = y => (y % 4 === 0 && y % 100 !== 0) || y % 400 === 0;
  const MONTH_DAYS = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];

  function gregorian() {
    return {
      kind: '公历',
      weekLen: 7,
      monthCount: () => 12,
      daysInMonth: (y, m) => (m === 2 && isLeap(y) ? 29 : MONTH_DAYS[m - 1]),
      toDay: (y, m, d) => daysFromCivil(y, m, d),
      fromDay: day => civilFromDays(day),
      // 1970-01-01 是周四；下标 0 = 周一
      weekday: day => (((day + 3) % 7) + 7) % 7,
      weekName: i => '周' + WEEK_ZH[i],
      weekNames: WEEK_ZH.slice(),
      monthName: m => m + '月',
    };
  }

  // spec: { 类型: '自定义', 周: ['甲', ...], 月: [{ 名, 天 }], 历元星期: 0, 历元年: 1 }
  function custom(spec) {
    const weeks = spec['周'];
    const months = spec['月'];
    const yearLen = months.reduce((s, x) => s + x['天'], 0);
    const y0 = spec['历元年'] ?? 1;
    const w0 = spec['历元星期'] ?? 0;
    return {
      kind: '自定义',
      weekLen: weeks.length,
      monthCount: () => months.length,
      daysInMonth: (_y, m) => months[m - 1]['天'],
      toDay(y, m, d) {
        let day = (y - y0) * yearLen;
        for (let i = 0; i < m - 1; i++) day += months[i]['天'];
        return day + d - 1;
      },
      fromDay(day) {
        const yi = Math.floor(day / yearLen);
        let rest = day - yi * yearLen;
        let m = 0;
        while (rest >= months[m]['天']) { rest -= months[m]['天']; m++; }
        return { y: y0 + yi, m: m + 1, d: rest + 1 };
      },
      weekday: day => (((day + w0) % weeks.length) + weeks.length) % weeks.length,
      weekName: i => weeks[i],
      weekNames: weeks.slice(),
      monthName: m => months[m - 1]['名'],
    };
  }

  function make(spec) {
    if (!spec || spec['类型'] === '公历' || !spec['类型']) return gregorian();
    return custom(spec);
  }

  const pad = n => String(n).padStart(2, '0');
  const dayOf = t => Math.floor(t / DAY);
  const minuteOfDay = t => t - dayOf(t) * DAY;
  const hm = mod => pad(Math.floor(mod / 60)) + ':' + pad(mod % 60);
  const parseHM = s => {
    const m = /^(\d{1,2}):(\d{2})$/.exec(String(s).trim());
    return m ? +m[1] * 60 + +m[2] : null;
  };

  // 「YYYY-MM-DD」（公历）或「Y年 月名 D日」（自定义）
  function dateText(cal, day) {
    const { y, m, d } = cal.fromDay(day);
    if (cal.kind === '公历') return `${y}-${pad(m)}-${pad(d)}`;
    return `${y}年 ${cal.monthName(m)} ${d}日`;
  }

  // 「2026-04-08 周三 16:40」
  function stamp(cal, t) {
    const day = dayOf(t);
    return `${dateText(cal, day)} ${cal.weekName(cal.weekday(day))} ${hm(minuteOfDay(t))}`;
  }

  // 时段表 [{ 名, 起: 'HH:MM' }]，返回按起点排好的 [{ name, start }]
  function compileSegments(list) {
    return list.map(x => ({ name: x['名'], start: parseHM(x['起']) }))
      .filter(x => x.start !== null)
      .sort((a, b) => a.start - b.start);
  }

  function segmentAt(segs, mod) {
    if (!segs.length) return '';
    let cur = segs[segs.length - 1];
    for (const s of segs) if (s.start <= mod) cur = s;
    return cur.name;
  }

  // 季节表 [{ 名, 起: 'MM-DD' }]，跨年取上一年最后一段
  function compileSeasons(list) {
    return (list || []).map(x => {
      const m = /^(\d{1,2})-(\d{1,2})$/.exec(String(x['起']).trim());
      return m ? { name: x['名'], key: +m[1] * 100 + +m[2] } : null;
    }).filter(Boolean).sort((a, b) => a.key - b.key);
  }

  function seasonAt(seasons, cal, day) {
    if (!seasons.length) return '';
    const { m, d } = cal.fromDay(day);
    const key = m * 100 + d;
    let cur = seasons[seasons.length - 1];
    for (const s of seasons) if (s.key <= key) cur = s;
    return cur.name;
  }

  return {
    DAY, make, dayOf, minuteOfDay, hm, parseHM, pad, dateText, stamp,
    compileSegments, segmentAt, compileSeasons, seasonAt, isLeap,
  };
})();

// ===== 02 时钟：时间短语的解析与换算 =====
// 解析只认写法，不猜意思：认出来的交给 resolve 按第 6.3 节换算成新的 t，认不出的原样退回。
// 模型只抄原文短语，换算全在这里。

GE.clock = (() => {
  const { DAY, dayOf, minuteOfDay } = GE.cal;

  // ---- 中文数字 ----
  const CN = { 零: 0, 〇: 0, 一: 1, 二: 2, 两: 2, 三: 3, 四: 4, 五: 5, 六: 6, 七: 7, 八: 8, 九: 9 };
  const UNIT = { 十: 10, 百: 100, 千: 1000 };
  const NUM_CHARS = '0-9０-９零〇一二两三四五六七八九十百千万';

  function toHalf(s) {
    return String(s).replace(/[０-９]/g, c => String.fromCharCode(c.charCodeAt(0) - 0xFEE0))
      .replace(/[：]/g, ':').replace(/[（]/g, '(').replace(/[）]/g, ')');
  }

  // 「二十五」「两千三百」「1.5万」「3万」「十」→ 数；认不出回 null
  function cnNum(s) {
    s = toHalf(String(s).trim());
    if (!s) return null;
    if (/^-?\d+(\.\d+)?$/.test(s)) return +s;
    let m = /^(\d+(?:\.\d+)?)\s*万$/.exec(s);
    if (m) return Math.round(+m[1] * 10000);
    m = /^(\d+(?:\.\d+)?)\s*千$/.exec(s);
    if (m) return Math.round(+m[1] * 1000);
    if (!/^[零〇一二两三四五六七八九十百千万]+$/.test(s)) return null;
    let total = 0, section = 0, num = 0;
    for (const ch of s) {
      if (ch in CN) num = CN[ch];
      else if (ch in UNIT) { section += (num || 1) * UNIT[ch]; num = 0; }
      else if (ch === '万') { total += (section + num) * 10000; section = 0; num = 0; }
    }
    return total + section + num;
  }

  // ---- 时段别名：映射到规则包的时段名（找不到就原样）----
  // 每个词按顺序给几个候选时段名，取规则包里有的第一个；都没有就原样
  const SEG_ALIAS = {
    早上: ['早晨', '早上'], 清晨: ['早晨', '早上'], 早晨: ['早晨', '早上'], 凌晨: ['深夜'], 深夜: ['深夜'], 半夜: ['深夜'],
    上午: ['上午', '白天'], 中午: ['中午', '白天'], 午间: ['中午', '白天'], 白天: ['白天', '上午'], 下午: ['下午', '白天'], 午后: ['下午', '白天'],
    傍晚: ['傍晚'], 黄昏: ['傍晚'], 夜里: ['夜里', '晚上'], 晚上: ['夜里', '晚上'], 夜晚: ['夜里', '晚上'], 今晚: ['夜里', '晚上'],
  };
  function segName(word, segNames) {
    const names = segNames || [];
    if (names.includes(word)) return word;
    for (const c of SEG_ALIAS[word] || []) if (names.includes(c)) return c;
    return (SEG_ALIAS[word] || [word])[0];
  }

  const WEEK_RE = /(下下|下|这|本)?(?:周|星期|礼拜)([一二三四五六日天七])/;
  const WEEK_IDX = { 一: 0, 二: 1, 三: 2, 四: 3, 五: 4, 六: 5, 日: 6, 天: 6, 七: 6 };

  // 12 小时制换算：前缀是时段词或 AM/PM
  function to24(h, prefix) {
    if (!prefix) return h;
    const p = prefix.toUpperCase();
    if (p === 'AM' || p === '上午' || p === '早上' || p === '清晨' || p === '早晨') return h === 12 ? 0 : h;
    if (p === '凌晨' || p === '半夜') return h === 12 ? 0 : h;
    if (p === '中午' || p === '午间') return h <= 3 ? h + 12 : h;
    if (p === 'PM' || p === '下午' || p === '午后' || p === '傍晚' || p === '黄昏') return h < 12 ? h + 12 : h;
    if (p === '晚上' || p === '夜里' || p === '夜晚' || p === '今晚') return h === 12 ? 0 : (h < 5 ? h : (h < 12 ? h + 12 : h));
    if (p === '深夜') return h === 12 ? 0 : (h >= 9 && h < 12 ? h + 12 : h);
    return h;
  }

  const PREFIX = '(AM|PM|am|pm|上午|下午|晚上|早上|中午|凌晨|傍晚|夜里|深夜|清晨|早晨|午后|黄昏|夜晚|半夜|今晚)?';
  const N = `[${NUM_CHARS}]`;

  const RE = {
    ymd: new RegExp(`(\\d{4})\\s*[-/.年]\\s*(\\d{1,2})\\s*[-/.月]\\s*(\\d{1,2})\\s*[日号]?`),
    md: new RegExp(`(${N}{1,3})月(${N}{1,3})[日号]`),
    hmDigit: new RegExp(`${PREFIX}\\s*(\\d{1,2})\\s*:\\s*(\\d{2})`),
    hmAmPmAfter: /(\d{1,2})\s*:\s*(\d{2})\s*(AM|PM|am|pm)/,
    hmCn: new RegExp(`${PREFIX}\\s*(${N}{1,3})\\s*[点時](?:\\s*(半|一刻|三刻|(${N}{1,3})\\s*分?))?`),
    elapsed: new RegExp(`(半|${N}+(?:\\.\\d+)?)\\s*(?:个)?\\s*(半)?\\s*(分钟|分|小时|钟头|钟|刻钟|天|日|周|星期|礼拜|个月|月|年)(半)?`),
    jumpDay: /(大后天|后天|明天|明日|次日|翌日|第二天|隔天|隔日|今天|今日)/,
  };

  // 解析一个时间短语，返回结构；什么都没认出回 null
  // { ymd:{y,m,d} | md:{m,d}, week:{idx, next:0|1|2}, tod:minute, seg:name, elapsed:minute, days:n }
  function parse(text, segNames) {
    if (!text) return null;
    const s = toHalf(text);
    const out = {};
    let m;
    if ((m = RE.ymd.exec(s))) out.ymd = { y: +m[1], m: +m[2], d: +m[3] };
    else if ((m = RE.md.exec(s))) {
      const mm = cnNum(m[1]), dd = cnNum(m[2]);
      if (mm && dd) out.md = { m: mm, d: dd };
    }
    if ((m = WEEK_RE.exec(s))) {
      out.week = { idx: WEEK_IDX[m[2]], next: m[1] === '下下' ? 2 : m[1] === '下' ? 1 : 0 };
    }
    const dj = RE.jumpDay.exec(s);
    if (dj) {
      out.days = { 今天: 0, 今日: 0, 明天: 1, 明日: 1, 次日: 1, 翌日: 1, 第二天: 1, 隔天: 1, 隔日: 1, 后天: 2, 大后天: 3 }[dj[1]];
    }
    // 时刻
    if ((m = RE.hmAmPmAfter.exec(s))) {
      out.tod = to24(+m[1], m[3]) * 60 + +m[2];
    } else if ((m = RE.hmDigit.exec(s))) {
      const h = to24(+m[2], m[1]);
      out.tod = h * 60 + +m[3];
      if (m[1]) out.todPrefix = m[1];
    } else if ((m = RE.hmCn.exec(s))) {
      const h0 = cnNum(m[2]);
      if (h0 !== null && h0 <= 24) {
        let min = 0;
        if (m[3] === '半') min = 30;
        else if (m[3] === '一刻') min = 15;
        else if (m[3] === '三刻') min = 45;
        else if (m[4]) min = cnNum(m[4]) ?? 0;
        const h = to24(h0, m[1]);
        out.tod = (h % 24) * 60 + min;
        if (m[1]) out.todPrefix = m[1];
      }
    }
    // 时段词（没有时刻时才算时段）
    if (out.tod === undefined) {
      const names = Object.keys(SEG_ALIAS).concat(segNames || []);
      for (const w of names.sort((a, b) => b.length - a.length)) {
        if (s.includes(w)) { out.seg = segName(w, segNames); break; }
      }
    }
    // 经过时间（和日期、星期、时刻都没有时才算；「三天后」「两个小时后」）
    if (out.tod === undefined && !out.ymd && !out.md && !out.week && out.days === undefined) {
      m = RE.elapsed.exec(s);
      // 「一个半小时」先按数字认；只有「半小时」「一刻钟」「半天」这类整词才走特例
      const numeric = m && m[1] !== '半';
      if (!numeric && /半小时|半个小时|半个钟头/.test(s)) out.elapsed = 30;
      else if (!numeric && /一刻钟/.test(s)) out.elapsed = 15;
      else if (!numeric && /半天/.test(s)) out.elapsed = 360;
      else if (m) {
        let n = m[1] === '半' ? 0.5 : cnNum(m[1]);
        if (n !== null) {
          if (m[2] || m[4]) n += 0.5;
          const unit = m[3];
          if (/^(分钟|分)$/.test(unit)) out.elapsed = Math.round(n);
          else if (/^(小时|钟头|钟)$/.test(unit)) out.elapsed = Math.round(n * 60);
          else if (unit === '刻钟') out.elapsed = Math.round(n * 15);
          else if (/^(天|日)$/.test(unit)) out.dayJump = n;
          else if (/^(周|星期|礼拜)$/.test(unit)) out.dayJump = n * 7;
          else if (/^(个月|月)$/.test(unit)) out.monthJump = n;
          else if (unit === '年') out.monthJump = n * 12;
        }
      }
    }
    return Object.keys(out).length ? out : null;
  }

  // ---- 换算 ----
  // ctx: { cal, segs:[{name,start}], now:t, maxJump, backTol, morning }
  // 返回 { t } 或 { reject: 原因 }，另可带 note
  function segStart(segs, name) {
    const s = segs.find(x => x.name === name);
    return s ? s.start : null;
  }

  function addMonths(cal, day, n) {
    const { y, m, d } = cal.fromDay(day);
    const mc = cal.monthCount();
    let mm = m - 1 + Math.round(n);
    const yy = y + Math.floor(mm / mc);
    mm = ((mm % mc) + mc) % mc + 1;
    return cal.toDay(yy, mm, Math.min(d, cal.daysInMonth(yy, mm)));
  }

  function resolve(p, ctx) {
    const { cal, segs, now } = ctx;
    const maxJump = ctx.maxJump ?? DAY;
    const backTol = ctx.backTol ?? 30;
    const morning = segStart(segs, ctx.morning || '早晨') ?? 300;
    const today = dayOf(now);
    const nowMod = minuteOfDay(now);
    const todOr = (fallback) => (p.tod !== undefined ? p.tod : p.seg ? (segStart(segs, p.seg) ?? fallback) : fallback);

    if (p.elapsed !== undefined) return { t: now + p.elapsed };

    // 有具体日子：完整日期、月日、星期、明天后天、N 天后、N 个月后
    let day = null;
    if (p.ymd) day = cal.toDay(p.ymd.y, p.ymd.m, p.ymd.d);
    else if (p.md) {
      const { y } = cal.fromDay(today);
      day = cal.toDay(y, p.md.m, p.md.d);
      // 没写年份：早于今天的算明年。只早了半年以内的多半是写错了日子、或说的是这一年早些时候，不往明年跳（下面按时间倒退处理）
      if (day < today && today - day > 183) day = cal.toDay(y + 1, p.md.m, p.md.d);
    } else if (p.days !== undefined) day = today + p.days;
    else if (p.dayJump !== undefined) day = today + Math.round(p.dayJump);
    else if (p.monthJump !== undefined) day = addMonths(cal, today, p.monthJump);
    if (p.week) {
      const base = day ?? today;
      const wd = cal.weekday(base);
      let diff = (p.week.idx - wd + cal.weekLen) % cal.weekLen;
      if (p.week.next) {
        // 「下周三」：下一周的周三（周一为一周之始）
        const startNext = base - wd + cal.weekLen * p.week.next;
        day = startNext + p.week.idx;
      } else if (day === null) {
        day = base + diff;
        if (diff === 0) {
          const tod = todOr(null);
          if (tod !== null && tod < nowMod) day += cal.weekLen;
        }
      }
    }

    if (day !== null) {
      let tod;
      if (p.tod !== undefined || p.seg) tod = todOr(morning);
      else if (day === today) tod = nowMod;
      else tod = morning;
      const t = day * DAY + tod;
      if (t < now) {
        if (p.ymd && now - t <= backTol) return { t: now, note: `时间戳早于账上 ${now - t} 分钟，按账上` };
        return { reject: '时间倒退' };
      }
      return { t };
    }

    if (p.tod !== undefined) {
      let diff = p.tod - nowMod;
      if (diff < 0) {
        if (-diff <= backTol) return { t: now, note: `时间戳早于账上 ${-diff} 分钟，按账上` };
        diff += DAY;
      }
      if (diff > maxJump) return { reject: '超过单次最大跳跃' };
      return { t: now + diff };
    }

    if (p.seg) {
      const start = segStart(segs, p.seg);
      if (start === null) return { reject: '未知时段' };
      // 已在该时段内则不动
      const idx = segs.findIndex(x => x.name === p.seg);
      const end = idx + 1 < segs.length ? segs[idx + 1].start : DAY + segs[0].start;
      const inSeg = (nowMod >= start && nowMod < end) || (end > DAY && nowMod < end - DAY);
      if (inSeg) return { t: now };
      let diff = start - nowMod;
      if (diff < 0) diff += DAY;
      return { t: now + diff };
    }
    return { reject: '认不出时间' };
  }

  // ---- 从正文里扫场景时间戳（兜底用）----
  // 只认独占一行、或在行首的时间戳；引号里的不认（那是台词）。
  // 日期可以不带年份（「4月28日 PM 4:15；羽丘」这种场景头，年份按账上的算）
  const QUOTE_RE = /[“"「『][^”"」』]*[”"」』]/g;
  const STAMP_RE = new RegExp(
    `(\\d{4}\\s*[-/.年]\\s*\\d{1,2}\\s*[-/.月]\\s*\\d{1,2}\\s*[日号]?|\\d{1,2}\\s*月\\s*\\d{1,2}\\s*[日号])?\\s*` +
    `((?:周|星期|礼拜)[一二三四五六日天])?\\s*[;；,，]?\\s*` +
    `(${PREFIX}\\s*\\d{1,2}\\s*:\\s*\\d{2}(?:\\s*(?:AM|PM|am|pm))?)`);

  function scanStamps(text) {
    const out = [];
    const lines = toHalf(text || '').split(/\r?\n/);
    for (const raw of lines) {
      const line = raw.replace(QUOTE_RE, '').trim();
      if (!line || line.length > 80) continue;
      const m = STAMP_RE.exec(line);
      if (!m) continue;
      // 行首的时间戳（场景头「时间；地点」，地点可以写得长）放宽到 80 字；不在行首的要占这一行的四成，行也不能超过 40 字
      const atStart = m.index <= 2;
      const covers = line.length <= 40 && m[0].trim().length >= line.length * 0.4;
      if (atStart || covers) out.push(m[0].trim());
    }
    return out;
  }

  return { cnNum, toHalf, parse, resolve, scanStamps, SEG_ALIAS, segName };
})();

// ===== 03 注册表：规则包的校验与编译 =====
// 规则包里出现哪一块，对应的模块就启用；没出现的不加载、不计算、不进工具定义和注入。
// 校验错误用白话指到具体字段，交给面板显示；校验失败由调用方退回内置预设。

GE.registry = (() => {
  const DEFAULT_SEGMENTS = [
    { 名: '深夜', 起: '00:00' }, { 名: '早晨', 起: '05:00' }, { 名: '上午', 起: '08:00' },
    { 名: '中午', 起: '11:30' }, { 名: '下午', 起: '13:00' }, { 名: '傍晚', 起: '17:00' }, { 名: '夜里', 起: '19:30' },
  ];

  function compile(pack) {
    const errs = [];
    const err = (path, msg) => errs.push(`${path}：${msg}`);
    if (!pack || typeof pack !== 'object') return { ok: false, errs: ['规则包不是一个 JSON 对象'] };

    const P = {
      name: pack['名称'] || '未命名规则包',
      raw: pack,
      on: { clock: true, calc: true },
    };

    // 时钟
    try { P.cal = GE.cal.make(pack['历法']); } catch (e) { err('历法', '写法不对'); P.cal = GE.cal.make(null); }
    if (pack['历法'] && pack['历法']['类型'] === '自定义') {
      const c = pack['历法'];
      if (!Array.isArray(c['周']) || !c['周'].length) err('历法.周', '要写每周各天的名字');
      if (!Array.isArray(c['月']) || !c['月'].length) err('历法.月', '要写各月的名字和天数');
      else c['月'].forEach((m, i) => { if (!(m['天'] > 0)) err(`历法.月[${i}].天`, '要写正整数'); });
    }
    P.segs = GE.cal.compileSegments(pack['时段'] || DEFAULT_SEGMENTS);
    if (!P.segs.length) err('时段', '至少要一个时段，起点写「HH:MM」');
    P.seasons = GE.cal.compileSeasons(pack['季节']);
    P.morning = (pack['次日起点时段'] || '早晨');

    const init = pack['初始'] || {};
    P.init = { time: null, loc: init['地点'] || null };
    if (init['时间']) {
      const p = GE.clock.parse(init['时间']);
      if (!p || !p.ymd || p.tod === undefined) err('初始.时间', '写成「YYYY-MM-DD HH:MM」');
      else P.init.time = P.cal.toDay(p.ymd.y, p.ymd.m, p.ymd.d) * GE.cal.DAY + p.tod;
    }

    // 各模块：各自编译，出错写进 errs
    if (pack['资源'] || pack['物品'] || pack['物价']) { P.on.ledger = true; P.ledger = GE.ledger.compile(pack, err); }
    if (pack['关系']) { P.on.relation = true; P.relation = GE.relation.compile(pack['关系'], pack, err); }
    if (pack['地图']) { P.on.map = true; P.map = GE.map.compile(pack['地图'], err); }
    // 房产在地图之后：住宅区要登记成地图上的地点
    if (pack['房产']) { P.on.estate = true; P.estate = GE.estate.compile(pack, P, err); }
    if (pack['作息'] || pack['约定']) { P.on.routine = true; P.routine = GE.routine.compile(pack, P, err); }
    if (pack['规则'] || pack['派生']) { P.on.rules = true; P.rules = GE.rules.compile(pack, err); }
    if (pack['判定']) { P.on.check = true; P.check = GE.rng.compile(pack['判定'], err); }
    P.on.timers = true;

    return errs.length ? { ok: false, errs, pack: P } : { ok: true, pack: P };
  }

  // 基底存档：首次设置或宿主 setBase 给出的初值
  function baseState(P, over) {
    over = over || {};
    const S = {
      v: 1,
      clock: { t: over.t ?? P.init.time ?? null },
      flags: {},
      loc: over.loc ?? P.init.loc ?? null,
      res: {}, items: {}, rel: {},
      excepts: [], appts: [], timers: [], cool: {},
      seq: 0,
    };
    if (P.on.ledger) GE.ledger.initState(P, S, over);
    if (P.on.relation) GE.relation.initState(P, S, over);
    if (P.on.routine) GE.routine.initState(P, S, over);
    if (P.on.estate) GE.estate.initState(P, S, over);
    return S;
  }

  // 工具 ge_call 的参数结构：只含已注册模块的项
  function toolSchema(P, opts) {
    const str = d => ({ type: 'string', description: d });
    const arr = (d, props, req) => ({ type: 'array', description: d, items: { type: 'object', properties: props, required: req } });
    const props = {
      time: {
        type: 'object',
        description: '本轮时间的变化。值是原文里的时间短语，换算由引擎做。三项只填一项。',
        properties: {
          elapsed: str('经过的时长，例如「35分钟」「两个小时」'),
          until: str('到某个时刻，例如「下午五点」「19:30」「周六下午两点」'),
          jump: str('跳转词，例如「次日」「三天后」「下周一」'),
        },
      },
    };
    if (opts.calc !== false) {
      props.calc = arr('只算不改状态的表达式。支持 + - * / %、括号、min max clamp floor ceil round abs if。', { expr: str('表达式，例如「1200 * 3 * 0.9」') }, ['expr']);
    }
    if (P.on.map) {
      const modes = P.map.modes.map(m => m.name);
      props.move = {
        type: 'object', description: '移动到某地。路程、耗时、车费由引擎算。',
        properties: { to: str('目的地名称'), by: str('交通方式：' + modes.join('、')), minutes: { type: 'number', description: '只在地点或方式未登记时用的耗时（分钟）' } },
        required: ['to'],
      };
    }
    if (P.on.ledger) {
      const ids = P.ledger.resIds.concat(P.ledger.itemIds);
      props.spend = arr('花费。只报这一笔的数额，不写余额。', {
        target: str('资源或物品：' + ids.join('、')), amount: { type: 'number', description: '数额，不带单位' },
        what: str('用途'), from: { type: 'array', items: { type: 'string' }, description: '付款方，按顺序扣；省略为玩家' },
      }, ['target', 'amount']);
      props.gain = arr('获得。只报这一笔的数额。', {
        target: str('资源或物品：' + ids.join('、')), amount: { type: 'number' }, what: str('来源'), to: str('收款方，省略为玩家'),
      }, ['target', 'amount']);
      if (P.ledger.itemIds.length) {
        props.trade = arr('以物易物：两边一起成立或一起不成立。', {
          with: str('交易对象'),
          give: { type: 'array', items: { type: 'object', properties: { target: str('物品'), amount: { type: 'number' } } } },
          get: { type: 'array', items: { type: 'object', properties: { target: str('物品'), amount: { type: 'number' } } } },
        }, ['give', 'get']);
      }
    }
    if (P.on.relation) {
      props.relation = arr('关系变化。delta 为这一楼的变化量。', {
        who: str('角色名'), dim: str('维度：' + P.relation.dims.map(d => d.id).join('、')), delta: { type: 'number' }, why: str('原因'),
      }, ['who', 'dim', 'delta']);
    }
    if (P.on.check) {
      props.check = arr('判定：引擎掷骰并返回点数与档位。', { id: str('判定：' + P.check.list.map(c => c.id).join('、')), who: str('相关角色') }, ['id']);
    }
    if (P.on.routine) {
      props.routine = arr('作息的例外：角色这段时间不按平常的作息。', {
        action: { type: 'string', enum: ['except', 'clear'] }, who: str('角色名'), what: str('例外的内容，例如「今天留下」'), until: str('到什么时候，省略为今天结束'),
      }, ['action', 'who']);
      props.appt = arr('约定：新增、完成、取消、改期。', {
        action: { type: 'string', enum: ['add', 'done', 'cancel', 'move'] }, id: str('已有约定的编号'), title: str('约定的事'), who: str('参与的人，顿号分隔'), when: str('时间短语'),
      }, ['action']);
    }
    props.timer = arr('计时：过一段时间自动结束的事（药效、冷却、伤势恢复）。', {
      title: str('计时的名字'), duration: str('时长，例如「三小时」'), action: { type: 'string', enum: ['add', 'cancel'] },
    }, ['title']);
    const q = ['时间'];
    if (P.on.ledger) q.push('资源');
    if (P.on.routine) q.push('约定', '作息:角色名');
    if (P.on.map) q.push('距离:甲,乙', '路线:甲,乙');
    if (P.on.estate) q.push('房产');
    if (P.on.ledger && P.ledger.prices.length) q.push('物价:名称');
    props.query = { type: 'array', items: { type: 'string' }, description: '只查询、不改状态：' + q.join('、') };
    return { type: 'object', properties: props };
  }

  return { compile, baseState, toolSchema, DEFAULT_SEGMENTS };
})();

// ===== 04 表达式：解析与求值 =====
// 通用计算 calc、派生值、触发规则、方式的条件共用。不用 eval 和 Function。
// 只读：无赋值、无循环；节点数上限 200，保证一定终止。
// 结果四舍五入到 6 位小数，避免浮点误差露到结果里（1200*3*0.9 → 3240）。

GE.expr = (() => {
  const MAX_NODES = 200;

  class ExprError extends Error {}

  // ---- 词法 ----
  function lex(src) {
    const s = GE.clock.toHalf(String(src))
      .replace(/×/g, '*').replace(/÷/g, '/').replace(/，/g, ',').replace(/－/g, '-').replace(/＋/g, '+');
    const toks = [];
    let i = 0, depth = 0;
    const isIdStart = c => /[A-Za-z_぀-ヿ㐀-鿿豈-﫿]/.test(c);
    const isId = c => isIdStart(c) || /[0-9]/.test(c);
    while (i < s.length) {
      const c = s[i];
      if (/\s/.test(c)) { i++; continue; }
      if (/[0-9.]/.test(c)) {
        let j = i;
        while (j < s.length && /[0-9.,]/.test(s[j])) {
          // 千分位逗号：只在括号外、后面正好三位数字时算（括号里的逗号是参数分隔）
          if (s[j] === ',' && (depth > 0 || !/^\d{3}(?!\d)/.test(s.slice(j + 1)))) break;
          j++;
        }
        const raw = s.slice(i, j).replace(/,/g, '');
        if (!/^\d*\.?\d+$|^\d+\.$/.test(raw)) throw new ExprError('数字写法不对：' + raw);
        toks.push({ k: 'num', v: parseFloat(raw) });
        i = j;
        // 「1.5万」「3千」
        if (s[i] === '万') { toks[toks.length - 1].v *= 10000; i++; }
        else if (s[i] === '千' && !isId(s[i + 1] || '')) { toks[toks.length - 1].v *= 1000; i++; }
        continue;
      }
      if (c === '"' || c === "'") {
        const j = s.indexOf(c, i + 1);
        if (j < 0) throw new ExprError('引号没有闭合');
        toks.push({ k: 'str', v: s.slice(i + 1, j) });
        i = j + 1;
        continue;
      }
      if (isIdStart(c)) {
        let j = i;
        while (j < s.length && (isId(s[j]) || (s[j] === '.' && isIdStart(s[j + 1] || '')))) j++;
        toks.push({ k: 'id', v: s.slice(i, j) });
        i = j;
        continue;
      }
      const two = s.slice(i, i + 2);
      if (['<=', '>=', '==', '!=', '&&', '||'].includes(two)) { toks.push({ k: 'op', v: two }); i += 2; continue; }
      if ('+-*/%<>!(),'.includes(c)) {
        if (c === '(') depth++;
        else if (c === ')') depth--;
        toks.push({ k: 'op', v: c }); i++; continue;
      }
      throw new ExprError('认不出的字符：' + c);
    }
    return toks;
  }

  // ---- 语法（递归下降）----
  const BIN = [['||'], ['&&'], ['==', '!='], ['<', '<=', '>', '>='], ['+', '-'], ['*', '/', '%']];
  const FUNCS = {
    min: { n: [1, 99], f: (...a) => Math.min(...a) },
    max: { n: [1, 99], f: (...a) => Math.max(...a) },
    clamp: { n: [3, 3], f: (x, lo, hi) => Math.min(Math.max(x, lo), hi) },
    floor: { n: [1, 1], f: Math.floor },
    ceil: { n: [1, 1], f: Math.ceil },
    round: { n: [1, 2], f: (x, d = 0) => { const k = 10 ** d; return Math.round(x * k) / k; } },
    abs: { n: [1, 1], f: Math.abs },
  };

  function parse(src) {
    const toks = lex(src);
    let pos = 0, nodes = 0;
    const peek = () => toks[pos];
    const isOp = v => peek() && peek().k === 'op' && peek().v === v;
    const node = n => { if (++nodes > MAX_NODES) throw new ExprError('表达式太长（超过 200 个节点）'); return n; };

    function level(i) {
      if (i >= BIN.length) return unary();
      let left = level(i + 1);
      while (peek() && peek().k === 'op' && BIN[i].includes(peek().v)) {
        const op = toks[pos++].v;
        left = node({ t: 'bin', op, a: left, b: level(i + 1) });
      }
      return left;
    }
    function unary() {
      if (isOp('-') || isOp('!') || isOp('+')) { const op = toks[pos++].v; return node({ t: 'un', op, a: unary() }); }
      return primary();
    }
    function primary() {
      const tk = toks[pos++];
      if (!tk) throw new ExprError('表达式不完整');
      if (tk.k === 'num') return node({ t: 'num', v: tk.v });
      if (tk.k === 'str') return node({ t: 'str', v: tk.v });
      if (tk.k === 'op' && tk.v === '(') {
        const e = level(0);
        if (!isOp(')')) throw new ExprError('括号没有闭合');
        pos++;
        return e;
      }
      if (tk.k === 'id') {
        if (tk.v === 'true' || tk.v === '真') return node({ t: 'bool', v: true });
        if (tk.v === 'false' || tk.v === '假') return node({ t: 'bool', v: false });
        if (isOp('(')) {
          pos++;
          const args = [];
          if (!isOp(')')) {
            for (;;) {
              args.push(level(0));
              if (isOp(',')) { pos++; continue; }
              break;
            }
          }
          if (!isOp(')')) throw new ExprError('函数括号没有闭合：' + tk.v);
          pos++;
          if (tk.v === 'if') {
            if (args.length !== 3) throw new ExprError('if 要三个参数');
            return node({ t: 'if', c: args[0], a: args[1], b: args[2] });
          }
          const fn = FUNCS[tk.v];
          if (!fn) throw new ExprError('没有这个函数：' + tk.v);
          if (args.length < fn.n[0] || args.length > fn.n[1]) throw new ExprError(`${tk.v} 的参数个数不对`);
          return node({ t: 'call', f: tk.v, args });
        }
        return node({ t: 'var', v: tk.v });
      }
      throw new ExprError('这里不该出现：' + tk.v);
    }

    const ast = level(0);
    if (pos < toks.length) throw new ExprError('多出来的内容：' + toks[pos].v);
    return ast;
  }

  // ---- 求值 ----
  function evaluate(ast, lookup) {
    const num = (x, what) => {
      if (typeof x === 'boolean') return x ? 1 : 0;
      if (typeof x !== 'number' || Number.isNaN(x)) throw new ExprError(`${what} 不是数`);
      return x;
    };
    function ev(n) {
      switch (n.t) {
        case 'num': case 'str': case 'bool': return n.v;
        case 'var': {
          const v = lookup ? lookup(n.v) : undefined;
          if (v === undefined) throw new ExprError('未知变量：' + n.v);
          return v;
        }
        case 'un': {
          const a = ev(n.a);
          if (n.op === '!') return !a;
          return n.op === '-' ? -num(a, '取负的对象') : num(a, '取正的对象');
        }
        case 'if': return ev(n.c) ? ev(n.a) : ev(n.b);
        case 'call': return FUNCS[n.f].f(...n.args.map(x => num(ev(x), n.f + ' 的参数')));
        case 'bin': {
          if (n.op === '&&') return ev(n.a) && ev(n.b);
          if (n.op === '||') return ev(n.a) || ev(n.b);
          const a = ev(n.a), b = ev(n.b);
          if (n.op === '==') return a === b;
          if (n.op === '!=') return a !== b;
          const x = num(a, '左边'), y = num(b, '右边');
          switch (n.op) {
            case '+': return x + y;
            case '-': return x - y;
            case '*': return x * y;
            case '/': if (y === 0) throw new ExprError('除以零'); return x / y;
            case '%': if (y === 0) throw new ExprError('除以零'); return x % y;
            case '<': return x < y;
            case '<=': return x <= y;
            case '>': return x > y;
            case '>=': return x >= y;
          }
        }
      }
      throw new ExprError('无法计算');
    }
    return ev(ast);
  }

  function tidy(v) {
    if (typeof v !== 'number') return v;
    if (!Number.isFinite(v)) throw new ExprError('结果不是有限数');
    const r = Math.round(v * 1e6) / 1e6;
    return Object.is(r, -0) ? 0 : r;
  }

  // 一步到位：返回 { ok: true, value } 或 { ok: false, err }
  function calc(src, lookup) {
    try {
      return { ok: true, value: tidy(evaluate(parse(src), lookup)) };
    } catch (e) {
      if (e instanceof ExprError) return { ok: false, err: e.message };
      throw e;
    }
  }

  // 条件：结果为真即真；出错算不满足并带原因
  function test(src, lookup) {
    const r = calc(src, lookup);
    return r.ok ? { ok: true, value: !!r.value } : r;
  }

  return { parse, evaluate, calc, test, tidy, MAX_NODES };
})();

// ===== 05 结算：上一份存档 + 一组事项 → 新存档、每项的结果、说明 =====
// 纯函数。工具调用、代码读时间戳、副模型抽取、宿主事项、面板手动，都走这一个入口。
// 处理顺序：time → move → spend/gain/trade → relation → check → routine → appt → calc → query，
// 之后到点的计时、约定状态、触发规则按新的时间统一更新。

GE.settle = (() => {
  const { DAY } = GE.cal;

  const DEFAULTS = {
    maxJumpMin: 1440,     // 只有时刻时的单次最大跳跃
    backTolMin: 30,       // 时间戳略早于账上多少分钟以内，按账上不动
    stampGapMin: 10,      // 时间戳与经过时间相差超过它就记说明
    bigJumpDays: 30,      // 跳跃超过这么多天标红
    perFloorDefaultMin: 0,
    maxEvents: 20,
    unknownPlace: 'minutes',   // minutes | reject | teleport
    unknownMode: 'teleport',   // teleport | minutes | reject
    unknownMinutesCap: 120,
    unknownPayer: 'external',  // external | reject
    locSource: 'engine',       // engine | host
    apptSource: 'engine',      // engine | host
    calc: true,
  };

  const clone = S => JSON.parse(JSON.stringify(S));
  const fmtDur = m => {
    m = Math.round(m);
    if (m < 60) return `${m} 分钟`;
    const d = Math.floor(m / DAY), h = Math.floor((m % DAY) / 60), mm = m % 60;
    return [d ? `${d} 天` : '', h ? `${h} 小时` : '', mm ? `${mm} 分钟` : ''].filter(Boolean).join(' ');
  };

  function clockCtx(P, S, o) {
    return { cal: P.cal, segs: P.segs, now: S.clock.t, maxJump: o.maxJumpMin, backTol: o.backTolMin, morning: P.morning };
  }

  function nowText(P, t) {
    if (t === null || t === undefined) return '未设置';
    const seg = GE.cal.segmentAt(P.segs, GE.cal.minuteOfDay(t));
    return `${GE.cal.stamp(P.cal, t)} ${seg}`.trim();
  }

  // ---- 时间 ----
  function settleTime(P, S, tev, env, out) {
    const o = env.opts;
    if (S.clock.t === null) { out.notes.push('还没有设定时间，时间项不结算'); return; }
    if (tev.scope && tev.scope !== 'present') {
      out.notes.push(`非现在的时间表述（${tev.scope}）只记录，不推进`);
      return;
    }
    const before = S.clock.t;
    const ctx = () => clockCtx(P, S, o);
    const one = (phrase, kind) => {
      const p = GE.clock.parse(phrase, P.segs.map(s => s.name));
      if (!p) return { reject: '认不出时间' };
      if (kind === 'elapsed' && p.elapsed === undefined && p.dayJump === undefined && p.monthJump === undefined) return { reject: '不是一段时长' };
      return GE.clock.resolve(p, ctx());
    };
    const push = (phrase, r, kind) => {
      if (r.reject) {
        out.results.push({ 项: '时间', 原文: phrase, 状态: '未结算：' + r.reject });
        return false;
      }
      if (r.t - S.clock.t > o.bigJumpDays * DAY) out.flags.push({ kind: 'bigJump', from: S.clock.t, to: r.t });
      S.clock.t = r.t;
      if (r.note) out.notes.push(r.note);
      return true;
    };

    // 兜底路径：正文里的时间戳，按原文顺序、采纳的必须不递减
    let stampT = null;
    for (const st of tev.stamps || []) {
      const r = one(st, 'stamp');
      if (r.reject) { out.notes.push(`时间戳「${st}」未采纳：${r.reject}`); continue; }
      if (stampT !== null && r.t < stampT) { out.notes.push(`时间戳「${st}」比前一个早，未采纳`); continue; }
      if (r.note) out.notes.push(`时间戳「${st}」${r.note}`);
      stampT = r.t;
      S.clock.t = r.t;
    }
    // 工具 / 抽取给的经过时间、到某时刻、跳转
    const pairs = [['elapsed', tev.elapsed], ['until', tev.until], ['jump', tev.jump]].filter(x => x[1]);
    if (stampT !== null) {
      // 有时间戳时以时间戳为准，经过时间只用来核对
      for (const [kind, phrase] of pairs) {
        const r = GE.clock.resolve(GE.clock.parse(phrase, P.segs.map(s => s.name)) || {}, { ...ctx(), now: before });
        if (r.t !== undefined && Math.abs(r.t - stampT) > o.stampGapMin) {
          out.notes.push(`正文时间戳与「${phrase}」相差 ${fmtDur(Math.abs(r.t - stampT))}，按时间戳`);
        }
        void kind;
      }
      S.clock.t = Math.max(S.clock.t, before);
    } else {
      for (const [kind, phrase] of pairs) push(phrase, one(phrase, kind), kind);
    }
    if (S.clock.t !== before) {
      out.results.push({ 项: '时间', 推进: fmtDur(S.clock.t - before), 现在: nowText(P, S.clock.t), 状态: '成立' });
    }
  }

  // ---- 通用计算 ----
  function lookupFor(P, S, env) {
    return name => GE.rules.lookup(P, S, env, name);
  }

  function settleCalc(P, S, list, env, out) {
    for (const it of list) {
      const src = typeof it === 'string' ? it : it && it.expr;
      if (!src) continue;
      const r = GE.expr.calc(src, lookupFor(P, S, env));
      out.results.push(r.ok
        ? { 项: '计算', 式: src, 值: r.value, 状态: '成立' }
        : { 项: '计算', 式: src, 状态: '未结算：无法计算（' + r.err + '）' });
    }
  }

  // ---- 查询 ----
  function settleQuery(P, S, list, env, out) {
    for (let q of list) {
      if (q && typeof q === 'object') {
        if (q.distance) q = '距离:' + q.distance.join(',');
        else if (q.route) q = '路线:' + q.route.join(',');
        else if (q.routine) q = '作息:' + q.routine;
        else if (q.price) q = '物价:' + q.price;
        else continue;
      }
      const [k, arg] = String(q).split(/[:：]/);
      const key = k.trim();
      if (key === '时间') out.results.push({ 项: '查询', 查: '时间', 现在: nowText(P, S.clock.t) });
      else if (key === '资源' && P.on.ledger) out.results.push({ 项: '查询', 查: '资源', 值: GE.ledger.summary(P, S) });
      else if (key === '约定' && P.on.routine) out.results.push({ 项: '查询', 查: '约定', 值: GE.routine.apptLines(P, S, env, 99) });
      else if (key === '作息' && P.on.routine) out.results.push({ 项: '查询', 查: '作息', 角色: arg, 值: GE.routine.lineFor(P, S, (arg || '').trim()) || '没有登记' });
      else if ((key === '距离' || key === '路线') && P.on.map) {
        const [a, b] = (arg || '').split(/[,，、]/).map(x => x.trim());
        out.results.push(GE.map.query(P, S, env, a, b, key === '路线'));
      } else if (key === '房产' && P.on.estate) out.results.push(GE.estate.query(P, S));
      else if (key === '物价' && P.on.ledger) out.results.push({ 项: '查询', 查: '物价', 名称: arg, 值: GE.ledger.priceText(P, (arg || '').trim()) || '没有登记' });
      else out.results.push({ 项: '查询', 查: String(q), 状态: '未结算：没有这项' });
    }
  }

  // ---- 变化 ----
  function diff(a, b) {
    const d = { 分钟: (b.clock.t ?? 0) - (a.clock.t ?? 0) };
    const num = (x, y) => {
      const o = {};
      for (const k of new Set([...Object.keys(x || {}), ...Object.keys(y || {})])) {
        const v = (y[k] || 0) - (x[k] || 0);
        if (v) o[k] = GE.expr.tidy(v);
      }
      return o;
    };
    d.res = num(a.res, b.res);
    d.items = num(a.items, b.items);
    d.rel = {};
    for (const who of new Set([...Object.keys(a.rel || {}), ...Object.keys(b.rel || {})])) {
      const x = (a.rel || {})[who] || {}, y = (b.rel || {})[who] || {};
      const o = {};
      for (const k of Object.keys(y)) if (k[0] !== '_' && (y[k] || 0) !== (x[k] || 0)) o[k] = GE.expr.tidy((y[k] || 0) - (x[k] || 0));
      if (Object.keys(o).length) d.rel[who] = o;
    }
    if (a.loc !== b.loc) d.loc = [a.loc, b.loc];
    return d;
  }

  // ---- 主入口 ----
  // env: { P, opts, seed, host: { items, locHint } }
  function run(prev, ev, env) {
    const P = env.P;
    env = { ...env, opts: { ...DEFAULTS, ...(env.opts || {}) } };
    // 旧存档里没有后来登记的资源：先按初值补进上一份，变化从这里算起
    if (P.on.ledger && GE.ledger.missing(P, prev)) { prev = clone(prev); GE.ledger.fillMissing(P, prev); }
    const S = clone(prev);
    const out = { results: [], notes: [], flags: [] };
    ev = ev || {};

    // 事项总数上限
    let count = 0;
    const cap = list => {
      if (!Array.isArray(list)) return [];
      const room = Math.max(0, env.opts.maxEvents - count);
      if (list.length > room) out.notes.push(`事项超过每楼上限 ${env.opts.maxEvents}，多出的 ${list.length - room} 条丢弃`);
      const kept = list.slice(0, room);
      count += kept.length;
      return kept;
    };

    // 手动设定时间（面板、setClock）：可以往回拨，不受跳跃上限
    if (ev.clockSet !== undefined && ev.clockSet !== null) {
      const before = S.clock.t;
      S.clock.t = ev.clockSet;
      out.results.push({ 项: '时间', 手动: true, 现在: nowText(P, S.clock.t), 状态: '成立' });
      if (before !== null && before !== S.clock.t) out.notes.push('时间被手动改过');
    }
    // 宿主同步：所在地、约定由宿主维护时，以宿主为准
    if (ev.hostSet) {
      const h = ev.hostSet;
      if (h.loc !== undefined) S.loc = h.loc || null;
      if (Array.isArray(h.appts) && P.on.routine) S.appts = GE.routine.fromHost(P, S, h.appts);
    }
    if (ev.time) settleTime(P, S, ev.time, env, out);
    if (ev.move && P.on.map) GE.map.settleMove(P, S, ev.move, env, out);
    else if (ev.move) out.results.push({ 项: '移动', 状态: '未结算：没有注册地图' });
    if (P.on.ledger) {
      for (const it of cap(ev.spend)) GE.ledger.spend(P, S, it, env, out);
      for (const it of cap(ev.gain)) GE.ledger.gain(P, S, it, env, out);
      for (const it of cap(ev.set)) GE.ledger.set(P, S, it, env, out);
      for (const it of cap(ev.transfer)) GE.ledger.transfer(P, S, it, env, out);
      for (const it of cap(ev.trade)) GE.ledger.trade(P, S, it, env, out);
    }
    if (P.on.estate) GE.estate.settle(P, S, cap(ev.house), env, out);
    if (P.on.relation) GE.relation.settle(P, S, cap(ev.relation), env, out);
    if (P.on.check) for (const it of cap(ev.check)) GE.rng.check(P, S, it, env, out);
    if (P.on.routine) {
      for (const it of cap(ev.routine)) GE.routine.except(P, S, it, env, out);
      for (const it of cap(ev.appt)) GE.routine.appt(P, S, it, env, out);
    }
    for (const it of cap(ev.timer)) GE.routine.timer(P, S, it, env, out);
    if (env.opts.calc !== false && ev.calc) settleCalc(P, S, cap(ev.calc), env, out);

    // 时间推进后的统一更新
    if (P.on.ledger) GE.ledger.passTime(P, prev, S, out);
    if (P.on.estate) GE.estate.passTime(P, prev, S, out);
    GE.routine.tick(P, S, env, out);
    if (P.on.relation) GE.relation.decay(P, prev, S);
    if (P.on.rules) GE.rules.apply(P, S, env, out);

    if (ev.query) settleQuery(P, S, Array.isArray(ev.query) ? ev.query : [ev.query], env, out);

    return { state: S, results: out.results, notes: out.notes, flags: out.flags, delta: diff(prev, S), now: nowText(P, S.clock.t) };
  }

  return { run, DEFAULTS, nowText, fmtDur, diff, clone };
})();

// ===== 10 账本：资源与物品的加减、上下限、多付款方、以物易物、参考价 =====
// 键为「所有者.id」，所有者默认「玩家」。未登记的付款方、收款方、交易对象按外部来源处理：不查余额、不记账。
// 结果只写事实：未结算时写原因和差额，由模型决定接下来怎么写。

GE.ledger = (() => {
  const PLAYER = '玩家';

  const fmt = (v, prec) => {
    const x = Number(v).toFixed(prec || 0);
    const [i, d] = x.split('.');
    const s = i.replace(/\B(?=(\d{3})+(?!\d))/g, ',');
    return d ? s + '.' + d : s;
  };

  function compile(pack, err) {
    const L = { res: {}, items: {}, owners: new Set([PLAYER, '世界']), prices: [], allowNew: !!pack['允许新物品'] };
    (pack['所有者'] || []).forEach(o => L.owners.add(o));
    (pack['资源'] || []).forEach((r, i) => {
      if (!r || !r.id) { err(`资源[${i}].id`, '必填'); return; }
      const over = r['越界'] || '未结算';
      if (!['未结算', '夹取'].includes(over)) err(`资源[${i}].越界`, '只能写「未结算」或「夹取」');
      L.res[r.id] = {
        id: r.id, unit: r['单位'] || '', init: r['初值'] ?? 0, min: r['最小'] ?? null, max: r['最大'] ?? null,
        prec: r['精度'] ?? 0, over, cap: r['单笔上限'] ?? null, owner: r['所有者'] || PLAYER, show: r['显示'] !== false,
        initBy: r['初值按所有者'] || null, time: null,
      };
      const tm = r['随时间'];
      if (tm) {
        const night = GE.cal.parseHM(String(tm['睡觉跨过'] ?? '03:00'));
        if (night === null) err(`资源[${i}].随时间.睡觉跨过`, '写「HH:MM」');
        const num = (k, d) => { const v = Number(tm[k] ?? d); if (!Number.isFinite(v)) err(`资源[${i}].随时间.${k}`, '要写数字'); return Number.isFinite(v) ? v : d; };
        L.res[r.id].time = {
          awake: num('醒着', 0), sleep: num('睡着', 0), night: night ?? 180,
          minSleep: num('睡觉至少', 180), maxNight: num('一晚最多', 480),
        };
      }
    });
    (pack['物品'] || []).forEach((it, i) => {
      if (!it || !it.id) { err(`物品[${i}].id`, '必填'); return; }
      L.items[it.id] = { id: it.id, init: it['初值'] ?? 0, tradable: it['可交易'] !== false };
    });
    (pack['物价'] || []).forEach((p, i) => {
      if (!p || !p['名'] || !Array.isArray(p['价'])) { err(`物价[${i}]`, '要写「名」和「价」区间'); return; }
      L.prices.push({ name: p['名'], lo: p['价'][0], hi: p['价'][1] ?? p['价'][0], places: p['地点'] || [], tags: p['标记'] || [], unit: p['单位'] || '' });
    });
    L.resIds = Object.keys(L.res);
    L.itemIds = Object.keys(L.items);
    L.money = pack['钱'] || (L.res['钱'] ? '钱' : L.resIds[0] || null);
    return L;
  }

  function initState(P, S, over) {
    const L = P.ledger;
    for (const r of Object.values(L.res)) {
      S.res[`${r.owner}.${r.id}`] = r.init;
      if (r.initBy) for (const [who, v] of Object.entries(r.initBy)) S.res[`${who}.${r.id}`] = v;
    }
    for (const it of Object.values(L.items)) if (it.init) S.items[`${PLAYER}.${it.id}`] = it.init;
    if (over && over.res) Object.assign(S.res, over.res);
    if (over && over.items) Object.assign(S.items, over.items);
  }

  const kindOf = (L, target) => (L.res[target] ? 'res' : L.items[target] ? 'item' : null);
  const bucket = (S, kind) => (kind === 'res' ? S.res : S.items);
  const unitOf = (L, target) => (L.res[target] ? L.res[target].unit : '');
  const registered = (L, who) => L.owners.has(who);

  function amountOf(x) {
    const n = typeof x === 'number' ? x : GE.clock.cnNum(String(x ?? '').replace(/[,，日元円￥¥\s]/g, ''));
    return n === null || Number.isNaN(n) ? null : n;
  }

  function limits(L, kind, target) {
    if (kind === 'item') return { min: 0, max: null, prec: 0 };
    const r = L.res[target];
    return { min: r.min, max: r.max, prec: r.prec };
  }
  const round = (v, prec) => GE.expr.tidy(Math.round(v * 10 ** prec) / 10 ** prec);

  function priceFor(L, what, target) {
    const text = `${what || ''} ${target || ''}`;
    return L.prices.find(p => text.includes(p.name)) || null;
  }
  const priceRange = p => `${fmt(p.lo)}–${fmt(p.hi)}${p.unit ? ' ' + p.unit : ''}`;

  // 付款方：['玩家'] / ['同伴', '玩家'] / [{ who, amount }]
  function normPayers(from) {
    let list = from;
    if (list === undefined || list === null || list === '') list = [PLAYER];
    if (!Array.isArray(list)) list = [list];
    return list.map(x => (typeof x === 'string' ? { who: x.trim() || PLAYER } : { who: (x.who || x['谁'] || PLAYER).trim(), amount: x.amount ?? x['金额'] }));
  }

  function spend(P, S, it, env, out) {
    const L = P.ledger, o = env.opts;
    const target = it.target, amount = amountOf(it.amount);
    const base = { 项: '花费', 目标: target, 要求: amount };
    const kind = kindOf(L, target);
    if (!kind) { out.results.push({ ...base, 状态: '未结算：未登记（' + target + '）' }); return; }
    if (amount === null || amount <= 0) { out.results.push({ ...base, 状态: '未结算：数额要大于 0' }); return; }
    const cap = kind === 'res' ? L.res[target].cap : null;
    if (cap !== null && amount > cap) {
      if (env.path === 'fallback') { out.notes.push(`存疑未采纳：花费 ${target} ${amount} 超过单笔上限 ${cap}`); out.results.push({ ...base, 状态: '存疑：超过单笔上限' }); }
      else out.results.push({ ...base, 状态: `未结算：超过单笔上限（${fmt(cap)}）` });
      return;
    }
    if (kind === 'item' && L.items[target] && !L.items[target].tradable && /送|卖|交易|转让|当掉|典当|给/.test(it.what || '')) {
      out.results.push({ ...base, 状态: '未结算：不可交易（' + target + '）' });
      return;
    }
    const { min, prec } = limits(L, kind, target);
    const B = bucket(S, kind);
    const payers = normPayers(it.from);
    // 每个付款方能出多少
    const avail = p => {
      if (!registered(L, p.who)) return Infinity;
      const v = B[`${p.who}.${target}`] || 0;
      const floor = min === null || min === undefined ? -Infinity : min;
      return Math.max(0, v - floor);
    };
    let rest = amount;
    const pay = [];
    let shortWho = null, short = 0;
    payers.forEach((p, i) => {
      const ext = !registered(L, p.who);
      if (ext && o.unknownPayer === 'reject') { shortWho = p.who; short = rest; return; }
      const isLast = i === payers.length - 1;
      const anyAmounts = payers.some(x => x.amount !== undefined);
      let want;
      if (p.amount !== undefined) want = Math.min(amountOf(p.amount) ?? 0, rest);
      else if (anyAmounts || isLast) want = rest;
      else want = Math.min(rest, avail(p));
      if (want <= 0) return;
      const can = Math.min(want, avail(p));
      if (can < want && !shortWho) { shortWho = p.who; short = want - can; }
      pay.push({ who: p.who, amt: can, ext });
      rest -= can;
    });
    if (shortWho && o.unknownPayer === 'reject' && !registered(L, shortWho)) {
      out.results.push({ ...base, 状态: `未结算：付款方未登记（${shortWho}）` });
      return;
    }
    const balances = () => {
      const b = {};
      for (const p of payers) if (registered(L, p.who)) b[p.who] = round(B[`${p.who}.${target}`] || 0, prec);
      return b;
    };
    if (rest > 1e-9) {
      const r = kind === 'res' ? L.res[target] : null;
      if (r && r.over === '夹取' || env.path === 'fallback') {
        // 夹取：能付多少付多少
        for (const p of pay) if (!p.ext) B[`${p.who}.${target}`] = round((B[`${p.who}.${target}`] || 0) - p.amt, prec);
        const paid = amount - rest;
        out.notes.push(`${target} 请求 ${fmt(amount, prec)}，实际 ${fmt(paid, prec)}（夹到下限）`);
        out.results.push({ ...base, 付款: pay.map(p => ({ 谁: p.who, 实际: round(p.amt, prec), ...(p.ext ? { 来源: '外部' } : {}) })), 余额: balances(), 状态: '夹取' });
        return;
      }
      const res = { ...base, 余额: balances(), 差额: round(rest, prec), 状态: `未结算：${kind === 'item' ? '数量不足' : '余额不足'}` };
      if (shortWho && payers.length > 1) res.不足的付款方 = shortWho;
      out.results.push(res);
      return;
    }
    for (const p of pay) if (!p.ext) {
      const k = `${p.who}.${target}`;
      B[k] = round((B[k] || 0) - p.amt, prec);
      if (kind === 'item' && B[k] <= 0) delete B[k];
    }
    const res = { ...base, 付款: pay.map(p => ({ 谁: p.who, 实际: round(p.amt, prec), ...(p.ext ? { 来源: '外部' } : {}) })), 余额: balances(), 状态: '成立' };
    if (it.what) res.用途 = it.what;
    const pr = priceFor(L, it.what, target);
    if (pr) {
      res.参考价 = priceRange(pr);
      if (amount > pr.hi) out.notes.push(`「${pr.name}」报价 ${fmt(amount)} 高于参考价上限 ${fmt(pr.hi)}`);
    }
    out.results.push(res);
  }

  function gain(P, S, it, env, out) {
    const L = P.ledger;
    let target = it.target;
    const amount = amountOf(it.amount);
    const who = (it.to || PLAYER).trim();
    const base = { 项: '获得', 目标: target, 数额: amount };
    let kind = kindOf(L, target);
    if (!kind && L.allowNew && target) { L.items[target] = { id: target, init: 0, tradable: true }; L.itemIds.push(target); kind = 'item'; }
    if (!kind) { out.results.push({ ...base, 状态: '未结算：未登记（' + target + '）' }); return; }
    if (amount === null || amount <= 0) { out.results.push({ ...base, 状态: '未结算：数额要大于 0' }); return; }
    const cap = kind === 'res' ? L.res[target].cap : null;
    if (cap !== null && amount > cap) {
      if (env.path === 'fallback') { out.notes.push(`存疑未采纳：获得 ${target} ${amount} 超过单笔上限 ${cap}`); out.results.push({ ...base, 状态: '存疑：超过单笔上限' }); }
      else out.results.push({ ...base, 状态: `未结算：超过单笔上限（${fmt(cap)}）` });
      return;
    }
    if (!registered(L, who)) { out.results.push({ ...base, 收款: who, 来源: '外部', 状态: '成立：外部，不记账' }); return; }
    const { max, prec } = limits(L, kind, target);
    const B = bucket(S, kind);
    const k = `${who}.${target}`;
    const before = B[k] || 0;
    let after = before + amount;
    let st = '成立';
    if (max !== null && after > max) { after = max; st = '夹取'; }
    B[k] = round(after, prec);
    const res = { ...base, 收款: who, 实际: round(after - before, prec), 余额: B[k], 状态: st };
    if (it.what) res.来源说明 = it.what;
    out.results.push(res);
  }

  // 写明终值：「全部花光」「恢复满」
  function set(P, S, it, env, out) {
    const L = P.ledger;
    const kind = kindOf(L, it.target);
    const who = (it.who || PLAYER).trim();
    let v = amountOf(it.value ?? it.amount);
    if (!kind || v === null) { out.results.push({ 项: '设为', 目标: it.target, 状态: '未结算：' + (!kind ? '未登记' : '数值认不出') }); return; }
    const { min, max, prec } = limits(L, kind, it.target);
    if (min !== null && v < min) v = min;
    if (max !== null && v > max) v = max;
    bucket(S, kind)[`${who}.${it.target}`] = round(v, prec);
    out.results.push({ 项: '设为', 目标: it.target, 值: round(v, prec), 状态: '成立' });
  }

  // 两个资源之间转移，总量守恒（钱 → 存款）
  function transfer(P, S, it, env, out) {
    const L = P.ledger;
    const a = L.res[it.from], b = L.res[it.to];
    const amount = amountOf(it.amount);
    const who = (it.who || PLAYER).trim();
    if (!a || !b) { out.results.push({ 项: '转移', 状态: '未结算：未登记' }); return; }
    const ka = `${who}.${a.id}`, kb = `${who}.${b.id}`;
    const va = S.res[ka] || 0, vb = S.res[kb] || 0;
    if (amount === null || amount <= 0) { out.results.push({ 项: '转移', 状态: '未结算：数额要大于 0' }); return; }
    if (a.min !== null && va - amount < a.min) { out.results.push({ 项: '转移', 从: a.id, 到: b.id, 余额: va, 差额: amount - (va - a.min), 状态: '未结算：余额不足' }); return; }
    if (b.max !== null && vb + amount > b.max) { out.results.push({ 项: '转移', 从: a.id, 到: b.id, 状态: '未结算：超过上限' }); return; }
    S.res[ka] = round(va - amount, a.prec);
    S.res[kb] = round(vb + amount, b.prec);
    out.results.push({ 项: '转移', 从: a.id, 到: b.id, 数额: amount, 状态: '成立' });
  }

  function trade(P, S, it, env, out) {
    const L = P.ledger;
    const other = (it.with || '').trim();
    const give = (it.give || []).map(x => ({ target: x.target, n: amountOf(x.amount) ?? 1 }));
    const get = (it.get || []).map(x => ({ target: x.target, n: amountOf(x.amount) ?? 1 }));
    const base = { 项: '交易', 对象: other || '（未写）' };
    const fail = why => out.results.push({ ...base, 状态: '未结算：' + why });
    for (const g of give) {
      const kind = kindOf(L, g.target);
      if (!kind) return fail('未登记（' + g.target + '）');
      if (kind === 'item' && !L.items[g.target].tradable) return fail('不可交易：' + g.target);
      const have = bucket(S, kind)[`${PLAYER}.${g.target}`] || 0;
      if (have < g.n) return fail(`数量不足：${g.target} 有 ${have}，要 ${g.n}`);
    }
    for (const g of get) {
      if (!kindOf(L, g.target) && !L.allowNew) return fail('未登记（' + g.target + '）');
    }
    const otherReg = other && registered(L, other) && other !== PLAYER;
    if (otherReg) {
      for (const g of get) {
        const kind = kindOf(L, g.target) || 'item';
        const have = bucket(S, kind)[`${other}.${g.target}`] || 0;
        if (have < g.n) return fail(`${other} 的 ${g.target} 不够：有 ${have}，要 ${g.n}`);
      }
    }
    const mv = (who, target, n) => {
      let kind = kindOf(L, target);
      if (!kind) { L.items[target] = { id: target, init: 0, tradable: true }; L.itemIds.push(target); kind = 'item'; }
      const B = bucket(S, kind);
      const k = `${who}.${target}`;
      B[k] = (B[k] || 0) + n;
      if (kind === 'item' && B[k] <= 0) delete B[k];
    };
    for (const g of give) { mv(PLAYER, g.target, -g.n); if (otherReg) mv(other, g.target, g.n); }
    for (const g of get) { mv(PLAYER, g.target, g.n); if (otherReg) mv(other, g.target, -g.n); }
    out.results.push({
      ...base,
      交出: give.map(g => `${g.target} ×${g.n}`).join('、'),
      换来: get.map(g => `${g.target} ×${g.n}`).join('、'),
      ...(otherReg ? {} : { 对方: '外部，不记账' }),
      状态: '成立',
    });
  }

  // 玩家可见的资源一览：{ 钱: '8,300 日元', 体力: '62/100' }
  function summary(P, S, who) {
    const L = P.ledger;
    who = who || PLAYER;
    const o = {};
    for (const r of Object.values(L.res)) {
      if (!r.show) continue;
      const v = S.res[`${who}.${r.id}`];
      if (v === undefined) continue;
      o[r.id] = r.max !== null ? `${fmt(v, r.prec)}/${fmt(r.max, r.prec)}` : `${fmt(v, r.prec)}${r.unit ? ' ' + r.unit : ''}`;
    }
    for (const [k, v] of Object.entries(S.items)) if (k.startsWith(who + '.')) o[k.slice(who.length + 1)] = `×${v}`;
    return o;
  }

  function priceText(P, name) {
    const p = P.ledger.prices.find(x => x.name === name) || P.ledger.prices.find(x => x.name.includes(name) || name.includes(x.name));
    return p ? `${p.name} ${priceRange(p)}` : '';
  }

  // 当前地点相关的参考价：地点名对上，或地点的标记（livehouse、咖啡店……）对上
  function pricesAt(P, loc, n) {
    if (!loc) return [];
    const node = P.on.map && P.map.nodes[loc];
    const tags = node ? node.tags : [];
    return P.ledger.prices
      .filter(p => p.places.includes(loc) || p.tags.some(t => tags.includes(t)))
      .slice(0, n).map(p => `${p.name} ${priceRange(p)}`);
  }

  // 账本里的数（给注入、ge_view、宿主写回）
  function value(P, S, id, who) { return S.res[`${who || PLAYER}.${id}`]; }

  // 规则包后来才登记的资源，旧存档里没有：按初值补上（不然第一笔花费从 0 扣起）
  function missing(P, S) {
    return Object.values(P.ledger.res).some(r => S.res[`${r.owner}.${r.id}`] === undefined);
  }
  function fillMissing(P, S) {
    for (const r of Object.values(P.ledger.res)) {
      const k = `${r.owner}.${r.id}`;
      if (S.res[k] === undefined) S.res[k] = r.init;
    }
  }

  // 随时间变的资源（体力）：醒着按小时加减，睡着按小时加减。一次推进跨过「睡觉跨过」那一刻、又不短于「睡觉至少」，
  // 就算睡了：跨过几次算几晚，每晚最多「一晚最多」分钟，其余算醒着。不够一个精度单位的零头攒在 S.carry 里，下次接着算
  function passTime(P, prev, S, out) {
    const a = prev.clock.t, b = S.clock.t;
    if (a === null || a === undefined || b === null || b === undefined || b <= a) return;
    const span = b - a, DAY = GE.cal.DAY;
    for (const r of Object.values(P.ledger.res)) {
      const tm = r.time;
      if (!tm) continue;
      const k = `${r.owner}.${r.id}`;
      const nights = Math.max(0, Math.floor((b - tm.night) / DAY) - (Math.floor((a - tm.night) / DAY) + 1) + 1);
      const slept = span >= tm.minSleep && nights > 0 ? Math.min(span, nights * tm.maxNight) : 0;
      S.carry = S.carry || {};
      const raw = (slept * tm.sleep + (span - slept) * tm.awake) / 60 + (S.carry[k] || 0);
      const before = S.res[k] ?? r.init;
      let want = GE.expr.tidy(before + raw), clamped = false;
      if (r.min !== null && want < r.min) { want = r.min; clamped = true; }
      if (r.max !== null && want > r.max) { want = r.max; clamped = true; }
      const after = round(Math.trunc(want * 10 ** r.prec) / 10 ** r.prec, r.prec);
      S.carry[k] = clamped ? 0 : GE.expr.tidy(want - after);
      S.res[k] = after;
      if (after !== before) {
        const res = { 项: '随时间', 目标: r.id, 变化: round(after - before, r.prec), 余额: after, 状态: clamped ? '夹取' : '成立' };
        if (slept) res.睡着 = GE.settle.fmtDur(slept);
        out.results.push(res);
      }
    }
  }

  return { compile, initState, spend, gain, set, transfer, trade, summary, priceText, pricesAt, value, fmt, amountOf, missing, fillMissing, passTime, PLAYER };
})();

// ===== 11 关系：维度、阶段与滞回；可选的单楼上限与负向系数 =====
// 单楼上限、负向系数会改写模型报上来的变化量，属于作者规则，默认不启用；启用后返回「要求、上限、实际」。
// 阶段按阈值与滞回判定：往上到阈值就进，往下要低于「阈值 − 滞回」才退。

GE.relation = (() => {
  function compile(list, pack, err) {
    const R = { dims: [], chars: pack['关系角色'] || null, initBy: pack['关系初值'] || {} };
    (Array.isArray(list) ? list : []).forEach((d, i) => {
      if (!d || !d.id) { err(`关系[${i}].id`, '必填'); return; }
      const range = d['范围'] || [0, 100];
      const stages = (d['阶段'] || []).map(s => ({ name: s['名'], start: s['起'] })).sort((a, b) => a.start - b.start);
      R.dims.push({
        id: d.id, min: range[0], max: range[1], init: d['初值'] ?? 50, stages,
        hyst: d['滞回'] ?? 2, decay: d['回归'] ?? 0,
        cap: d['单楼上限'] ?? null, negK: d['负向系数'] ?? 1, show: d['显示'] !== false,
      });
    });
    if (!R.dims.length) err('关系', '至少要一个维度');
    return R;
  }

  function stageOf(dim, v, cur) {
    if (!dim.stages.length) return '';
    let cand = dim.stages[0];
    for (const s of dim.stages) if (s.start <= v) cand = s;
    if (!cur) return cand.name;
    const ci = dim.stages.findIndex(s => s.name === cur);
    const ni = dim.stages.indexOf(cand);
    if (ci < 0 || ni >= ci) return cand.name;
    // 往下退：低于「当前阶段阈值 − 滞回」才退，退到按阈值应在的那一档
    return v < dim.stages[ci].start - dim.hyst ? cand.name : cur;
  }

  function ensure(P, S, who) {
    if (!S.rel[who]) {
      const o = { _stage: {} };
      for (const d of P.relation.dims) {
        const v = (P.relation.initBy[who] || {})[d.id] ?? d.init;
        o[d.id] = v;
        o._stage[d.id] = stageOf(d, v, null);
      }
      S.rel[who] = o;
    }
    return S.rel[who];
  }

  function initState(P, S, over) {
    for (const who of P.relation.chars || []) ensure(P, S, who);
    for (const who of Object.keys(P.relation.initBy)) ensure(P, S, who);
    if (over && over.rel) {
      for (const [who, dims] of Object.entries(over.rel)) {
        const o = ensure(P, S, who);
        for (const [k, v] of Object.entries(dims)) {
          const d = P.relation.dims.find(x => x.id === k);
          if (d && typeof v === 'number') { o[k] = v; o._stage[k] = stageOf(d, v, null); }
        }
      }
    }
  }

  function settle(P, S, list, env, out) {
    const R = P.relation;
    // 同一角色同一维度先合并（有负向系数时负的先乘系数）
    const groups = new Map();
    for (const it of list || []) {
      const who = String(it.who || '').trim();
      const dim = R.dims.find(d => d.id === it.dim);
      const delta = GE.ledger.amountOf(it.delta);
      if (!who) { out.results.push({ 项: '关系', 状态: '未结算：没写角色' }); continue; }
      if (!dim) { out.results.push({ 项: '关系', 角色: who, 维度: it.dim, 状态: '未结算：未登记的维度（' + it.dim + '）' }); continue; }
      if (R.chars && !R.chars.includes(who)) { out.results.push({ 项: '关系', 角色: who, 状态: '未结算：未登记的角色（' + who + '）' }); continue; }
      if (delta === null) { out.results.push({ 项: '关系', 角色: who, 维度: dim.id, 状态: '未结算：变化量认不出' }); continue; }
      const k = who + '\u0000' + dim.id;
      const g = groups.get(k) || { who, dim, req: 0, eff: 0, why: [] };
      g.req += delta;
      g.eff += delta < 0 ? delta * dim.negK : delta;
      if (it.why) g.why.push(it.why);
      groups.set(k, g);
    }
    for (const g of groups.values()) {
      const o = ensure(P, S, g.who);
      const d = g.dim;
      let eff = g.eff, st = '成立';
      const res = { 项: '关系', 角色: g.who, 维度: d.id, 要求: GE.expr.tidy(g.req) };
      if (d.cap !== null && Math.abs(eff) > d.cap) { res.上限 = d.cap; eff = Math.sign(eff) * d.cap; st = '夹取'; }
      const before = o[d.id];
      let after = Math.min(d.max, Math.max(d.min, before + eff));
      if (after !== before + eff) st = '夹取';
      after = GE.expr.tidy(after);
      o[d.id] = after;
      const prevStage = o._stage[d.id];
      o._stage[d.id] = stageOf(d, after, prevStage);
      res.变化 = GE.expr.tidy(after - before);
      res.现值 = after;
      if (o._stage[d.id]) res.阶段 = o._stage[d.id];
      if (g.why.length) res.原因 = g.why.join('；');
      res.状态 = st;
      out.results.push(res);
      if (prevStage !== o._stage[d.id]) out.flags.push({ kind: 'stage', who: g.who, dim: d.id, from: prevStage, to: o._stage[d.id] });
    }
  }

  // 每过一天向初值回归（回归为 0 的维度不动）
  function decay(P, prev, S) {
    if (prev.clock.t === null || S.clock.t === null) return;
    const days = Math.floor(S.clock.t / GE.cal.DAY) - Math.floor(prev.clock.t / GE.cal.DAY);
    if (days <= 0) return;
    for (const [who, o] of Object.entries(S.rel)) {
      for (const d of P.relation.dims) {
        if (!d.decay) continue;
        const base = (P.relation.initBy[who] || {})[d.id] ?? d.init;
        const v = o[d.id];
        const step = d.decay * days;
        o[d.id] = v > base ? Math.max(base, v - step) : Math.min(base, v + step);
        o._stage[d.id] = stageOf(d, o[d.id], o._stage[d.id]);
      }
    }
  }

  // 「角色甲：好感 61（熟识）、信任 48（普通）」
  function line(P, S, who, mode) {
    const o = S.rel[who];
    if (!o) return '';
    const parts = P.relation.dims.filter(d => d.show).map(d => {
      const v = o[d.id], st = o._stage[d.id];
      if (mode === '阶段') return `${d.id} ${st || v}`;
      if (mode === '数值' || !st) return `${d.id} ${v}`;
      return `${d.id} ${v}（${st}）`;
    });
    return `${who}：${parts.join('、')}`;
  }

  return { compile, initState, settle, decay, line, stageOf, ensure };
})();

// ===== 12 地图与距离：地点、路、方式、最短路、耗时、车费 =====
// 方式的结算顺序：登记 → 谁 → 条件 → 运营时间 → 冷却 → 只到标记 → 求路 → 最小/最大距离 → 车费与消耗。
// 任何一步不满足，返回「未结算」和那一步的事实，不移动、不扣钱。
// 电车走 12_rail（按线路与车站算），其余方式走这里的路网。

GE.map = (() => {
  const R_EARTH = 6371000;

  // ---- 小工具 ----
  const norm = s => GE.clock.toHalf(String(s || '')).toLowerCase().replace(/[\s・·•／/、,，()（）「」『』"“”']/g, '');

  function geoDist(a, b) {
    const la = ((a[1] + b[1]) / 2) * Math.PI / 180;
    const dx = (b[0] - a[0]) * Math.PI / 180 * Math.cos(la) * R_EARTH;
    const dy = (b[1] - a[1]) * Math.PI / 180 * R_EARTH;
    return Math.hypot(dx, dy);
  }

  function straight(M, a, b) {
    const A = M.nodes[a], B = M.nodes[b];
    if (!A || !B) return null;
    if (A.ll && B.ll) return geoDist(A.ll, B.ll);
    if (A.xy && B.xy) return Math.hypot(A.xy[0] - B.xy[0], A.xy[1] - B.xy[1]);
    return null;
  }

  // 二叉堆
  function heap() {
    const a = [];
    return {
      size: () => a.length,
      push(k, v) {
        a.push([k, v]);
        let i = a.length - 1;
        while (i > 0) { const p = (i - 1) >> 1; if (a[p][0] <= a[i][0]) break; [a[p], a[i]] = [a[i], a[p]]; i = p; }
      },
      pop() {
        const top = a[0], last = a.pop();
        if (a.length) {
          a[0] = last;
          let i = 0;
          for (;;) {
            const l = 2 * i + 1, r = l + 1;
            let m = i;
            if (l < a.length && a[l][0] < a[m][0]) m = l;
            if (r < a.length && a[r][0] < a[m][0]) m = r;
            if (m === i) break;
            [a[m], a[i]] = [a[i], a[m]];
            i = m;
          }
        }
        return top;
      },
    };
  }

  const parseClock = s => {
    if (s === undefined || s === null) return null;
    const m = /^(\d{1,2}):(\d{2})$/.exec(String(s).trim());
    return m ? +m[1] * 60 + +m[2] : null;
  };
  const inWindow = (mod, w) => {
    if (!w) return true;
    const [a, b] = w;
    return a <= b ? mod >= a && mod <= b : mod >= a || mod <= b;
  };

  // ---- 编译 ----
  function compileMode(x, i, err) {
    if (!x || !x['名']) { err(`地图.方式[${i}].名`, '必填'); return null; }
    const mode = {
      name: x['名'],
      mpm: x['米每分'] ?? null,
      extra: x['附加分钟'] ?? 0,
      fixed: x['固定分钟'] ?? null,
      ignoreNet: !!x['无视路网'],
      factor: x['直线系数'] ?? 1,
      maxDist: x['最大距离'] ?? null,
      minDist: x['最小距离'] ?? null,
      onlyTag: x['只到标记'] || null,
      who: x['谁'] ? [].concat(x['谁']) : null,
      cond: x['条件'] || null,
      condText: x['条件说明'] || null,
      cost: x['消耗'] || null,
      cooldown: null,
      hours: x['运营时间'] ? [parseClock(x['运营时间'][0]), parseClock(x['运营时间'][1])] : null,
      climbK: x['爬坡系数'] ?? 0,
      fare: x['车费'] || null,
      rail: !!x['铁道'],
      payRes: x['付款资源'] || null,
    };
    if (x['冷却']) {
      const p = GE.clock.parse(x['冷却']);
      if (!p || p.elapsed === undefined) err(`地图.方式[${i}].冷却`, '写成时长，例如「6小时」');
      else mode.cooldown = p.elapsed;
    }
    if (mode.mpm === null && mode.fixed === null && !mode.rail) err(`地图.方式[${i}]`, '「米每分」「固定分钟」「铁道」至少写一样');
    if (mode.hours && (mode.hours[0] === null || mode.hours[1] === null)) err(`地图.方式[${i}].运营时间`, '写成 ["05:00", "00:30"]');
    return mode;
  }

  function compile(m, err) {
    const M = { nodes: {}, alias: new Map(), adj: {}, modes: [], straightFactor: m['无路时按直线'] ?? null };
    (m['节点'] || []).forEach((n, i) => {
      if (!n || !n.id) { err(`地图.节点[${i}].id`, '必填'); return; }
      M.nodes[n.id] = {
        id: n.id, aliases: n['别名'] || [], tags: n['标记'] || [],
        ll: n['坐标'] && n['坐标'].length === 2 && Math.abs(n['坐标'][0]) <= 180 && !n['平面'] ? n['坐标'] : null,
        xy: n['平面'] || null, ele: n['海拔'] ?? null, area: n['片区'] || '',
      };
      M.adj[n.id] = [];
    });
    for (const n of Object.values(M.nodes)) {
      for (const a of [n.id, ...n.aliases]) {
        const k = norm(a);
        if (!k) continue;
        if (M.alias.has(k) && M.alias.get(k) !== n.id) M.alias.set(k, null); // 重名：不猜
        else M.alias.set(k, n.id);
      }
    }
    (m['边'] || []).forEach((e, i) => {
      const a = e['从'], b = e['到'];
      if (!M.nodes[a] || !M.nodes[b]) { err(`地图.边[${i}]`, `两端要是已登记的节点（${a} → ${b}）`); return; }
      const ed = { m: e['米'] ?? null, min: e['分钟'] ?? null, modes: e['方式'] || null };
      if (ed.m === null && ed.min === null) {
        const s = straight(M, a, b);
        if (s === null) { err(`地图.边[${i}]`, '要写「米」或「分钟」'); return; }
        ed.m = s;
      }
      M.adj[a].push({ to: b, ...ed });
      if (!e['单向']) M.adj[b].push({ to: a, ...ed });
    });
    (m['方式'] || [{ 名: '步行', 米每分: 80 }]).forEach((x, i) => { const md = compileMode(x, i, err); if (md) M.modes.push(md); });
    M.defaultMode = m['默认方式'] || (M.modes[0] && M.modes[0].name);
    M.payRes = m['车费资源'] || null;
    if (m['铁道']) M.rail = GE.rail.compile(m['铁道'], M, err);
    return M;
  }

  // 编译之后再加一个地点（房产的住宅区这类）：别名和已有的撞了就两边都不认，同编译时一样
  function addNode(M, n) {
    if (!n || !n.id || M.nodes[n.id]) return false;
    M.nodes[n.id] = {
      id: n.id, aliases: n['别名'] || [], tags: n['标记'] || [],
      ll: n['坐标'] && n['坐标'].length === 2 ? n['坐标'] : null, xy: null, ele: n['海拔'] ?? null, area: n['片区'] || '',
    };
    M.adj[n.id] = [];
    for (const a of [n.id, ...M.nodes[n.id].aliases]) {
      const k = norm(a);
      if (!k) continue;
      if (M.alias.has(k) && M.alias.get(k) !== n.id) M.alias.set(k, null);
      else M.alias.set(k, n.id);
    }
    return true;
  }

  // ---- 认地点 ----
  // 先认整串（id、别名），再按分隔符切段逐段认，最后认「名字至少 3 个字且被整串包含」；只认唯一命中，有歧义不猜。
  function resolve(M, text) {
    if (!text) return null;
    const whole = norm(text);
    if (M.alias.has(whole)) return M.alias.get(whole);
    const segs = GE.clock.toHalf(String(text)).split(/[・·/、,，>›\s]+/).map(norm).filter(Boolean);
    const hits = new Set();
    for (const s of segs) if (M.alias.get(s)) hits.add(M.alias.get(s));
    if (hits.size === 1) return [...hits][0];
    if (hits.size > 1) return null;
    for (const [k, id] of M.alias) if (id && k.length >= 3 && whole.includes(k)) hits.add(id);
    return hits.size === 1 ? [...hits][0] : null;
  }

  // 认存档里的地点：房产记着住处时，「家」「回家」「自己家」和住处的门牌认成住处所在的地点（住宅区、角色家）；
  // 其余先认节点 id（别名撞车时 resolve 会不认），再照规则包认
  function placeOf(P, S, text) {
    if (!text) return null;
    if (P.on.estate && S) {
      const h = GE.estate.homeNode(P, S, text);
      if (h) return h;
    }
    const M = P.map;
    return M.nodes[text] ? text : resolve(M, text);
  }

  // ---- 求路（非铁道方式）----
  function edgeMinutes(M, e, from, mode) {
    let t = e.min !== null ? e.min : (mode.mpm ? e.m / mode.mpm : Infinity);
    if (mode.climbK && e.min === null) {
      const A = M.nodes[from], B = M.nodes[e.to];
      if (A.ele !== null && B.ele !== null && B.ele > A.ele) t += (B.ele - A.ele) / 10 * mode.climbK;
    }
    return t;
  }

  function dijkstra(M, a, b, mode) {
    const dist = { [a]: 0 }, meters = { [a]: 0 }, prev = {};
    const h = heap();
    h.push(0, a);
    while (h.size()) {
      const [d, u] = h.pop();
      if (u === b) break;
      if (d > dist[u]) continue;
      for (const e of M.adj[u] || []) {
        if (e.modes && !e.modes.includes(mode.name)) continue;
        const w = edgeMinutes(M, e, u, mode);
        if (!Number.isFinite(w)) continue;
        const nd = d + w;
        if (dist[e.to] === undefined || nd < dist[e.to]) {
          dist[e.to] = nd;
          meters[e.to] = meters[u] + (e.m ?? 0);
          prev[e.to] = u;
          h.push(nd, e.to);
        }
      }
    }
    if (dist[b] === undefined) return null;
    const path = [b];
    while (path[0] !== a) path.unshift(prev[path[0]]);
    return { minutes: dist[b], meters: meters[b], path };
  }

  // 一种方式从 a 到 b：{ ok, meters, minutes, note, legs } 或 { ok:false, why }
  function travel(P, S, env, a, b, mode) {
    const M = P.map;
    const sd = straight(M, a, b);
    if (mode.rail) {
      if (!M.rail) return { ok: false, why: '没有登记铁道' };
      const r = GE.rail.route(P, a, b, S.clock.t);
      if (!r.ok) return r;
      return { ok: true, meters: r.meters, minutes: r.minutes + mode.extra, legs: r.legs, fare: r.fare, walkM: r.walkM, straightM: sd };
    }
    if (mode.ignoreNet || mode.fixed !== null) {
      if (mode.fixed !== null) return { ok: true, meters: sd ?? 0, minutes: mode.fixed + mode.extra, straightM: sd };
      if (sd === null) return { ok: false, why: '两地没有坐标，算不出直线距离' };
      const m = sd * mode.factor;
      return { ok: true, meters: m, minutes: m / mode.mpm + mode.extra, straightM: sd };
    }
    const r = dijkstra(M, a, b, mode);
    if (r) return { ok: true, meters: r.meters, minutes: r.minutes + mode.extra, path: r.path, straightM: sd };
    if (M.straightFactor && sd !== null && mode.mpm) {
      const m = sd * M.straightFactor;
      let min = m / mode.mpm + mode.extra;
      if (mode.climbK) {
        const A = M.nodes[a], B = M.nodes[b];
        if (A.ele !== null && B.ele !== null && B.ele > A.ele) min += (B.ele - A.ele) / 10 * mode.climbK;
      }
      return { ok: true, meters: m, minutes: min, note: '路网上没有这段路，按直线距离估算', straightM: sd };
    }
    return { ok: false, why: '无路' };
  }

  // ---- 车费 ----
  function fareOf(fare, meters, depMod) {
    if (!fare) return 0;
    const km = meters / 1000;
    const t = fare['类型'];
    if (t === '固定') return fare['价'];
    if (t === '距离段') {
      for (const [lim, price] of fare['段']) if (km <= lim) return price;
      const last = fare['段'][fare['段'].length - 1];
      return fare['超出每公里'] ? last[1] + Math.ceil(km - last[0]) * fare['超出每公里'] : last[1];
    }
    if (t === '出租') {
      let p = fare['起步价'];
      const over = meters - fare['起步米'];
      if (over > 0) p += Math.ceil(over / fare['每段米']) * fare['每段价'];
      const n = fare['夜间'];
      if (n && inWindow(depMod, [parseClock(n['从']), parseClock(n['到'])])) p = Math.round(p * (1 + n['加成']) / 10) * 10;
      return p;
    }
    return 0;
  }

  // ---- 方式检查（不含求路）----
  function precheck(P, S, env, mode, destId) {
    const M = P.map;
    const who = (env.mover || GE.ledger.PLAYER);
    if (mode.who && !mode.who.includes(who) && !(who === GE.ledger.PLAYER && mode.who.includes('玩家'))) return '只有' + mode.who.join('、') + '能用';
    if (mode.cond) {
      const r = GE.expr.test(mode.cond, name => GE.rules.lookup(P, S, env, name));
      if (!r.ok) return '条件不满足（' + r.err + '）';
      if (!r.value) return '条件不满足' + (mode.condText ? '：' + mode.condText : '');
    }
    if (mode.hours && S.clock.t !== null) {
      const mod = GE.cal.minuteOfDay(S.clock.t);
      if (!inWindow(mod, mode.hours)) return `不在运营时间（${GE.cal.hm(mode.hours[0])}–${GE.cal.hm(mode.hours[1])}）`;
    }
    const cd = S.cool[mode.name];
    if (cd && S.clock.t < cd) return '冷却中，还剩 ' + GE.settle.fmtDur(cd - S.clock.t);
    if (mode.onlyTag && destId && !(M.nodes[destId].tags || []).includes(mode.onlyTag)) return `目的地没有「${mode.onlyTag}」标记`;
    return null;
  }

  function payFor(P, S, mode, meters, minutes) {
    // 返回 [{ res, amount, why }]
    const list = [];
    const depMod = S.clock.t === null ? 0 : GE.cal.minuteOfDay(S.clock.t);
    const money = mode.payRes || P.map.payRes || (P.on.ledger ? P.ledger.money : null);
    if (mode.fare && money) {
      const f = fareOf(mode.fare, meters, depMod);
      if (f) list.push({ res: money, amount: f, why: '车费' });
    }
    if (mode.cost && P.on.ledger) {
      const c = mode.cost;
      const amt = (c['每次'] || 0) + (c['每公里'] || 0) * meters / 1000;
      if (amt) list.push({ res: c['资源'], amount: Math.ceil(amt), why: '消耗' });
    }
    void minutes;
    return list;
  }

  function canPay(P, S, list) {
    for (const x of list) {
      const r = P.ledger && P.ledger.res[x.res];
      if (!r) return `未登记的资源（${x.res}）`;
      const v = S.res[`${GE.ledger.PLAYER}.${x.res}`] || 0;
      const floor = r.min ?? -Infinity;
      if (v - x.amount < floor) return `${x.res} ${GE.ledger.fmt(v, r.prec)}，需要 ${GE.ledger.fmt(x.amount, r.prec)}`;
    }
    return null;
  }

  function findMode(M, by) {
    if (!by) return M.modes.find(m => m.name === M.defaultMode) || M.modes[0];
    const k = norm(by);
    return M.modes.find(m => norm(m.name) === k) || M.modes.find(m => k.includes(norm(m.name)) || norm(m.name).includes(k)) || null;
  }

  // 一种方式的完整评估（不改状态）
  function evaluate(P, S, env, a, b, mode) {
    const pre = precheck(P, S, env, mode, b);
    if (pre) return { ok: false, why: pre };
    // 距离限制：两地有坐标时按直线距离，先查再求路；没有坐标时按求出的路程
    const limit = d => {
      if (mode.minDist !== null && d < mode.minDist) return `距离不到 ${(mode.minDist / 1000).toFixed(1)} km`;
      if (mode.maxDist !== null && d > mode.maxDist) return `超出距离（最远 ${(mode.maxDist / 1000).toFixed(1)} km）`;
      return null;
    };
    const sd = straight(P.map, a, b);
    if (sd !== null && limit(sd)) return { ok: false, why: limit(sd) };
    const r = travel(P, S, env, a, b, mode);
    if (!r.ok) return r;
    if (sd === null && limit(r.meters)) return { ok: false, why: limit(r.meters) };
    // 没注册账本时车费只报数、不扣
    const pays = P.on.ledger ? payFor(P, S, mode, r.meters, r.minutes) : [];
    const money = P.map.payRes || (P.on.ledger ? P.ledger.money : null);
    if (r.fare && money && P.on.ledger) pays.unshift({ res: money, amount: r.fare, why: '车费' });
    const fareOnly = !P.on.ledger ? (r.fare || fareOf(mode.fare, r.meters, S.clock.t === null ? 0 : GE.cal.minuteOfDay(S.clock.t))) : 0;
    const lack = P.on.ledger ? canPay(P, S, pays) : null;
    return { ...r, minutes: Math.max(1, Math.round(r.minutes)), pays, lack, fareOnly };
  }

  const kmText = m => (m >= 1000 ? (m / 1000).toFixed(1) + ' km' : Math.round(m) + ' m');

  function settleMove(P, S, mv, env, out) {
    const M = P.map, o = env.opts;
    const res = { 项: '移动' };
    // 所在地可能是宿主同步来的原文（「池袋站东口」）：先认成地图上的地点
    const fromId = S.loc ? placeOf(P, S, S.loc) : null;
    const toId = placeOf(P, S, mv.to);
    res.从 = S.loc || '（未设）';
    res.到 = toId || mv.to;
    const advance = min => {
      if (S.clock.t === null || !min) return;
      const t0 = S.clock.t;
      S.clock.t += Math.round(min);
      res.出发 = GE.cal.hm(GE.cal.minuteOfDay(t0));
      res.到达 = GE.cal.hm(GE.cal.minuteOfDay(S.clock.t));
    };
    const place = id => { if (o.locSource !== 'host') S.loc = id; };
    const capMin = () => Math.min(GE.ledger.amountOf(mv.minutes) ?? 0, o.unknownMinutesCap);

    let mode = findMode(M, mv.by);
    if (!mode) {
      // 方式没登记
      if (o.unknownMode === 'reject') { out.results.push({ ...res, 方式: mv.by, 状态: '未结算：未登记的方式（' + mv.by + '）' }); return; }
      out.flags.push({ kind: 'unknownMode', name: mv.by });
      out.notes.push(`未登记方式：${mv.by}`);
      if (o.unknownMode === 'minutes' && mv.minutes) { advance(capMin()); res.耗时 = capMin() + ' 分钟（模型给的）'; }
      else res.耗时 = '不计时';
      place(toId || mv.to);
      out.results.push({ ...res, 方式: mv.by, 状态: '成立：未登记方式' });
      return;
    }
    res.方式 = mode.name;
    if (!toId) {
      if (o.unknownPlace === 'reject') { out.results.push({ ...res, 状态: '未结算：未登记的地点（' + mv.to + '）' }); return; }
      out.notes.push(`未登记地点：${mv.to}`);
      if (o.unknownPlace === 'minutes' && mv.minutes) { advance(capMin()); res.耗时 = capMin() + ' 分钟（模型给的）'; }
      else res.耗时 = '不计时';
      place(mv.to);
      out.results.push({ ...res, 状态: '成立：未登记地点' });
      return;
    }
    if (!fromId) {
      place(toId);
      out.results.push({ ...res, 耗时: '不计时', 状态: '成立：起点未设，只换地点' });
      return;
    }
    if (fromId === toId) { out.results.push({ ...res, 状态: '成立：已在此地' }); return; }
    const ev = evaluate(P, S, env, fromId, toId, mode);
    if (!ev.ok) { out.results.push({ ...res, 状态: '未结算：' + ev.why }); return; }
    if (ev.lack) { out.results.push({ ...res, 路程: kmText(ev.meters), 耗时: ev.minutes + ' 分钟', 状态: '未结算：' + ev.lack }); return; }
    // 成立：扣钱、推进时间、换地点、记冷却
    for (const p of ev.pays) {
      const r = P.ledger.res[p.res];
      const k = `${GE.ledger.PLAYER}.${p.res}`;
      S.res[k] = GE.expr.tidy((S.res[k] || 0) - p.amount);
      res[p.why] = p.amount;
      res['余额'] = GE.ledger.fmt(S.res[k], r.prec) + (r.unit ? ' ' + r.unit : '');
    }
    res.路程 = kmText(ev.meters);
    res.耗时 = ev.minutes + ' 分钟';
    if (ev.fareOnly) res.车费 = ev.fareOnly;
    if (ev.legs) res.线路 = GE.rail.legsText(ev.legs);
    if (ev.note) out.notes.push(ev.note);
    const t0 = S.clock.t;
    advance(ev.minutes);
    place(toId);
    // 记下这一趟：所在地写成「电车上」「去 RiNG 的路上」这类时，locate 按它算人在路线上的哪儿
    S.trip = { from: fromId, to: toId, by: mode.name, t0, t1: S.clock.t };
    if (mode.cooldown) S.cool[mode.name] = S.clock.t + mode.cooldown;
    out.results.push({ ...res, 状态: '成立' });
  }

  // 查询：两地之间每种方式各要多久、多少钱、能不能用
  function query(P, S, env, a, b, detailed) {
    const M = P.map;
    const here = S.loc ? placeOf(P, S, S.loc) : null;
    const A = a ? placeOf(P, S, a) : here;
    const B = placeOf(P, S, b || a);
    const from = b ? A : here;
    const res = { 项: '查询', 查: detailed ? '路线' : '距离', 从: from || a, 到: B || b || a };
    if (!from || !B) { res.状态 = '未结算：认不出地点'; return res; }
    const sd = straight(M, from, B);
    if (sd !== null) res.直线 = kmText(sd);
    res.方式 = M.modes.map(mode => {
      const ev = evaluate(P, S, env, from, B, mode);
      if (!ev.ok) return { 方式: mode.name, 状态: '不可用：' + ev.why };
      const o = { 方式: mode.name, 耗时: ev.minutes + ' 分钟', 路程: kmText(ev.meters) };
      const money = ev.pays.filter(p => p.why === '车费').reduce((s, p) => s + p.amount, 0) || ev.fareOnly;
      if (money) o.车费 = money;
      if (detailed && ev.legs) o.线路 = GE.rail.legsText(ev.legs);
      if (ev.lack) o.状态 = '钱不够：' + ev.lack;
      return o;
    });
    return res;
  }

  // ---- 路线的形状（给地图画线）：只算不改，不看运营时间、钱和冷却 ----
  // 铁道：从出发地走到上车站 → 各段途经的车站 → 换乘 → 从下车站走到目的地；
  // 其余方式：路网上途经的节点（宿主拿去再细化成街道）；路网上没有这段路、或方式本来就按直线算，只给两端，标「估算」
  function geometry(P, S, env, a, b, by) {
    const M = P.map;
    const here = S.loc ? placeOf(P, S, S.loc) : null;
    const 认 = x => placeOf(P, S, x);
    const A = a ? 认(a) : here, B = 认(b);
    if (!A || !B) return { 状态: '认不出地点' };
    if (A === B) return { 从: A, 到: B, 状态: '已在此地' };
    const mode = findMode(M, by);
    if (!mode) return { 从: A, 到: B, 状态: '没有这种方式（' + by + '）' };
    const ll = id => (M.nodes[id] && M.nodes[id].ll) || null;
    const out = { 从: A, 到: B, 方式: mode.name, 段: [], 估算: false };
    const two = why => {
      out.估算 = true;
      if (why) out.状态 = why;
      if (ll(A) && ll(B)) out.段.push({ 类: '直线', 点: [ll(A), ll(B)] });
      const sd = straight(M, A, B);
      if (sd !== null) out.米 = Math.round(sd);
      return out;
    };
    if (mode.rail) {
      if (!M.rail) return two('没有登记铁道');
      const r = GE.rail.route(P, A, B, S.clock.t);
      if (!r.ok) return two(r.why);
      const st = name => (M.rail.stations[name] && M.rail.stations[name].ll) || null;
      const walk = (p, q) => { if (p && q && (p[0] !== q[0] || p[1] !== q[1])) out.段.push({ 类: '步行', 点: [p, q] }); };
      walk(ll(A), st(r.access.from));
      r.legs.forEach((x, i) => {
        if (i) walk(st(r.legs[i - 1].到), st(x.从));
        out.段.push({ 类: '电车', 线路: x.线路, 点: (x.站 || [x.从, x.到]).map(st).filter(Boolean) });
      });
      walk(st(r.access.to), ll(B));
      out.米 = Math.round(r.meters);
      out.分钟 = Math.round(r.minutes + mode.extra);
      return out;
    }
    if (mode.ignoreNet || mode.fixed !== null) return two('');
    const r = dijkstra(M, A, B, mode);
    if (!r) return two('路网上没有这段路');
    out.段.push({ 类: mode.name, 点: r.path.map(ll).filter(Boolean) });
    out.米 = Math.round(r.meters);
    out.分钟 = Math.round(r.minutes + mode.extra);
    return out;
  }

  // ---- 认所在地的坐标：给了字就认这段字，没给就认引擎现在的所在地 ----
  // 认不出、字面是在路上（「电车上」「去 RiNG 的路上」），而且三个小时内刚出过一趟（S.trip）：回在路上，
  // 位置照这一趟的路线形状取——时钟落在出发和到达之间按时间算，否则（出行一结算时钟就跳到到达）取路线正中
  const 在路上的说法 = /路上|途中|车上|车里|车内|车厢|电车|地铁|新干线|巴士|公交|出租车|的士|计程车|骑车|开车|骑行|步行中|走着/;
  const 在路上多久 = 180;
  function onTheWay(P, S, raw) {
    const T = S.trip, t = S.clock.t;
    if (!T || !T.from || !T.to || !raw || !在路上的说法.test(raw)) return null;
    if (t !== null && T.t1 !== null && T.t1 !== undefined && t - T.t1 > 在路上多久) return null;
    const known = t !== null && T.t0 !== null && T.t1 > T.t0 && t >= T.t0 && t < T.t1;
    const p = known ? (t - T.t0) / (T.t1 - T.t0) : 0.5;
    const g = geometry(P, S, null, T.from, T.to, T.by);
    const pts = [];
    for (const seg of (g && g.段) || []) for (const q of seg.点) if (!pts.length || pts[pts.length - 1][0] !== q[0] || pts[pts.length - 1][1] !== q[1]) pts.push(q);
    const M = P.map, A = M.nodes[T.from], B = M.nodes[T.to];
    if (pts.length < 2 && A && B && A.ll && B.ll) { pts.length = 0; pts.push(A.ll, B.ll); }
    let at = null;
    if (pts.length >= 2) {
      const cum = [0];
      for (let i = 1; i < pts.length; i++) cum.push(cum[i - 1] + geoDist(pts[i - 1], pts[i]));
      const want = cum[cum.length - 1] * p;
      let i = 1;
      while (i < cum.length - 1 && cum[i] < want) i++;
      const seg = cum[i] - cum[i - 1], f = seg > 0 ? (want - cum[i - 1]) / seg : 0;
      at = [+(pts[i - 1][0] + (pts[i][0] - pts[i - 1][0]) * f).toFixed(6), +(pts[i - 1][1] + (pts[i][1] - pts[i - 1][1]) * f).toFixed(6)];
    }
    const hm = x => (x === null || x === undefined ? '' : GE.cal.hm(GE.cal.minuteOfDay(x)));
    return { 原文: raw, 在路上: true, 从: T.from, 到: T.to, 方式: T.by, 进度: +p.toFixed(2), 按时间: known, 经纬: at,
      从经纬: (A && A.ll) || null, 到经纬: (B && B.ll) || null, 出发: hm(T.t0), 到达: hm(T.t1) };
  }
  function locate(P, S, text) {
    const M = P.map;
    const raw = text === undefined || text === null || text === '' ? (S.loc || '') : String(text);
    const id = raw ? placeOf(P, S, raw) : null;
    if (!id) return onTheWay(P, S, raw) || { 原文: raw, 状态: raw ? '认不出' : '没有所在地' };
    const n = M.nodes[id];
    const h = P.on.estate && GE.estate.homeNode(P, S, raw) ? GE.estate.homeOf(P, S) : null;
    if (h) return { 原文: raw, id, 经纬: h.坐标 || n.ll || null, 片区: n.area || '', 标记: ['住处'], 住处: h.门牌 || id };
    return { 原文: raw, id, 经纬: n.ll || null, 片区: n.area || '', 标记: n.tags.slice() };
  }

  return { compile, addNode, resolve, placeOf, travel, evaluate, settleMove, query, geometry, locate, straight, geoDist, fareOf, heap, kmText, norm, inWindow, parseClock };
})();

// ===== 12 铁道：按线路与车站算电车的耗时与车费 =====
// 门到门 = 走到车站 + 平均候车（半个发车间隔）+ 乘车（站间公里 ÷ 表定速度）+ 换乘（换乘步行 + 新线的半个间隔）+ 从车站走到目的地。
// 线路给了「站间分钟」（时刻表算出的相邻两站之间的时间，含停站）就用它，没给按表定速度换算。
// 同一条线的各停与快车登记成「基线」相同的两条，彼此换乘只算同站台的 1 分钟加新车的半个间隔。
// 车费按运营商分段：同一运营商连续乘坐的公里数合计后查它的票价表，各运营商的票价相加。

GE.rail = (() => {
  function compile(rb, M, err) {
    const R = {
      lines: {}, stations: {}, byNode: {},
      transferMin: rb['换乘分钟'] ?? 5,
      samePlatformMin: rb['同站台换乘分钟'] ?? 1,
      transferAt: rb['换乘'] || {},
      access: { maxM: 2000, factor: 1.3, mpm: 80, k: 4, ...(rb['接驳'] ? {
        maxM: rb['接驳']['最远米'] ?? 2000, factor: rb['接驳']['直线系数'] ?? 1.3,
        mpm: rb['接驳']['米每分'] ?? 80, k: rb['接驳']['候选'] ?? 4,
      } : {}) },
      fares: rb['票价'] || {},
    };
    (rb['车站'] || []).forEach((s, i) => {
      if (!s || !s['名'] || !s['坐标']) { err(`地图.铁道.车站[${i}]`, '要写「名」和「坐标」'); return; }
      R.stations[s['名']] = { name: s['名'], ll: s['坐标'], node: s['节点'] || null, lines: [] };
      if (s['节点']) R.byNode[s['节点']] = s['名'];
    });
    (rb['线路'] || []).forEach((l, i) => {
      if (!l || !l.id || !Array.isArray(l['站'])) { err(`地图.铁道.线路[${i}]`, '要写 id 和「站」'); return; }
      if (!(l['表定速度'] > 0) && !Array.isArray(l['站间分钟'])) err(`地图.铁道.线路[${i}]`, '「表定速度」「站间分钟」至少写一样');
      const st = l['站'].map(([n, km]) => ({ n, km }));
      for (let j = 1; j < st.length; j++) if (st[j].km < st[j - 1].km) err(`地图.铁道.线路[${i}].站`, '按里程从小到大排');
      const gaps = Array.isArray(l['站间分钟']) ? l['站间分钟'] : null;
      if (gaps && gaps.length < st.length - 1) err(`地图.铁道.线路[${i}].站间分钟`, `要有 ${st.length - 1} 个数`);
      for (const s of st) {
        if (!R.stations[s.n]) { err(`地图.铁道.线路[${i}].站`, `车站「${s.n}」没有登记坐标`); continue; }
        R.stations[s.n].lines.push(l.id);
      }
      R.lines[l.id] = {
        id: l.id, name: l['名'] || l.id, op: l['运营'] || '', st, speed: l['表定速度'] || 30,
        headway: l['间隔'] ?? 6, loop: !!l['环线'], loopLen: l['环长'] ?? null,
        gaps, base: l['基线'] || l.id, kind: l['种别'] || '',
      };
    });
    // 节点就是车站时直接对上（节点 id 与站名相同，或节点别名里有站名）
    for (const s of Object.values(R.stations)) {
      if (s.node) continue;
      if (M.nodes[s.name]) { s.node = s.name; R.byNode[s.name] = s.name; }
    }
    return R;
  }

  function neighbors(R, line, stationName) {
    const L = R.lines[line];
    const i = L.st.findIndex(s => s.n === stationName);
    const out = [];
    if (i < 0) return out;
    const n = L.st.length;
    const gap = j => (L.gaps && L.gaps[j] !== undefined && L.gaps[j] !== null ? L.gaps[j] : null);
    const mk = (to, km, min) => ({ n: L.st[to].n, km, min: min ?? km / L.speed * 60 });
    if (i > 0) out.push(mk(i - 1, L.st[i].km - L.st[i - 1].km, gap(i - 1)));
    if (i < n - 1) out.push(mk(i + 1, L.st[i + 1].km - L.st[i].km, gap(i)));
    if (L.loop && n > 2) {
      const len = L.loopLen ?? L.st[n - 1].km + (L.st[1].km - L.st[0].km);
      if (i === 0) out.push(mk(n - 1, len - L.st[n - 1].km, gap(n - 1)));
      if (i === n - 1) out.push(mk(0, len - L.st[n - 1].km, gap(n - 1)));
    }
    return out;
  }

  // 一个地点附近的车站：[{ name, walkM, walkMin }]
  function nearStations(P, nodeId) {
    const M = P.map, R = M.rail;
    const N = M.nodes[nodeId];
    if (R.byNode[nodeId]) return [{ name: R.byNode[nodeId], walkM: 0, walkMin: 0 }];
    if (!N || !N.ll) return [];
    const c = Object.values(R.stations)
      .filter(s => s.lines.length)
      .map(s => ({ name: s.name, d: GE.map.geoDist(N.ll, s.ll) }))
      .filter(x => x.d <= R.access.maxM)
      .sort((a, b) => a.d - b.d)
      .slice(0, R.access.k);
    return c.map(x => ({ name: x.name, walkM: x.d * R.access.factor, walkMin: x.d * R.access.factor / R.access.mpm }));
  }

  function fareFor(R, op, km, stations) {
    const f = R.fares[op];
    if (!f) return 0;
    let table = f['段'];
    for (const z of f['区域'] || []) if (stations.every(s => z['站'].includes(s))) { table = z['段']; break; }
    if (!table || !table.length) return 0;
    const k = Math.ceil(km - 1e-9);
    for (const [lim, price] of table) if (k <= lim) return price;
    const last = table[table.length - 1];
    return f['超出每公里'] ? last[1] + Math.ceil(km - last[0]) * f['超出每公里'] : last[1];
  }

  function route(P, a, b) {
    const R = P.map.rail;
    const O = nearStations(P, a), D = nearStations(P, b);
    if (!O.length) return { ok: false, why: '出发地附近没有车站' };
    if (!D.length) return { ok: false, why: '目的地附近没有车站' };
    const dWalk = new Map(D.map(x => [x.name, x]));
    const key = (s, l) => s + '|' + l;
    const dist = new Map(), prev = new Map(), km = new Map();
    const h = GE.map.heap();
    for (const o of O) {
      for (const l of R.stations[o.name].lines) {
        const c = o.walkMin + R.lines[l].headway / 2;
        const k = key(o.name, l);
        if (!dist.has(k) || c < dist.get(k)) { dist.set(k, c); prev.set(k, { start: o }); km.set(k, 0); h.push(c, k); }
      }
    }
    while (h.size()) {
      const [d, k] = h.pop();
      if (d > dist.get(k)) continue;
      const [s, l] = k.split('|');
      const L = R.lines[l];
      for (const nb of neighbors(R, l, s)) {
        const nk = key(nb.n, l);
        const nd = d + nb.min;
        if (!dist.has(nk) || nd < dist.get(nk)) { dist.set(nk, nd); prev.set(nk, { from: k, ride: nb.km, min: nb.min }); km.set(nk, km.get(k) + nb.km); h.push(nd, nk); }
      }
      for (const l2 of R.stations[s].lines) {
        if (l2 === l) continue;
        const nk = key(s, l2);
        const walk = R.lines[l2].base === L.base ? R.samePlatformMin : (R.transferAt[s] ?? R.transferMin);
        const nd = d + walk + R.lines[l2].headway / 2;
        if (!dist.has(nk) || nd < dist.get(nk)) { dist.set(nk, nd); prev.set(nk, { from: k, transfer: true }); km.set(nk, km.get(k)); h.push(nd, nk); }
      }
    }
    let best = null;
    for (const [k, d] of dist) {
      const [s] = k.split('|');
      const e = dWalk.get(s);
      if (!e) continue;
      const total = d + e.walkMin;
      if (!best || total < best.total) best = { k, total, egress: e };
    }
    if (!best) return { ok: false, why: '铁道上到不了' };
    // 还原各段
    const states = [];
    let cur = best.k;
    while (cur) { states.unshift(cur); const p = prev.get(cur); cur = p && p.from; }
    const start = prev.get(states[0]).start;
    const legs = [];
    let leg = null;
    for (let i = 0; i < states.length; i++) {
      const [s, l] = states[i].split('|');
      const p = prev.get(states[i]);
      if (!leg || p.transfer) {
        if (leg) legs.push(leg);
        leg = { line: l, name: R.lines[l].name, op: R.lines[l].op, from: s, to: s, stops: 0, km: 0, min: 0, stations: [s] };
        continue;
      }
      leg.to = s;
      leg.stops++;
      leg.km += p.ride;
      leg.min += p.min;
      leg.stations.push(s);
    }
    if (leg) legs.push(leg);
    const rideLegs = legs.filter(x => x.stops > 0);
    if (!rideLegs.length) return { ok: false, why: '两地离同一个车站最近，不用坐车' };
    for (const x of rideLegs) x.min = Math.round(x.min);
    // 车费：同一运营商连续的段合起来算
    let fare = 0;
    const groups = [];
    for (const x of rideLegs) {
      const g = groups[groups.length - 1];
      if (g && g.op === x.op) { g.km += x.km; g.stations.push(...x.stations); }
      else groups.push({ op: x.op, km: x.km, stations: x.stations.slice() });
    }
    for (const g of groups) fare += fareFor(R, g.op, g.km, g.stations);
    const railKm = rideLegs.reduce((s, x) => s + x.km, 0);
    const walkM = start.walkM + best.egress.walkM;
    return {
      ok: true,
      minutes: best.total,
      meters: railKm * 1000 + walkM,
      walkM,
      fare,
      legs: rideLegs.map(x => ({ 线路: x.name, 从: x.from, 到: x.to, 站数: x.stops, 公里: +x.km.toFixed(1), 分钟: x.min, 运营: x.op, 站: x.stations.slice() })),
      access: { from: start.name, to: best.egress.name, walkIn: Math.round(start.walkMin), walkOut: Math.round(best.egress.walkMin) },
    };
  }

  function legsText(legs) {
    return legs.map(x => `${x.线路} ${x.从}→${x.到}（${x.站数} 站，${x.分钟} 分钟）`).join(' → 换乘 → ');
  }

  return { compile, route, nearStations, fareFor, legsText };
})();

// ===== 13 作息、例外、约定与计时 =====
// 作息写在规则包里，按时间推算，不进存档；例外与约定进存档。
// 作息是事实：正文偏离作息不算不一致，引擎不提示、不更正。约定过点只注入一次「已过多少分钟」。

GE.routine = (() => {
  const { DAY } = GE.cal;

  function weekIdx(cal, w) {
    const s = String(w).replace(/^(周|星期|礼拜)/, '');
    if (cal.kind === '公历') return { 一: 0, 二: 1, 三: 2, 四: 3, 五: 4, 六: 5, 日: 6, 天: 6, 七: 6 }[s] ?? -1;
    return cal.weekNames.indexOf(s);
  }

  // 「约19:00」「19:00」「傍晚」→ { min, approx }
  function timePoint(P, s, end) {
    if (s === undefined || s === null || s === '') return null;
    let t = String(s).trim();
    const approx = /^约|左右$|前后$/.test(t);
    t = t.replace(/^约/, '').replace(/(左右|前后)$/, '').trim();
    const hm = GE.cal.parseHM(t);
    if (hm !== null) return { min: hm, approx };
    const seg = GE.clock.segName(t, P.segs.map(x => x.name));
    const i = P.segs.findIndex(x => x.name === seg);
    if (i < 0) return null;
    if (!end) return { min: P.segs[i].start, approx: true };
    const next = P.segs[(i + 1) % P.segs.length].start;
    return { min: next, approx: true };
  }

  const mdKey = s => { const m = /^(\d{1,2})-(\d{1,2})$/.exec(String(s).trim()); return m ? +m[1] * 100 + +m[2] : null; };

  function compile(pack, P, err) {
    const T = { routines: {}, presets: [] };
    (pack['作息'] || []).forEach((r, i) => {
      if (!r || !r['谁']) { err(`作息[${i}].谁`, '必填'); return; }
      const e = {
        who: r['谁'],
        days: r['星期'] ? r['星期'].map(w => weekIdx(P.cal, w)) : null,
        period: r['期间'] ? [mdKey(r['期间'][0]), mdKey(r['期间'][1])] : null,
        from: timePoint(P, r['从'], false), to: timePoint(P, r['到'], true),
        place: r['在'] || '', doing: r['做'] || '', loose: r['做'] === '不固定',
        rawDays: r['星期'] || null,
      };
      if (e.days && e.days.some(x => x < 0)) err(`作息[${i}].星期`, '有认不出的星期名');
      if (r['期间'] && (e.period[0] === null || e.period[1] === null)) err(`作息[${i}].期间`, '写成 ["MM-DD", "MM-DD"]');
      if (r['从'] && !e.from) err(`作息[${i}].从`, '写「HH:MM」「约HH:MM」或时段名');
      if (r['到'] && !e.to) err(`作息[${i}].到`, '写「HH:MM」「约HH:MM」或时段名');
      (T.routines[e.who] = T.routines[e.who] || []).push(e);
    });
    (pack['约定'] || []).forEach((a, i) => {
      if (!a || !a['名称']) { err(`约定[${i}].名称`, '必填'); return; }
      T.presets.push(a);
    });
    T.lead = (pack['约定设置'] || {})['提前'] ?? 3 * DAY;
    T.grace = (pack['约定设置'] || {})['宽限'] ?? 60;
    return T;
  }

  function initState(P, S) {
    for (const a of P.routine.presets) {
      const rep = a['重复'] || null;
      const tod = GE.cal.parseHM(a['时刻'] || '') ?? null;
      let at = null;
      if (a['日期']) {
        const p = GE.clock.parse(a['日期']);
        if (p && p.ymd) at = P.cal.toDay(p.ymd.y, p.ymd.m, p.ymd.d) * DAY + (tod ?? 0);
      }
      S.appts.push({
        id: 'A' + (++S.seq), title: a['名称'], who: a['谁'] ? [].concat(a['谁']) : [], place: a['地点'] || '',
        at, tod, rep: rep ? normRep(P, rep) : null, state: '未到', src: '规则包', done: [], noticed: {},
      });
    }
  }

  function normRep(P, rep) {
    if (rep['每周']) return { weekly: rep['每周'].map(w => weekIdx(P.cal, w)) };
    if (rep['每月']) return { monthly: [].concat(rep['每月']) };
    if (rep['每年']) return { yearly: mdKey(rep['每年']) };
    return null;
  }

  // ---- 作息推算 ----
  function inPeriod(P, day, period) {
    if (!period) return true;
    const { m, d } = P.cal.fromDay(day);
    const k = m * 100 + d;
    const [a, b] = period;
    return a <= b ? k >= a && k <= b : k >= a || k <= b;
  }

  function matchRoutine(P, who, t) {
    const list = (P.routine && P.routine.routines[who]) || [];
    const day = Math.floor(t / DAY), mod = t - day * DAY;
    const wd = P.cal.weekday(day);
    const hits = list.filter(e => {
      if (e.days && !e.days.includes(wd)) return false;
      if (!inPeriod(P, day, e.period)) return false;
      if (e.from && e.to) {
        const a = e.from.min, b = e.to.min;
        return a <= b ? mod >= a && mod < b : mod >= a || mod < b;
      }
      if (e.from) return mod >= e.from.min;
      if (e.to) return mod < e.to.min;
      return true;
    });
    if (!hits.length) return null;
    hits.sort((x, y) => (!!y.period - !!x.period) || (span(x) - span(y)));
    return hits[0];
  }
  const span = e => (e.from && e.to ? ((e.to.min - e.from.min + DAY) % DAY) : DAY);

  function daysLabel(e) {
    if (!e.rawDays) return '';
    const s = e.rawDays.map(w => String(w).replace(/^(周|星期|礼拜)/, '')).join('');
    if (s === '一二三四五') return '平日';
    if (s === '六日' || s === '六天') return '周末';
    return '每周' + e.rawDays.map(w => String(w).replace(/^(周|星期|礼拜)/, '')).join('、');
  }

  const tp = x => (x ? (x.approx ? '约 ' : '') + GE.cal.hm(x.min) : '');

  function activeExcept(S, who) {
    const t = S.clock.t;
    return S.excepts.find(x => x.who === who && x.from <= t && t < x.to) || null;
  }

  // 「角色乙：平日约 16:30–约 19:00 在练习室乐队练习（作息，可变）」；有例外时写例外
  function lineFor(P, S, who) {
    if (!who || S.clock.t === null) return '';
    const ex = activeExcept(S, who);
    if (ex) return `${who}：${ex.what}（例外）`;
    const e = matchRoutine(P, who, S.clock.t);
    if (!e) return '';
    if (e.loose) return `${who}：${daysLabel(e)}不固定（作息）`;
    const approx = (e.from && e.from.approx) || (e.to && e.to.approx) ? '约 ' : '';
    const hmOf = x => (x ? GE.cal.hm(x.min) : '');
    let when = '';
    if (e.from && e.to) when = `${approx}${hmOf(e.from)}–${hmOf(e.to)}`;
    else if (e.from) when = `${approx}${hmOf(e.from)} 起`;
    else if (e.to) when = `到${approx}${hmOf(e.to)}`;
    const where = e.place ? `在${e.place}` : '';
    const sep = /^\d/.test(when) ? ' ' : '';
    return `${who}：${daysLabel(e)}${sep}${when} ${where}${e.doing}（作息，可变）`.replace(/\s+/g, ' ').replace(' （', '（');
  }

  function viewFor(P, S, who) {
    const ex = activeExcept(S, who);
    if (ex) return { 例外: ex.what };
    const e = matchRoutine(P, who, S.clock.t);
    if (!e) return null;
    return { 在: e.place, 做: e.doing, 到: tp(e.to) };
  }

  // ---- 例外 ----
  function endOfDay(t) { return (Math.floor(t / DAY) + 1) * DAY; }

  function except(P, S, it, env, out) {
    const who = String(it.who || '').trim();
    if (!who) { out.results.push({ 项: '例外', 状态: '未结算：没写角色' }); return; }
    if (S.clock.t === null) { out.results.push({ 项: '例外', 状态: '未结算：还没有设定时间' }); return; }
    if (it.action === 'clear') {
      const n = S.excepts.length;
      S.excepts = S.excepts.filter(x => x.who !== who);
      out.results.push({ 项: '例外', 角色: who, 清除: n - S.excepts.length, 状态: '成立' });
      return;
    }
    let to = endOfDay(S.clock.t);
    if (it.until) {
      const p = GE.clock.parse(it.until, P.segs.map(s => s.name));
      const r = p ? GE.clock.resolve(p, { cal: P.cal, segs: P.segs, now: S.clock.t, maxJump: 400 * DAY, morning: P.morning }) : null;
      if (r && r.t > S.clock.t) to = r.t;
    }
    const what = String(it.what || '不按平常的作息').trim();
    S.excepts = S.excepts.filter(x => !(x.who === who && x.to > S.clock.t));
    S.excepts.push({ id: 'E' + (++S.seq), who, what, from: S.clock.t, to, src: env.path || 'tool' });
    out.results.push({ 项: '例外', 角色: who, 内容: what, 到: GE.cal.stamp(P.cal, to), 状态: '成立' });
  }

  // ---- 约定 ----
  function nextOccur(P, a, from) {
    if (!a.rep) return a.at;
    const tod = a.tod ?? 0;
    const d0 = Math.floor(from / DAY);
    for (let d = d0; d < d0 + 400; d++) {
      const key = d;
      if (a.done.includes(key)) continue;
      let ok = false;
      if (a.rep.weekly) ok = a.rep.weekly.includes(P.cal.weekday(d));
      else if (a.rep.monthly) ok = a.rep.monthly.includes(P.cal.fromDay(d).d);
      else if (a.rep.yearly) { const { m, d: dd } = P.cal.fromDay(d); ok = m * 100 + dd === a.rep.yearly; }
      if (ok && d * DAY + tod >= from) return d * DAY + tod;
    }
    return null;
  }

  const OPEN = s => s === '未到' || s === '临近';

  function findAppt(S, it) {
    if (it.id) { const a = S.appts.find(x => x.id === it.id); if (a) return a; }
    const t = String(it.title || '').trim();
    if (!t) return null;
    return S.appts.find(x => OPEN(x.state) && x.title === t) || S.appts.find(x => OPEN(x.state) && (x.title.includes(t) || t.includes(x.title))) || null;
  }

  function whenToT(P, S, when) {
    if (!when) return { at: null };
    const p = GE.clock.parse(when, P.segs.map(s => s.name));
    if (!p) return { at: null, note: `约定时间「${when}」认不出，记为未定` };
    const r = GE.clock.resolve(p, { cal: P.cal, segs: P.segs, now: S.clock.t, maxJump: 400 * DAY, morning: P.morning });
    if (r.reject) return { at: null, note: `约定时间「${when}」：${r.reject}，记为未定` };
    return { at: r.t, tod: p.tod ?? null };
  }

  function appt(P, S, it, env, out) {
    const o = env.opts;
    if (o.apptSource === 'host') { out.results.push({ 项: '约定', 状态: '未结算：约定由宿主记录' }); return; }
    const act = it.action || 'add';
    if (act === 'add') {
      const title = String(it.title || '').trim();
      if (!title) { out.results.push({ 项: '约定', 状态: '未结算：没写约定的事' }); return; }
      const w = whenToT(P, S, it.when);
      if (w.note) out.notes.push(w.note);
      const a = {
        id: 'A' + (++S.seq), title, who: it.who ? String(it.who).split(/[、,，]/).map(x => x.trim()).filter(Boolean) : [],
        place: it.place || '', at: w.at, tod: w.tod ?? null, rep: null, state: '未到', src: env.path || 'tool', done: [], noticed: {},
      };
      S.appts.push(a);
      out.results.push({ 项: '约定', 动作: '新增', 编号: a.id, 事: title, 时间: a.at === null ? '未定' : GE.cal.stamp(P.cal, a.at), 状态: '成立' });
      return;
    }
    const a = findAppt(S, it);
    if (!a) { out.results.push({ 项: '约定', 动作: act, 状态: '未结算：找不到这条约定' }); return; }
    if (act === 'done' || act === 'cancel') {
      if (a.rep) {
        const occ = nextOccur(P, a, S.clock.t - P.routine.grace - DAY);
        if (occ !== null) a.done.push(Math.floor(occ / DAY));
      } else a.state = act === 'done' ? '已完成' : '已取消';
      out.results.push({ 项: '约定', 动作: act === 'done' ? '完成' : '取消', 编号: a.id, 事: a.title, 状态: '成立' });
      return;
    }
    if (act === 'move') {
      const w = whenToT(P, S, it.when);
      if (w.at === null) { out.results.push({ 项: '约定', 动作: '改期', 编号: a.id, 状态: '未结算：新时间认不出' }); return; }
      a.at = w.at; a.tod = w.tod ?? a.tod; a.state = '未到'; a.noticed = {};
      out.results.push({ 项: '约定', 动作: '改期', 编号: a.id, 事: a.title, 时间: GE.cal.stamp(P.cal, a.at), 状态: '成立' });
    }
  }

  function timer(P, S, it, env, out) {
    if (S.clock.t === null) { out.results.push({ 项: '计时', 状态: '未结算：还没有设定时间' }); return; }
    if (it.action === 'cancel') {
      const n = S.timers.length;
      S.timers = S.timers.filter(x => x.title !== it.title);
      out.results.push({ 项: '计时', 事: it.title, 清除: n - S.timers.length, 状态: '成立' });
      return;
    }
    const p = GE.clock.parse(it.duration || '');
    const min = p && (p.elapsed ?? (p.dayJump !== undefined ? p.dayJump * DAY : undefined));
    if (!min) { out.results.push({ 项: '计时', 事: it.title, 状态: '未结算：时长认不出' }); return; }
    S.timers.push({ id: 'T' + (++S.seq), title: it.title || '计时', until: S.clock.t + min });
    out.results.push({ 项: '计时', 事: it.title, 到: GE.cal.stamp(P.cal, S.clock.t + min), 状态: '成立' });
  }

  // ---- 时间推进后的更新 ----
  function tick(P, S, env, out) {
    const t = S.clock.t;
    if (t === null) return;
    // 计时到点
    const ended = S.timers.filter(x => x.until <= t);
    for (const x of ended) out.flags.push({ kind: 'timer_end', text: `计时「${x.title}」已结束` });
    S.timers = S.timers.filter(x => x.until > t);
    // 例外过期
    S.excepts = S.excepts.filter(x => x.to > t);
    if (!P.on.routine) return;
    const grace = P.routine.grace, lead = P.routine.lead;
    const host = env.opts.apptSource === 'host';
    for (const a of S.appts) {
      if (!OPEN(a.state)) continue;
      const at = a.rep ? nextOccur(P, a, t - grace) : a.at;
      if (at === null) continue;
      if (t > at && !(a.noticed.passed === at)) {
        a.noticed.passed = at;
        out.flags.push({ kind: 'appt_passed', text: `约定 ${GE.cal.hm(GE.cal.minuteOfDay(at))} ${a.title}，已过 ${GE.settle.fmtDur(t - at)}` });
      }
      if (host) continue;
      if (!a.rep && t >= at + grace) a.state = '已错过';
      else if (!a.rep && at - t <= lead) a.state = '临近';
    }
  }

  // 约定的注入行：「今天 17:30 社团活动（50 分钟后）」
  function dayLabel(P, now, at) {
    const d = Math.floor(at / DAY) - Math.floor(now / DAY);
    if (d === 0) return '今天';
    if (d === 1) return '明天';
    if (d === 2) return '后天';
    if (d > 0 && d < 7) return P.cal.weekName(P.cal.weekday(Math.floor(at / DAY)));
    const { m, d: dd } = P.cal.fromDay(Math.floor(at / DAY));
    return P.cal.kind === '公历' ? `${m}月${dd}日` : `${P.cal.monthName(m)}${dd}日`;
  }

  function apptLines(P, S, env, n) {
    const t = S.clock.t;
    if (t === null) return [];
    const items = [];
    for (const a of S.appts) {
      if (!OPEN(a.state)) continue;
      const at = a.rep ? nextOccur(P, a, t) : a.at;
      if (at === null) { items.push({ k: Infinity, s: `时间未定 ${a.title}` }); continue; }
      if (at < t) continue;
      const left = at - t;
      const rel = left < 60 * 24 && Math.floor(at / DAY) === Math.floor(t / DAY) ? `${GE.settle.fmtDur(left)}后` : `还有 ${GE.settle.fmtDur(left)}`;
      items.push({ k: at, s: `${dayLabel(P, t, at)} ${GE.cal.hm(GE.cal.minuteOfDay(at))} ${a.title}（${rel}）` });
    }
    return items.sort((x, y) => x.k - y.k).slice(0, n).map(x => x.s);
  }

  // 有临近约定的角色
  function apptPeople(P, S) {
    const t = S.clock.t, set = new Set();
    for (const a of S.appts) {
      if (!OPEN(a.state)) continue;
      const at = a.rep ? nextOccur(P, a, t) : a.at;
      if (at !== null && at >= t && at - t <= DAY) a.who.forEach(w => set.add(w));
    }
    return [...set];
  }

  // 宿主记的约定（如数据库的日程表）→ 引擎的约定列表。时间写「YYYY-MM-DD」加「HH:MM」或「未定」
  const HOST_STATE = { 约定: '未到', 完成: '已完成', 取消: '已取消', 爽约: '已错过', 已完成: '已完成', 已取消: '已取消', 已错过: '已错过' };
  function fromHost(P, S, list) {
    const old = new Map(S.appts.map(a => [a.title + '|' + a.at, a]));
    return list.map((x, i) => {
      const title = String(x.title || x['事项'] || '').trim();
      const date = String(x.date || x['日期'] || '').trim();
      const tod = GE.cal.parseHM(String(x.time || x['时刻'] || '').trim());
      let at = null;
      const p = date ? GE.clock.parse(date) : null;
      if (p && p.ymd) at = P.cal.toDay(p.ymd.y, p.ymd.m, p.ymd.d) * DAY + (tod ?? 0);
      const prev = old.get(title + '|' + at);
      return {
        id: 'H' + (i + 1), title, place: x.place || x['地点'] || '',
        who: String(x.who || x['参与者'] || '').split(/[、,，]/).map(s => s.trim()).filter(Boolean),
        at, tod, rep: null, state: HOST_STATE[String(x.state || x['状态'] || '约定').trim()] || '未到',
        src: '宿主', done: [], noticed: prev ? prev.noticed : {},
      };
    }).filter(a => a.title);
  }

  return { compile, initState, lineFor, viewFor, except, appt, timer, tick, apptLines, apptPeople, matchRoutine, nextOccur, fromHost };
})();

// ===== 14 规则与派生值 =====
// 派生值由表达式定义，随状态实时计算；触发规则「当 条件 → 置标记」。
// 内置预设只用标记；作者自己写的提示文字照原样进注入的「提示」行。

GE.rules = (() => {
  function compile(pack, err) {
    const R = { rules: [], derived: {} };
    (pack['规则'] || []).forEach((r, i) => {
      if (!r || !r['当']) { err(`规则[${i}].当`, '必填'); return; }
      try { GE.expr.parse(r['当']); } catch (e) { err(`规则[${i}].当`, e.message); return; }
      R.rules.push({ when: r['当'], mark: r['标记'] || null, hint: r['提示'] || null });
    });
    (pack['派生'] || []).forEach((d, i) => {
      if (!d || !d['名'] || !d['式']) { err(`派生[${i}]`, '要写「名」和「式」'); return; }
      try { GE.expr.parse(d['式']); } catch (e) { err(`派生[${i}].式`, e.message); return; }
      R.derived[d['名']] = d['式'];
    });
    return R;
  }

  // 表达式里的变量：时钟字段、资源、物品、关系、flags、派生值、宿主给的值
  function lookup(P, S, env, name, depth) {
    depth = depth || 0;
    const t = S.clock.t;
    if (t !== null) {
      const day = Math.floor(t / GE.cal.DAY), mod = t - day * GE.cal.DAY;
      const ymd = P.cal.fromDay(day);
      switch (name) {
        case '小时': return Math.floor(mod / 60);
        case '分': return mod % 60;
        case '时刻': return mod;
        case '星期': return P.cal.weekday(day) + 1;
        case '日': return ymd.d;
        case '月': return ymd.m;
        case '年': return ymd.y;
        case '时段': return GE.cal.segmentAt(P.segs, mod);
        case '季节': return GE.cal.seasonAt(P.seasons, P.cal, day);
      }
    }
    if (name === '所在') return S.loc || '';
    if (name.startsWith('flags.')) return S.flags[name.slice(6)] ?? false;
    if (name.startsWith('物品.')) {
      const k = name.slice(3);
      const v = S.items[`${GE.ledger.PLAYER}.${k}`];
      if (v !== undefined) return v;
      const h = env && env.host && env.host.items;
      return h ? (h[k] ?? 0) : 0;
    }
    if (name.startsWith('关系.')) {
      const [, who, dim] = name.split('.');
      const v = S.rel[who] && S.rel[who][dim];
      return v === undefined ? undefined : v;
    }
    if (P.on.ledger) {
      if (P.ledger.res[name]) return S.res[`${GE.ledger.PLAYER}.${name}`] ?? 0;
      const dot = name.indexOf('.');
      if (dot > 0 && P.ledger.res[name.slice(dot + 1)]) return S.res[name] ?? 0;
    }
    if (P.on.rules && P.rules.derived[name] !== undefined && depth < 8) {
      const ast = GE.expr.parse(P.rules.derived[name]);
      return GE.expr.evaluate(ast, n => lookup(P, S, env, n, depth + 1));
    }
    const hv = env && env.host && env.host.vars;
    if (hv && hv[name] !== undefined) return hv[name];
    return undefined;
  }

  function apply(P, S, env, out) {
    for (const r of P.rules.rules) {
      if (!r.mark) continue;
      const v = GE.expr.test(r.when, n => lookup(P, S, env, n));
      if (v.ok && v.value) S.flags[r.mark] = true;
      else delete S.flags[r.mark];
    }
    void out;
  }

  // 条件为真的规则：标记名或作者写的提示
  function hints(P, S, env) {
    if (!P.on.rules) return [];
    const list = [];
    for (const r of P.rules.rules) {
      const v = GE.expr.test(r.when, n => lookup(P, S, env, n));
      if (v.ok && v.value) list.push(r.hint || r.mark);
    }
    return list.filter(Boolean);
  }

  function derivedValues(P, S, env) {
    const o = {};
    if (!P.on.rules) return o;
    for (const k of Object.keys(P.rules.derived)) {
      try { o[k] = GE.expr.tidy(lookup(P, S, env, k)); } catch (e) { o[k] = null; }
    }
    return o;
  }

  return { compile, lookup, apply, hints, derivedValues };
})();

// ===== 15 种子随机与判定 =====
// 种子 = 哈希（聊天标识、楼层的 send_date、序号）。同一条消息重算得到同样的点数；换一条消息点数重掷。

GE.rng = (() => {
  function hash(str) {
    let h = 2166136261 >>> 0;
    for (let i = 0; i < str.length; i++) { h ^= str.charCodeAt(i); h = Math.imul(h, 16777619); }
    return h >>> 0;
  }
  function mulberry32(a) {
    return () => {
      a |= 0; a = (a + 0x6D2B79F5) | 0;
      let t = Math.imul(a ^ (a >>> 15), 1 | a);
      t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    };
  }
  const make = seed => mulberry32(hash(String(seed)));

  // 「1d100」「2d6」「d20」
  function parseDice(s) {
    const m = /^(\d*)d(\d+)$/i.exec(String(s || '1d100').trim());
    return m ? { n: +(m[1] || 1), f: +m[2] } : null;
  }

  function compile(list, err) {
    const C = { list: [] };
    (list || []).forEach((c, i) => {
      if (!c || !c.id) { err(`判定[${i}].id`, '必填'); return; }
      const dice = parseDice(c['骰']);
      if (!dice) { err(`判定[${i}].骰`, '写成「1d100」「2d6」'); return; }
      C.list.push({
        id: c.id, name: c['名'] || c.id, dice, target: c['目标'] || null,
        tiers: (c['档'] || []).map(t => ({ name: t['名'], when: t['条件'] })),
      });
    });
    return C;
  }

  function check(P, S, it, env, out) {
    const c = P.check.list.find(x => x.id === it.id || x.name === it.id);
    if (!c) { out.results.push({ 项: '判定', 判定: it.id, 状态: '未结算：未登记的判定' }); return; }
    env._checkN = (env._checkN || 0) + 1;
    const r = make(`${env.seed || ''}|${c.id}|${env._checkN}`);
    let roll = 0;
    for (let i = 0; i < c.dice.n; i++) roll += 1 + Math.floor(r() * c.dice.f);
    const who = it.who || '';
    const look = name => {
      if (name === '骰') return roll;
      if (name === '角色') return who;
      if (name === '目标') return target;
      if (who && name.indexOf('.') < 0 && P.on.relation) {
        const dim = P.relation.dims.find(d => d.id === name);
        if (dim) {
          const v = S.rel[who] && S.rel[who][name];
          return v !== undefined ? v : ((P.relation.initBy[who] || {})[name] ?? dim.init);
        }
      }
      return GE.rules.lookup(P, S, env, name);
    };
    let target = null;
    if (c.target) {
      const tr = GE.expr.calc(c.target, look);
      if (!tr.ok) { out.results.push({ 项: '判定', 判定: c.name, 状态: '未结算：目标算不出（' + tr.err + '）' }); return; }
      target = tr.value;
    }
    let tier = '';
    for (const t of c.tiers) {
      const v = GE.expr.test(t.when, look);
      if (v.ok && v.value) { tier = t.name; break; }
    }
    const res = { 项: '判定', 判定: c.name, 点数: roll, 状态: '成立' };
    if (who) res.角色 = who;
    if (target !== null) res.目标 = target;
    if (tier) res.档位 = tier;
    out.results.push(res);
  }

  return { make, hash, compile, check, parseDice };
})();

// ===== 16 视图：注入块、只读出口、面板快照 =====
// 注入只写事实。各行只在对应模块已注册、且有内容时出现；超出字数预算按顺序舍弃，「现在」一行不舍弃。

GE.view = (() => {
  const HEAD = '以下时间和数值由外部账本计算，数字以此为准。';
  const ROUTINE_NOTE = '作息是平常的安排，剧情里已经发生的变动以正文为准。';
  const TOOL_NOTE = '需要时间经过、花费、移动、关系变化、判定或计算时，写正文之前先调用 ge_call，本轮事项一次报完。';

  // 舍弃顺序：数字越小越先舍弃
  const DROP = { 约定远: 1, 物价: 2, 账本: 3, 关系: 4, 作息: 5, 计时: 6, 提示: 7, 住处: 7.5, 约定: 8, 刚过: 9, 账上: 10 };

  function fmtDelta(v, prec) {
    const s = GE.ledger.fmt(Math.abs(v), prec);
    return (v < 0 ? '−' : '+') + s;
  }

  // info: { delta, flags, people, toolOn, lines: { 行名: false }, budget, relMode, stated }
  function injection(P, S, env, info) {
    info = info || {};
    const off = info.lines || {};
    const on = k => off[k] !== false;
    if (S.clock.t === null) return '';
    const secs = [];
    const add = (key, text, prio) => { if (text && on(key)) secs.push({ key, text, prio: prio ?? DROP[key] ?? 99 }); };

    // 现在
    const day = Math.floor(S.clock.t / GE.cal.DAY);
    const { y, m, d } = P.cal.fromDay(day);
    const date = P.cal.kind === '公历' ? `${y}年${m}月${d}日` : `${y}年 ${P.cal.monthName(m)} ${d}日`;
    const mod = GE.cal.minuteOfDay(S.clock.t);
    let now = `现在｜${date} ${P.cal.weekName(P.cal.weekday(day))} ${GE.cal.hm(mod)} ${GE.cal.segmentAt(P.segs, mod)}`;
    const season = GE.cal.seasonAt(P.seasons, P.cal, day);
    if (season) now += `｜${season}`;
    if (S.loc) now += `｜所在：${S.loc}`;
    const head = [HEAD];

    if (info.delta && info.delta.分钟 > 0) add('刚过', `刚过｜上一楼 ${GE.settle.fmtDur(info.delta.分钟)}`);

    if (P.on.routine) {
      const lines = GE.routine.apptLines(P, S, env, 4);
      if (lines.length) {
        add('约定', `约定｜${lines.slice(0, 2).join('；')}`);
        if (lines.length > 2) add('约定远', `约定｜${lines.slice(2).join('；')}`);
      }
      const people = [...new Set([...(info.people || []), ...GE.routine.apptPeople(P, S)])];
      const rl = people.map(w => GE.routine.lineFor(P, S, w)).filter(Boolean);
      if (rl.length && on('作息')) { add('作息', `作息｜${rl.join('；')}`); head.push(ROUTINE_NOTE); }
    }
    if (P.on.ledger) {
      const L = P.ledger;
      const parts = [];
      for (const r of Object.values(L.res)) {
        if (!r.show) continue;
        const k = `${GE.ledger.PLAYER}.${r.id}`;
        const v = S.res[k];
        if (v === undefined) continue;
        let s = r.max !== null ? `${r.id} ${GE.ledger.fmt(v, r.prec)}/${GE.ledger.fmt(r.max, r.prec)}` : `${r.id} ${GE.ledger.fmt(v, r.prec)}${r.unit ? ' ' + r.unit : ''}`;
        const dv = info.delta && info.delta.res && info.delta.res[k];
        if (dv) s += `（上一楼 ${fmtDelta(dv, r.prec)}）`;
        parts.push(s);
      }
      if (parts.length) add('账本', `账本｜${parts.join('；')}`);
      const pr = GE.ledger.pricesAt(P, S.loc, 3);
      if (pr.length) add('物价', `物价｜${pr.join('；')}`);
    }
    if (P.on.estate) add('住处', GE.estate.line(P, S));
    if (P.on.relation) {
      const who = new Set(info.people || []);
      if (info.delta && info.delta.rel) Object.keys(info.delta.rel).forEach(w => who.add(w));
      const rl = [...who].filter(w => S.rel[w]).map(w => GE.relation.line(P, S, w, info.relMode));
      if (rl.length) add('关系', `关系｜${rl.join('；')}`);
    }
    if (S.timers.length) {
      add('计时', `计时｜${S.timers.map(x => `${x.title} 剩 ${GE.settle.fmtDur(x.until - S.clock.t)}`).join('；')}`);
    }
    const hints = GE.rules.hints(P, S, env);
    if (hints.length) add('提示', `提示｜${hints.join('；')}`);
    const facts = [];
    for (const f of info.flags || []) if (f.text) facts.push(f.text);
    for (const f of info.flags || []) if (f.kind === 'stage') facts.push(`${f.who} ${f.dim} 阶段：${f.from} → ${f.to}`);
    if (info.stated) facts.push(info.stated);
    if (facts.length) add('账上', `账上｜${facts.join('；')}`);
    if (info.toolOn) head.push(TOOL_NOTE);

    const budget = info.budget ?? 400;
    const build = () => ['<世界状态>', head.join(''), now, ...secs.map(s => s.text), '</世界状态>'].join('\n');
    let text = build();
    const order = secs.slice().sort((a, b) => a.prio - b.prio);
    while (text.length > budget && order.length) {
      const victim = order.shift();
      secs.splice(secs.indexOf(victim), 1);
      text = build();
    }
    return text;
  }

  // 摊平给世界书条件、模板引擎、其他脚本读的只读出口
  function flat(P, S, env, people) {
    const o = {};
    if (S.clock.t !== null) {
      const day = Math.floor(S.clock.t / GE.cal.DAY), mod = GE.cal.minuteOfDay(S.clock.t);
      o['时间'] = `${GE.cal.dateText(P.cal, day)} ${GE.cal.hm(mod)}`;
      o['星期'] = P.cal.weekName(P.cal.weekday(day));
      o['时段'] = GE.cal.segmentAt(P.segs, mod);
      const season = GE.cal.seasonAt(P.seasons, P.cal, day);
      if (season) o['季节'] = season;
    }
    if (S.loc) o['地点'] = S.loc;
    if (P.on.ledger) for (const r of Object.values(P.ledger.res)) {
      const v = S.res[`${GE.ledger.PLAYER}.${r.id}`];
      if (v !== undefined) o[r.id] = v;
    }
    if (P.on.relation) for (const [who, dims] of Object.entries(S.rel)) {
      for (const d of P.relation.dims) o[`${d.id}.${who}`] = dims[d.id];
    }
    if (P.on.routine) for (const who of Object.keys(P.routine.routines).concat(people || [])) {
      const v = GE.routine.viewFor(P, S, who);
      if (v) o[`作息.${who}`] = v.例外 ? `${v.例外}（例外）` : [v.在, v.做].filter(Boolean).join(' · ');
    }
    Object.assign(o, GE.rules.derivedValues(P, S, env));
    return o;
  }

  return { injection, flat, HEAD, TOOL_NOTE };
})();

// ===== 17 房产：住宅区、买租卖、搬家、同住、每月房租 =====
// 规则包「房产」：住宅区（每一处登记成地图上的地点，能导航、能算通勤）、户型、各户型的价、设施，
// 以及首付月数、押金月数、卖房到手、交租日、借住月费。
// 存档 S.estate：住在哪一处（住）、名下各处（房）、欠的房租（欠）。钱走账本的「钱」，房价不受「钱」的单笔上限：
// 单笔上限防的是正文模型报错数，房价出自规则包。
// 事项 house 只认宿主交的（面板上玩家点了确认）：买、租、搬回、退租、卖、同住、搬出、借住、开局、登记。
// 结果只写事实：钱不够写还差多少，住不下写几个人，标了未成年的同住没写家里同意就不成立。

GE.estate = (() => {
  const HOME = /^(回)?(家|自己家|自家|家里|家中|主角家|我家)$/;
  const norm = s => GE.map.norm(s);
  const round10 = v => Math.ceil(v / 10) * 10;

  // ---- 编译 ----
  function compile(pack, P, err) {
    const E = pack['房产'] || {};
    const X = {
      kinds: {}, kindList: [], areas: {}, areaList: [], tiers: E['档'] || [], extras: {},
      firstMonths: E['首付月数'] ?? 3, depositMonths: E['押金月数'] ?? 1, sellRate: E['卖房到手'] ?? 0.9,
      payDay: E['交租日'] ?? 1, lodgeFee: (E['借住'] && E['借住']['月费']) ?? 0, pinSlack: E['图钉余量'] ?? 60,
    };
    if (!P.on.ledger || !P.ledger.money) err('房产', '要先在「资源」里登记钱');
    if (!(X.payDay >= 1 && X.payDay <= 28)) err('房产.交租日', '写 1～28 的整数');
    (E['户型'] || []).forEach((k, i) => {
      if (!k || !k['名']) { err(`房产.户型[${i}].名`, '必填'); return; }
      X.kinds[k['名']] = { name: k['名'], rentOnly: !!k['只租'], cap: k['人数'] ?? 1, note: k['说明'] || '' };
      X.kindList.push(k['名']);
    });
    (E['设施'] || []).forEach((f, i) => {
      if (!f || !f['名']) { err(`房产.设施[${i}].名`, '必填'); return; }
      X.extras[f['名']] = { name: f['名'], kinds: f['户型'] || null, rent: f['租'] ?? 0, buy: f['买'] ?? 0, note: f['说明'] || '' };
    });
    (E['住宅区'] || []).forEach((a, i) => {
      if (!a || !a.id) { err(`房产.住宅区[${i}].id`, '必填'); return; }
      const prices = {};
      for (const [k, v] of Object.entries(a['价'] || {})) {
        if (!X.kinds[k]) { err(`房产.住宅区[${i}].价.${k}`, '户型没有登记'); continue; }
        prices[k] = { rent: (v && v['租']) ?? null, buy: X.kinds[k].rentOnly ? null : ((v && v['买']) ?? null) };
      }
      const ll = a['坐标'] && a['坐标'].length === 2 ? a['坐标'] : null;
      // 住宅区登记成地图上的地点：规则包的地图里已有同名地点就用它，没有就按坐标加一个
      let node = a['节点'] || a.id;
      if (P.on.map) {
        if (!P.map.nodes[node]) {
          if (!ll) err(`房产.住宅区[${i}].坐标`, '地图上没有这个地点，要写坐标');
          else GE.map.addNode(P.map, { id: node, 坐标: ll, 片区: a['片区'] || '', 别名: [a.id + '住宅区'], 标记: ['住宅区'] });
        }
      }
      const n = P.on.map ? P.map.nodes[node] : null;
      X.areas[a.id] = {
        id: a.id, node, tier: a['档'] || '', radius: a['半径'] ?? 500, station: a['车站'] || '', note: a['说明'] || '', intro: a['介绍'] || '',
        ll: ll || (n && n.ll) || null, area: a['片区'] || (n && n.area) || '', prices,
      };
      X.areaList.push(a.id);
    });
    return X;
  }

  function ensure(S) {
    if (!S.estate) S.estate = { 住: null, 房: {}, 欠: 0, seq: 0 };
    return S.estate;
  }
  // 基底：开局的家、已有的房子（宿主 setBase 时带上 estate: [{ 方式, 区 或 节点, 坐标, 门牌, 户型, 价, 月租, 当前 }]）
  function initState(P, S, over) {
    ensure(S);
    const list = over && Array.isArray(over.estate) ? over.estate : [];
    for (const x of list) register(P, S, x, null);
  }

  // ---- 钱 ----
  const key = P => `${GE.ledger.PLAYER}.${P.ledger.money}`;
  const have = (P, S) => S.res[key(P)] ?? 0;
  const moneyText = (P, v) => GE.ledger.fmt(v, P.ledger.res[P.ledger.money].prec) + (P.ledger.res[P.ledger.money].unit ? ' ' + P.ledger.res[P.ledger.money].unit : '');
  function take(P, S, v) { S.res[key(P)] = GE.expr.tidy(have(P, S) - v); }
  function give(P, S, v) { S.res[key(P)] = GE.expr.tidy(have(P, S) + v); }

  // ---- 一处房子 ----
  // { id, 区, 节点, 户型, 方式: 租 | 买 | 开局 | 借住, 月租（整套）, 价, 押金, 起, 门牌, 坐标, 同住: [{ 名, 未成年, 家里同意 }], 设施: [] }
  function newId(E) { E.seq += 1; return 'h' + E.seq; }
  const mates = h => (h && h.同住) || [];
  // 主角这个月出多少：租的整套月租按人头分（同住的人各出一份），借住按规则包的借住月费
  function share(P, h) {
    if (!h) return 0;
    if (h.方式 === '租') return round10((h.月租 || 0) / (1 + mates(h).length));
    if (h.方式 === '借住') return P.estate.lodgeFee || 0;
    return 0;
  }
  const kindCap = (P, h) => (h && h.户型 && P.estate.kinds[h.户型] ? P.estate.kinds[h.户型].cap : Infinity);

  // 登记（不扣钱）：开局、旧局搬过来的房子
  function register(P, S, x, out) {
    const E = ensure(S), X = P.estate;
    const area = x['区'] ? X.areas[x['区']] : null;
    const kind = x['户型'] && X.kinds[x['户型']] ? x['户型'] : null;
    const how = ['租', '买', '开局', '借住'].includes(x['方式']) ? x['方式'] : '开局';
    const h = {
      id: newId(E), 区: area ? area.id : null, 节点: x['节点'] || (area ? area.node : null), 户型: kind, 方式: how,
      月租: how === '租' ? (Number(x['月租']) || 0) : 0, 价: how === '买' ? (Number(x['价']) || 0) : 0,
      押金: how === '租' ? (Number(x['押金']) || 0) : 0, 起: S.clock.t, 门牌: String(x['门牌'] || '').trim(),
      坐标: Array.isArray(x['坐标']) && x['坐标'].length === 2 ? x['坐标'].map(Number) : (area ? area.ll : null),
      同住: [], 设施: [].concat(x['设施'] || []).filter(f => X.extras[f]),
    };
    E.房[h.id] = h;
    if (x['当前'] !== false && (how !== '买' || x['当前'] === true || !E.住)) E.住 = h.id;
    if (out) out.results.push({ 项: '住处', 动作: '登记', 住处: label(h), 方式: how, 状态: '成立' });
    return h;
  }

  function label(h) {
    if (!h) return '';
    return h.门牌 || [h.区, h.户型].filter(Boolean).join(' ') || h.节点 || '住处';
  }

  // 搬走：租的退租（押金退回），买的留成名下的房子，开局的家、借住的地方不留
  function leave(P, S, out) {
    const E = ensure(S), h = E.房[E.住];
    E.住 = null;
    if (!h) return;
    if (h.方式 === '买') { h.同住 = []; return; }
    if (h.方式 === '租' && h.押金) {
      give(P, S, h.押金);
      out.results.push({ 项: '住处', 动作: '退租', 住处: label(h), 退押金: h.押金, 余额: moneyText(P, have(P, S)), 状态: '成立' });
    }
    delete E.房[h.id];
  }

  // 同住的人：名字列表或 { 名, 未成年, 家里同意 }；标了未成年的要写家里同意
  function normMate(m) {
    if (!m) return null;
    if (typeof m === 'string') return { 名: m.trim(), 未成年: false, 家里同意: false };
    const 名 = String(m['名'] || m.who || '').trim();
    return 名 ? { 名, 未成年: !!m['未成年'], 家里同意: !!m['家里同意'] } : null;
  }
  const consentMissing = list => list.find(m => m.未成年 && !m.家里同意);

  // 图钉在不在住宅区里（多给一点余量：面板吸到街上会挪几十米）
  function inArea(P, area, ll) {
    if (!ll || !area.ll) return true;
    return GE.map.geoDist(area.ll, ll) <= area.radius + P.estate.pinSlack;
  }

  // ---- 事项 ----
  function settle(P, S, list, env, out) {
    for (const it of list || []) one(P, S, it || {}, env, out);
  }

  function one(P, S, it, env, out) {
    const E = ensure(S), X = P.estate;
    const act = String(it['动作'] || it.action || '').trim();
    const res = { 项: '住处', 动作: act };
    const fail = (why, extra) => { out.results.push({ ...res, ...(extra || {}), 状态: '未结算：' + why }); };
    if (env.path !== 'host' && env.path !== 'manual') return fail('住处只由面板上的确认来改');
    const cur = E.房[E.住] || null;

    if (act === '买' || act === '租') {
      const area = X.areas[it['区']];
      if (!area) return fail(`没有这个住宅区（${it['区'] || '没写'}）`);
      const kind = X.kinds[it['户型']];
      if (!kind) return fail(`没有这种户型（${it['户型'] || '没写'}）`);
      const price = area.prices[kind.name];
      if (!price) return fail(`${area.id}没有${kind.name}`);
      if (act === '买' && price.buy === null) return fail(`${kind.name}只能租`);
      if (act === '租' && price.rent === null) return fail(`${area.id}的${kind.name}不出租`);
      const extras = [].concat(it['设施'] || []).filter(Boolean);
      for (const f of extras) {
        const ex = X.extras[f];
        if (!ex) return fail(`没有这种设施（${f}）`);
        if (ex.kinds && !ex.kinds.includes(kind.name)) return fail(`${kind.name}装不了${f}`);
      }
      const ll = Array.isArray(it['坐标']) && it['坐标'].length === 2 ? it['坐标'].map(Number) : null;
      if (ll && !inArea(P, area, ll)) return fail(`图钉不在${area.id}住宅区里`);
      // 一起搬过去的人：没写就是现在同住的人；新来的照「同住」的规矩查
      const moving = (it['同住'] !== undefined ? [].concat(it['同住']) : mates(cur)).map(normMate).filter(Boolean);
      const miss = consentMissing(moving);
      if (miss) return fail(`${miss.名}未成年，同住要她家里同意`);
      if (1 + moving.length > kind.cap) return fail(`${kind.name}住不下 ${1 + moving.length} 个人（最多 ${kind.cap} 人）`);
      const extraBuy = extras.reduce((s, f) => s + (X.extras[f].buy || 0), 0);
      const extraRent = extras.reduce((s, f) => s + (X.extras[f].rent || 0), 0);
      const h = {
        id: '', 区: area.id, 节点: area.node, 户型: kind.name, 方式: act, 月租: 0, 价: 0, 押金: 0, 起: S.clock.t,
        门牌: String(it['门牌'] || '').trim(), 坐标: ll || area.ll, 同住: moving, 设施: extras,
      };
      let pay;
      if (act === '买') { h.价 = price.buy + extraBuy; pay = h.价; }
      else {
        h.月租 = price.rent + extraRent;
        const mine = share(P, h);
        h.押金 = mine * X.depositMonths;
        pay = mine * X.firstMonths;
      }
      // 退租退回的押金这一笔先算进来：钱够不够按搬完的结果看
      const refund = cur && cur.方式 === '租' ? (cur.押金 || 0) : 0;
      const short = pay - (have(P, S) + refund);
      if (short > 0) return fail('钱不够', { 住宅区: area.id, 户型: kind.name, 要付: pay, 还差: short });
      leave(P, S, out);
      take(P, S, pay);
      h.id = newId(E);
      E.房[h.id] = h;
      E.住 = h.id;
      const r = { ...res, 住宅区: area.id, 户型: kind.name, 住处: label(h), 付: pay, 余额: moneyText(P, have(P, S)), 状态: '成立' };
      if (act === '租') { r.月租 = h.月租; r.你出 = share(P, h); }
      if (moving.length) r.同住 = moving.map(m => m.名).join('、');
      out.results.push(r);
      return;
    }

    if (act === '搬回') {
      const h = E.房[it['房']];
      if (!h || h.方式 !== '买') return fail('名下没有这一处');
      if (h.id === E.住) return fail('已经住在这里');
      const moving = mates(cur);
      if (1 + moving.length > kindCap(P, h)) return fail(`${h.户型}住不下 ${1 + moving.length} 个人`);
      leave(P, S, out);
      h.同住 = moving;
      E.住 = h.id;
      out.results.push({ ...res, 住处: label(h), 状态: '成立' });
      return;
    }

    if (act === '退租' || act === '卖') {
      const h = E.房[it['房']];
      if (!h) return fail('没有这一处');
      if (h.id === E.住) return fail('住着的地方先搬走再' + act);
      if (act === '退租') {
        if (h.方式 !== '租') return fail('这一处不是租的');
        delete E.房[h.id];
        if (h.押金) give(P, S, h.押金);
        out.results.push({ ...res, 住处: label(h), 退押金: h.押金 || 0, 余额: moneyText(P, have(P, S)), 状态: '成立' });
        return;
      }
      if (h.方式 !== '买') return fail('这一处不是买的');
      const got = Math.round((h.价 || 0) * X.sellRate);
      delete E.房[h.id];
      give(P, S, got);
      out.results.push({ ...res, 住处: label(h), 到手: got, 余额: moneyText(P, have(P, S)), 状态: '成立' });
      return;
    }

    if (act === '同住') {
      if (!cur) return fail('还没有住处');
      if (cur.方式 === '借住') return fail('借住在别人家，不能再带人住进来');
      const m = normMate(it['谁'] !== undefined ? { 名: it['谁'], 未成年: it['未成年'], 家里同意: it['家里同意'] } : it);
      if (!m) return fail('没写谁');
      if (mates(cur).some(x => x.名 === m.名)) return fail(`${m.名}已经住在这里`);
      if (m.未成年 && !m.家里同意) return fail(`${m.名}未成年，同住要她家里同意`);
      if (1 + mates(cur).length + 1 > kindCap(P, cur)) return fail(`${cur.户型}住不下 ${2 + mates(cur).length} 个人（最多 ${kindCap(P, cur)} 人）`);
      cur.同住 = mates(cur).concat([m]);
      const r = { ...res, 谁: m.名, 住处: label(cur), 状态: '成立' };
      if (cur.方式 === '租') r.你出 = share(P, cur);
      out.results.push(r);
      return;
    }

    if (act === '搬出') {
      const 名 = String(it['谁'] || '').trim();
      const h = Object.values(E.房).find(x => mates(x).some(m => m.名 === 名));
      if (!h) return fail(`${名 || '没写谁'}没有和你同住`);
      h.同住 = mates(h).filter(m => m.名 !== 名);
      const r = { ...res, 谁: 名, 住处: label(h), 状态: '成立' };
      if (h.方式 === '租') r.你出 = share(P, h);
      out.results.push(r);
      return;
    }

    if (act === '借住') {
      // 住进角色家：节点是地图上她家那个地点（或者给坐标和名字）；她家里同意才成立
      const host = normMate(it['谁'] !== undefined ? { 名: it['谁'], 未成年: it['未成年'], 家里同意: it['家里同意'] } : null);
      if (!host) return fail('没写住进谁家');
      if (!it['家里同意']) return fail(`住进${host.名}家要她家里同意`);
      const nodeId = it['节点'] && P.on.map && P.map.nodes[it['节点']] ? it['节点'] : null;
      const ll = nodeId ? P.map.nodes[nodeId].ll : (Array.isArray(it['坐标']) && it['坐标'].length === 2 ? it['坐标'].map(Number) : null);
      if (!nodeId && !ll) return fail(`地图上找不到${host.名}家`);
      if (mates(cur).length) return fail('先让同住的人搬出，再住进别人家');
      const fee = X.lodgeFee || 0;
      leave(P, S, out);
      const h = { id: newId(E), 区: null, 节点: nodeId, 户型: null, 方式: '借住', 月租: fee, 价: 0, 押金: 0, 起: S.clock.t,
        门牌: String(it['门牌'] || (host.名 + '家')).trim(), 坐标: ll, 同住: [{ ...host, 家里同意: true }], 设施: [] };
      E.房[h.id] = h;
      E.住 = h.id;
      out.results.push({ ...res, 谁: host.名, 住处: label(h), 月费: fee, 状态: '成立' });
      return;
    }

    if (act === '开局' || act === '登记') {
      if (act === '开局' && cur && cur.方式 !== '开局') return fail('已经有住处了');
      if (act === '开局' && cur) delete E.房[cur.id];
      register(P, S, act === '开局' ? { ...it, 方式: '开局', 当前: true } : it, out);
      return;
    }

    fail(`不认得这个动作（${act || '没写'}）`);
  }

  // ---- 每月交房租：时钟跨过交租日 0:00，每跨一次交一个月 ----
  // 欠着的先还；钱不够的部分记成欠房租，下一次接着还。房子是这一段时间里新租的，交租日在起租之前的不收（首付里含首月）
  function paydays(P, a, b) {
    const DAY = GE.cal.DAY, out = [];
    const d0 = P.cal.fromDay(Math.floor(a / DAY)), d1 = P.cal.fromDay(Math.floor(b / DAY));
    let y = d0.y, m = d0.m;
    for (let guard = 0; guard < 2400; guard++) {
      const t = P.cal.toDay(y, m, Math.min(P.estate.payDay, P.cal.daysInMonth(y, m))) * DAY;
      if (t > a && t <= b) out.push(t);
      if (y > d1.y || (y === d1.y && m >= d1.m)) break;
      m += 1;
      if (m > P.cal.monthCount(y)) { m = 1; y += 1; }
    }
    return out;
  }

  function passTime(P, prev, S, out) {
    const a = prev.clock.t, b = S.clock.t;
    if (a === null || a === undefined || b === null || b === undefined || b <= a || !S.estate) return;
    const E = S.estate;
    const homes = Object.values(E.房).filter(h => share(P, h) > 0);
    if (!homes.length && !E.欠) return;
    for (const t of paydays(P, a, b)) {
      const due = homes.filter(h => h.起 === null || h.起 < t).reduce((s, h) => s + share(P, h), 0);
      if (!due) continue;
      E.欠 = GE.expr.tidy((E.欠 || 0) + due);
      const pay = Math.max(0, Math.min(have(P, S), E.欠));
      take(P, S, pay);
      E.欠 = GE.expr.tidy(E.欠 - pay);
      const { y, m } = P.cal.fromDay(Math.floor(t / GE.cal.DAY));
      out.results.push({ 项: '房租', 月: `${y}-${String(m).padStart(2, '0')}`, 应交: due, 交了: pay, 欠: E.欠, 余额: moneyText(P, have(P, S)), 状态: E.欠 ? '欠着' : '成立' });
      if (E.欠) out.flags.push({ kind: 'rentOwed', text: `房租没交齐，欠 ${moneyText(P, E.欠)}` });
    }
  }

  // ---- 「家」认成住处所在的地点 ----
  // 家的叫法（家、回家、自己家……）和住处的门牌认成住处的地点（住宅区、角色家）；图钉买的房子认成它所在的住宅区
  function homeOf(P, S) {
    const E = S && S.estate;
    return E && E.住 ? E.房[E.住] || null : null;
  }
  function homeNode(P, S, text) {
    const h = homeOf(P, S);
    if (!h || !text) return null;
    const t = String(text).trim();
    if (HOME.test(t) || (h.门牌 && norm(h.门牌) === norm(t))) return h.节点 || null;
    return null;
  }

  // ---- 读 ----
  function nextPayday(P, S) {
    if (S.clock.t === null) return null;
    const DAY = GE.cal.DAY, { y, m, d } = P.cal.fromDay(Math.floor(S.clock.t / DAY));
    let yy = y, mm = m;
    if (d >= P.estate.payDay) { mm += 1; if (mm > P.cal.monthCount(yy)) { mm = 1; yy += 1; } }
    return GE.cal.dateText(P.cal, P.cal.toDay(yy, mm, Math.min(P.estate.payDay, P.cal.daysInMonth(yy, mm))));
  }
  function homeView(P, S, h) {
    if (!h) return null;
    const area = h.区 ? P.estate.areas[h.区] : null;
    return {
      id: h.id, 住处: label(h), 门牌: h.门牌, 区: h.区, 档: area ? area.tier : '', 片区: area ? area.area : '', 车站: area ? area.station : '',
      节点: h.节点, 户型: h.户型, 方式: h.方式, 月租: h.月租, 你出: share(P, h), 价: h.价, 押金: h.押金, 坐标: h.坐标,
      同住: mates(h).map(m => ({ ...m })), 设施: h.设施.slice(), 起: h.起 === null ? '' : GE.cal.dateText(P.cal, Math.floor(h.起 / GE.cal.DAY)),
      住着: S.estate.住 === h.id,
    };
  }
  function view(P, S) {
    const E = ensure(S), X = P.estate, money = have(P, S);
    const areas = X.areaList.map(id => {
      const a = X.areas[id], 价 = {};
      for (const k of X.kindList) {
        const p = a.prices[k];
        if (!p) continue;
        const mine = p.rent !== null ? round10(p.rent) : null;
        价[k] = { 租: p.rent, 买: p.buy, 首付: mine !== null ? mine * X.firstMonths : null,
          租得起: mine !== null && money >= mine * X.firstMonths, 买得起: p.buy !== null && money >= p.buy };
      }
      return { id, 档: a.tier, 片区: a.area, 车站: a.station, 坐标: a.ll, 半径: a.radius, 说明: a.note, 介绍: a.intro, 节点: a.node, 价 };
    });
    return {
      住: homeView(P, S, homeOf(P, S)),
      房: Object.values(E.房).map(h => homeView(P, S, h)),
      欠: E.欠 || 0, 下次交租: nextPayday(P, S), 每月: Object.values(E.房).reduce((s, h) => s + share(P, h), 0), 钱: money,
      区: areas, 档: X.tiers.slice(),
      户型: X.kindList.map(k => ({ 名: k, 只租: X.kinds[k].rentOnly, 人数: X.kinds[k].cap, 说明: X.kinds[k].note })),
      设施: Object.values(X.extras).map(f => ({ 名: f.name, 户型: f.kinds, 租: f.rent, 买: f.buy, 说明: f.note })),
      设置: { 首付月数: X.firstMonths, 押金月数: X.depositMonths, 卖房到手: X.sellRate, 交租日: X.payDay, 借住月费: X.lodgeFee },
    };
  }

  // 注入的一行：住在哪、怎么住、每月出多少、同住的人、名下另有、欠的房租
  function line(P, S) {
    const E = S.estate;
    if (!E) return '';
    const h = homeOf(P, S);
    const parts = [];
    if (h) {
      const how = [h.区, h.户型].filter(Boolean).join(' ');
      let s = `住处｜${label(h)}（${[how && how !== label(h) ? how : '', h.方式 === '开局' ? '开局时的家' : h.方式].filter(Boolean).join(' · ')}`;
      const mine = share(P, h);
      if (mine) s += `，每月 ${P.estate.payDay} 号 ${moneyText(P, mine)}` + (h.方式 === '租' && mates(h).length ? `，${1 + mates(h).length} 人分` : '');
      if (h.设施.length) s += `，有${h.设施.join('、')}`;
      s += '）';
      parts.push(s);
      if (mates(h).length) parts.push('同住：' + mates(h).map(m => m.名 + (m.未成年 ? '（未成年，家里同意）' : '')).join('、'));
    }
    const owned = Object.values(E.房).filter(x => x !== h && x.方式 === '买').map(label);
    if (owned.length) parts.push('名下另有：' + owned.join('、'));
    if (E.欠) parts.push('欠房租 ' + moneyText(P, E.欠));
    return parts.length ? parts.join('｜').replace(/^(?!住处｜)/, '住处｜') : '';
  }

  // 每个住宅区到某地（学校、工作）最快怎么走：按当天早上 8 点算，比较时不受末班车影响；打车、无视路网的（新干线）不算
  function commute(P, S, env, toText) {
    const out = {};
    if (!P.on.map || !toText) return out;
    const to = GE.map.placeOf(P, S, toText);
    if (!to) return out;
