    const text = stripTags(m.mes);
    if (cfg().代码读时间戳) {
      const stamps = GE.clock.scanStamps(text);
      if (stamps.length) batches.push({ path: 'code', ev: { time: { stamps } } });
    }
    if (!batches.some(b => b.path === 'tool') && cfg().正文自报标签) {
      const tagEv = GE_TAG.parse(m.mes);
      if (tagEv) batches.push({ path: 'tag', ev: tagEv });
    }
    const hasTime = batches.some(b => b.ev.time || b.ev.move);
    if (!hasTime && cfg().每楼默认推进分钟 > 0) batches.push({ path: 'code', ev: { time: { elapsed: cfg().每楼默认推进分钟 + '分钟' } } });
    const out = replay(P, base, batches);
    const src = batches.some(b => b.path === 'tool') ? 'tool' : batches.some(b => b.path === 'tag') ? 'tag' : 'code';
    const rec = {
      floor: id, sd: m.send_date, sw: m.swipe_id || 0, h: textHash(m.mes), src, status: statusOf(out.results),
      batches, S: out.S, results: out.results, notes: out.notes, flags: out.flags, delta: out.delta, at: Date.now(),
      calls: turnOpen ? TURN.calls : 0,
    };
    putRec(rec);
    saveStore();
    writeView(P, out.S);
    BUS.emit('settled', { floor: id, rec });
    // 本轮没有工具调用：有线索、配了副模型时，副模型补抽其余事项
    if (src !== 'tool' && GE_SIDE.enabled() && GE_SIDE.hasClues(P, text)) {
      rec.status = 'pending';
      saveStore();
      GE_SIDE.run(id, rec, m).catch(e => warn('副模型兜底出错：', e));
    }
    return rec;
  }

  // ======================== 兜底：副模型读正文、正文自报标签 ========================
  // 只在本轮没有工具调用时用。副模型只抄原文短语和数额，换算全在引擎；每一条都要带正文原话，
  // 原话不在这一楼正文里的丢掉，数额在原话里找不到的标存疑、不采纳。

  const GENERATE_URL = '/api/backends/chat-completions/generate';

  const GE_CALL = (() => {
    let running = 0, coolUntil = 0;
    const waiters = [];
    const yq = s => '"' + String(s).replace(/\\/g, '\\\\').replace(/"/g, '\\"') + '"';
    const excludeYaml = raw => String(raw || '').split(/[\s,，、;；]+/).map(x => x.replace(/^[-*]+/, '').match(/^[A-Za-z_][\w.-]*/))
      .filter(Boolean).map(m => '- ' + m[0]).join('\n');

    async function acquire() {
      for (;;) {
        const wait = coolUntil - Date.now();
        if (wait > 0) await sleep(wait);
        if (running < Math.max(1, cfg().同时最多请求数)) { running++; return; }
        await new Promise(r => waiters.push(r));
      }
    }
    function release() { running--; const w = waiters.shift(); if (w) w(); }

    // 中转把报错当成回答转回来：「[API 错误]」「[Error]」「错误：」开头，或者整条是 {"error": …}
    function wrappedError(text) {
      const t = String(text || '').trim();
      if (/^\[(API\s*错误|Error|ERROR)\]|^错误[:：]/.test(t)) return t.slice(0, 200);
      if (/^\{\s*"error"\s*:/.test(t)) return t.slice(0, 200);
      return '';
    }

    function parseJsonLoose(text) {
      let s = String(text || '').trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
      try { return JSON.parse(s); } catch (e) { /* 再试 */ }
      const a = s.indexOf('{'), b = s.lastIndexOf('}');
      if (a >= 0 && b > a) return JSON.parse(s.slice(a, b + 1));
      throw new Error('返回的不是 JSON：' + s.slice(0, 80));
    }

    async function chat(system, user, schema) {
      const c = cfg();
      if (c.副模型来源 === '宿主提供') {
        if (!HOST.sideCaller) throw new Error('宿主没有提供副模型');
        const text = await HOST.sideCaller({ messages: [{ role: 'system', content: system }, { role: 'user', content: user }], schema });
        const w = wrappedError(text);
        if (w) throw new Error(w);
        return parseJsonLoose(text);
      }
      const ctx = getCtx();
      if (!ctx || typeof ctx.getRequestHeaders !== 'function') throw new Error('拿不到酒馆上下文');
      const key = getApiKey();
      const sendSchema = c.结构约束 && !/response_format/.test(c.排除主体参数 || '');
      const body = {
        chat_completion_source: 'custom',
        custom_url: String(c.副API地址).trim(),
        custom_include_headers: key ? 'Authorization: ' + yq('Bearer ' + key) : '',
        custom_include_body: c.附加请求体 || '',
        custom_exclude_body: excludeYaml(c.排除主体参数),
        model: String(c.副模型).trim(),
        messages: [
          { role: 'system', content: system + (sendSchema ? '' : '\n\n【JSON Schema】\n只输出一个照这个结构的 JSON 对象：\n' + JSON.stringify(schema)) },
          { role: 'user', content: user },
        ],
        max_tokens: 1200, temperature: 0.2, stream: false,
      };
      if (sendSchema) body.json_schema = { name: 'ge_events', strict: false, value: schema };
      await acquire();
      const ctrl = new (TOP.AbortController || AbortController)();
      const timer = setTimeout(() => ctrl.abort(), c.抽取等待秒 * 1000);
      try {
        const r = await TOP.fetch(TOP.location.origin + GENERATE_URL, {
          method: 'POST', headers: ctx.getRequestHeaders(), body: JSON.stringify(body), signal: ctrl.signal,
        });
        const text = await r.text();
        let j = null;
        try { j = JSON.parse(text); } catch (e) { /* 下面报错 */ }
        if (r.status === 429 || /\b429\b|too many requests/i.test(text)) { coolUntil = Date.now() + 15000; throw new Error('限流（429）'); }
        if (!r.ok || !j || j.error) throw new Error('副模型报错：' + String((j && j.error && (j.error.message || JSON.stringify(j.error))) || text).slice(0, 160));
        const content = (j.choices && j.choices[0] && j.choices[0].message && j.choices[0].message.content) || '';
        const w = wrappedError(content);
        if (w) throw new Error(w);
        if (!content.trim()) throw new Error('副模型返回了空内容');
        return parseJsonLoose(content);
      } catch (e) {
        if (e && e.name === 'AbortError') throw new Error(`副模型超过 ${c.抽取等待秒} 秒没回`);
        throw e;
      } finally {
        clearTimeout(timer);
        release();
      }
    }

    return { chat, parseJsonLoose, wrappedError };
  })();

  // ---------- 正文自报标签：<账本>{ 和工具参数一样的 JSON }</账本> ----------
  const GE_TAG = {
    parse(mes) {
      const m = /<账本>([\s\S]*?)<\/账本>/.exec(String(mes || ''));
      if (!m) return null;
      try { return normalizeArgs(GE_CALL.parseJsonLoose(m[1])); } catch (e) { warn('账本标签不是合法的 JSON：', e); return null; }
    },
  };

  // ---------- 副模型抽取 ----------
  const GE_SIDE = (() => {
    const normQ = s => String(s || '').replace(/[\s，,。.！!？?、；;：:「」『』“”‘’"'（）()【】《》<>…—\-~～·]/g, '');

    function enabled() {
      const c = cfg();
      if (!c.副模型兜底) return false;
      if (c.副模型来源 === '宿主提供') return !!HOST.sideCaller;
      return !!(String(c.副API地址).trim() && String(c.副模型).trim());
    }

    function names(P) {
      const L = latest();
      const S = L.S || {};
      const people = new Set([...(HOST.people || []), ...Object.keys(S.rel || {})]);
      if (P.on.routine) Object.keys(P.routine.routines).forEach(x => people.add(x));
      return [...people];
    }

    const CLUE = /(\d{1,2}\s*[:：]\s*\d{2}|[0-9一二两三四五六七八九十]+\s*[点點時]|分钟|小时|钟头|天后|明天|后天|次日|翌日|第二天|周[一二三四五六日天]|星期|上午|中午|下午|傍晚|晚上|夜里|深夜|凌晨|\d[\d,，]*\s*(?:円|日元|元|块)|[一二两三四五六七八九十百千万]+\s*(?:円|日元|元|块))/;

    function hasClues(P, text) {
      if (CLUE.test(text)) return true;
      if (P.on.ledger && [...P.ledger.resIds, ...P.ledger.itemIds].some(x => x && text.includes(x))) return true;
      if (names(P).some(x => x && text.includes(x))) return true;
      return false;
    }

    function schemaFor(P) {
      const str = { type: 'string' };
      const quote = { type: 'string', description: '支撑这一条的正文原话，一字不改' };
      const props = {
        time: {
          type: 'object',
          properties: {
            scope: { type: 'string', enum: ['present', 'past', 'future', 'hypothetical'] },
            elapsed: str, jump: str,
            stated_today: { type: 'object', properties: { weekday: str, date: str } },
            quote,
          },
        },
      };
      const list = (p, req) => ({ type: 'array', items: { type: 'object', properties: { ...p, quote }, required: [...req, 'quote'] } });
      if (P.on.map) props.moves = list({ to: str, by: str }, ['to']);
      if (P.on.ledger) {
        props.changes = list({ target: str, op: { type: 'string', enum: ['spend', 'gain', 'set'] }, amount: { type: 'number' }, from: { type: 'array', items: str } }, ['target', 'op', 'amount']);
        if (P.ledger.itemIds.length) props.trades = list({ with: str, give: { type: 'array', items: { type: 'object', properties: { target: str, amount: { type: 'number' } } } }, get: { type: 'array', items: { type: 'object', properties: { target: str, amount: { type: 'number' } } } } }, ['give', 'get']);
      }
      if (P.on.relation && cfg().副模型抽关系 !== false) props.relations = list({ who: str, dim: str, delta: { type: 'number' } }, ['who', 'dim', 'delta']);
      if (P.on.routine) {
        props.excepts = list({ who: str, what: str, until: str }, ['who', 'what']);
        props.appts = list({ action: { type: 'string', enum: ['add', 'done', 'cancel', 'move'] }, id: str, title: str, when: str }, ['action']);
      }
      props.timers = list({ title: str, duration: str }, ['title', 'duration']);
      return { type: 'object', properties: props };
    }

    function systemFor(P) {
      const lines = [
        '你是记账员。只从「本楼正文」里抽出已经发生的、可以计算的事项，按给定结构输出一个 JSON 对象，不写别的。',
        '只抽正文里明确写出来的事；没写的不补、不推测、不计算。',
        'time.scope：正在发生写 present；回忆写 past；预告、计划写 future；假设写 hypothetical。',
        'time.elapsed 抄经过的时长原文（例如「两个小时」）；time.jump 抄跳转词原文（例如「次日」「三天后」）；没有就不填。',
        'time.stated_today 填正文声称的今天是周几、几号，没写就留空。',
        '每一条都填 quote：支撑这一条的正文原话，一字不改。',
        '数额只写这一笔本身，不写余额，不写合计。',
      ];
      if (P.on.ledger) lines.push('资源和物品只用这些名字：' + [...P.ledger.resIds, ...P.ledger.itemIds].join('、') + '。');
      if (P.on.relation && cfg().副模型抽关系 !== false) lines.push('关系维度只用这些：' + P.relation.dims.map(d => d.id).join('、') + '；delta 是这一楼的变化量。');
      if (P.on.map) lines.push('交通方式只用这些：' + P.map.modes.map(m => m.name).join('、') + '。');
      if (P.on.routine) lines.push('excepts：角色这段时间不按平常的作息（请假、留下、改了安排）。appts：说定了的约定。');
      return lines.join('\n');
    }

    function userFor(P, S, playerText, text) {
      const sum = [];
      sum.push('现在：' + GE.settle.nowText(P, S.clock.t));
      if (S.loc) sum.push('所在：' + S.loc);
      if (P.on.ledger) sum.push('资源：' + Object.entries(GE.ledger.summary(P, S)).map(([k, v]) => `${k} ${v}`).join('、'));
      if (P.on.routine) {
        const open = S.appts.filter(a => a.state === '未到' || a.state === '临近').map(a => `${a.id} ${a.title}`);
        if (open.length) sum.push('开放约定：' + open.join('；'));
      }
      const t = text.length > 6000 ? text.slice(0, 1200) + '\n……\n' + text.slice(-4800) : text;
      return `【账上】\n${sum.join('\n')}\n\n【玩家上一句】\n${playerText || '（无）'}\n\n【本楼正文】\n${t}`;
    }

    // 闸门：原话在不在正文里、数额在不在原话里
    function numbersIn(q) {
      const out = [];
      const s = GE.clock.toHalf(q).replace(/[,，]/g, '');
      (s.match(/\d+(\.\d+)?\s*[万千]?/g) || []).forEach(x => { const n = GE.clock.cnNum(x.replace(/\s/g, '')); if (n !== null) out.push(n); });
      (s.match(/[零〇一二两三四五六七八九十百千万]+/g) || []).forEach(x => { const n = GE.clock.cnNum(x); if (n !== null) out.push(n); });
      return out;
    }

    function gate(raw, text, rec) {
      const T = normQ(text);
      const notes = [];
      const ok = it => {
        if (!it || !it.quote) { notes.push('没带原话，丢弃'); return false; }
        if (!T.includes(normQ(it.quote))) { notes.push(`原话不在本楼正文里，丢弃：「${String(it.quote).slice(0, 20)}」`); return false; }
        return true;
      };
      const ev = {};
      const hasStamps = rec.batches.some(b => b.path === 'code' && b.ev.time && b.ev.time.stamps);
      const tm = raw.time || {};
      if (tm.scope && tm.scope !== 'present') notes.push(`时间表述是 ${tm.scope}，只记录不推进`);
      else if (!hasStamps && (tm.elapsed || tm.jump) && (!tm.quote || T.includes(normQ(tm.quote)))) {
        ev.time = { elapsed: tm.elapsed || undefined, jump: tm.jump || undefined };
      }
      const stated = tm.stated_today || null;
      const moves = (raw.moves || []).filter(ok);
      const changes = (raw.changes || []).filter(ok).filter(c => {
        const nums = numbersIn(c.quote);
        if (!nums.includes(Number(c.amount))) { notes.push(`存疑未采纳：${c.target} ${c.amount} 在原话里找不到`); return false; }
        return true;
      });
      ev.spend = changes.filter(c => c.op === 'spend').map(c => ({ target: c.target, amount: c.amount, from: c.from, what: c.quote }));
      ev.gain = changes.filter(c => c.op === 'gain').map(c => ({ target: c.target, amount: c.amount, what: c.quote }));
      ev.set = changes.filter(c => c.op === 'set').map(c => ({ target: c.target, value: c.amount }));
      ev.trade = (raw.trades || []).filter(ok);
      ev.relation = cfg().副模型抽关系 === false ? [] : (raw.relations || []).filter(ok).map(r => ({ who: r.who, dim: r.dim, delta: r.delta, why: r.quote }));
      ev.routine = (raw.excepts || []).filter(ok).map(x => ({ action: 'except', who: x.who, what: x.what, until: x.until }));
      ev.appt = (raw.appts || []).filter(ok);
      ev.timer = (raw.timers || []).filter(ok);
      return { ev, moves, notes, stated };
    }

    // 正文声称的今天和账上不一致：下一轮注入一行账上的事实
    function statedFlag(P, S, stated) {
      if (!stated || S.clock.t === null) return null;
      const day = Math.floor(S.clock.t / GE.cal.DAY);
      const wd = P.cal.weekName(P.cal.weekday(day));
      const w = String(stated.weekday || '').replace(/^(星期|礼拜)/, '周');
      if (w && /^周[一二三四五六日天]$/.test(w) && w.replace('天', '日') !== wd) {
        return { kind: 'stated', text: `上一楼正文写了${w}，账上是${wd}` };
      }
      return null;
    }

    async function run(floor, rec, m) {
      const P = PACK.P;
      const c = chatArr();
      let playerText = '';
      for (let i = floor - 1; i >= 0; i--) if (c[i] && c[i].is_user) { playerText = c[i].mes; break; }
      const text = stripTags(m.mes);
      const base = baseFor(floor).S || ensureBase(P);
      try {
        const raw = await GE_CALL.chat(systemFor(P), userFor(P, base, playerText, text), schemaFor(P));
        const cur = recFor(floor);
        if (!cur || cur !== rec || DISPOSED) return;            // 这一楼已经换了、删了，结果作废
        const g = gate(raw || {}, text, rec);
        const batches = [];
        if (Object.values(g.ev).some(v => v && (!Array.isArray(v) || v.length))) batches.push({ path: 'sub', ev: g.ev });
        for (const mv of g.moves) batches.push({ path: 'sub', ev: { move: { to: mv.to, by: mv.by } } });
        rec.batches.push(...batches);
        rec.status = 'ok';
        recomputeFrom(floor);
        const after = recFor(floor);
        if (after) {
          after.notes.push(...g.notes);
          const f = statedFlag(P, after.S, g.stated);
          if (f) after.flags.push(f);
          saveStore();
          reinject();
        }
      } catch (e) {
        const cur = recFor(floor);
        if (cur) { cur.status = 'failed'; cur.notes.push('副模型兜底失败：' + ((e && e.message) || e)); saveStore(); }
        BUS.emit('settled', { floor, failed: true });
        warn('副模型兜底失败：', e);
      }
    }

    return { enabled, hasClues, run, schemaFor, systemFor, gate, numbersIn };
  })();

  // ======================== 注入 ========================
  // <世界状态> 只在正文生成时挂（深度 1，system），不写进聊天记录、不参与世界书扫描。
  // 窗口：正文生成的生成前事件里开，生成结束、停止时关；工具调用后的那次递归请求还在窗口里。
  // 别的脚本（数据库填表、手账本的副请求）用酒馆助手的 generate 拼自己的提示词时先撤掉，拼好再挂回。

  const WIN = { armed: false, tracking: false, building: new Map() };
  const BUILD_MAX_MS = 20000;

  function foreignBuilding() {
    const now = Date.now();
    WIN.building.forEach((at, id) => { if (now - at > BUILD_MAX_MS) WIN.building.delete(id); });
    return WIN.building.size > 0;
  }

  function isMainGeneration() {
    if (foreignBuilding()) return false;
    return WIN.armed || !WIN.tracking;
  }

  // 注入块：底是「要生成的那一楼之前」的最新有效存档
  function injectionText() {
    const c = cfg();
    const P = PACK.P;
    if (!c.注入 || !P) return '';
    let floor;
    // 生成进行中：底是这一轮的落点之前；生成之外：底是聊天末尾之前（最新一份）
    if (WIN.armed && TURN.active && TURN.floor !== undefined && TURN.floor !== null) floor = TURN.floor;
    else floor = chatArr().length;
    const b = baseFor(floor);
    const S = b.S;
    if (!S || S.clock.t === null) return '';
    const rec = b.rec;
    const toolOn = c.工具调用 && toolUsable();
    // 相关的人：宿主给的在场名单、玩家这一句提到的人
    const people = new Set(HOST.people || []);
    const lastUser = [...chatArr()].reverse().find(m => m && m.is_user);
    if (lastUser) {
      const known = new Set([...Object.keys(S.rel || {}), ...(P.on.routine ? Object.keys(P.routine.routines) : [])]);
      known.forEach(n => { if (lastUser.mes && lastUser.mes.includes(n)) people.add(n); });
    }
    return GE.view.injection(P, S, envFor(P), {
      delta: rec && rec.delta, flags: rec && rec.flags, people: [...people], toolOn,
      lines: c.注入行, budget: c.注入预算, relMode: c.关系显示,
    });
  }

  function hideInjection() { try { uninjectPrompts([INJECT_ID]); } catch (e) { /* ignore */ } }

  function reinject() {
    if (DISPOSED) return;
    if (!isMainGeneration()) { hideInjection(); return; }
    let text = '';
    try { text = injectionText(); } catch (e) { warn('注入块没拼出来：', e); }
    if (!text) { hideInjection(); return; }
    try {
      injectPrompts([{ id: INJECT_ID, position: 'in_chat', depth: 1, role: 'system', content: text, should_scan: false }]);
    } catch (e) { warn('注入失败：', e); }
  }

  function armMain() { WIN.armed = true; reinject(); }
  function disarmMain() { WIN.armed = false; hideInjection(); }
  function onForeignStart(id) { WIN.building.set(id ? String(id) : 'x:' + Date.now(), Date.now()); hideInjection(); }
  function onForeignBuilt(id) {
    if (id) WIN.building.delete(String(id));
    const now = Date.now();
    WIN.building.forEach((at, k) => { if (k.startsWith('x:') && at <= now) WIN.building.delete(k); });
    if (isMainGeneration()) reinject();
  }

  // ---------- 发送前剪掉旧的 ge_call 调用记录 ----------
  // 酒馆把每次调用存成一条系统消息，之后每轮都还原成「调用 + 结果」两段送回模型。
  // 状态以注入块为准，旧结果不用留在上下文里：只留玩家最后一句之后（本轮）的调用。
  function pruneToolHistory(data) {
    if (!cfg().剪除旧调用记录 || !data || data.dryRun || !Array.isArray(data.chat)) return;
    const chat = data.chat;
    let lastUser = -1;
    for (let i = chat.length - 1; i >= 0; i--) if (chat[i] && chat[i].role === 'user') { lastUser = i; break; }
    const dropIds = new Set();
    const stale = (TURN.active && TURN.stale) || new Set();
    // 本轮里被重新生成丢掉的那次尝试的调用
    for (let i = lastUser + 1; i < chat.length; i++) {
      const m = chat[i];
      if (!m || m.role !== 'assistant' || !Array.isArray(m.tool_calls)) continue;
      const old = m.tool_calls.filter(t => t && stale.has(t.id));
      if (!old.length) continue;
      old.forEach(t => dropIds.add(t.id));
      const rest = m.tool_calls.filter(t => !stale.has(t && t.id));
      if (rest.length) m.tool_calls = rest;
      else { delete m.tool_calls; if (!String(m.content || '').trim()) m._drop = true; }
    }
    for (let i = 0; i < lastUser; i++) {
      const m = chat[i];
      if (!m || m.role !== 'assistant' || !Array.isArray(m.tool_calls)) continue;
      const mine = m.tool_calls.filter(t => t && t.function && t.function.name === TOOL_NAME);
      if (!mine.length) continue;
      mine.forEach(t => dropIds.add(t.id));
      const rest = m.tool_calls.filter(t => !(t && t.function && t.function.name === TOOL_NAME));
      if (rest.length) m.tool_calls = rest;
      else delete m.tool_calls;
    }
    if (!dropIds.size) return;
    for (let i = chat.length - 1; i >= 0; i--) {
      const m = chat[i];
      if (!m) continue;
      if (m._drop) chat.splice(i, 1);
      else if (m.role === 'tool' && dropIds.has(m.tool_call_id)) chat.splice(i, 1);
      else if (m.role === 'assistant' && !m.tool_calls && !String(m.content || '').trim() && i < lastUser) chat.splice(i, 1);
    }
    dbg('剪掉旧调用', dropIds.size);
  }

  // ---------- 聊天界面里藏起 ge_call 的调用记录 ----------
  function isOwnInvocation(m) {
    const inv = m && m.extra && m.extra.tool_invocations;
    return Array.isArray(inv) && inv.length > 0 && inv.every(x => x && x.name === TOOL_NAME);
  }

  function hideInvocationMessages() {
    if (!cfg().隐藏调用记录) return;
    try {
      const doc = TOP.document;
      chatArr().forEach((m, i) => {
        if (!isOwnInvocation(m)) return;
        const el = doc.querySelector(`#chat .mes[mesid="${i}"]`);
        if (el) el.style.display = 'none';
      });
    } catch (e) { /* 界面不在 */ }
  }

  // ======================== 工具注册与事件挂载 ========================
  const TOOL_DESC = [
    '游戏引擎的计算器：时间、钱、移动、关系、判定、算式都由它算。',
    '需要时间经过、花费或收入、移动、关系变化、判定或计算时，写正文之前先调用它。',
    '本轮所有事项放进一次调用里报完，多个角色的事项也放在一起。',
    '调用时不先输出正文。',
    '按返回的结果写正文，结果里的时间和数不改写；「未结算」的事项没有发生，按返回的原因写。',
  ].join('\n');

  function toolUsable() {
    const ctx = getCtx();
    try { return !!(ctx && ctx.isToolCallingSupported && ctx.isToolCallingSupported()); } catch (e) { return false; }
  }

  function registerTool() {
    const ctx = getCtx();
    if (!ctx || typeof ctx.registerFunctionTool !== 'function' || !PACK.P) return false;
    try {
      ctx.registerFunctionTool({
        name: TOOL_NAME,
        displayName: DISPLAY,
        description: TOOL_DESC,
        parameters: GE.registry.toolSchema(PACK.P, { calc: cfg().通用计算 }),
        action: onToolCall,
        formatMessage: () => '',
        shouldRegister: async () => !DISPOSED && cfg().工具调用 && !!PACK.P,
      });
      return true;
    } catch (e) {
      warn('工具没注册上：', e);
      return false;
    }
  }

  function unregisterTool() {
    const ctx = getCtx();
    try { if (ctx && ctx.unregisterFunctionTool) ctx.unregisterFunctionTool(TOOL_NAME); } catch (e) { /* ignore */ }
  }

  // 开场白（第 0 楼）里有完整日期的时间戳：以它为基底时间
  function baseFromGreeting(P) {
    const g = chatArr()[0];
    const base = STORE.data.base;
    if (!g || g.is_user || !base || (base.clock.t !== null && !base.fromGreeting)) return;
    for (const st of GE.clock.scanStamps(stripTags(g.mes))) {
      const p = GE.clock.parse(st);
      if (p && p.ymd && p.tod !== undefined) {
        base.clock.t = P.cal.toDay(p.ymd.y, p.ymd.m, p.ymd.d) * GE.cal.DAY + p.tod;
        base.fromGreeting = true;
        return;
      }
    }
  }

  let CHAT_GEN = 0;
  async function onChatChanged() {
    const gen = ++CHAT_GEN;
    endTurn();
    disarmMain();
    loadStore();
    await loadPack(STORE.data.over);
    if (gen !== CHAT_GEN || DISPOSED) return;
    ensureBase(PACK.P);
    baseFromGreeting(PACK.P);
    registerTool();
    hideInvocationMessages();
    const L = latest();
    if (L.S) writeView(PACK.P, L.S);
    BUS.emit('chat', { chat: STORE.chatId });
  }

  // 生成前：正文生成开一轮；工具调用后的递归请求接着用同一个缓存区
  function onAfterCommands(type, params, dryRun) {
    if (dryRun || DISPOSED || !PACK.P) return;
    if (type === 'quiet' || type === 'impersonate') return;
    if (foreignBuilding()) return;
    if (TURN.active && TURN.recursing) { TURN.recursing = false; TURN.recursedAt = Date.now(); TURN.closedAt = 0; armMain(); return; }
    startTurn(type || 'normal');
    armMain();
  }

  function onToolsPerformed() { if (TURN.active) TURN.recursing = true; }

  function onReceived(id) {
    if (DISPOSED || !PACK.P) return;
    const i = Number(id);
    const m = chatArr()[i];
    if (!isAiFloor(m)) return;
    if (i === 0 && chatArr().length === 1) { baseFromGreeting(PACK.P); saveStore(); return; }
    try { commitFloor(i); } catch (e) { warn('这一楼没存上：', e); }
  }

  // 「生成结束」在流式下每段流结束都会发一次（工具调用后的递归请求还没开始时也发），不能拿它当一轮的结束：
  // 一轮保留到下一轮开始、停止或换聊天。这里只关注入窗口；刚进递归、或者马上要递归时不关。
  function onEnded() {
    if (foreignBuilding()) return;
    if (TURN.active && (TURN.recursing || (TURN.recursedAt && Date.now() - TURN.recursedAt < 3000))) return;
    disarmMain();
    if (TURN.active) TURN.closedAt = Date.now();
  }

  function onStopped() { endTurn(); disarmMain(); WIN.building.clear(); }

  function onEdited(id) {
    const i = Number(id);
    const r = recFor(i);
    if (!r || !r.edited) return;
    if (cfg().编辑后 === '自动重算') {
      const m = chatArr()[i];
      r.batches = r.batches.filter(b => b.path !== 'code');
      const stamps = GE.clock.scanStamps(stripTags(m.mes));
      if (stamps.length) r.batches.push({ path: 'code', ev: { time: { stamps } } });
      r.h = textHash(m.mes);
      recomputeFrom(i);
    } else {
      r.notes.push('正文已改，账上还是改之前的结算');
      saveStore();
      BUS.emit('settled', { floor: i, edited: true });
    }
  }

  function onDeleted() {
    const L = latest();
    if (L.S && PACK.P) writeView(PACK.P, L.S);
    BUS.emit('settled', { deleted: true });
  }

  function onPromptReady(data) {
    if (!data || data.dryRun) return;
    if (foreignBuilding()) return;
    pruneToolHistory(data);
  }

  function boot() {
    const ev = typeof tavern_events !== 'undefined' ? tavern_events : {};
    const ie = typeof iframe_events !== 'undefined' ? iframe_events : {};
    const offs = [];
    const on = (name, fn) => { if (name) { try { offs.push(eventOn(name, fn)); } catch (e) { warn('挂不上事件', name, e); } } };
    on(ev.CHAT_CHANGED || 'chat_id_changed', onChatChanged);
    on(ev.GENERATION_AFTER_COMMANDS || 'GENERATION_AFTER_COMMANDS', onAfterCommands);
    on(ev.TOOL_CALLS_PERFORMED || 'tool_calls_performed', onToolsPerformed);
    on(ev.TOOL_CALLS_RENDERED || 'tool_calls_rendered', () => setTimeout(hideInvocationMessages, 0));
    on(ev.MESSAGE_RECEIVED || 'message_received', onReceived);
    on(ev.GENERATION_ENDED || 'generation_ended', onEnded);
    on(ev.GENERATION_STOPPED || 'generation_stopped', onStopped);
    on(ev.MESSAGE_EDITED || 'message_edited', onEdited);
    on(ev.MESSAGE_DELETED || 'message_deleted', onDeleted);
    on(ev.MESSAGE_SWIPED || 'message_swiped', () => BUS.emit('settled', { swiped: true }));
    on(ev.MORE_MESSAGES_LOADED || 'more_messages_loaded', hideInvocationMessages);
    on(ev.CHAT_COMPLETION_PROMPT_READY || 'chat_completion_prompt_ready', onPromptReady);
    if (ie.GENERATION_STARTED || ie.GENERATION_REQUESTED) {
      WIN.tracking = true;
      on(ie.GENERATION_REQUESTED || 'js_generation_requested', onForeignStart);
      on(ie.GENERATION_STARTED || 'js_generation_started', onForeignBuilt);
      on(ie.GENERATION_ENDED || 'js_generation_ended', onForeignBuilt);
    }
    onDispose(() => offs.forEach(o => { try { o && o.stop ? o.stop() : typeof o === 'function' && o(); } catch (e) { /* ignore */ } }));
    onDispose(() => { unregisterTool(); hideInjection(); });
    onChatChanged().catch(e => warn('初始化失败：', e));
    log(`v${VERSION} 已启动`);
  }

  // ======================== 公开接口 __GE__ ========================
  // 给宿主卡的总控脚本、面板、其他脚本用。都是同步或返回 Promise 的普通函数，挂在顶层窗口上。

  function currentS() { const L = latest(); return L.S; }

  function addBatch(floor, batch) {
    const c = chatArr();
    const f = floor === undefined || floor === null ? lastAiFloor() : floor;
    if (f < 0) {
      // 还没有 AI 楼层：直接改基底
      const r = GE.settle.run(STORE.data.base || ensureBase(PACK.P), batch.ev, envFor(PACK.P, { path: batch.path }));
      STORE.data.base = r.state;
      saveStore();
      return r;
    }
    let rec = recFor(f);
    if (!rec) {
      const m = c[f];
      rec = { floor: f, sd: m.send_date, sw: m.swipe_id || 0, h: textHash(m.mes), src: batch.path, status: 'ok', batches: [], S: null, results: [], notes: [], flags: [], delta: {}, at: Date.now() };
      putRec(rec);
    }
    rec.batches.push(batch);
    recomputeFrom(f);
    return recFor(f);
  }

  const API = {
    version: VERSION,
    get ready() { return !!PACK.P && !!STORE.data; },

    // 读
    getState() { const S = currentS(); return S ? JSON.parse(JSON.stringify(S)) : null; },
    getView() { const S = currentS(); return S && PACK.P ? GE.view.flat(PACK.P, S, envFor(PACK.P), HOST.people) : null; },
    // now：这一楼过完时的时间（「2020-04-08 周三 16:40 傍晚」），这一楼时间没动也有；没设时间是「未设置」
    getRecord(floor) {
      const f = floor === undefined ? lastAiFloor() : floor;
      const r = recFor(f);
      const now = r && r.S && r.S.clock && PACK.P ? GE.settle.nowText(PACK.P, r.S.clock.t) : '';
      return r ? JSON.parse(JSON.stringify({ floor: r.floor, src: r.src, status: r.status, now, results: r.results, notes: r.notes, flags: r.flags, delta: r.delta, calls: r.calls, edited: r.edited })) : null;
    },
    injectionPreview() { return injectionText(); },
    packInfo() { return { name: PACK.P && PACK.P.name, source: PACK.source, errs: PACK.errs.slice(), modules: PACK.P ? Object.keys(PACK.P.on).filter(k => PACK.P.on[k]) : [] }; },

    // 只算不改
    calc(expr) {
      const P = PACK.P, S = currentS();
      const r = GE.expr.calc(expr, name => (S ? GE.rules.lookup(P, S, envFor(P), name) : undefined));
      return r.ok ? { 值: r.value } : { 错误: r.err };
    },
    // 地图：两地之间某种方式的路线形状（给地图画线）、所在地的坐标；只算不改
    route(a, b, by) {
      const P = PACK.P, S = currentS();
      if (!S || !P || !P.on.map) return null;
      return GE.map.geometry(P, S, envFor(P), a, b, by);
    },
    locate(text) {
      const P = PACK.P, S = currentS();
      if (!S || !P || !P.on.map) return null;
      return GE.map.locate(P, S, text);
    },
    // 房产：住在哪、名下各处、欠的房租、下次交租，住宅区目录（价钱、买不买得起）；只读
    estate() {
      const P = PACK.P, S = currentS();
      if (!S || !P || !P.on.estate) return null;
      return JSON.parse(JSON.stringify(GE.estate.view(P, S)));
    },
    // 每个住宅区到某地最快怎么走（{ 住宅区: { 方式, 分钟 } }）；只算不改
    estateCommute(to) {
      const P = PACK.P, S = currentS();
      if (!S || !P || !P.on.estate) return null;
      return GE.estate.commute(P, S, envFor(P), to);
    },
    query(q) {
      const P = PACK.P, S = currentS();
      if (!S) return null;
      return GE.settle.run(S, { query: Array.isArray(q) ? q : [q] }, envFor(P)).results;
    },

    // 写：都记成一批事项进最新一楼（或指定楼），然后从那一楼重算
    applyEvents(events, opts) {
      opts = opts || {};
      return addBatch(opts.floor, { path: opts.path || 'ext', ev: events, seed: `${STORE.chatId}|ext|${Date.now()}` });
    },
    setClock(text, reason) {
      const P = PACK.P;
      const p = GE.clock.parse(text);
      if (!p || !p.ymd || p.tod === undefined) return { 错误: '写成「YYYY-MM-DD HH:MM」' };
      const t = P.cal.toDay(p.ymd.y, p.ymd.m, p.ymd.d) * GE.cal.DAY + p.tod;
      addBatch(undefined, { path: 'manual', ev: { clockSet: t }, why: reason || '' });
      return { 现在: GE.settle.nowText(P, t) };
    },
    settleNow(floor) {
      const f = floor === undefined ? lastAiFloor() : floor;
      if (recFor(f)) recomputeFrom(f);
      else commitFloor(f);
      return API.getRecord(f);
    },

    // 宿主
    // 基底：{ 时间: 'YYYY-MM-DD HH:MM' 或 t, 地点, res: { '玩家.钱': 10000 }, rel: { 角色: { 好感: 50 } } }
    setBase(base, opts) {
      opts = opts || {};
      const P = PACK.P;
      const hasRecs = Object.keys(STORE.data.recs).length > 0;
      const noClock = !STORE.data.base || STORE.data.base.clock.t === null;
      // 已有楼层存档时：还没有时间的基底可以补交（已有楼层在新基底上重算）；有时间的要带 force
      if (hasRecs && !opts.force && !noClock) return { 错误: '这个聊天已经有楼层存档；要重设基底请带 force' };
      let t = base && base.t;
      if (t === undefined && base && base['时间']) {
        const p = GE.clock.parse(base['时间']);
        if (p && p.ymd) t = P.cal.toDay(p.ymd.y, p.ymd.m, p.ymd.d) * GE.cal.DAY + (p.tod ?? 0);
      }
      STORE.data.base = GE.registry.baseState(P, { t, loc: base && base['地点'], res: base && base.res, items: base && base.items, rel: base && base.rel, estate: base && base.estate });
      if (opts.force && !opts.keep) STORE.data.recs = {};
      saveStore();
      if (hasRecs && (opts.keep || noClock)) recomputeFrom(0);
      else { writeView(P, STORE.data.base); reinject(); }
      return { 现在: GE.settle.nowText(P, STORE.data.base.clock.t) };
    },
    // 宿主维护的字段：{ loc, appts, scope, items, people, vars, floor }
    hostSync(patch) {
      patch = patch || {};
      if (patch.items) HOST.items = patch.items;
      if (patch.people) HOST.people = patch.people;
      if (patch.vars) HOST.vars = patch.vars;
      const f = patch.floor === undefined ? lastAiFloor() : patch.floor;
      const set = {};
      const o = engineOpts();
      if (patch.loc !== undefined && o.locSource === 'host') set.loc = patch.loc;
      if (Array.isArray(patch.appts) && o.apptSource === 'host') set.appts = patch.appts;
      let changed = false;
      const r = recFor(f);
      if (r && patch.scope && patch.scope !== 'present') {
        // 宿主判断这一楼不是「现在」（回忆、梦境、想象）：代码读到、副模型抽到的时间不推进
        for (const b of r.batches) if ((b.path === 'code' || b.path === 'sub') && b.ev.time) b.ev.time.scope = patch.scope;
        changed = true;
      }
      if (Object.keys(set).length) {
        if (r) { r.batches = r.batches.filter(b => b.path !== 'hostSet'); r.batches.push({ path: 'hostSet', ev: { hostSet: set } }); changed = true; }
        else addBatch(f, { path: 'hostSet', ev: { hostSet: set } });
      }
      if (changed && r) recomputeFrom(f);
      else reinject();
      return true;
    },
    setSideCaller(fn) { HOST.sideCaller = typeof fn === 'function' ? fn : null; return true; },
    async usePack(pack) {
      PACK.host = pack || null;
      await loadPack(STORE.data && STORE.data.over);
      if (STORE.data && !STORE.data.base) ensureBase(PACK.P);
      registerTool();
      reinject();
      return API.packInfo();
    },
    // 聊天内的规则包改动（只存差异）。recompute：已有楼层按改过的规则包从头重算（例如补交关系初值后）
    packOverride() { return STORE.data && STORE.data.over ? JSON.parse(JSON.stringify(STORE.data.over)) : null; },
    async setPackOverride(over, opts) {
      STORE.data.over = over || null;
      saveStore();
      compilePack(STORE.data.over);
      registerTool();
      // 关系初值里的人放进基底：从第一楼起账上就有他们
      const P = PACK.P;
      if (P.on.relation && STORE.data.base) {
        for (const who of Object.keys(P.relation.initBy)) if (!STORE.data.base.rel[who]) GE.relation.ensure(P, STORE.data.base, who);
      }
      if (opts && opts.recompute) recomputeFrom(0);
      return API.packInfo();
    },

    // 设置
    settings() { return { ...cfg() }; },
    setSetting(key, value) {
      const next = setCfg({ [key]: value });
      if (key === '通用计算') registerTool();
      reinject();
      return next[key];
    },
    setApiKey(k) { setApiKey(k); return true; },

    on(name, cb) { return BUS.on(name, cb); },
    openPanel() { return false; },
    dispose() {
      if (DISPOSED) return;
      DISPOSED = true;
      DISPOSERS.splice(0).reverse().forEach(fn => { try { fn(); } catch (e) { /* ignore */ } });
      try { if (TOP.__GE__ === API) delete TOP.__GE__; } catch (e) { /* ignore */ }
    },
    debug: {
      get on() { return DEBUG; }, set on(v) { DEBUG = !!v; },
      core: GE, store: () => STORE.data, turn: () => TURN, pack: () => PACK, host: () => HOST,
      replay: f => recomputeFrom(f),
    },
  };

  // ======================== 启动 ========================
  TOP.__GE__ = API;
  try { if (typeof initializeGlobal === 'function') initializeGlobal('GameEngine', API); } catch (e) { /* 旧版酒馆助手没有 */ }
  boot();
})();

/**
 * BanG 引擎接线 v0.1.0
 * 酒馆助手脚本：把「游戏引擎」接到 BanG 卡（正常内容）上。卡里同时开着 BanG 总控、游戏引擎、这条接线。
 * ==================================================================
 * 引擎本体不含任何一张卡的代码，BanG 这边的事都在这里，经两边公开的接口办：
 *   · 总控：BanGCtl（snapshot、editRow，事件 BanGCtl:data）
 *   · 引擎：__GE__（setBase、hostSync、applyEvents、setSideCaller，事件 settled）
 *
 * 分工（每一格由谁写）：
 *   引擎写回并锁住：全局数据表的当前时间、经过的时间、年份、时节；主角现况表的持有金钱、体力；重要角色表的好感度、信任度
 *   填表 AI 照旧写：场景类型、天气、地点三列、日程表、物品表、足迹表、关系阶段、最近变化、心声……
 *   引擎从数据库读：地点（所在地以它为准）、日程表（只读，算临近和已过多久）、场景类型（回忆梦境想象不推进时间）、
 *                   物品表（交通工具的条件）、在场的人（注入作息、关系）、最近变化（「好感 +20」交给引擎记账；
 *                   不带数的、新交的人记一笔变化 0，只留原因给面板动态页）、
 *                   主角现况表的体力变化（「体力 -15 · 排练」交给引擎记账；睡觉、醒着随时间的变化引擎自己算）
 *   副模型：用卡自己的帮填接口（总控 BanGCtl.ask），没配就不挂；不借数据库的 callAI（见 lendSideModel）
 */

(function () {
  'use strict';

  const TOP = (function () {
    try { if (window.parent && window.parent.document) return window.parent; } catch (e) { /* 跨域 */ }
    return window;
  })();
  try { const prev = TOP.__GE_BANG__; if (prev && prev.dispose) prev.dispose(); } catch (e) { /* ignore */ }

  const VERSION = '0.1.10';
  const VAR = 'ge_bang';                 // 聊天变量：接线自己的记录（交过基底没有、上次同步了什么）
  const log = (...a) => console.log('%c[BanG 接线]', 'color:#d0739b;font-weight:bold', ...a);
  const warns = [];   // 最近几条警告，writeState 里看得到（查写回没落成的原因）
  const warn = (...a) => { console.warn('[BanG 接线]', ...a); warns.push(a.map(x => String((x && x.message) || x)).join(' ').slice(0, 300)); if (warns.length > 8) warns.shift(); };
  const sleep = ms => new Promise(r => setTimeout(r, ms));
  let DISPOSED = false;
  const offs = [];

  const SCOPE = { 现实: 'present', 他人视角: 'present', 回忆: 'past', 梦境: 'hypothetical', 想象: 'hypothetical' };
  const 取数 = v => { const m = /-?\d+(\.\d+)?/.exec(String(v == null ? '' : v).replace(/[,，]/g, '')); return m ? Number(m[0]) : null; };
  // 年份格记学年：1 月到春的起点（时节.json 3/26）之前仍是冬，算上一学年。世界书的年级、剧情总览、剧情档都按学年分
  function 学年(stamp, 季节) {
    const y = Number(stamp.slice(0, 4)), m = Number(stamp.slice(5, 7));
    const 冬 = 季节 ? String(季节).charAt(0) === '冬' : true;
    return String(m <= 3 && 冬 ? y - 1 : y);
  }

  function readVar() { try { return (getVariables({ type: 'chat' }) || {})[VAR] || {}; } catch (e) { return {}; } }
  function writeVar(patch) {
    const v = { ...readVar(), ...patch };
    try { updateVariablesWith(vars => { vars[VAR] = v; return vars; }, { type: 'chat' }); } catch (e) { warn('记录没存上：', e); }
    return v;
  }

  async function waitFor(get, sec) {
    for (let i = 0; i < sec * 4; i++) {
      if (DISPOSED) return null;
      const x = get();
      if (x) return x;
      await sleep(250);
    }
    return null;
  }

  let CTL = null, GE = null;
  function ctl() {
    try { if (typeof BanGCtl !== 'undefined' && BanGCtl && typeof BanGCtl.snapshot === 'function') return BanGCtl; } catch (e) { /* 还没共享过来 */ }
    return TOP.BanGCtl && typeof TOP.BanGCtl.snapshot === 'function' ? TOP.BanGCtl : null;
  }

  // ---------- 开局：把数据库里的初值交给引擎当基底 ----------
  function baseFromSnapshot(snap) {
    const rel = {};
    for (const c of snap.角色 || []) {
      if (c.其他) continue;
      const o = {};
      if (c.好感数 !== null && c.好感数 !== undefined) o.好感 = c.好感数;
      if (c.信任数 !== null && c.信任数 !== undefined) o.信任 = c.信任数;
      if (Object.keys(o).length) rel[c.姓名] = o;
    }
    const 现况 = (snap.主角 && snap.主角.现况) || {};
    const money = 取数(现况.持有金钱), 体力 = 取数(现况.体力);
    const res = {};
    if (money !== null) res['玩家.钱'] = money;
    if (体力 !== null) res['玩家.体力'] = 体力;
    return {
      时间: snap.当前时间,
      地点: (snap.地点 && (snap.地点.详细 || snap.地点.次要)) || undefined,
      res: Object.keys(res).length ? res : undefined,
      rel,
    };
  }

  function maybeBase(snap) {
    if (!snap || !snap.当前时间) return;
    // 开局写初值是一张表一张表写的：等开局完成、各表都有了再交，免得交出一份缺人缺钱的基底
    const st = ctl().state();
    if (!st || st.状态 !== '已开局') return;
    const S = GE.getState();
    const noClock = !S || S.clock.t === null;
    if (readVar().基底 && !noClock) return;
    // 引擎还没有时间：用数据库的初值当基底，已有的楼层在它上面重算
    const r = GE.setBase(baseFromSnapshot(snap), { keep: true });
    if (r && r.错误) { writeVar({ 基底: '已有存档，没交' }); return; }
    writeVar({ 基底: Date.now() });
    log('交了基底：', r && r.现在);
  }

  // ---------- 引擎结算后：写回数据库并锁住 ----------
  // 数据库填表进行中会拒绝外部写入（它的日志里记一条「已拒绝外部表格写入」）：先记下，填完再写。
  // 新的一楼刚落地，数据库紧接着要填这一楼。1.2.4 自动填表是静默的（不发「填表开始」），而且它先抄一份表、
  // 隔两步才把自己标成「在填」：这中间写进去的一格不会被拒，却让它填完时对不上版本，这一轮填表整轮作废
  // （runtime revision conflict，纪要、新来的人都丢）。它填完先通知「表更新了」、半秒后才放下「在填」再通知一次。
  // 总控 0.12 起会说数据库忙不忙（dbBusy：在填、这一楼等它填、刚填完）：忙就每秒再问，不忙再写；
  // 新楼落地先挂 1.5 秒让总控记下这一楼。旧总控没有 dbBusy：照旧挂 HOLD_MS 躲过它开头那一段
  const HOLD_MS = 6000;
  let writing = false, pendingWrite = false, holdUntil = 0, holdTimer = null, retryTimer = null;
  function dbBusy() {
    try { const c = ctl(); return c && typeof c.dbBusy === 'function' ? (c.dbBusy() || '') : null; } catch (e) { return null; }
  }
  function holdForFill() {
    holdUntil = Date.now() + (dbBusy() === null ? HOLD_MS : 1500);
    pendingWrite = true;
    clearTimeout(holdTimer);
    holdTimer = setTimeout(() => { holdUntil = 0; if (pendingWrite) writeBack(); }, HOLD_MS);
  }
  const trail = [];   // 写回每次停在哪（writeState 里看得到）
  const mark = x => { trail.push(new Date().toISOString().slice(14, 23) + ' ' + x); if (trail.length > 16) trail.shift(); };
  async function writeBack() {
    if (DISPOSED) return;
    if (writing || Date.now() < holdUntil) { pendingWrite = true; mark(writing ? '写着' : '挂起'); return; }
    const 忙 = dbBusy();
    if (忙) {
      pendingWrite = true;
      mark('等数据库·' + 忙);
      clearTimeout(retryTimer);
      retryTimer = setTimeout(() => { if (pendingWrite) writeBack(); }, 1000);
      return;
    }
    const snap = ctl().snapshot();
    const S = GE.getState();
    if (!snap || !S || S.clock.t === null) { mark('没有表或时间'); return; }
    if (snap.填表中) { pendingWrite = true; mark('填表中'); return; }
    if (!readVar().基底) { mark('没交基底'); return; }                 // 开局完成、交过基底之后才写回
    pendingWrite = false;
    writing = true;
    try {
      const now = GE.query('时间')[0].现在;                         // 「2020-04-15 周三 11:10 白天」
      const stamp = now.split(' ').slice(0, 3).join(' ');
      const view = GE.getView() || {};
      const rec = GE.getRecord();
      const 要 = { 当前时间: stamp, 年份: 学年(stamp, view.季节) };
      if (view.季节) 要.时节 = view.季节;
      if (rec && rec.delta && rec.delta.分钟 > 0) 要.经过的时间 = fmtDur(rec.delta.分钟);
      // 只写变了的格子：每写一次数据库都要存一次档、版本跟着变
      const g = {};
      for (const k of Object.keys(要)) if (String(snap[k] || '') !== String(要[k])) g[k] = 要[k];
      // 一格要写一两秒，几格下来能拖到下一楼落地：新楼一挂起，剩下的值等挂起完了重新算、再写（锁照上，锁不动表的版本）
      let 停 = false;
      const 让路 = () => (停 = 停 || Date.now() < holdUntil);
      if (Object.keys(g).length) await ctl().editRow('全局数据表', 0, g);
      const money = S.res && S.res['玩家.钱'], 体力 = S.res && S.res['玩家.体力'];
      const 现况 = (snap.主角 && snap.主角.现况) || {};
      const 现改 = {};
      if (money !== undefined && String(现况.持有金钱 == null ? '' : 现况.持有金钱) !== String(money)) 现改.持有金钱 = String(money);
      // 表里没有体力这一列（还没升级的旧局）就不写
      if (体力 !== undefined && 现况.体力 !== undefined && String(现况.体力) !== String(体力)) 现改.体力 = String(体力);
      if (!让路() && Object.keys(现改).length) await ctl().editRow('主角现况表', 0, 现改);
      for (const c of snap.角色 || []) {
        if (让路()) break;
        const r = S.rel && S.rel[c.姓名];
        if (!r || c._行 === undefined) continue;
        const ch = {};
        if (r.好感 !== undefined && r.好感 !== c.好感数) ch.好感度 = String(r.好感);
        if (r.信任 !== undefined && r.信任 !== c.信任数) ch.信任度 = String(r.信任);
        // 关系阶段跟好感走（总控的分界，0.2.1 起有；0.3.0 起千分制、和手账本同一套七档）：好感变了阶段跟着变。
        // 填表 AI 只有情侣、夫妻能写：正文里确定了关系才写，好感没跌破在意的人那条线（550）就留着，别的写了也会被这里改回按好感算的那一档
        const 好 = r.好感 !== undefined ? r.好感 : c.好感数;
        const 阶 = typeof ctl().stageOf === 'function' && 好 != null ? ctl().stageOf(好, c.关系阶段) : '';
        if (阶 && 阶 !== c.关系阶段) ch.关系阶段 = 阶;
        if (Object.keys(ch).length) await ctl().editRow('重要角色表', c._行, ch);
      }
      // 引擎负责的格子，值没变的也锁上：填表 AI 改不了
      const lockAll = (表, 行, 列们) => {
        const lk = ctl().locks(表, 行) || {};
        for (const 列 of 列们) if (lk[列] === false) ctl().lock(表, 行, 列);
      };
      lockAll('全局数据表', 0, ['当前时间', '经过的时间', '年份', '时节']);
      lockAll('主角现况表', 0, [money !== undefined && '持有金钱', 体力 !== undefined && 现况.体力 !== undefined && '体力'].filter(Boolean));
      for (const c of ctl().snapshot().角色 || []) {
        const handed = ((GE.packOverride() || {})['关系初值'] || {})[c.姓名];
        // 关系阶段不锁：填表 AI 要能写情侣、夫妻（上面按好感改回去的不算数）
        if (c._行 !== undefined && ((S.rel && S.rel[c.姓名]) || handed)) lockAll('重要角色表', c._行, ['好感度', '信任度']);
      }
      if (停) pendingWrite = true;
      mark('写完' + (停 ? '（让路）' : '') + ' ' + Object.keys(g).join('、'));
    } catch (e) {
      mark('出错 ' + ((e && e.message) || e));
      pendingWrite = true;                 // 多半是撞上了填表：填完再写一次
      warn('写回数据库没成，填表完成后再写：', (e && e.message) || e);
    } finally {
      writing = false;
    }
  }

  // 引擎的格子有没锁上的：升级、恢复、重新导入以后表是重建的，不等下一楼，表一更新就写回一次
  function 有没锁的() {
    try {
      const g = ctl().locks('全局数据表', 0) || {}, x = ctl().locks('主角现况表', 0) || {};
      return g.当前时间 === false || x.持有金钱 === false || x.体力 === false;
    } catch (e) { return false; }
  }

  function fmtDur(m) {
    if (m < 60) return m + ' 分钟';
    const d = Math.floor(m / 1440), h = Math.floor((m % 1440) / 60), mm = m % 60;
    return [d ? d + ' 天' : '', h ? h + ' 小时' : '', mm ? mm + ' 分钟' : ''].filter(Boolean).join(' ');
  }

  // ---------- 填表完成后：把数据库维护的字段同步给引擎 ----------
  let lastSync = '';
  function syncFromDb(snap) {
    if (!snap || DISPOSED) return;
    maybeBase(snap);
    const items = {};
    for (const it of snap.物品 || []) {
      const n = String(it.物品 || '').trim();
      if (n) items[n] = (items[n] || 0) + (取数(it.数量) || 1);
    }
    const patch = {
      loc: (snap.地点 && (snap.地点.详细 || snap.地点.次要)) || '',
      appts: (snap.日程 || []).map(r => ({ 日期: r.日期, 时刻: r.时刻, 事项: r.事项, 地点: r.地点, 参与者: r.参与者, 状态: r.状态 })),
      scope: SCOPE[String(snap.场景类型 || '现实').trim()] || 'present',
      items,
      people: (snap.角色 || []).filter(c => !c.离场 && !c.其他).map(c => c.姓名),
    };
    const key = JSON.stringify(patch);
    if (key !== lastSync) {
      lastSync = key;
      GE.hostSync(patch);
    }
    const fresh = handOverNewPeople(snap);
    relationsFromDb(snap, fresh);
    staminaFromDb(snap);
  }

  // 填表 AI 中途加进表的人：引擎账上没有，第一次变化会从默认值算起。
  // 把表里现有的好感、信任作为「关系初值」交给引擎（聊天内的规则包差异），已有楼层从头重算，再锁上这两格。
  // 返回这次新交的人：他们这一次的「最近变化」已经算在表里的数里了，不再记账
  function handOverNewPeople(snap) {
    const S = GE.getState();
    if (!S || S.clock.t === null || !readVar().基底) return new Set();
    const over = GE.packOverride() || {};
    const init = { ...(over['关系初值'] || {}) };
    const fresh = new Set();
    for (const c of snap.角色 || []) {
      if (c.其他 || !c.姓名 || (S.rel && S.rel[c.姓名]) || init[c.姓名]) continue;
      const o = {};
      if (c.好感数 !== null && c.好感数 !== undefined) o.好感 = c.好感数;
      if (c.信任数 !== null && c.信任数 !== undefined) o.信任 = c.信任数;
      if (!Object.keys(o).length) continue;
      init[c.姓名] = o;
      fresh.add(c.姓名);
    }
    if (!fresh.size) return fresh;
    GE.setPackOverride({ ...over, 关系初值: init }, { recompute: true });
    for (const c of snap.角色 || []) {
      if (!fresh.has(c.姓名) || c._行 === undefined) continue;
      const lk = ctl().locks('重要角色表', c._行) || {};
      for (const 列 of ['好感度', '信任度']) if (lk[列] === false) ctl().lock('重要角色表', c._行, 列);
    }
    log('交了关系初值：', [...fresh].join('、'));
    return fresh;
  }

  // 「最近变化」里的「好感 +20」：交给引擎记账（引擎按单楼上限夹取、写回数字）
  // 这一楼正文模型已经用工具报过同一个人同一个维度的，不再记，免得记两遍。
  // 不带数的（「约好周六去乐器店」）和新交的人（原因写成「初次见面 · ……」）记一笔好感变化 0：不动数、不跨档，
  // 只把这句话留在这一楼的记录里，面板动态页拿它画一行。引擎账上还没有的人不记这一笔（记了会按默认值给他开户，表里的初值就交不进去了）
  const 空话 = /^(无|暂无|没有|没变|无变化|没有变化|不变|持平|维持|none|null|n\/a|[—－\-\/／]+)$/i;
  function relationsFromDb(snap, fresh) {
    fresh = fresh || new Set();
    if (!readVar().基底) return;
    const seen = readVar().最近变化 || {};
    const rec = GE.getRecord() || { results: [] };
    const reported = new Set(rec.results.filter(x => x.项 === '关系' && x.来源 === 'tool').map(x => x.角色 + '|' + x.维度));
    const S = GE.getState();
    const 有账 = who => !!(S && S.rel && S.rel[who]);
    const evs = [];
    const next = { ...seen };
    for (const c of snap.角色 || []) {
      if (c.其他) continue;
      const text = String(c.最近变化 || '').trim();
      if (fresh.has(c.姓名)) {
        // 这一次的「最近变化」已经算在交过去的初值里了，不再记账
        if (text) next[c.姓名] = text;
        if (有账(c.姓名)) evs.push({ who: c.姓名, dim: '好感', delta: 0, why: /^初次见面/.test(text) ? text : '初次见面' + (text ? ' · ' + text : '') });
        continue;
      }
      if (!text || seen[c.姓名] === text) continue;
      next[c.姓名] = text;
      const re = /(好感|信任)度?\s*[:：]?\s*([+\-−＋－])\s*(\d+)/g;
      let m, 有数 = false;
      while ((m = re.exec(text))) {
        有数 = true;
        const dim = m[1];
        if (reported.has(c.姓名 + '|' + dim)) continue;
        const sign = /[-−－]/.test(m[2]) ? -1 : 1;
        evs.push({ who: c.姓名, dim, delta: sign * Number(m[3]), why: text });
      }
      if (!有数 && 有账(c.姓名) && !空话.test(text.replace(/[\s。.！!]/g, ''))) evs.push({ who: c.姓名, dim: '好感', delta: 0, why: text });
    }
    writeVar({ 最近变化: next });
    if (evs.length) GE.applyEvents({ relation: evs }, { path: 'host' });
  }

  // 主角现况表「体力变化」里的「体力 -15 · 排练」：交给引擎记账（引擎按上下限夹取、写回体力）。
  // 睡觉、醒着随时间的变化引擎自己算；同一句话只记一次
  function staminaFromDb(snap) {
    if (!readVar().基底) return;
    // 规则包后来才有体力（0.0.22 开的局）：引擎账上还没有这一项时，先拿表里填表 AI 记的数交给引擎，不从初值 100 算起
    const S = GE.getState(), 表体力 = 取数(snap.主角 && snap.主角.现况 && snap.主角.现况.体力);
    if (S && S.res && S.res['玩家.体力'] === undefined && 表体力 !== null) GE.applyEvents({ set: [{ target: '体力', value: 表体力 }] }, { path: 'host' });
    const text = String((snap.主角 && snap.主角.现况 && snap.主角.现况.体力变化) || '').trim();
    if (!text || readVar().体力变化 === text) return;
    writeVar({ 体力变化: text });
    const evs = { spend: [], gain: [] };
    const re = /体力\s*[:：]?\s*([+\-−＋－])\s*(\d+)/g;
    let m;
    while ((m = re.exec(text))) {
      const n = Number(m[2]);
      if (!n) continue;
      (/[-−－]/.test(m[1]) ? evs.spend : evs.gain).push({ target: '体力', amount: n, what: text });
    }
    if (evs.spend.length || evs.gain.length) GE.applyEvents(evs, { path: 'host' });
  }

  // ---------- 副模型：用卡自己的帮填接口 ----------
  // 不借数据库的 callAI：数据库走主接口时 callAI 经酒馆助手的 generateRaw，会发出「生成开始」事件；
  // 开着剧情推进（数据库默认开）的数据库会把它当成玩家又发了一句，真正那条回复的自动填表就时有时无（测试酒馆实测）。
  // 卡的帮填接口（总控 BanGCtl.ask）直连酒馆后端，不发生成事件。没配接口时不挂副模型，引擎只读正文里的时间戳；
  // 玩家之后在 ⚙ 里配好了，总控发状态事件，这里再挂上。
  let lent = false;
  function lendSideModel() {
    const s = GE.settings();
    if (String(s.副API地址 || '').trim()) return false;          // 玩家在引擎里另配了副模型：用那一套
    const k = ctl();
    const 配好 = !!(k && typeof k.ask === 'function' && typeof k.api === 'function' && k.api().配好);
    if (配好 && !lent) {
      GE.setSideCaller(async ({ messages }) => {
        const c = ctl();
        const r = c && await c.ask(messages, { max_tokens: 1200 });
        if (!r || !r.ok) throw new Error((r && r.原因) || '帮填接口没回话');
        return r.文;
      });
      GE.setSetting('副模型来源', '宿主提供');
      lent = true;
    } else if (!配好 && lent) {
      GE.setSideCaller(null);
      lent = false;
    }
    return lent;
  }

  let STAGE = '启动';
  async function start() {
    // 总控是卡的脚本，选了卡才起来；接线是全局脚本，开酒馆就起来。两路等：酒馆助手的等待、直接看主窗口，哪路先到用哪路
    STAGE = '等总控';
    // waitGlobalInitialized 只负责等，等完以后用全局的 BanGCtl（总控重载后它自动指向新的一份，所以每次用时现取）
    const viaHelper = typeof waitGlobalInitialized === 'function' ? Promise.resolve(waitGlobalInitialized('BanGCtl')).then(() => true).catch(() => null) : new Promise(() => {});
    await Promise.race([viaHelper, waitFor(() => TOP.BanGCtl && typeof TOP.BanGCtl.snapshot === 'function', 3600)]);
    CTL = await waitFor(() => ctl(), 30);
    STAGE = '等引擎';
    GE = await waitFor(() => TOP.__GE__ && TOP.__GE__.ready && TOP.__GE__, 120);
    if (!CTL || !GE || DISPOSED) { STAGE = '没等到'; warn('没等到 BanG 总控或游戏引擎：检查两个脚本都开着'); return; }
    STAGE = '接线';
    const s = GE.settings();
    if (s.所在地来源 !== '宿主') GE.setSetting('所在地来源', '宿主');
    if (s.约定来源 !== '宿主') GE.setSetting('约定来源', '宿主');
    // 关系的变化由填表 AI 写进「最近变化」、这里交给引擎；副模型兜底不再抽关系，免得记两遍
    if (s.副模型抽关系 !== false) GE.setSetting('副模型抽关系', false);
    // 导演类预设（奏明！序曲）一楼里还有剧本、平行线、选项、NPC 检索：剧本、选项、检索不是演出来的事，
    // 平行线是主角不在场的别处。不从这些块里扫场景时间戳（分镜表里排了没拍的镜头，时钟会跑到片子前面），
