  // 氛围池原文 → [{ name, cat, use, how }]。一条：第一行「【名字】类别」，下面「用在：」「写法：」各一行（没写「写法：」的，其余几行都算写法）。
  // 名字重复的只留第一条；没有写法的丢掉
  function parseMoodPool(text) {
    const out = [];
    const seen = new Set();
    String(text || '').split(/^(?=【)/m).forEach((block) => {
      const m = block.match(/^【([^】\n]{1,12})】([^\n]*)\n?([\s\S]*)$/);
      if (!m) return;
      const name = m[1].trim();
      if (!name || seen.has(name)) return;
      const lines = m[3].split('\n').map((s) => s.trim()).filter(Boolean);
      const pick = (re) => { const l = lines.find((s) => re.test(s)); return l ? l.replace(re, '').trim() : ''; };
      const use = pick(/^用在[：:]\s*/);
      let how = pick(/^写法[：:]\s*/);
      if (!how) how = lines.filter((s) => !/^(用在|写法)[：:]/.test(s)).join('');
      if (!how) return;
      seen.add(name);
      out.push({ name, cat: m[2].trim(), use: clip(use, 60), how: clip(how, 160) });
    });
    return out;
  }

  let _moodCache = { text: null, list: [] };
  function moodPool() {
    const text = promptText('氛围池');
    if (_moodCache.text !== text) _moodCache = { text, list: parseMoodPool(text) };
    return _moodCache.list;
  }

  // 基调限定氛围（内容规划书 2.5）：基调从预设里读（currentTone），没设就不限。
  // 这一场的三个候选只从「可选」里挑；越界骰从「可越界」里挑；「不出」的哪种情况都不出。
  // 氛围池里自己加的类别不在下表里，算可选
  const MOOD_CATS = ['日常与生活', '冒险与奇幻', '战斗与冲突', '悬疑与恐怖', '情感与亲密', '心理与情绪', '青春与刺痛', '舞台与团队', '扭曲与执念', '特殊与混合'];
  const MOOD_TONES = {
    日常: {
      cats: ['日常与生活', '青春与刺痛', '舞台与团队'],
      names: ['轻快冒险', '神秘探索', '异域奇幻', '暧昧缱绻', '别扭和好', '温情依偎', '怀旧追忆', '平静接纳', '欣喜若狂', '怪诞荒诞', '童话梦幻'],
      never: ['绝望深渊', '惨烈战场', '自毁激化', '惊悚恐怖', '激烈交火', '病态拉扯'],
    },
    沉重: {
      cats: ['心理与情绪', '青春与刺痛', '扭曲与执念', '悬疑与恐怖', '战斗与冲突', '舞台与团队'],
      names: ['伤感离别', '背德诱惑', '温情依偎', '别扭和好', '尴尬冷场', '职场紧绷', '魔幻暗黑', '赛博阴郁', '废土苍凉'],
      never: ['轻快喜剧', '慵懒闲适', '童话梦幻'],
    },
  };
  // 返回 { tone, allowed:[条目], jumpable:[条目] }
  function moodPlanNow() {
    const pool = moodPool();
    const tone = currentTone();
    const rule = MOOD_TONES[tone];
    if (!rule) return { tone, allowed: pool, jumpable: pool };
    const allowed = [];
    const jumpable = [];
    pool.forEach((x) => {
      if (rule.never.indexOf(x.name) !== -1) return;
      if (MOOD_CATS.indexOf(x.cat) === -1 || rule.cats.indexOf(x.cat) !== -1 || rule.names.indexOf(x.name) !== -1) allowed.push(x);
      else jumpable.push(x);
    });
    return { tone, allowed, jumpable };
  }

  // 场面表的结构：氛围的名字按氛围池锁死（池子空了就不要这一格）。
  // 候选报贴合程度（1～10），不报概率：概率由脚本按分数算（模型报的概率几乎总是同一套比例）。
  // jump 是越界骰的候选：一种平时不选、但这一场有由头的氛围
  function sceneSchema() {
    const plan = moodPlanNow();
    const names = plan.allowed.map((x) => x.name);
    const props = Object.assign({}, SCENE_SCHEMA.properties);
    const required = SCENE_SCHEMA.required.slice();
    if (names.length) {
      const jumps = (plan.tone ? plan.jumpable : plan.allowed).map((x) => x.name);
      props.mood = {
        type: 'object',
        properties: {
          candidates: {
            type: 'array',
            maxItems: 3,
            items: {
              type: 'object',
              properties: {
                name: { type: 'string', enum: names, description: '照抄氛围池里的名字' },
                fit: { type: 'integer', description: '和这一场贴合的程度，1 到 10' },
                why: S_STR('这一场里的具体依据，≤20字'),
              },
              required: ['name', 'fit', 'why'],
              additionalProperties: false,
            },
          },
          jump: {
            type: 'object',
            properties: {
              name: { type: 'string', enum: jumps.concat(['']), description: '越界的氛围；没有由头写空字符串' },
              hook: S_STR('越界的由头，材料里写着的事，≤20字；没有写空字符串'),
            },
            required: ['name', 'hook'],
            additionalProperties: false,
          },
        },
        required: ['candidates', 'jump'],
        additionalProperties: false,
        description: '这一场的氛围',
      };
      required.push('mood');
    }
    return Object.assign({}, SCENE_SCHEMA, { properties: props, required });
  }

