  // opt：{ stable（稳定人设）, ledger（场面那一路顺带记约定和事件） }
  function schemaFor(mode, max, names, opt) {
    const o = opt || {};
    const scene = () => (o.ledger ? withLedger(sceneSchema()) : sceneSchema());
    if (mode === 'group') {
      return {
        type: 'object',
        properties: {
          people: { type: 'array', minItems: names.length, maxItems: names.length, items: personSchema(names, o.stable) },
        },
        required: ['people'],
        additionalProperties: false,
      };
    }
    if (mode === 'cold') {
      return {
        type: 'object',
        properties: {
          scene: scene(),
          people: { type: 'array', minItems: 1, maxItems: max, items: personSchema(null, o.stable) },
        },
        required: ['scene', 'people'],
        additionalProperties: false,
      };
    }
    if (mode === 'scene') {
      return {
        type: 'object',
        properties: { scene: scene() },
        required: ['scene'],
        additionalProperties: false,
      };
    }
    return personSchema(null, o.stable);
  }

