  const GROUP_DYNAMIC_ONLY = [/^· 压力按人单独报/, /^· 任务里对某个人另有交代时/];
  function groupRules(stable) {
    const t = promptText('一次记全场的规则');
    return stable ? t.split('\n').filter((l) => !GROUP_DYNAMIC_ONLY.some((re) => re.test(l))).join('\n') : t;
  }

  // 提示词可以在面板「提示词」页改，改过的用改过的（见 13_prompts.js）。opt 同 schemaFor
  function systemFor(mode, max, opt) {
    const o = opt || {};
    const base = () => promptText(o.stable ? '记状态的规则（稳定人设）' : '记状态的规则（动态人设）');
    if (mode === 'cold') return coldPrompt(max, o.stable) + (o.ledger ? promptText('记事件和约定的规则') : '');
    if (mode === 'group') return base() + groupRules(o.stable);
    if (mode === 'scene') return promptText('场面的规则') + (o.ledger ? promptText('记事件和约定的规则') : '');
    return base();
  }

  // ---------- 用户消息 ----------
  // mat：一次运行共用的材料（见 05_run.js 的 gather）；target：这一次写谁（冷启动为 null）
  // lite：被接口的内容审查拦下后重试用的短材料（本人档案、世界设定各 1200 字，同场其他人各 400 字）
  // 四张专属表里和这一场的人有关、还没了结的行，每块最多 6 行（取最新的）
  function dbOwnLines(own, people) {
    const o = own || {};
    const who = (people || []).filter((n, i, a) => n && a.indexOf(n) === i);
    const hit = (v) => who.some((n) => String(v || '').indexOf(n) !== -1);
    const out = [];
    const block = (title, rows, test, fmt) => {
      const got = (rows || []).filter(test).slice(-6).map(fmt);
      if (got.length) { out.push(title); got.forEach((l) => out.push(l)); }
    };
    block('谁知道什么：', o.knowledge, (r) => r['是否公开'] !== '是' && (hit(r['知情人']) || hit(r['不知情人'])),
      (r) => '· ' + clip(r['事项'], 60) + '（知道：' + (r['知情人'] || '无') + '；不知道：' + (r['不知情人'] || '无') + '）');
    block('还没兑现的约定：', o.promises, (r) => (!r['状态'] || r['状态'] === '未到期') && (hit(r['发起人']) || hit(r['对象'])),
      (r) => '· ' + (r['发起人'] || '?') + ' 答应 ' + (r['对象'] || '?') + '：' + clip(r['约定内容'], 60) + (r['约定时间'] ? '（' + r['约定时间'] + '）' : ''));
    block('还没了结的大事（好事坏事）：', o.events, (r) => r['是否已解决'] !== '是' && hit(r['当事人']),
      (r) => '· ' + r['当事人'] + '：' + clip(r['事件'], 70) + (r['发生时间'] ? '（' + r['发生时间'] + '）' : ''));
    block('配角之间：', o.npc, (r) => hit(r['人物A']) && hit(r['人物B']),
      (r) => '· ' + r['人物A'] + ' 和 ' + r['人物B'] + '：' + clip(r['当前状态'] || r['交往经过'], 60));
    return out;
  }

  // 世界运行报告（咩咩预设的 <wlog>）里她所在的那件平行线事件，见 03_sources.js 的 wlogEvents
  function wlogBlock(ev) {
    return ['事件：' + (ev.name || '没写事件名'), '一起的人：' + ev.people.join('、'),
      ev.now ? '当前状态：' + ev.now : '', ev.next ? '下回合推演：' + ev.next : '', ev.eta ? '下回合ETA：' + ev.eta : '']
      .filter(Boolean).join('\n');
  }

  // 一个人的「上一轮的状态」「现在」两块，和任务里要单独交代她的那一句（另一个人格、崩溃、紧张）。
  // 稳定人设：只有上一轮的状态（不带另一个人格），没有「现在」（压力、关系阶段不记）和单独交代
  function personState(mat, target) {
    const out = { prev: '', now: [], note: '' };
    const p = mat.prev && mat.prev.people ? mat.prev.people[target] : null;
    if (p) {
      const said = p.unsaid ? '「' + p.unsaid.line + '」' : '（没有记）';
      out.prev = (p.persona && !mat.stable ? '现在是：' + p.persona + '（替她出来的另一个人格）\n' : '') +
        '行动：' + (p.doing || '') + '\n目标：' + (p.want || '') +
        '\n隐言：' + said + '\n顾虑：' + (p.afraid || '') + '\n动向：' + (p.will || '');
    }
    if (mat.stable) return out;
    const ch = mat.chars ? mat.chars[target] : null;
    const tp = mat.roster ? mat.roster.people.get(target) : null;
    const swapped = mat.c.允许崩溃 && p && p.persona ? p.persona : '';   // 上一轮已经是另一个人格在代替她
    const backNow = !mat.c.允许崩溃 && p && p.persona ? p.persona : '';  // 刚关掉「允许崩溃」：这一轮让她本人回来
    const except = ((ch && ch.level === '崩溃') || swapped) && tp ? exceptionLines(tp.profile) : [];
    out.now.push('压力：' + (ch ? ch.level : '平稳'));
    if (ch && ch.recent && ch.recent.length) out.now.push('最近落到她身上的事：' + ch.recent.map((r) => r.event).join('；'));
    const rel = relSummary(ch, 8, true);
    if (rel) out.now.push('关系：' + rel);
    // 崩溃时把档案里写的例外单独拎出来：夹在长档案中间，填表员常常看不到
    if (except.length) out.now.push('档案里写的例外：\n' + except.join('\n'));
    if (backNow) {
      out.note = '上一轮是「' + backNow + '」在代替她；现在不再让另一个人格出来。这一轮她本人回来：persona 写空字符串，行动、目标、隐言、顾虑、动向都按她本人填。';
    } else if (swapped) {
      out.note = '上一轮已经是「' + swapped + '」在代替她。按【压力】里的说明，接着按' + swapped + '填，persona 照填。' +
        '只有两种情况让她本人回来，这时 persona 写空字符串：档案里写的让她本人回来的那件事这一轮真的发生了；现在的压力已经回到平稳。';
    } else if (ch && ch.level === '崩溃' && except.length) {
      out.note = '她现在崩溃了。档案里写了她到极限时的例外，照它填。档案写了会换成另一个人格的：动向第一句写那个人格出来了，' +
        '再写出来以后的第一个动作和说话方式；行动、目标、隐言、顾虑也按出来的那个人格填。这是档案里写好的，不算你安排剧情。';
    } else if (ch && ch.level === '崩溃') {
      out.note = '她现在崩溃了。按档案里写的例外和性格模板的【破防】填。动向写她崩溃时真正会做的事，不写成她继续忍着。';
    } else if (ch && ch.level === '紧张') {
      out.note = '她现在紧张，接近极限。动向里可以写出失误和快要失控的迹象。';
    }
    return out;
  }


  // 【今天】：数据库「现在」里有日期就连星期几一起给；不知道星期几时明说，免得把档案里每周几的安排当成今天的事
  // prevScene：上一份状态的场面。数据库算不出星期几时，接着用场面那一路上一场记下的（它会按正文里过去的天数往后推）
  function todayText(db, prevScene) {
    const t = todayOf(db && db.global);
    if (t.known) return t.text;
    const now = t.text ? '现在：' + t.text + '。' : '';
    const last = prevScene && prevScene.weekday ? String(prevScene.weekday) : '';
    if (last) return now + '上一场记的是' + last + '。最近的正文里过了夜、换了一天的，往后推；没换天就还是' + last + '。';
    return now + '材料里没有写今天星期几。最近的正文写明了就按正文；没写就当不知道，档案里按星期排的事不算这一场要赶的事。';
  }

  // 场面那一路专用：氛围池（名字、类别、用在）和最近几场挑中的氛围。写法不给它，挑中以后交给正文
  function moodBlocks(mat) {
    const plan = moodPlanNow();
    if (!plan.allowed.length) return [];
    const line = (x) => x.name + '｜' + x.cat + '｜' + x.use;
    const out = [];
    out.push('【基调】\n' + (plan.tone ? '这个故事的基调是' + plan.tone + '。候选只从【氛围池】里挑，越界只从【越界可选】里挑。' : '没有设定基调。按世界设定和最近几段正文判断。越界从【氛围池】里另挑一种。'));
    out.push('【氛围池】\n' + plan.allowed.map(line).join('\n'));
    if (plan.tone && plan.jumpable.length) out.push('【越界可选】\n' + plan.jumpable.map(line).join('\n'));
    const last = (mat.history || []).map((st) => st && st.scene && st.scene.mood && st.scene.mood.name).filter(Boolean).slice(0, 3).reverse();
    out.push('【最近几场的氛围】\n' + (last.length ? '从早到晚：' + last.join(' → ') : '还没有。'));
    return out;
  }

  // chunk：一次记全场拆成几次时，这一次要写的那几个人（不给就是整场）
  // 玩家在设置里给这个人写的补充：只对她，和档案、性格模板冲突时照它
  function noteBlock(name, text) {
    return '【补充：' + name + '】（玩家写的，只对她。和档案、性格模板说的不一样时，照这一段）\n' + text;
  }

  // 玩家在设置里写的时期：她现在处在剧情的哪个时期
  function periodBlock(name, text) {
    return '【时期：' + name + '】（玩家写的）\n她现在处在这个时期：' + text + '。档案和设定里分时期写的内容，只用这个时期的。还没到这个时期的事，她不知道，也还没发生。';
  }

  // 有几个时期条目的人：玩家选了时期的照选的写；没选的列出几个时期，让状态模型照正文判断她现在在哪个时期（填 period）。
  // 没有时期条目的人：玩家手填了时期就给 periodBlock
  function periodPart(mat, name, lite) {
    const p = mat.roster && mat.roster.people.get(name);
    const typed = (mat.periods || {})[name];
    if (!p || !p.periods) return typed ? periodBlock(name, typed) : '';
    const now = periodNow(mat, name);
    if (now.manual) return periodBlock(name, now.label) + '\nperiod 照抄：' + now.label + '。';
    const others = p.periods.filter((v) => v.label !== now.label).map((v) => '· ' + v.label + '：' + clip(v.content, lite ? 80 : 200)).join('\n');
    return '【时期：' + name + '】\n她在设定里分这几个时期：' + p.periods.map((v) => v.label).join('、') + '。' +
      (now.label ? '上一轮记的是：' + now.label + '，上面的档案是这个时期的。' : '还没记过她在哪个时期，上面的档案是最长的那一条。') +
      '\n照最近的正文和数据库记忆判断她现在处在哪个时期，把时期名照抄进 period。正文写明剧情到了另一个时期，才换。没有依据时照上一轮的。' +
      (others ? '\n别的时期的档案开头：\n' + others : '');
  }

  // 平行线安排挑中的人（见 08_run.js 的 planArranged）：她这一场不在，给她记的是别处的此刻
  function arrangeBlock(name) {
    return '【平行线安排：' + name + '】\n她这一场不在玩家身边，在别处过自己的日子。照档案、【今天】和最近的正文推她此刻在哪、在做什么，行动里写清她在哪。' +
      'in_scene 填 false，parallel 填 true。她不知道玩家这一场的事。';
  }

  function buildUserContent(mat, target, mode, max, lite, chunk) {
    const parts = [];
    const persona = mat.persona;
    const group = mode === 'group';
    parts.push('【玩家】\n玩家扮演的人叫「' + persona.name + '」。' +
      (persona.desc ? '\n玩家给这个人写的设定：\n' + clip(persona.desc, 800) : ''));

    // 冷启动 = 名册里一个人都没在这一场认出来。这时候再把名册给它，它会拿名册里的人去凑数。
    const names = mode === 'cold' ? [] : Array.from(mat.roster.people.keys());
    if (names.length) {
      parts.push('【名册】\n' + names.map((n) => {
        const al = mat.roster.people.get(n).aliases.slice(0, 6);
        return n + (al.length ? '（也叫：' + al.join('、') + '）' : '');
      }).join('\n'));
    }

    if (mat.roster.world) parts.push('【世界与卡片设定】\n' + clip(mat.roster.world, lite ? 1200 : 2500));

    const shown = [];
    if (group) {
      // 一次记全场：名单上每个人的档案和性格模板，和每人一次时给她的那份一样长。
      // 真模型对比过：档案截短、模板只留本质时，压力报得千篇一律，该先崩的人晚崩好几轮。
      // 拆成几次时，这一次不写的同场的人给摘要，和每人一次时一样
      const who = chunk || mat.cast || [];
      who.forEach((n) => {
        if (!mat.roster.people.has(n)) return;
        parts.push('【档案：' + n + '】\n' + clip(profileFor(mat.roster.people.get(n), periodNow(mat, n).label), lite ? 800 : 3200));
        const pb = periodPart(mat, n, lite);
        if (pb) parts.push(pb);
        if (mat.notes && mat.notes[n]) parts.push(noteBlock(n, mat.notes[n]));
        if (mat.arranged && mat.arranged === n) parts.push(arrangeBlock(n));
        ((mat.templates && mat.templates[n]) || []).forEach((t) => {
          parts.push('【性格模板：' + n + '·' + t.kind + '】\n' + templateForSide(t, lite));
        });
        shown.push(n);
      });
      (mat.cast || []).forEach((n) => {
        if (shown.indexOf(n) !== -1 || !mat.roster.people.has(n)) return;
        parts.push('【档案：' + n + '】（摘要）\n' + clip(mat.roster.people.get(n).profile, lite ? 400 : 700));
        shown.push(n);
      });
    } else {
      // 档案：这一次要写的人给全文，同场的其他人给摘要，让她知道对面是谁。
      // 摘要总量封顶：五个人以内每人 700 字，人再多就每人分得少一点，最少 400 字。
      const others = (mat.cast || []).filter((n) => n !== target && mat.roster.people.has(n));
      const brief = lite ? 400 : Math.max(400, Math.min(700, Math.floor(2800 / Math.max(1, others.length))));
      if (target && mat.roster.people.has(target)) {
        parts.push('【档案：' + target + '】\n' + clip(profileFor(mat.roster.people.get(target), periodNow(mat, target).label), lite ? 1200 : 3200));
        const pb = periodPart(mat, target, lite);
        if (pb) parts.push(pb);
        if (mat.notes && mat.notes[target]) parts.push(noteBlock(target, mat.notes[target]));
        if (mat.arranged && mat.arranged === target) parts.push(arrangeBlock(target));
        shown.push(target);
      }
      // 性格模板只给这一次要写的人（同场其他人给了就太长）
      ((target && mat.templates && mat.templates[target]) || []).forEach((t) => {
        parts.push('【性格模板：' + t.kind + '】\n' + templateForSide(t, lite));
      });
      (mat.cast || []).forEach((n) => {
        if (shown.indexOf(n) !== -1 || !mat.roster.people.has(n)) return;
        parts.push('【档案：' + n + '】（摘要）\n' + clip(mat.roster.people.get(n).profile, brief));
        shown.push(n);
      });
    }

    const db = mat.db;
    if (db) {
      const lines = [];
      if (db.memo && db.memo.length) {
        lines.push('最近发生的事（从早到晚）：');
        db.memo.forEach((r, i) => {
          const brief = r['概览'] || r['概要'] || '';
          const full = r['纪要'] || '';
          const last = i === db.memo.length - 1;
          lines.push('· ' + [r['时间跨度'], r['地点']].filter(Boolean).join(' ') + ' —— ' +
            (last && full ? clip(full, 700) : (brief || clip(full, 120))));
        });
      }
      if (!lite && db.recalled && db.recalled.length) {
        lines.push('更早的、和这一场有关的事（数据库的剧情推进找回来的，从早到晚）：');
        db.recalled.forEach((r) => {
          const full = r['纪要'] || '';
          lines.push('· ' + [r['时间跨度'], r['地点']].filter(Boolean).join(' ') + ' —— ' +
            (full ? clip(full, 200) : (r['概览'] || r['概要'] || '')));
        });
      }
      const rel = shown.concat(mat.cast || []).filter((n, i, a) => a.indexOf(n) === i)
        .map((n) => db.people[n]).filter(Boolean);
      if (rel.length) {
        lines.push('人物现况：');
        rel.forEach((r) => {
          const parts2 = Object.keys(r).filter((k) => r[k]).map((k) => k + '：' + clip(r[k], 160));
          lines.push('· ' + parts2.join('；'));
        });
      }
      dbOwnLines(db.own, shown.concat(mat.cast || [])).forEach((l) => lines.push(l));
      if (lines.length) parts.push('【数据库记忆】\n' + lines.join('\n'));
    }
    // 稳定人设、手账本自己记约定和事件时：场面那一路（和冷启动）拿到全部没了结的，带编号，好按编号改状态；
    // 记人的几路只拿和这一场的人有关的
    if (mat.stable && mat.ledgerSelf) {
      const lg = mat.prevLedger || {};
      const open = ledgerOpen(lg);
      if (mode === 'scene' || mode === 'cold') {
        parts.push('【没了结的约定】\n' + (open.promises.length ? open.promises.map((x) => x.id + '｜' + ledgerPromiseText(x)).join('\n') : '没有。'));
        parts.push('【没了结的事】\n' + (open.events.length ? open.events.map((x) => x.id + '｜' + ledgerEventText(x)).join('\n') : '没有。'));
      } else {
        const who = shown.concat(mat.cast || []);
        const ps = open.promises.filter((x) => who.indexOf(x.from) !== -1 || who.indexOf(x.to) !== -1).slice(-6);
        const es = open.events.filter((x) => who.indexOf(x.who) !== -1).slice(-6);
        if (ps.length || es.length) {
          parts.push('【约定和事件】\n' + (ps.length ? '还没兑现的约定：\n' + ps.map((x) => '· ' + ledgerPromiseText(x)).join('\n') : '') +
            (ps.length && es.length ? '\n' : '') + (es.length ? '还没过去的事：\n' + es.map((x) => '· ' + ledgerEventText(x)).join('\n') : ''));
        }
      }
    }
    parts.push('【今天】\n' + todayText(db, mat.prev && mat.prev.scene));

    if (mat.story.items.length) {
      parts.push('【最近的正文】\n' + parallelNote(mat.story.items.map((x) => x.text).join('\n')) + mat.story.items.map((x) =>
        (x.who === '正文' ? '〔正文〕\n' : '〔' + x.who + '〕\n') + x.text).join('\n\n'));
    } else {
      parts.push('【最近的正文】\n还没有正文，故事从这一轮开始。');
    }

    parts.push('【玩家这一轮】\n' + (mat.input || (mat.tail ? '玩家还没开口。填最近的正文停下那一刻每个人的状态。' : '玩家这一轮没有输入文字。')));
    if (mode === 'scene' || mode === 'cold') moodBlocks(mat).forEach((b) => parts.push(b));
    if (mode === 'scene' && mat.encounter) parts.push('【这一场的偶遇】\n这一场安排一次偶遇。下面是这个地点的资料。\n〔' + mat.encounter.name + '〕\n' + mat.encounter.content);

    // 任务放最后，离输出最近
    let task;
    if (group) {
      const cast = (chunk || mat.cast || []).filter((n) => mat.roster.people.has(n));
      const others = (mat.cast || []).filter((n) => cast.indexOf(n) === -1 && mat.roster.people.has(n));
      const notes = [];
      cast.forEach((n) => {
        const ps = personState(mat, n);
        if (ps.prev) parts.push('【上一轮的状态：' + n + '】\n' + ps.prev);
        if (ps.now.length) parts.push('【现在：' + n + '】\n' + ps.now.join('\n'));
        const ev = mat.wlogOf && mat.wlogOf.get(n);
        if (ev) parts.push('【平行线事件：' + n + '】\n' + wlogBlock(ev));
        if (ps.note) notes.push('· ' + n + '：' + ps.note);
      });
      task = '【这一次的任务】\n一次记全场：给这几个人各填一张状态表，按这个顺序放进 people，name 照抄：' + cast.join('、') +
