        (notes.length ? '\n另外交代：\n' + notes.join('\n') : '');
    } else if (mode === 'cold') {
      task = '【这一次的任务】\n冷启动。从玩家这一轮和最近的正文里找出这一场的角色，最多 ' + max +
        ' 个，每人填一张状态表。再填这一场的场面。';
    } else if (mode === 'scene') {
      const cast = mat.cast || [];
      task = '【这一次的任务】\n只填这一场的场面，也就是 scene。' +
        (cast.length ? '\n脚本从正文里认出来、可能在场的人：' + cast.join('、') +
          '。这份名单只作参考。读完正文，自己判断谁此刻真的在场。名单里没有、但正文里在场的人，也写上。' : '');
    } else {
      const ps = personState(mat, target);
      if (ps.prev) parts.push('【上一轮的状态：' + target + '】\n' + ps.prev);
      if (ps.now.length) parts.push('【她现在】\n' + ps.now.join('\n'));
      const ev = mat.wlogOf && mat.wlogOf.get(target);
      if (ev) parts.push('【平行线事件】\n' + wlogBlock(ev));
      const others = (mat.cast || []).filter((n) => n !== target);
      task = '【这一次的任务】\n这一次只记「' + target + '」一个人的状态。name 填「' + target + '」。' +
        (others.length ? '\n同一场里可能还有：' + others.join('、') + '。她们的状态表由别人填，你不给她们填表。她的目标、顾虑、动向、隐言照样可以冲着她们。' : '') +
        (ps.note ? '\n' + ps.note : '');
    }
    parts.push(task);
    return parts.join('\n\n');
  }

