  function identifySchema(names, tplNames) {
    return {
      type: 'object',
      properties: {
        people: {
          type: 'array',
          minItems: names.length,
          maxItems: names.length,
          items: {
            type: 'object',
            properties: {
              name: { type: 'string', enum: names.slice() },
              core_trait: { type: 'string' },
              core: { type: 'string', enum: [''].concat(tplNames) },
              extra: {
                type: 'array',
                maxItems: 2,
                items: {
                  type: 'object',
                  properties: { name: { type: 'string', enum: tplNames.slice() }, evidence: { type: 'string' } },
                  required: ['name', 'evidence'],
                  additionalProperties: false,
                },
              },
            },
            required: ['name', 'core_trait', 'core', 'extra'],
            additionalProperties: false,
          },
        },
      },
      required: ['people'],
      additionalProperties: false,
    };
  }

  // 回来的一个人 → 模板名列表：core 在前，extra 里抄不出原文的丢掉。也认旧写法 picks: [...]
  function identifyPicks(hit) {
    if (!hit || typeof hit !== 'object') return null;
    if (Array.isArray(hit.picks)) return hit.picks.map((s) => String(s || '').trim());
    if (typeof hit.core !== 'string' || !Array.isArray(hit.extra)) return null;
    const out = hit.core.trim() ? [hit.core.trim()] : [];
    hit.extra.forEach((x) => { if (x && String(x.evidence || '').trim().length >= 4) out.push(String(x.name || '').trim()); });
    return out;
  }

  // catalog：[{ name }]；batch：[{ name, profile }]；lite：被内容审查拦下重试时档案只给短的
  function buildIdentifyContent(catalog, batch, lite) {
    const parts = ['【模板目录】\n' + catalog.map((t) => t.name).join('、')];
    batch.forEach((p) => { parts.push('【档案：' + p.name + '】\n' + clip(p.profile, lite ? 400 : 1500)); });
    parts.push('这一次给这几个人挑：' + batch.map((p) => '「' + p.name + '」').join('、') + '。');
    return parts.join('\n\n');
  }

