  // 正文里有平行线（预设的「平行线」视角，玩家不在的镜头包在 <parallel_line> 里）时，材料开头交代一句它是什么
  function parallelNote(text) {
    return /<parallel_line>/i.test(String(text || '')) ? '<parallel_line> 包着的是平行线：玩家不在场的另一条线，别处同一时间发生的事。\n' : '';
  }

  // 材料按块放，每块有上限；放不下的条目不硬塞，记在 dropped 里（日志和面板说得出漏了哪几条）
  // 材料原样给，保留换行（数据库的表格要看得出行和列）；太长就在换行处截断。clip 会把换行压成空格，这里不能用
  function cutKeep(s, max) {
    const t = String(s || '').trim();
    if (t.length <= max) return t;
    const head = t.slice(0, max - 2);                       // 留两个字给末尾的「\n…」，截完不超过上限
    const nl = head.lastIndexOf('\n');
    return (nl >= max * 0.6 ? head.slice(0, nl) : head) + '\n…';
  }

  function buildDirectorContent(m, lite) {
    const parts = [];
    const sc = m.scene || {};
    const head = [];
    if (sc.place) head.push('地点：' + sc.place);
    const present = (sc.present || []).concat(m.cast || []).filter((n, i, a) => n && a.indexOf(n) === i);
    if (present.length) head.push('在场：' + present.join('、'));
    head.push('玩家扮演：' + (m.player || '玩家'));
    if (m.today) head.push('今天：' + m.today);
    parallelGroups({ scene: sc }, m.away || []).forEach((l) => {
      const who = l.present.concat(l.people).filter((n, i, a) => n && a.indexOf(n) === i);
      if (who.length) head.push('平行线：' + (l.place ? '地点：' + l.place + '；' : '') + '在场：' + who.join('、') + '（玩家不在场）');
    });
    parts.push('【这一场】\n' + head.join('\n'));
    if (m.recent) parts.push('【最近一段正文】\n' + parallelNote(m.recent) + clipStory(m.recent, lite ? 2000 : STORY_MAX));
    parts.push('【玩家这一轮】\n' + (m.input || '（玩家这一轮没有输入文字）'));
    const dropped = [];
    const pack = (title, list, per, total) => {
      if (!list || !list.length) return;
      const out = [];
      let used = 0;
      list.forEach((e) => {
        const t = cutKeep(e.text, per);
        if (used + t.length > total) { dropped.push(e.name); return; }
        used += t.length;
        out.push('〔' + e.name + '〕\n' + t);
      });
      if (out.length) parts.push(title + '\n' + out.join('\n\n'));
    };
    pack('【数据库记忆】', m.db, lite ? 1500 : 8000, lite ? 8000 : 40000);
    // 剧情推进不像条目那样能「留在原处」（玩家那条要还原成原话），截掉多少记下来，面板和日志说得出
    let plotCut = 0;
    if (m.plot) {
      const lim = lite ? 3000 : 8000;
      const t = cutKeep(m.plot, lim);
      if (m.plot.trim().length > lim) plotCut = m.plot.trim().length - t.replace(/\n…$/, '').length;
      parts.push('【剧情推进】\n' + t);
    }
    pack('【世界书设定】', m.settings, lite ? 1000 : 4000, lite ? 6000 : 24000);
    parts.push('【这一次的任务】\n把上面材料里这一场用得上的东西整理成稿子，按 now、events、people、open、setting、plan、lines、parallel 八块填。');
    return { text: parts.join('\n\n'), dropped, plotCut };
  }

  // ======================== 副模型调用 ========================
  // 走酒馆后端的自定义接口（chat_completion_source: 'custom'），不经过酒馆前端的生成流程：
  //   · 不发任何酒馆事件 —— 数据库不会把这次调用当成用户发送；
  //   · 浏览器直连豆包 / 火山方舟会被跨域拦下，经后端转一手就没这个问题；
  //   · 密钥放在自定义请求头里，覆盖后端存的那份，不动酒馆主连接的任何设置。
  const GENERATE_URL = '/api/backends/chat-completions/generate';

  function yamlQuote(s) {
    return '"' + String(s).replace(/\\/g, '\\\\').replace(/"/g, '\\"') + '"';
  }

  // 附加请求体：常见的错写是把两层写在一行里（thinking: type: disabled），这不是合法的 YAML，
  // 酒馆后端解析失败就整段不加、也不报错——思考关不掉，一次要等好几分钟。这种一行两层的写法拆成两行
  function bodyYaml(raw) {
    return String(raw || '').split('\n')
      .map((l) => l.replace(/^(\s*)([\w.-]+)\s*:\s+([\w.-]+)\s*:\s+(\S.*)$/, (m, sp, a, b, v) => sp + a + ':\n' + sp + '  ' + b + ': ' + v))
      .join('\n');
  }

  // 排除主体参数：酒馆后端的 custom_exclude_body 认 YAML（列表、对象或单个名字）。
  // 玩家的写法五花八门（「temperature, max_tokens」、一行一个、「- top_p」「-top_p」、[a, b]、{a: 1}），
  // 先拆成参数名，再统一交一份 YAML 列表。只认开头那段英文参数名，后面跟的中文备注丢掉
  function excludeKeys(raw) {
    let t = String(raw || '')
      .replace(/(^|\s)(#|\/\/).*$/gm, '')          // 注释（# 或 // 到行尾）整段不算
      .replace(/:[^,，\n}\]]*/g, '')                 // 「名字: 值」只要名字（{top_p: false} 里的 false 不是参数）
      .trim();
    if (!t) return [];
    if (/^[[{]/.test(t)) t = t.replace(/^[[{]|[\]}]$/g, '');
    const out = [];
    t.split(/[\s,，、;；]+/).forEach((piece) => {
      const s = piece.replace(/^[-*•·]+/, '').replace(/^["'“”‘’`]+/, '');
      const m = s.match(/^[A-Za-z_][\w.-]*/);
      if (m && out.indexOf(m[0]) === -1) out.push(m[0]);
    });
    return out;
  }

  function excludeYaml(raw) {
    return excludeKeys(raw).map((k) => '- ' + k).join('\n');
  }

  // 附加请求体最外层的参数名（thinking、reasoning_effort……）
  function includeKeys(raw) {
    const out = [];
    bodyYaml(raw).split('\n').forEach((l) => {
      const m = l.match(/^([A-Za-z_][\w.-]*)\s*:/);
      if (m && out.indexOf(m[1]) === -1) out.push(m[1]);
    });
    return out;
  }

  // 模型偶尔会在 JSON 外面包一层代码块，或者前后带几个字，剥掉再解析。
  function parseJsonLoose(text) {
    let s = String(text || '').trim();
    s = s.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
    try { return JSON.parse(s); } catch (e) { /* 再试一次 */ }
    const a = s.indexOf('{');
    const b = s.lastIndexOf('}');
    if (a !== -1 && b > a) {
      try { return JSON.parse(s.slice(a, b + 1)); } catch (e) { /* 结尾多了括号或者别的字：取第一个配平的对象 */ }
      const one = firstObject(s, a);
      if (one) return JSON.parse(one);
    }
    throw new Error('返回的不是 JSON：' + s.slice(0, 80));
  }

  // 从 from 那个「{」起，跳过字符串里的括号，数到配平的那个「}」为止。没结构约束时模型偶尔在结尾多写一个括号
  function firstObject(s, from) {
    let depth = 0;
    let inStr = false;
    for (let i = from; i < s.length; i += 1) {
      const ch = s[i];
      if (inStr) {
        if (ch === '\\') i += 1;
        else if (ch === '"') inStr = false;
        continue;
      }
      if (ch === '"') inStr = true;
      else if (ch === '{') depth += 1;
      else if (ch === '}') { depth -= 1; if (depth === 0) return s.slice(from, i + 1); }
    }
    return '';
  }

  // 接口给的模型列表（OpenAI 兼容的 /models）。同样经酒馆后端转一手：后端替我们去请求，不会被跨域拦。
  // 返回 { models: [...] } 或 { error }
  async function listSideModels(c) {
    const ctx = getCtx();
    const url = String((c && c.副API地址) || '').trim();
    if (!url) return { error: '先填接口地址' };
    if (!ctx || typeof ctx.getRequestHeaders !== 'function') return { error: '拿不到酒馆上下文' };
    const key = c && c._key != null ? c._key : getApiKey();     // 导演稿的连接自带密钥（见 directorConn）
    const body = {
      chat_completion_source: 'custom',
      custom_url: url,
      custom_include_headers: key ? 'Authorization: ' + yamlQuote('Bearer ' + key) : '',
    };
    try {
      await reqAcquire('normal');
    } catch (e) {
      return { error: String((e && e.message) || e) };
    }
    try {
      const r = await TOP.fetch(TOP.location.origin + '/api/backends/chat-completions/status', {
        method: 'POST',
        headers: ctx.getRequestHeaders(),
        body: JSON.stringify(body),
      });
      const j = await r.json().catch(() => null);
      const raw = j && Array.isArray(j.data) ? j.data : (j && j.data && Array.isArray(j.data.data) ? j.data.data : []);
      const ids = raw.map((m) => String((m && (m.id || m.name)) || '').trim()).filter(Boolean);
      if (!ids.length) return { error: r.ok ? '这个接口没给模型列表' : 'HTTP ' + r.status };
      return { models: ids.filter((x, i, a) => a.indexOf(x) === i).sort() };
    } catch (e) {
      return { error: String((e && e.message) || e) };
    } finally {
      reqRelease();
    }
  }

  // ---------- 请求队列 ----------
  // 发给状态模型、写稿模型的请求都排这一个队：同时在路上的不超过「同时最多发几个请求」（公益站并发一高就 429）。
  // 优先级：记状态和导演稿（正文在等它们）> 测试连接、模型列表 > 后台自动识别。同一级先来先走。
  // 接口回 429：整个队停下，到点再放行。服务端给了 Retry-After 就照它等。
  // 酒馆后端转回 429 时不带 Retry-After，只能估：上一次等了多少秒才放行（learned），下次就从这个数起等，再不行翻倍，最多 60 秒；
  // 十分钟没再被限流，这个数作废。被限流以后的 CALM_MS 里只放一个请求出去，免得一放行又一起撞上。
  const PRIO = { high: 2, normal: 1, low: 0 };
  const RATE_RETRY = 2;                          // 一个请求被 429 挡回来，最多再排几次队
  const CALM_MS = 60000;
  const LEARN_TTL_MS = 10 * 60000;
  const REQ = { active: 0, waiting: [], coolUntil: 0, backoff: 0, timer: null, seq: 0, learned: 0, lastLimitAt: 0, calmUntil: 0 };

  function reqMax() {
    let n = 2;
    try { n = cfg().同时最多发几个请求; } catch (e) { n = 2; }
    return Date.now() < REQ.calmUntil ? 1 : n;
  }

  // 还在限流冷却里就返回剩下的毫秒数，否则 0
  function reqCoolLeft() {
    return Math.max(0, REQ.coolUntil - Date.now());
  }

  function reqPump() {
    if (REQ.timer) { clearTimeout(REQ.timer); REQ.timer = null; }
    const left = reqCoolLeft();
    if (left > 0) {
      if (REQ.waiting.length) REQ.timer = setTimeout(reqPump, left + 20);
      return;
    }
    while (REQ.active < reqMax() && REQ.waiting.length) {
      let k = 0;
      REQ.waiting.forEach((w, i) => { const b = REQ.waiting[k]; if (w.prio > b.prio || (w.prio === b.prio && w.seq < b.seq)) k = i; });
      const w = REQ.waiting.splice(k, 1)[0];
      w.done();
      REQ.active += 1;
      w.resolve();
    }
  }

  // 排到了才返回；叫停（signal）或者超过 until 还没排到就抛错，不占位
  function reqAcquire(priority, signal, until) {
    return new Promise((resolve, reject) => {
      const w = { prio: PRIO[priority] != null ? PRIO[priority] : PRIO.normal, seq: REQ.seq += 1, resolve };
      let timer = null;
      const onAbort = () => { drop(); reject(new Error('停下了')); };
      const drop = () => {
        const i = REQ.waiting.indexOf(w);
        if (i !== -1) REQ.waiting.splice(i, 1);
        w.done();
      };
      w.done = () => {
        if (timer) clearTimeout(timer);
        if (signal) signal.removeEventListener('abort', onAbort);
      };
      if (signal) {
        if (signal.aborted) { reject(new Error('停下了')); return; }
        signal.addEventListener('abort', onAbort);
      }
      if (until) timer = setTimeout(() => { drop(); reject(new Error('排队等了太久（接口在限流）')); }, Math.max(0, until - Date.now()));
      REQ.waiting.push(w);
      reqPump();
    });
  }

  function reqRelease() {
    REQ.active = Math.max(0, REQ.active - 1);
    reqPump();
  }

  // 被限流：整队停 wait 秒。返回这次停多久（毫秒）
  function reqCoolDown(retryAfterSec) {
    const now = Date.now();
    if (REQ.learned && now - REQ.lastLimitAt > LEARN_TTL_MS) REQ.learned = 0;
    REQ.lastLimitAt = now;
    REQ.calmUntil = now + CALM_MS;
    const first = Math.max(5, REQ.learned || 5);
    REQ.backoff = retryAfterSec > 0 ? retryAfterSec : Math.min(60, REQ.backoff ? REQ.backoff * 2 : first);
    const ms = REQ.backoff * 1000;
    REQ.coolUntil = Math.max(REQ.coolUntil, now + ms);
    reqPump();
    BUS.emit('queue', { coolUntil: REQ.coolUntil });
    setTimeout(() => BUS.emit('queue', { coolUntil: REQ.coolUntil }), ms + 50);
    return ms;
  }

  // 回的是不是限流：状态码 429，或者报错原文里带 429 / Too Many Requests / rate limit（酒馆后端常把上游的状态码包在 200 里转回来）。
  // 酒馆后端转 429 时只留一句 Too Many Requests 和 quota_error：quota_error 为真是今天的额度用完了，排队重试没有用
  function rateLimitOf(status, why, headers, j) {
    const s = String(why || '');
    if (j && j.quota_error === true) return { quota: true, sec: 0 };
    if (status !== 429 && !/\b429\b|too many requests|rate[ _-]?limit|请求过于频繁|请求太频繁/i.test(s)) return null;
    let sec = 0;
    try { sec = Number(headers && headers.get && headers.get('retry-after')) || 0; } catch (e) { sec = 0; }
    if (!sec) {
      const m = s.match(/retry[ _-]?after\D{0,12}(\d+(?:\.\d+)?)/i) || s.match(/(\d+(?:\.\d+)?)\s*(?:s|秒)\s*(?:后|later)/i);
      if (m) sec = Number(m[1]) || 0;
    }
    return { sec: Math.min(300, Math.ceil(sec)) };
  }

  // 返回 { data, ms, usage }；失败抛错（调用方负责降级）。
  // opts.priority：'high'（记状态、导演稿）/ 'normal' / 'low'（后台识别）；opts.until：排队最晚等到这个时间点
  async function callSide(system, user, schema, schemaName, opts) {
    let lastLimit = null;
    let schemaRetried = false;
    for (let attempt = 0; attempt <= RATE_RETRY; attempt += 1) {
      await reqAcquire(opts.priority, opts.signal, opts.until);
      try {
        const r = await callSideOnce(system, user, schema, schemaName, opts, attempt < RATE_RETRY);
        // 等过才放行的：记下这次等了几秒，下次被限流从这里起等
        if (attempt > 0 && REQ.backoff) REQ.learned = REQ.backoff;
        REQ.backoff = 0;
        return r;
      } catch (e) {
        // 接口不收固定结构（json_schema）：结构改写进提示词马上重发一次（测试连接、试参数不重发，交给它们去试出来写进设置）
        if (e && e.schemaReject && !schemaRetried && !opts.probe) { schemaRetried = true; attempt -= 1; continue; }
        if (!e || !e.rateLimit) throw e;
        lastLimit = e;
      } finally {
        reqRelease();
      }
      reqCoolDown(lastLimit.rateLimit.sec);
    }
    throw lastLimit;
  }

  // 上游拒收时的报错：限流、额度用完、拒收三种。status 为 0 表示状态码没有意义
  // （酒馆后端会把上游的报错包在 200 里转回来，上游的原话也只剩一句状态，400 就是「Bad Request」）
  function upstreamError(status, why, headers, j, willRetry) {
    const limit = rateLimitOf(status || 200, why, headers, j);
    if (limit && limit.quota) return new Error('额度用完了（429）：接口说今天的额度已经用完，换个接口或者明天再来。服务端原话：' + String(why).slice(0, 120));
    if (limit) {
      const err = new Error(willRetry ? '限流（429），排队等一会儿再发' :
        '限流（429）：重试了 ' + RATE_RETRY + ' 次还是被挡。可能是并发或频率限制，也可能是今天的额度用完了。服务端原话：' + String(why).slice(0, 120));
      err.rateLimit = limit;
      return err;
    }
    const err = new Error((status ? 'HTTP ' + status + '：' : '') + String(why).slice(0, 160));
    err.rejected = true;               // 接口回了话、拒收了这次请求（不是超时、断网）
    return err;
  }

  // 中转包成回答的报错长什么样：开头是「[API 错误]」「[Error]」「错误：」这类标记，或者整条是 {"error": …}。
  // 手账本要的回答都是 JSON 对象，最外层没有 error 这一格，所以不会把正常回答认成报错
  const WRAPPED_HEAD = /^\s*(?:\[\s*(?:API\s*)?(?:错误|报错|Error)[^\]\n]{0,20}\]|(?:API\s*)?(?:错误|报错|Error)\s*[:：])/i;
  function wrappedError(content) {
    const t = String(content || '').trim();
    if (!t || t.length > 2000) return '';
    if (WRAPPED_HEAD.test(t)) return t.replace(/\s+/g, ' ');
    if (/^\{\s*"error"\s*:/.test(t)) {
      try {
        const j = JSON.parse(t);
        if (j && j.error) return String(typeof j.error === 'string' ? j.error : (j.error.message || JSON.stringify(j.error)));
      } catch (e) { /* 不是整段 JSON，当正常回答 */ }
    }
    return '';
  }

  let _authBlock = null;                    // { sig, why, at }：回过 401 / 403 的那一套接口、模型、密钥
  // 拒收了固定结构（json_schema，酒馆后端转成 response_format）的接口和模型：这次打开期间不再发结构，改写进提示词。
  // DeepSeek 只收 json_object，回「This response_format type is unavailable now」
  const SCHEMA_REJECT = /response_format|json_schema/i;
  const _noSchema = new Set();
  function authBlocked() { return _authBlock; }

  async function callSideOnce(system, user, schema, schemaName, opts, willRetry) {
    const c = opts.cfg;
    const ctx = getCtx();
    if (!ctx || typeof ctx.getRequestHeaders !== 'function') throw new Error('拿不到酒馆上下文');
    const url = String(c.副API地址 || '').trim();
    if (!url) throw new Error('没有填副 API 地址');
    if (!c.副模型) throw new Error('没有填副模型');

    const key = c._key != null ? c._key : getApiKey();
    if (sideUnset(c)) { const err = new Error(UNSET_MSG); err.unset = true; throw err; }
    // 这个接口、模型、密钥上一次回了 401 / 403：换了设置或者点「测试连接」之前不再发，免得每一轮都去撞一次
    const sig = url + '|' + String(c.副模型).trim() + '|' + hashStr(key || '');
    if (_authBlock && _authBlock.sig === sig && !opts.probe) { const err = new Error(_authBlock.why); err.blocked = true; throw err; }
    // 回答结构随请求发（json_schema，酒馆后端转成 response_format）；关了固定结构、或者 response_format 被排除时不发，
    // 这时把结构写进系统提示词，不然模型不知道每一格叫什么（提示词里说的「结构按给你的 JSON Schema」就落空了）
    const ep = url + '|' + String(c.副模型 || '').trim();
    const sendSchema = !!c.用JSON结构约束 && excludeKeys(c.排除主体参数).indexOf('response_format') === -1 && (opts.probe || !_noSchema.has(ep));
    const schemaNote = schema && !sendSchema ? '\n\n【JSON Schema】\n回答照这个结构写，只输出一个 JSON 对象：\n' + JSON.stringify(schema) : '';
    const body = {
      chat_completion_source: 'custom',
      custom_url: url,
      custom_include_headers: key ? 'Authorization: ' + yamlQuote('Bearer ' + key) : '',
      custom_include_body: bodyYaml(c.附加请求体),
      custom_exclude_body: excludeYaml(c.排除主体参数),
      model: String(c.副模型).trim(),
      messages: [
        { role: 'system', content: withPrefix(system) + schemaNote },
        { role: 'user', content: user },
      ],
      // 会思考的模型思考也算在字数里，几百字常常想不完就被截断、再加大重发一遍（多等一轮）。下限放到 OUT_FLOOR；
      // 不思考的模型用多少算多少，字数给大不多花钱
      max_tokens: Math.max(opts.maxTokens || 900, OUT_FLOOR),
      temperature: 1,
      stream: false,
    };
    if (sendSchema) body.json_schema = { name: schemaName, strict: true, value: schema };

    // 排队的时间不算进超时；给了 until（导演稿的 600 秒）就不能越过它
    const hard = opts.until ? Math.max(1000, Math.min(opts.hardTimeout || 30000, opts.until - Date.now())) : (opts.hardTimeout || 30000);
    const Ctrl = TOP.AbortController || AbortController;
    const ctrl = new Ctrl();
    const timer = setTimeout(() => ctrl.abort(), hard);
    let stopped = false;                   // 外面叫停的（导演稿：点了停止、换了聊天），不是超时
    if (opts.signal) {
      if (opts.signal.aborted) { stopped = true; ctrl.abort(); }
      else opts.signal.addEventListener('abort', () => { stopped = true; ctrl.abort(); });
    }
    const t0 = Date.now();
    // 调试记录（面板「提示词」页最下面）：这一次发了什么、回了什么
    let reply = '';
    const record = (ok, error) => {
      try {
        debugRecord({ label: opts.label || schemaName, model: body.model, ms: Date.now() - t0, ok, error, system: body.messages[0].content, user, reply });
      } catch (e) { /* 记不下来不影响调用 */ }
    };
    try {
      const r = await TOP.fetch(TOP.location.origin + GENERATE_URL, {
        method: 'POST',
        headers: ctx.getRequestHeaders(),
        body: JSON.stringify(body),
        signal: ctrl.signal,
      });
      const text = await r.text();
      reply = text;
      let j = null;
      try { j = JSON.parse(text); } catch (e) { /* 下面统一报错 */ }
      if (!r.ok || !j || j.error) {
        const why = j && j.error ? (j.error.message || JSON.stringify(j.error)) : text;
        const err = upstreamError(r.ok ? 0 : r.status, why, r.headers, j, willRetry);
        if (r.status === 401 || r.status === 403) _authBlock = { sig, why: err.message, at: Date.now() };
        if (sendSchema && SCHEMA_REJECT.test(err.message) && !opts.probe) { _noSchema.add(ep); err.schemaReject = true; }
        throw err;
      }
      const choice = j.choices && j.choices[0];
      // 接口的内容审查按整段材料打分，档案越长越容易踩线；拦下时回一句道歉或者空内容。
      // 单独标出来，调用方会换短档案重试一次。
      if (choice && choice.finish_reason === 'content_filter') {
        const err = new Error('被接口的内容审查拦下了');
        err.filtered = true;
        throw err;
      }
      const msg = choice && choice.message;
      const content = msg && typeof msg.content === 'string' ? msg.content : '';
      reply = content || reply;
      // 回答写到一半、最多输出字数用完了：会思考的模型（Gemini 3 这类）思考也算在字数里，给记状态的几百字不够它想完。
      // 单独标出来，调用方加大字数重发一次
      const cut = choice && choice.finish_reason === 'length';
      const truncated = () => {
        const err = new Error('回答写到一半被截断了：最多输出字数用完了（会思考的模型，思考也算在字数里）');
        err.truncated = true;
        return err;
      };
      if (!content.trim()) throw cut ? truncated() : new Error('副模型返回了空内容');
      // 有的中转把上游的报错当成一条回答转回来（HTTP 200，内容是「[API 错误] …」或者一段 {"error": …}）：照报错处理，
      // 不然测试连接会当成连上了，记状态时只报「不是 JSON」
      const wrapped = wrappedError(content);
      if (wrapped) {
        const err = upstreamError(0, wrapped, null, null, willRetry);
        if (sendSchema && SCHEMA_REJECT.test(err.message) && !opts.probe) { _noSchema.add(ep); err.schemaReject = true; }
        throw err;
      }
      if (!c._ownEndpoint) clearIdentifyBlock();   // 状态模型连得上了：之前因为连不上停下的自动识别可以接着做
      if (_authBlock && _authBlock.sig === sig) _authBlock = null;
      let data = content;                          // raw：只看接口收不收，不管回的是什么
      if (!opts.raw) {
        try { data = parseJsonLoose(content); } catch (e) { throw cut ? truncated() : e; }
      }
      record(true, '');
      return { data, ms: Date.now() - t0, usage: j.usage || null, cut };
    } catch (e) {
      const err = e && e.name === 'AbortError'
        ? new Error(stopped ? '停下了' : '副模型超过 ' + Math.round(hard / 1000) + ' 秒没回') : e;
      record(false, (err && err.message) || String(err));
      throw err;
    } finally {
      clearTimeout(timer);
    }
  }

  // ---------- 接口拒收时：试出是哪个参数 ----------
  // 酒馆后端只把上游报错的状态转回来（400 就只剩「Bad Request」），接口的原话打在酒馆的后台窗口里，手账本看不到。
  // 所以自己试：手账本加的参数先全去掉发一次；通了，再一次只加回一个，加回哪个被拒就是哪个
  const PARAM_REJECT = /Bad Request|HTTP 4(00|22)|Unprocessable|unsupported|unrecognized|response_format|json_schema|unknown (field|param|name|argument)|invalid.{0,20}(param|argument|field|value|schema|request)|extra (inputs|fields)|not (supported|permitted|allowed)/i;
  const NOT_PARAM = /401|403|404|429|Unauthorized|Forbidden|Not Found|Too Many/i;

  function isParamReject(e) {
    const t = String((e && e.message) || '');
    return !!(e && e.rejected) && PARAM_REJECT.test(t) && !NOT_PARAM.test(t);
  }

  // shape：{ system, user, schema, schemaName, maxTokens, hardTimeout, label }，照被拒的那次请求的样子发。
  // 返回 { culprits: [参数名] }（把它们加进排除主体参数就能通）/ { notParams: true }（全去掉也被拒）/ { error }
  async function probeParams(conn, shape) {
    const base = excludeKeys(conn.排除主体参数);
    const cands = [];
    const add = (k) => { if (k && base.indexOf(k) === -1 && cands.indexOf(k) === -1) cands.push(k); };
    if (conn.用JSON结构约束) add('response_format');
    includeKeys(conn.附加请求体).forEach(add);
    ['max_tokens', 'temperature', 'stream'].forEach(add);
    // true = 收下了；false = 又被拒；别的错（超时、断网、限流、密钥）直接抛出去，试不下去
    const send = async (ex) => {
      const c2 = Object.assign({}, conn, { 排除主体参数: base.concat(ex).join('\n') });
      try {
        await callSide(shape.system, shape.user, shape.schema, shape.schemaName,
          { cfg: c2, maxTokens: shape.maxTokens, hardTimeout: shape.hardTimeout, priority: 'normal', raw: true, probe: true, label: shape.label });
        return true;
      } catch (e) {
        if (isParamReject(e)) return false;
        if (e && !e.rejected && /空内容/.test(String(e.message))) return true;   // 收下了，只是没写出字
        if (e && e.truncated) return true;                                       // 收下了，思考把字数用完了
        throw e;
      }
    };
    try {
      if (!cands.length || !(await send(cands))) return { notParams: true };
      const culprits = [];
      for (const k of cands) {
        if (!(await send(cands.filter((x) => x !== k)))) culprits.push(k);
      }
      if (culprits.length && culprits.length < cands.length && await send(culprits)) return { culprits };
      return { culprits: cands.slice() };   // 一个个加回去都能通、合在一起才被拒：全去掉是试过能通的
    } catch (e) {
      return { error: e };
    }
  }

  // ======================== 闸门与骰子 ========================
  // 副模型交回来的东西，要过这几道才进提示词：
  //   字数闸      每格有上限，三人全满约 900 字。它不占世界书预算，所以上限必须自己守。
  //   空话识别    三条判据命中两条 → 这个人这一轮不更新，沿用上一轮的真实状态。
  //   说不出口    证据锚 / thin / 长度 / 性格解释 / 封口 / 老化，逐个候选过，活下来的按概率掷骰。

  const LIMIT = {
    doing: 40, want: 40, afraid: 40, will: 60, sketch: 40,
    place: 30, leave: 30, physics: 40, breath: 60,
    line: 20,          // 提示词要求 ≤15 字，超过 20 字的候选直接丢——长句几乎一定是总结
    whyNot: 30, evidence: 25,
  };
  const PRESSURE_LEVELS = ['没有', '一点', '明显', '很重'];
  const REL_DIRS = ['靠近', '推远', '没变'];
  const REL_LEVELS = ['一点', '明显', '很重'];
  const P_CAP = 0.6;           // 最高概率的上限。模型给高了，脚本往均匀分布拉回来
  const AGE_LIMIT = 3;         // 同一句连续进了 3 轮提示词，第 4 轮就不再给

  // 正确的废话：拒答被 JSON 结构洗过之后，常常是这些词。只在校验端用，模型看不见这张表。
  const BOILER = ['情绪复杂', '内心复杂', '有些复杂', '心情复杂', '情绪波动', '内心波动',
    '有些在意', '比较在意', '难以言喻', '五味杂陈', '百感交集', '不知所措',
    '内心挣扎', '心理活动丰富', '情感丰富', '难以名状', '思绪万千',
    '说不清道不明', '心情沉重', '感慨良多'];
  const EXCUSE = /性格|内向|不擅长|不善于|不善言辞|从小|一直都|天生|本性|习惯了/;
  const TYPE_LABEL = /傲娇|病娇|三无|元气|高冷|腹黑|天然呆|无口/;
  // 隐言里材料没有的专业内容：音名、调、和弦（乐队故事里最常编的一类）。材料里写着同样的字就不算编
  const SPECIALIST = /升[A-G]|降[A-G]|[A-G][#♯b♭](?![A-Za-z])|[A-G]\s*(?:大|小)?调|[A-G]m?7?\s*和弦|和弦\s*[A-G]/;

  // 空话识别：三条判据，命中两条判空话。和 性格引擎/验空话.py 的 detect 同一套。
  function detectBoiler(cur, prev) {
    const flags = [];
    if (prev) {
      const same = ['doing', 'want', 'afraid']
        .filter((k) => cur[k] && fuzzyHit(cur[k], prev[k] || '')).length;
      if (same >= 2) flags.push('跨轮雷同');
    }
    if (cur.thin === true) flags.push('thin');
    const blob = [cur.doing, cur.want, cur.afraid].map((x) => String(x || '')).join(' ') + ' ' +
      (cur.unsaid_candidates || []).map((c) => (c && c.line) || '').join(' ');
    const hits = BOILER.filter((w) => blob.indexOf(w) !== -1);
    if (hits.length) flags.push('废话模板:' + hits.slice(0, 3).join('/'));
    return { bad: flags.length >= 2, flags };
  }

  // 按概率掷骰。最高概率超过上限时，把分布往均匀分布拉，直到最高的正好等于上限。
  function rollCandidate(cands) {
    const n = cands.length;
    let ps = cands.map((c) => Math.max(0, Number(c.p) || 0));
    const sum = ps.reduce((a, b) => a + b, 0);
    ps = sum > 0 ? ps.map((p) => p / sum) : ps.map(() => 1 / n);
    const maxP = Math.max.apply(null, ps);
    if (n > 1 && maxP > P_CAP) {
      const lam = (maxP - P_CAP) / (maxP - 1 / n);
      ps = ps.map((p) => (1 - lam) * p + lam / n);
    }
    const r = randomUnit();
    let acc = 0;
    let idx = n - 1;
    for (let i = 0; i < n; i += 1) {
      acc += ps[i];
      if (r < acc) { idx = i; break; }
    }
    return { idx, ps: ps.map((p) => Math.round(p * 100) / 100), roll: Math.round(r * 1000) / 1000 };
  }

  // 这一句在最近几轮里已经连续进过几次提示词
  function ageOf(name, line, history) {
    let n = 0;
    for (const st of history) {
      const p = st && st.people && st.people[name];
      const u = p && p.unsaid;
      if (u && u.line && (fuzzyHit(line, u.line) || fuzzyHit(u.line, line))) n += 1;
      else break;
    }
    return n;
  }

  // 压力：只收档位和几个是非，数不让模型报
  function normPressure(raw) {
    if (!raw || typeof raw !== 'object') return null;
    return {
      level: PRESSURE_LEVELS.indexOf(raw.level) !== -1 ? raw.level : '没有',
      event: clip(raw.event, 30),
      uncontrollable: raw.uncontrollable === true,
      evaluated: raw.evaluated === true,
      supported: raw.supported === true,
      relief: raw.relief === true,
    };
  }

  // 关系：对象名按名册归一（「小祥」→ 丰川祥子；「玩家」「你」→ 玩家的名字），不许写她自己，最多三条。
  // 好感底色最多两个词，用顿号接起来
  function normRelations(raw, env) {
    const alias = env.alias || {};
    const out = [];
    (Array.isArray(raw) ? raw : []).forEach((x) => {
      let to = String((x && x.to) || '').trim();
      to = alias[to] || to;
      if (env.player && (/^(玩家|你|user|\{\{user\}\}|<user>)$/i.test(to) || sameName(to, env.player))) to = env.player;   // 玩家名换了汉字写法也认
      if (!to || to === env.name || out.some((y) => y.to === to)) return;
      const tone = String((x && x.tone) || '').split(/[、，,*＊·\/／|｜\s]+/).map((w) => w.trim()).filter(Boolean).slice(0, 2).join('、');
      out.push({
        to,
        contract: clip(x && x.contract, 20),
        stage: canonStage(x && x.stage) || '',
        dir: REL_DIRS.indexOf(x && x.dir) !== -1 ? x.dir : '没变',
        level: REL_LEVELS.indexOf(x && x.level) !== -1 ? x.level : '一点',
        why: clip(x && x.why, 30),
        tone: clip(tone, 10),
        tested: !!(x && x.tested === true),
        trust: clip(x && x.trust, 12),
      });
    });
    return out.slice(0, 3);
  }

  // 隐言的对象：她在玩家这一场里时，只能是这一场的人或玩家（env.near：这一场可能在场的人）。返回检查函数；不用查时返回 null。
  // 名字按名册别名归一；「玩家」「你」算玩家；写成称呼的（「千早同学」）两字以上互相包含也算
  function targetCheck(entry, env) {
    if (!entry.inScene || !Array.isArray(env.near)) return null;
    const alias = env.alias || {};
    const ok = env.near.concat(env.player ? [env.player] : []).map((n) => alias[n] || n).filter((n) => n && n !== env.name);
    // known：名册里的名字和别名。名册外的人（临时出场的店员这类）当对象放行，只拦名册里、却不在这一场的人
    const known = Array.isArray(env.known) ? new Set(env.known) : null;
    return (to) => {
      let t = String(to || '').trim();
      if (!t) return false;
      if (env.player && /^(玩家|你|user|\{\{user\}\}|<user>)$/i.test(t)) return true;
      if (known && !known.has(t) && !known.has(alias[t] || t)) return true;
      t = alias[t] || t;
      return ok.some((n) => n === t || (t.length >= 2 && n.length >= 2 && (t.indexOf(n) !== -1 || n.indexOf(t) !== -1)));
    };
  }

  // raw：副模型给的一个人；env：{ name, input, recent, history(新→旧的状态数组), alias, player, near(这一场可能在场的人，可缺) }
  // 返回 { entry } 或 { rejected: true, flags }
  function processPerson(raw, env) {
    const notes = [];
    const name = env.name;
    const prev = env.history[0] && env.history[0].people ? env.history[0].people[name] : null;

    const verdict = detectBoiler(raw, prev);
    if (verdict.bad) return { rejected: true, flags: verdict.flags };

    const entry = {
      name,
      inScene: raw.in_scene !== false,
      parallel: raw.in_scene === false && raw.parallel === true,     // 在平行线上：玩家不在场的另一条线，照样注入
      sketch: clip(raw.sketch, LIMIT.sketch),
      doing: clip(raw.doing, LIMIT.doing),
      want: clip(raw.want, LIMIT.want),
      afraid: clip(raw.afraid, LIMIT.afraid),
      will: clip(raw.will, LIMIT.will),
      // 档案里写的另一个人格出来代替她时，填表员填那个人格的名字；是她本人就空着
      persona: (() => {
        const s = clip(raw.persona, 12).replace(/[「」『』"“”]/g, '').trim();
        return s && s !== name && (env.alias || {})[s] !== name ? s : '';     // 写成她自己的名字或别名，就是她本人
      })(),
      thin: raw.thin === true,
      found: raw.found !== false,
      cands: [],
      unsaid: null,
      dice: null,
      pressure: normPressure(raw.pressure),
      relations: normRelations(raw.relations, env),
      checkRaw: normCheck(raw.check, env.player),
      periodRaw: clip(raw.period, 20),          // 落档前对着她的时期名换成 period（见 08_run.js 的 markPeriod）
      notes,
    };

    const blob = [entry.doing, entry.want, entry.afraid, entry.will].join(' ');
    const label = blob.match(TYPE_LABEL);
    if (label) notes.push('出现类型标签「' + label[0] + '」');
    if (name && name.length >= 2 && entry.want.indexOf(name) !== -1) notes.push('「想要」里出现了她自己的名字，视角可能反了');

    const cands = (Array.isArray(raw.unsaid_candidates) ? raw.unsaid_candidates : []).map((c) => ({
      line: String((c && c.line) || '').replace(/^[「『“"]+|[」』”"]+$/g, '').trim(),
      p: Number(c && c.p) || 0,
      to: String((c && c.to_whom) || '').trim(),
      whyNot: clip(c && c.why_not, LIMIT.whyNot),
      evidence: clip(c && c.evidence, LIMIT.evidence),
      out: '',
    }));
    entry.cands = cands;
    const heardBy = targetCheck(entry, env);

    if (!entry.found) {
      notes.push('隐言：正文里没有依据，这一轮不填');
    } else if (entry.thin) {
      notes.push('隐言：正文里关于她的内容太少，这一轮不填');
    } else {
      const heard = env.input + '\n' + env.recent;
      const alive = cands.filter((c) => {
        if (!c.line) { c.out = '空'; return false; }
        if (norm(c.line).length > LIMIT.line) { c.out = '太长'; return false; }
        if (!c.evidence) { c.out = '没有证据'; return false; }
        if (EXCUSE.test(c.whyNot)) { c.out = '性格解释'; return false; }
        if (fuzzyHit(c.line, heard)) { c.out = '已经说出口了'; return false; }
        if (ageOf(name, c.line, env.history) >= AGE_LIMIT) { c.out = '连续给了 ' + AGE_LIMIT + ' 轮'; return false; }
        if (heardBy && !heardBy(c.to)) { c.out = '对象不在这一场'; return false; }
        const sp = c.line.match(SPECIALIST);
        if (sp && heard.indexOf(sp[0]) === -1) { c.out = '编了材料里没有的专业内容'; return false; }
        return true;
      });
      if (!alive.length) {
        notes.push('隐言：三个候选都没过检查（' + cands.map((c) => c.out).join('、') + '）');
      } else {
        const d = rollCandidate(alive);
        const pick = alive[d.idx];
        entry.unsaid = { line: pick.line, to: pick.to };
        entry.dice = { roll: d.roll, ps: d.ps, pool: alive.map((c) => c.line) };
      }
    }
    return { entry };
  }

  // encounter：这一场安排了偶遇时（08_run 的 gather 掷的），收它写的偶遇；没安排时它写了也不收
  function processScene(raw, userName, encounter) {
    if (!raw || typeof raw !== 'object') return null;
    const names = (list, skip) => {
      const out = [];
      (Array.isArray(list) ? list : []).forEach((x) => {
        const n = String(x || '').trim();
        if (n && n !== userName && out.indexOf(n) === -1 && skip.indexOf(n) === -1) out.push(n);
      });
      return out.slice(0, 8);
    };
    const seen = names(raw.present, []);
    // 平行线：玩家不在场、别处同时在演的线，最多两条；这一场里已经有的人不再算进平行线
    const parallel = [];
    (Array.isArray(raw.parallel) ? raw.parallel : []).forEach((x) => {
      if (!x || typeof x !== 'object' || parallel.length >= 2) return;
      const line = { place: clip(x.place, LIMIT.place), present: names(x.present, seen) };
      if (line.place || line.present.length) parallel.push(line);
    });
    const sc = {
      place: clip(raw.place, LIMIT.place),
      present: seen,
      leave: clip(raw.leave, LIMIT.leave),
      physics: clip(raw.physics, LIMIT.physics),
      weekday: clip(raw.weekday, 10).replace(/^(不知道|未知|不详|无|空)$/, ''),
      breath: clip(raw.breath, LIMIT.breath),
      mood: rollMood(raw.mood),
      encounter: encounter ? clip(raw.encounter, 40) : '',
      encounterFrom: encounter && raw.encounter ? encounter.name : '',
      parallel,
    };
    return sc;
  }

  // 稳定人设、手账本自己记约定和事件时，场面那一路顺带交回来的（见 07_state.js 的 stepLedger）；没有就是 null。
  // 不放进场面里存，单独挂在这一轮上，落档时进 st.ledgerRaw
  function ledgerOf(raw) {
    return raw && typeof raw === 'object' && (Array.isArray(raw.promises) || Array.isArray(raw.events)) ? normLedgerRaw(raw) : null;
  }

  const PROMISE_STATUS = ['未到期', '已兑现', '已违约', '已取消'];
  // 场面那一路交回来的约定和事件：只收形状对的，每样最多 6 条，字数截好
  function normLedgerRaw(raw) {
    const promises = (Array.isArray(raw.promises) ? raw.promises : []).filter((p) => p && typeof p === 'object').slice(0, 6).map((p) => ({
      ref: String(p.ref || '').trim(),
      from: clip(p.from, 20), to: clip(p.to, 20), what: clip(p.what, 40), when: clip(p.when, 20),
      status: PROMISE_STATUS.indexOf(p.status) !== -1 ? p.status : '未到期',
    }));
    const events = (Array.isArray(raw.events) ? raw.events : []).filter((e) => e && typeof e === 'object').slice(0, 6).map((e) => ({
      ref: String(e.ref || '').trim(),
      who: clip(e.who, 20), kind: e.kind === '好事' ? '好事' : '坏事', what: clip(e.what, 50), settled: e.settled === true,
    }));
    return { promises, events };
  }

  // ---------- 判定骰（内容规划书第三章） ----------
  // 模型写判什么、难度、四个落点；它不知道会掷到哪一个。阈值、d100、程度、选落点、写法限制都在这里。
  //   阈值 T = 50 + 她的状态（压力档位；判「想要」时压力越大越难做成，判「隐言」时压力越大越容易说出口）
  //            + 场上的旁观者（她之外还有两个以上的人 −10）+ 难度（易 +10 / 中 0 / 难 −10），夹在 5～95
  //   掷 1～100：≤ T 算成，> T 算没成。程度 = 离 T 多远占这一侧的比例：< 0.3 贴线，< 0.7 干净，其余夸张；1～5、96～100 一律夸张。
  //   上一楼已经有过夸张的，这一次的夸张降成干净（连着两轮不破防）。
  //   贴线用 line 落点，夸张用 far 落点（没写就退回 line），干净按程度就近
  const CHECK_KINDS = ['想要', '隐言'];
  const CHECK_RES = { 想要: { 平稳: 10, 紧张: -5, 崩溃: -15 }, 隐言: { 平稳: -10, 紧张: 10, 崩溃: 20 } };
  const CHECK_HARD = { 易: 10, 中: 0, 难: -10 };
  const CHECK_HOW = {
    想要: { 贴线pass: '做得很勉强，写出勉强在哪。', 贴线fail: '只差一点，写出差的那一点，不写成完全没做到。',
      夸张pass: '结果溢出这一场：影响到别人，或者留到下一场，或者她自己也吓到。', 夸张fail: '结果溢出这一场：影响到别人，或者留到下一场，或者她自己也吓到。' },
    隐言: { 贴线pass: '话说出了一部分。写出停在哪里。', 贴线fail: '话到嘴边没说。写出差的那一下。',
      夸张pass: '这是这一局最重的一句话。写出说完以后她自己的反应。', 夸张fail: '说出的话和本意相反。写出说完以后她自己的反应。' },
  };

  // 落点里写到玩家（名字、换了汉字写法的名字、「玩家」「{{user}}」）：玩家的动作和反应只能由玩家自己定，
  // 这种落点掷中时不把原话交给正文，只交结果和写法（面板照样显示原话）
  const PLAYER_WORD = /玩家|\{\{user\}\}|<user>/i;
  function mentionsPlayer(text, player) {
    const t = String(text || '');
    if (!t) return false;
    if (PLAYER_WORD.test(t)) return true;
    const p = String(player || '').trim();
    return !!p && (t.indexOf(p) !== -1 || foldName(t).indexOf(foldName(p)) !== -1);
  }

  function normCheck(c, player) {
    if (!c || typeof c !== 'object') return null;
    const kind = CHECK_KINDS.indexOf(c.kind) !== -1 ? c.kind : '';
    const what = clip(c.what, 24);
    const anchors = { line_pass: clip(c.line_pass, 30), line_fail: clip(c.line_fail, 30), far_pass: clip(c.far_pass, 30), far_fail: clip(c.far_fail, 30) };
    if (!kind || !what || !anchors.line_pass || !anchors.line_fail) return null;
    const playerIn = Object.keys(anchors).filter((k) => anchors[k] && mentionsPlayer(anchors[k], player));
    return { kind, what, hardness: CHECK_HARD[c.hardness] != null ? c.hardness : '中', anchors, playerIn };
  }

  // info：{ level（她这一楼之前的压力档位）, onlookers（她之外场上几个人）, prevExtreme（上一楼有过夸张） }
  function rollCheck(raw, info) {
    const res = (CHECK_RES[raw.kind] || {})[info.level || '平稳'] || 0;
    const crowd = (info.onlookers || 0) >= 2 ? -10 : 0;
    const T = Math.max(5, Math.min(95, 50 + res + crowd + (CHECK_HARD[raw.hardness] || 0)));
    const roll = Math.floor(randomUnit() * 100) + 1;
    const pass = roll <= T;
    const degree = pass ? (T - roll) / T : (roll - T) / (100 - T);
    let band = roll <= 5 || roll >= 96 ? '夸张' : degree < 0.3 ? '贴线' : degree < 0.7 ? '干净' : '夸张';
    const softened = band === '夸张' && !!info.prevExtreme;
    if (softened) band = '干净';
    const side = pass ? 'pass' : 'fail';
    const nearKey = 'line_' + side;
    const farKey = raw.anchors['far_' + side] ? 'far_' + side : nearKey;
    const slot = band === '贴线' ? nearKey : band === '夸张' ? farKey : (degree < 0.5 ? nearKey : farKey);
    const anchor = raw.anchors[slot];
    const how = (CHECK_HOW[raw.kind] || {})[band + side] || '';
    const anchorPlayer = (raw.playerIn || []).indexOf(slot) !== -1;
    return { kind: raw.kind, what: raw.what, hardness: raw.hardness, T, roll, pass, band, softened,
      degree: Math.round(degree * 100) / 100, slot, anchor, how, anchors: raw.anchors, anchorPlayer };
  }

  // 交给正文的那一句：想要写「做到了 / 没做到」，隐言只写落点（落点本身就是说没说出口）。
  // 掷中的落点写到了玩家：原话不交（玩家的动作和反应由玩家定），只交结果和写法
  function checkLine(ck) {
    if (!ck || !ck.anchor) return '';
    const a = ck.anchorPlayer ? '' : String(ck.anchor).replace(/[。．.！!？?]+$/, '') + '。';
    return ck.what + '：' + (ck.kind === '想要' ? (ck.pass ? '做到了' : '没做到') + '。' : '') + a + (ck.how || '');
  }

  // 氛围（内容规划书 2.6）：
  //   · 候选：名字不在「可选」里的丢掉、重名的只留第一个。贴合程度 fit（1～10）按 exp(fit / MOOD_T) 算概率，最高压到 0.6，掷骰
  //   · 越界骰：每场掷一次，JUMP_PCT% 的时候改用 jump——名字在「可越界」里、不和候选重名、而且写了由头（没由头就不越界）
  //   · 旧格式（数组、带 p）照样认：p 当成 fit
  const MOOD_T = 2.5;
  const JUMP_PCT = 10;
  function rollMood(raw) {
    const plan = moodPlanNow();
    const allowed = plan.allowed.map((x) => x.name);
    const jumpable = (plan.tone ? plan.jumpable : plan.allowed).map((x) => x.name);
    const src = Array.isArray(raw) ? { candidates: raw } : (raw && typeof raw === 'object' ? raw : {});
    const cands = [];
    (Array.isArray(src.candidates) ? src.candidates : []).forEach((x) => {
      const name = String((x && x.name) || '').trim();
      if (!name || allowed.indexOf(name) === -1 || cands.some((c) => c.name === name) || cands.length >= 3) return;
      const f = x.fit != null ? Number(x.fit) : Number(x.p) * 10;
      cands.push({ name, fit: Math.max(1, Math.min(10, Math.round(Number.isFinite(f) ? f : 5))), why: clip(x.why, 20) });
    });
    const j = src.jump && typeof src.jump === 'object' ? src.jump : null;
    const jName = j ? String(j.name || '').trim() : '';
    const jHook = j ? clip(j.hook, 20) : '';
    const jumpOk = !!jName && !!jHook && jumpable.indexOf(jName) !== -1 && !cands.some((c) => c.name === jName);
    const jumpRoll = Math.floor(randomUnit() * 100) + 1;
    if (jumpOk && cands.length && jumpRoll <= JUMP_PCT) {
      return { name: jName, why: jHook, jump: true, hook: jHook, jumpRoll, pool: cands.map((c) => c.name), fits: cands.map((c) => c.fit) };
    }
    if (!cands.length) return null;
    const ws = cands.map((c) => Math.exp(c.fit / MOOD_T));
    const sum = ws.reduce((a, b) => a + b, 0);
    const d = rollCandidate(cands.map((c, i) => ({ p: ws[i] / sum })));
    return { name: cands[d.idx].name, why: cands[d.idx].why, roll: d.roll, ps: d.ps, pool: cands.map((c) => c.name), fits: cands.map((c) => c.fit), jumpRoll };
  }

  // ======================== 存储与注入 ========================
  // 每一份状态挂在「算它的那条玩家消息」的楼层上，用那条消息的发送时间认身份：
  //   · 删掉消息、回退楼层，状态跟着回退；
  //   · 重新生成、换 swipe，玩家那条没变，状态也不变。
  // 存在聊天变量 dyn_hb 里，只保留最近 20 份。

  const KEEP_FLOORS = 20;

  // 最近一次存进去的状态（只认这个聊天的）。聊天变量是一秒防抖存盘的：这一秒里聊天被重新载入（别的脚本、扩展重载聊天），
  // 或者别的脚本拿着旧的一份整份写回聊天变量，刚存的状态就没了，面板一直停在更早的那一楼。
  // 读的时候发现存档里少了、或者比这里旧，就从这里补回去再存一遍
  let _shadow = null;
  let _healing = false;

  function healStore(s) {
    const sh = _shadow;
    if (!sh || sh.chatId !== currentChatId()) return;
    const chat = chatNow();
    if (!chat.length) return;
    const back = [];
    Object.keys(sh.floors).forEach((k) => {
      const st = sh.floors[k];
      const cur = s.floors[k];
      if (!st || !stillValid(st, chat)) return;
      if (cur && stillValid(cur, chat) && (cur.at || 0) >= (st.at || 0)) return;
      s.floors[k] = JSON.parse(JSON.stringify(st));
      back.push(k);
    });
    Object.keys(sh.meta || {}).forEach((k) => { if (s.meta[k] === undefined) s.meta[k] = sh.meta[k]; });
    if (!back.length || _healing) return;
    _healing = true;
    warn('聊天变量里的状态少了第 ' + back.join('、') + ' 楼（聊天被重新载入过，或者别的脚本整份改写了聊天变量），已经从内存补回');
    setTimeout(() => {
      try { if (!DISPOSED && sh.chatId === currentChatId()) saveStore(loadStore()); } catch (e) { warn('补回的状态没存上：', e); }
      _healing = false;
    }, 0);
  }

  function forgetShadow() { _shadow = null; }

  function loadStore() {
    let v = {};
    try { v = getVariables({ type: 'chat' }) || {}; } catch (e) { v = {}; }
    const s = v[NS];
    if (s && typeof s === 'object' && s.floors && typeof s.floors === 'object') {
      if (!s.meta || typeof s.meta !== 'object') s.meta = {};
      // 形状不对的楼层（旧版本写的、在变量管理器里手改过的）就地修补或丢掉，别让它一路崩到启动
      Object.keys(s.floors).forEach((k) => {
        const f = s.floors[k];
        if (!f || typeof f !== 'object') { delete s.floors[k]; return; }
        if (typeof f.floor !== 'number') f.floor = Number(k);
        if (!f.people || typeof f.people !== 'object') f.people = {};
        if (!Array.isArray(f.order)) f.order = Object.keys(f.people);
        f.order = f.order.filter((n) => f.people[n] && typeof f.people[n] === 'object');
      });
      healStore(s);
      return s;
    }
    const empty = { v: 1, floors: {}, meta: {} };
    healStore(empty);
    return empty;
  }

  // 这个聊天里手账本记过状态没有。没记过（只是点开卡看看、刚清空过）时不在后台识别性格模板，也不建聊天世界书、不写条目
  function chatStarted() {
    return Object.keys(loadStore().floors).length > 0;
  }

  function currentChatId() {
    try {
      const ctx = getCtx();
      return ctx && typeof ctx.getCurrentChatId === 'function' ? ctx.getCurrentChatId() : null;
    } catch (e) {
      return null;
    }
  }

  function saveStore(store) {
    // 删消息、回退以后失效的楼层先清掉，别占着 KEEP_FLOORS 的名额（聊天记录还没载入时不清，免得清空）
    const chat = chatNow();
    if (chat.length) {
      Object.keys(store.floors).forEach((k) => { const st = store.floors[k]; if (!st || !stillValid(st, chat)) delete store.floors[k]; });
    }
    // 「记到最新」的只留最新一份；后面又记了玩家那一楼的正式的状态，它就用完了
    const all = Object.keys(store.floors).map(Number);
    const lastUser = Math.max(-1, ...all.filter((k) => !store.floors[k].tail));
    const lastTail = Math.max(-1, ...all.filter((k) => store.floors[k].tail));
    all.forEach((k) => { if (store.floors[k].tail && (k !== lastTail || k < lastUser)) delete store.floors[k]; });
    const keys = Object.keys(store.floors).map(Number).sort((a, b) => a - b);
    keys.slice(0, Math.max(0, keys.length - KEEP_FLOORS)).forEach((k) => { delete store.floors[k]; });
    try {
      updateVariablesWith((vars) => { vars[NS] = store; return vars; }, { type: 'chat' });
    } catch (e) {
      warn('状态写入失败：', e);
    }
    if (chat.length) _shadow = { chatId: currentChatId(), floors: JSON.parse(JSON.stringify(store.floors)), meta: JSON.parse(JSON.stringify(store.meta || {})) };
  }

  function chatNow() {
    const ctx = getCtx();
    return (ctx && Array.isArray(ctx.chat)) ? ctx.chat : [];
  }

  // 「记到最新」的那份（tail，见 17_boot.js 的 onRerun）挂在正文那一楼上：那条正文换了 swipe、续写过，send_date 就变了，这份跟着作废
  function stillValid(st, chat) {
    const m = chat[st.floor];
    if (!m || String(m.send_date || '') !== String(st.sd || '')) return false;
    return st.tail ? !m.is_user : !!m.is_user;
  }

  // uptoExclusive 之前、仍然有效的状态，新→旧。
  // withTail：算不算「记到最新」的那份。它只是临时的——记新的一轮、算压力关系都不拿它当底，只有注入和面板显示用
  function statesBefore(store, uptoExclusive, limit, withTail) {
    const chat = chatNow();
    const out = [];
    Object.keys(store.floors).map(Number).sort((a, b) => b - a).forEach((k) => {
      if (out.length >= (limit || 1)) return;
      if (uptoExclusive != null && k >= uptoExclusive) return;
      const st = store.floors[k];
      if (st && (withTail || !st.tail) && stillValid(st, chat)) out.push(st);
    });
    return out;
  }

  // 现在挂着的那份（算上「记到最新」的）。noTail：不算它
  function latestState(store, uptoExclusive, noTail) {
    return statesBefore(store, uptoExclusive, 1, !noTail)[0] || null;
  }

  // 正文生成要用的那份：重新生成、换一条 swipe 时，要重写的就是「记到最新」读过的那段正文，不能拿它的状态
  function stateForGeneration() {
    return latestState(loadStore(), null, GEN.armed && GEN.noTail);
  }

  // 这一句（最新的玩家那一楼）的键：聊天、楼层、它的 send_date。重新生成按这个数次数（见 17_boot.js 的 rerollTurn）
  function turnKey() {
    const uf = latestUserFloor();
    const m = uf >= 0 ? chatNow()[uf] : null;
    return m ? currentChatId() + ':' + uf + ':' + String(m.send_date || '') : '';
  }

  function latestUserFloor() {
    const chat = chatNow();
    for (let i = chat.length - 1; i >= 0; i -= 1) if (chat[i] && chat[i].is_user) return i;
    return -1;
  }

  // ---------- 稳定 / 动态（此聊天的「性格」） ----------
  // 存在这个聊天的存档里（meta.mode），没写就是动态。稳定：照角色卡和档案演，不用性格模板，压力、关系阶段冻住，
  // 「手账本-」条目不写不激活；约定和事件交给正文
  function chatMode(store) {
    const s = store || loadStore();
    return s.meta && s.meta.mode === '稳定' ? '稳定' : '动态';
  }
  function isStable(store) { return chatMode(store) === '稳定'; }
  function setChatMode(mode) {
    const store = loadStore();
    if (mode === '稳定') store.meta.mode = '稳定';
    else delete store.meta.mode;
    saveStore(store);
    reinject();
  }

  // ---------- 约定和事件（稳定人设） ----------
  // 有数据库的约定表、重大事件表就读表；没有就由场面那一路顺带记，存在每一楼的状态里（st.ledger），跟着删消息回退。
  // st.ledger = { seq, promises: [{ id, from, to, what, when, status, floor, upd }], events: [{ id, who, kind, what, settled, floor, upd }] }
  const LEDGER_KEEP = 6;     // 了结了的过几楼不再留
  const LEDGER_MAX = 20;     // 没了结的每样最多留几条
  const LEDGER_SHOW = 4;     // 交给正文、面板上每样最多几行

  // [谁, 什么]：交给正文的一行是两段用「：」接起来，面板上前一段加粗
  function ledgerPromiseParts(x) { return [x.from + ' 答应 ' + x.to, x.what + (x.when && x.when !== '未定' ? '（' + x.when + '）' : '')]; }
  function ledgerEventParts(x) { return [x.who, x.what + '（' + x.kind + (x.kind === '坏事' ? '，没了结' : '') + '）']; }
  function ledgerPromiseText(x) { return ledgerPromiseParts(x).join('：'); }
  function ledgerEventText(x) { return ledgerEventParts(x).join('：'); }
  function ledgerOpen(lg) {
    return {
      promises: (lg && Array.isArray(lg.promises) ? lg.promises : []).filter((x) => x && x.status === '未到期'),
      events: (lg && Array.isArray(lg.events) ? lg.events : []).filter((x) => x && !x.settled),
    };
  }

  // base：上一楼的 ledger；raw：这一楼场面那一路交回来的（normLedgerRaw）；alias：名册别名；player：玩家扮演的人。纯函数
  //   · 带编号的改那一条：约定改状态和时间，事件改成了结；编号对不上的当新的
  //   · 新的约定一来就了结了、新的事一来就过去了：不记；和没了结的那条意思一样（同一对人 / 同一个人）：不重复记
  //   · 玩家可以是约定的一方，事件不记玩家身上的
  function stepLedger(base, raw, floor, alias, player) {
    const out = { seq: (base && base.seq) || 0,
      promises: ((base && base.promises) || []).map((x) => Object.assign({}, x)),
      events: ((base && base.events) || []).map((x) => Object.assign({}, x)) };
    const al = alias || {};
    const nm = (v) => {
      const t = String(v || '').trim();
      if (!t) return '';
      if (player && (t === player || /^(玩家|你|user|\{\{user\}\}|<user>)$/i.test(t))) return player;
      return al[t] || t;
    };
    const same = (a, b) => a === b || fuzzyHit(a, b) || fuzzyHit(b, a);
    const r = raw || {};
    (r.promises || []).forEach((p) => {
      const hit = p.ref && out.promises.find((x) => x.id === p.ref);
      if (hit) {
        hit.status = p.status;
        if (p.when) hit.when = p.when;
        hit.upd = floor;
        return;
      }
      const from = nm(p.from);
      const to = nm(p.to);
      if (!from || !to || from === to || !p.what || p.status !== '未到期') return;
      if (out.promises.some((x) => x.status === '未到期' && x.from === from && x.to === to && same(x.what, p.what))) return;
      out.seq += 1;
      out.promises.push({ id: 'P' + out.seq, from, to, what: p.what, when: p.when || '未定', status: '未到期', floor, upd: floor });
    });
    (r.events || []).forEach((e) => {
      const hit = e.ref && out.events.find((x) => x.id === e.ref);
      if (hit) {
        if (e.settled && !hit.settled) { hit.settled = true; hit.upd = floor; }
        return;
      }
      const who = nm(e.who);
      if (!who || who === player || !e.what || e.settled) return;
      if (out.events.some((x) => !x.settled && x.who === who && same(x.what, e.what))) return;
      out.seq += 1;
      out.events.push({ id: 'E' + out.seq, who, kind: e.kind === '好事' ? '好事' : '坏事', what: e.what, settled: false, floor, upd: floor });
    });
    // 了结了的过 LEDGER_KEEP 楼不再留；没了结的各留最新的 LEDGER_MAX 条
    const prune = (list, done) => {
      const open = list.filter((x) => !done(x)).slice(-LEDGER_MAX);
      return list.filter((x) => (done(x) ? floor - (x.upd || 0) < LEDGER_KEEP : open.indexOf(x) !== -1));
    };
    out.promises = prune(out.promises, (x) => x.status !== '未到期');
    out.events = prune(out.events, (x) => x.settled);
    return out;
  }

  // 数据库的约定表、重大事件表（开着「读数据库」、至少有一张）：{ promises: 行, events: 行 }；没有返回 null
  function dbLedger(c) {
    if (!c || !c.读数据库) return null;
    let db = null;
    try { db = readDatabase(null); } catch (e) { db = null; }
    if (!db || !db.own || (!db.own.promises && !db.own.events)) return null;
    return { promises: db.own.promises || [], events: db.own.events || [] };
  }

  // 交给正文、面板上的约定和事件（只在稳定时有）：有数据库的表读表，没有读这一楼记下的。
  // 约定要发起人或对象有一个出场，事件要当事人出场；删掉的人跳过；各最多 LEDGER_SHOW 行，新的在前。
  // 重大事件表的「事件」一栏开头写「好事：」「坏事：」，没写的旧行当坏事
  function ledgerView(st, c) {
    const cc = c || cfg();
    const none = { promises: [], events: [] };
    if (!st || !isStable()) return none;
    const shown = shownPeople(st, cc);
    const roster = rosterFull(cc);
    const alias = (roster && roster.alias) || {};
    const muted = mutedNames();
    const nm = (v) => { const t = String(v || '').replace(/[（(].*$/, '').trim(); return alias[t] || t; };
    const names = (v) => String(v || '').split(/[、,，;；\/]/).map(nm).filter(Boolean);
    let promises;
    let events;
    const db = dbLedger(cc);
    if (db) {
      promises = db.promises.filter((r) => !r['状态'] || r['状态'] === '未到期').map((r) => ({
        from: nm(r['发起人']), toList: names(r['对象']), what: clip(r['约定内容'], 40), when: clip(r['约定时间'], 20) }));
      events = db.events.filter((r) => r['是否已解决'] !== '是').map((r) => {
        const t = String(r['事件'] || '');
        const m = t.match(/^\s*(好事|坏事)\s*[：:]\s*/);
        return { who: nm(r['当事人']), kind: m ? m[1] : '坏事', what: clip(m ? t.slice(m[0].length) : t, 50) };
      });
    } else {
      const open = ledgerOpen(st.ledger);
      promises = open.promises.map((x) => Object.assign({}, x, { toList: [x.to] }));
      events = open.events.slice();
    }
    const on = (n) => shown.indexOf(n) !== -1;
    const ok = (n) => !muted.has(n);
    promises = promises.filter((x) => x.from && x.toList.length && x.what && ok(x.from) && x.toList.every(ok) && (on(x.from) || x.toList.some(on)))
      .map((x) => ({ from: x.from, to: x.toList.join('、'), what: x.what, when: x.when })).reverse().slice(0, LEDGER_SHOW);
    events = events.filter((x) => x.who && x.what && ok(x.who) && on(x.who))
      .map((x) => ({ who: x.who, kind: x.kind, what: x.what })).reverse().slice(0, LEDGER_SHOW);
    return { promises, events };
  }

  // ---------- 渲染：给正文模型看的那一块 ----------
  // 出场的人：在玩家这一场里的，和在平行线上的（玩家不在场、别处同时在演的另一条线，照样注入）
  function onStage(p) { return !!p && (p.inScene !== false || p.parallel === true); }

  // 注入里写哪几个人：出场的，最多「每场最多几人」个；这一场的人排在平行线前面
  // 此刻页「加上」的人（added）不占名额
  function shownPeople(st, c) {
    const max = (c && c.每场最多几人) || DEFAULTS.每场最多几人;
    const on = (st.order || []).filter((n) => onStage(st.people[n]));
    const ranked = on.filter((n) => st.people[n].inScene !== false).concat(on.filter((n) => st.people[n].inScene === false));
    const fit = ranked.filter((n) => !st.people[n].added).slice(0, max);
    return ranked.filter((n) => fit.indexOf(n) !== -1 || st.people[n].added);
  }

  // 平行线上的人分到哪一条线：场面里哪条线的在场名单有她（名字或别名）就归哪条，都没有就归第一条；
  // 场面没记出平行线时给一条没有地点的。返回 [{ place, present, people }]，场面里记了但没人记状态的线也在
  function parallelGroups(st, names) {
    const sc = st.scene || {};
    const alias = (_roster && _roster.alias) || {};
    const lines = (Array.isArray(sc.parallel) ? sc.parallel : []).map((l) => ({ place: l.place || '', present: (l.present || []).slice(), people: [], arranged: !!l.arranged }));
    names.forEach((n) => {
      let i = lines.findIndex((l) => l.present.some((x) => x === n || alias[x] === n));
      if (i === -1) {
        if (!lines.length) lines.push({ place: '', present: [], people: [] });
        i = 0;
      }
      lines[i].people.push(n);
    });
    return lines;
  }

  // stable：稳定人设，不写另一个人格、伏笔、压力、关系（这几样稳定时不算）
  // inBook：这个聊天的世界书里写过「手账本-」条目的人（meta.bookSig），她的关系在条目里
  function personLines(L, st, n, c, stable, inBook) {
    const p = st.people[n];
    L.push('〔' + n + '〕');
    // 另一个人格代替了她：单独一行放在最前面，别让它埋在「动向」里被略过
    if (p.persona && !stable) L.push('现在是｜' + p.persona + '（' + n + '到了极限，档案里写的另一个人格出来代替她。下面几格记的都是' + p.persona + '）');
    if (p.sketch) L.push('简介｜' + p.sketch);
    const period = p.period || personPeriods()[n];          // 有几个时期条目的人记着 period；别的人用设置里手填的
    if (period) L.push('时期｜' + period);
    // 平行线上的人行动、动向和上一楼几乎一样（markRepeat）：这两格不交，免得正文把写过的平行线再写一遍
    const rep = p.repeat || {};
    if (p.doing && !rep.doing) L.push('行动｜' + p.doing);
    if (p.want) L.push('目标｜' + p.want);
    if (p.unsaid && p.unsaid.line) {
      L.push('隐言｜「' + p.unsaid.line + '」' + (p.unsaid.to ? '（对' + p.unsaid.to + '）' : ''));
    }
    if (p.afraid) L.push('顾虑｜' + p.afraid);
    if (p.will && !rep.will) L.push('动向｜' + p.will);
    const ck = checkLine(p.check);
    if (ck) L.push('判定｜' + ck);
    if (stable) return;
    if (p.foreshadow && p.foreshadow.by) L.push('伏笔｜' + p.foreshadow.by + '之前就看出她在忍着，当时没说。这一场写' + p.foreshadow.by + '表现出来。');
    const ch = st.chars && st.chars[n];
    if (ch && ch.level !== '平稳') L.push('压力｜' + ch.level);
    // 关系阶段平时写在世界书条目里；不写世界书、或者她没有「手账本-」条目（自动时没配上性格模板）时放这里
    if (ch && c && (c.自动写入世界书 === false || !(inBook && inBook[n]))) {
      const r = relSummary(ch, 3, true);
      if (r) L.push('关系｜' + r);
    }
  }

  function renderState(st, c) {
    if (!st) return '';
    const L = ['<当前状态>'];
    const sc = st.scene;
    const shown = shownPeople(st, c);
    const here = shown.filter((n) => st.people[n].inScene !== false);
    const away = shown.filter((n) => st.people[n].inScene === false);
    if (sc) {
      // 场面和每个人是分开几路算的，「在场」取两边的并集，免得同一块里自相矛盾
      const present = (sc.present || []).slice();
      here.forEach((n) => { if (present.indexOf(n) === -1) present.push(n); });
      const seg = [];
      if (sc.weekday) seg.push(sc.weekday);
      if (sc.place) seg.push('地点：' + sc.place);
      if (present.length) seg.push('在场：' + present.join('、'));
      if (sc.leave) seg.push('去留：' + sc.leave);
      if (seg.length) L.push('这一场｜' + seg.join('。'));
      if (sc.physics) L.push('世界｜' + sc.physics);
      if (sc.encounter) L.push('偶遇｜' + sc.encounter);
    }
    const stable = isStable();
    const inBook = loadStore().meta.bookSig || {};
    here.forEach((n) => personLines(L, st, n, c, stable, inBook));
    parallelGroups(st, away).forEach((l) => {
      const present = l.present.slice();
      l.people.forEach((n) => { if (present.indexOf(n) === -1) present.push(n); });
      if (!present.length) return;
      L.push('平行线｜' + (l.place ? '地点：' + l.place + '。' : '') + '在场：' + present.join('、') + '（玩家不在场' + (l.arranged ? '；手账本安排的，这一轮可以写到' : '') + '）');
      l.people.forEach((n) => personLines(L, st, n, c, stable, inBook));
    });
    // 配角之间：排在所有人后面（这一对可能一个在这一场、一个在平行线上），见 09_templates.js 的 pairLines
    pairLines(st, c).forEach((p) => L.push('配角之间｜' + p.a + ' 和 ' + p.b + '：' + p.text));
    // 稳定人设：约定和事件跟在配角之间后面
    if (stable) {
      const lv = ledgerView(st, c);
      lv.promises.forEach((x) => L.push('约定｜' + ledgerPromiseText(x)));
      lv.events.forEach((x) => L.push('事件｜' + ledgerEventText(x)));
    }
    if (sc && sc.breath) L.push('节奏｜' + sc.breath);
    const mood = moodHow(sc);
    if (mood) L.push('氛围｜' + mood + (sc.mood && sc.mood.jump && sc.mood.hook ? '这一场的写法和前面几场不同，起因是' + sc.mood.hook + '。' : ''));
    L.push('</当前状态>');
    return L.length > 2 ? L.join('\n') : '';
  }

  // 氛围轨迹（内容规划书 2.7）：每一楼掷中的氛围按楼层记进 meta.moods，最多 MOOD_TRACK_MAX 条
  const MOOD_TRACK_MAX = 100;
  function recordMood(store, floor, sd, mood) {
    if (!store || !mood || !mood.name) return;
    const list = (Array.isArray(store.meta.moods) ? store.meta.moods : []).filter((x) => x && x.floor !== floor);
    const hit = moodPool().find((x) => x.name === mood.name);
    list.push({ floor, sd: String(sd || ''), name: mood.name, cat: hit ? hit.cat : '', jump: !!mood.jump });
    list.sort((a, b) => a.floor - b.floor);
    store.meta.moods = list.slice(-MOOD_TRACK_MAX);
  }

  // 面板用：还在聊天里的那些楼（删掉、换过的不算），和两个数——最近 10 场用了几种、同一种最短隔几场又出现（null＝没重复过）
  function moodTrack(store) {
    const chat = chatNow();
    const list = (store && Array.isArray(store.meta.moods) ? store.meta.moods : [])
      .filter((x) => x && chat[x.floor] && String(chat[x.floor].send_date || '') === String(x.sd || ''));
    const last10 = list.slice(-10);
    const kinds = new Set(last10.map((x) => x.name)).size;
    let gap = null;
    const seen = {};
    list.slice(-20).forEach((x, i) => {
      if (seen[x.name] != null) gap = gap == null ? i - seen[x.name] - 1 : Math.min(gap, i - seen[x.name] - 1);
      seen[x.name] = i;
    });
    return { cells: list, kinds, recent: last10.length, gap };
  }

  // 这一场挑中的氛围 → 氛围池里那一条的写法。名字不给正文；氛围池里已经没有这个名字（被改掉了）就不给
  function moodHow(sc) {
    const name = sc && sc.mood && sc.mood.name;
    if (!name) return '';
    const hit = moodPool().find((x) => x.name === name);
    return hit ? hit.how : '';
  }

  // 单独拎出来：开着导演稿时这一句换成指向导演稿的说法（见 12_director.js）
  const GUIDE_RECALL_LINE = '· 玩家这一轮的话后面如果跟着 <recall>、<supplement> 这样的块，那是数据库的剧情推进找到的旧事编码和背景设定，不是玩家说的话。它们属于已经发生的事，和 <当前状态> 不冲突。';

  const GUIDE = `<手账本读法>
玩家每一轮消息的前面有一块 <当前状态>。填表员读完设定和最近的剧情以后，给这一场的角色填了此刻的状态。读法如下。

【是什么】
· 这是幕后的状态，不是剧情大纲，也不是台词稿。它写角色此刻在做什么、想要什么、有什么话没说、在躲什么。怎么写成正文由你决定。
· 它每一轮都会更新。以最新的一块为准。

【每一格】
· 这一场：星期几、地点、在场的人、去留。星期几只在知道时出现。按它安排人物的位置，以及谁能离开、谁只能留在原地。
· 平行线：玩家不在场、别处同时在演的另一条线。后面跟着那条线上的人的状态，每一格的读法和这一场的人一样。写到那条线时照它写。玩家不知道那条线上的事。回到玩家这边时，不写玩家知道那边的事。写着「手账本安排的」的平行线，正文还没写过：这一轮可以写到她，写在平行线里；不写也可以。不为这一条安排她和这一场的人见面。平行线上的人少了行动、动向两格，是这两格和上一轮一样：这条线写过的不重写，写就接着往下写，不写也可以。
· 世界：只在缺世界设定时出现，定下这是什么样的世界。照它写，不在几种设定之间来回换。
· 偶遇：这一场碰上的一件事或一样东西。写进这一场，写成自然发生的事。
· 简介：只在缺人物档案时出现，写她是谁。
· 时期：她现在处在剧情的哪个时期，玩家定的。角色卡和设定里分时期写的，只用这个时期的；还没到这个时期的事，她不知道，也还没发生。
· 行动：玩家这一轮之前她手上在做的事。开写时她还在做。玩家是打断她的人，她不是在等玩家。
· 目标：这一场她要做成的事。写她朝这个方向做了什么：动作，把话题往哪里带，盯着什么。不写她直接说出自己的目标。
· 隐言：她刚才没说出口的一句话，是这一场的潜台词。这句话不出现在正文里，换个说法也不出现。只写它在她言行上留下的痕迹。括号里写的是她想对谁说。
· 顾虑：她在避开的事。写她回避的动作，不直接写她的情绪。
· 动向：没人再打断时她接下来会做的事，以及她怎么回应玩家这一轮。玩家这一轮的内容和它冲突时，以玩家这一轮为准。
· 现在是：她到了极限，档案里写的另一个人格出来代替了她。这一格在时，用她的身体说话、行动的是这个人格。照档案写这个人格的语气、称呼、举止。不写回她本人，也不写成她在模仿别人。这一格消失时，她本人才回来。
· 压力：只在紧张或崩溃时出现。紧张：她接近极限。写出失误和快要失控的迹象。崩溃：她已经到了极限。照她的角色卡和性格模板写崩溃的样子，包括换成另一个人格的情况。不替她忍住。这一格优先于隐言、顾虑里忍着的写法。
· 关系：她和谁到了哪一步，后面跟着好感底色和信任落点。按这一步对待这个人，不跳级。好感底色是这份感情由什么构成，她对这个人的温度和偏心照它写。信任落点是她相信这个人会做或不会做的事。这个人的举动含糊时，她往哪边想、肯交出什么，照它写。关系阶段和好感底色对不上时，按她的角色卡写出这份落差。
· 判定：这一场掷过骰的一件事和它的结果，后面跟着写法。照结果写，写法照这一格。结果和她的动向对不上时，照判定写。正文里不写骰子、阈值、判定这些词。
· 伏笔：之前有人看出了她在忍着，当时没说。这一场写那个人表现出来。
· 配角之间：两个配角现在看得见的相处。她们同场、或者说到对方时照它写。上文写到两人的相处变了的，照上文。不为这一格安排她们见面或互动。别的角色知不知道，按上文。
· 约定：谁答应了谁什么，还没兑现。写到这两个人、或者到了约定的时间时照它写。不为这一格安排兑现。上文写到约定已经变了的，照上文。
· 事件：最近落在她身上、还没过去的好事和坏事。她的言行照这件事写，不替她了结。上文写到这件事已经过去的，照上文。
· 节奏：这一场快还是慢，哪里停顿。照它控制快慢和停顿。
· 氛围：这一场怎么写：写哪些东西，句子多长。照它写。写法里要写的人和东西，只用上文和设定里已有的，不另外添加。氛围和人物的档案、状态冲突时，人物照档案和状态写。这一格的字句不抄进正文。正文里不点明这是什么氛围。

【和别的材料分工】
· 已经发生的事，以上文、世界书和记忆记录为准。已经发生的事包括：事件，经历，谁对谁做过什么，人物的身份和外貌。
· 此刻的状态，以 <当前状态> 为准。此刻的状态包括：行动，目标，隐言，顾虑，动向。
· 世界书里的「手账本-某人」条目写着：她用哪几本性格模板，每本的要点，她的压力，她和每个人的关系阶段、好感底色、信任落点。好感底色、信任落点的读法和 <当前状态> 里的「关系」一样。模板写的是这一类性格一般怎么表现。模板和角色卡冲突时，按角色卡。
${GUIDE_RECALL_LINE}
· 冲突时：事实按记忆，此刻按 <当前状态>。

【注意】
· 不把 <当前状态> 的字句照抄进正文。不在正文里复述或解释它。
· 正文里不出现「当前状态」「手账本」「填表员」这些词。
· 没出现的格子当作没有，不替它补。<当前状态> 里没出现的角色，按设定和上文照常写。
</手账本读法>`;

  function injectState(st, c) {
    if (DISPOSED) return '';
    const conf = c || cfg();
    let text = '';
    try { text = renderState(st, conf); } catch (e) { warn('状态渲染失败，这一轮不注入：', e); }
    if (!text) { clearInjection(); return ''; }
    if (!isMainGeneration()) { hideState(); return text; }                    // 不在正文生成的窗口里：存着，开窗时再挂
    try {
      // 读法说明和状态放在同一块里。聊天变长以后酒馆从最旧的一头往下裁，
      // 放在聊天记录最上方的注入会第一个被裁掉；贴着玩家消息的这一块不会。
      const content = conf.注入读法说明 ? promptText('读法说明') + '\n\n' + text : text;
      uninjectPrompts([INJECT_GUIDE_ID, INJECT_ACG_ID]);
      // 只进正文生成：别的插件（数据库填表、剧情推进、总结……）调模型时不带，不然它们会把这份状态当成事实记下来
      injectPrompts([{ id: INJECT_STATE_ID, position: 'in_chat', depth: 1, role: 'system', content, should_scan: false, filter: isMainGeneration }]);
    } catch (e) {
      warn('注入失败：', e);
    }
    return text;
  }

  function clearInjection() {
    try { uninjectPrompts([INJECT_STATE_ID, INJECT_GUIDE_ID, INJECT_ACG_ID]); } catch (e) { /* ignore */ }
  }

  // ---------- 只给正文生成 ----------
  // 状态注入和强制激活只在一个窗口里生效：从正文生成马上要扫世界书、拼提示词开始（arm），到它的提示词拼好为止（disarm）。
  //   · 普通发送：玩家那条落楼、冲击轮等完以后开窗（数据库的剧情推进在这之前就跑完了）
  //   · 重新生成、换一条、继续：生成前事件里开窗
  //   · 正文的提示词拼好就关窗（聊天补全接口看 chat_completion_prompt_ready，文本补全看 generate_after_combine_prompts，试算不算）；停止生成也关
  // 为什么不用「生成开始 / 结束」：酒馆助手的 generate（数据库等脚本调模型用它）也会发 generation_ended，还在发
  // js_generation_started 之前就拼好了自己的提示词；酒馆注入的 filter 对聊天内的注入又不生效（异步函数传给了 Array.filter）。
  // 所以脚本的生成插进来时先把窗口挂起、撤掉注入。脚本只在拼提示词的那一下会和正文撞上：
  // 酒馆助手的 generate 先发 js_generation_requested（带生成编号），拼好提示词再发 js_generation_started（同一个编号）。
  // 挂起只挂到它拼好为止，不等它整个生成跑完；正文生成这时候照常拿状态、导演稿照常接管。
  // 旧版酒馆助手没有 requested 事件时，退回看「生成前事件不带参数」，拼好的信号还是 started，都没来就按 BUILD_MAX_MS 放掉。
  // builtKey：正文提示词真正拼好过的那一句（turnKey）。剧情推进开着时，数据库先拦下普通发送、再用「重新生成」生成第一条回复，
  // 那一次正文还没生成过，不算玩家的重新生成
  const GEN = { tracking: false, armed: false, building: new Map(), noTail: false, builtKey: '' };
  const BUILD_MAX_MS = 20000;

  function foreignBuilding() {
    const now = Date.now();
    GEN.building.forEach((at, id) => { if (now - at > BUILD_MAX_MS) GEN.building.delete(id); });
    return GEN.building.size > 0;
  }

  function isMainGeneration() {
    if (!GEN.tracking) return true;                  // 旧版酒馆助手挂不上这些事件：照旧每次都注入
    if (foreignBuilding()) return false;             // 有脚本正在拼它自己的提示词
    return GEN.armed;
  }

  function armMain() { GEN.armed = true; resetActivated(); reinject(); }
  function disarmMain() { GEN.armed = false; GEN.noTail = false; hideState(); }
  // id：酒馆助手给的生成编号；生成前事件不带参数的那种没有编号，记成 ac: 开头的一条
  function onForeignStart(id) { GEN.building.set(id ? String(id) : 'ac:' + Date.now() + ':' + GEN.building.size, Date.now()); hideState(); }
  // 脚本拼好了提示词（started）或者整个结束了（ended）：放掉它，连同它之前记下的没有编号的那条
  function onForeignBuilt(id) {
    const now = Date.now();
    if (id) GEN.building.delete(String(id));
    GEN.building.forEach((at, k) => { if (k.indexOf('ac:') === 0 && at <= now) GEN.building.delete(k); });
    if (isMainGeneration()) reinject();
  }
  function onForeignEnd(id) { onForeignBuilt(id); }
  // 换聊天、点停止：还挂着的脚本生成算它结束了。停止按钮会把脚本的生成一起停掉，结束事件不一定还会来
  function resetForeign() { GEN.building.clear(); }
  // kind：'chat'（chat_completion_prompt_ready）或 'text'（generate_after_combine_prompts）。
  // 用聊天补全接口时，after_combine 在拼聊天消息之前就发了，那时候关窗，状态就进不了这一次的提示词。
  // 开着导演稿时，关窗前先把拼好的提示词交给导演稿改（酒馆会等这个监听器跑完才发请求）
  async function onPromptReady(data, kind) {
    if (data && data.dryRun) return;
    if (kind === 'text') {
      const ctx = getCtx();
      if (ctx && ctx.mainApi === 'openai') return;
    }
    if (foreignBuilding()) return;                   // 是脚本生成拼好的，不是正文的
    if (!GEN.armed) return;
    GEN.builtKey = turnKey();
    const c = cfg();
    if (c.导演稿 !== '关') {
      try { await runDirector(data, c); } catch (e) { warn('导演稿出错，这一轮照原样交给正文：', e); }
    }
    disarmMain();
  }

  function hideState() {
    try { uninjectPrompts([INJECT_STATE_ID]); } catch (e) { /* ignore */ }
  }

  // 切聊天、删消息、脚本重载之后：把最新的有效状态重新挂上去
  function reinject() {
    const st = stateForGeneration();
    if (st) injectState(st);
    else clearInjection();
    return st;
  }

  // ======================== 一轮的编排 ========================
  // 时序（和数据库同时启用时）：
  //   GENERATION_AFTER_COMMANDS  我们排第一个：趁数据库改写输入框之前拍下玩家原话，立刻开跑副模型
  //                             （不等它，数据库的剧情推进和我们并行）
  //   MESSAGE_SENT               玩家那条进了聊天记录，拿到真楼层号；冲击轮在这里等，最多等到上限
  //   世界书扫描 / 拼提示词       注入在这之后才被读，所以等到的结果当轮就生效
  // 场面一路、每个人各一路，并行跑：一次写全场要五秒多，拆开后每路三秒上下，谁先回来谁先用。

  let runSeq = 0;
  let pendingRun = null;       // 已经开跑、还没认领楼层的那一轮
  let lastRun = null;          // 悬浮窗「此刻」那一页用
  const inflight = new Set();  // 还在跑的轮次，悬浮球据此转圈

  // opt.cast：照这份名单记（单独重算时用那一楼原来的名单），不按这一次的排名挑；opt.noEncounter：不掷偶遇
  async function gather(input, upto, tail, opt) {
    const c = cfg();
    const base = await buildRoster(false);
    const merged = mergeDatabase(base, c, latestRecall(upto + 1));   // 重算时 upto 是玩家那一楼本身，召回要算上它
    const roster = merged.roster;
    const db = merged.db;
    _rosterFull = roster;                              // 数据库这一轮新读到的人，性格模板和写世界书也看得见
    const persona = readPersona();
    const store = loadStore();
    const history = statesBefore(store, upto, AGE_LIMIT + 1);
    const prev = history[0] || null;
    const story = recentStory(upto);
    const muted = mutedNames(store);                   // 这个聊天里删掉的人：哪条路都不挑她
    const skip = skipNames(c);
    // 咩咩预设的世界运行报告里的平行线事件：事件里的人这一场没写到时算在平行线上（凭据之一），状态照下回合推演记
    const wlog = wlogEvents(story.lastAIRaw, roster, persona.name, skip);
    const ranked = rankPresent(roster, story, input, prev, skip, wlog).filter((x) => !muted.has(x.name));
    const lined = new Set(ranked.filter((x) => x.lines).map((x) => x.name));    // 这一轮 <parallel_line> 里写到的人，平行线的凭据之一
    const wlogOf = new Map();
    ranked.filter((x) => x.wlog).forEach((x) => { const ev = wlog.find((e) => e.people.indexOf(x.name) !== -1); if (ev) wlogOf.set(x.name, ev); });
    const cast = (opt && Array.isArray(opt.cast) ? opt.cast.slice() : ranked.slice(0, c.每场最多几人).map((x) => x.name)).filter((n) => !muted.has(n));
    // 平行线安排（设置，默认关）：这一轮挑一个人放到平行线上，不在 cast 里就加进去（多记一个人）
    const arranged = opt && Array.isArray(opt.cast) ? String(opt.arranged || '')
      : planArranged({ c, roster, cast, history, prev, lined, wlogOf, ranked, muted, skip, player: persona.name,
        appeared: c.平行线安排 ? appearedNames(roster, store, db, upto) : null });
    if (arranged && cast.indexOf(arranged) === -1) cast.push(arranged);
    // 重算这一楼：上次在此刻页「加上」的人留着，照样不占名额
    const added = [];
    const here = store.floors[upto];
    const hereMsg = chatNow()[upto];
    if (!(opt && Array.isArray(opt.cast)) && here && here.people && hereMsg && String(here.sd || '') === String(hereMsg.send_date || '')) {
      Object.keys(here.people).forEach((n) => {
        if (!here.people[n] || !here.people[n].added || muted.has(n)) return;
        added.push(n);
        if (cast.indexOf(n) === -1) cast.push(n);
      });
    }
    // 稳定人设（此聊天的「性格」选稳定）：不用性格模板，也不在后台识别；约定和事件没有数据库的表时由场面那一路顺带记
    const stable = isStable(store);
    const ledgerSelf = stable && !dbLedger(c);
    // 这些人的性格模板，和上一楼算到的压力、关系阶段
    const tpl = stable ? null : await loadTemplates(false);
    const templates = {};
    cast.forEach((n) => {
      const p = roster.people.get(n);
      templates[n] = p && tpl ? templatesFor(n, p.profile, c, tpl) : [];
    });
    // 还没识别过性格模板的人，后台让副模型识别；这一轮不等它，识别完写世界书，下一轮起填表员就读得到
    const unknown = stable ? [] : cast.map((n) => roster.people.get(n)).filter((p) => p && !templates[p.name].length);
    if (unknown.length && !identifyBlocked()) {
      const chatId = currentChatId();
      identifyTemplates(unknown.map((p) => ({ name: p.name, profile: p.profile })), tpl, c)
        .then((r) => { if (r.done && !DISPOSED && chatId === currentChatId()) { reinject(); scheduleBookWrite(); } })
        .catch((e) => warn('自动识别性格模板失败：', e));
    }
    const chars = (prev && prev.chars) || {};
    const encounter = tail || (opt && opt.noEncounter) ? null : maybeEncounter(base, prev && prev.scene, story);     // 地点资料在原始名册上（合并数据库的那份副本不带）
    return { c, roster, db, persona, store, history, prev, story, input, ranked, lined, muted, cast, templates, chars, encounter, tail: !!tail,
      stable, ledgerSelf, prevLedger: (prev && prev.ledger) || null, wlog, wlogOf, notes: personNotes(store), periods: personPeriods(store), arranged, added };
  }

  // 平行线事件里的人：上一楼记她时用的就是这一版下回合推演（sig 一样），这一轮正文的 <parallel_line> 也没写到她，就不重记、沿用上一楼
  // ---------- 平行线安排（设置「平行线安排」，默认关） ----------
  // 这一轮正文里没有平行线（<parallel_line> 没写到人、世界运行报告里也没有平行线事件）时，挑一个人放到平行线上：
  //   · 上一轮安排过、这一场也不在的人接着安排，最多连着 ARRANGE_RUNS 轮（正文写到她以后就照平常的凭据算）；
  //   · 这一轮要记的人里，有上一楼「不在场、没注入」的，不另挑：落档时把她们放到平行线上（arrangeParallel）；
  //   · 否则从名册里挑一个：这一场的正文没提到、最近 ARRANGE_RECENT 楼没出场、没删掉、不在「不算点名的名字」里、不是玩家。
  //   这一场人已经满了（每场最多几人）不安排。返回名字，不安排时是空字符串
  const ARRANGE_RUNS = 3;
  const ARRANGE_RECENT = 6;
  function planArranged(o) {
    const { c, roster, cast, history, prev, lined, wlogOf, ranked, muted, skip, player } = o;
    if (!c.平行线安排 || !roster || !roster.people) return '';
    if ((lined && lined.size) || (wlogOf && wlogOf.size)) return '';
    if (cast.length >= c.每场最多几人) return '';
    const pp = (prev && prev.people) || {};
    const mentioned = new Set((ranked || []).map((x) => x.name));
    const keep = Object.keys(pp).find((n) => pp[n] && pp[n].arranged && (pp[n].arrangedRuns || 1) < ARRANGE_RUNS &&
      roster.people.has(n) && !muted.has(n) && !(mentioned.has(n) && !(ranked.find((x) => x.name === n) || {}).parallel));
    if (keep) return keep;
    if (cast.some((n) => pp[n] && pp[n].inScene === false && pp[n].parallel !== true)) return '';
    const recent = new Set();
    (history || []).slice(0, ARRANGE_RECENT).forEach((st) => Object.keys((st && st.people) || {}).forEach((n) => { if (onStage(st.people[n])) recent.add(n); }));
    // 只挑这个聊天里出场过的人（appearedNames）：名册里有、剧情里还没登场的人不安排
    const seen = o.appeared || new Set();
    const pool = Array.from(roster.people.keys()).filter((n) => cast.indexOf(n) === -1 && !mentioned.has(n) && !recent.has(n) &&
      !muted.has(n) && !(skip && skip.has(n)) && !sameName(n, player) && seen.has(n));
    if (!pool.length) return '';
    return pool[Math.floor(randomUnit() * pool.length) % pool.length];
  }
  // 这个聊天里出场过的人：存档里哪一楼记过她，数据库里记着她，或者聊天记录里写到过她的名字或别名（撞车的词不算）
  function appearedNames(roster, store, db, upto) {
    const out = new Set();
    Object.keys((store && store.floors) || {}).forEach((k) => Object.keys((store.floors[k] && store.floors[k].people) || {}).forEach((n) => out.add(n)));
    Object.keys((db && db.people) || {}).forEach((n) => out.add(n));
    const text = chatNow().slice(0, upto).map((m) => String((m && m.mes) || '')).join('\n');
    const amb = roster.ambiguous || new Set();
    Object.keys(roster.alias || {}).forEach((a) => {
      const n = roster.alias[a];
      if (out.has(n) || a.length < 2 || amb.has(a)) return;
      if (text.indexOf(a) !== -1) out.add(n);
    });
    return out;
  }
  // 有几个时期条目的人这一轮在哪个时期：玩家在设置里选了的照选的；没选的照上一楼记的（periodNow）。
  // 状态模型这一轮报的 period 对得上她的时期名就换成它（玩家选了的不换）
  function periodNow(mat, name) {
    const p = mat && mat.roster && mat.roster.people.get(name);
    if (!p || !p.periods) return { label: '', manual: false };
    const manual = matchPeriod(p, (mat.periods || {})[name]);
    if (manual) return { label: manual, manual: true };
    const pp = mat.prev && mat.prev.people && mat.prev.people[name];
    return { label: matchPeriod(p, pp && pp.period), manual: false };
  }
  function markPeriod(mat, name, entry) {
    if (!entry) return entry;
    const p = mat && mat.roster && mat.roster.people.get(name);
    if (!p || !p.periods) { delete entry.periodRaw; return entry; }
    const now = periodNow(mat, name);
    const said = now.manual ? '' : matchPeriod(p, entry.periodRaw);
    entry.period = said || now.label || '';
    delete entry.periodRaw;
    return entry;
  }
  // 记好的这个人：照安排放在平行线上（模型写成在场也改过来），记下连着安排了几轮
  function markArranged(mat, name, entry) {
    markPeriod(mat, name, entry);
    if (!entry || !mat || mat.arranged !== name) return entry;
    const pp = mat.prev && mat.prev.people && mat.prev.people[name];
    entry.inScene = false;
    entry.parallel = true;
    entry.arranged = true;
    entry.arrangedRuns = pp && pp.arranged ? (pp.arrangedRuns || 1) + 1 : 1;
    return entry;
  }
  // 落档时：这一轮没有正文写到的平行线，就把安排的人、和这一轮「不在场、没注入」的人放到平行线上（最多两条）；
  // 正文这一轮写了平行线的，安排的人退回「不在场」
  function arrangeParallel(st, mat) {
    if (!mat || !mat.c || !mat.c.平行线安排 || !st || !st.people) return;
    const names = Object.keys(st.people).filter((n) => st.people[n]);
    const sc = st.scene || {};
    const lines = (Array.isArray(sc.parallel) ? sc.parallel : []).filter((l) => l && Array.isArray(l.present) && l.present.length && !l.arranged);
    const backed = names.some((n) => st.people[n].parallel === true && !st.people[n].arranged);
    if (backed || lines.length) {
      names.forEach((n) => { if (st.people[n].arranged) st.people[n] = Object.assign({}, st.people[n], { parallel: false, arranged: undefined }); });
      return;
    }
    const picks = names.filter((n) => st.people[n].arranged && !st.people[n].carried)
      .concat(names.filter((n) => { const p = st.people[n]; return !p.carried && !p.arranged && p.inScene === false && p.parallel !== true; }))
      .slice(0, 2);
    names.forEach((n) => { if (st.people[n].arranged && picks.indexOf(n) === -1) st.people[n] = Object.assign({}, st.people[n], { parallel: false, arranged: undefined }); });
    if (!picks.length) return;
    const pp = (mat.prev && mat.prev.people) || {};
    picks.forEach((n) => {
      const p = st.people[n];
      if (p.arranged) return;
      st.people[n] = Object.assign({}, p, { inScene: false, parallel: true, arranged: true, arrangedRuns: pp[n] && pp[n].arranged ? (pp[n].arrangedRuns || 1) + 1 : 1 });
    });
    st.scene = Object.assign({}, sc, { parallel: picks.map((n) => ({ place: '', present: [n], arranged: true })) });
  }

  // 平行线上的人：行动、动向和上一楼记的几乎一样（推演没变沿用的、跨轮雷同的），标 repeat，交给正文时不带这两格
  // （正文会照着把写过的平行线再写一遍，下回合推演又不变，就转圈）。不在平行线上的人不标
  const REPEAT_NOTE = '平行线：行动、动向和上一轮几乎一样，这一轮没交给正文';
  function markRepeat(st, base) {
    const bp = (base && base.people) || {};
    Object.keys(st.people).forEach((n) => {
      const p = st.people[n];
      if (!p) return;
      const q = p.inScene === false && p.parallel === true ? bp[n] : null;
      const same = (k) => !!(q && p[k] && q[k] && (p[k] === q[k] || fuzzyHit(p[k], q[k])));
      const rep = { doing: same('doing'), will: same('will') };
      const notes = (p.notes || []).filter((x) => x !== REPEAT_NOTE);
      if (rep.doing || rep.will) st.people[n] = Object.assign({}, p, { repeat: rep, notes: notes.concat([REPEAT_NOTE]) });
      else if (p.repeat) st.people[n] = Object.assign({}, p, { repeat: undefined, notes });
    });
  }

  function keepWlog(mat, n) {
    const ev = mat.wlogOf && mat.wlogOf.get(n);
    const p = mat.prev && mat.prev.people && mat.prev.people[n];
    return !!(ev && p && p.wlog === ev.sig && !(mat.lined && mat.lined.has(n)));
  }
  const WLOG_KEPT = '平行线：世界运行报告里这件事的下回合推演没变，沿用上一轮';
  // 记好的平行线事件里的人：记下用的是哪一版推演；她这一场没写到，一律算在平行线上
  function markWlog(mat, name, entry) {
    const ev = mat.wlogOf && mat.wlogOf.get(name);
    if (!ev || !entry) return entry;
    entry.wlog = ev.sig;
    entry.inScene = false;
    entry.parallel = true;
    return entry;
  }
  // 平行线事件在场面里没有对应的平行线时，一件事补一条（没有地点），这件事里的人分在这条线上；
  // 场面那一路把这些人写进了「在场」的，拿掉（她这一场没写到，已经算在平行线上）
  function withWlogLines(sc, mat, people) {
    if (!sc || !mat.wlog || !mat.wlog.length) return sc;
    const alias = (mat.roster && mat.roster.alias) || {};
    const away = new Set(Object.keys(people).filter((n) => mat.wlogOf && mat.wlogOf.has(n) && people[n] && people[n].parallel === true));
    const present = Array.isArray(sc.present) ? sc.present.filter((x) => !away.has(x) && !away.has(alias[x])) : sc.present;
    const lines = (Array.isArray(sc.parallel) ? sc.parallel : []).map((l) => Object.assign({}, l, { present: (l && Array.isArray(l.present) ? l.present : []).slice() }));
    const inLine = (n) => lines.some((l) => l.present.some((x) => x === n || alias[x] === n));
    let added = false;
    mat.wlog.forEach((ev) => {
      const who = ev.people.filter((n) => away.has(n) && !inLine(n));
      if (!who.length) return;
      lines.push({ place: '', present: who });
      added = true;
    });
    const moved = Array.isArray(sc.present) && present.length !== sc.present.length;
    return added || moved ? Object.assign({}, sc, { present, parallel: lines }) : sc;
  }

  // 发给状态模型的提示词和回答结构要按哪种来：稳定人设、场面那一路要不要顺带记约定和事件
  function promptOpt(mat, mode) {
    return { stable: !!mat.stable, ledger: !!mat.ledgerSelf && (mode === 'scene' || mode === 'cold') };
  }

  // ---------- 删掉一个人（人物卡上的「删掉」） ----------
  // 只管这个聊天：名字记进 meta.muted；存档里每一楼都拿掉她的状态（压力、关系阶段留着），以后挑人、落档都跳过她。
  // 「恢复」只把名字从 meta.muted 拿掉：删掉的那几楼状态不回来，下一轮起照常挑、照常记
  function mutedNames(store) {
    const s = store || loadStore();
    return new Set((Array.isArray(s.meta.muted) ? s.meta.muted : []).filter((n) => typeof n === 'string' && n));
  }
  // 场面里「在场」和平行线的名单也拿掉删掉的人（名单里写的可能是别名）
  function sceneWithout(sc, muted, alias) {
    if (!sc || !muted.size) return sc;
    const al = alias || {};
    const keep = (list) => (Array.isArray(list) ? list.filter((x) => !muted.has(x) && !muted.has(al[x])) : list);
    return Object.assign({}, sc, { present: keep(sc.present),
      parallel: Array.isArray(sc.parallel) ? sc.parallel.map((l) => Object.assign({}, l, { present: keep(l && l.present) })) : sc.parallel });
  }
  function mutePerson(name) {
    const n = String(name || '').trim();
    if (!n) throw new Error('没有名字');
    const store = loadStore();
    store.meta.muted = (Array.isArray(store.meta.muted) ? store.meta.muted : []).filter((x) => x !== n).concat([n]);
    const one = new Set([n]);
    const alias = (_roster && _roster.alias) || {};
    Object.keys(store.floors).forEach((k) => {
      const st = store.floors[k];
      if (!st) return;
      if (st.scene) st.scene = sceneWithout(st.scene, one, alias);
      if (!st.people || !st.people[n]) return;
      delete st.people[n];
      st.order = (Array.isArray(st.order) ? st.order : []).filter((x) => x !== n);
    });
    saveStore(store);
    reinject();
    BUS.emit('state', latestState(store, null));
  }
  // ---------- 补充（设置「选择性格模板」里每人一栏） ----------
  // 只管这个聊天：存在 meta.notes { 名字: 文字 }。交给状态模型（档案后面）、写进她的「手账本-名字」条目，和模板冲突时照它
  const NOTE_MAX = 600;
  function personNotes(store) {
    const s = store || loadStore();
    const v = s.meta.notes;
    const out = {};
    if (v && typeof v === 'object' && !Array.isArray(v)) {
      Object.keys(v).forEach((k) => { const t = String(v[k] == null ? '' : v[k]).trim(); if (k && t) out[k] = t; });
    }
    return out;
  }
  // 时期（同一块里每人一格）：她现在处在剧情的哪个时期，一句话，玩家手填。只管这个聊天：存在 meta.periods { 名字: 文字 }。
  // 交给状态模型（档案后面）和正文（她那几行里），档案、设定里分时期写的照这个时期
  const PERIOD_MAX = 60;
  function personPeriods(store) {
    const v = (store || loadStore()).meta.periods;
    const out = {};
    if (v && typeof v === 'object' && !Array.isArray(v)) {
      Object.keys(v).forEach((k) => { const t = String(v[k] == null ? '' : v[k]).replace(/\s+/g, ' ').trim(); if (k && t) out[k] = t; });
    }
    return out;
  }
  function setPersonPeriod(name, text) {
    const n = String(name || '').trim();
    if (!n) throw new Error('没有名字');
    const t = String(text == null ? '' : text).replace(/\s+/g, ' ').trim().slice(0, PERIOD_MAX);
    const store = loadStore();
    const v = personPeriods(store);
    if (t) v[n] = t; else delete v[n];
    store.meta.periods = v;
    saveStore(store);
    reinject();
    return t;
  }

  // 设置里改一个人对某人的关系（阶段、好感底色、信任落点）：改进面板显示的那一楼（「记到最新」那份改到它底下玩家那一楼，两份都改），
  // 后面有楼就顺着重算。阶段变了记一笔「手改」、攒的清零；手动、自动都能改，自动时从改过的那一格接着攒
  function setRelation(name, to, patch) {
    const store = loadStore();
    const st = latestState(store, null);
    if (!st || !st.chars || !st.chars[name] || !st.chars[name].rel || !st.chars[name].rel[to]) throw new Error('还没记过她和' + to + '的关系');
    const base = st.tail ? statesBefore(store, st.floor, 1)[0] : null;
    const into = base && base.chars && base.chars[name] && base.chars[name].rel && base.chars[name].rel[to] ? base : st;
    const apply = (ch, floor) => {
      const r = ch.rel[to] || (ch.rel[to] = { stage: '陌生人', acc: 0, moved: null, log: [] });
      if (patch.stage != null && STAGES.indexOf(patch.stage) !== -1 && patch.stage !== r.stage) {
        r.log = (r.log || []).concat([{ floor, from: r.stage, to: patch.stage, why: '手改' }]).slice(-R.keepLog);
        r.stage = patch.stage;
        r.acc = 0;
        r.moved = floor;
      }
      if (patch.tone != null) { const t = clip(patch.tone, 10); if (t) r.tone = t; else delete r.tone; }
      if (patch.trust != null) { const t = clip(patch.trust, 12); if (t) r.trust = t; else delete r.trust; }
    };
    apply(into.chars[name], into.floor);
    if (into !== st && st.chars[name]) apply(st.chars[name], st.floor);
    if (Object.keys(store.floors).some((k) => Number(k) > into.floor && store.floors[k] !== st)) refoldChars(store, into.floor + 1, cfg());
    saveStore(store);
    reinject();
    BUS.emit('state', null);
    scheduleBookWrite();
    return st.chars[name].rel[to];
  }

  // 存一个人的补充；空着就删掉。返回存下的文字（删掉时是空字符串）
  function setPersonNote(name, text) {
    const n = String(name || '').trim();
    if (!n) throw new Error('没有名字');
    const t = String(text == null ? '' : text).trim().slice(0, NOTE_MAX);
    const store = loadStore();
    const notes = personNotes(store);
    if (t) notes[n] = t; else delete notes[n];
    store.meta.notes = notes;
    saveStore(store);
    scheduleBookWrite();
    return t;
  }
  function unmutePerson(name) {
    const store = loadStore();
    const list = Array.isArray(store.meta.muted) ? store.meta.muted : [];
    if (list.indexOf(name) === -1) return false;
    store.meta.muted = list.filter((x) => x !== name);
    saveStore(store);
    return true;
  }

  // 平行线要有凭据：这一轮正文里 <parallel_line> 包着的段落写到了她，或者这一轮正文的世界运行报告（咩咩预设的 <wlog>）
  // 平行线事件里有她，或者场面那一路这一轮把她写进了平行线。
  // 状态模型自己说她在平行线上、这两样都没有的，这一轮不算平行线、不注入——
  // 不然一个没出场的人会被写成在别处盯着玩家这一场。scene：这一轮的场面（还没回来、没算出来时为 null，只看正文）
  function parallelBacked(mat, scene, n) {
    if (mat.lined && mat.lined.has(n)) return true;
    if (mat.wlogOf && mat.wlogOf.has(n)) return true;            // 世界运行报告的平行线事件里有她
    if (mat.arranged && mat.arranged === n) return true;          // 平行线安排挑中的她
    const alias = (mat.roster && mat.roster.alias) || {};
    return !!(scene && Array.isArray(scene.parallel)) &&
      scene.parallel.some((l) => (l && Array.isArray(l.present) ? l.present : []).some((x) => x === n || alias[x] === n));
  }
  const PARALLEL_UNBACKED = '平行线：正文里没写到她在那条线上，这一轮不算平行线，不注入';
  function checkParallel(mat, scene, people, names) {
    (names || Object.keys(people)).forEach((n) => {
      const p = people[n];
      if (!p || p.parallel !== true || parallelBacked(mat, scene, n)) return;
      people[n] = Object.assign({}, p, { parallel: false, notes: (p.notes || []).concat([PARALLEL_UNBACKED]) });
    });
  }

  function runKey(run) {
    return run.startedAt + ':' + run.id;
  }

  // 记状态的一路（场面、冷启动、某一个人）：被接口的内容审查拦下时，换短材料重试一次；
  // 回答写到一半被截断（会思考的模型把字数想完了）时，加大字数重发一次
  const biggerTokens = (n) => Math.min(16000, Math.max(n * 8, 8192));
  // 每一路最多等多久（排队不算）。会思考的模型（Gemini 3 系）记一个人实测 12～41 秒，想得多的人每次都过 30 秒；
  // 手账本到点放弃，接口那边照样写完、照样计费，所以宁可多等：晚回来的结果照样落档，下一轮用上，不拖正文
  const WAIT = { person: 90000, scene: 90000, cold: 120000, redo: 120000 };
  const groupWait = (n) => Math.min(180000, 60000 + 20000 * n);
  function askSide(run, target, mode, schemaName, maxTokens, hardTimeout) {
    const mat = run.mat;
    const c = mat.c;
    const max = c.每场最多几人;
    const who = target || (mode === 'cold' ? '冷启动' : '场面');
    const po = promptOpt(mat, mode);
    const once = (lite, more) => callSide(systemFor(mode, max, po), buildUserContent(mat, target, mode, max, lite),
      schemaFor(mode, max, null, po), schemaName, { cfg: c, maxTokens: more ? biggerTokens(maxTokens) : maxTokens, hardTimeout: more ? hardTimeout * 2 : hardTimeout, priority: 'high',
        label: (target ? '记状态·' + target + (run.only ? '（单独重算）' : '') : (mode === 'cold' ? '冷启动' : '场面')) + (lite ? '（短材料）' : '') + (more ? '（加大字数）' : '') });
    return once(false).catch((e) => {
      if (e && e.truncated) {
        run.timings.push(who + ' 回答被截断，加大字数重发');
        return once(false, true);
      }
      if (!e || !e.filtered) throw e;
      run.timings.push(who + ' 被内容审查拦下，换短档案重试');
      return once(true).catch((e2) => {
        if (e2 && e2.filtered) e2.message = '被接口的内容审查拦下了，换短档案重试也没过';
        throw e2;
      });
    });
  }

  // ---------- 单独重算一个人（面板人物卡上的按钮） ----------
  // 只给她重发一次记状态（每人一次的写法，不管设置里选的是哪种），结果换进面板正在显示的那一楼；
  // 场面、别的人都不动。材料照那一楼当时的读法：玩家那一楼读到它之前、玩家这一轮是它的原话；「记到最新」那份读到它记的那段正文。
  // 判定：那一楼已经掷给了别人，这次不掷；原来掷给的就是她，照她这次写的重掷。压力、关系阶段按这一楼的人重新算一遍。
  const redoing = new Map();   // 名字 → 正在单独重算的运行对象
  // opt.add：此刻页「加上」的人，这一楼原来没有她（见 addPerson）
  async function redoPerson(name, opt) {
    const add = !!(opt && opt.add);
    if (redoing.has(name)) throw new Error('她正在重算');
    const store = loadStore();
    if (mutedNames(store).has(name)) throw new Error('已经删掉了');
    const was = latestState(store, null);
    if (!was || !was.people || (!add && !was.people[name])) throw new Error('面板上这一楼没有她的状态');
    const old = was.people[name] || null;
    const chat = chatNow();
    const m = chat[was.floor];
    if (!m || String(m.send_date || '') !== String(was.sd || '')) throw new Error('第 ' + was.floor + ' 楼已经不在了');
    const tail = !!was.tail;
    const input = tail ? '' : extractRawInput(m.mes);
    const upto = tail ? (was.readTo != null ? was.readTo + 1 : chat.length) : was.floor;
    const cast = (Array.isArray(was.order) ? was.order : Object.keys(was.people)).filter((n) => was.people[n]);
    if (cast.indexOf(name) === -1) cast.push(name);
    const run = {
      id: ++runSeq, input, upto, tail, startedAt: Date.now(), chatId: currentChatId(),
      floor: was.floor, sd: was.sd, mode: 'redo', only: name, add, mat: null,
      entries: {}, scene: was.scene || null, notes: [], timings: [], done: false, failed: 0,
    };
    const other = Object.keys(was.people).find((n) => n !== name && was.people[n] && was.people[n].check);
    if (other) run.check = { name: other, at: 0 };
    redoing.set(name, run);
    try {
      run.mat = await gather(input, upto, tail, { cast, noEncounter: true, arranged: old && old.arranged ? name : '' });
      const c = run.mat.c;
      if (!String(c.副API地址 || '').trim() || !String(c.副模型 || '').trim()) throw new Error('没有配置状态模型');
      const res = await askSide(run, name, 'person', 'handbook_person', 700, WAIT.redo);
      const raw = res.data || {};
      if (!raw || typeof raw !== 'object' || typeof raw.doing !== 'string' || !Array.isArray(raw.unsaid_candidates)) throw new Error('返回的结构不对');
      const out = processPerson(raw, envFor(run, name));
      if (out.rejected) throw new Error('像是空话（' + out.flags.join('、') + '）');
      out.entry.ms = res.ms;
      if (add || (old && old.added)) out.entry.added = true;      // 加上的人单独重算以后还是加上的，照样不占名额
      run.entries[name] = markArranged(run.mat, name, markWlog(run.mat, name, out.entry));
      maybeCheck(run, name);
      run.timings.push(name + (add ? '（加上）' : '（单独重算）') + res.ms + 'ms' + tokNote(res));
      return commitRedo(run, was);
    } finally {
      run.done = true;
      redoing.delete(name);
    }
  }

  function commitRedo(run, was) {
    if (DISPOSED || run.chatId !== currentChatId()) throw new Error('已经换了聊天');
    const store = loadStore();
    if (store.meta.resetAt && run.startedAt < store.meta.resetAt) throw new Error('这个聊天的状态清空过了');
    const st = store.floors[run.floor];
    if (!st || String(st.sd || '') !== String(run.sd || '') || st.runKey !== was.runKey) throw new Error('这一楼在重算期间又被记过一遍，这次的结果没写进去');
    const name = run.only;
    if (mutedNames(store).has(name)) throw new Error('重算期间被删掉了');
    if (run.add && st.people[name] && !st.people[name].added) throw new Error('这一楼重记的时候已经记上她了');
    // 整份沿用上一楼的那种：别的人其实是上一楼的，标成沿用，免得压力把上一楼的事再算一遍
    if (st.carried) {
      Object.keys(st.people).forEach((n) => {
        if (n !== name) st.people[n] = Object.assign({}, st.people[n], { carried: true, notes: [], check: null, foreshadow: null });
      });
      delete st.carried;
    }
    st.people[name] = run.entries[name];
    checkParallel(run.mat, run.scene, st.people, [name]);       // 场面用那一楼记下的
    if (!Array.isArray(st.order)) st.order = Object.keys(st.people);
    if (st.order.indexOf(name) === -1) st.order.push(name);
    st.notes = (st.notes || []).concat([name + (run.add ? '：手动加上' : '：单独重算过')]).slice(-20);
    st.timings = (st.timings || []).concat(run.timings);
    let base = statesBefore(store, run.floor, 1)[0];
    if (!base && !st.tail) base = statesBefore(store, run.floor, 1, true)[0] || null;
    markRepeat(st, base);
    if (run.mat.stable) {
      st.stable = true;
      st.chars = cloneChars(base && base.chars ? base.chars : {});
      if (st.people[name].persona) st.people[name] = Object.assign({}, st.people[name], { persona: '' });
    } else {
      st.chars = stepChars(base && base.chars ? base.chars : {}, st.people, run.floor, run.mat.c);
      settlePersona(st, base, run.mat.c);
    }
    store.floors[run.floor] = st;
    if (Object.keys(store.floors).some((k) => Number(k) > run.floor)) refoldChars(store, run.floor + 1, run.mat.c);
    if (!st.tail && !run.mat.stable) stepHidden(store, st, run);     // 这一楼的暗骰已经掷过就不再掷；浮出来的伏笔照样挂回她身上
    saveStore(store);
    reinject();
    BUS.emit('state', st);
    scheduleBookWrite();
    return st;
  }

  function recentText(mat) {
    return mat.story.items.filter((x) => x.who === '正文').slice(-1).map((x) => x.text).join('\n');
  }

  // tail：「记到最新」——最新一楼是正文时点重算，读到这段正文为止、挂在它上面（见 17_boot.js 的 onRerun）
  function startRun(input, upto, tail) {
    const run = {
      id: ++runSeq, input, upto, tail: !!tail, startedAt: Date.now(), chatId: currentChatId(),
      floor: null, sd: null, mode: null, mat: null,
      entries: {}, scene: null, notes: [], timings: [], done: false, failed: 0,
    };
    const tick = () => BUS.emit('progress', run);
    // 面板上「正在记这一轮（几/几）」：按发出去的路数和回来的路数算（重发、换短材料不算一路）
    const oneDone = () => { run.jobsDone = (run.jobsDone || 0) + 1; tick(); };
    const fail = (label, t0, e) => {
      run.failed += 1;
      run.notes.push(label + '：' + e.message);
      run.timings.push(label + ' ✗ ' + (Date.now() - t0) + 'ms');
    };
    inflight.add(run);
    run.ready = (async () => {
      const mat = await gather(input, upto, tail);
      run.mat = mat;
      run.gatherMs = Date.now() - run.startedAt;       // 读名册、世界书、数据库、最近正文花的时间
      const c = mat.c;
      if (!String(c.副API地址 || '').trim() || !String(c.副模型 || '').trim()) {
        run.notes.push('没有配置状态模型，这一轮不记状态');
        return;
      }
      if (sideUnset(c)) {                          // 没填密钥、接口还是默认的火山方舟：不发（见 02_config.js）
        run.notes.push('出错：' + UNSET_MSG);
        return;
      }
      const max = c.每场最多几人;
      const jobs = [];
      const ask = (target, mode, schemaName, maxTokens, hardTimeout) => askSide(run, target, mode, schemaName, maxTokens, hardTimeout);
      const bigger = biggerTokens;
      const askGroup = (names, split, maxTokens, hardTimeout) => {
        const po = promptOpt(mat, 'group');
        const once = (lite, more) => callSide(systemFor('group', max, po), buildUserContent(mat, null, 'group', max, lite, names),
          schemaFor('group', max, names, po), 'handbook_group', { cfg: c, maxTokens: more ? bigger(maxTokens) : maxTokens, hardTimeout: more ? Math.min(300000, hardTimeout * 2) : hardTimeout, priority: 'high',
            label: '记状态·全场' + (split ? '（' + names.join('、') + '）' : '') + (lite ? '（短材料）' : '') + (more ? '（加大字数）' : '') });
        // 一次调用管一场人：回来的 JSON 坏了（半截、引号没合上）就整场都没记上，所以这种情况重发一次
        const badJson = (e) => e && !e.filtered && !e.rateLimit && (e.name === 'SyntaxError' || /不是 JSON|JSON/.test(String(e.message || '')));
        return once(false).catch((e) => {
          if (e && e.truncated) {
            run.timings.push('全场 回答被截断，加大字数重发');
            return once(false, true);
          }
          if (badJson(e)) {
            run.timings.push('全场 回的 JSON 不完整，重发一次');
            return once(false);
          }
          if (!e || !e.filtered) throw e;
          run.timings.push('全场 被内容审查拦下，换短档案重试');
          return once(true).catch((e2) => {
            if (e2 && e2.filtered) e2.message = '被接口的内容审查拦下了，换短档案重试也没过';
            throw e2;
          });
        });
      };
      const t0 = Date.now();
      // 平行线事件的下回合推演没变的人不重记，落档时沿用上一楼（见 keepWlog）
      run.kept = new Set(mat.cast.filter((n) => keepWlog(mat, n)));
      if (run.kept.size) run.timings.push(Array.from(run.kept).join('、') + ' 平行线推演没变，沿用上一轮');
      if (!mat.cast.length) {
        run.mode = 'cold';
        jobs.push(ask(null, 'cold', 'handbook_cold', 700 * max, WAIT.cold)
          .then((res) => onCold(run, res))
          .catch((e) => fail('冷启动', t0, e))
          .finally(oneDone));
      } else if (c.记状态的方式 === '一次记全场') {
        // 每个人放进一次调用，规则和共用的材料只发一遍；场面照旧单独一次（真模型盲评：场面和人挤在一次里明显记得差）
        run.mode = 'group';
        jobs.push(ask(null, 'scene', 'handbook_scene', 600, WAIT.scene)
          .then((res) => onScene(run, res))
          .catch((e) => fail('场面', t0, e))
          .finally(oneDone));
        // 一次最多写 GROUP_MAX 个人：人多时后面的人分到的注意力少，逐人比略逊。人多就拆成几次，每次人数尽量平均
        const groups = splitGroups(mat.cast.filter((n) => mat.roster.people.has(n) && !run.kept.has(n)));
        groups.forEach((names) => {
          const n = names.length;
          jobs.push(askGroup(names, groups.length > 1, 900 * n + 600, groupWait(n))
            .then((res) => onGroup(run, res, names))
            .catch((e) => fail(groups.length > 1 ? names.join('、') : '全场', t0, e))
            .finally(oneDone));
        });
      } else {
        run.mode = 'cast';
        jobs.push(ask(null, 'scene', 'handbook_scene', 600, WAIT.scene)
          .then((res) => onScene(run, res))
          .catch((e) => fail('场面', t0, e))
          .finally(oneDone));
        mat.cast.filter((name) => !run.kept.has(name)).forEach((name) => {
          jobs.push(ask(name, 'person', 'handbook_person', 700, WAIT.person)
            .then((res) => onPerson(run, name, res))
            .catch((e) => fail(name, t0, e))
            .finally(oneDone));
        });
      }
      run.jobsTotal = jobs.length;
      await Promise.all(jobs);
    })().catch((e) => {
      run.notes.push('出错：' + (e && e.message ? e.message : e));
      warn(e);
    }).finally(() => {
      run.done = true;
      run.doneAt = Date.now();
      inflight.delete(run);
      if (DISPOSED) return;
      if (run.floor == null) relocate(run);             // 记完了还没认到楼：在聊天里找那句（见 17_boot.js）
      if (run.floor != null) commit(run);
      BUS.emit('run-end', run);
      log('第 ' + run.id + ' 轮记状态结束：' + (run.timings.join('，') || '没有调用') +
        (run.notes.length ? '｜' + run.notes.join('；') : ''));
    });
    lastRun = run;
    BUS.emit('run', run);
    return run;
  }

  function tokNote(res) {
    const u = res && res.usage;
    return u && u.completion_tokens ? '/' + u.completion_tokens + 'tok' : '';
  }

  // near：这一场可能在场的人（脚本认出来的、不在平行线上的，加上场面那一路已经回来时它写的在场），隐言对象按它把关。
  // extra：冷启动时模型自己找出来的那几个人
  function envFor(run, name, extra) {
    const mat = run.mat;
    const near = (mat.ranked || []).slice(0, mat.c.每场最多几人).filter((x) => !x.parallel).map((x) => x.name)
      .concat((run.scene && run.scene.present) || [], extra || []);
    const known = (mat.roster.people ? Array.from(mat.roster.people.keys()) : []).concat(Object.keys(mat.roster.alias || {}));
    return { name, input: run.input, recent: recentText(mat), history: mat.history, alias: mat.roster.alias, player: mat.persona.name, near, known };
  }

  function onScene(run, res) {
    const raw = (res.data || {}).scene;
    const sc = processScene(raw, run.mat.persona.name, run.mat.encounter);
    if (sc) { run.scene = sc; run.ledgerRaw = ledgerOf(raw); }
    else run.notes.push('场面：返回的结构不对，沿用上一轮');
    run.timings.push('场面 ' + res.ms + 'ms' + tokNote(res));
    if (run.floor != null) commit(run);
  }

  function onPerson(run, name, res) {
    const raw = res.data || {};
    if (!raw || typeof raw !== 'object' || typeof raw.doing !== 'string' || !Array.isArray(raw.unsaid_candidates)) {
      run.notes.push(name + '：返回的结构不对，沿用上一轮');
      run.timings.push(name + ' ? ' + res.ms + 'ms');
      return;
    }
    const out = processPerson(raw, envFor(run, name));
    if (out.rejected) {
      run.notes.push(name + '：像是空话（' + out.flags.join('、') + '），沿用上一轮');
      run.timings.push(name + ' ✗ ' + res.ms + 'ms');
    } else {
      out.entry.ms = res.ms;
      run.entries[name] = markArranged(run.mat, name, markWlog(run.mat, name, out.entry));
      maybeCheck(run, name);
      run.timings.push(name + ' ' + res.ms + 'ms' + tokNote(res));
    }
    if (run.floor != null) commit(run);
  }

  function onCold(run, res) {
    const data = res.data || {};
    const sc = processScene(data.scene, run.mat.persona.name);
    if (sc) { run.scene = sc; run.ledgerRaw = ledgerOf(data.scene); }
    const list = Array.isArray(data.people) ? data.people.slice(0, run.mat.c.每场最多几人) : [];
    const found = list.map((raw) => String((raw && raw.name) || '').trim()).filter(Boolean);
    list.forEach((raw) => {
      const name = String((raw && raw.name) || '').trim();
      if (!name || sameName(name, run.mat.persona.name) || typeof raw.doing !== 'string' || run.mat.muted.has(name)) return;
      const out = processPerson(raw, envFor(run, name, found));
      if (out.rejected) run.notes.push(name + '：像是空话（' + out.flags.join('、') + '）');
      else { out.entry.ms = res.ms; run.entries[name] = out.entry; maybeCheck(run, name); }
    });
    run.timings.push('冷启动 ' + res.ms + 'ms' + tokNote(res) + '（' + Object.keys(run.entries).join('、') + '）');
    if (run.floor != null) commit(run);
  }

  // 一次记全场：名单上每个人（场面另外一次）。名单外的名字不收；缺了的人沿用上一轮
  // 判定：一场最多掷一次。先回来、写了判定、在玩家这一场里的那个人就是这一场掷的；记到最新（tail）不掷，免得同一场掷两次
  function maybeCheck(run, name) {
    if (run.check || run.tail) return;
    const e = run.entries[name];
    if (!e || !e.checkRaw || e.inScene === false) return;
    const ch = (run.mat.chars || {})[name];
    const prev = run.mat.prev;
    const prevExtreme = !!(prev && prev.people && Object.keys(prev.people).some((n) => prev.people[n] && prev.people[n].check && prev.people[n].check.band === '夸张'));
    // 场面那一路还没回来时按脚本认出的这一场的人算，平行线上的人不算旁观者
    const present = (run.scene && run.scene.present) ||
      (run.mat.ranked || []).filter((x) => !x.parallel && (run.mat.cast || []).indexOf(x.name) !== -1).map((x) => x.name);
    // 稳定人设不算压力：一律按平稳掷
    e.check = rollCheck(e.checkRaw, { level: ch && !run.mat.stable ? ch.level : '平稳', onlookers: present.filter((n) => n !== name).length, prevExtreme });
    run.check = { name, at: Date.now() };
  }

  // 全暗骰（内容规划书 3.3c）：她紧张或崩溃、身边还有别的角色时，脚本掷一次「那个人看没看出来她在忍着」。
  // 结果只存在 meta.hidden，不告诉正文模型，面板也不显示。看出来的那一条，等到下面任一条才浮出来（写进她的「伏笔」）：
  //   她又紧张或崩溃、而且那个人在场；玩家这一轮点了她的名、说到她在忍；过了 HIDDEN_WAIT 楼、那个人在场。
  // 没看出来的，过了 HIDDEN_WAIT 楼就删。看的人按关系排：挚友、情侣、夫妻最容易看出来
  const HIDDEN_WAIT = 8;
  const HIDDEN_MAX = 20;
  const HIDDEN_STAGE = { 挚友: 20, 情侣: 20, 夫妻: 20, 在意的人: 10 };
  const POKE = /忍|撑|逞强|装作|假装|没事吧|看得出|看出来/;
  function stepHidden(store, st, run) {
    const list = Array.isArray(store.meta.hidden) ? store.meta.hidden.filter((h) => h) : [];
    const here = (n) => st.people[n] && st.people[n].inScene !== false && !st.people[n].parallel;
    const names = Object.keys(st.people).filter(here);
    const lv = (n) => (st.chars && st.chars[n] && st.chars[n].level) || '平稳';
    const alias = (run.mat.roster && run.mat.roster.alias) || {};
    const named = (n) => { const input = String(run.input || ''); return input.indexOf(n) !== -1 || Object.keys(alias).some((a) => alias[a] === n && a.length >= 1 && input.indexOf(a) !== -1); };
    list.forEach((h) => {
      if (!h.seen || h.floor >= st.floor || (h.revealed && h.revealed !== st.floor)) return;
      if (!here(h.who) || !here(h.by)) return;
      let why = h.why || '';
      if (!h.revealed) {
        if (lv(h.who) !== '平稳') why = '她又在忍';
        else if (named(h.who) && POKE.test(String(run.input || ''))) why = '玩家说破了';
        else if (st.floor - h.floor >= HIDDEN_WAIT) why = '过了几场';
        else return;
        h.revealed = st.floor;
        h.why = why;
      }
      st.people[h.who] = Object.assign({}, st.people[h.who], { foreshadow: { by: h.by, floor: h.floor, why } });
    });
    if (!list.some((h) => h.floor === st.floor)) {
      const who = names.find((n) => lv(n) !== '平稳' && names.some((o) => o !== n));
      if (who) {
        const stageOf = (o) => ((st.chars && st.chars[o] && st.chars[o].rel && st.chars[o].rel[who]) || {}).stage || '';
        const by = names.filter((o) => o !== who).sort((a, b) => (HIDDEN_STAGE[stageOf(b)] || 0) - (HIDDEN_STAGE[stageOf(a)] || 0))[0];
        if (by && !list.some((h) => !h.revealed && h.who === who && h.by === by)) {
          const T = Math.min(90, 30 + (HIDDEN_STAGE[stageOf(by)] || 0) + (lv(who) === '崩溃' ? 20 : 0));
          const roll = Math.floor(randomUnit() * 100) + 1;
          list.push({ floor: st.floor, sd: String(st.sd || ''), who, by, T, roll, seen: roll <= T, revealed: 0 });
        }
      }
    }
    store.meta.hidden = list.filter((h) => h.revealed || h.seen || st.floor - h.floor < HIDDEN_WAIT).slice(-HIDDEN_MAX);
  }

  const GROUP_MAX = 3;
  function splitGroups(names) {
    const k = Math.max(1, Math.ceil(names.length / GROUP_MAX));
    const out = [];
    let from = 0;
    for (let i = 0; i < k; i += 1) {
      const size = Math.floor(names.length / k) + (i < names.length % k ? 1 : 0);
      out.push(names.slice(from, from + size));
      from += size;
    }
    return out.filter((g) => g.length);
  }

  // names：这一次要写的那几个人（拆成几次时是其中一组）
  function onGroup(run, res, names) {
    const who = names || run.mat.cast;
    const data = res.data || {};
    const list = Array.isArray(data.people) ? data.people : [];
    const got = [];
    list.forEach((raw) => {
      const name = String((raw && raw.name) || '').trim();
      if (!name || who.indexOf(name) === -1 || run.entries[name]) return;
      if (typeof raw.doing !== 'string' || !Array.isArray(raw.unsaid_candidates)) {
        run.notes.push(name + '：返回的结构不对，沿用上一轮');
        return;
      }
      const out = processPerson(raw, envFor(run, name));
      if (out.rejected) run.notes.push(name + '：像是空话（' + out.flags.join('、') + '），沿用上一轮');
      else { out.entry.ms = res.ms; run.entries[name] = markArranged(run.mat, name, markWlog(run.mat, name, out.entry)); got.push(name); maybeCheck(run, name); }
    });
    const miss = who.filter((n) => !run.entries[n] && got.indexOf(n) === -1 && !run.notes.some((x) => x.indexOf(n + '：') === 0));
    if (miss.length) run.notes.push(miss.join('、') + '：这一次没记到，沿用上一轮');
    run.timings.push('全场 ' + res.ms + 'ms' + tokNote(res) + '（' + got.join('、') + '）');
    if (run.floor != null) commit(run);
  }

  // 把这一轮已经回来的结果拼成一份状态、存档、注入。可以反复调用：每回来一个人就拼一次。
  // 出错只记日志：它会在酒馆等待的监听器里被调用，不能把异常抛回去。
  function commit(run) {
    try { commitInner(run); } catch (e) { warn('落档失败：', e); }
  }

  function commitInner(run) {
    if (DISPOSED || run.floor == null || !run.mat) return;
    if (run.chatId !== currentChatId()) return;                          // 已经切到别的聊天了
    const chat = chatNow();
    let m = chat[run.floor];
    if (!m || String(m.send_date || '') !== String(run.sd || '')) {
      // 那条消息不在了：被删掉重发的（同一句话又落在后面），改挂到新的那条；真删了就不写
      if (!relocate(run)) { run.dropped = run.tail ? '那段正文换过了' : '玩家那条消息已经不在了'; return; }
      m = chat[run.floor];
    }

    const store = loadStore();
    // 开跑以后玩家清空过这个聊天的状态：这一轮作废
    if (store.meta.resetAt && run.startedAt < store.meta.resetAt) { run.dropped = '这个聊天的状态清空过了'; return; }
    const first = !Object.keys(store.floors).length;   // 这个聊天的第一份状态：落档后再在后台识别性格模板
    // 这一楼已经有更晚开跑的一轮落过档（同一句被记了两轮时），早的这一轮不盖它
    const had = store.floors[run.floor];
    if (had && had.runAt > run.startedAt && String(had.sd || '') === String(run.sd || '')) { run.dropped = '这一楼已经有更新的一轮记过了'; return; }

    const prev = run.mat.prev;
    const muted = mutedNames(store);                  // 这一轮在路上时才删掉的人，落档时也跳过
    const st = {
      floor: run.floor, sd: run.sd, at: Date.now(), mode: run.mode, tail: run.tail || undefined,
      runAt: run.startedAt, runKey: runKey(run),             // 哪一轮记的（轮次编号每次重载从 1 数起，所以带上开跑时间）
      readTo: run.upto - 1,                                  // 材料读到第几楼（面板上说）
      scene: run.scene || (prev && prev.scene ? Object.assign({}, prev.scene, { encounter: '' }) : null),   // 沿用上一场时，偶遇不跟着沿用
      sceneFresh: !!run.scene,
      people: {}, order: [],
      notes: run.notes.slice(-20), timings: run.timings.slice(),
    };
    const names = (run.mode === 'cold' ? Object.keys(run.entries) : run.mat.cast).filter((n) => !muted.has(n));
    names.forEach((n) => {
      if (run.entries[n]) {
        st.people[n] = (run.mat.added || []).indexOf(n) !== -1 ? Object.assign({}, run.entries[n], { added: true }) : run.entries[n];
        st.order.push(n);
      } else if (prev && prev.people && prev.people[n]) {
        // 平行线事件推演没变、特意不重记的（run.kept）标 kept，状态条不当成没算出来
        const kept = !!(run.kept && run.kept.has(n));
        st.people[n] = Object.assign({}, prev.people[n], { carried: true, kept: kept || undefined, notes: kept ? [WLOG_KEPT] : [], check: null, foreshadow: null });
        st.order.push(n);
      }
    });
    if (!st.order.length) {
      if (!prev) return;                                  // 什么都没有，就不存一份空的
      st.people = Object.assign({}, prev.people);
      muted.forEach((n) => { delete st.people[n]; });
      st.order = (Array.isArray(prev.order) ? prev.order : Object.keys(st.people)).filter((n) => st.people[n]);
      st.carried = true;
    }
    // 每回来一路都重拼一次：场面那一路晚到时，它写的平行线在这里补上凭据
    checkParallel(run.mat, run.scene, st.people);
    arrangeParallel(st, run.mat);
    st.scene = withWlogLines(sceneWithout(st.scene, muted, run.mat.roster && run.mat.roster.alias), run.mat, st.people);

    // 压力和关系阶段：上一楼（按落档时的存档取，不用开跑时的快照）加这一楼新报的事。
    // 整份沿用上一楼时没有新事，只自然回落，免得同一件事算两遍。
    // 还没有正式的状态（新聊天、只在开场白上点过重算）时，拿「记到最新」那份当底，免得在它上面做的手改丢了。
    // 这一轮第一次落档就会把那份清掉，所以第一次找到的底记在这一轮上，后面每回来一路都用它
    let base = statesBefore(store, run.floor, 1)[0];
    if (!base && !run.tail) {
      if (run.tailBase === undefined) run.tailBase = statesBefore(store, run.floor, 1, true)[0] || null;
      base = run.tailBase;
    }
    markRepeat(st, base);
    // 稳定人设：压力、关系阶段停在上一楼（冻住，切回动态接着算），另一个人格不出来；暗骰不掷
    const stable = !!run.mat.stable;
    if (stable) {
      st.stable = true;
      st.chars = cloneChars(base && base.chars ? base.chars : {});
      Object.keys(st.people).forEach((n) => { if (st.people[n] && st.people[n].persona) st.people[n] = Object.assign({}, st.people[n], { persona: '' }); });
    } else {
      st.chars = stepChars(base && base.chars ? base.chars : {}, st.carried ? {} : st.people, run.floor, run.mat.c);
      settlePersona(st, base, run.mat.c);    // 另一个人格只在崩溃时出来，压力回到平稳或关掉「允许崩溃」就回去
    }
    // 约定和事件：手账本自己记的（稳定人设、没有数据库的表）在上一楼的基础上加这一楼场面那一路交回来的；别的时候照上一楼带着
    if (run.mat.ledgerSelf) {
      st.ledgerRaw = run.ledgerRaw || null;
      st.ledger = stepLedger(base && base.ledger, st.ledgerRaw, run.floor, run.mat.roster && run.mat.roster.alias, run.mat.persona.name);
    } else if (base && base.ledger) {
      st.ledger = base.ledger;
    }
    store.floors[run.floor] = st;
    // 后面已经有楼层落档（这一楼的状态晚到了）：顺着重算一遍
    const later = Object.keys(store.floors).some((k) => Number(k) > run.floor);
    if (later) refoldChars(store, run.floor + 1, run.mat.c);
    if (run.impact) store.meta.lastImpact = run.floor;
    if (run.scene && run.scene.mood && !run.tail) recordMood(store, run.floor, run.sd, run.scene.mood);
    if (!run.tail && !st.carried && !stable) stepHidden(store, st, run);
    saveStore(store);
    // 重新挑一遍再注入：重新生成、换一条 swipe 时不能用「记到最新」那份，它晚到的结果也不能直接塞进去
    if (run.floor >= latestUserFloor() || later) reinject();
    run.committed = st;
    BUS.emit('state', st);
    scheduleBookWrite();                  // 状态可能在玩家那条落楼之前就记完了，所以挂在落档上，不挂在跑完上
    if (first) scheduleAutoIdentify();    // 打开聊天时没识别（那时还没记过状态），现在补上
  }

  // 此刻页「加上」：这一楼漏记的人（多半是「每一场最多记几个人」满了），填名字只给她记这一楼，同单独重算；
  // 不占名额，重算这一楼时留着，下一轮照常挑
  async function addPerson(text) {
    const raw = String(text || '').trim();
    if (!raw) throw new Error('没填名字');
    const roster = _rosterFull || await buildRoster(false);
    const name = (roster && roster.alias && roster.alias[raw]) || raw;
    const player = readPersona().name;
    if (player && sameName(name, player)) throw new Error('这是玩家扮演的人');
    const store = loadStore();
    if (mutedNames(store).has(name)) throw new Error(name + '在「不记的人」里，先在设置里点「恢复」');
    const was = latestState(store, null);
    if (!was) throw new Error('还没有记好的一楼');
    if (was.people && was.people[name]) throw new Error(name + '这一楼记过了，要重记点她卡片上的「单独重算」');
    return redoPerson(name, { add: true });
  }

  // 设置「高级」→「清空这个聊天的状态」：各楼的状态、压力、关系、暗骰、氛围轨迹都清掉，聊天世界书里的「手账本-」条目删掉；
  // 性格（稳定 / 动态）、不记的人、补充留着。还在路上的那几轮落档时认 meta.resetAt，不写回来
  async function resetChat() {
    const chatId = currentChatId();
    const store = loadStore();
    const meta = { resetAt: Date.now() };
    ['mode', 'muted', 'notes', 'periods'].forEach((k) => { if (store.meta[k] !== undefined) meta[k] = store.meta[k]; });
    forgetShadow();
    saveStore({ v: store.v || 1, floors: {}, meta });
    pendingRun = null;
    lastRun = null;
    cancelBookWrite();
    clearInjection();
    BUS.emit('state', null);
    const removed = await queueBookJob(removeBookEntries);
    return { removed: chatId === currentChatId() ? Number(removed) || 0 : 0 };
  }

  // ---------- 冲击轮：这一轮值不值得等 ----------
  // 强：肢体接触、表白、决裂——单独出现就值得等；弱：离场、道歉、揭底——要再凑一条
  const ACTION_STRONG = /抱|吻|亲|扇|踢|推开|拽|拉住|抓住|握住|牵|告白|表白|喜欢你|爱你|分手|跪|摔|砸|撕/;
  const ACTION_WEAK = /离开|走了|转身|哭|逃|跑开|再见|对不起|道歉|死|血|受伤|秘密|真相|其实|原来/;

  function impactScore(input, roster) {
    const t = String(input || '');
    let s = 0;
    const len = norm(t).length;
    if (len >= 40) s += 0.5;
    if (len >= 120) s += 1;
    if (/[!！]/.test(t)) s += 1;
    if (/[?？]/.test(t)) s += 0.5;
    if (ACTION_STRONG.test(t)) s += 2;
    else if (ACTION_WEAK.test(t)) s += 1;
    // 直接冲着某个角色说话 / 动手，算一分（单字名要前后不挨汉字才算，免得「和睦」也中）
    if (roster && Object.keys(roster.alias || {}).some((a) => countMentions(t, a, true) > 0)) s += 1;
    return s;
  }

  // 返回要等的毫秒数；0 = 不等
  function waitBudget(run, c) {
    if (c.阻塞方式 === '从不') return 0;
    const store = loadStore();
    const hasState = !!latestState(store, run.floor);
    if (!hasState) return c.冷启动阻塞上限毫秒;          // 还没有任何状态：第一轮必须等
    if (c.阻塞方式 === '每轮') return c.阻塞上限毫秒;
    const since = store.meta.lastImpact == null ? 99 : (run.floor - store.meta.lastImpact) / 2;
    const score = impactScore(run.input, _roster) + (since >= 6 ? 1 : 0);
    run.impactScore = score;
    return score >= 2 ? c.阻塞上限毫秒 : 0;
  }

  // ======================== 性格模板 ========================
  // 咩咩的「acg 角色心理模型」世界书：每本手册包在 <acg_archetype: 名字> 里，
  // 分【本质】【关系光谱】【破防】等几段。不用挂：这里按名字直接读，要点抄进这个聊天的「手账本-名字」条目。
  // 用户自己挂上了（全局、角色卡或聊天），就在正文生成时直接激活在场的人对应的那几本（见 forceEntries），
  // 不往扫描文本里塞 <acg_think>，也不在别的插件调模型时激活。
  // 模板是「这类人一般怎么演」，角色卡是「她这一个人」：两边冲突听卡。

  // 关系阶段的台阶，从远到近；「讨厌的人」在最底下。
  const STAGES = ['讨厌的人', '陌生人', '普通朋友', '在意的人', '挚友', '情侣', '夫妻'];
  const AUTO_STAGE_CAP = '挚友';            // 攒着挪最多挪到这一格；情侣、夫妻靠契约事件或手动定
  // 契约事件（成为情侣、夫妻，结束这两种关系，决裂、和好）只管进出这几格；情侣、夫妻只靠契约事件或手动变，攒着挪不动
  const CONTRACT_STAGES = ['讨厌的人', '情侣', '夫妻'];
  const CONTRACT_ONLY = ['情侣', '夫妻'];

  // 模板里的光谱标签写法不一（「本能排斥」「普通朋友/同学」「大多数人」），归到上面的台阶
  function canonStage(label) {
    const s = String(label || '').trim();
    if (!s) return null;
    if (STAGES.indexOf(s) !== -1) return s;
    if (/讨厌|排斥|厌恶|敌人|威胁|对手|伤害过/.test(s)) return '讨厌的人';
    if (/夫妻|伴侣|配偶/.test(s)) return '夫妻';
    if (/情侣|恋人|恋爱/.test(s)) return '情侣';
    if (/挚友|死党|至交/.test(s)) return '挚友';
    if (/在意|重要的人/.test(s)) return '在意的人';
    if (/朋友|同学|部下|同事|熟人|同伴|伙伴/.test(s)) return '普通朋友';
    if (/陌生|大多数|其他人|路人|无聊|无关|普通人/.test(s)) return '陌生人';
    return null;
  }

  function stageIndex(s) { return STAGES.indexOf(s); }

  // 世界书条目 → { name, kind, enabled, sections, spectrum, body }；不是模板返回 null
  function parseTemplate(e) {
    const content = String((e && e.content) || '');
    const m = content.match(/<acg_archetype:\s*([^>]+?)\s*>/);
    if (!m) return null;
    const kind = m[1].trim();
    const body = content.replace(/<\/?acg_archetype:[^>]*>/g, '').trim();
    const heads = [];
    const re = /【([^】]+)】/g;
    let x;
    while ((x = re.exec(body))) heads.push({ title: x[1], at: x.index, end: re.lastIndex });
    const sections = {};
    heads.forEach((h, i) => {
      const key = h.title.split(/——|—/)[0].trim();          // 「破防——微观地震」→「破防」
      const text = body.slice(h.end, i + 1 < heads.length ? heads[i + 1].at : body.length).trim();
      if (key && !sections[key]) sections[key] = text;
    });
    const spectrum = [];
    String(sections['关系光谱'] || '').split('\n').forEach((line) => {
      const mm = line.match(/^\s*[-·•]\s*([^→\n]{1,16}?)\s*→\s*(.+)$/);
      if (mm) spectrum.push({ label: mm[1].trim(), stage: canonStage(mm[1]), text: mm[2].trim() });
    });
    return { name: String((e && e.name) || kind).trim(), kind, enabled: !(e && e.enabled === false), sections, spectrum, body };
  }

  let _tpl = null;                          // { book, list, at, error }
  const TPL_TTL = 10 * 60 * 1000;

  // 没填世界书名时：先看挂在全局的（咩咩的心理模型一般挂全局），再看名字像的，再挨个看有没有 <acg_archetype:
  async function findTemplateBook() {
    let names = [];
    let globals = [];
    try { names = typeof getWorldbookNames === 'function' ? (getWorldbookNames() || []) : []; } catch (e) { names = []; }
    try { globals = typeof getGlobalWorldbookNames === 'function' ? (getGlobalWorldbookNames() || []) : []; } catch (e) { globals = []; }
    const likely = names.filter((n) => /心理模型|acg/i.test(n));
    const order = globals.concat(likely, names).filter((n, i, a) => n && a.indexOf(n) === i).slice(0, 40);
    for (const n of order) {
      try {
        const entries = await getWorldbook(n);
        if (Array.isArray(entries) && entries.some((e) => /<acg_archetype:/.test(String(e.content || '')))) return n;
      } catch (e) { /* 读不到就跳过 */ }
    }
    return '';
  }

  async function loadTemplates(force) {
    const c = cfg();
    if (!force && _tpl && (Date.now() - _tpl.at) < TPL_TTL && (!c.性格模板世界书 || _tpl.book === c.性格模板世界书)) return _tpl;
    const book = c.性格模板世界书 || await findTemplateBook();
    if (!book) {
      _tpl = { book: '', list: [], at: Date.now(), error: '没找到性格模板世界书。先把咩咩的 acg 角色心理模型导进酒馆。' };
      return _tpl;
    }
    let entries = [];
    try {
      entries = await getWorldbook(book);
    } catch (e) {
      _tpl = { book, list: [], at: Date.now(), error: '读不到世界书「' + book + '」，检查名字有没有写错。' };
      return _tpl;
    }
    const list = (Array.isArray(entries) ? entries : []).map(parseTemplate).filter(Boolean);
    _tpl = { book, list, at: Date.now(), error: list.length ? '' : '世界书「' + book + '」里没有性格模板。' };
    return _tpl;
  }

  // 卡里「性格标签：三无、弱气、沉重」→ 名字对得上的模板；同名的几本（三无有两个版本）先挑开着的
  function suggestTemplates(profile, list) {
    const m = String(profile || '').match(/性格标签\s*[:：]\s*([^\n]+)/);
    if (!m) return [];
    const out = [];
    m[1].split(/[、，,／/\s]+/).map((s) => s.trim()).filter(Boolean).forEach((tag) => {
      const hits = list.filter((t) => t.kind === tag || t.name === tag);
      const pick = hits.find((t) => t.enabled) || hits[0];
      if (pick && out.indexOf(pick.name) === -1) out.push(pick.name);
    });
    return out.slice(0, 3);
  }

  // 这个人用哪几本，按先后：设置里手选的（选空 = 不用）→ 卡里的「性格标签」→ 副模型自动识别的
  function templatesFor(name, profile, c, tpl) {
    return templateSource(name, profile, c, tpl).list;
  }

  // { from: 手选 / 性格标签 / 自动识别 / 识别中 / 等识别 / 没识别成 / 档案太短 / 没有模板, list }
  function templateSource(name, profile, c, tpl) {
    if (!tpl || !tpl.list.length) return { from: '没有模板', list: [] };
    // 同名的几本（有人把同一本导了两次）先挑开着的
    const byName = (n) => { const hits = tpl.list.filter((t) => t.name === n); return hits.find((t) => t.enabled) || hits[0]; };
    const pick = (names) => names.map(byName).filter(Boolean).slice(0, 3);
    const manual = manualPicks(name, profile);
    if (manual) return { from: '手选', list: pick(manual) };
    const tagged = suggestTemplates(profile, tpl.list);
    if (tagged.length) return { from: '性格标签', list: pick(tagged) };
    const key = identifyKey(name, profile, tpl);
    const rec = tplStore().recs[key];
    if (rec) return { from: '自动识别', list: pick(rec.picks) };
    if (_identifying.has(key)) return { from: '识别中', list: [] };
    if (!tpl.list.some((t) => t.enabled)) return { from: '没有模板', list: [] };
    if (!canIdentify(profile)) return { from: '档案太短', list: [] };
    if (_identifyFailed.has(key)) return { from: '没识别成', list: [] };
    return { from: '等识别', list: [] };
  }

  // ---------- 手选和自动识别的记录 ----------
  // 都存在全局变量 dyn_hb_tpl 里（不放脚本变量：脚本变量会跟着导出的脚本走）：
  //   manual：{ 「名字#档案指纹」: [模板名] }——按档案认人，别的卡里的同名角色不会沾上
  //   recs：自动识别的结果，按「名字 + 档案 + 模板书」认；换聊天、重开酒馆都不用再问，档案或模板书变了才重新识别
  const TPL_AUTO_NS = 'dyn_hb_tpl';
  // 一次问几个人。一批里有一份档案踩了内容审查，整批都得换短档案重来，所以不往大调
  const IDENTIFY_BATCH = 6;
  const IDENTIFY_MIN_PROFILE = 40;          // 档案短于这个字数就不识别
  const IDENTIFY_KEEP = 400;                // 全局变量里最多记多少人
  const MANUAL_KEEP = 200;                  // 手选最多记多少条；档案改过字，旧的那条就再也用不上了，满了从最早的删
  const _identifying = new Map();           // key → 这一次识别的 Promise（同一个人同时只问一次）
  const _identifyFailed = new Set();        // 这个聊天里识别失败过的 key（档案被审查拦下、模型没给结果），换聊天前不再自动问
  // 连不上状态模型（没填密钥、密钥不对、超时……）：不算谁没识别成，先停下别反复问。
  // 换聊天、换密钥、测试连接连上、点「重新识别」时清掉
  let _identifyBlocked = null;              // { why, at }

  function hashStr(s) {
    let h = 0x811c9dc5;
    const t = String(s || '');
    for (let i = 0; i < t.length; i += 1) { h ^= t.charCodeAt(i); h = Math.imul(h, 0x01000193) >>> 0; }
    return h.toString(36);
  }

  function identifyKey(name, profile, tpl) {
    if (!tpl._sig) tpl._sig = hashStr(tpl.book + '|' + tpl.list.filter((t) => t.enabled).map((t) => t.name).join('、'));
    return name + '#' + tpl._sig + hashStr(profile);
  }

  function tplStore() {
    let v = null;
    try { v = (getVariables({ type: 'global' }) || {})[TPL_AUTO_NS]; } catch (e) { v = null; }
    const ok = (x) => (x && typeof x === 'object' && !Array.isArray(x) ? x : {});
    return { recs: ok(v && v.recs), manual: ok(v && v.manual) };
  }

  function updateTplStore(fn) {
    try {
      updateVariablesWith((v) => {
        const cur = v[TPL_AUTO_NS] && typeof v[TPL_AUTO_NS] === 'object' ? v[TPL_AUTO_NS] : {};
        const ok = (x) => (x && typeof x === 'object' && !Array.isArray(x) ? x : {});
        const next = { v: 1, recs: Object.assign({}, ok(cur.recs)), manual: Object.assign({}, ok(cur.manual)) };
        fn(next);
        v[TPL_AUTO_NS] = next;
        return v;
      }, { type: 'global' });
      return true;
    } catch (e) {
      warn('性格模板的记录没存上：', e);
      return false;
    }
  }

  function manualKey(name, profile) { return name + '#' + hashStr(profile); }

  // 手选的几本；没手选过返回 null（手选空数组 = 这个人不用模板）
  function manualPicks(name, profile) {
    const m = tplStore().manual[manualKey(name, profile)];
    return Array.isArray(m) ? m : null;
  }

  // picks 为 null：删掉手选，改回自动
  function setManualPicks(name, profile, picks) {
    return updateTplStore((s) => {
      const k = manualKey(name, profile);
      delete s.manual[k];                                     // 删了再加，排到最后＝最新
      if (picks != null) s.manual[k] = picks.slice(0, 3);
      const keys = Object.keys(s.manual);
      keys.slice(0, Math.max(0, keys.length - MANUAL_KEEP)).forEach((x) => { delete s.manual[x]; });
    });
  }

  // 档案够不够长。状态模型的地址和名字有默认值，不会是空的；连不上的在识别时算「没识别成」
  function canIdentify(profile) {
    return String(profile || '').trim().length >= IDENTIFY_MIN_PROFILE;
  }

  // 给识别用的档案：写性格、说话、待人的段落排到前面，外貌、生日、爱吃什么这些放到最后，再截断。
  // 档案一般先写基本信息和外貌，按原样截前一千多字，「性格」那段常常只剩半截
  const ID_KEEP_HEAD = /性格|说话|口癖|语气|习惯|待人|心理|底色|内心|弱点|反差|看法|面对/;
  const ID_DROP_HEAD = /外貌|外观|服饰|衣着|穿着|发型|身高|体重|生日|食物|补充|乐器|装备|经历|年表|时间线/;
  // 档案里一段的标题：■ 性格 / 【性格】 / ## 性格 / 性格：（冒号后面没东西）
  function sectionHead(l) {
    return /^\s*(■|◆|●|【[^】]{1,12}】\s*$|#{1,4}\s)/.test(l) || /^\s*[^：:\s]{1,10}[：:]\s*$/.test(l);
  }

  function identifyProfile(profile) {
    const lines = String(profile || '').replace(/\r/g, '').split('\n');
    const blocks = [];
    let cur = { head: '', lines: [] };
    lines.forEach((l) => {
      if (sectionHead(l)) { blocks.push(cur); cur = { head: l, lines: [] }; }
      cur.lines.push(l);
    });
    blocks.push(cur);
    const keep = blocks.filter((b) => ID_KEEP_HEAD.test(b.head));
    if (!keep.length) return String(profile || '');
    const drop = blocks.filter((b) => keep.indexOf(b) === -1 && ID_DROP_HEAD.test(b.head));
    const rest = blocks.filter((b) => keep.indexOf(b) === -1 && drop.indexOf(b) === -1);
    // 开头那段（名字、年龄、所属）留几行，让模型知道是谁
    const first = rest.length && !rest[0].head ? [{ lines: rest.shift().lines.filter((l) => /姓名|名字|年龄|性别|所属/.test(l)).slice(0, 3) }] : [];
    return first.concat(keep, rest, drop).map((b) => b.lines.join('\n')).join('\n').trim();
  }

  // 档案里写的「撑不住时会怎样」：先找标题带「例外」的那一段，没有就挑提到另一个人格、代替她的句子。最多 5 行
  function exceptionLines(profile) {
    const lines = String(profile || '').replace(/\r/g, '').split('\n').map((l) => l.trim()).filter(Boolean);
    const at = lines.findIndex((l) => /例外/.test(l) && sectionHead(l));
    let out = [];
    if (at !== -1) {
      for (let i = at + 1; i < lines.length && out.length < 5; i += 1) {
        if (sectionHead(lines[i])) break;
        out.push(lines[i]);
      }
    }
    // 没有「例外」那一段：只认明说另一个人格代替她的句子，别把往事里的只言片语当成机制
    if (!out.length) out = lines.filter((l) => /另一个人格|代替她|出来代替|接管(她的)?身体/.test(l)).slice(0, 4);
    return out.map((l) => clip(l, 160));
  }

  // 目录：只列开着的模板的名字。这些是 ACG 里通行的叫法，模型本来就认识；
  // 实测（52 张写了性格标签的卡）附上【本质】第一句反而更不准——那一句常常写得抽象，把模型带偏
  function identifyCatalog(tpl) {
    return tpl.list.filter((t) => t.enabled).map((t) => t.name).filter((n, i, a) => a.indexOf(n) === i).map((name) => ({ name }));
  }

  function saveAutoRecs(add) {
    updateTplStore((s) => {
      Object.assign(s.recs, add);
      const keys = Object.keys(s.recs).sort((a, b) => (s.recs[b].at || 0) - (s.recs[a].at || 0));
      keys.slice(IDENTIFY_KEEP).forEach((k) => { delete s.recs[k]; });
    });
  }

  function identifyBlocked() { return _identifyBlocked; }
  function clearIdentifyBlock() { _identifyBlocked = null; }

  // people：[{ name, profile }]。返回 { asked, done, failed, blocked }；不需要问的人直接跳过
  async function identifyTemplates(people, tpl, c) {
    if (!tpl || !tpl.list.some((t) => t.enabled)) return { asked: 0, done: 0, failed: 0 };
    const recs = tplStore().recs;
    const waitFor = [];
    const todo = [];
    (people || []).forEach((p) => {
      if (!p || !p.name || todo.some((x) => x.name === p.name)) return;
      if (manualPicks(p.name, p.profile) || suggestTemplates(p.profile, tpl.list).length || !canIdentify(p.profile)) return;
      const key = identifyKey(p.name, p.profile, tpl);
      if (recs[key] || _identifyFailed.has(key)) return;
      if (_identifying.has(key)) { waitFor.push(_identifying.get(key)); return; }
      todo.push({ name: p.name, profile: p.profile, key });
    });
    if (!todo.length) {
      await Promise.all(waitFor).catch(() => {});
      return { asked: 0, done: 0, failed: 0 };
    }
    const catalog = identifyCatalog(tpl);
    const tplNames = catalog.map((t) => t.name).filter((n, i, a) => a.indexOf(n) === i);   // 同名的导了两本也只列一次：严格模式的枚举不许重复
    const batches = [];
    for (let i = 0; i < todo.length; i += IDENTIFY_BATCH) batches.push(todo.slice(i, i + IDENTIFY_BATCH));
    let done = 0;
    let failed = 0;
    let blocked = 0;
    const jobs = batches.map((batch) => {
      const job = (async () => {
        const names = batch.map((p) => p.name);
        const shown = batch.map((p) => ({ name: p.name, profile: identifyProfile(p.profile) }));
        const tokens = 120 * batch.length + 200;
        // 回答被截断（会思考的模型把字数想完了）时加大字数重发一次，和记状态那几路一样
        const once = (lite, more) => callSide(promptText('认性格模板的规则'), buildIdentifyContent(catalog, shown, lite), identifySchema(names, tplNames),
          'handbook_tpl', { cfg: c, maxTokens: more ? biggerTokens(tokens) : tokens, hardTimeout: more ? 120000 : 60000, priority: 'low',
            label: '认性格模板·' + names.join('、') + (lite ? '（短材料）' : '') + (more ? '（加大字数）' : '') });
        let res;
        try {
          res = await once(false).catch((e) => {
            if (e && e.truncated) return once(false, true);
            if (e && e.filtered) return once(true);
            throw e;
          });
        } catch (e) {
          warn('自动识别性格模板失败：', e);
          if (e && (e.filtered || e.truncated)) {     // 换短档案也被审查拦下、加大字数还是被截断：是这一批这一次的事，接口是连得上的
            batch.forEach((p) => _identifyFailed.add(p.key));
            failed += batch.length;
          } else {                                    // 请求本身没成：这几个人还是「等识别」
            _identifyBlocked = { why: String((e && e.message) || e), at: Date.now() };
            blocked += batch.length;
          }
          return;
        }
        const got = Array.isArray(res.data && res.data.people) ? res.data.people : [];
        const add = {};
        batch.forEach((p) => {
          const raw = identifyPicks(got.find((x) => x && String(x.name || '').trim() === p.name));
          if (!raw) { _identifyFailed.add(p.key); failed += 1; return; }
          const picks = raw.filter((s, i, a) => tplNames.indexOf(s) !== -1 && a.indexOf(s) === i).slice(0, 3);
          add[p.key] = { name: p.name, picks, at: Date.now() };
          done += 1;
        });
        if (Object.keys(add).length) saveAutoRecs(add);
      })();
      batch.forEach((p) => _identifying.set(p.key, job));
      return job.finally(() => batch.forEach((p) => _identifying.delete(p.key)));
    });
    BUS.emit('tpl');
    await Promise.all(jobs.concat(waitFor)).catch(() => {});
    BUS.emit('tpl');
    return { asked: todo.length, done, failed, blocked };
  }

  // 名册里所有人都识别一遍（打开聊天后在后台跑），识别完写世界书
  let _autoIdTimer = null;
  function scheduleAutoIdentify(delay) {
    if (_autoIdTimer) clearTimeout(_autoIdTimer);
    const chatId = currentChatId();
    _autoIdTimer = setTimeout(() => {
      _autoIdTimer = null;
      autoIdentifyAll(chatId).catch((e) => warn('自动识别性格模板失败：', e));
    }, delay == null ? 3000 : delay);
  }

  function cancelAutoIdentify() {
    if (_autoIdTimer) clearTimeout(_autoIdTimer);
    _autoIdTimer = null;
    _identifyFailed.clear();
    _plainFailed.clear();                 // 换了聊天：改写失败过的模板再给一次机会
    _identifyBlocked = null;
  }

  // 手动重来：清掉「没识别成」和「连不上」，名册里还没识别的人再问一遍
  function retryIdentify() {
    _identifyFailed.clear();
    _identifyBlocked = null;
    return autoIdentifyAll(currentChatId(), true);
  }

  // force：连不上的记号也不管，照样去问（手动点的）
  async function autoIdentifyAll(chatId, force) {
    if (DISPOSED) return null;
    if (_identifyBlocked && !force) return null;
    if (isStable()) return null;              // 稳定人设的聊天不用性格模板：后台不识别，测试连接以后也不补识别
    if (!force && !chatStarted()) return null;   // 这个聊天还没记过状态（只是点开看看）：不发识别请求，第一轮落档后再识别
    const c = cfg();
    const tpl = await loadTemplates(false);
    if (!tpl.list.some((t) => t.enabled)) return null;
    const roster = mergeDatabase(await buildRoster(false), c).roster;
    if (chatId !== undefined && chatId !== currentChatId()) return null;       // 已经换到别的聊天了
    if (isStable()) return null;                                               // 读模板、名册的时候切成了稳定
    const people = Array.from(roster.people.values()).map((p) => ({ name: p.name, profile: p.profile }));
    const r = await identifyTemplates(people, tpl, c);
    // 识别过的（别的聊天里识别的、上次打开时识别的）这次不会再问，但这个聊天的世界书可能还没有条目：
    // 打开聊天就对一遍。没变化时 writeBookNow 只比对不写。激活模板的那一块也跟着刷新
    if (!DISPOSED && (chatId === undefined || chatId === currentChatId())) { reinject(); scheduleBookWrite(); }
    return r;
  }

  // 保留换行的截断：给世界书条目用，正文模型读起来还有段落
  function clipKeep(s, max) {
    const t = String(s || '').trim();
    if (!max || t.length <= max) return t;
    const head = t.slice(0, max);
    const m = head.match(/^[\s\S]*[。！？；\n]/);
    return (m && m[0].length >= max * 0.6 ? m[0] : head + '…').trim();
  }

  // ---------- 咩咩心理模型只给手账本读 ----------
  // 每次扫描世界书（正文、别的插件调模型，一律）都把模板书的条目拿掉：不管这本书挂没挂、预设有没有让正文模型写
  // <acg_think>，酒馆都不会自己激活它。手账本自己读条目，把在场的人用到的要点写进「手账本-名字」。
  // 改的是这一次扫描读到的内存副本，不存盘，世界书面板里还是原样；数据库读写世界书不走这条路，也不受影响。
  function hideTemplateBook(lores) {
    if (!lores) return 0;
    const book = _tpl && _tpl.book;
    let n = 0;
    ['globalLore', 'characterLore', 'chatLore', 'personaLore'].forEach((k) => {
      const arr = lores[k];
      if (!Array.isArray(arr)) return;
      for (let i = arr.length - 1; i >= 0; i -= 1) {
        const e = arr[i];
        if (e && ((book && e.world === book) || /<acg_archetype:/.test(String(e.content || '')))) {
          arr.splice(i, 1);
          n += 1;
        }
      }
    });
    return n;
  }

  // 正文生成时：有几个时期条目的人，这一轮定了在哪个时期，就把她别的时期的条目拿掉（按书名加条目名认）。
  // 只改这一次扫描的内存副本，世界书里的开关不动；别的插件调模型时不走这里
  function hideOtherPeriods(lores, st, c) {
    const roster = rosterFull(c);
    if (!lores || !roster) return 0;
    const drop = new Set();
    const typed = personPeriods();
    roster.people.forEach((p, n) => {
      if (!p.periods) return;
      const label = matchPeriod(p, typed[n]) || matchPeriod(p, st && st.people && st.people[n] && st.people[n].period);
      if (!label) return;
      p.periods.forEach((v) => { if (v.label !== label) drop.add(v.book + '\u0000' + v.entry); });
    });
    if (!drop.size) return 0;
    let n = 0;
    ['globalLore', 'characterLore', 'chatLore', 'personaLore'].forEach((k) => {
      const arr = lores[k];
      if (!Array.isArray(arr)) return;
      for (let i = arr.length - 1; i >= 0; i -= 1) {
        const e = arr[i];
        if (e && drop.has(String(e.world || '') + '\u0000' + loreName(e))) { arr.splice(i, 1); n += 1; }
      }
    });
    return n;
  }

  // 预设是不是还在让正文模型写 <acg_think>（咩咩的「其他预设使用教程」就是这么接的）。模板书现在只给手账本读，
  // 那段标签不起作用，面板上提醒一句可以关掉。
  // 只认给出了输出格式的条目（一对 <acg_think>…</acg_think>）：咩咩预设里清空变量、插入变量的条目也带着
  // 「acg角色心理模型_思维链」这个名字，那些不算
  function presetMakesTags() {
    try {
      const pre = typeof getPreset === 'function' ? getPreset('in_use') : null;
      return !!(pre && Array.isArray(pre.prompts) &&
        pre.prompts.some((x) => x && x.enabled !== false && /<acg_think>[\s\S]{0,400}?<\/acg_think>/.test(String(x.content || ''))));
    } catch (e) {
      return false;
    }
  }

  // 故事的基调：预设里开着「基调·日常」「基调·沉重」这类条目就是它（常夜灯预设的 🧾 那组）；都没有返回 ''（不限）
  function currentTone() {
    try {
      const pre = typeof getPreset === 'function' ? getPreset('in_use') : null;
      const on = (pre && Array.isArray(pre.prompts) ? pre.prompts : []).filter((x) => x && x.enabled !== false)
        .map((x) => String(x.name || ''));
      if (on.some((n) => /基调\s*[·・:：]?\s*沉重/.test(n))) return '沉重';
      if (on.some((n) => /基调\s*[·・:：]?\s*日常/.test(n))) return '日常';
    } catch (e) { /* 读不到预设就当不限 */ }
    return '';
  }

  // 世界书条目的几个字段，酒馆的（comment / disable / world / key / constant）和酒馆助手的（name / enabled / strategy）两种写法都认
  const loreName = (e) => String((e && (e.comment != null ? e.comment : e.name)) || '');
  const loreOff = (e) => !!e && (e.disable === true || e.enabled === false);
  const loreConst = (e) => !!e && (e.constant === true || (e.strategy && e.strategy.type === 'constant'));
  function loreKeys(e) {
    const raw = [].concat((e && e.key) || [], (e && e.keys) || [], (e && e.strategy && e.strategy.keys) || []);
    return raw.map((k) => (k instanceof RegExp ? '' : String(k || '').trim()))
      .filter((k) => k && k.length >= 2 && !/^\/.*\/[a-z]*$/.test(k));      // 正则关键词不认
  }
  // 数据库写的条目（纪要、人物、可读汇总、外部导入……）
  function isDbLore(nm) {
    return /^(ACU-[^-]+-)?(TavernDB-ACU-|重要人物条目|总结条目|小总结条目|外部导入-)/.test(nm);
  }

  // 「按场景选设定」：从世界书里挑和这一场有关的设定条目，原文照带，不改写。
  // 候选：开着的、有关键词的普通条目；不要人物档案（名册那套）、手账本自己的、数据库写的、常驻的（本来就在）。
  // 打分只看这一场：关键词出现在地点里算 3 分，是在场的人的名字或别名算 2 分。最近的正文里提到的，酒馆自己会按关键词激活，不用手账本管
  const SCENE_LORE_MAX = 6;
  function sceneLore(all, st, c, roster) {
    const place = String((st && st.scene && st.scene.place) || '');
    const names = [];
    shownPeople(st, c).forEach((n) => {
      names.push(n);
      Object.keys((roster && roster.alias) || {}).forEach((a) => { if (roster.alias[a] === n) names.push(a); });
    });
    if (!place && !names.length) return [];
    const scored = [];
    all.forEach((e) => {
      if (!e || loreOff(e) || loreConst(e)) return;
      const nm = loreName(e);
      if (nm.indexOf(BOOK_PREFIX) === 0 || isDbLore(nm) || parseRosterComment(nm)) return;
      let score = 0;
      loreKeys(e).forEach((k) => {
        if (place && place.indexOf(k) !== -1) score += 3;
        else if (names.indexOf(k) !== -1) score += 2;
      });
      if (score) scored.push({ e, score });
    });
    return scored.sort((a, b) => b.score - a.score).slice(0, SCENE_LORE_MAX).map((x) => x.e);
  }

  // 这一轮被叫到名字、但不在出场名单里的人。点名只认正文里的：状态栏、好感栏会列出一整排没登场的人。
  // 「不算点名的名字」里的、这个聊天里删掉的人不算；出场的人不占名额，按被叫到的次数取前「点名最多带几人」个
  function mentionedPeople(c, roster, shown) {
    const cc = c || cfg();
    const skip = skipNames(cc);
    const muted = mutedNames();
    const talk = chatNow().filter((m) => m && !m.is_system).slice(-2).map(plainBody).join('\n');
    const hits = {};
    Object.keys(roster.alias || {}).forEach((a) => {
      const who = roster.alias[a];
      if (skip.has(a) || skip.has(who) || muted.has(who) || shown.indexOf(who) !== -1) return;
      const n = countMentions(talk, a, true);
      if (n > 0) hits[who] = (hits[who] || 0) + n;
    });
    return Object.keys(hits).sort((a, b) => hits[b] - hits[a]).slice(0, cc.点名最多带几人);
  }

  // 配角之间（2026-10-02 常夜灯定）：配角关系表里一行的人物A、人物B都在这一轮的人里（出场的、被叫到名字的），
  // 而且至少一个出场（这一场或平行线上），就把这一行的「当前状态」交给正文。只发这一列，「交往经过」不发。
  // 一轮最多 PAIR_MAX 行，两个人都出场的排前面；同一对写了几行的，取表里靠后的那行。
  // 没开「读数据库」、没有这张表、表里对不上，返回空数组。正文的注入和面板都用这一份
  const PAIR_MAX = 4;
  function pairLines(st, c) {
    const cc = c || cfg();
    if (!st || !cc.读数据库) return [];
    const roster = rosterFull(cc);
    if (!roster) return [];
    let db = null;
    try { db = readDatabase(null); } catch (e) { db = null; }
    const rows = db && db.own && Array.isArray(db.own.npc) ? db.own.npc : [];
    if (!rows.length) return [];
    const shown = shownPeople(st, cc);
    const near = shown.concat(mentionedPeople(cc, roster, shown));
    const muted = mutedNames();
    const ambiguous = roster.ambiguous || new Set();
    const nameOf = (v) => {
      const t = String(v || '').replace(/[（(].*$/, '').trim();
      return !t || ambiguous.has(t) ? '' : (roster.alias[t] || t);
    };
    const seen = new Set();
    const got = [];
    rows.slice().reverse().forEach((r) => {
      const a = nameOf(r['人物A']);
      const b = nameOf(r['人物B']);
      const text = clip(r['当前状态'], 40);
      if (!a || !b || a === b || !text || muted.has(a) || muted.has(b)) return;
      if (near.indexOf(a) === -1 || near.indexOf(b) === -1) return;
      const onA = shown.indexOf(a) !== -1;
      const onB = shown.indexOf(b) !== -1;
      if (!onA && !onB) return;
      const key = [a, b].sort().join('\n');
      if (seen.has(key)) return;
      seen.add(key);
      got.push({ a, b, text, both: onA && onB });
    });
    return got.filter((x) => x.both).concat(got.filter((x) => !x.both)).slice(0, PAIR_MAX).map((x) => ({ a: x.a, b: x.b, text: x.text }));
  }

  // 这一次扫描要强制激活的条目。lores 是酒馆刚读好的全局 / 角色 / 聊天 / 用户四份条目（模板书已经拿掉了）。
  //   · 「手账本-名字」：在场的人，加上最近两条消息的正文里被点名的人（最多「点名最多带几人」个，「不算点名的名字」里的不算；条目本身没有关键词，只有这里会激活它）。
  //     另一个人格替她出来时，激活那个人格的「手账本-」条目，不激活她自己的：她自己的写的是平时的她，激活了会把人往回拽。
  //     那个人格在名册里没有条目，这一轮就不给她激活
  //   · 开了「按场景选设定」：再加上和这一场有关的设定条目
  // 纯函数，不看这一次是不是正文生成，调用方决定
  function forceEntries(lores, st, c) {
    const all = [].concat(lores.globalLore || [], lores.characterLore || [], lores.chatLore || [], lores.personaLore || []);
    const roster = rosterFull(c);
    if (!st || !roster) return [];
    const out = [];
    const shown = shownPeople(st, c);
    // 稳定人设：「手账本-」条目（性格模板、压力、关系阶段）不激活，按场景选的设定照旧
    const mentioned = isStable() ? [] : mentionedPeople(c, roster, shown);
    const wantOwn = [];
    (isStable() ? [] : shown.concat(mentioned)).forEach((n) => {
      const alter = st.people && st.people[n] && st.people[n].persona;
      const who = alter || n;
      if (wantOwn.indexOf(who) === -1) wantOwn.push(who);
    });
    all.forEach((e) => {
      const nm = loreName(e);
      if (nm.indexOf(BOOK_PREFIX) === 0 && !loreOff(e) && wantOwn.indexOf(nm.slice(BOOK_PREFIX.length)) !== -1) out.push(e);
    });
    if (c && c.按场景选设定) sceneLore(all, st, c, roster).forEach((e) => { if (out.indexOf(e) === -1) out.push(e); });
    return out;
  }

  // 酒馆每次扫描世界书都会先读条目、发 worldinfo_entries_loaded。每一次都先把模板书拿掉；
  // 只在正文生成的那一次，把要激活的条目交给酒馆。这样既不往扫描文本里塞字（塞了会顺带激活别的条目），也不会让别的插件调模型时带上
  async function onEntriesLoaded(lores) {
    try {
      if (DISPOSED || !lores) return;
      hideTemplateBook(lores);
      if (!isMainGeneration()) return;
      const c = cfg();
      const st = stateForGeneration();
      hideOtherPeriods(lores, st, c);
      const list = forceEntries(lores, st, c);
      if (list.length && typeof eventEmit === 'function') {
        await eventEmit((tavern_events && tavern_events.WORLDINFO_FORCE_ACTIVATE) || 'worldinfo_force_activate', list);
      }
    } catch (e) {
      warn('激活手账本条目失败：', e);
    }
  }

  // 给填表员的整本；被内容审查拦下重试时只给【本质】。
  // 【破防】放在最后、先留够位置：有几本正文很长，按字数一刀切会把崩溃的样子整段切掉
  function templateForSide(t, lite) {
    if (lite) return clip(t.sections['本质'] || t.body, 400);
    const bk = Object.keys(t.sections).find((x) => /破防/.test(x));
    const brk = bk ? '【破防】' + clip(t.sections[bk], 600) : '';
    const rest = Object.keys(t.sections).filter((x) => x !== bk).map((x) => '【' + x + '】' + t.sections[x]).join(' ');
    const main = Object.keys(t.sections).length ? rest : t.body;
    return [clip(main, 1800 - brk.length - 1), brk].filter(Boolean).join(' ');
  }

  function spectrumLine(t, stage) {
    const hit = t.spectrum.find((s) => s.stage === stage);
    return hit ? hit.text : '';
  }

  function breakSection(t) {
    const k = Object.keys(t.sections).find((x) => /破防/.test(x));
    return k ? t.sections[k] : '';
  }

  // ---------- 性格模板改写成档案（「手账本-名字」条目用） ----------
  // 模板原文是散文，带比喻和例句，正文模型读了会跟着写。条目里放的是状态模型改写过的档案：核心、对每一步关系的人怎样、破防。
  // 每本模板按原文指纹存一份，存在全局变量里（换聊天、换卡都用得上）。rule 记着是照哪一版「整理性格模板的规则」改写的：
  // 规则变了（升级换了内置的、玩家在提示词页改了），没手改过的那些下次写条目时重新整理；manual 是玩家在设置里改过的，一直照它用，
  // 只有点「重新整理」才换掉。改写失败的这次打开期间不再问
  const TPL_PLAIN_NS = NS + '_tplplain';
  const TPL_PLAIN_KEEP = 200;
  const PLAIN_VER = '2';
  const _plainBusy = new Map();
  const _plainFailed = new Set();
  const _plainErr = new Map();      // 这一本上一次没改写成的原因（设置里「重新整理」没成时说）

  function plainKey(t) { return hashStr(String(t.kind || '') + '\n' + String(t.body || '')); }
  function plainRule() { return hashStr(PLAIN_VER + '\n' + promptText('整理性格模板的规则')); }
  // 没有、或者是照旧规则整理的（手改过的不算）：要重新整理
  function plainNeeds(t) {
    const p = plainOf(t);
    return !p || (!p.manual && p.rule !== plainRule());
  }

  function plainStore() {
    try {
      const v = (getVariables({ type: 'global' }) || {})[TPL_PLAIN_NS];
      return v && typeof v === 'object' ? v : {};
    } catch (e) { return {}; }
  }

  function plainOf(t) {
    const p = plainStore()[plainKey(t)];
    return p && typeof p === 'object' ? p : null;
  }

  const PLAIN_SCHEMA = {
    type: 'object',
    properties: {
      core: { type: 'string', description: '这一类性格的核心，≤120字' },
      stages: {
        type: 'array',
        maxItems: 7,
        items: {
          type: 'object',
          properties: { stage: { type: 'string', enum: STAGES }, text: { type: 'string', description: '她对这一步关系的人怎样，≤80字' } },
          required: ['stage', 'text'],
          additionalProperties: false,
        },
      },
      break_when: { type: 'string', description: '什么情况下会破防，≤50字；模板没写就空' },
      break_how: { type: 'string', description: '破防时她会怎样，≤80字；模板没写就空' },
    },
    required: ['core', 'stages', 'break_when', 'break_how'],
    additionalProperties: false,
  };

  function normPlain(d) {
    const stages = {};
    (Array.isArray(d && d.stages) ? d.stages : []).forEach((x) => {
      if (x && STAGES.indexOf(x.stage) !== -1 && String(x.text || '').trim()) stages[x.stage] = clip(x.text, 80);
    });
    return { core: clip(d && d.core, 120), stages, when: clip(d && d.break_when, 50), how: clip(d && d.break_how, 80), at: Date.now() };
  }

  // 存一本的档案；超过 TPL_PLAIN_KEEP 本时先丢最旧的、没手改过的
  function putPlain(key, val) {
    updateVariablesWith((g) => {
      const all = g[TPL_PLAIN_NS] && typeof g[TPL_PLAIN_NS] === 'object' ? g[TPL_PLAIN_NS] : {};
      if (val) all[key] = val;
      else delete all[key];
      const drop = Object.keys(all).length - TPL_PLAIN_KEEP;
      if (drop > 0) {
        Object.keys(all).sort((a, b) => (all[a].manual ? 1 : 0) - (all[b].manual ? 1 : 0) || (all[a].at || 0) - (all[b].at || 0))
          .slice(0, drop).forEach((k) => { delete all[k]; });
      }
      g[TPL_PLAIN_NS] = all;
      return g;
    }, { type: 'global' });
  }

  // 这一次新改写好、存进去的那份；不用改写、改写失败、整理期间被手改了都返回 null（调用方据此决定要不要再写一遍条目，
  // 返回旧的那份会让写条目和改写来回触发）。同一本同时只问一次
  function makePlain(t, c) {
    const key = plainKey(t);
    if (!plainNeeds(t)) return Promise.resolve(null);
    const rule = plainRule();
    if (_plainFailed.has(key + rule)) return Promise.resolve(null);
    if (_plainBusy.has(key)) return _plainBusy.get(key);
    const ask = (more) => callSide(promptText('整理性格模板的规则'), '【性格模板：' + t.kind + '】\n' + clip(t.body, 4000),
      PLAIN_SCHEMA, 'handbook_tplplain', { cfg: c, maxTokens: more ? 6000 : 1500, hardTimeout: 90000, priority: 'low', label: '整理性格模板·' + t.kind });
    const job = ask(false)
      .catch((e) => { if (e && e.truncated) return ask(true); throw e; })
      .then((res) => {
        const p = normPlain(res.data || {});
        if (!p.core) throw new Error('改写回来是空的');
        const now = plainOf(t);
        if (now && now.manual) return null;                 // 整理期间玩家手改了：照手改的
        const val = Object.assign({ kind: t.kind }, p, { rule });
        putPlain(key, val);
        return val;
      })
      .catch((e) => {
        _plainFailed.add(key + rule);
        _plainErr.set(key, String((e && e.message) || e));
        warn('性格模板「' + t.kind + '」没改写成档案：', e);
        return null;
      })
      .finally(() => { _plainBusy.delete(key); });
    _plainErr.delete(key);
    _plainBusy.set(key, job);
    return job;
  }
  function plainBusy(t) { return _plainBusy.has(plainKey(t)); }
  function plainError(t) { return _plainErr.get(plainKey(t)) || ''; }

  // 设置里「整理好的模板」那一格的文字：一项一行，「核心：」「阶段名：」「破防条件：」「破防表现：」开头，没有的不写
  const PLAIN_LABELS = ['核心'].concat(STAGES, ['破防条件', '破防表现']);
  function plainText(p) {
    if (!p) return '';
    const L = [];
    if (p.core) L.push('核心：' + p.core);
    STAGES.forEach((sg) => { if (p.stages && p.stages[sg]) L.push(sg + '：' + p.stages[sg]); });
    if (p.when) L.push('破防条件：' + p.when);
    if (p.how) L.push('破防表现：' + p.how);
    return L.join('\n');
  }
  // 反过来读：认得的开头起一项（条目里「对陌生人：」那种写法也认），后面没有开头的行接在上一项后面；第一项之前的行算核心。
  // 每项最多 400 字
  const PLAIN_LINE = new RegExp('^\\s*(?:对)?(' + PLAIN_LABELS.join('|') + ')\\s*[：:]\\s*(.*)$');
  function parsePlainText(text) {
    const got = {};
    let cur = '核心';
    String(text || '').replace(/\r/g, '').split('\n').forEach((line) => {
      const m = line.match(PLAIN_LINE);
      if (m) { cur = m[1]; got[cur] = (got[cur] ? got[cur] + '\n' : '') + m[2].trim(); return; }
      if (!line.trim()) return;
      got[cur] = (got[cur] ? got[cur] + '\n' : '') + line.trim();
    });
    const cut = (s) => clipKeep(String(s || '').trim(), 400);
    const stages = {};
    STAGES.forEach((sg) => { if (got[sg] && got[sg].trim()) stages[sg] = cut(got[sg]); });
    return { core: cut(got.核心), stages, when: cut(got.破防条件), how: cut(got.破防表现) };
  }
  // 设置里改了一本：存成手改的，一直照它用。清空就等于点「重新整理」
  function savePlainEdit(t, text) {
    if (!String(text || '').trim()) return replain(t, cfg());
    const p = parsePlainText(text);
    const old = plainOf(t);
    if (old && plainText(old) === plainText(p)) return Promise.resolve(old);
    const val = Object.assign({ kind: t.kind }, p, { at: Date.now(), manual: true, rule: plainRule() });
    putPlain(plainKey(t), val);
    return Promise.resolve(val);
  }
  // 「重新整理」：丢掉这一本现在的档案（手改的也丢），照现在的规则重新改写
  function replain(t, c) {
    const key = plainKey(t);
    putPlain(key, null);
    Array.from(_plainFailed).forEach((k) => { if (k.indexOf(key) === 0) _plainFailed.delete(k); });
    return makePlain(t, c);
  }

  // ======================== 压力与关系阶段 ========================
  // 只做计算，不碰酒馆。每一楼的状态里带一份 chars（每个人的压力和关系阶段），
  // 由「上一楼的 chars」加上「这一楼填表员报的事」算出来，所以删消息时跟着楼层回退。
  //
  // 下面的数都是工程上定的，不是论文给的。论文只管结构：
  //   · 压力跨轮攒，每轮自然降一点（允稳负荷、资源保存理论）
  //   · 「控制不了」加「当着人被评价」最重（Dickerson & Kemeny 2004）
  //   · 有人撑着减半（Cohen & Wills 1985）
  //   · 进崩溃和出崩溃是两条线，崩溃至少两轮（反应和恢复是两个过程；滞回）
  //   · 崩过一次，之后一阵子门槛低一点（「点燃」假说）
  //   · 关系要反复才挪一格，推远的分量是靠近的两倍，久了会散（TESSERA；坏事比好事重；设定点）
  //   · 情侣、夫妻、决裂这类关系由一件旁人指得出的事定下（契约事件），不靠攒

  const PRESSURE_W = { 没有: 0, 一点: 1, 明显: 2, 很重: 4 };
  const P = {
    decay: 1,          // 每轮自然降
    tense: 6,          // 平稳 → 紧张
    tenseOut: 3,       // 紧张 → 平稳
    brk: 12,           // → 崩溃
    brkOut: 5,         // 崩溃 → 紧张（再低到 tenseOut 以下直接平稳）
    brkMin: 2,         // 崩溃至少几轮
    max: 20,
    relief: 4,         // 发生了她的恢复方式，额外降多少
    kindle: 3,         // 崩过以后门槛低多少
    kindleTurns: 30,   // 低多少轮
  };
  const LEVEL_LOAD = { 平稳: 0, 紧张: P.tense, 崩溃: P.brk };   // 手改档位时，负荷挪到这一档的起点
  const REL_W = { 一点: 1, 明显: 2, 很重: 3 };
  const R = { step: 6, decay: 0.25, cooldown: 3, negMul: 2, keepLog: 5 };

  function emptyChar() {
    return { load: 0, level: '平稳', inLevel: 0, kindle: 0, breaks: 0, recent: [], rel: {} };
  }

  function cloneChars(chars) {
    return JSON.parse(JSON.stringify(chars || {}));
  }

  // rep：填表员报的 { level, event, uncontrollable, evaluated, supported, relief }；这一楼没有她就是 null
  function pressureStep(ch, rep, c, floor) {
    let w = 0;
    let relief = 0;
    if (rep) {
      w = PRESSURE_W[rep.level] || 0;
      if (w > 0) {
        if (rep.uncontrollable && rep.evaluated) w = Math.max(w, PRESSURE_W.很重);
        else if (rep.uncontrollable || rep.evaluated) w += 1;
        if (rep.supported) w = Math.floor(w / 2);
      }
      if (rep.relief) relief = P.relief;
      if (w > 0 && rep.event) {
        ch.recent = (ch.recent || []).concat([{ floor, event: rep.event, w }]).slice(-3);
      }
    }
    ch.load = Math.max(0, Math.min(P.max, Math.max(0, ch.load - P.decay) + w - relief));
    ch.kindle = Math.max(0, (ch.kindle || 0) - 1);
    const brkLine = P.brk - (ch.kindle > 0 ? P.kindle : 0);

    const prev = ch.level;
    let next = prev;
    if (prev === '崩溃') {
      if (!c.允许崩溃) next = '紧张';
      else if (ch.inLevel + 1 >= P.brkMin && ch.load <= P.brkOut) next = ch.load <= P.tenseOut ? '平稳' : '紧张';
    } else if (c.允许崩溃 && ch.load >= brkLine) {
      next = '崩溃';
    } else if (prev === '紧张') {
      if (ch.load <= P.tenseOut) next = '平稳';
    } else if (ch.load >= P.tense) {
      next = '紧张';
    }
    if (next === '崩溃' && prev !== '崩溃') {
      ch.breaks = (ch.breaks || 0) + 1;
      ch.kindle = P.kindleTurns;
    }
    ch.inLevel = next === prev ? (ch.inLevel || 0) + 1 : 0;
    ch.level = next;
  }

  // rels：填表员报的 [{ to, contract, stage, dir, level, why, tone, tested, trust }]；这一楼没有她就是 null
  function relationStep(ch, rels, floor, c) {
    Object.keys(ch.rel).forEach((to) => {                  // 很久没发生，攒着的慢慢散
      const r = ch.rel[to];
      if (r.acc > 0) r.acc = Math.max(0, r.acc - R.decay);
      else if (r.acc < 0) r.acc = Math.min(0, r.acc + R.decay);
    });
    (rels || []).forEach((x) => {
      if (!x || !x.to) return;
      // 同一个人记成了两种汉字写法（辺 / 边 这类）：留这一次报的写法，另一种并进来或去掉
      Object.keys(ch.rel).forEach((k) => {
        if (k === x.to || !sameName(k, x.to)) return;
        if (!ch.rel[x.to]) ch.rel[x.to] = ch.rel[k];
        delete ch.rel[k];
      });
      let r = ch.rel[x.to];
      if (!r) r = ch.rel[x.to] = { stage: canonStage(x.stage) || '陌生人', acc: 0, moved: null, log: [] };
      // 好感底色、信任落点不管自动手动都记：底色报了就换（提示词要求构成变了才换），信任落点空着才补、有检验才换
      if (x.tone) r.tone = x.tone;
      if (x.trust && (!r.trust || x.tested)) r.trust = x.trust;
      if (c.关系阶段调整 !== '自动') return;
      // 契约事件：直接改到报的那一格，不攒、不等冷却，情侣、夫妻也能到；只认进出情侣、夫妻、讨厌的人的
      const set = canonStage(x.stage);
      if (x.contract && set && set !== r.stage && (CONTRACT_STAGES.indexOf(set) !== -1 || CONTRACT_STAGES.indexOf(r.stage) !== -1)) {
        r.log = (r.log || []).concat([{ floor, from: r.stage, to: set, why: x.contract, contract: true }]).slice(-R.keepLog);
        r.stage = set;
        r.acc = 0;
        r.moved = floor;
        return;
      }
      const w = REL_W[x.level] || 0;
      if (x.dir === '靠近') r.acc += w;
      else if (x.dir === '推远') r.acc -= w * R.negMul;
      else return;
      if (CONTRACT_ONLY.indexOf(r.stage) !== -1) return;                   // 情侣、夫妻只靠契约事件变
      if (r.moved != null && (floor - r.moved) / 2 < R.cooldown) return;   // 一轮是玩家一楼加正文一楼
      const i = stageIndex(r.stage);
      let to = null;
      if (r.acc >= R.step && i >= 0 && i < stageIndex(AUTO_STAGE_CAP)) to = STAGES[i + 1];
      else if (r.acc <= -R.step && i > 0) to = STAGES[i - 1];
      if (!to) return;
      r.log = (r.log || []).concat([{ floor, from: r.stage, to, why: x.why || '' }]).slice(-R.keepLog);
      r.stage = to;
      r.acc = 0;
      r.moved = floor;
    });
  }

  // prev：上一楼的 chars；people：这一楼的 st.people。只有这一轮新算、出场的人（这一场和平行线上的）带着事，其余的人只自然回落
  function stepChars(prev, people, floor, c) {
    const out = cloneChars(prev);
    const ppl = people || {};
    const fresh = Object.keys(ppl).filter((n) => ppl[n] && !ppl[n].carried && onStage(ppl[n]));
    fresh.forEach((n) => { if (!out[n]) out[n] = emptyChar(); });
    Object.keys(out).forEach((n) => {
      const p = fresh.indexOf(n) !== -1 ? ppl[n] : null;
      pressureStep(out[n], p ? p.pressure : null, c, floor);
      relationStep(out[n], p ? p.relations : null, floor, c);
    });
    return out;
  }

  // 从 fromFloor 起往后顺着重算（前一楼的状态比后一楼晚到时用）。删掉的楼层跳过。
  // 稳定人设记的楼（st.stable）压力、关系阶段照上一楼冻住；手账本自己记约定和事件的楼（有 ledgerRaw）跟着重算
  function refoldChars(store, fromFloor, c) {
    const chat = chatNow();
    let prev = null;
    let prevSt = null;
    let prevLedger = null;
    const alias = (_roster && _roster.alias) || {};
    const player = readPersona().name;
    Object.keys(store.floors).map(Number).sort((a, b) => a - b).forEach((k) => {
      const st = store.floors[k];
      if (!st || !stillValid(st, chat)) return;
      // 整份沿用上一楼的楼层没有新事，和落档时一样只回落，免得同一件事算两遍
      if (k >= fromFloor) {
        if (st.stable) st.chars = cloneChars(prev || {});
        else {
          st.chars = stepChars(prev || {}, st.carried ? {} : st.people, k, c);
          settlePersona(st, prevSt, c);                     // 压力重算过，「现在是」也要跟着重新对一遍
        }
        if (st.ledgerRaw !== undefined) st.ledger = stepLedger(prevLedger, st.ledgerRaw, k, alias, player);
        else if (prevLedger) st.ledger = prevLedger;
      }
      if (st.tail) return;                                   // 「记到最新」的那份是临时的，后面的楼层不拿它当底
      prev = st.chars || prev;
      prevLedger = st.ledger || prevLedger;
      prevSt = st;
    });
  }

  // 另一个人格（people[n].persona）什么时候算数：
  //   · 关掉「允许崩溃」就不算；
  //   · 这一楼压力到了崩溃，算；
  //   · 上一楼已经出来了，压力还没回到平稳，接着算（档案没写怎么回来时，等压力回到平稳再回来）；
  //   · 其余情况（填表员在紧张时就写了、沿用下来的旧值而压力已经平稳）都清掉。
  // 沿用上一楼的人也要对：不然她这一楼没算出新状态，「现在是」就再也清不掉
  function settlePersona(st, prevSt, c) {
    Object.keys(st.people || {}).forEach((n) => {
      const p = st.people[n];
      if (!p || !p.persona) return;
      const was = prevSt && prevSt.people && prevSt.people[n] && prevSt.people[n].persona;
      const lvl = st.chars && st.chars[n] ? st.chars[n].level : '平稳';
      const keep = c.允许崩溃 && (lvl === '崩溃' || (was && lvl !== '平稳'));
      if (!keep) st.people[n] = Object.assign({}, p, { persona: '' });   // 整份沿用时和上一楼共用对象，换一份再改
    });
  }

  function charsNow() {
    const st = latestState(loadStore(), null);
    return (st && st.chars) || {};
  }

  // 「对沈遥：普通朋友；对丰川祥子：挚友」；full 时每个人后面跟着好感底色、信任落点
  function relSummary(ch, max, full) {
    if (!ch || !ch.rel) return '';
    return Object.keys(ch.rel).slice(0, max || 4).map((to) => {
      const r = ch.rel[to];
      return '对' + to + '：' + r.stage + (full && r.tone ? '，好感底色：' + r.tone : '') + (full && r.trust ? '，信任落点：' + r.trust : '');
    }).join('；');
  }

  // ======================== 写进世界书 ========================
  // 给用了性格模板的人，在这个聊天自己的世界书里建一条「手账本-名字」。关系阶段选了「手动」时，记过状态的人都建一条：
  // 手动模式下玩家要靠这条条目改关系阶段，没模板的人也得有地方改。
  // 条目本身不带关键词、也不常驻，只在正文生成时由手账本激活（在场的人、最近两条消息里被点名的人，见 forceEntries）：
  // 别的卡、别的插件调模型时都不会带上它。
  // 条目里「压力」「关系阶段」两处是固定格式：玩家在世界书里手改了，下次写之前先收回来，照改的算。
  // 状态本身还是按楼层存在聊天变量里；世界书只是给正文模型看、给玩家改的那一份。

  const BOOK_PREFIX = '手账本-';
  let _bookTimer = null;
  let _bookChain = Promise.resolve();

  function entryName(name) { return BOOK_PREFIX + name; }

  // 这个聊天还没有聊天世界书时，手账本新建的那本叫「手账本-卡名」（群聊用群名）。
  // 同一张卡的别的聊天已经用了这个名字，就在后面加这个聊天的开始时间，各记各的。
  // 世界书名就是文件名：Windows 不许半角冒号，时间里用全角「：」
  // 卡名（群聊用群名），去掉文件名里不许有的字符；取不到就叫「聊天」
  function cardLabel() {
    const ctx = getCtx() || {};
    let card = '';
    try {
      if (ctx.groupId) {
        const g = (ctx.groups || []).find((x) => String(x.id) === String(ctx.groupId));
        card = g ? g.name : '';
      } else {
        card = ctx.name2 || ((ctx.characters || [])[ctx.characterId] || {}).name || '';
      }
    } catch (e) {
      card = '';
    }
    return String(card || '').replace(/[\\/:*?"<>|\u0000-\u001f]/g, ' ').replace(/\s+/g, ' ').trim() || '聊天';
  }

  function newBookName() {
    const base = BOOK_PREFIX + cardLabel();
    let names = [];
    try { names = getWorldbookNames() || []; } catch (e) { names = []; }
    if (names.indexOf(base) === -1) return base;
    const m = String(currentChatId() || '').match(/(\d{4}-\d{2}-\d{2})@(\d{2})h(\d{2})m/);
    const pad = (n) => String(n).padStart(2, '0');
    const d = new Date();
    const stamp = m ? m[1] + ' ' + m[2] + '：' + m[3]
      : d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate()) + ' ' + pad(d.getHours()) + '：' + pad(d.getMinutes());
    let name = base + ' ' + stamp;
    for (let i = 2; names.indexOf(name) !== -1; i += 1) name = base + ' ' + stamp + ' (' + i + ')';
    return name;
  }

  // 条目不靠关键词、也不常驻：只有手账本在正文生成时激活它。旧版写过的关键词、常驻在这里一并去掉
  function bookStrategy(name, roster, present, old) {
    return Object.assign({}, old, { type: 'selective', keys: [] });
  }

  // 模板书只给手账本读（酒馆不会自己激活它），正文模型用到的模板要点都从这里来：本质、当前关系阶段那句、压力不平稳时的破防
  function buildEntryContent(name, tpls, ch, note) {
    const L = ['<' + entryName(name) + '>'];
    if (tpls.length) L.push('性格模板：' + tpls.map((t) => t.kind).join('、'));
    L.push('压力：' + (ch ? ch.level : '平稳'));
    const tos = ch ? Object.keys(ch.rel || {}) : [];
    if (tos.length) {
      L.push('关系阶段：');
      // 好感底色、信任落点写在阶段下面缩进的两行：parseEntryEdits 只认「- 对某人：阶段」那一行
      tos.forEach((to) => {
        const r = ch.rel[to];
        L.push('- 对' + to + '：' + r.stage);
        if (r.tone) L.push('  好感底色：' + r.tone);
        if (r.trust) L.push('  信任落点：' + r.trust);
      });
    }
    const stages = tos.map((to) => ch.rel[to].stage).filter((s, i, a) => a.indexOf(s) === i);
    // 模板内容用改写成档案的那份（见 09_templates.js 的 makePlain）；还没改写好的先不放，改写好了这一条会重写
    tpls.forEach((t) => {
      const p = plainOf(t);
      if (!p) return;
      const rows = [];
      if (p.core) rows.push('核心：' + p.core);
      stages.forEach((sg) => { if (p.stages && p.stages[sg]) rows.push('对' + sg + '：' + p.stages[sg]); });
      if (ch && ch.level !== '平稳') {
        if (p.when) rows.push('破防条件：' + p.when);
        if (p.how) rows.push('破防表现：' + p.how);
      }
      if (rows.length) L.push('【' + t.kind + '】\n' + rows.join('\n'));
    });
    // 玩家在设置里写的补充：只对她，和上面的模板冲突时照它
    if (note) L.push('【补充】（只对她，和上面的模板不一样时照这里）\n' + note);
    L.push('</' + entryName(name) + '>');
    return L.join('\n');
  }

  // 读条目里的「压力：」和「- 对某人：阶段」。只看开头那几行，模板正文里的列表不算
  function parseEntryEdits(content) {
    const s = String(content || '').split(/\n(?=【)/)[0];
    const m = s.match(/^压力[：:]\s*(平稳|紧张|崩溃)\s*$/m);
    const rel = {};
    const re = /^-\s*对(.+?)[：:]\s*(.+?)\s*$/gm;
    let x;
    while ((x = re.exec(s))) {
      const st = canonStage(x[2]);
      if (st) rel[x[1].trim()] = st;
    }
    return { level: m ? m[1] : null, rel };
  }

  // 条目和上次写进去的不一样，就是玩家手改过：改进最新一楼的 chars
  function adoptEdits(ch, edits, sig, floor) {
    let changed = false;
    if (edits.level && sig.level && edits.level !== sig.level && edits.level !== ch.level) {
      ch.level = edits.level;
      ch.load = LEVEL_LOAD[edits.level];
      ch.inLevel = 0;
      changed = true;
    }
    Object.keys(edits.rel).forEach((to) => {
      const was = sig.rel ? sig.rel[to] : null;       // 上次没写这个人、这次条目里有：玩家加的一行
      if (edits.rel[to] === was) return;
      const r = ch.rel[to] || (ch.rel[to] = { stage: null, acc: 0, moved: null, log: [] });
      if (r.stage === edits.rel[to]) return;
      r.log = (r.log || []).concat([{ floor, from: r.stage, to: edits.rel[to], why: '手改' }]).slice(-R.keepLog);
      r.stage = edits.rel[to];
      r.acc = 0;
      r.moved = floor;
      changed = true;
    });
    return changed;
  }

  // 返回 { written, removed, adopted, book } 或 { skipped } / { error }
  async function writeBookNow(force) {
    const c = cfg();
    if (DISPOSED) return { skipped: true };
    if (!force && !c.自动写入世界书) return { skipped: true };
    if (isStable()) return { skipped: true, stable: true };       // 稳定人设：「手账本-」条目不写（写好的留着，也不激活）
    if (!chatStarted()) return { skipped: true, fresh: true };    // 这个聊天还没记过状态（只是点开看看、刚清空过）：不建书、不写条目
    if (typeof getOrCreateChatWorldbook !== 'function' || typeof updateWorldbookWith !== 'function') {
      return { error: '酒馆助手版本太旧，没有写世界书的接口' };
    }
    // 世界书和聊天变量的接口都认「现在打开的聊天」。中途换了聊天就整段作罢，免得把上一个聊天的状态写进这一个
    const chatId = currentChatId();
    const moved = () => DISPOSED || chatId !== currentChatId();
    const tpl = await loadTemplates(false);
    const roster = mergeDatabase(await buildRoster(false), c).roster;   // 数据库里的人也写
    if (moved()) return { skipped: true };
    const tplOf = (n) => (roster.people.has(n) ? templatesFor(n, roster.people.get(n).profile, c, tpl) : []);
    const tplNames = Array.from(roster.people.keys()).filter((n) => tplOf(n).length);
    // 手动模式：最近几轮（存档里还留着的那些楼层）记过状态的人都要有条目。
    // 很久没出场的路人不留条目：她的关系阶段照样记在状态里，再出场时条目会跟着回来
    const pickNames = (s) => {
      let extra = [];
      if (c.关系阶段调整 === '手动' && s && s.chars) {
        const recent = new Set();
        const floors = loadStore().floors;
        Object.keys(floors).forEach((k) => { ((floors[k] && floors[k].order) || []).forEach((n) => recent.add(n)); });
        extra = Object.keys(s.chars).filter((n) => recent.has(n));
      }
      return tplNames.concat(extra.filter((n) => tplNames.indexOf(n) === -1));
    };
    let names = pickNames(latestState(loadStore(), null));
    let bookName = null;
    try { bookName = getChatWorldbookName('current'); } catch (e) { return { skipped: true }; }
    // 没用模板、这个聊天也还没有世界书时，不为了删东西去新建一本
    if (!names.length && !bookName) return { written: 0, removed: 0 };
    const book = bookName || await getOrCreateChatWorldbook('current', newBookName());
    if (moved()) return { skipped: true };

    const entries = await getWorldbook(book);
    if (moved()) return { skipped: true };
    // 这本书里没有手账本的条目、也没人要写：不动它（这本书可能是玩家自己的设定书）
    if (!names.length && !entries.some((e) => String(e.name || '').indexOf(BOOK_PREFIX) === 0)) return { written: 0, removed: 0, book };
    // 等世界书的这一会儿可能又落了一楼：从这里起按最新的存档算
    const st = latestState(loadStore(), null);
    names = pickNames(st);
    const sig = loadStore().meta.bookSig || {};
    // 书里每一条写过的「手账本-」都收一遍手改：这次要收掉的条目（比如从手动切回自动）也先把改动收进存档
    const edits = {};
    entries.forEach((e) => {
      const nm = String(e.name || '');
      if (nm.indexOf(BOOK_PREFIX) !== 0) return;
      const n = nm.slice(BOOK_PREFIX.length);
      if (sig[n]) edits[n] = parseEntryEdits(e.content);
    });
    const chars = st && st.chars ? cloneChars(st.chars) : {};
    let adopted = false;
    Object.keys(edits).forEach((n) => {
      if (chars[n]) adopted = adoptEdits(chars[n], edits[n], sig[n], st.floor) || adopted;
    });

    const contents = {};
    const notes = personNotes();                       // 设置里写的补充（只管这个聊天）
    const newSig = {};
    names.forEach((n) => {
      const ch = chars[n] || null;
      contents[n] = buildEntryContent(n, tplOf(n), ch, notes[n]);
      newSig[n] = { level: ch ? ch.level : '平稳', rel: ch ? Object.fromEntries(Object.keys(ch.rel).map((to) => [to, ch.rel[to].stage])) : {} };
    });
    // 条目里用到、还没改写成档案（或者是照旧规则整理、没手改过）的模板：后台改写，改好一本就再写一遍书
    const raw = [];
    names.forEach((n) => tplOf(n).forEach((t) => { if (plainNeeds(t) && raw.indexOf(t) === -1) raw.push(t); }));
    if (raw.length && String(c.副API地址 || '').trim() && String(c.副模型 || '').trim()) {
      raw.forEach((t) => makePlain(t, c).then((p) => { if (p && !DISPOSED && chatId === currentChatId()) scheduleBookWrite(); }));
    }

    const present = st ? (st.order || []).filter((n) => onStage(st.people[n])) : [];
    const missing = names.filter((n) => !entries.some((x) => x.name === entryName(n)));
    // 和书里现在的一样（内容、触发方式、关键词都没变，也没有要收掉的）就不写：每落一楼都会走到这里
    const keyStr = (ks) => (ks || []).map(String).join('\n');
    const same = (e) => {
      const who = e.name.slice(BOOK_PREFIX.length);
      if (names.indexOf(who) === -1) return false;
      const want = bookStrategy(who, roster, present, e.strategy);
      return e.content === contents[who] && e.strategy && e.strategy.type === want.type && keyStr(e.strategy.keys) === keyStr(want.keys);
    };
    const ours = entries.filter((e) => String(e.name || '').indexOf(BOOK_PREFIX) === 0);
    if (!missing.length && ours.every(same) && !adopted) {
      const store0 = loadStore();
      store0.meta.bookSig = newSig;
      store0.meta.book = book;
      saveStore(store0);
      return { written: names.length, removed: 0, adopted: false, book, unchanged: true };
    }
    if (moved()) return { skipped: true };
    if (missing.length) {
      await createWorldbookEntries(book, missing.map((n) => ({
        name: entryName(n),
        enabled: true,
        strategy: bookStrategy(n, roster, present, {}),
        position: { type: 'after_character_definition', order: 150 },
        recursion: { prevent_incoming: true, prevent_outgoing: true, delay_until: null },
        content: contents[n],
      })));
    }
    if (moved()) return { skipped: true };
    let removed = 0;
    await updateWorldbookWith(book, (wb) => {
      const keep = wb.filter((e) => {
        if (String(e.name || '').indexOf(BOOK_PREFIX) !== 0) return true;
        const who = e.name.slice(BOOK_PREFIX.length);
        if (names.indexOf(who) !== -1) return true;
        removed += 1;                                        // 不再用模板的人（手动模式下是没记过状态的人），条目收掉
        return false;
      });
      keep.forEach((e) => {
        const who = String(e.name || '').indexOf(BOOK_PREFIX) === 0 ? e.name.slice(BOOK_PREFIX.length) : null;
        if (who && contents[who] != null) {
          e.content = contents[who];
          e.strategy = bookStrategy(who, roster, present, e.strategy);
        }
      });
      return keep;
    });

    if (moved()) return { skipped: true };
    // 存档只动两处：签名，和收回来的手改。写世界书期间落了新楼层也不会被盖掉
    const store = loadStore();
    const target = st ? store.floors[st.floor] : null;
    if (adopted && target && String(target.sd || '') === String(st.sd || '') && target.chars) {
      // 现在挂着的是「记到最新」的那份：下一轮拿它底下玩家那一楼的正式的状态当底，手改记到那份上再顺着重算，不然下一轮就丢了
      const base = target.tail ? statesBefore(store, st.floor, 1)[0] : null;
      const into = base && base.chars ? base : target;
      Object.keys(edits).forEach((n) => { if (into.chars[n]) adoptEdits(into.chars[n], edits[n], sig[n], into.floor); });
      if (Object.keys(store.floors).some((k) => Number(k) > into.floor)) refoldChars(store, into.floor + 1, c);
      // 只在「记到最新」这份里出现的人，底下那份没有她，只能记在这份上
      if (into !== target) Object.keys(edits).forEach((n) => { if (!into.chars[n] && target.chars[n]) adoptEdits(target.chars[n], edits[n], sig[n], st.floor); });
    }
    store.meta.bookSig = newSig;
    store.meta.book = book;
    saveStore(store);
    if (adopted) {
      const now = reinject();
      BUS.emit('state', now);
    }
    return { written: names.length, removed, adopted, book };
  }

  // 清空这个聊天的状态时：聊天世界书里的「手账本-」条目都删掉，别的条目不动。返回删了几条
  async function removeBookEntries() {
    let book = null;
    try { book = getChatWorldbookName('current'); } catch (e) { return 0; }
    if (!book || typeof updateWorldbookWith !== 'function') return 0;
    const entries = await getWorldbook(book);
    if (!entries.some((e) => String(e.name || '').indexOf(BOOK_PREFIX) === 0)) return 0;
    let removed = 0;
    await updateWorldbookWith(book, (wb) => wb.filter((e) => {
      if (String(e.name || '').indexOf(BOOK_PREFIX) !== 0) return true;
      removed += 1;
      return false;
    }));
    return removed;
  }

  // 旧版建聊天世界书时没起名，书叫「Chat_Book_…」。书里只有手账本自己的条目时，换成「手账本-卡名」：
  // 建新书、条目原样搬过去、这个聊天改绑新书，再删掉旧书。
  // 书里还有别的条目（玩家自己写的、别的插件写的），或者这本书同时挂在全局、角色卡上，就不动，照旧往里写
  async function renameOwnBook(book, entries, chatId) {
    if (!book || book.indexOf(BOOK_PREFIX) === 0) return book;
    if (typeof rebindChatWorldbook !== 'function' || typeof createWorldbook !== 'function') return book;
    if (!entries.length || !entries.every((e) => String(e.name || '').indexOf(BOOK_PREFIX) === 0)) return book;
    try { if ((getGlobalWorldbookNames() || []).indexOf(book) !== -1) return book; } catch (e) { /* ignore */ }
    try {
      const cb = getCharWorldbookNames('current') || {};
      if (cb.primary === book || (cb.additional || []).indexOf(book) !== -1) return book;
    } catch (e) { /* ignore */ }
    const name = newBookName();
    if (!(await createWorldbook(name, entries))) return book;
    if (DISPOSED || chatId !== currentChatId()) return book;
    await rebindChatWorldbook('current', name);
    try { if (typeof deleteWorldbook === 'function') await deleteWorldbook(book); } catch (e) { warn('旧的聊天世界书没删掉：', e); }
    log('聊天世界书改名：' + book + ' → ' + name);
    return name;
  }

  // 旧版写的「手账本-」条目带着关键词或常驻，酒馆会自己激活它（别的插件调模型时也会）。
  // 打开聊天就改一次，不看「自动写入世界书」开没开：这只改触发方式，不改内容。书名是旧版起的就顺手换掉
  async function migrateBookEntries() {
    try {
      const chatId = currentChatId();
      let book = null;
      try { book = getChatWorldbookName('current'); } catch (e) { return false; }
      if (!book || typeof updateWorldbookWith !== 'function') return false;
      let entries = await getWorldbook(book);
      if (DISPOSED || chatId !== currentChatId()) return false;
      const renamed = await renameOwnBook(book, entries, chatId);
      const moved = renamed !== book;
      if (moved) { book = renamed; entries = await getWorldbook(book); }
      const stale = (e) => String(e.name || '').indexOf(BOOK_PREFIX) === 0 && e.strategy &&
        (e.strategy.type !== 'selective' || (Array.isArray(e.strategy.keys) && e.strategy.keys.length));
      if (DISPOSED || chatId !== currentChatId() || !entries.some(stale)) return moved;
      await updateWorldbookWith(book, (wb) => wb.map((e) => (stale(e) ? Object.assign({}, e, { strategy: Object.assign({}, e.strategy, { type: 'selective', keys: [] }) }) : e)));
      return true;
    } catch (e) {
      warn('整理旧的聊天世界书失败：', e);
      return false;
    }
  }

  // 排队写，连着几次只写最后一次；上一次没写完不会叠着写
  function writeBook(force) {
    const job = _bookChain.then(() => writeBookNow(force)).catch((e) => {
      warn('写世界书失败：', e);
      return { error: e && e.message ? e.message : String(e) };
    });
    _bookChain = job.then(() => {}, () => {});
    return job;
  }

  // 和写世界书排同一个队：迁移、改名这类动书的活不能和 writeBookNow 同时跑（改名会删旧书）
  function queueBookJob(fn) {
    const job = _bookChain.then(() => fn()).catch((e) => { warn('整理聊天世界书失败：', e); return false; });
    _bookChain = job.then(() => {}, () => {});
    return job;
  }

  function scheduleBookWrite() {
    if (_bookTimer) clearTimeout(_bookTimer);
    _bookTimer = setTimeout(() => { _bookTimer = null; writeBook(false); }, 1200);
  }

  function cancelBookWrite() {
    if (_bookTimer) clearTimeout(_bookTimer);
    _bookTimer = null;
  }

  // ======================== 导演稿 ========================
  // 开着时手账本是这一轮的总控：数据库只管读正文填表，它写进世界书的记忆、这张卡的剧情推进交出来的东西，
  // 都由手账本收走，让模型写成一份《导演稿》，连同此刻状态一起放进玩家这一轮交给正文。
  //   · 世界书照常扫、照常激活；激活了哪些，从 world_info_activated 拿
  //   · 提示词拼好（chat_completion_prompt_ready，酒馆会等监听器跑完）时：
  //       收走数据库条目的原文（「连设定一起」时连设定）→ 玩家这一轮换成「原话 + 导演稿 + 此刻状态」→ 挂状态的那一块只留读法说明
  //   · 聊天记录里玩家那条还原成原话：数据库填表会原样读玩家消息，剧情推进的那一大段和导演稿都不能留在里面。
  //     剧情推进交出来的东西另存一份（按楼层），重新生成时还要用
  //   · 写不成（出错、超过 600 秒、点了停止、换了聊天）：这一轮提示词和聊天记录都不动，正文照老样子读
  // 只管聊天补全接口：文本补全拼出来的是一整段字符串，不接管
  const DIRECTOR_MODES = ['关', '只接管记忆', '连设定一起'];
  const DIRECTOR_MAX_MS = 600000;
  const BRIEF_CACHE_MAX = 20;
  const MEMO_BY_CODE_MAX = 20;                  // 剧情推进点到的纪要，最多查这么多条原文
  const WI_AT_DEPTH = 4;                       // 酒馆世界书「按深度插入」的位置编号
  const PLOT_WRAP = /<本轮用户输入>([\s\S]*?)<\/本轮用户输入>/;
  const PLOT_KEY = NS + '_plot';               // 聊天变量：每层剧情推进交出来的东西（只留最近 5 层）

  let _activated = null;                        // 这一次正文生成激活了的世界书条目
  const _briefCache = new Map();                // 同样的材料（重新生成、换一条）不再写一遍
  let lastBrief = null;                         // 面板和日志用
  let _stopDirector = null;                     // 正在写的这一次：点停止、换聊天时叫停

  const GUIDE_DIRECTOR = `<导演稿读法>
这一轮玩家的消息里，玩家原话后面跟着一份 <导演稿> 和一块 <当前状态>。它们都是填表员整理的，不是玩家说的话。
· <导演稿>：从记忆库、剧情推进和设定里挑出的事实。它写着现在的时间和地点，已经发生的事，人物现况，没了结的事，背景设定。有时还有剧情推进给的这一轮走向，标题是「推进」。已经发生的事以它为准，不和它矛盾。它没写到的，按上文和角色卡照常写，不自己编一段过去。
· <导演稿> 里的「重要对话」是以前真说过的原话。角色提起以前说过的话时，只用这几句原文。这里没有的话，不替谁编。
· <导演稿> 里的「平行线」是玩家不在场、别处同时在演的另一条线。它写着在哪，谁在，那边发生过什么。写到那条线时照它写。玩家不知道这些。回到玩家这边时，不写玩家知道那边的事。
· <当前状态>：每个人此刻的状态。读法见下面的《手账本读法》。那里说它在玩家消息的前面；这一轮它在玩家消息里面，读法一样。
· 不把 <导演稿> 的字句照抄进正文，「重要对话」里的原话除外。正文里不出现「导演稿」这个词。
</导演稿读法>`;

  // 读法说明里讲剧情推进标签的那一句：开着导演稿时这些标签已经整理进导演稿了，换成指向导演稿的说法
  const GUIDE_RECALL_DIRECTOR = '· 剧情推进交出来的旧事和背景设定，这一轮已经整理进 <导演稿>，不会再单独出现 <recall>、<supplement> 这样的块。';

  // 玩家这一轮交给正文的样子：原话在最前面，后面是手账本的输出提示词、导演稿、此刻状态
  // 样子写在「手账本输出提示词」里（13_prompts.js），可以在面板「提示词」页改
  function directorTurn(raw, brief, stateText) { return fillDirectorTurn(raw, brief, stateText); }

  // 世界书扫完：只记正文生成这一次的。开窗时清掉，免得拿到上一次的
  function onWorldInfoActivated(entries) {
    if (DISPOSED || !isMainGeneration()) return;
    _activated = Array.isArray(entries) ? entries.slice() : null;
  }

  function resetActivated() { _activated = null; }

  function stopDirector(why) { if (_stopDirector) _stopDirector(why); }

  // 哪些条目收走：数据库写的一律收；「连设定一起」时别的设定条目也收。手账本自己的条目不收
  function takeOver(e, mode) {
    const name = String((e && e.comment) || '');
    if (/^手账本-/.test(name)) return false;
    if (isDbLore(name)) return true;
    return mode === '连设定一起';
  }

  // 条目进提示词时酒馆会先套一遍世界书范围的正则；套过和没套过的都试着找
  function insertedForms(e) {
    const raw = String((e && e.content) || '');
    const out = [];
    try {
      if (typeof formatAsTavernRegexedString === 'function') {
        const opt = e.position === WI_AT_DEPTH ? { depth: e.depth == null ? 4 : e.depth } : {};
        const f = formatAsTavernRegexedString(raw, 'world_info', 'prompt', opt);
        if (f) out.push(f);
      }
    } catch (err) { /* 旧版酒馆助手没有这个函数 */ }
    if (raw && out.indexOf(raw) === -1) out.push(raw);
    return out.filter((t) => t.trim());
  }

  // 消息里能改的文字：字符串内容就是它自己；分段的内容（带图片的消息）取其中的文字段
  function textSlots(m) {
    if (!m) return [];
    if (typeof m.content === 'string') return [{ get: () => m.content, set: (t) => { m.content = t; } }];
    if (Array.isArray(m.content)) {
      return m.content.filter((p) => p && typeof p.text === 'string').map((p) => ({ get: () => p.text, set: (t) => { p.text = t; } }));
    }
    return [];
  }

  function messageText(m) { return textSlots(m).map((s) => s.get()).join('\n'); }

  // 世界书条目是一条一行拼进去的：先找单独成行的那一处，找不到才退回第一处
  function findCut(text, t) {
    let loose = -1;
    for (let i = text.indexOf(t); i !== -1; i = text.indexOf(t, i + 1)) {
      if (loose === -1) loose = i;
      const head = i === 0 || text[i - 1] === '\n';
      const tail = i + t.length === text.length || text[i + t.length] === '\n';
      if (head && tail) return { i, whole: true };
    }
    return loose === -1 ? null : { i: loose, whole: false };
  }

  // 世界书内容多半落在系统消息里：先在系统消息里找，找不到再看别的，免得从聊天记录里误删一段一样的字
  function cutFrom(chat, forms) {
    const order = chat.filter((m) => m && m.role === 'system').concat(chat.filter((m) => m && m.role !== 'system'));
    const cut = (hit, t) => {
      const s = hit.slot.get();
      hit.slot.set(s.slice(0, hit.i) + s.slice(hit.i + t.length));
      hit.m._hbCut = true;
      return true;
    };
    for (const t of forms) {
      let loose = null;
      for (const m of order) {
        for (const slot of textSlots(m)) {
          const f = findCut(slot.get(), t);
          if (!f) continue;
          if (f.whole) return cut({ m, slot, i: f.i }, t);
          if (!loose) loose = { m, slot, i: f.i };
        }
      }
      if (loose) return cut(loose, t);
    }
    return false;
  }

  // 剧情推进把玩家那条改写过：拆成玩家原话和它交出来的东西。各张卡的推进写法不一样，不认具体标签：
  //   · 有 <本轮用户输入> 外壳（数据库自带的两套任务都这么写）：壳里是原话，壳外都算推进的
  //   · 没有外壳：原话用生成前拍下的那句，消息里除掉原话的部分都算推进的；原话整句都被改写了，整条都算推进的
  function splitPlot(mes, captured) {
    const s = String(mes || '');
    const cap = String(captured || '').trim();
    const m = s.match(PLOT_WRAP);
    if (m) {
      let head = s.slice(0, m.index).trim();
      if (head.length <= 40 && /[:：]$/.test(head)) head = '';   // 「以下是用户的本轮输入：」这种引子不算
      return { raw: cap || m[1].trim(), plot: (head + '\n' + s.slice(m.index + m[0].length)).trim() };
    }
    if (!cap || s.trim() === cap) return { raw: s.trim(), plot: '' };
    const i = s.indexOf(cap);
    if (i !== -1) return { raw: cap, plot: (s.slice(0, i) + s.slice(i + cap.length)).trim() };
    return { raw: cap, plot: s.trim() };
  }

  // 剧情推进把 <本轮用户输入> 外壳写进了更早的玩家消息（导演稿还没开的时候留下的）：只留原话；名字前缀照留
  function unwrapPlot(content, userName) {
    const s = String(content || '');
    const m = s.match(PLOT_WRAP);
    if (!m) return null;
    const pre = userName && s.indexOf(userName + ': ') === 0 ? userName + ': ' : '';
    return pre + m[1].trim();
  }

  function savePlot(floor, sd, text) {
    try {
      updateVariablesWith((vars) => {
        const all = vars[PLOT_KEY] && typeof vars[PLOT_KEY] === 'object' ? vars[PLOT_KEY] : {};
        all[floor] = { sd: String(sd || ''), text: String(text || '') };
        Object.keys(all).map(Number).sort((a, b) => b - a).slice(5).forEach((k) => { delete all[k]; });
        vars[PLOT_KEY] = all;
        return vars;
      }, { type: 'chat' });
    } catch (e) { warn('剧情推进的内容没存上：', e); }
  }

  function loadPlot(floor, sd) {
    try {
      const v = getVariables({ type: 'chat' }) || {};
      const p = v[PLOT_KEY] && v[PLOT_KEY][floor];
      return p && p.sd === String(sd || '') ? String(p.text || '') : '';
    } catch (e) { return ''; }
  }

  function lastOfRole(chat, role) {
    for (let i = chat.length - 1; i >= 0; i -= 1) {
      const m = chat[i];
      if (m && m.role === role && textSlots(m).length) return { m, i, text: messageText(m) };
    }
    return null;
  }

  // 这一轮的状态还没记完就等它：导演稿要带上这一轮的「此刻」
  function waitThisRun(deadline) {
    const run = lastRun;
    if (!run || run.done || run.chatId !== currentChatId()) return Promise.resolve();
    const left = deadline - Date.now();
    return left > 0 ? Promise.race([run.ready.catch(() => {}), sleep(left)]) : Promise.resolve();
  }

  // 聊天记录里玩家最新那一条：原话、剧情推进交出来的东西、要不要还原
  function thisTurn() {
    const chat = chatNow();
    const floor = latestUserFloor();
    const m = floor >= 0 ? chat[floor] : null;
    if (!m) return null;
    const run = lastRun && lastRun.floor === floor && String(lastRun.sd) === String(m.send_date) ? lastRun : null;
    const sp = splitPlot(m.mes, run && run.input);
    const saved = sp.plot ? '' : loadPlot(floor, m.send_date);
    return { floor, sd: m.send_date, mes: String(m.mes || ''), raw: sp.raw, plot: sp.plot || saved, fresh: !!sp.plot };
  }

  const memoLine = (r) => [r['编码索引'], r['时间跨度'], r['地点'], r['纪要'] || r['概览'] || r['概要'], r['重要对话']]
    .map((x) => String(x || '').trim()).filter(Boolean).join('｜');

  // 文本补全的提示词里分不出哪段是正文：最近一段正文从聊天记录里取
  function lastAiText() {
    const ch = chatNow();
    for (let i = ch.length - 1; i >= 0; i -= 1) {
      const m = ch[i];
      if (m && !m.is_user && !m.is_system && m.mes) return stripFunctionBlocks(m.mes);
    }
    return '';
  }

  function directorMaterials(chat, sel, turn, c) {
    const st = stateForGeneration();
    const userName = readPersona().name;
    const a = lastOfRole(chat, 'assistant');
    const pack = (list) => list.map((e) => ({ name: String(e.comment || '（没有名字的条目）'), text: String(e.content || '') }))
      .filter((e) => e.text.trim());
    const db = pack(sel.filter((e) => isDbLore(String(e.comment || ''))));
    // 剧情推进点到的纪要编码：世界书里激活了的就在上面；没激活的（玩家消息还原成原话以后编码不在扫描文本里）去纪要表里查原文
    const plot = turn ? turn.plot : '';
    const codes = Array.from(new Set(plot.match(/AM\d{3,}/g) || []));
    const have = db.map((e) => e.text).join('\n');
    memoRowsByCodes(codes.filter((k) => have.indexOf(k) === -1), MEMO_BY_CODE_MAX)
      .forEach((r) => db.push({ name: '纪要 ' + r['编码索引'], text: memoLine(r) }));
    let input = turn ? turn.raw : '';
    if (userName && input.indexOf(userName + ': ') === 0) input = input.slice(userName.length + 2);
    let today = '';
    if (c && c.读数据库) { try { const d = readDatabase(null); today = d ? todayOf(d.global).text : ''; } catch (e) { today = ''; } }
    // 数据库算不出星期几时，用场面那一路这一场记下的
    const wd = st && st.scene && st.scene.weekday ? String(st.scene.weekday) : '';
    if (wd && today.indexOf(wd) === -1 && !/(星期|周|礼拜)[一二三四五六日天]/.test(today)) today = today ? today + '（' + wd + '）' : wd;
    return {
      today,
      db,
      settings: pack(sel.filter((e) => !isDbLore(String(e.comment || '')))),
      plot,
      scene: (st && st.scene) || null,
      cast: st ? (st.order || []).filter((n) => st.people && st.people[n] && st.people[n].inScene !== false) : [],
      away: st ? (st.order || []).filter((n) => st.people && st.people[n] && st.people[n].inScene === false && st.people[n].parallel === true) : [],
      player: userName,
      input,
      recent: a ? stripFunctionBlocks(a.text) : lastAiText(),
    };
  }

  // 「重要对话」只留材料里真有的：原话去掉标点和空白后，要能在材料里原样找到（中间用省略号略过的，每一段都要找得到）。
  // 模型编的、改过字的整句丢掉；说话的人材料里找不到（全名、名册里的别名都算），就不写是谁说的，免得把话安到别人头上
  const LINES_MAX = 8;
  function nameForms(who) {
    const r = _rosterFull && _rosterFull.base === _roster ? _rosterFull : _roster;
    const alias = (r && r.alias) || {};
    const main = alias[who] || who;
    return [who, main].concat(Object.keys(alias).filter((a) => alias[a] === main));
  }

  function keepLines(lines, hay) {
    const H = norm(hay);
    const kept = [];
    let dropped = 0;
    (Array.isArray(lines) ? lines : []).forEach((x) => {
      if (!x || typeof x !== 'object') return;
      const text = String(x.text || '').trim().replace(/^[「『“"]+|[」』”"]+$/g, '');
      const parts = text.split(/…+|\.{3,}|⋯+/).map(norm).filter((p) => p.length >= 2);
      const found = parts.length && parts.join('').length >= 4 && parts.every((p) => H.indexOf(p) !== -1);
      if (!found || kept.length >= LINES_MAX) { if (!found && text) dropped += 1; return; }
      const who = String(x.who || '').trim();
      const named = who && nameForms(who).some((n) => norm(n).length >= 2 && H.indexOf(norm(n)) !== -1);
      kept.push({ who: named ? who : '', text, when: String(x.when || '').trim() });
    });
    return { lines: kept, dropped };
  }

  function renderBrief(d) {
    if (!d || typeof d !== 'object') return '';
    const list = (x) => (Array.isArray(x) ? x : []).map((s) => String(s || '').trim()).filter(Boolean);
    const L = [];
    const now = String(d.now || '').trim();
    if (now) L.push('现在｜' + now);
    const ev = list(d.events);
    if (ev.length) L.push('已经发生的事（从早到晚）：\n' + ev.map((s) => '· ' + s).join('\n'));
    const said = (Array.isArray(d.lines) ? d.lines : []).filter((x) => x && String(x.text || '').trim());
    if (said.length) {
      L.push('重要对话（原文）：\n' + said.map((x) => '· ' + (x.who ? x.who + '：' : '') +
        '「' + String(x.text).trim() + '」' + (x.when ? '（' + x.when + '）' : '')).join('\n'));
    }
    // 平行线上的人的现况放进平行线那一块，别和玩家这一场的人列在一起
    const par = (Array.isArray(d.parallel) ? d.parallel : []).slice(0, 2).map((x) => ({
      place: String((x && x.place) || '').trim(), who: list(x && x.present), ev: list(x && x.events),
    })).filter((x) => x.place || x.who.length || x.ev.length);
    const ppl = (Array.isArray(d.people) ? d.people : [])
      .map((p) => ({ name: String((p && p.name) || '').trim(), facts: String((p && p.facts) || '').trim() }))
      .filter((p) => p.name && p.facts);
    const lineOf = (n) => par.findIndex((x) => x.who.indexOf(n) !== -1);
    const here = ppl.filter((p) => lineOf(p.name) === -1);
    if (here.length) L.push('在场的人：\n' + here.map((p) => '〔' + p.name + '〕' + p.facts).join('\n'));
    const op = list(d.open);
    if (op.length) L.push('没了结的事：\n' + op.map((s) => '· ' + s).join('\n'));
    const se = list(d.setting);
    if (se.length) L.push('背景设定：\n' + se.map((s) => '· ' + s).join('\n'));
    if (par.length) {
      L.push('平行线（玩家不在场）：\n' + par.map((x, i) => '〔' + (x.place || '别处') + '〕' + (x.who.length ? '在场：' + x.who.join('、') : '') +
        ppl.filter((p) => lineOf(p.name) === i).map((p) => '\n' + p.name + '｜' + p.facts).join('') +
        x.ev.map((s) => '\n· ' + s).join('')).join('\n'));
    }
    const pl = list(d.plan);
    if (pl.length) L.push('推进：\n' + pl.map((s) => '· ' + s).join('\n'));
    if (!L.length) return '';
    return '<导演稿>\n' + L.join('\n') + '\n</导演稿>';
  }

  async function writeBrief(mat, c, deadline, live, signal) {
    let dropped = [];
    let plotCut = 0;
    const conn = directorConn(c);
    const once = (lite) => {
      if (!live()) throw new Error('停下了');
      const left = deadline - Date.now();
      if (left < 1000) throw new Error('等了 ' + Math.round(DIRECTOR_MAX_MS / 1000) + ' 秒还没写完');
      const built = buildDirectorContent(mat, lite);
      dropped = built.dropped;
      plotCut = built.plotCut || 0;
      // 会思考的模型要留够字数：思考也占 max_tokens 的那些接口，4000 不够
      return callSide(promptText('写导演稿的规则'), built.text, DIRECTOR_SCHEMA, 'handbook_director',
        { cfg: conn, maxTokens: 16000, hardTimeout: left, until: deadline, signal, priority: 'high', label: '导演稿' + (lite ? '（短材料）' : '') });
    };
    let res;
    try {
      res = await once(false);
    } catch (e) {
      if (!e || !e.filtered) throw e;
      res = await once(true);                    // 被内容审查拦下：换短材料再试一次
    }
    const data = res.data && typeof res.data === 'object' ? res.data : {};
    const hay = (mat.db || []).concat(mat.settings || []).map((e) => e.text).concat([mat.plot || '']).join('\n');
    const said = keepLines(data.lines, hay);
    data.lines = said.lines;
    return { text: renderBrief(data), ms: res.ms, dropped, plotCut, lines: said.lines.length, fakeLines: said.dropped };
  }

  // 挂状态的那一块（读法说明 + <当前状态>）：状态挪进玩家这一轮了，这里只留读法说明；读法说明关着就整块拿掉
  function placeGuide(chat, guide) {
    for (const m of chat) {
      if (!m || m.role !== 'system' || typeof m.content !== 'string') continue;
      const s = m.content.indexOf('<当前状态>\n');
      if (s === -1) continue;
      const e = m.content.indexOf('</当前状态>', s);
      if (e === -1) continue;
      const g = m.content.indexOf('<手账本读法>');
      const from = g !== -1 && g < s ? g : s;
      m.content = m.content.slice(0, from) + guide + m.content.slice(e + '</当前状态>'.length);
      m._hbCut = true;
      return 'replaced';
    }
    if (!guide) return 'none';
    // 文本补全：玩家这一轮前面紧挨着「名字: 」这类前缀，插在那里会拆开它，放到整段最前面
    if (chat.length && chat[0]._hbText) { chat.unshift({ role: 'system', content: guide }); return 'inserted'; }
    const u = lastOfRole(chat, 'user');
    chat.splice(u ? u.i : chat.length, 0, { role: 'system', content: guide });
    return 'inserted';
  }

  function applyBriefNow(chat, sel, brief, turn, stateText, c) {
    const missed = [];
    let cut = 0;
    sel.forEach((e) => { if (cutFrom(chat, insertedForms(e))) cut += 1; else missed.push(String(e.comment || '')); });
    const userName = readPersona().name;
    // 玩家这一轮：原话 + 导演稿 + 此刻状态
    const u = lastOfRole(chat, 'user');
    if (!u) throw new Error('提示词里找不到玩家这一轮');
    const pre = userName && u.text.indexOf(userName + ': ') === 0 ? userName + ': ' : '';
    let raw = turn ? turn.raw : '';
    if (!raw) raw = extractRawInput(u.text);
    if (pre && raw.indexOf(pre) === 0) raw = raw.slice(pre.length);
    const slots = textSlots(u.m);
    slots[0].set(pre + directorTurn(raw, brief, stateText));
    for (let k = 1; k < slots.length; k += 1) slots[k].set('');   // 带图片的消息：文字并进第一段，图片留着
    // 更早的玩家消息里剧情推进留下的外壳：只留原话
    let unwrapped = 0;
    chat.forEach((m) => {
      if (!m || m.role !== 'user' || m === u.m) return;
      textSlots(m).forEach((slot) => {
        const r = unwrapPlot(slot.get(), userName);
        if (r != null) { slot.set(r); unwrapped += 1; }
      });
    });
    // 文本补全：更早的玩家消息都在前文那一段里，按聊天记录里的原样找到再换成原话
    if (chat.some((m) => m && m._hbText)) {
      const latest = turn ? turn.floor : -1;
      chatNow().forEach((m, i) => {
        if (!m || !m.is_user || i === latest) return;
        const mes = String(m.mes || '');
        const r = mes ? unwrapPlot(mes, userName) : null;
        if (r == null) return;
        chat.forEach((x) => {
          if (x && x.role === 'system' && typeof x.content === 'string' && x.content.indexOf(mes) !== -1) {
            x.content = x.content.split(mes).join(r);
            unwrapped += 1;
          }
        });
      });
    }
    const how = placeGuide(chat, c.注入读法说明
      ? promptText('导演稿读法') + '\n\n' + promptText('读法说明').replace(GUIDE_RECALL_LINE, GUIDE_RECALL_DIRECTOR) : '');
    // 收走条目以后整条空掉的消息删掉（有的接口不收空消息），多出来的空行收一收；带图片的消息不删
    for (let i = chat.length - 1; i >= 0; i -= 1) {
      const m = chat[i];
      if (!m || !m._hbCut) continue;
      delete m._hbCut;
      textSlots(m).forEach((slot) => slot.set(slot.get().replace(/\n{3,}/g, '\n\n')));
      if (typeof m.content === 'string' && !m.content.trim()) chat.splice(i, 1);
    }
    return { cut, missed, unwrapped, how };
  }

  // 改到一半出错就整份还原：酒馆发出去的就是这个数组，不能留半截
  function applyBrief(chat, sel, brief, turn, stateText, c) {
    const msgs = chat.slice();
    const saved = msgs.map((m) => {
      if (!m) return null;
      return Array.isArray(m.content) ? m.content.map((p) => (p && typeof p.text === 'string' ? p.text : null)) : m.content;
    });
    try {
      return applyBriefNow(chat, sel, brief, turn, stateText, c);
    } catch (e) {
      chat.length = 0;
      msgs.forEach((m, i) => {
        if (m) {
          try {
            delete m._hbCut;
            if (Array.isArray(m.content) && Array.isArray(saved[i])) m.content.forEach((p, k) => { if (saved[i][k] != null) p.text = saved[i][k]; });
            else if (m.content !== saved[i]) m.content = saved[i];
          } catch (err) { /* 这一条还原不了就算了，别的照样还原 */ }
        }
        chat.push(m);
      });
      throw e;
    }
  }

  // 聊天记录里玩家那条还原成原话，剧情推进交出来的东西另存。
  // 数据库填表会原样读玩家消息（对玩家消息不做任何过滤），留着那一大段它就会把召回、设定当成这一轮发生的事记下来
  // 返回 true = 还原了；false = 不用还原；null = 该还原却没还原成
  async function restoreTurn(turn) {
    if (!turn || !turn.fresh || turn.mes === turn.raw) return false;
    savePlot(turn.floor, turn.sd, turn.plot);
    try {
      if (typeof setChatMessages === 'function') {
        await setChatMessages([{ message_id: turn.floor, message: turn.raw }], { refresh: 'affected' });
        return true;
      }
    } catch (e) {
      warn('玩家那条没还原成原话：', e);
    }
    return null;
  }

  function rememberBrief(key, brief) {
    _briefCache.delete(key);
    _briefCache.set(key, brief);
    while (_briefCache.size > BRIEF_CACHE_MAX) _briefCache.delete(_briefCache.keys().next().value);
  }

  // 面板只看这个聊天的那份：换了聊天，上一个聊天的稿子（和还在收尾的那次）都不显示
  function briefNow() {
    return lastBrief && lastBrief.chatId === currentChatId() ? lastBrief : null;
  }

  function briefFailed(why, t0, loud, chatId) {
    lastBrief = { ok: false, why, at: Date.now(), ms: Date.now() - t0, chatId };
    if (loud) {
      warn('导演稿没写成，这一轮照原样交给正文：' + why);
      try { toastr.warning('导演稿没写成，这一轮照原样交给正文：' + why); } catch (e) { /* ignore */ }
    }
    BUS.emit('brief', lastBrief);
    return lastBrief;
  }

  // 返回这一轮做了什么（测试和日志用）；不接管时返回 null
  // 文本补全的提示词是一整段字：按玩家这一轮切成前文、玩家这一轮、后文三条，交给和聊天补全同一套的收条目、换稿子，改完拼回去。
  // 玩家这一轮按聊天记录里那条原样找（最后一处），找不到再按原话找；都找不到，整段当一条，换稿子时会报「找不到玩家这一轮」、不接管
  function splitTextPrompt(prompt) {
    const turn = thisTurn();
    const tries = [turn && turn.mes, turn && turn.raw].map((t) => String(t || '').trim()).filter((t) => t.length >= 2);
    for (const t of tries) {
      const i = prompt.lastIndexOf(t);
      if (i === -1) continue;
      return [{ role: 'system', content: prompt.slice(0, i), _hbText: true }, { role: 'user', content: t, _hbText: true },
        { role: 'system', content: prompt.slice(i + t.length), _hbText: true }];
    }
    return [{ role: 'system', content: prompt, _hbText: true }];
  }

  function joinTextPrompt(chat) {
    return chat.map((m) => (m._hbText ? m.content : m.content + '\n\n')).join('');
  }

  async function runDirector(data, c) {
    if (data && !Array.isArray(data.chat) && typeof data.prompt === 'string') {
      const parts = splitTextPrompt(data.prompt);
      const res = await runDirectorOn(parts, c);
      if (res && res.ok) data.prompt = joinTextPrompt(parts);
      return res;
    }
    return runDirectorOn(data && Array.isArray(data.chat) ? data.chat : null, c);
  }

  async function runDirectorOn(chat, c) {
    const acts = _activated || [];
    _activated = null;
    if (!chat || DIRECTOR_MODES.indexOf(c.导演稿) < 1) return null;
    const sel = acts.filter((e) => takeOver(e, c.导演稿));
    let turn = thisTurn();
    // 聊天记录里那条和提示词里的对不上（比如别的脚本改过提示词）：剧情推进的内容以提示词里的为准，原话照旧
    const pu = lastOfRole(chat, 'user');
    if (pu && !(turn && turn.plot) && PLOT_WRAP.test(pu.text)) {
      const sp = splitPlot(pu.text.replace(/^[^\n:：]{1,40}: /, ''), '');
      turn = Object.assign({ floor: -1, sd: '', mes: '', fresh: false }, turn || {}, { raw: sp.raw, plot: sp.plot });
    }
    if (!sel.length && !(turn && turn.plot)) return null;    // 这一轮没有要接管的东西（数据库条目、剧情推进都没有）

    const t0 = Date.now();
    const deadline = t0 + DIRECTOR_MAX_MS;
    const chatId = currentChatId();
    let stopWhy = '';
    const Ctrl = TOP.AbortController || AbortController;
    const ctrl = new Ctrl();
    const stopped = new Promise((resolve) => {
      _stopDirector = (why) => { if (!stopWhy) { stopWhy = why || '停下了'; ctrl.abort(); resolve(); } };
    });
    const live = () => !DISPOSED && !stopWhy && chatId === currentChatId();
    lastBrief = { busy: true, at: t0, chatId };
    BUS.emit('brief', lastBrief);
    try {
      const mat = directorMaterials(chat, sel, turn, c);
      // 同一句话（重新生成、换一条）沿用写过的稿子：认这一层、这一句、这一段剧情推进，不认世界书这次激活了哪些
      // （玩家那条还原成原话以后，靠编码激活的纪要条目就不激活了，材料会跟第一次不一样，但事实是同一份）
      const key = turn && turn.floor >= 0
        ? [chatId, c.导演稿, turn.floor, turn.sd, hashStr(turn.plot + '\n' + turn.raw)].join('|')
        : chatId + '|' + c.导演稿 + '|' + hashStr(JSON.stringify(Object.assign({}, mat, { state: '' })));
      let brief = _briefCache.get(key) || null;
      const cached = !!brief;
      let why = '';
      // 写稿和等这一轮的状态同时进行：写稿的模型不看此刻状态（状态原样附在稿子后面）。
      // 「发送的时候等不等它」选了「从不」：写完稿状态还没回来就不等，用现有最新的那份
      const briefJob = cached ? Promise.resolve(brief) : writeBrief(mat, c, deadline, live, ctrl.signal)
        .then((b) => { if (!b.text) { why = '交回来的稿子是空的'; return null; } return b; })
        .catch((e) => { why = (e && e.message) || String(e); return null; });
      const runJob = c.阻塞方式 === '从不' ? Promise.resolve() : waitThisRun(deadline);
      brief = await Promise.race([briefJob, stopped.then(() => null)]);
      if (brief && live()) await Promise.race([runJob, stopped]);
      // 点了停止、换了聊天：别把旧聊天的材料和新聊天的状态拼在一起发出去，提示词也不动
      if (!live()) return briefFailed(stopWhy || '换了聊天', t0, false, chatId);
      if (!brief) return briefFailed(why, t0, true, chatId);
      if (!cached) rememberBrief(key, brief);
      const st = stateForGeneration();
      const stateText = st ? renderState(st, c) : '';
      // 材料太长、没交给写稿模型的条目，稿子里没有它们：留在提示词原处，不收
      const dropped = brief.dropped || [];
      let res;
      try {
        res = applyBrief(chat, sel.filter((e) => dropped.indexOf(String(e.comment || '')) === -1), brief.text, turn, stateText, c);
      } catch (e) {
        return briefFailed('换稿子时出错：' + ((e && e.message) || e), t0, true, chatId);
      }
      // 这一轮的状态在交给正文之前都回来了、跟着稿子进了玩家这一轮：面板别说「沿用上一轮」
      if (lastRun && lastRun.done && lastRun.chatId === chatId && st && st.floor === lastRun.floor) lastRun.caughtUp = true;
      const restored = await restoreTurn(turn);
      const restoreFailed = restored === null;
      if (restoreFailed) {
        warn('玩家那条没能还原成原话，数据库这一轮填表可能把剧情推进的内容当成这一轮的事记下来');
        try { toastr.warning('玩家那条没能还原成原话，数据库这一轮填表可能会记错'); } catch (e) { /* ignore */ }
      }
      lastBrief = Object.assign({ ok: true, text: brief.text, state: stateText, dropped, plotCut: brief.plotCut || 0, cached,
        restored: restored === true, restoreFailed, at: Date.now(), ms: Date.now() - t0, chatId }, res);
      log('导演稿：' + (cached ? '沿用这一句写过的那份' : '写好了，' + (brief.ms || 0) + 'ms') + '，收走 ' + res.cut + ' 条' +
        (res.missed.length ? '，没找到 ' + res.missed.length + ' 条（' + res.missed.join('、') + '）' : '') +
        (dropped.length ? '，材料放不下、留在原处 ' + dropped.length + ' 条（' + dropped.join('、') + '）' : '') +
        (brief.plotCut ? '，剧情推进的内容太长，砍了约 ' + brief.plotCut + ' 字' : '') +
        (brief.lines ? '，重要对话 ' + brief.lines + ' 句' : '') +
        (brief.fakeLines ? '，丢掉 ' + brief.fakeLines + ' 句材料里找不到的原话' : '') +
        (restored === true ? '，玩家那条还原成了原话' : '') + (restoreFailed ? '，玩家那条没能还原' : ''));
      BUS.emit('brief', lastBrief);
      return lastBrief;
    } finally {
      _stopDirector = null;
    }
  }

  // ======================== 提示词（可以改）和调试记录 ========================
  // 手账本发给模型的每一段提示词都能在面板「提示词」页里改。编辑框里放的就是原文，
  // 整段复制给别的 AI 改完再贴回来也行。
  //   · 改过的存在脚本变量「提示词」里：{ 段名: { text, base } }，base 是改的时候内置那段的指纹，
  //     内置那段后来变了（手账本升级），面板上会提醒
  //   · 改完和内置一模一样就当没改；没改过的段跟着以后版本的内置走
  //   · 模型回答的格式（JSON 的那几个字段）由代码定，改提示词改不了它
  //   · 预设：整套导出成一个文件，别人导入就换成这一套。只带提示词，不带接口和密钥
  // 调试记录：最近 20 次调用发了什么、回了什么，存在这台电脑的浏览器里

  const PROMPT_VAR = '提示词';
  const PRESET_FORMAT = '常夜灯的手账本·提示词预设';

  // 开着导演稿时，玩家这一轮交给正文的样子
  const DIRECTOR_TURN_TPL = `以下是玩家这一轮的输入：
<本轮用户输入>
{{原话}}
</本轮用户输入>

以下是手账本为这一轮整理的导演稿和当前状态。导演稿写这一场用得上的事实，和剧情推进给的走向。当前状态写每个人此刻的状态。照它们写接下来的剧情：
· 已经发生的事、人物现况、没了结的约定和秘密，以导演稿为准，不和它矛盾。
· 导演稿里有「推进」时，这一轮照它往下写。没有时，顺着玩家这一轮和上文写。
· 角色提起以前说过的话时，只用导演稿「重要对话」里的原句，不另编。
· 导演稿里有「平行线」时，那是玩家不在场的另一条线。写到那条线时，照导演稿和当前状态里那条线上的人写。玩家不知道那边的事。
· 人物此刻在做什么、想要什么、有什么话没说出口，照当前状态写。
· 玩家这一轮的输入和它们冲突时，以玩家这一轮为准。
· 正文里不复述导演稿和当前状态，也不出现这两个名字。

{{导演稿}}

{{当前状态}}`;

  const PROMPT_DEFS = [
    { id: '前置提示词', group: '前置提示词',
      tip: '拼在发给状态模型和写稿模型的每一段提示词最前面。默认空着；要缝破限或自己的预设就写在这里。正文模型那边归你的主预设管，这里不管。',
      builtin: () => '' },
