  // 改过名的段：旧名字 → 新名字。旧版里改过的、导出的预设文件里的都认；代码里用旧名字取也照样取得到
  const LEGACY_PROMPT_IDS = { 记账的规则: '记状态的规则（动态人设）', 记状态的规则: '记状态的规则（动态人设）' };

  function promptDef(id) {
    const real = LEGACY_PROMPT_IDS[id] || id;
    return PROMPT_DEFS.find((d) => d.id === real) || null;
  }

  // 发给记状态 / 写稿模型的系统提示词：前置提示词写了就拼在最前面
  function withPrefix(system) {
    const pre = promptText('前置提示词').trim();
    return pre ? pre + '\n\n' + system : system;
  }

  function customPrompts() {
    const v = readScriptVars()[PROMPT_VAR];
    if (!v || typeof v !== 'object' || Array.isArray(v)) return {};
    const out = Object.assign({}, v);
    Object.keys(LEGACY_PROMPT_IDS).forEach((old) => {
      if (out[old] && !out[LEGACY_PROMPT_IDS[old]]) out[LEGACY_PROMPT_IDS[old]] = out[old];
      delete out[old];
    });
    return out;
  }

  // 这一段现在用的原文：改过就用改过的，没改过就用内置的
  function promptText(id) {
    const d = promptDef(id);
    if (!d) return '';
    const own = customPrompts()[d.id];
    return own && typeof own.text === 'string' && own.text.trim() ? own.text : d.builtin();
  }

  // custom：改过；stale：改过，而且内置那段后来又变了（升级以后可能想看看新的）
  function promptState(id) {
    const d = promptDef(id);
    const own = d ? customPrompts()[d.id] : null;
    const custom = !!(d && own && typeof own.text === 'string' && own.text.trim());
    return { custom, stale: custom && own.base !== hashStr(d.builtin()) };
  }

  function writeCustomPrompts(all) {
    try {
      updateVariablesWith((vars) => { vars[PROMPT_VAR] = all; return vars; }, { type: 'script' });
      backupSettings();
      return true;
    } catch (e) {
      warn('提示词没存上：', e);
      return false;
    }
  }

  // 改完和内置一样（或者清空了）就当恢复内置
  function savePrompt(id, text) {
    const d = promptDef(id);
    if (!d) return false;
    const all = Object.assign({}, customPrompts());
    const t = String(text == null ? '' : text);
    if (!t.trim() || t.trim() === d.builtin().trim()) delete all[d.id];
    else all[d.id] = { text: t, base: hashStr(d.builtin()) };
    return writeCustomPrompts(all);
  }

  function resetAllPrompts() { return writeCustomPrompts({}); }

  function exportPromptPreset() {
    const prompts = {};
    PROMPT_DEFS.forEach((d) => { prompts[d.id] = promptText(d.id); });
    return { format: PRESET_FORMAT, version: VERSION, prompts };
  }

  // 导入就换成这一套：文件里有的段照文件，没有的段回到内置。认不得的段名跳过，报出来
  function importPromptPreset(obj) {
    if (!obj || typeof obj !== 'object' || !obj.prompts || typeof obj.prompts !== 'object') {
      throw new Error('这不是手账本的提示词预设（里面没有 prompts）');
    }
    const all = {};
    let changed = 0;
    const got = Object.assign({}, obj.prompts);
    Object.keys(LEGACY_PROMPT_IDS).forEach((old) => {
      if (got[old] !== undefined && got[LEGACY_PROMPT_IDS[old]] === undefined) got[LEGACY_PROMPT_IDS[old]] = got[old];
      delete got[old];
    });
    PROMPT_DEFS.forEach((d) => {
      const t = got[d.id];
      if (typeof t !== 'string' || !t.trim() || t.trim() === d.builtin().trim()) return;
      all[d.id] = { text: t, base: hashStr(d.builtin()) };
      changed += 1;
    });
    const unknown = Object.keys(got).filter((k) => !promptDef(k));
    if (!writeCustomPrompts(all)) throw new Error('存不进脚本变量');
    return { changed, unknown };
  }

  // 冷启动：记状态的规则（动态人设或稳定人设）+ 冷启动的规则
  function coldPrompt(max, stable) {
    return promptText(stable ? '记状态的规则（稳定人设）' : '记状态的规则（动态人设）') + promptText('冷启动的规则').replace(/\{\{最多几人\}\}/g, String(max));
  }

  // 玩家这一轮：一次替换完，玩家原话里就算写着 {{导演稿}} 也不会被换掉。少了哪个占位符就补上，玩家的话不能丢
  function fillDirectorTurn(raw, brief, stateText) {
    let t = promptText('手账本输出提示词');
    if (t.indexOf('{{原话}}') === -1) t = '{{原话}}\n\n' + t;
    if (t.indexOf('{{导演稿}}') === -1) t += '\n\n{{导演稿}}';
    if (t.indexOf('{{当前状态}}') === -1) t += '\n\n{{当前状态}}';
    const map = { 原话: raw, 导演稿: brief, 当前状态: stateText || '' };
    return t.replace(/\{\{(原话|导演稿|当前状态)\}\}/g, (m, k) => map[k]).replace(/\s+$/, '');
  }

  // ---------- 调试记录 ----------
  // 系统提示词每次都一样长，按指纹只存一份
  const DEBUG_KEY = NS + '.debuglog';
  const DEBUG_MAX = 20;
  let _debug = null;              // { log: [...], sys: { 指纹: 原文 } }

  function debugLoad() {
    if (_debug) return _debug;
    let j = null;
    try { j = JSON.parse(TOP.localStorage.getItem(DEBUG_KEY) || 'null'); } catch (e) { j = null; }
    _debug = { log: j && Array.isArray(j.log) ? j.log : [], sys: (j && j.sys && typeof j.sys === 'object') ? j.sys : {} };
    return _debug;
  }

  function debugSave() {
    const d = debugLoad();
    const used = new Set(d.log.map((x) => x.sys));
    Object.keys(d.sys).forEach((h) => { if (!used.has(h)) delete d.sys[h]; });
    for (let tries = 0; tries < 3; tries += 1) {
      try { TOP.localStorage.setItem(DEBUG_KEY, JSON.stringify(d)); return; } catch (e) {
        d.log = d.log.slice(0, Math.max(1, Math.floor(d.log.length / 2)));     // 浏览器存不下：丢掉旧的一半再试
      }
    }
  }

  const tailClip = (s, max) => { const t = String(s == null ? '' : s); return t.length > max ? t.slice(0, max) + '\n…（后面还有 ' + (t.length - max) + ' 字，没存）' : t; };

  function debugRecord(e) {
    const d = debugLoad();
    const sys = String(e.system || '');
    const h = hashStr(sys);
    d.sys[h] = sys;
    d.log.unshift({ at: Date.now(), label: String(e.label || ''), model: String(e.model || ''), ms: e.ms || 0, ok: !!e.ok,
      error: e.error ? String(e.error) : '', sys: h, user: tailClip(e.user, 40000), reply: tailClip(e.reply, 20000) });
    d.log = d.log.slice(0, DEBUG_MAX);
    debugSave();
    BUS.emit('debug', null);
  }

  function debugEntries() {
    const d = debugLoad();
    return d.log.map((x) => Object.assign({}, x, { system: d.sys[x.sys] || '' }));
  }

  function debugClear() {
    _debug = { log: [], sys: {} };
    try { TOP.localStorage.removeItem(DEBUG_KEY); } catch (e) { /* ignore */ }
    BUS.emit('debug', null);
  }

  function debugText(x) {
    const t = new Date(x.at);
    const pad = (n) => String(n).padStart(2, '0');
    return '【时间】' + t.getFullYear() + '-' + pad(t.getMonth() + 1) + '-' + pad(t.getDate()) + ' ' + pad(t.getHours()) + ':' + pad(t.getMinutes()) + ':' + pad(t.getSeconds()) +
      '\n【调用】' + x.label + '（' + x.model + '，' + (x.ms / 1000).toFixed(1) + ' 秒）' +
      '\n【结果】' + (x.ok ? '成功' : '失败：' + x.error) +
      '\n\n【发送的系统提示词】\n' + x.system + '\n\n【发送的材料】\n' + x.user + '\n\n【模型的回答】\n' + (x.reply || '（没有回答）');
  }

