  const STITCH_SHEETS = {"纪要表": {"uid": "sheet_GnJvgids", "name": "纪要表", "orderNo": 0, "sourceData": {"note": "轮次日志。每一轮交互结束后，必须插入一条新记录，记下这一轮发生了什么。这张表是整个故事的「事实账本」：以后任何人想知道「之前发生过什么」，都会来这里查。所以它必须客观、完整、可以核对。（列号为 0 基，与表格数据中的列标一致）\n- 列0: 时间跨度 - 本轮事件在故事世界里发生的时间范围。格式固定为「YYYY-MM-DD HH:MM ~ YYYY-MM-DD HH:MM」，例如「2025-04-08 16:20 ~ 2025-04-08 16:45」。正文没写具体时间时，按上一条记录的时间和本轮经过的时长推算，不要留空。\n- 列1: 地点 - 本轮事件发生的地点，从大到小写，用「·」隔开，例如「学校·三楼·音乐教室」。只用正文里出现过的名字；正文里没有专有名词的，用普通说法（「她家楼下」「车站前」），不要自己编店名和地名。\n- 列2: 纪要 - 以第三方视角、按时间顺序客观记录本轮发生的事：谁在场、谁做了什么、谁说了什么（关键台词可以直接引用原话）、结果是什么、有什么东西发生了变化。300 到 400 字。只写发生了的事和说出口的话，不写任何人的心理活动、动机猜测、情绪判断；不写「他们的关系更近了一步」这种总结；结尾不升华、不点题、不评论。\n- 列3: 概览 - 一句话概括本轮纪要，不超过 30 字。写事件本身（谁、做了什么），不写评价。例如「放学后两人在音乐教室收谱架，被值日生打断」这种形态。\n- 列4: 编码索引 - 本条记录的编号，格式为 AM 加四位数字，从 AM0001 开始逐条递增，不得跳号，不得与已有编号重复。插入前先看表里最大的编号，新编号是它加一。\n\n- 【纪要表专用】每一轮都必须插入且只插入一条新记录，不修改、不删除旧记录。\n- 【纪要表专用】玩家扮演的人的行动也要记，但只记他做了什么、说了什么，不写他的心理。\n\n【手账本·拼表开始】\n【分工】人物的心理、情绪、动机由「常夜灯的手账本」插件单独记录，本表不记录。\n本表只记正文里明确写到、可以核对的事实：人物做了什么、说了什么、去了哪里、什么东西变了。\n不写心理活动和动机推测（「她心里」「她其实」「她想要」「她害怕」这类句子删掉）。\n不写性格评价和类型标签（温柔、傲娇、腹黑、高冷……）。\n正文没写到的不补、不推测。\n本表的列说明里专门要求写人物认知、关系、心理、性格的那几列，照那几列自己的说明写；上面几条只管其余的列。\n【手账本·拼表结束】", "initNode": "故事开始时，插入一条新记录，记录开场的情形：谁在哪里、在做什么、发生了什么。", "deleteNode": "禁止。已经写下的纪要是事实记录，不删除。", "updateNode": "禁止。已经写下的纪要是事实记录，不修改。", "insertNode": "每一轮交互结束后，插入一条新记录。\n时间跨度格式必须为 YYYY-MM-DD HH:MM ~ YYYY-MM-DD HH:MM。\n编码索引必须是表中最大编号加一。\nSQL示例: INSERT INTO chronicle (time_span, location, chronicle_text, summary, code_index) VALUES ('示例时间跨度', '示例地点', '示例纪要', '示例概览', '示例编码索引');", "ddl": "CREATE TABLE chronicle ( -- 纪要表\n  row_id INTEGER PRIMARY KEY, -- 行号\n  time_span TEXT, -- 时间跨度\n  location TEXT, -- 地点\n  chronicle_text TEXT, -- 纪要\n  summary TEXT, -- 概览\n  code_index TEXT -- 编码索引\n);"}, "content": [["row_id", "时间跨度", "地点", "纪要", "概览", "编码索引"]], "updateConfig": {"uiSentinel": -1, "contextDepth": -1, "updateFrequency": -1, "batchSize": -1, "skipFloors": -1, "groupId": -1}, "exportConfig": {"enabled": true, "splitByRow": true, "entryName": "纪要", "entryType": "keyword", "keywords": "编码索引", "preventRecursion": true, "injectionTemplate": "<记忆回溯>\n$1\n</记忆回溯>", "extraIndexEnabled": true, "extraIndexEntryName": "纪要索引", "extraIndexColumns": ["概览", "编码索引"], "extraIndexColumnModes": {"概览": "index_only", "编码索引": "both"}, "extraIndexInjectionTemplate": "<已发生的事件概览>\n$1\n</已发生的事件概览>", "sqlInjectionTemplate": "", "entryPlacement": {"position": "at_depth_as_system", "depth": 999, "order": 10000}, "extraIndexPlacement": {"position": "at_depth_as_system", "depth": 1000, "order": 10010}, "fixedEntryPlacement": {"position": "at_depth_as_system", "depth": 999, "order": 99990}, "fixedIndexPlacement": {"position": "at_depth_as_system", "depth": 1000, "order": 99991}}}, "重要角色表": {"uid": "sheet_xSspmIQX", "name": "重要角色表", "orderNo": 1, "sourceData": {"note": "记录故事里有名字、会反复出现的重要人物的「客观现况」：她是谁、长什么样、现在穿着什么、和主角之间实际发生过什么、在不在场、经历过什么。这张表是人物的「事实档案」，不是人物分析。（列号为 0 基，与表格数据中的列标一致）\n- 列0: 姓名 - 人物的名字，用正文里最常用的那个全名。一个人只占一行，不得和表里已有的人重名，也不要用昵称或别名另开一行。玩家扮演的人不入本表。\n- 列1: 一句话介绍 - 不超过 15 字，写身份和位置，例如「主角的同班同学，园艺部成员」。不写性格，不写评价。\n- 列2: 外貌与衣着 - 看得见的外貌特征，以及她此刻（本轮结束时）的穿着和随身物品。不超过 80 字。衣着变了就更新；外貌只写正文里描写过的。\n- 列3: 与主角的关系 - 她和主角是怎么认识的、两人之间实际发生过的关键事件、目前两人处在什么位置（例如「同班，说过的话不超过十句」「上周一起淋过雨，交换了联系方式」）。不超过 100 字。只写发生过的事和能看到的状态，不写「她喜欢主角」「她对主角有好感」「她在意主角」这类心里的东西。\n- 列4: 是否离场 - 她此刻能不能直接和主角互动。只填「是」或「否」：「是」表示离场（不在这一场、走了、在别处），「否」表示在场。\n- 列5: 过往经历 - 她的背景和在故事里经历过的关键事件，按时间顺序，只写事实。随剧情增量追加，不超过 300 字，超过时把最早的部分压缩成一两句，保留因果。\n\n- 【重要角色表专用】只有有名字、而且之后还会再出现的人才入表。路人、一次性出场的店员、没有名字的人不入表。\n- 【重要角色表专用】不要新增「性格」「心理」「好感度」「想法」这类列的内容，也不要把这类内容塞进别的列里。\n\n【手账本·拼表开始】\n【分工】人物的心理、情绪、动机由「常夜灯的手账本」插件单独记录，本表不记录。\n本表只记正文里明确写到、可以核对的事实：人物做了什么、说了什么、去了哪里、什么东西变了。\n不写心理活动和动机推测（「她心里」「她其实」「她想要」「她害怕」这类句子删掉）。\n不写性格评价和类型标签（温柔、傲娇、腹黑、高冷……）。\n正文没写到的不补、不推测。\n本表的列说明里专门要求写人物认知、关系、心理、性格的那几列，照那几列自己的说明写；上面几条只管其余的列。\n【手账本·拼表结束】", "initNode": "故事开始时，为正文里已经登场、有名字、之后还会再出现的人物各插入一行。", "deleteNode": "禁止。人物离开故事时把「是否离场」改成「是」，不删除。", "updateNode": "已有人物的看得见的事实变了时，更新对应的那一格：换了衣服、和主角之间发生了新的关键事件、离场或回到这一场、经历里多了一件关键的事。人物死亡时在姓名后面标注「（已死亡）」。\nSQL示例: UPDATE important_characters SET brief_intro = '示例一句话介绍' WHERE name = '示例姓名';", "insertNode": "剧情里第一次出现一个有名字、会再出现的人物，而且表里还没有她时，插入一行。\nSQL示例: INSERT INTO important_characters (name, brief_intro, appearance, relation, is_absent, past_experience) VALUES ('示例姓名', '示例一句话介绍', '示例外貌与衣着', '示例与主角的关系', '示例是否离场', '示例过往经历');", "ddl": "CREATE TABLE important_characters ( -- 重要角色表\n  row_id INTEGER PRIMARY KEY, -- 行号\n  name TEXT, -- 姓名\n  brief_intro TEXT, -- 一句话介绍\n  appearance TEXT, -- 外貌与衣着\n  relation TEXT, -- 与主角的关系\n  is_absent TEXT, -- 是否离场\n  past_experience TEXT -- 过往经历\n);"}, "content": [["row_id", "姓名", "一句话介绍", "外貌与衣着", "与主角的关系", "是否离场", "过往经历"]], "updateConfig": {"uiSentinel": -1, "contextDepth": -1, "updateFrequency": -1, "batchSize": -1, "skipFloors": -1, "groupId": -1}, "exportConfig": {"enabled": true, "splitByRow": true, "entryName": "重要人物表", "entryType": "keyword", "keywords": "姓名", "preventRecursion": true, "injectionTemplate": "", "extraIndexEnabled": true, "extraIndexEntryName": "重要人物表-索引", "extraIndexColumns": ["姓名", "一句话介绍"], "extraIndexColumnModes": {"姓名": "both", "一句话介绍": "index_only"}, "extraIndexInjectionTemplate": "以下为已经登场过的角色：\n<已登场角色>\n$1\n</已登场角色>", "sqlInjectionTemplate": "", "entryPlacement": {"position": "at_depth_as_system", "depth": 10000, "order": 10000}, "extraIndexPlacement": {"position": "at_depth_as_system", "depth": 10000, "order": 8000}, "fixedEntryPlacement": {"position": "at_depth_as_system", "depth": 10000, "order": 99990}, "fixedIndexPlacement": {"position": "at_depth_as_system", "depth": 10000, "order": 99991}}}, "手账本·知情表": {"uid": "sheet_oI9AKIMJ", "name": "手账本·知情表", "orderNo": 2, "sourceData": {"note": "记录剧情里需要保密、或者只有一部分人知道的事：谁已经知道，谁还不知道。每件事占一行。（列号为 0 基，与表格数据中的列标一致）\n- 列0: 事项 - 被知道或被瞒着的那件事，一句话写清，不超过 40 字，例如「若叶睦还在弹吉他」。\n- 列1: 知情人 - 已经知道这件事的人物名字，多人用「、」隔开。只写正文里明确得知的人。\n- 列2: 不知情人 - 和这件事有关、但正文里明确还不知道的人物名字，多人用「、」隔开。没有就写「无」。\n- 列3: 得知方式 - 知情人是怎么知道的，例如「本人告知」「偷听到」「看到聊天记录」。几个人得知方式不同就分开写。\n- 列4: 是否公开 - 只填「是」或「否」。有关的人都已经知道时填「是」。\n\n- 【知情表专用】只记正文里明确写到的得知和隐瞒，不按人物性格推测谁可能知道。\n- 【知情表专用】有人新得知时，把名字从「不知情人」移到「知情人」，补上得知方式；所有人都知道后把「是否公开」改成「是」。\n- 【知情表专用】已经公开、而且纪要表里记下了公开经过的事，删掉这一行，表里只留还瞒着人的事。\n\n【手账本·拼表开始】\n【分工】人物的心理、情绪、动机由「常夜灯的手账本」插件单独记录，本表不记录。\n本表只记正文里明确写到、可以核对的事实：人物做了什么、说了什么、去了哪里、什么东西变了。\n不写心理活动和动机推测（「她心里」「她其实」「她想要」「她害怕」这类句子删掉）。\n不写性格评价和类型标签（温柔、傲娇、腹黑、高冷……）。\n正文没写到的不补、不推测。\n本表的列说明里专门要求写人物认知、关系、心理、性格的那几列，照那几列自己的说明写；上面几条只管其余的列。\n【手账本·拼表结束】", "initNode": "故事开始时，设定或开场里有明确要保密的事，每件插入一行。", "deleteNode": "「是否公开」已经是「是」，并且纪要表里已经记下了这件事公开的经过时，删除这一行。还有人不知道的不删。\nSQL示例: DELETE FROM hb_knowledge WHERE item = '示例事项';", "updateNode": "有人新得知、或者事情公开时，更新这一行的知情人、不知情人、得知方式、是否公开。\nSQL示例: UPDATE hb_knowledge SET knowers = '示例知情人' WHERE item = '示例事项';", "insertNode": "正文里出现新的保密的事，或者某件事第一次只被一部分人知道时，插入一行。\nSQL示例: INSERT INTO hb_knowledge (item, knowers, unaware, how_known, is_public) VALUES ('示例事项', '示例知情人', '示例不知情人', '示例得知方式', '示例是否公开');", "ddl": "CREATE TABLE hb_knowledge ( -- 手账本·知情表\n  row_id INTEGER PRIMARY KEY, -- 行号\n  item TEXT, -- 事项\n  knowers TEXT, -- 知情人\n  unaware TEXT, -- 不知情人\n  how_known TEXT, -- 得知方式\n  is_public TEXT -- 是否公开\n);"}, "content": [["row_id", "事项", "知情人", "不知情人", "得知方式", "是否公开"]], "updateConfig": {"uiSentinel": -1, "contextDepth": -1, "updateFrequency": -1, "batchSize": -1, "skipFloors": -1, "groupId": -1}, "exportConfig": {"enabled": false, "splitByRow": false, "entryName": "手账本·知情表", "entryType": "constant", "keywords": "", "preventRecursion": true, "injectionTemplate": "", "extraIndexEnabled": false, "extraIndexEntryName": "手账本·知情表-索引", "extraIndexColumns": [], "extraIndexColumnModes": {}, "extraIndexInjectionTemplate": "", "sqlInjectionTemplate": "", "entryPlacement": {"position": "at_depth_as_system", "depth": 2, "order": 10000}, "extraIndexPlacement": {"position": "at_depth_as_system", "depth": 2, "order": 10010}, "fixedEntryPlacement": {"position": "at_depth_as_system", "depth": 2, "order": 99990}, "fixedIndexPlacement": {"position": "at_depth_as_system", "depth": 2, "order": 99991}, "injectIntoWorldbook": false}}, "手账本·约定表": {"uid": "sheet_2Fzrwz1r", "name": "手账本·约定表", "orderNo": 3, "sourceData": {"note": "记录人物之间说出口的约定、答应过的事、接受了的请求，以及它们后来怎样了。每个约定占一行。（列号为 0 基，与表格数据中的列标一致）\n- 列0: 发起人 - 提出或答应这件事的人物名字。\n- 列1: 对象 - 约定的另一方，多人用「、」隔开。\n- 列2: 约定内容 - 约了什么、答应了什么，一句话，不超过 40 字，例如「周六一起去看演出」。\n- 列3: 约定时间 - 约好什么时候兑现，例如「本周六下午」「演出前」。正文没说就写「未定」。\n- 列4: 状态 - 只填「未到期」「已兑现」「已违约」「已取消」之一。\n\n- 【约定表专用】只记正文里明确说出口的约定和答应，不记人物心里的打算。\n- 【约定表专用】约定兑现、违约或取消时先改「状态」；纪要表里记下了这件事以后，删掉这一行，表里只留还没了结的约定。\n\n【手账本·拼表开始】\n【分工】人物的心理、情绪、动机由「常夜灯的手账本」插件单独记录，本表不记录。\n本表只记正文里明确写到、可以核对的事实：人物做了什么、说了什么、去了哪里、什么东西变了。\n不写心理活动和动机推测（「她心里」「她其实」「她想要」「她害怕」这类句子删掉）。\n不写性格评价和类型标签（温柔、傲娇、腹黑、高冷……）。\n正文没写到的不补、不推测。\n本表的列说明里专门要求写人物认知、关系、心理、性格的那几列，照那几列自己的说明写；上面几条只管其余的列。\n【手账本·拼表结束】", "initNode": "故事开始时，设定或开场里有明确的约定，每个插入一行。", "deleteNode": "「状态」已经是「已兑现」「已违约」或「已取消」，并且纪要表里已经记下了这件事时，删除这一行。「未到期」的不删。\nSQL示例: DELETE FROM hb_promises WHERE content = '示例约定内容';", "updateNode": "约定兑现、违约、取消，或者约定时间改了时，更新这一行。\nSQL示例: UPDATE hb_promises SET promisee = '示例对象' WHERE content = '示例约定内容';", "insertNode": "正文里有人明确约定、答应或接受请求时，插入一行，状态填「未到期」。\nSQL示例: INSERT INTO hb_promises (promiser, promisee, content, due, status) VALUES ('示例发起人', '示例对象', '示例约定内容', '示例约定时间', '示例状态');", "ddl": "CREATE TABLE hb_promises ( -- 手账本·约定表\n  row_id INTEGER PRIMARY KEY, -- 行号\n  promiser TEXT, -- 发起人\n  promisee TEXT, -- 对象\n  content TEXT, -- 约定内容\n  due TEXT, -- 约定时间\n  status TEXT -- 状态\n);"}, "content": [["row_id", "发起人", "对象", "约定内容", "约定时间", "状态"]], "updateConfig": {"uiSentinel": -1, "contextDepth": -1, "updateFrequency": -1, "batchSize": -1, "skipFloors": -1, "groupId": -1}, "exportConfig": {"enabled": false, "splitByRow": false, "entryName": "手账本·约定表", "entryType": "constant", "keywords": "", "preventRecursion": true, "injectionTemplate": "", "extraIndexEnabled": false, "extraIndexEntryName": "手账本·约定表-索引", "extraIndexColumns": [], "extraIndexColumnModes": {}, "extraIndexInjectionTemplate": "", "sqlInjectionTemplate": "", "entryPlacement": {"position": "at_depth_as_system", "depth": 2, "order": 10000}, "extraIndexPlacement": {"position": "at_depth_as_system", "depth": 2, "order": 10010}, "fixedEntryPlacement": {"position": "at_depth_as_system", "depth": 2, "order": 99990}, "fixedIndexPlacement": {"position": "at_depth_as_system", "depth": 2, "order": 99991}, "injectIntoWorldbook": false}}, "手账本·重大事件表": {"uid": "sheet_FlbifpHe", "name": "手账本·重大事件表", "orderNo": 4, "sourceData": {"note": "记录对某个人物影响大的、正文里明确发生的事，好事坏事都记。坏事指当众出丑、失去重要的人或东西、被拒绝、被揭穿、受伤这一类；好事指被认可、做成了一直想做的事、得到重要的人或东西、和重要的人和好这一类。日常小事不记。每件事占一行。（列号为 0 基，与表格数据中的列标一致）\n- 列0: 当事人 - 这件事落在谁身上，写人物名字。\n- 列1: 事件 - 开头写「好事：」或「坏事：」，后面写发生了什么，不超过 50 字，只写经过和结果。\n- 列2: 在场者 - 当时在场看到的人物名字，多人用「、」隔开。没有旁人写「无」。\n- 列3: 发生时间 - 故事里的时间，格式「YYYY-MM-DD HH:MM」。正文没写具体时间时，按纪要表里最近一条的时间推算。\n- 列4: 是否已解决 - 只填「是」或「否」。坏事在正文里明确出现和解、弥补、澄清、伤好了，好事在正文里明确过去了、不再影响当事人时，改成「是」。\n\n- 【重大事件表专用】只写发生了什么，不写当事人的感受和反应。\n- 【重大事件表专用】同一件事后来有了进展（被澄清、被弥补），更新原来那一行，不另开一行。\n- 【重大事件表专用】已经解决、而且纪要表里记下了经过的事，删掉这一行，表里只留还没解决的事。\n\n【手账本·拼表开始】\n【分工】人物的心理、情绪、动机由「常夜灯的手账本」插件单独记录，本表不记录。\n本表只记正文里明确写到、可以核对的事实：人物做了什么、说了什么、去了哪里、什么东西变了。\n不写心理活动和动机推测（「她心里」「她其实」「她想要」「她害怕」这类句子删掉）。\n不写性格评价和类型标签（温柔、傲娇、腹黑、高冷……）。\n正文没写到的不补、不推测。\n本表的列说明里专门要求写人物认知、关系、心理、性格的那几列，照那几列自己的说明写；上面几条只管其余的列。\n【手账本·拼表结束】", "initNode": "故事开始时，设定或开场里已经发生过的大事，每件插入一行。", "deleteNode": "「是否已解决」已经是「是」，并且纪要表里已经记下了经过时，删除这一行。没解决的不删。\nSQL示例: DELETE FROM hb_major_events WHERE event = '示例事件';", "updateNode": "坏事有了解决（和解、弥补、澄清、伤好了）、好事的影响过去了时，把是否已解决改成「是」。\nSQL示例: UPDATE hb_major_events SET event = '示例事件' WHERE event = '示例事件';", "insertNode": "正文里发生了对某个人物影响大的好事或坏事时，插入一行，事件开头写「好事：」或「坏事：」，是否已解决填「否」。\nSQL示例: INSERT INTO hb_major_events (person, event, witnesses, time, resolved) VALUES ('示例当事人', '示例事件', '示例在场者', '示例发生时间', '示例是否已解决');", "ddl": "CREATE TABLE hb_major_events ( -- 手账本·重大事件表\n  row_id INTEGER PRIMARY KEY, -- 行号\n  person TEXT, -- 当事人\n  event TEXT, -- 事件\n  witnesses TEXT, -- 在场者\n  time TEXT, -- 发生时间\n  resolved TEXT -- 是否已解决\n);"}, "content": [["row_id", "当事人", "事件", "在场者", "发生时间", "是否已解决"]], "updateConfig": {"uiSentinel": -1, "contextDepth": -1, "updateFrequency": -1, "batchSize": -1, "skipFloors": -1, "groupId": -1}, "exportConfig": {"enabled": false, "splitByRow": false, "entryName": "手账本·重大事件表", "entryType": "constant", "keywords": "", "preventRecursion": true, "injectionTemplate": "", "extraIndexEnabled": false, "extraIndexEntryName": "手账本·重大事件表-索引", "extraIndexColumns": [], "extraIndexColumnModes": {}, "extraIndexInjectionTemplate": "", "sqlInjectionTemplate": "", "entryPlacement": {"position": "at_depth_as_system", "depth": 2, "order": 10000}, "extraIndexPlacement": {"position": "at_depth_as_system", "depth": 2, "order": 10010}, "fixedEntryPlacement": {"position": "at_depth_as_system", "depth": 2, "order": 99990}, "fixedIndexPlacement": {"position": "at_depth_as_system", "depth": 2, "order": 99991}, "injectIntoWorldbook": false}}, "手账本·配角关系表": {"uid": "sheet_DLezkJQz", "name": "手账本·配角关系表", "orderNo": 5, "sourceData": {"note": "记录配角和配角之间（不包括主角）正文里写到的来往：一起经历过什么、现在怎么相处。主角和别人的关系记在重要角色表里，这里不记。每一对人物占一行。（列号为 0 基，与表格数据中的列标一致）\n- 列0: 人物A - 一方的名字。\n- 列1: 人物B - 另一方的名字。\n- 列2: 交往经过 - 两人之间发生过的关键事，按时间顺序，只写事实，不超过 150 字；超过时把最早的部分压成一两句。\n- 列3: 当前状态 - 两人现在看得见的相处状态，不超过 30 字，例如「同一乐队，排练时不说话」。不写喜欢、讨厌这类感情判断。\n\n- 【配角关系表专用】同一对人物只占一行，人物A和人物B换个顺序也算同一对。\n- 【配角关系表专用】主角不进这张表。\n\n【手账本·拼表开始】\n【分工】人物的心理、情绪、动机由「常夜灯的手账本」插件单独记录，本表不记录。\n本表只记正文里明确写到、可以核对的事实：人物做了什么、说了什么、去了哪里、什么东西变了。\n不写心理活动和动机推测（「她心里」「她其实」「她想要」「她害怕」这类句子删掉）。\n不写性格评价和类型标签（温柔、傲娇、腹黑、高冷……）。\n正文没写到的不补、不推测。\n本表的列说明里专门要求写人物认知、关系、心理、性格的那几列，照那几列自己的说明写；上面几条只管其余的列。\n【手账本·拼表结束】", "initNode": "故事开始时，设定或开场里写明关系的配角，每一对插入一行。", "deleteNode": "禁止。关系断了就在当前状态里写明，不删除。", "updateNode": "两人之间又发生了关键的事、或者相处状态变了时，更新交往经过和当前状态。\nSQL示例: UPDATE hb_npc_relations SET person_b = '示例人物B' WHERE person_a = '示例人物A';", "insertNode": "正文里两个配角第一次有了实质来往时，插入一行。\nSQL示例: INSERT INTO hb_npc_relations (person_a, person_b, history, status) VALUES ('示例人物A', '示例人物B', '示例交往经过', '示例当前状态');", "ddl": "CREATE TABLE hb_npc_relations ( -- 手账本·配角关系表\n  row_id INTEGER PRIMARY KEY, -- 行号\n  person_a TEXT, -- 人物A\n  person_b TEXT, -- 人物B\n  history TEXT, -- 交往经过\n  status TEXT -- 当前状态\n);"}, "content": [["row_id", "人物A", "人物B", "交往经过", "当前状态"]], "updateConfig": {"uiSentinel": -1, "contextDepth": -1, "updateFrequency": -1, "batchSize": -1, "skipFloors": -1, "groupId": -1}, "exportConfig": {"enabled": false, "splitByRow": false, "entryName": "手账本·配角关系表", "entryType": "constant", "keywords": "", "preventRecursion": true, "injectionTemplate": "", "extraIndexEnabled": false, "extraIndexEntryName": "手账本·配角关系表-索引", "extraIndexColumns": [], "extraIndexColumnModes": {}, "extraIndexInjectionTemplate": "", "sqlInjectionTemplate": "", "entryPlacement": {"position": "at_depth_as_system", "depth": 2, "order": 10000}, "extraIndexPlacement": {"position": "at_depth_as_system", "depth": 2, "order": 10010}, "fixedEntryPlacement": {"position": "at_depth_as_system", "depth": 2, "order": 99990}, "fixedIndexPlacement": {"position": "at_depth_as_system", "depth": 2, "order": 99991}, "injectIntoWorldbook": false}}};        // 构建时换成配套表格里的六张表：纪要表、重要角色表、四张「手账本·」专属表
  const STITCH_BEGIN = STITCH_BLOCK.split('\n')[0];
  const STITCH_END = STITCH_BLOCK.split('\n').slice(-1)[0];
  const OWN_TABLE_PREFIX = '手账本·';
  const OWN_SHEET_NAMES = Object.keys(STITCH_SHEETS).filter((n) => n.indexOf(OWN_TABLE_PREFIX) === 0);
  function isOwnSheet(name) { return String(name || '').indexOf(OWN_TABLE_PREFIX) === 0; }
  const stitchEsc = (s) => String(s).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  // 一段规则 = 开始标记到最近的结束标记，中间不许再出现开始标记：玩家原文里单独写了一个开始标记时，
  // 从它那里起不算一段，不会连着玩家后面的原文一起被当成规则删掉
  const STITCH_PAIR = stitchEsc(STITCH_BEGIN) + '(?:(?!' + stitchEsc(STITCH_BEGIN) + ')[\\s\\S])*?' + stitchEsc(STITCH_END);
  const STITCH_RE = new RegExp('\\s*' + STITCH_PAIR, 'g');
  const STITCH_TEST = new RegExp(STITCH_PAIR);

  // 表里专门写人物认知、关系变化、心理、性格的列：分工规则管不到这几列（规则里写了它们照列的说明写），面板上提醒一句。
  // 认表头和 DDL 里的列名、注释；「与主角的关系」这类只写关系事实的列不算
  const MIND_COL = /认知|心理|情绪|心情|感受|想法|内心|动机|好感|态度|印象|看法|性格|关系(?:变化|阶段|值|度)|cognition|psych|emotion|feeling|mood|affinity|attitude|personality|relation(?:ship)?_?(?:change|stage|level|value)/i;
  function mindCols(cols, ddl) {
    const out = [];
    const add = (n) => { const t = String(n || '').trim(); if (t && out.indexOf(t) === -1) out.push(t); };
    (cols || []).forEach((c) => { if (MIND_COL.test(c)) add(c); });
    // DDL 一行一列（行号那一列除外），顺序和表头一样：英文列名，「--」后面是中文名。
    // 按顺序对到表头上，报表头的名字（数据库面板里看到的）；表头那一轮已经记下的不再记
    let i = -1;
    String(ddl || '').split('\n').forEach((l) => {
      const m = l.match(/^\s*([A-Za-z_]\w*)\s+[A-Za-z]+[^-\n]*(?:--\s*(.+))?$/);
      if (!m || /^(CREATE|PRIMARY)$/i.test(m[1])) return;
      if (/^row_id$/i.test(m[1])) return;
      i += 1;
      const label = (m[2] || '').trim();
      if (!MIND_COL.test(m[1]) && !MIND_COL.test(label)) return;
      const h = (cols || [])[i];
      if ((h && out.indexOf(h) !== -1) || out.indexOf(label) !== -1 || out.indexOf(m[1]) !== -1) return;
      add(h || label || m[1]);
    });
    return out;
  }

  function stitchApi() {
    try {
      const a = TOP.AutoCardUpdaterAPI;
      return a && typeof a.getTableTemplate === 'function' && typeof a.importTemplateFromData === 'function' ? a : null;
    } catch (e) {
      return null;
    }
  }

  function isStitched(note) {
    return STITCH_TEST.test(String(note || ''));
  }

  function unstitchNote(note) {
    return String(note || '').replace(STITCH_RE, '').replace(/\s+$/, '');
  }

  function stitchNote(note) {
    const base = unstitchNote(note);
    return (base ? base + '\n\n' : '') + STITCH_BLOCK;
  }

  // 读这个聊天现在用的表格模板。返回 { tpl, sheets } 或 { error }
  async function readStitchTemplate() {
    const api = stitchApi();
    if (!api) return { error: '没检测到数据库' };
    let t = null;
    try { t = await api.getTableTemplate({ scope: 'chat' }); } catch (e) { t = null; }
    if (typeof t === 'string') {
      try { t = JSON.parse(t); } catch (e) { t = null; }
    }
    if (!t || typeof t !== 'object') return { error: '读不到这个聊天的表格模板' };
    const sheets = Object.keys(t)
      .filter((k) => k.indexOf('sheet_') === 0 && t[k] && typeof t[k] === 'object')
      .map((k) => {
        const s = t[k];
        const head = Array.isArray(s.content) && Array.isArray(s.content[0])
          ? s.content[0].slice(1).map((x) => String(x == null ? '' : x).trim()) : [];
        const ec = s.exportConfig && typeof s.exportConfig === 'object' ? s.exportConfig : {};
        const name = String(s.name || '').trim();
        const sd = s.sourceData && typeof s.sourceData === 'object' ? s.sourceData : {};
        const note = String(sd.note || '');
        const def = isOwnSheet(name) && STITCH_SHEETS[name];
        return { key: k, name, order: Number(s.orderNo) || 0, cols: head,
          stitched: isStitched(note),
          mind: isOwnSheet(name) ? [] : mindCols(head, sd.ddl),
          // 拼过、但拼进去的还是旧版规则（专属表：说明、触发和列定义不是最新的）：再点一次一键拼表就换成新的
          outdated: def ? Object.keys(def.sourceData || {}).some((f) => JSON.stringify(sd[f]) !== JSON.stringify(def.sourceData[f]))
            : isStitched(note) && note.indexOf(STITCH_BLOCK) === -1,
          // 专属表旧版没设「注入到世界书条目」：数据库默认当它开着，整张表会进正文提示词
          leaks: isOwnSheet(name) && ec.injectIntoWorldbook === undefined,
          // 更新频率 0：数据库不再自动填这张表（数据留着）
          paused: !!(s.updateConfig && s.updateConfig.updateFrequency === 0) };
      })
      .filter((s) => s.name)
      .sort((a, b) => a.order - b.order);
    return { tpl: t, sheets };
  }

  function stitchReads(name) {
    return DB_MEMO_NAMES.indexOf(name) !== -1 || DB_PEOPLE_NAMES.indexOf(name) !== -1;
  }

  // 往哪几张表里拼规则的默认勾选（只管玩家的表，专属表自己带着规则）。这份模板里玩家的表一张都还没拼过：
  // 勾手账本读的、带「姓名」这类列（写到人）的表；拼过以后就照现在的样子勾，玩家取消过的表不会自己又勾回来
  function stitchByDefault(sheet, anyStitched) {
    if (anyStitched) return sheet.stitched;
    if (sheet.name.indexOf(OWN_TABLE_PREFIX) === 0 || stitchReads(sheet.name)) return true;
    return sheet.cols.some((c) => /^(姓名|角色名|人物名?|名字)$/.test(c));
  }

  // 常夜灯专属表里，这个聊天的模板还没有的
  function ownMissing(sheets) {
    return OWN_SHEET_NAMES.filter((n) => !sheets.some((s) => s.name === n));
  }

  // 专属表和玩家模板里意思相近的表：还没加专属表时提醒一句，不要就别勾。按表名认，认出一张就够
  const OWN_OVERLAP = {
    '手账本·知情表': /秘密|知情|隐瞒|情报/,
    '手账本·约定表': /约定|承诺|备忘|待办/,
    '手账本·重大事件表': /重大|蝴蝶|伏笔|大事/,
    '手账本·配角关系表': /关系/,
  };
  function ownOverlap(sheets) {
    const out = {};
    ownMissing(sheets).forEach((n) => {
      const re = OWN_OVERLAP[n];
      const hit = re && sheets.find((s) => !isOwnSheet(s.name) && !stitchReads(s.name) && re.test(s.name));
      if (hit) out[n] = hit.name;
    });
    return out;
  }

  // 手账本要读、这个聊天的模板里又没有的表：只补配套表格里有的这两张
  function stitchMissing(sheets) {
    const has = (names) => sheets.some((s) => names.indexOf(s.name) !== -1);
    const out = [];
    if (!has(DB_MEMO_NAMES)) out.push('纪要表');
    if (!has(DB_PEOPLE_NAMES)) out.push('重要角色表');
    return out.filter((n) => STITCH_SHEETS[n]);
  }

  // want：{ 表名: true 拼上 / false 拿掉 }，没列出来的表不动（专属表不在这里管）；add：要加的表名（专属表、缺的纪要表 / 重要角色表）。
  // 已经有的专属表：说明、各种触发、列定义换成配套表格里最新的那份，数据不动；
  // 注入设置只补一项「不进正文」，而且只补没设过的（玩家在数据库里自己打开的不改）。
  // 整份模板读出来、只改要改的地方、原样写回这个聊天：数据库按表名合并，别的表和数据行都不受影响。
  // fill：{ 专属表名: true 接着填 / false 不再填 }，只管已经有的专属表：不再填＝更新频率设 0（数据库不再自动填，数据留着），
  // 接着填＝换回配套表格里的频率（跟全局走）。
  // 返回 { changed, removed, added, refreshed, muted, paused, resumed } / { unchanged: true } / { skipped: true } / { error }
  async function stitchTables(want, add, fill) {
    const api = stitchApi();
    if (!api) return { error: '没检测到数据库' };
    const chatId = currentChatId();
    const cur = await readStitchTemplate();
    if (cur.error) return cur;
    const tpl = JSON.parse(JSON.stringify(cur.tpl));
    const w = want || {};
    let changed = 0;
    let removed = 0;
    cur.sheets.forEach((s) => {
      if (isOwnSheet(s.name) || !Object.prototype.hasOwnProperty.call(w, s.name)) return;
      const sd = tpl[s.key].sourceData || (tpl[s.key].sourceData = {});
      const old = String(sd.note || '');
      if (w[s.name]) {
        const next = stitchNote(old);
        if (next !== old) { sd.note = next; changed += 1; }
      } else if (isStitched(old)) {
        sd.note = unstitchNote(old);
        removed += 1;
      }
    });
    let refreshed = 0;
    let muted = 0;
    let paused = 0;
    let resumed = 0;
    const f = fill || {};
    cur.sheets.forEach((s) => {
      if (!isOwnSheet(s.name) || !Object.prototype.hasOwnProperty.call(f, s.name)) return;
      const def = STITCH_SHEETS[s.name];
      const uc = Object.assign({}, tpl[s.key].updateConfig || {});
      if (!f[s.name] && !s.paused) { uc.updateFrequency = 0; paused += 1; }
      else if (f[s.name] && s.paused) {
        const back = def && def.updateConfig && Number.isFinite(def.updateConfig.updateFrequency) ? def.updateConfig.updateFrequency : -1;
        uc.updateFrequency = back === 0 ? -1 : back;
        resumed += 1;
      } else return;
      tpl[s.key].updateConfig = uc;
    });
    cur.sheets.forEach((s) => {
      const def = isOwnSheet(s.name) && STITCH_SHEETS[s.name];
      if (!def) return;
      const sd = tpl[s.key].sourceData || (tpl[s.key].sourceData = {});
      const next = Object.assign({}, sd, JSON.parse(JSON.stringify(def.sourceData || {})));
      if (JSON.stringify(next) !== JSON.stringify(sd)) { tpl[s.key].sourceData = next; refreshed += 1; }
      if (s.leaks) {
        tpl[s.key].exportConfig = Object.assign({}, tpl[s.key].exportConfig || {}, { injectIntoWorldbook: false });
        muted += 1;
      }
    });
    const missing = stitchMissing(cur.sheets).concat(ownMissing(cur.sheets));
    const added = [];
    let order = cur.sheets.reduce((m, s) => Math.max(m, s.order), -1);
    (add || []).forEach((n) => {
      if (missing.indexOf(n) === -1 || added.indexOf(n) !== -1) return;
      const sh = JSON.parse(JSON.stringify(STITCH_SHEETS[n]));
      let key = sh.uid;
      while (tpl[key]) key += 'x';                        // 内部 ID 要和键一致；数据库会按表名重生，这里只求不撞
      sh.uid = key;
      order += 1;
      sh.orderNo = order;
      tpl[key] = sh;
      added.push(n);
    });
    if (!changed && !removed && !refreshed && !muted && !paused && !resumed && !added.length) {
      return { unchanged: true, changed: 0, removed: 0, refreshed: 0, muted: 0, paused: 0, resumed: 0, added: [] };
    }
    if (DISPOSED || chatId !== currentChatId()) return { skipped: true };
    let r = null;
    try {
      r = await api.importTemplateFromData(tpl, { scope: 'chat', dataMode: 'seed' });
    } catch (e) {
      return { error: String((e && e.message) || e) };
    }
    if (!r || r.success === false) {
      const why = r && (r.error || (Array.isArray(r.blockers) && r.blockers.map((b) => (b && b.message) || String(b)).join('；')));
      return { error: why || '数据库没接受这份模板' };
    }
    return { changed, removed, added, refreshed, muted, paused, resumed };
  }

  // ---------- 另存为预设 ----------
  // 把这个聊天现在的表格模板（拼好的那份）存成数据库里的一个命名预设。
  // 拼表写回模板以后，数据库会把这个聊天已经填进去的数据行也记进这个聊天的模板，原样存出去新聊天就会带着旧记录：
  // 存之前把每张表的行都拿掉，只留表头（presetTemplate）。全局默认模板本身可能就是旧版存坏的那份，拿它当「本来就有的起始行」靠不住，
  // 所以起始行也不留，新聊天的第一行由数据库照表格说明自己填。
  // 数据库自己遇到同名会直接覆盖，所以先查一遍：同名又没说覆盖，就返回 { dup } 让玩家选。
  // setGlobal：存完再设成全局默认（所有跟随全局的聊天都会换成这一套）
  function presetApi() {
    const a = stitchApi();
    return a && typeof a.getTemplatePresetNames === 'function' ? a : null;
  }

  function stitchPresetNames() {
    const a = presetApi();
    if (!a) return [];
    try { return (a.getTemplatePresetNames() || []).map((x) => String(x)); } catch (e) { return []; }
  }

  // 默认名：手账本拼表-卡名-月日
  function defaultPresetName() {
    const d = new Date();
    return '手账本拼表-' + cardLabel() + '-' + (d.getMonth() + 1) + '月' + d.getDate() + '日';
  }

  // 同名时往后加 (2)(3)…
  function freePresetName(name) {
    const names = stitchPresetNames();
    const base = String(name || '').replace(/\s*\(\d+\)$/, '');
    let n = base;
    for (let i = 2; names.indexOf(n) !== -1; i += 1) n = base + ' (' + i + ')';
    return n;
  }

  // 只留表头和起始行：content 第一行是表头；后面的行、seedRows 只留全局模板里同名表也有的（按整行比）
  function presetTemplate(tpl, base) {
    const t = JSON.parse(JSON.stringify(tpl));
    const keep = {};
    Object.keys(base || {}).forEach((k) => {
      const b = base[k];
      if (k.indexOf('sheet_') !== 0 || !b || typeof b !== 'object' || !b.name) return;
      keep[b.name] = (Array.isArray(b.content) ? b.content.slice(1) : []).concat(Array.isArray(b.seedRows) ? b.seedRows : []).map((r) => JSON.stringify(r));
    });
    let dropped = 0;
    Object.keys(t).forEach((k) => {
      const sh = t[k];
      if (k.indexOf('sheet_') !== 0 || !sh || typeof sh !== 'object') return;
      const ok = keep[sh.name] || [];
      if (Array.isArray(sh.content) && sh.content.length > 1) {
        const rest = sh.content.slice(1).filter((r) => ok.indexOf(JSON.stringify(r)) !== -1);
        dropped += sh.content.length - 1 - rest.length;
        sh.content = sh.content.slice(0, 1).concat(rest);
      }
      if (Array.isArray(sh.seedRows) && sh.seedRows.length) {
        const rest = sh.seedRows.filter((r) => ok.indexOf(JSON.stringify(r)) !== -1);
        dropped += sh.seedRows.length - rest.length;
        sh.seedRows = rest;
      }
    });
    return { tpl: t, dropped };
  }

  // 返回 { ok, name, global, warning } / { dup: name } / { error }
  async function savePreset(name, setGlobal, overwrite) {
    const api = presetApi();
    if (!api) return { error: '这个版本的数据库没有存预设的接口' };
    const nm = String(name || '').trim();
    if (!nm) return { error: '先起个预设名' };
    if (!overwrite && stitchPresetNames().indexOf(nm) !== -1) return { dup: nm };
    const cur = await readStitchTemplate();
    if (cur.error) return cur;
    const clean = presetTemplate(cur.tpl, null);
    let r = null;
    try { r = await api.importTemplateFromData(clean.tpl, { scope: 'global', presetName: nm }); } catch (e) { return { error: String((e && e.message) || e) }; }
    if (!r || r.success === false) return { error: (r && (r.error || r.message)) || '数据库没存上' };
    if (!setGlobal) return { ok: true, name: nm, global: false };
    let s = null;
    try { s = await api.switchTemplatePreset(nm, { scope: 'global' }); } catch (e) { s = { success: false, error: String((e && e.message) || e) }; }
    if (!s || s.success === false) {
      const why = s && (s.error || (Array.isArray(s.blockers) && s.blockers.map((b) => (b && b.message) || String(b)).join('；')) || s.message);
      return { ok: true, name: nm, global: false, warning: '存好了，但没设成全局默认：' + (why || '数据库没接受') };
    }
    return { ok: true, name: nm, global: true, warning: s.warning || '' };
  }

  // ---------- 修坏档：清理预设、清掉带过来的旧记录（DESIGN.md「修坏档」） ----------
  // 旧版「另存为预设」会把那个聊天填好的行一起存进预设；用这份预设开的新聊天一开局就带着那些旧记录。
  // 清理预设时把拿掉的行按「表名 + 各格内容」记一份指纹（全局变量），清掉带过来的旧记录只拿当前聊天的数据和它比：
  // 只认玩家亲手勾选清理过的预设里的行，没勾的预设、全局默认模板里的行（可能是模板本来就带的起始行）不算。行号那一格不算
  const OLD_ROWS_NS = NS + '_oldrows';
  const OLD_ROWS_MAX = 2000;

  function tplOf(t) {
    if (typeof t === 'string') { try { t = JSON.parse(t); } catch (e) { t = null; } }
    return t && typeof t === 'object' ? t : null;
  }
  function rowKey(r) {
    return JSON.stringify((Array.isArray(r) ? r.slice(1) : [r]).map((x) => (x == null ? '' : String(x).trim())));
  }
  function emptyRow(r) {
    return !Array.isArray(r) || r.slice(1).every((x) => x == null || String(x).trim() === '');
  }
  // 一份模板里每张表带了几行（表头不算，seedRows 也算）
  function tplRows(t) {
    const out = { total: 0, sheets: {}, keys: {} };
    Object.keys(t || {}).forEach((k) => {
      const sh = t[k];
      if (k.indexOf('sheet_') !== 0 || !sh || typeof sh !== 'object' || !sh.name) return;
      const rows = (Array.isArray(sh.content) ? sh.content.slice(1) : []).concat(Array.isArray(sh.seedRows) ? sh.seedRows : []).filter((r) => !emptyRow(r));
      if (!rows.length) return;
      out.total += rows.length;
      out.sheets[sh.name] = (out.sheets[sh.name] || 0) + rows.length;
      out.keys[sh.name] = (out.keys[sh.name] || []).concat(rows.map(rowKey));
    });
    return out;
  }

  function readOldRows() {
    try {
      const v = (getVariables({ type: 'global' }) || {})[OLD_ROWS_NS];
      return v && typeof v === 'object' ? v : {};
    } catch (e) { return {}; }
  }
  function rememberOldRows(keys) {
    try {
      updateVariablesWith((g) => {
        const cur = g[OLD_ROWS_NS] && typeof g[OLD_ROWS_NS] === 'object' ? g[OLD_ROWS_NS] : {};
        Object.keys(keys).forEach((n) => {
          const list = (cur[n] || []).concat(keys[n]).filter((x, i, a) => a.indexOf(x) === i);
          cur[n] = list.slice(-OLD_ROWS_MAX);
        });
        g[OLD_ROWS_NS] = cur;
        return g;
      }, { type: 'global' });
    } catch (e) { /* 记不下就只能比预设里还在的行 */ }
  }

  // 带着数据行的预设，和全局默认模板（它是单独一份，清了预设它不跟着变）。返回 { list: [{ name, rows, sheets, global? }] } / { error }
  const GLOBAL_DEFAULT = '全局默认模板';
  async function dirtyPresets() {
    const api = presetApi();
    if (!api) return { error: '这个版本的数据库读不了预设' };
    const list = [];
    for (const n of stitchPresetNames()) {
      let t = null;
      try { t = tplOf(await api.getTableTemplate({ scope: 'global', presetName: n })); } catch (e) { t = null; }
      const c = t && tplRows(t);
      if (c && c.total) list.push({ name: n, rows: c.total, sheets: c.sheets });
    }
    let g = null;
    try { g = tplOf(await api.getTableTemplate({ scope: 'global' })); } catch (e) { g = null; }
    const gc = g && tplRows(g);
    if (gc && gc.total) list.push({ name: GLOBAL_DEFAULT, global: true, rows: gc.total, sheets: gc.sheets });
    return { list };
  }

  // a 的行指纹是不是全在 b 里
  function rowsWithin(a, b) {
    return Object.keys(a.keys).every((n) => (a.keys[n] || []).every((k) => (b.keys[n] || []).indexOf(k) !== -1));
  }
  // 两份模板的表名和表头一样
  function sameShape(a, b) {
    const shape = (t) => Object.keys(t || {})
      .filter((k) => k.indexOf('sheet_') === 0 && t[k] && t[k].name)
      .map((k) => t[k].name + '|' + JSON.stringify(((Array.isArray(t[k].content) && t[k].content[0]) || []).slice(1)))
      .sort().join('\n');
    return shape(a) === shape(b);
  }

  // 把勾上的预设清成只有表头，同名覆盖存回去；拿掉的行记指纹。
  // 全局默认模板是数据库单独存的一份，覆盖预设它不跟着变（实测）：所有预设里只有一份和它表名、表头、带的行都一样，
  // 而且这一份这次清过，清完就把它重新设成全局默认；对上好几份认不准就不动，提示去数据库里设。
  // 勾了「全局默认模板」、又没换成清过的预设的，清好存成「全局默认模板（清理后）」再设成全局默认。
  // 返回 { done: [名字], failed: [{ name, why }], dropped, regloballed }
  async function cleanPresets(names) {
    const api = presetApi();
    if (!api) return { error: '这个版本的数据库读不了预设' };
    const done = [];
    const failed = [];
    let dropped = 0;
    let regloballed = '';
    let g = null;
    try { g = tplOf(await api.getTableTemplate({ scope: 'global' })); } catch (e) { g = null; }
    const gc = g ? tplRows(g) : { total: 0, keys: {} };
    const save = async (n, t) => {
      const c = tplRows(t);
      const clean = presetTemplate(t, null);
      let r = null;
      try { r = await api.importTemplateFromData(clean.tpl, { scope: 'global', presetName: n }); } catch (e) { r = { success: false, error: String((e && e.message) || e) }; }
      if (!r || r.success === false) { failed.push({ name: n, why: (r && (r.error || r.message)) || '数据库没存上' }); return null; }
      rememberOldRows(c.keys);
      dropped += clean.dropped;
      return c;
    };
    const reglobal = async (n) => {
      let s = null;
      try { s = typeof api.switchTemplatePreset === 'function' ? await api.switchTemplatePreset(n, { scope: 'global' }) : null; } catch (e) { s = null; }
      if (s && s.success !== false) regloballed = n;
      else failed.push({ name: GLOBAL_DEFAULT, why: '没能重新设成全局默认，在数据库里把「' + n + '」设一次全局默认' });
    };
    // 全局默认是从哪一份预设来的：清之前先找，所有预设里和它一模一样（表名、表头、带的行）的只有一份才算认准
    const origin = [];
    if (gc.total) {
      for (const n of stitchPresetNames()) {
        let t = null;
        try { t = tplOf(await api.getTableTemplate({ scope: 'global', presetName: n })); } catch (e) { t = null; }
        if (!t) continue;
        const c = tplRows(t);
        if (c.total === gc.total && rowsWithin(gc, c) && sameShape(g, t)) origin.push(n);
      }
    }
    for (const n of (names || []).filter((x) => x !== GLOBAL_DEFAULT)) {
      let t = null;
      try { t = tplOf(await api.getTableTemplate({ scope: 'global', presetName: n })); } catch (e) { t = null; }
      if (!t) { failed.push({ name: n, why: '读不到' }); continue; }
      const c = await save(n, t);
      if (!c) continue;
      done.push(n);
    }
    if (origin.length === 1 && done.indexOf(origin[0]) !== -1) await reglobal(origin[0]);
    else if (origin.length > 1 && origin.some((n) => done.indexOf(n) !== -1) && (names || []).indexOf(GLOBAL_DEFAULT) === -1) {
      failed.push({ name: GLOBAL_DEFAULT, why: '有几份预设和它一样，认不准是哪一份；在数据库里把清过的那份重新设成全局默认，或者勾上「全局默认模板」再清一次' });
    }
    if ((names || []).indexOf(GLOBAL_DEFAULT) !== -1 && gc.total && !regloballed) {
      const n = freePresetName(GLOBAL_DEFAULT + '（清理后）');
      if (await save(n, g)) {
        done.push(GLOBAL_DEFAULT);
        await reglobal(n);
      }
    }
    return { done, failed, dropped, regloballed };
  }

  // 坏预设里的行：清理预设时记下的指纹。{ 表名: [指纹] }
  function knownOldRows() {
    const old = readOldRows();
    const known = {};
    Object.keys(old).forEach((n) => { if (Array.isArray(old[n]) && old[n].length) known[n] = old[n]; });
    return known;
  }

  // 一行的各格（不含行号那一格），去掉首尾空白
  function rowCells(r) {
    return (Array.isArray(r) ? r.slice(1) : []).map((x) => (x == null ? '' : String(x).trim()));
  }
  // 当前这一行是不是坏预设里的那一行：数据库把带过来的行写进表时会重排编号那一格，所以两边有内容的格子里最多一格对不上也算；
  // 只有一两格有内容的要全对上。这一行比旧行多填了的格子也算对不上（模板的起始行被这个聊天填满了，就不是旧记录）
  function sameOldRow(cur, old) {
    if (!old.some((x) => x !== '')) return false;
    let filled = 0;
    let diff = 0;
    for (let i = 0; i < Math.max(cur.length, old.length); i += 1) {
      const a = cur[i] || '';
      const b = old[i] || '';
      if (a === '' && b === '') continue;
      filled += 1;
      if (a !== b) diff += 1;
    }
    return filled >= 3 ? diff <= 1 : diff === 0;
  }

  // 当前聊天表里和坏预设里的行对得上的行（按上面的规则）。返回 { tables: [{ name, rows: [{ index, key, text }] }], total, seeds, noPrints } / { error }。
  // index 是数据库 deleteRow 用的行号（表头是 0），key 是这一行各格的内容。noPrints：还没清理过预设，没有可比的。
  // 用坏预设开的聊天，带过来的行先放在数据库的起始行（seedRows）里，数据库第一次填表时才写进表（实测）；起始行改不了、也删不了，
  // seeds 是起始行里对得上的行数：表里还没有、起始行里有，说明这个聊天还没填过表，要等填完表再删
  async function inheritedRows() {
    const api = stitchApi();
    if (!api || typeof api.exportTableAsJson !== 'function') return { error: '没检测到数据库' };
    const known = knownOldRows();
    if (!Object.keys(known).length) return { tables: [], total: 0, noPrints: true };
    let data = null;
    try { data = tplOf(api.exportTableAsJson()); } catch (e) { data = null; }
    if (!data) return { error: '读不到这个聊天的表格数据' };
    const tables = [];
    let total = 0;
    let seeds = 0;
    Object.keys(data).forEach((k) => {
      const sh = data[k];
      if (k.indexOf('sheet_') !== 0 || !sh || !sh.name || !known[sh.name] || !Array.isArray(sh.content)) return;
      const olds = known[sh.name].map((x) => { try { return JSON.parse(x); } catch (e) { return null; } }).filter(Array.isArray);
      (Array.isArray(sh.seedRows) ? sh.seedRows : []).forEach((r) => { if (!emptyRow(r) && olds.some((o) => sameOldRow(rowCells(r), o))) seeds += 1; });
      const rows = [];
      sh.content.forEach((r, i) => {
        if (i === 0 || emptyRow(r)) return;
        const cur = rowCells(r);
        if (!olds.some((o) => sameOldRow(cur, o))) return;
        rows.push({ index: i, key: JSON.stringify(cur), text: cur.filter(Boolean).join(' · ').slice(0, 60) });
      });
      if (rows.length) { tables.push({ name: sh.name, rows }); total += rows.length; }
    });
    return { tables, total, seeds };
  }

  // 删掉玩家确认过的那几行：查找和点删之间数据库可能又填过表、行号变了，所以删之前重查一遍，按内容对上玩家看到的那几行，
  // 再按新行号每张表从后往前删（免得行号错位）；删完再查，按实际少了几行算。返回 { deleted, left } / { error }
  async function clearInherited(found) {
    const api = stitchApi();
    if (!api || typeof api.deleteRow !== 'function') return { error: '这个版本的数据库删不了行' };
    const chatId = currentChatId();
    const want = {};
    ((found && found.tables) || []).forEach((t) => { want[t.name] = t.rows.map((r) => r.key); });
    const pick = (f) => ((f && f.tables) || []).map((t) => ({ name: t.name, rows: t.rows.filter((r) => (want[t.name] || []).indexOf(r.key) !== -1) }))
      .filter((t) => t.rows.length);
    const now = await inheritedRows();
    if (now.error) return now;
    const todo = pick(now);
    const before = todo.reduce((n, t) => n + t.rows.length, 0);
    for (const t of todo) {
      const idx = t.rows.map((r) => r.index).sort((a, b) => b - a);
      for (const i of idx) {
        if (currentChatId() !== chatId) return { error: '删到一半换了聊天，停下了；回到那个聊天再查一次' };
        try { await api.deleteRow({ tableName: t.name, rowIndex: i }); } catch (e) { /* 删不掉的下面再查出来 */ }
      }
    }
    const again = await inheritedRows();
    const left = again && !again.error ? pick(again).reduce((n, t) => n + t.rows.length, 0) : 0;
    return { deleted: Math.max(0, before - left), left };
  }

  // ======================== 悬浮窗样式 ========================
  // 规范见同目录 DESIGN.md（「场记板」主题，浅色毛玻璃）。一张注进酒馆顶层 head 的样式表，
  // 选择器一律带 #hb- / .hb- 前缀，不碰酒馆本体。
  //
  // 设计变量照 DESIGN.md「设计变量」原样接进来，但只挂在悬浮球、面板这两个根上，
  // 不挂 :root —— --bg / --border / --accent 这些名字太通用，挂到酒馆根上会和酒馆或别的扩展撞车。

  // 两张图由 构建.py 从 assets/ 压成 WebP 后替换进来（见 DESIGN.md「素材」）
  const ASSET_AVATAR = 'data:image/webp;base64,';
  const ASSET_PERCH = 'data:image/webp;base64,';

  const STYLE_ID = 'hb-style';

  const CSS = `
#hb-fab,#hb-panel{
  /* 颜色 */
  --bg:        rgba(248, 246, 253, .86);
  --text-1:    #231D33;
  --text-2:    #574E6E;
  --text-3:    #6E6688;
  --border:    rgba(92, 72, 160, .16);
  --accent:    #7457D6;
  --on-accent: #FFFFFF;
  --accent-2:  #8A611C;
  --card-1:    #FFFFFF;
  --card-2:    #F2EEFB;
  --ok:        #23804F;
  --warn:      #B8550F;
  --danger:    #C9364B;

  /* 质感 */
  --shadow: 0 16px 40px -12px rgba(38, 24, 82, .32),
            0 2px 8px rgba(38, 24, 82, .08);
  --blur:   blur(18px) saturate(140%);
  --radius-lg: 16px;
  --radius-sm: 10px;

  /* 字号 / 行高 */
  --fs-title:  15px;  --lh-title:  22px;
  --fs-body:   13px;  --lh-body:   20px;
  --fs-row:    13px;  --lh-row:    20px;
  --fs-status: 12px;  --lh-status: 18px;
  --fs-tag:    11px;  --lh-tag:    16px;
  --fs-note:   11px;  --lh-note:   16px;

  /* 动效 */
  --dur-spin:  .9s;
  --dur-blink: 1.2s;
  --dur-hover: .16s;

  /* 组件里用到的派生值（数值来自 DESIGN.md 各组件小节） */
  --avatar-bg:    #EEE9FB;
  --shadow-hover: 0 20px 44px -12px rgba(38, 24, 82, .42), 0 4px 10px rgba(38, 24, 82, .12);
  --shadow-press: 0 8px 18px -10px rgba(38, 24, 82, .32), 0 1px 4px rgba(38, 24, 82, .08);
  --border-dash:  rgba(92, 72, 160, .24);
  --bg-solid:     rgba(248, 246, 253, .97);   /* 没有模糊时的面板底色，见下面「关闭模糊」那段 */
  --accent-fill:  #7457D6;                    /* 强调色铺底、上面放白字（按钮、圆圈勾、进度条）。深色下和 --accent 分开 */
  --field:        #FFFFFF;                    /* 输入框、代码框、下拉框的底 */
  --slate-a:      #231D33;                    /* 场记板斜纹，深浅色都不变 */
  --slate-b:      #FFFFFF;
  --panel-solid:  #F8F6FD;                    /* 手机抽屉的实色底 */
  /* 氛围轨迹带：氛围池十个类别各一色，自己加的类别用 --mood-x（DESIGN.md「氛围轨迹」） */
  --mood-0: #D9A05B; --mood-1: #6FB27A; --mood-2: #D06A5A; --mood-3: #7C6FA8; --mood-4: #E08DAA;
  --mood-5: #6E93C6; --mood-6: #E3C04E; --mood-7: #4FB3B0; --mood-8: #9B5A7E; --mood-9: #9A9A8A; --mood-x: #BDB6CC;
  color-scheme: light;                        /* 告诉浏览器这是浅色面板：原生控件、滚动条按浅色画，强制深色别来反色 */
  font-family: var(--mainFontFamily, inherit);
}
/* 深色（DESIGN.md「深色」）：外观选深色，或者跟随酒馆而酒馆是深色主题时，面板和悬浮球挂 data-theme="dark" */
#hb-fab[data-theme="dark"],#hb-panel[data-theme="dark"]{
  --bg:        rgba(28, 26, 36, .88);
  --text-1:    #E8E6F0;
  --text-2:    #A9A4BC;
  --text-3:    #9A94AF;
  --border:    #36324A;
  --accent:    #A08CFF;
  --accent-fill: #6E56DC;
  --on-accent: #FFFFFF;
  --accent-2:  #D6A650;
  --card-1:    #252231;
  --card-2:    #2B2739;
  --field:     #14121B;
  --ok:        #5CC98E;
  --warn:      #F0A060;
  --danger:    #FF7A8C;
  --shadow: 0 16px 40px -12px rgba(0, 0, 0, .32),
            0 2px 8px rgba(0, 0, 0, .08);
  --shadow-hover: 0 20px 44px -12px rgba(0, 0, 0, .42), 0 4px 10px rgba(0, 0, 0, .12);
  --shadow-press: 0 8px 18px -10px rgba(0, 0, 0, .32), 0 1px 4px rgba(0, 0, 0, .08);
  --border-dash:  rgba(160, 140, 255, .24);
  --bg-solid:     rgba(28, 26, 36, .97);
  --panel-solid:  #1C1A24;
  --mood-0: #D8A868; --mood-1: #7DBF88; --mood-2: #D98373; --mood-3: #968AC4; --mood-4: #E59BB5;
  --mood-5: #83A6D6; --mood-6: #E0C465; --mood-7: #62C2BF; --mood-8: #B37196; --mood-9: #A8A898; --mood-x: #5A546C;
  color-scheme: dark;
}
#hb-fab *,#hb-panel *{box-sizing:border-box;}
#hb-fab svg,#hb-panel svg{flex:none;display:block;}

/* ---------- 悬浮球 ----------
   一律从上边量：酒馆给 html 加了 transform，html 又没有高度，fixed 元素是相对它定位的，
   用 bottom 会跑到屏幕上方去。vh / dvh 始终按视口算，不受这个影响。 */
#hb-fab{--fab:40px;position:fixed;right:14px;top:calc(100vh - 136px);top:calc(100dvh - 136px);z-index:9000;
  width:var(--fab);height:var(--fab);padding:0;margin:0;border:2px solid #fff;border-radius:50%;
  background:var(--avatar-bg);box-shadow:var(--shadow);cursor:pointer;user-select:none;touch-action:none;
  transition:transform var(--dur-hover) ease-out,box-shadow var(--dur-hover) ease-out;}
#hb-fab[data-size="big"]{--fab:52px;}
@media (pointer:fine) and (min-width:601px){#hb-fab[data-size="auto"]{--fab:52px;}}
#hb-fab .hb-av{display:block;width:100%;height:100%;border-radius:50%;object-fit:cover;pointer-events:none;-webkit-user-drag:none;}
#hb-fab:hover{transform:translateY(-2px);box-shadow:var(--shadow-hover);}
#hb-fab:active{transform:scale(.94);box-shadow:var(--shadow-press);}
#hb-fab.hb-dragging{transform:none;box-shadow:var(--shadow-hover);}
#hb-fab:focus-visible{outline:2px solid var(--accent);outline-offset:3px;}
/* 记状态中：比球大 8px 的转圈环。环画在边框外面，所以相对内边距框再往外让 6px */
#hb-fab .hb-ring{position:absolute;left:-6px;top:-6px;width:calc(var(--fab) + 8px);height:calc(var(--fab) + 8px);display:none;pointer-events:none;
  animation:hb-spin var(--dur-spin) linear infinite;}
#hb-fab.hb-busy .hb-ring{display:block;}
#hb-fab .hb-ring-trk{stroke:color-mix(in srgb,var(--accent) 18%,transparent);}
#hb-fab .hb-ring-arc{stroke:var(--accent);}
/* 状态点：右下角 12px，2px 白边，向外偏出 3px */
#hb-fab .hb-dot{position:absolute;right:-5px;bottom:-5px;width:12px;height:12px;border-radius:50%;
  border:2px solid #fff;display:none;pointer-events:none;}
#hb-fab.hb-fresh .hb-dot{display:block;background:var(--ok);}
#hb-fab.hb-stale .hb-dot{display:block;background:var(--warn);}
#hb-fab.hb-error .hb-dot{display:block;background:var(--danger);}
@keyframes hb-spin{to{transform:rotate(360deg)}}
@keyframes hb-blink{0%,100%{opacity:1}50%{opacity:.3}}

/* ---------- 面板外壳 ----------
   #hb-panel 只管定位；立绘趴在它上沿外面，所以圆角裁切放在里层的 .hb-shell 上。 */
#hb-panel{position:fixed;right:14px;top:calc(100vh - 146px);top:calc(100dvh - 146px);transform:translateY(-100%);
  z-index:9001;width:min(340px,calc(100vw - 28px));max-height:min(78vh,calc(100vh - 36px));
  display:none;flex-direction:column;color:var(--text-1);font-size:var(--fs-body);line-height:var(--lh-body);}
#hb-panel.hb-open{display:flex;}
#hb-panel .hb-perch{position:absolute;left:16px;bottom:calc(100% - 2px);height:110px;width:auto;z-index:1;
  pointer-events:none;user-select:none;-webkit-user-drag:none;}
#hb-panel.hb-no-perch .hb-perch{display:none;}
#hb-panel .hb-shell{flex:1 1 auto;min-height:0;display:flex;flex-direction:column;overflow:hidden;
  background:var(--bg);-webkit-backdrop-filter:var(--blur);backdrop-filter:var(--blur);
  border:1px solid var(--border);border-radius:var(--radius-lg);box-shadow:var(--shadow);}
/* 酒馆开了「关闭模糊」时会给 body 加 no-blur，用 !important 清掉所有 backdrop-filter。那是用户的性能设置，不去顶它；
   但 .86 的底色是配着模糊用的，没模糊时后面的聊天字会透出来，所以只在这种情况下换成接近实色。 */
body.no-blur #hb-panel .hb-shell{background:var(--bg-solid);}
@supports not ((backdrop-filter:blur(1px)) or (-webkit-backdrop-filter:blur(1px))){#hb-panel .hb-shell{background:var(--bg-solid);}}
#hb-panel .hb-slate{flex:none;height:6px;
  background:repeating-linear-gradient(-45deg,var(--slate-a) 0 8px,var(--slate-b) 8px 16px);}

/* 标题栏 */
#hb-panel .hb-hd{flex:none;display:flex;align-items:center;gap:8px;padding:8px 8px 8px 12px;
  border-bottom:1px solid var(--border);user-select:none;cursor:move;touch-action:none;}
