  background:var(--avatar-bg);border:2px solid #fff;}
#hb-panel .hb-hd-av img{display:block;width:100%;height:100%;object-fit:cover;pointer-events:none;-webkit-user-drag:none;}
#hb-panel .hb-title{flex:1;min-width:0;font-size:var(--fs-title);line-height:var(--lh-title);font-weight:700;
  color:var(--text-1);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
#hb-panel .hb-rerun{flex:none;height:28px;padding:0 10px;display:inline-flex;align-items:center;gap:4px;
  border:1px solid var(--border);border-radius:var(--radius-sm);background:var(--card-1);color:var(--text-2);
  font-family:inherit;font-size:var(--fs-status);line-height:var(--lh-status);cursor:pointer;
  transition:background-color var(--dur-hover) ease-out;}
#hb-panel .hb-rerun:hover:not(:disabled){background:var(--card-2);}
#hb-panel .hb-rerun:disabled{opacity:.5;cursor:default;}
#hb-panel .hb-ibtn{flex:none;width:32px;height:32px;padding:0;display:inline-flex;align-items:center;justify-content:center;
  border:0;border-radius:var(--radius-sm);background:transparent;color:var(--text-2);cursor:pointer;
  transition:background-color var(--dur-hover) ease-out,color var(--dur-hover) ease-out;}
