#hb-panel .hb-ibtn[aria-pressed="true"]{background:var(--card-2);color:var(--accent);}
#hb-panel button:focus-visible,#hb-panel a:focus-visible{outline:2px solid var(--accent);outline-offset:2px;}

/* 滚动区 */
#hb-panel .hb-body{flex:1 1 auto;min-height:0;overflow-y:auto;overflow-x:hidden;padding:12px;overscroll-behavior:contain;}
#hb-panel .hb-body::-webkit-scrollbar{width:6px;}
