#hb-panel .hb-go{flex:none;height:22px;padding:0 8px;border:0;border-radius:var(--radius-sm);background:var(--card-1);
  color:var(--accent);font-family:inherit;font-size:var(--fs-status);line-height:22px;font-weight:600;cursor:pointer;}

/* 场面块 */
#hb-panel .hb-scene{display:flex;flex-direction:column;gap:6px;padding:10px 12px;border-radius:var(--radius-sm);background:var(--card-2);}
