  border-radius:var(--radius-sm);background:var(--card-2);}
#hb-panel .hb-tpl-list{display:flex;flex-direction:column;gap:6px;max-height:220px;overflow:auto;}
#hb-panel .hb-tpl-rows{display:flex;flex-direction:column;gap:4px;align-items:stretch;}
#hb-panel .hb-check input[type="checkbox"]:disabled,#hb-panel .hb-check input[type="checkbox"]:disabled+span{opacity:.5;cursor:default;}
#hb-panel .hb-bs-who{font-size:var(--fs-tag);line-height:var(--lh-tag);font-weight:600;color:var(--text-3);}
#hb-panel .hb-cand{padding:8px 10px;border:1.5px solid transparent;border-radius:var(--radius-sm);background:var(--card-1);}
#hb-panel .hb-cand.pick{border-color:var(--accent);}
#hb-panel .hb-cand-main{display:flex;flex-direction:column;gap:4px;}
#hb-panel .hb-cand.out .hb-cand-main{opacity:.5;}
#hb-panel .hb-c1{display:flex;align-items:flex-start;gap:6px;}
#hb-panel .hb-c1 .hb-line{flex:1;min-width:0;font-size:var(--fs-row);line-height:var(--lh-row);color:var(--text-1);}
#hb-panel .hb-c1 .hb-p{flex:none;font-size:var(--fs-status);line-height:var(--lh-row);color:var(--text-2);font-variant-numeric:tabular-nums;}
#hb-panel .hb-ck{flex:none;width:16px;height:16px;margin-top:2px;border-radius:50%;background:var(--accent-fill);color:var(--on-accent);
  display:inline-flex;align-items:center;justify-content:center;}
#hb-panel .hb-c2{display:flex;align-items:center;gap:8px;}
#hb-panel .hb-c2 .hb-to{flex:none;font-size:var(--fs-note);line-height:var(--lh-note);color:var(--text-3);}
#hb-panel .hb-bar{flex:1;height:3px;border-radius:2px;background:var(--border);overflow:hidden;}
#hb-panel .hb-bar i{display:block;height:100%;background:var(--text-3);}
#hb-panel .hb-cand.pick .hb-bar i{background:var(--accent-fill);}
#hb-panel .hb-c3{font-size:var(--fs-note);line-height:var(--lh-note);color:var(--text-3);}
#hb-panel .hb-cwarn{display:flex;align-items:flex-start;gap:4px;margin-top:4px;
  font-size:var(--fs-note);line-height:var(--lh-note);color:var(--warn);}
#hb-panel .hb-cwarn svg{margin-top:2px;}
#hb-panel .hb-bs-note{font-size:var(--fs-note);line-height:var(--lh-note);color:var(--text-3);}
#hb-panel .hb-bs-foot{display:flex;justify-content:flex-end;gap:12px;font-size:var(--fs-note);line-height:var(--lh-note);
  color:var(--text-3);font-variant-numeric:tabular-nums;}
#hb-panel .hb-brief-text{white-space:pre-wrap;word-break:break-word;font-size:var(--fs-row);line-height:var(--lh-row);color:var(--text-1);}

/* 空状态 */
#hb-panel .hb-empty{margin:24px 0;text-align:center;font-size:var(--fs-body);line-height:var(--lh-body);color:var(--text-2);}

/* ---------- 设置页 ---------- */
#hb-panel .hb-set{display:flex;flex-direction:column;gap:18px;}
#hb-panel .hb-grp{display:flex;flex-direction:column;gap:10px;}
#hb-panel .hb-grp-hd h4{margin:0;font-size:var(--fs-body);line-height:var(--lh-body);font-weight:700;color:var(--text-1);}
#hb-panel .hb-grp-hd p,#hb-panel .hb-note{margin:0;font-size:var(--fs-note);line-height:var(--lh-note);color:var(--text-2);}
#hb-panel .hb-field{display:flex;flex-direction:column;gap:4px;margin:0;}
#hb-panel .hb-flabel{font-size:var(--fs-status);line-height:var(--lh-status);color:var(--text-2);}
#hb-panel .hb-muted{display:flex;flex-direction:column;gap:6px;}
#hb-panel .hb-add{display:flex;flex-direction:column;gap:4px;}
#hb-panel .hb-rel-edit{display:flex;flex-direction:column;gap:10px;}
#hb-panel .hb-rel-row{display:flex;flex-direction:column;gap:4px;}
#hb-panel .hb-rel-row select.hb-input{margin-top:0;}
#hb-panel .hb-rel-to{font-size:var(--fs-body);line-height:var(--lh-body);font-weight:600;color:var(--text-1);}
#hb-panel .hb-add-row{display:flex;align-items:center;gap:8px;}
#hb-panel .hb-add-row .hb-input{flex:1;min-width:0;}
#hb-panel .hb-add-row .hb-btn{flex:none;}
#hb-panel .hb-add-row .hb-btn[disabled]{filter:none;opacity:.6;cursor:default;}
#hb-panel .hb-muted-row{display:flex;align-items:center;gap:8px;font-size:var(--fs-body);line-height:var(--lh-body);color:var(--text-1);}
#hb-panel .hb-input{width:100%;height:32px;margin:0;padding:0 10px;border:1px solid var(--border);border-radius:var(--radius-sm);
  background:var(--field);color:var(--text-1);font-family:inherit;font-size:var(--fs-body);line-height:var(--lh-body);
  box-shadow:none;outline:none;max-height:none;
  transition:border-color var(--dur-hover) ease-out,box-shadow var(--dur-hover) ease-out;}
#hb-panel .hb-input:focus,#hb-panel .hb-input:focus-visible{border-color:var(--accent);outline:none;
  box-shadow:0 0 0 3px color-mix(in srgb,var(--accent) 18%,transparent);}
#hb-panel .hb-input::placeholder{color:var(--text-3);-webkit-text-fill-color:var(--text-3);opacity:1;}
/* 酒馆的美化主题常用 !important 给所有输入框换底色（手机浏览器的强制深色也会改），文字色却还是面板的深色，
   就成了黑底深字、密钥框又是白的。面板里的输入框、代码框、下拉框颜色锁住，跟着面板自己的配色走 */
#hb-panel .hb-input{background:var(--field) !important;color:var(--text-1) !important;-webkit-text-fill-color:var(--text-1) !important;}
#hb-panel select.hb-input option{background:var(--field);color:var(--text-1);}
#hb-panel .hb-num{display:flex;align-items:center;gap:8px;}
#hb-panel .hb-num .hb-input{width:88px;font-variant-numeric:tabular-nums;}
#hb-panel select.hb-input{margin-top:6px;padding-right:6px;cursor:pointer;}
#hb-panel .hb-num span{font-size:var(--fs-status);line-height:var(--lh-status);color:var(--text-2);}
#hb-panel textarea.hb-input{height:auto;min-height:72px;padding:8px 10px;resize:vertical;
  font-family:ui-monospace,"SF Mono",Consolas,monospace;font-size:12px;line-height:18px;}
#hb-panel textarea.hb-prompt{min-height:240px;}
#hb-panel textarea.hb-plain{min-height:160px;}
#hb-panel textarea.hb-debug{min-height:120px;}
#hb-panel .hb-seg{display:flex;gap:2px;padding:3px;border-radius:var(--radius-sm);background:var(--card-2);}
#hb-panel .hb-seg button{flex:1;height:28px;padding:0 6px;border:0;border-radius:8px;background:transparent;color:var(--text-2);
  font-family:inherit;font-size:var(--fs-body);line-height:28px;cursor:pointer;
  transition:background-color var(--dur-hover) ease-out,color var(--dur-hover) ease-out;}
#hb-panel .hb-seg button[aria-pressed="true"]{background:var(--card-1);color:var(--accent);font-weight:600;
  box-shadow:0 1px 2px rgba(38,24,82,.12);}
#hb-panel .hb-check{display:flex;align-items:flex-start;gap:8px;margin:0;cursor:pointer;}
#hb-panel .hb-check input[type="checkbox"]{-webkit-appearance:auto;-moz-appearance:auto;appearance:auto;
  flex:none;width:16px;height:16px;margin:2px 0 0;padding:0;border:0;border-radius:0;background:none;box-shadow:none;
  filter:none;transform:none;outline:none;overflow:visible;display:inline-block;accent-color:var(--accent);cursor:pointer;}
#hb-panel .hb-check input[type="checkbox"]::before{content:none;}
#hb-panel .hb-check input[type="checkbox"]:focus-visible{outline:2px solid var(--accent);outline-offset:2px;}
#hb-panel .hb-check b{display:block;font-weight:400;font-size:var(--fs-body);line-height:var(--lh-body);color:var(--text-1);}
#hb-panel .hb-check small{display:block;font-size:var(--fs-note);line-height:var(--lh-note);color:var(--text-2);}
#hb-panel .hb-actions{display:flex;flex-direction:column;align-items:flex-start;gap:8px;}
#hb-panel .hb-btn{height:32px;padding:0 14px;display:inline-flex;align-items:center;gap:6px;border:0;border-radius:var(--radius-sm);
  background:var(--accent-fill);color:var(--on-accent);font-family:inherit;font-size:var(--fs-body);line-height:var(--lh-body);
  font-weight:600;cursor:pointer;transition:filter var(--dur-hover) ease-out,background-color var(--dur-hover) ease-out;}
#hb-panel .hb-btn:hover:not(:disabled){filter:brightness(.92);}
#hb-panel .hb-btn:disabled{opacity:.5;cursor:default;}
#hb-panel .hb-btn.danger{background:transparent;border:1px solid color-mix(in srgb,var(--danger) 35%,transparent);color:var(--danger);}
#hb-panel .hb-btn.danger:hover{filter:none;background:color-mix(in srgb,var(--danger) 6%,transparent);}
#hb-panel .hb-result{display:flex;align-items:flex-start;gap:6px;padding:7px 10px;border-radius:var(--radius-sm);
  font-size:var(--fs-status);line-height:var(--lh-status);}
#hb-panel .hb-result svg{margin-top:2px;}
#hb-panel .hb-result.busy{background:var(--card-2);color:var(--text-2);}
#hb-panel .hb-result.busy svg{color:var(--accent);}
#hb-panel .hb-result.ok{background:color-mix(in srgb,var(--ok) 6%,transparent);color:var(--ok);}
#hb-panel .hb-result.bad{background:color-mix(in srgb,var(--danger) 6%,transparent);color:var(--danger);}
#hb-panel .hb-result.warn{background:color-mix(in srgb,var(--warn) 6%,transparent);color:var(--warn);}
#hb-panel .hb-spin{animation:hb-spin var(--dur-spin) linear infinite;}
#hb-panel .hb-adv{display:flex;flex-direction:column;gap:10px;margin-top:10px;}

/* 窄屏：面板改成贴底的抽屉，不拖 */
@media (max-width:600px){
  #hb-panel{left:8px !important;right:8px !important;bottom:auto !important;
    top:calc(100vh - 8px) !important;top:calc(100dvh - 8px) !important;transform:translateY(-100%) !important;
    width:auto;max-height:72vh !important;max-height:72dvh !important;}
  #hb-panel .hb-hd{cursor:default;}
  /* 手机上抽屉底下就是聊天字，毛玻璃又常被关掉（或者很耗电）：直接用实色，字不透出来 */
  body #hb-panel .hb-shell,body.no-blur #hb-panel .hb-shell{background:var(--panel-solid);-webkit-backdrop-filter:none;backdrop-filter:none;}
}
/* 触屏：输入框字号不到 16px 时，iPhone 一点输入框就把整页放大；按钮做大一点好点中 */
@media (pointer:coarse){
  #hb-panel .hb-input{font-size:16px;}
  #hb-panel textarea.hb-input{font-size:14px;}
  #hb-panel .hb-ibtn{width:40px;height:40px;}
  #hb-panel .hb-rerun{height:34px;}
  #hb-panel .hb-seg button{height:34px;}
  #hb-panel .hb-btn{min-height:40px;}
  #hb-panel .hb-check input[type="checkbox"]{width:20px;height:20px;}
}

/* 系统要求减少动态效果：转圈停成一段静止的四分之一弧，闪烁改常亮，过渡时长归零 */
@media (prefers-reduced-motion:reduce){
  #hb-fab .hb-ring,#hb-panel .hb-spin{animation:none;}
  #hb-panel .hb-status.busy .hb-sdot{animation:none;opacity:1;}
  #hb-fab,#hb-fab *,#hb-panel,#hb-panel *{transition-duration:0s !important;}
}
/* ================= BanG 皮肤「票根」（DESIGN.md 末节，2026-10-09 常夜灯批） =================
   外观选 BanG，或者跟随酒馆而当前卡挂了 __BANG_FACE__ 时，悬浮球和面板挂 data-skin="bang"。
   强调色由面板写进 --bang-accent（读主卡的推し色，读不到用默认蓝）；每个人的颜色写在票根、人头的 --pc 上 */
#hb-fab .hb-pick,#hb-panel .hb-title-en,#hb-panel .hb-heads{display:none;}
#hb-fab[data-skin="bang"],#hb-panel[data-skin="bang"]{
  --accent: var(--bang-accent, #3f7fd0);
  --accent-fill: var(--accent);
  --on-accent: #FFFFFF;
  --accent-deep: color-mix(in srgb, var(--accent) 72%, #1b2030);
  --accent-soft: color-mix(in srgb, var(--accent) 16%, #ffffff);
  --stage: #1f2433; --stage-2: #2a3044; --stage-t: #eef1f8; --stage-t2: #aeb6cc; --stage-t3: #7f88a3;
  --bg: #f4f6fb; --bg-solid: #f4f6fb; --panel-solid: #f4f6fb;
  --text-1: #23283a; --text-2: #525a70; --text-3: #8a92a8;
  --border: #e1e5ef; --border-dash: #d3d9e6;
  --card-1: #FFFFFF; --card-2: #eef1f8; --field: #FFFFFF;
  --ok: #3fae8c; --warn: #b8692c; --danger: #d0455c;
  --radius-lg: 18px; --radius-sm: 9px;
  --shadow: 0 18px 40px rgba(20, 30, 60, .35);
  --blur: none;
  --font-d: 'Fredoka', 'Arial Rounded MT Bold', 'Segoe UI', sans-serif;
  --ease-out: cubic-bezier(.22, 1, .36, 1);
  --ease-pop: cubic-bezier(.34, 1.56, .64, 1);
  font-family: 'Noto Sans SC', 'PingFang SC', 'Microsoft YaHei', sans-serif;
}
/* 入口：拨片 */
#hb-fab[data-skin="bang"]{background:transparent;border:0;border-radius:0;box-shadow:none;height:calc(var(--fab) * 1.08);}
#hb-fab[data-skin="bang"]:hover,#hb-fab[data-skin="bang"]:active{box-shadow:none;}
#hb-fab[data-skin="bang"] .hb-av,#hb-fab[data-skin="bang"] .hb-ring{display:none !important;}
#hb-fab[data-skin="bang"] .hb-pick{display:grid;place-items:center;position:absolute;inset:0;color:#fff;pointer-events:none;
  background:linear-gradient(160deg, color-mix(in srgb, var(--accent) 70%, #fff), var(--accent));
  border-radius:50% 50% 50% 50% / 38% 38% 62% 62%;box-shadow:0 6px 16px rgba(0,0,0,.4);
  font-family:var(--font-d);transition:transform .24s var(--ease-pop);}
#hb-fab[data-skin="bang"] .hb-pick b{font-weight:700;font-size:calc(var(--fab) * .29);letter-spacing:.04em;line-height:1;margin-top:-8%;}
#hb-fab[data-skin="bang"] .hb-pick small{position:absolute;bottom:16%;font-size:calc(var(--fab) * .14);letter-spacing:.2em;font-weight:700;opacity:.85;}
#hb-fab[data-skin="bang"]:hover .hb-pick{transform:translateY(-2px) rotate(-6deg);}
#hb-fab[data-skin="bang"]:active .hb-pick{transform:scale(.94);}
#hb-fab[data-skin="bang"].hb-busy .hb-pick{animation:hb-spin 1.1s linear infinite;}
#hb-fab[data-skin="bang"] .hb-dot{right:-3px;top:0;bottom:auto;}
#hb-fab[data-skin="bang"].hb-fresh .hb-dot{animation:hb-pop .38s var(--ease-pop) both;}
@keyframes hb-pop{from{transform:scale(0)}to{transform:scale(1)}}

/* 面板外壳：不要立绘、场记板斜纹和小头像；进场 .46s */
#hb-panel[data-skin="bang"] .hb-perch,#hb-panel[data-skin="bang"] .hb-slate,#hb-panel[data-skin="bang"] .hb-hd-av{display:none !important;}
#hb-panel[data-skin="bang"] .hb-shell{border:0;background:var(--bg);-webkit-backdrop-filter:none;backdrop-filter:none;}
#hb-panel[data-skin="bang"].hb-open .hb-shell{animation:hb-sheet .46s var(--ease-out) both;}
@keyframes hb-sheet{from{opacity:0;transform:scale(1.045)}to{opacity:1;transform:none}}
/* 顶栏：深色舞台 */
#hb-panel[data-skin="bang"] .hb-hd{background:var(--stage);color:#fff;border-bottom:0;padding:12px 12px 8px;}
#hb-panel[data-skin="bang"] .hb-title{display:flex;flex-direction:column;line-height:1.25;font-size:10px;letter-spacing:.2em;font-weight:700;color:var(--stage-t3);}
#hb-panel[data-skin="bang"] .hb-title-en{display:block;font-family:var(--font-d);font-size:15px;letter-spacing:.06em;color:#fff;font-weight:700;}
#hb-panel[data-skin="bang"] .hb-rerun,#hb-panel[data-skin="bang"] .hb-ibtn{background:rgba(255,255,255,.1);color:#dfe4f2;border:0;border-radius:9px;box-shadow:none;}
#hb-panel[data-skin="bang"] .hb-rerun:hover:not(:disabled),#hb-panel[data-skin="bang"] .hb-ibtn:hover{background:rgba(255,255,255,.18);color:#fff;}
#hb-panel[data-skin="bang"] .hb-ibtn[aria-pressed="true"]{background:#fff;color:var(--accent-deep);}
/* 人头胶囊一排 */
#hb-panel[data-skin] .hb-heads{display:flex;align-items:center;gap:6px;background:var(--heads-bg, var(--stage));padding:var(--heads-pad, 0 12px 10px);flex:none;}
#hb-panel[data-skin] .hb-heads[hidden]{display:none;}
/* 人头在左边那段里横着滚，「加上」固定在右边；左右还有人时那一边 24px 淡出 */
#hb-panel .hb-heads-list{flex:1 1 auto;min-width:0;display:flex;gap:6px;overflow-x:auto;scrollbar-width:none;overscroll-behavior-x:contain;}
#hb-panel .hb-heads-list::-webkit-scrollbar{display:none;}
#hb-panel .hb-heads-list.fade-r{-webkit-mask-image:linear-gradient(to right,#000 calc(100% - 24px),transparent);mask-image:linear-gradient(to right,#000 calc(100% - 24px),transparent);}
#hb-panel .hb-heads-list.fade-l{-webkit-mask-image:linear-gradient(to left,#000 calc(100% - 24px),transparent);mask-image:linear-gradient(to left,#000 calc(100% - 24px),transparent);}
#hb-panel .hb-heads-list.fade-l.fade-r{-webkit-mask-image:linear-gradient(to right,transparent,#000 24px,#000 calc(100% - 24px),transparent);mask-image:linear-gradient(to right,transparent,#000 24px,#000 calc(100% - 24px),transparent);}
#hb-panel .hb-head{flex:none;display:inline-flex;align-items:center;gap:5px;height:26px;padding:0 10px 0 4px;border-radius:var(--r-chip, 999px);border:var(--chip-border, 0);
  background:var(--chip-bg, var(--stage-2));color:var(--chip-fg, var(--stage-t));font:inherit;font-size:12px;font-weight:700;cursor:pointer;
  transition:transform .24s var(--ease-pop, cubic-bezier(.34,1.56,.64,1)),background .2s;}
#hb-panel .hb-head:hover{background:var(--chip-hover, #353c55);}
#hb-panel .hb-head:active{transform:scale(.95);}
#hb-panel .hb-head.away{background:transparent;border:1.5px dashed var(--away-line, #4b5370);color:var(--chip-fg2, var(--stage-t2));}
#hb-panel .hb-head.plus{padding:0 10px 0 8px;border:0;background:var(--accent);color:var(--on-accent, #fff);}
#hb-panel .hb-face{position:relative;flex:none;width:18px;height:18px;border-radius:var(--r-dot, 50%);overflow:hidden;display:grid;place-items:center;
  background:var(--pc);color:#fff;font-style:normal;font-size:10px;font-weight:900;}
#hb-panel .hb-face img{position:absolute;inset:0;width:100%;height:100%;max-width:none;object-fit:cover;}
/* 状态条：记状态中强调色浅底，一道光扫过 */
#hb-panel[data-skin="bang"] .hb-status{border-radius:10px;}
#hb-panel[data-skin="bang"] .hb-status.busy{position:relative;overflow:hidden;background:var(--accent-soft);color:var(--accent-deep);}
#hb-panel[data-skin="bang"] .hb-status.busy::after{content:'';position:absolute;inset:0;pointer-events:none;
  background:linear-gradient(100deg,transparent 30%,rgba(255,255,255,.65) 50%,transparent 70%);
  transform:translateX(-100%);animation:hb-shine 1.4s var(--ease-out) infinite;}
@keyframes hb-shine{to{transform:translateX(100%)}}
/* 场面块：深色舞台 */
#hb-panel[data-skin="bang"] .hb-scene{position:relative;background:var(--stage);color:var(--stage-t);border:0;border-radius:12px;}
#hb-panel[data-skin="bang"] .hb-scene .hb-place{font-family:var(--font-d);letter-spacing:.03em;color:#fff;padding-right:64px;}
#hb-panel[data-skin="bang"] .hb-scene .hb-kv b{color:var(--stage-t3);}
#hb-panel[data-skin="bang"] .hb-scene .hb-kv span,#hb-panel[data-skin="bang"] .hb-scene .hb-pair{color:var(--stage-t2);}
#hb-panel[data-skin="bang"] .hb-scene .hb-pair em{color:var(--stage-t);}
#hb-panel[data-skin="bang"] .hb-scene .hb-fold-btn,#hb-panel[data-skin="bang"] .hb-scene .hb-sfold-sum,#hb-panel[data-skin="bang"] .hb-scene .hb-note{color:var(--stage-t2);}
#hb-panel[data-skin="bang"] .hb-scene .hb-pill{background:var(--stage-2);color:var(--stage-t2);border-color:#4b5370;}
#hb-panel .hb-set-no{position:absolute;right:12px;top:10px;font-family:var(--font-d);font-size:10px;letter-spacing:.2em;font-weight:700;color:var(--scene-sub, var(--stage-t3));}
/* 票根 */
#hb-panel .hb-tk{position:relative;display:flex;background:var(--card-1);border:var(--c-border, 0);border-radius:var(--r-card, 12px);box-shadow:var(--c-shadow, 0 2px 8px rgba(30,40,70,.08));overflow:hidden;transition:box-shadow .2s;}
#hb-panel .hb-tk:hover{box-shadow:var(--c-shadow-h, 0 6px 16px rgba(30,40,70,.12));}
#hb-panel .hb-tk.off{opacity:.5;}
#hb-panel .hb-tk-band{flex:none;width:var(--band-w, 6px);background:var(--pc);}
#hb-panel .hb-tk-main{flex:1;min-width:0;padding:10px 10px 10px 12px;cursor:pointer;outline:none;}
#hb-panel .hb-tk-main:focus-visible{box-shadow:inset 0 0 0 2px var(--accent);border-radius:8px;}
#hb-panel .hb-tk .hb-name{display:flex;align-items:center;gap:6px;flex-wrap:wrap;}
#hb-panel .hb-tk .hb-name>span:first-child{font-size:14.5px;font-weight:900;}
#hb-panel .hb-tk .hb-name>svg{margin-left:auto;color:var(--text-3);transform:rotate(90deg);transition:transform .32s var(--ease-out);}
#hb-panel .hb-tk.open .hb-name>svg{transform:rotate(270deg);}
#hb-panel .hb-tk .hb-rows{margin-top:6px;}
#hb-panel .hb-tk-more{display:grid;grid-template-rows:0fr;opacity:0;transition:grid-template-rows .32s var(--ease-out),opacity .32s var(--ease-out);}
#hb-panel .hb-tk-more>div{overflow:hidden;min-height:0;}
#hb-panel .hb-tk.open .hb-tk-more{grid-template-rows:1fr;opacity:1;}
#hb-panel .hb-tk .hb-row.unsaid{background:var(--unsaid-bg, color-mix(in srgb, var(--pc) 12%, #fff));}
#hb-panel .hb-tk .hb-row.unsaid b,#hb-panel .hb-tk .hb-row.unsaid span{color:var(--unsaid-fg, color-mix(in srgb, var(--pc) 80%, #222));}
#hb-panel .hb-tk-stub{position:relative;flex:none;width:58px;border-left:var(--stub-line, 2px dashed var(--border));display:flex;flex-direction:column;align-items:center;justify-content:center;gap:6px;padding:8px 0;}
#hb-panel .hb-tk-stub::before,#hb-panel .hb-tk-stub::after{content:'';position:absolute;left:-7px;width:12px;height:12px;border-radius:50%;background:var(--bg);}
#hb-panel .hb-tk-stub::before{top:-6px;}
#hb-panel .hb-tk-stub::after{bottom:-6px;}
#hb-panel .hb-stamp{display:flex;flex-direction:column;align-items:center;line-height:1;font-family:var(--font-d);}
#hb-panel .hb-stamp b{font-size:20px;font-weight:700;color:var(--stub-num, color-mix(in srgb, var(--pc) 70%, #1b2030));}
#hb-panel .hb-stamp i{margin-top:3px;font-style:normal;font-size:8px;letter-spacing:.16em;font-weight:700;color:var(--text-3);}
#hb-panel .hb-tk-btn{width:30px;height:30px;padding:0;border:0;border-radius:var(--radius-sm);background:var(--sb-bg, var(--card-2));color:var(--sb-fg, var(--accent-deep));display:grid;place-items:center;cursor:pointer;
  transition:transform .24s var(--ease-pop);}
#hb-panel .hb-tk-btn:hover{transform:scale(1.08);}
#hb-panel .hb-tk-btn.del{color:var(--danger);}
#hb-panel .hb-tk-btn[disabled]{opacity:.5;cursor:default;transform:none;}
/* 单独重算在路上：箭头匀速转，按钮不变淡，换强调色 */
#hb-panel .hb-tk-btn.busy[disabled]{opacity:1;cursor:progress;color:var(--accent);}
#hb-panel .hb-tk-btn.busy svg{animation:hb-spin 1s linear infinite;}
#hb-panel .hb-tk-mini,#hb-panel .hb-cut{display:none;}
/* 换了一份状态：票根逐张发出来，楼层号盖章 */
#hb-panel .hb-deal .hb-tk{animation:hb-deal .28s var(--ease-out) both;}
#hb-panel .hb-deal .hb-tk+.hb-tk{animation-delay:60ms;}
#hb-panel .hb-deal .hb-tk+.hb-tk+.hb-tk{animation-delay:120ms;}
#hb-panel .hb-deal .hb-tk+.hb-tk+.hb-tk+.hb-tk{animation-delay:180ms;}
#hb-panel .hb-deal .hb-stamp{animation:hb-stamp .38s var(--ease-out) .28s both;}
@keyframes hb-deal{from{opacity:0;transform:translateY(9px) scale(.97)}to{opacity:1;transform:none}}
@keyframes hb-stamp{0%{opacity:0;transform:translateY(-26px) scale(.8)}65%{opacity:1;transform:translateY(0) scale(1.06)}100%{transform:none}}
/* 设置：白底分组卡、四个页签 */
#hb-panel[data-skin="bang"] .hb-grp{background:var(--card-1);border:0;border-radius:12px;box-shadow:0 2px 8px rgba(30,40,70,.06);padding:12px;}
#hb-panel .hb-tabs{display:flex;gap:4px;padding:3px;border-radius:var(--radius-sm);background:var(--seg-bg, #e6eaf3);}
#hb-panel .hb-tabs button{flex:1;height:30px;border:0;border-radius:calc(var(--radius-sm) - 2px);background:transparent;color:var(--text-3);font:inherit;font-size:12.5px;font-weight:700;cursor:pointer;transition:background .2s,color .2s;}
#hb-panel .hb-tabs button[aria-selected="true"]{background:var(--seg-on, #fff);color:var(--accent-ink, var(--accent-deep));box-shadow:0 1px 3px rgba(60,40,90,.12);}
#hb-panel .hb-set{display:flex;flex-direction:column;gap:10px;}
#hb-panel .hb-tabpane{display:flex;flex-direction:column;gap:10px;animation:hb-tab .35s var(--ease-out, cubic-bezier(.22,1,.36,1)) both;}
@keyframes hb-tab{from{opacity:0;transform:translateX(24px)}to{opacity:1;transform:none}}
#hb-panel[data-skin="bang"] .hb-seg{background:#e6eaf3;border-radius:9px;}
#hb-panel[data-skin="bang"] .hb-seg button[aria-pressed="true"]{background:#fff;color:var(--accent-deep);}
#hb-panel[data-skin="bang"] .hb-btn:not(.danger){background:var(--accent);color:#fff;border-radius:9px;}
#hb-panel[data-skin="bang"] .hb-input{border-color:#dde2ee;border-radius:9px;}
/* 窄屏：票根右边那一截收起，往左滑出来 */
@media (max-width:600px){
  /* 左右划交给页面（露出右边那截），上下划、双指缩放照旧归浏览器；不认 pinch-zoom 的浏览器用前一句 */
  #hb-panel[data-skin] .hb-tk{touch-action:pan-y;touch-action:pan-y pinch-zoom;}
  /* 收着的那截连按钮一起藏起来（visibility），键盘 Tab 不会跳进看不见的按钮；收回时等宽度动画走完再藏 */
  #hb-panel[data-skin] .hb-tk-stub{width:0;border-left-width:0;overflow:hidden;padding:0;visibility:hidden;
    transition:width .3s var(--ease-out, cubic-bezier(.22,1,.36,1)),visibility 0s linear .3s;}
  #hb-panel[data-skin] .hb-tk-stub .hb-stamp{display:none;}
  #hb-panel[data-skin] .hb-tk.swiped .hb-tk-stub{width:58px;border-left-width:var(--stub-bw, 2px);padding:8px 0;visibility:visible;
    transition:width .3s var(--ease-out, cubic-bezier(.22,1,.36,1)),visibility 0s;}
  /* 「#楼层」是按钮：点了露出、收回右边那截，露出时跟着平移到那截左边；四周透明内边距撑出点击区 */
  #hb-panel[data-skin] .hb-tk-mini{display:block;position:absolute;right:4px;top:3px;min-height:28px;padding:4px 6px;margin:0;border:0;border-radius:6px;background:transparent;cursor:pointer;
    font-family:var(--font-d);font-size:11px;font-weight:700;line-height:20px;color:var(--stub-num, color-mix(in srgb, var(--pc) 70%, #1b2030));
    transition:right .3s var(--ease-out, cubic-bezier(.22,1,.36,1));}
  #hb-panel[data-skin] .hb-tk.swiped .hb-tk-mini{right:60px;}
  #hb-panel[data-skin="film"] .hb-cut{cursor:pointer;}
  #hb-panel[data-skin="film"] .hb-cut::after{content:'';position:absolute;inset:-6px -6px -8px -4px;}
  #hb-panel[data-skin] .hb-tk .hb-name>svg{margin-right:30px;}
  #hb-panel[data-skin="film"] .hb-tk .hb-name>svg{margin-right:0;}
}
/* ================= 原版三套风格（DESIGN.md「原版改版：三套风格」，2026-10-10 常夜灯定） =================
   BanG 卡以外，按外观里的「风格」挂 data-skin="slate" / "lamp" / "film"。人头一排、卡片、右边那截、页签和票根共用上面那套结构，
   这里只给颜色和质感变量，再补各自的几处样子 */
#hb-fab[data-skin="slate"],#hb-panel[data-skin="slate"]{
  --accent-deep: #5a3fc0;
  --font-d: ui-monospace, "SF Mono", Consolas, monospace;
  --heads-bg: transparent; --heads-pad: 10px 12px 0;
  --chip-bg: var(--card-1); --chip-fg: var(--text-1); --chip-fg2: var(--text-3); --chip-hover: var(--card-2);
  --chip-border: 1px solid var(--border); --away-line: rgba(92, 72, 160, .35); --r-chip: 8px;
  --r-card: 12px; --c-border: 1px solid var(--border); --c-shadow: 0 1px 3px rgba(38, 24, 82, .08); --c-shadow-h: 0 4px 12px rgba(38, 24, 82, .12);
  --band-w: 5px; --stub-line: 2px dashed var(--border-dash); --stub-num: var(--text-1);
  --sb-bg: var(--card-2); --sb-fg: var(--accent-deep);
  --seg-bg: var(--card-2); --seg-on: var(--card-1); --accent-ink: var(--accent-deep);
  --unsaid-bg: color-mix(in srgb, var(--accent) 10%, transparent); --unsaid-fg: var(--accent-deep);
  --scene-sub: var(--text-3);
}
#hb-fab[data-skin="slate"][data-theme="dark"],#hb-panel[data-skin="slate"][data-theme="dark"]{
  --accent-deep: #C4B5FF; --away-line: rgba(160, 140, 255, .35);
  --c-shadow: 0 1px 3px rgba(0, 0, 0, .25); --c-shadow-h: 0 4px 12px rgba(0, 0, 0, .35);
}

/* 夜灯：深蓝夜色、灯光黄；浅色主题换米白（场面块留一块夜色） */
#hb-fab[data-skin="lamp"],#hb-panel[data-skin="lamp"]{
  --bg: #171a2b; --bg-solid: #171a2b; --panel-solid: #171a2b; --hd-bg: #1c2034;
  --text-1: #eceaf6; --text-2: #c9cbe0; --text-3: #9aa0c0;
  --border: #2c3150; --border-dash: #3e4466;
  --accent: #f2b25c; --accent-fill: #f2b25c; --on-accent: #2a1e0a; --accent-deep: #f2b25c; --accent-2: #f6c785;
  --card-1: #1f2338; --card-2: #262b44; --field: #14172a; --avatar-bg: #262b44;
  --ok: #5fd09a; --warn: #f0a060; --danger: #ff7a8c;
  --shadow: 0 20px 50px rgba(0, 0, 0, .55), 0 0 0 1px rgba(242, 178, 92, .12);
  --blur: none; --radius-lg: 20px; --radius-sm: 10px;
  --font-d: ui-monospace, "SF Mono", Consolas, monospace;
  --heads-bg: #1c2034; --heads-pad: 0 12px 10px;
  --chip-bg: #262b44; --chip-fg: #eceaf6; --chip-fg2: #9aa0c0; --chip-hover: #2f3554; --away-line: #3e4466; --r-chip: 999px;
  --r-card: 14px; --c-border: 1px solid #2c3150; --c-shadow: 0 2px 10px rgba(0, 0, 0, .25); --c-shadow-h: 0 4px 16px rgba(0, 0, 0, .35);
  --band-w: 5px; --stub-line: 2px dashed #2f3454; --stub-num: #f2b25c;
  --sb-bg: #2a2f4c; --sb-fg: #f2b25c;
  --seg-bg: #262b44; --seg-on: #f2b25c; --accent-ink: #2a1e0a;
  --unsaid-bg: rgba(242, 178, 92, .13); --unsaid-fg: #f6c785;
  --scene-sub: #9aa0c0;
  color-scheme: dark;
}
#hb-fab[data-skin="lamp"][data-theme="light"],#hb-panel[data-skin="lamp"][data-theme="light"]{
  --bg: #fbf7ef; --bg-solid: #fbf7ef; --panel-solid: #fbf7ef; --hd-bg: #f4ecdc;
  --text-1: #2c2416; --text-2: #5c4e36; --text-3: #8f7f62;
  --border: #eadfc8; --border-dash: #d8c8a6;
  --accent-deep: #94600f; --accent-2: #94600f;
  --card-1: #FFFFFF; --card-2: #f4ecdc; --field: #FFFFFF; --avatar-bg: #f4ecdc;
  --ok: #2d7a4b; --warn: #b8550f; --danger: #c9364b;
  --shadow: 0 18px 40px rgba(60, 40, 10, .25);
  --heads-bg: #f4ecdc;
  --chip-bg: #FFFFFF; --chip-fg: #2c2416; --chip-fg2: #8f7f62; --chip-hover: #fbf3e4; --away-line: #d8c8a6;
  --c-border: 1px solid #eadfc8; --c-shadow: 0 2px 8px rgba(80, 60, 20, .08); --c-shadow-h: 0 4px 14px rgba(80, 60, 20, .14);
  --stub-line: 2px dashed #eadfc8; --stub-num: #b27a1e;
  --sb-bg: #f4ecdc; --sb-fg: #94600f; --seg-bg: #f0e6d2;
  --unsaid-bg: #fdf0d9; --unsaid-fg: #94600f;
  color-scheme: light;
}
#hb-fab[data-skin="lamp"]{border-color:#f2b25c;box-shadow:0 0 0 3px rgba(242,178,92,.35),0 0 22px rgba(242,178,92,.45),0 8px 20px rgba(0,0,0,.5);}
#hb-fab[data-skin="lamp"]:hover{box-shadow:0 0 0 3px rgba(242,178,92,.45),0 0 28px rgba(242,178,92,.55),0 10px 24px rgba(0,0,0,.5);}
#hb-panel[data-skin="lamp"] .hb-shell,#hb-panel[data-skin="film"] .hb-shell{background:var(--bg);-webkit-backdrop-filter:none;backdrop-filter:none;}
#hb-panel[data-skin="lamp"] .hb-slate,#hb-panel[data-skin="film"] .hb-slate{display:none;}
#hb-panel[data-skin="lamp"] .hb-hd{background:var(--hd-bg);border-bottom:0;}
#hb-panel[data-skin="lamp"] .hb-hd-av{border-color:#f2b25c;}
#hb-panel[data-skin="lamp"] .hb-rerun{border:0;background:color-mix(in srgb, var(--text-1) 8%, transparent);color:var(--text-2);}
#hb-panel[data-skin="lamp"] .hb-scene{--text-1:#f4efe6;--text-2:#c9cbe0;--text-3:#9aa0c0;--card-2:#323858;--card-1:#2a2f4c;--border-dash:#3e4466;
  position:relative;background:linear-gradient(160deg,#232846,#1d2138);border:1px solid rgba(242,178,92,.18);border-radius:14px;}
#hb-panel[data-skin="lamp"][data-theme="light"] .hb-scene{background:#2a2f4a;}
#hb-panel[data-skin="lamp"] .hb-scene .hb-place{color:#ffd9a0;padding-right:64px;}
#hb-panel[data-skin="lamp"] .hb-tk.open{box-shadow:0 0 0 1px rgba(242,178,92,.35),0 0 24px rgba(242,178,92,.12);}
#hb-panel[data-skin="lamp"] .hb-head.plus{box-shadow:0 0 12px rgba(242,178,92,.45);}
#hb-panel[data-skin="lamp"] .hb-seg button[aria-pressed="true"],#hb-panel[data-skin="film"] .hb-seg button[aria-pressed="true"]{background:var(--seg-on);color:var(--accent-ink);}
#hb-panel[data-skin="lamp"] .hb-seg,#hb-panel[data-skin="film"] .hb-seg{background:var(--seg-bg);}

/* 分镜本：白纸黑框、直角，人头一排是胶片条，左上角「CUT 楼层」，名字后面一小条人物色 */
#hb-fab[data-skin="film"],#hb-panel[data-skin="film"]{
  --bg: #FFFFFF; --bg-solid: #FFFFFF; --panel-solid: #FFFFFF;
  --text-1: #1f1d24; --text-2: #4a4752; --text-3: #7c7884;
  --border: #d6d3da; --border-dash: #c9c6cf;
  --accent: #e2574c; --accent-fill: #e2574c; --on-accent: #FFFFFF; --accent-deep: #b8352b; --accent-2: #b8352b;
  --card-1: #FFFFFF; --card-2: #f4f3f1; --field: #FFFFFF; --avatar-bg: #f4f3f1;
  --ok: #2f8a57; --warn: #B8550F; --danger: #e2574c;
  --shadow: 0 14px 34px rgba(0, 0, 0, .35);
  --blur: none; --radius-lg: 6px; --radius-sm: 4px;
  --font-d: ui-monospace, "SF Mono", Consolas, monospace;
  --heads-bg: #1f1d24; --heads-pad: 8px 10px;
  --chip-bg: #FFFFFF; --chip-fg: #1f1d24; --chip-fg2: #c9c6cf; --chip-hover: #f0efed; --away-line: #77737f; --r-chip: 3px; --r-dot: 3px;
  --r-card: 4px; --c-border: 1.5px solid #1f1d24; --c-shadow: none; --c-shadow-h: 3px 3px 0 #1f1d24;
  --band-w: 0px; --stub-line: 1.5px solid #1f1d24; --stub-bw: 1.5px;
  --sb-bg: #f4f3f1; --sb-fg: #1f1d24;
  --seg-bg: #f0efed; --seg-on: #1f1d24; --accent-ink: #FFFFFF;
  --unsaid-bg: #fdeceb; --unsaid-fg: #b8352b;
  --scene-sub: #7c7884;
  color-scheme: light;
}
#hb-fab[data-skin="film"]{border-color:#1f1d24;box-shadow:4px 4px 0 #e2574c;}
#hb-fab[data-skin="film"]:hover{box-shadow:5px 5px 0 #e2574c;}
#hb-fab[data-skin="film"]:active{box-shadow:2px 2px 0 #e2574c;}
#hb-panel[data-skin="film"] .hb-shell{border:1.5px solid #1f1d24;}
#hb-panel[data-skin="film"] .hb-hd{border-bottom:1.5px solid #1f1d24;}
#hb-panel[data-skin="film"] .hb-hd-av{border-color:#1f1d24;}
#hb-panel[data-skin="film"] .hb-title,#hb-panel[data-skin="film"] .hb-place,#hb-panel[data-skin="film"] .hb-tk .hb-name>span:first-child,
#hb-panel[data-skin="film"] .hb-grp h4{font-family:Georgia, "Songti SC", "SimSun", serif;}
#hb-panel[data-skin="film"] .hb-rerun{border:1.5px solid #1f1d24;color:#1f1d24;}
#hb-panel[data-skin="film"] .hb-heads{position:relative;}
#hb-panel[data-skin="film"] .hb-heads::before,#hb-panel[data-skin="film"] .hb-heads::after{content:'';position:absolute;left:0;right:0;height:4px;pointer-events:none;
  background:repeating-linear-gradient(90deg,transparent 0 6px,#fff 6px 11px,transparent 11px 14px);opacity:.55;}
#hb-panel[data-skin="film"] .hb-heads::before{top:1px;}
#hb-panel[data-skin="film"] .hb-heads::after{bottom:1px;}
#hb-panel[data-skin="film"] .hb-head.away{background:transparent;}
#hb-panel[data-skin="film"] .hb-scene{position:relative;background:var(--card-2);border:1.5px solid #1f1d24;border-radius:4px;}
#hb-panel[data-skin="film"] .hb-scene .hb-place{padding-right:64px;}
#hb-panel[data-skin="film"] .hb-tk-main{padding-top:22px;}
#hb-panel[data-skin="film"] .hb-cut{display:block;position:absolute;left:0;top:0;margin:0;padding:1px 8px;border:0;border-radius:0;background:#1f1d24;color:#fff;cursor:default;
  font-family:var(--font-d);font-size:9.5px;font-weight:800;letter-spacing:.12em;line-height:16px;}
#hb-panel[data-skin="film"] .hb-tk .hb-name>span:first-child::after{content:'';display:inline-block;width:22px;height:4px;margin-left:8px;border-radius:2px;background:var(--pc);vertical-align:middle;}
#hb-panel[data-skin="film"] .hb-tabs button[aria-selected="true"]{box-shadow:none;}
/* 场面块右上角「SC / FLOOR / CUT 楼层」 */
#hb-panel[data-skin] .hb-scene{position:relative;}
#hb-panel[data-skin] .hb-scene .hb-place{padding-right:64px;}
/* 设置里每一组一张卡片 */
#hb-panel[data-skin] .hb-grp{background:var(--card-1);border:var(--c-border, 0);border-radius:var(--r-card, 12px);box-shadow:var(--c-shadow, 0 2px 8px rgba(30,40,70,.06));padding:12px;}
/* 票根的打孔只在 BanG 皮肤上 */
#hb-panel:not([data-skin="bang"]) .hb-tk-stub::before,#hb-panel:not([data-skin="bang"]) .hb-tk-stub::after{display:none;}
@media (prefers-reduced-motion:reduce){
  #hb-panel .hb-tk-btn.busy svg{animation:none;}
  #hb-fab[data-skin="bang"] .hb-pick,#hb-panel[data-skin="bang"] .hb-shell,#hb-panel .hb-tk,#hb-panel .hb-stamp,#hb-panel .hb-tabpane,
  #hb-panel[data-skin="bang"] .hb-status.busy::after{animation-duration:.01s !important;animation-iteration-count:1 !important;}
}

`;

  function injectCss() {
    const doc = TOP.document;
    if (doc.getElementById(STYLE_ID)) return;
    const el = doc.createElement('style');
    el.id = STYLE_ID;
    el.textContent = CSS;
    doc.head.appendChild(el);
  }

  function removeCss() {
    try { const el = TOP.document.getElementById(STYLE_ID); if (el) el.remove(); } catch (e) { /* ignore */ }
  }

  // ---------- 线性图标 ----------
