    spinner: '<circle cx="12" cy="12" r="9" opacity=".25"/><path d="M21 12a9 9 0 0 0-9-9"/>',
    plus: '<path d="M12 5v14M5 12h14"/>',
    trash: '<path d="M5 7h14M10 7V5h4v2M7 7l1 12h8l1-12"/>',
    star: '<path d="M12 3c.7 5 2.8 7.8 9 9-6.2 1.2-8.3 4-9 9-.7-5-2.8-7.8-9-9 6.2-1.2 8.3-4 9-9Z"/>',
  };

  function icon(name, size, extraClass) {
    const sw = size <= 14 ? 2.3 : 2;
    return '<svg class="' + (extraClass || '') + '" width="' + size + '" height="' + size + '" viewBox="0 0 24 24" fill="none" ' +
      'stroke="currentColor" stroke-width="' + sw + '" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false">' +
      ICON_PATH[name] + '</svg>';
  }

  // 悬浮球的转圈环：底环强调色 18%，上面一段约四分之一圈的圆头弧线
  const RING_SVG = (() => {
    const r = 22.75, c = 2 * Math.PI * r;
    return '<svg class="hb-ring" viewBox="0 0 48 48" aria-hidden="true" focusable="false">' +
      '<circle class="hb-ring-trk" cx="24" cy="24" r="' + r + '" fill="none" stroke-width="2.5"/>' +
      '<circle class="hb-ring-arc" cx="24" cy="24" r="' + r + '" fill="none" stroke-width="2.5" stroke-linecap="round" ' +
      'stroke-dasharray="' + (c / 4).toFixed(2) + ' ' + c.toFixed(2) + '"/></svg>';
  })();

  // ======================== 悬浮窗 ========================
  // 样式规范见 DESIGN.md。这里管结构、文案和交互：
  //   悬浮球：头像；转圈 = 正在记这一轮；右下角绿点 = 这一轮是新的，橙点 = 沿用上一轮 / 超时，红点 = 没连上。
  //   面板：顶上场记板斜纹，上沿趴着立绘；两页 ——「此刻」看现在挂在提示词里的状态，每张人物卡底下能展开详情；
  //         「设置」改了就存，不用点保存。
  // 酒馆助手的脚本跑在隐藏的 iframe 里，悬浮窗要挂到酒馆的顶层页面上，所以一律用 TOP.document。

  const UI_STORE = NS + '.ui';
  const POS_FAB = NS + '.pos.fab';
  const POS_PANEL = NS + '.pos.panel';
  const PERCH_H = 110;                      // 立绘显示高度；面板顶边离视口顶不到这么多就整张藏起来
  const ui = {
    fab: null, panel: null, body: null, view: 'now', open: false, offs: [],
    testMsg: null, dtestMsg: null, expanded: new Set(), advOpen: false, dot: '',
    tplOpen: new Set(), tplFilter: {}, tplMsg: null, bookMsg: null, plainOpen: new Set(), plainMsg: {}, tplPeople: '', plainFilter: '',
    sub: 'settings', pOpen: new Set(), dOpen: new Set(), pMsg: null, flipped: new Set(), redo: new Set(), addName: '', adding: null, skin: '', tkOpen: new Set(), tkSwiped: '', dirty: null, dirtySel: new Set(), cleanMsg: null, inh: null, inhMsg: null, addOpen: false, dealKey: '', setTab: '此聊天',
    stitch: null, stitchLoading: false, stitchSel: {}, stitchAdd: new Set(), stitchMsg: null, idMsg: null, models: null, ownSel: {},
  };

  function readUiPref() {
    try { return JSON.parse(TOP.localStorage.getItem(UI_STORE) || '{}') || {}; } catch (e) { return {}; }
  }
  function writeUiPref() {
    try { TOP.localStorage.setItem(UI_STORE, JSON.stringify({ open: ui.open, view: ui.view, sub: ui.sub })); } catch (e) { /* 隐私模式 */ }
  }

  // ---------- 拖动（鼠标和触屏走同一套 pointer 事件） ----------
  function makeDraggable(handle, target, storeKey, opts) {
    const win = TOP;
    const o = opts || {};
    let down = false, moved = false, sx = 0, sy = 0, sl = 0, st = 0, pid = null;
    const narrow = () => o.skipNarrow && win.innerWidth <= 600;

    const place = (l, t) => {
      const w = target.offsetWidth || 0, h = target.offsetHeight || 0;
      const left = Math.min(Math.max(4, l), Math.max(4, win.innerWidth - w - 4));
      let top;
      if (o.fit) {
        // 面板：顶边至少留出 160px 给内容，高度按顶边以下剩多少来限，内容再长也伸不出屏幕
        top = Math.min(Math.max(4, t), Math.max(4, win.innerHeight - 164));
        target.style.maxHeight = Math.max(160, Math.min(win.innerHeight * 0.78, win.innerHeight - top - 8)) + 'px';
      } else {
        top = Math.min(Math.max(4, t), Math.max(4, win.innerHeight - h - 4));
      }
      target.style.left = left + 'px';
      target.style.top = top + 'px';
      target.style.right = 'auto';
      target.style.bottom = 'auto';
      target.style.transform = 'none';
      if (o.onPlace) o.onPlace();
    };
    const onDown = (e) => {
      if (e.button !== undefined && e.button !== 0) return;
      if (narrow()) return;
      if (e.target.closest && e.target.closest('button,input,textarea,select,a') && e.target !== handle) return;
      down = true; moved = false; pid = e.pointerId;
      const r = target.getBoundingClientRect();
      sx = e.clientX; sy = e.clientY; sl = r.left; st = r.top;
      // 按下就抓住指针：不然手一快，下一次移动事件已经落在把手外面，拖动永远起不来
      try { handle.setPointerCapture(pid); } catch (err) { /* ignore */ }
    };
    const onMove = (e) => {
      if (!down || e.pointerId !== pid) return;
      const dx = e.clientX - sx, dy = e.clientY - sy;
      if (!moved && Math.abs(dx) + Math.abs(dy) < 5) return;
      if (!moved && o.dragClass) target.classList.add(o.dragClass);
      moved = true;
      e.preventDefault();
      place(sl + dx, st + dy);
    };
    const onUp = (e) => {
      if (!down || (e && e.pointerId !== pid)) return;
      down = false;
      try { handle.releasePointerCapture(pid); } catch (err) { /* ignore */ }
      if (o.dragClass) target.classList.remove(o.dragClass);
      if (moved) {
        const r = target.getBoundingClientRect();
        try { win.localStorage.setItem(storeKey, JSON.stringify({ left: r.left, top: r.top })); } catch (err) { /* ignore */ }
      }
    };
    handle.addEventListener('pointerdown', onDown);
    handle.addEventListener('pointermove', onMove);
    handle.addEventListener('pointerup', onUp);
    handle.addEventListener('pointercancel', onUp);

    const onResize = () => {
      if (target.style.left && target.style.left !== 'auto' && !narrow()) {
        const r = target.getBoundingClientRect();
        place(r.left, r.top);
      }
    };
    win.addEventListener('resize', onResize);
    ui.offs.push(() => win.removeEventListener('resize', onResize));

    const restore = () => {
      try {
        const saved = JSON.parse(win.localStorage.getItem(storeKey) || 'null');
        if (saved && typeof saved.left === 'number') { place(saved.left, saved.top); return true; }
      } catch (e) { /* ignore */ }
      return false;
    };
    // 拖过之后紧跟的那次 click 要吃掉，否则拖一下悬浮球面板就开了
    return { restore, place, consumeDrag: () => { const m = moved; moved = false; return m; } };
  }

  // ---------- 状态：这一轮怎么样了 ----------
  // 只看当前聊天的：切到别的聊天以后，上一个聊天还在路上的那一轮不该出现在这里
  function newestRun() {
    const chatId = currentChatId();
    let r = null;
    inflight.forEach((x) => { if (x.chatId === chatId && (!r || x.id > r.id)) r = x; });
    return r;
  }

  function lastRunHere() {
    return lastRun && lastRun.chatId === currentChatId() ? lastRun : null;
  }

  // 报错翻成人话：发生了什么、下一步怎么做
  function friendlyError(why) {
    const t = String(why || '');
    if (/Unauthorized|401|invalid.{0,12}(key|token)|authentication/i.test(t)) return '密钥无效（401），检查后再试';
    if (/403|forbidden/i.test(t)) return '没有权限（403），检查密钥和模型的开通情况';
    if (/404|not.?found|does not exist/i.test(t)) return '地址或模型名不对（404），检查后再试';
    if (/^(限流|额度用完了)（429）/.test(t)) return t.replace(/。服务端原话：[\s\S]*$/, '');   // 手账本自己写清了原因，照原样说
    if (/429|rate.?limit|too many/i.test(t)) return '请求太频繁（429），等一会儿再试';
    if (/Bad Request|HTTP 4(00|22)|Unprocessable/i.test(t)) return '接口拒收了请求（400），常见原因是模型不收某个参数，点「测试连接」自动查';
    const slow = t.match(/超过 (\d+) 秒没回/);
    if (slow) return '等了 ' + slow[1] + ' 秒还没回完，这一路放弃了。会思考的模型想得久，可以在附加请求体里关掉思考，或者换快一点的模型';
    if (/没回|timeout|timed out/i.test(t)) return '状态模型没有回应，稍后再试';
    if (/被截断/.test(t)) return '回答写到一半被截断：最多输出字数不够，会思考的模型思考也算字数。换不思考的模型，或者在附加请求体里关掉思考';
    if (/Failed to fetch|NetworkError|拿不到酒馆/i.test(t)) return '连不上酒馆后端，刷新页面再试';
    if (/ECONNREFUSED|Connection refused|ENOTFOUND|getaddrinfo|EAI_AGAIN|ECONNRESET|socket hang up|HTTP 50[234]/i.test(t)) return '连不上接口地址，检查「接口地址」';
    if (/没有填/.test(t)) return t;
    return clip(t, 48) || '原因不明，打开调试日志看控制台';
  }

  function freshCount(st) {
    return (st.order || []).filter((n) => st.people[n] && !st.people[n].carried && onStage(st.people[n])).length;
  }

  // 返回 { cls: ''|busy|fresh|stale|error, text, act }
  function statusOf() {
    const c = cfg();
    const running = newestRun();
    const st = latestState(loadStore(), null);
    const cool = reqCoolLeft();
    if (cool > 0) return { cls: 'stale', text: '限流中，' + Math.ceil(cool / 1000) + ' 秒后接着记' };
    if (running) {
      const n = running.jobsTotal || 0;
      return { cls: 'busy', text: '正在记这一轮' + (n ? '（' + (running.jobsDone || 0) + '/' + n + '）' : '') };
    }
    // 状态记完了、导演稿还在写：这一轮正文还没发出去
    const bn = briefNow();
    if (bn && bn.busy) return { cls: 'busy', text: '正在写这一轮的导演稿' };
    if (!String(c.副API地址 || '').trim() || !String(c.副模型 || '').trim()) {
      return { cls: 'error', text: '没连上：还没填状态模型的地址或名字', act: '去设置' };
    }
    if (sideUnset(c)) return { cls: 'error', text: '没连上：' + UNSET_MSG, act: '去设置' };   // 没填密钥、接口还是默认的火山方舟
    const last = lastRunHere();
    if (last && last.done && last.failed && !Object.keys(last.entries).length && !last.scene &&
        (!st || last.floor == null || last.floor >= st.floor)) {
      const why = (last.notes[0] || '').replace(/^[^：]*：/, '');
      return { cls: 'error', text: '没连上：' + friendlyError(why) + (st ? '。先用着上一轮的' : ''), act: '去设置' };
    }
    // 一路都没发出去就结束了（读材料时出错这类）：说出原因，别让面板看起来像什么都没发生
    if (last && last.done && !last.tail && last.source !== 'rerun' && !last.committed && !last.failed &&
        !Object.keys(last.entries).length && !last.scene && last.notes.length && (!st || last.upto > st.floor)) {
      return { cls: 'stale', text: '这一轮没记上：' + clip(last.notes[0].replace(/^出错：/, ''), 60) + (st ? '。先用着第 ' + st.floor + ' 楼的' : '') };
    }
    // 这一轮记完了却还没挂到玩家那一楼上：剧情推进还在跑、玩家那条还没落楼；或者那条消息被删了、认不出是哪一条
    if (last && !last.tail && last.source !== 'rerun' && !last.committed && (Object.keys(last.entries).length || last.scene) &&
        (!st || last.upto > st.floor)) {
      if (last.floor == null && pendingRun === last) return { cls: 'busy', text: '这一轮记好了，等玩家那条消息落楼' };
      return { cls: 'stale', text: '这一轮记好了但没挂上：' + (last.dropped || '没认出是哪一条玩家消息') + (st ? '。先用着第 ' + st.floor + ' 楼的' : '') };
    }
    if (!st) {
      if (!getApiKey()) return { cls: '', text: '还没开始记：还没填密钥（不填就用酒馆后端存的自定义接口密钥）', act: '去设置' };
      return { cls: '', text: '还没开始记', empty: true };
    }
    const r = last && last.floor === st.floor ? last : null;
    // 平行线事件推演没变、特意沿用的人（kept）不算「没算出来」
    const carried = (st.order || []).filter((n) => st.people[n] && st.people[n].carried && !st.people[n].kept);
    const n = freshCount(st);
    // 冲击轮等满了，但开着导演稿时导演稿会等这一轮的状态都回来再交给正文：那就不算沿用
    if (r && r.waited > 0 && r.timedOut && r.caughtUp) {
      return { cls: 'fresh', text: '这一轮是新的（第 ' + st.floor + ' 楼），记了 ' + n + ' 个人（导演稿等到了这一轮的状态，正文当轮就用上了）' };
    }
    if (r && r.waited > 0 && r.timedOut) {
      return { cls: 'stale', text: '沿用上一轮：这一轮超时了（等满 ' + (r.waited / 1000).toFixed(1) + ' 秒，回来的已经补上）' };
    }
    if (carried.length) {
      return { cls: 'stale', text: '沿用上一轮：' + carried.join('、') + ' 这一轮没算出来' + (n ? '，其余是新的' : '') };
    }
    if (r && r.source === 'rerun') {
      return { cls: 'fresh', text: '重算好了：' + (st.tail ? '读到第 ' + st.floor + ' 楼的正文' : '第 ' + st.floor + ' 楼（玩家那句）') +
        '，记了 ' + n + ' 个人，下一次生成起用这份' };
    }
    if (r && r.waited > 0) {
      return { cls: 'fresh', text: '这一轮是新的（第 ' + st.floor + ' 楼），记了 ' + n + ' 个人（等了 ' + ((r.waitedActual || 0) / 1000).toFixed(1) + ' 秒，正文当轮就用上了）' };
    }
    if (r) return { cls: 'fresh', text: '这一轮是新的（第 ' + st.floor + ' 楼），记了 ' + n + ' 个人（这一轮没等，下一次生成起生效）' };
    return { cls: 'fresh', text: '现在用的是第 ' + st.floor + ' 楼' + (st.tail ? '（读到这段正文）' : '') + '的状态，记了 ' + n + ' 个人' };
  }

  // ---------- 渲染：此刻 ----------
  // 面板上的标注和注入给正文模型的那块用同一套叫法（行动、目标、隐言、顾虑、动向），
  // 人物卡的标签四个字以内，放得进 52px 的标签列。
  function rowHtml(label, val, extra) {
    if (!val) return '';
    return '<div class="hb-row' + (extra ? ' ' + extra : '') + '"><b>' + label + '</b><span>' + val + '</span></div>';
  }

  function kvHtml(label, val) {
    return val ? '<div class="hb-kv"><b>' + label + '</b><span>' + val + '</span></div>' : '';
  }

  function sceneHtml(st, c) {
    const sc = st.scene;
    if (!sc) return '';
    const shown = shownPeople(st, c);
    const present = (sc.present || []).slice();
    shown.filter((n) => st.people[n].inScene !== false).forEach((n) => { if (present.indexOf(n) === -1) present.push(n); });
    // 平行线：一条一行，地点 · 在场
    const lines = parallelGroups(st, shown.filter((n) => st.people[n].inScene === false)).map((l) => {
      const who = l.present.slice();
      l.people.forEach((n) => { if (who.indexOf(n) === -1) who.push(n); });
      return who.length ? kvHtml('平行线', esc((l.place ? l.place + ' · ' : '') + who.join('、'))) : '';
    }).join('');
    // 这一轮场面那一路没算出来（出错、结构不对）时整块沿用上一轮：和人物卡一样标出来，免得把旧的地点当成新的
    const stale = st.sceneFresh === false ? '<span class="hb-pill warn">沿用上一轮</span>' : '';
    // 配角之间：一个标签，一对一行，名字在前（和交给正文的是同一份，见 09_templates.js 的 pairLines）
    const pairs = pairLines(st, c);
    const pairKv = pairs.length ? '<div class="hb-kv"><b>配角之间</b><span class="hb-pairs">' +
      pairs.map((p) => '<i class="hb-pair"><em>' + esc(p.a + ' 和 ' + p.b) + '</em>：' + esc(p.text) + '</i>').join('') + '</span></div>' : '';
    // 约定、事件：稳定人设才有，写法同配角之间（和交给正文的是同一份、同一个顺序，见 07_state.js 的 ledgerView）
    const lg = ledgerView(st, c);
    const ledgerKv = (label, rows) => rows.length ? '<div class="hb-kv"><b>' + label + '</b><span class="hb-pairs">' +
      rows.map((r) => '<i class="hb-pair"><em>' + esc(r[0]) + '</em>：' + esc(r[1]) + '</i>').join('') + '</span></div>' : '';
    // 写法：氛围、节奏、氛围轨迹收在场面块底下，默认收着；收着时旁边露出氛围名和节奏的头一句
    const mood = sc.mood && sc.mood.name ? sc.mood.name + (sc.mood.jump ? '（越界）' : '') : '';
    const track = moodTrackHtml();
    let style = '';
    if (mood || sc.breath || track) {
      const open = ui.expanded.has(STYLE_KEY);
      const head = sc.breath ? clip(String(sc.breath).split(/[，。；,;]/)[0], 10) : '';
      const sum = [mood, head].filter(Boolean).join(' · ');
      style = '<div class="hb-sfold"><button type="button" class="hb-fold-btn" data-act="bs" data-name="' + STYLE_KEY + '" ' +
        'aria-expanded="' + (open ? 'true' : 'false') + '">写法' + icon('chevron', 12) + '</button>' +
        (!open && sum ? '<span class="hb-sfold-sum">' + esc(sum) + '</span>' : '') + '</div>' +
        (open ? kvHtml('氛围', esc(mood)) +
          (sc.breath ? '<div class="hb-breath">' + icon('star', 11) + '<span>' + esc(sc.breath) + '</span></div>' : '') + track : '');
    }
    return '<div class="hb-scene">' +
      (sc.place || stale ? '<div class="hb-place">' + esc(sc.place || '') + stale + '</div>' : '') +
      kvHtml('在场', esc(present.join('、'))) +
      lines +
      pairKv +
      ledgerKv('约定', lg.promises.map(ledgerPromiseParts)) +
      ledgerKv('事件', lg.events.map(ledgerEventParts)) +
      kvHtml('去留', esc(sc.leave)) +
      kvHtml('世界', esc(sc.physics)) +
      kvHtml('偶遇', esc(sc.encounter || '')) +
      style +
      '</div>';
  }
  const STYLE_KEY = '#写法';

  // 氛围轨迹：最近 30 场一格一场，颜色按氛围池的类别；越界的那格描边。下面两个数：最近 10 场用了几种、同一种最短隔几场又出现
  function moodTrackHtml() {
    let t = null;
    try { t = moodTrack(loadStore()); } catch (e) { t = null; }
    if (!t || t.cells.length < 2) return '';
    const cells = t.cells.slice(-30).map((x) => {
      const k = MOOD_CATS.indexOf(x.cat);
      return '<i' + (x.jump ? ' class="j"' : '') + ' style="background:var(--mood-' + (k === -1 ? 'x' : k) + ')" title="第 ' + x.floor + ' 楼 ' + esc(x.name) + (x.jump ? '（越界）' : '') + '"></i>';
    }).join('');
    const note = '最近 ' + t.recent + ' 场用了 ' + t.kinds + ' 种' +
      (t.gap == null ? '，没有重复' : t.gap === 0 ? '，有连着两场同一种' : '，同一种最短隔 ' + t.gap + ' 场又出现');
    return kvHtml('氛围轨迹', '<span class="hb-mtrack">' + cells + '</span><span class="hb-mtrack-note">' + note + '</span>');
  }

  // 一个候选：抽中 / 被拦 / 普通。被拦的整体调淡，但警示行保持不透明，所以警示行放在调淡的那层外面。
  function candHtml(p, cd) {
    const pool = (p.dice && Array.isArray(p.dice.pool)) ? p.dice.pool : [];
    const ps = (p.dice && Array.isArray(p.dice.ps)) ? p.dice.ps : [];
    const k = pool.indexOf(cd.line);
    const shown = k !== -1 && ps[k] != null ? ps[k] : (Number(cd.p) || 0);
    const pct = Math.max(0, Math.min(100, Math.round(shown * 100)));
    const pick = !!(p.unsaid && p.unsaid.line === cd.line);
    return '<div class="hb-cand' + (pick ? ' pick' : '') + (cd.out ? ' out' : '') + '">' +
      '<div class="hb-cand-main">' +
      '<div class="hb-c1">' + (pick ? '<span class="hb-ck">' + icon('check', 10) + '</span>' : '') +
      '<span class="hb-line">「' + esc(cd.line) + '」</span><span class="hb-p">' + pct + '%</span></div>' +
      '<div class="hb-c2">' + (cd.to ? '<span class="hb-to">对' + esc(cd.to) + '</span>' : '') +
      '<span class="hb-bar"><i style="width:' + pct + '%"></i></span></div>' +
      (cd.whyNot ? '<div class="hb-c3">为什么没说：' + esc(cd.whyNot) + '</div>' : '') +
      (cd.evidence ? '<div class="hb-c3">证据：' + esc(cd.evidence) + '</div>' : '') +
      '</div>' +
      (cd.out ? '<div class="hb-cwarn">' + icon('warn', 12) + '<span>没用上：' + esc(cd.out) + '</span></div>' : '') +
      '</div>';
  }

  // 这一轮交给正文的导演稿：开着导演稿时放在人物卡下面，和「详情」一样折叠着
  const BRIEF_KEY = '#导演稿';
  function briefHtml(c) {
    const b = briefNow();
    if (c.导演稿 === '关' || !b) return '';
    const open = ui.expanded.has(BRIEF_KEY);
    let h = '<div class="hb-bs"><button type="button" class="hb-fold-btn" data-act="bs" data-name="' + BRIEF_KEY + '" ' +
      'aria-expanded="' + (open ? 'true' : 'false') + '">导演稿' + icon('chevron', 12) + '</button>';
    if (open) {
      h += '<div class="hb-bs-body">';
      if (b.busy) h += '<div class="hb-bs-note">正在写这一轮的导演稿。</div>';
      else if (!b.ok) h += '<div class="hb-bs-note">上一次没写成，照原样交给了正文：' + esc(b.why) + '</div>';
      else {
        h += '<div class="hb-brief-text">' + esc(String(b.text || '').replace(/^<导演稿>\n/, '').replace(/\n<\/导演稿>$/, '')) + '</div>';
        const foot = ['<span>收走 ' + b.cut + ' 条</span>', '<span>' + (b.cached ? '沿用写过的那份' : '用了 ' + (b.ms / 1000).toFixed(1) + ' 秒') + '</span>'];
        h += '<div class="hb-bs-foot">' + foot.join('') + '</div>';
      }
      h += '</div>';
    }
    return h + '</div>';
  }

  function backstageHtml(name, p) {
    if (p.carried) return '';                               // 沿用上一轮的人这一轮没有新的候选
    const open = ui.expanded.has(name);
    let h = '<div class="hb-bs"><button type="button" class="hb-fold-btn" data-act="bs" data-name="' + esc(name) + '" ' +
      'aria-expanded="' + (open ? 'true' : 'false') + '">详情' + icon('chevron', 12) + '</button>';
    if (open) {
      const cands = Array.isArray(p.cands) ? p.cands : [];
      h += '<div class="hb-bs-body"><div class="hb-bs-who">' + esc(name) + '</div>';
      if (!cands.length) h += '<div class="hb-bs-note">这一轮没有候选。</div>';
      cands.forEach((cd) => { h += candHtml(p, cd); });
      (p.notes || []).forEach((x) => { h += '<div class="hb-bs-note">' + esc(x) + '</div>'; });
      const foot = [];
      if (p.dice) foot.push('<span>骰值 ' + esc(p.dice.roll) + '</span>');
      if (p.ms) foot.push('<span>耗时 ' + esc((p.ms / 1000).toFixed(1)) + ' 秒</span>');
      if (foot.length) h += '<div class="hb-bs-foot">' + foot.join('') + '</div>';
      h += '</div>';
    }
    return h + '</div>';
  }

  // shown：这个人这一轮有没有注入（这一场的人、平行线上的人，在人数上限以内）
  // 判定骰在面板上怎么显示（内容规划书 3.3c、3.8）：只管面板，正文照样拿到结果
  const JUDGE_TIP = {
    按类型: '想要的事公开掷；没说出口的那句只写有过判定，点「翻面」才看；有没有人看出她在忍着，等它生效那一场才显示。',
    全公开: '所有判定都公开，连还没生效的暗骰也显示。',
    全藏起: '面板上不显示判定和暗骰。',
  };
  const CHECK_WORD = { pass贴线: '勉强', pass干净: '正好', pass夸张: '超出预期', fail贴线: '差一点', fail干净: '没成', fail夸张: '更糟' };
  // 隐言的结论跟着落点走：改口是说了一半，真说出来才是说出了口
  const HIDE_WORD = { line_pass: '说了一半', far_pass: '说出了口', line_fail: '没说出口', far_fail: '说反了' };
  function checkHtml(name, ck) {
    if (!ck || !ck.anchor) return '';
    const mode = cfg().判定显示;
    if (mode === '全藏起') return '';
    const key = name + ':' + ck.roll + ':' + ck.what;
    if (ck.kind === '隐言' && mode === '按类型' && !ui.flipped.has(key)) {
      return '这一场有过一次判定 <button type="button" class="hb-go" data-act="flip" data-key="' + esc(key) + '">翻面</button>';
    }
    const side = ck.pass ? 'pass' : 'fail';
    const verdict = ck.kind === '隐言' ? (HIDE_WORD[ck.slot] || (ck.pass ? '说出了口' : '没说出口')) : (ck.pass ? '做到了' : '没做到');
    const others = ['line_pass', 'line_fail', 'far_pass', 'far_fail'].map((k) => ck.anchors && ck.anchors[k]).filter((a) => a && a !== ck.anchor);
    return esc(ck.what) + '：阈值 ' + ck.T + '，掷出 ' + ck.roll + '，' + verdict + '（' + (CHECK_WORD[side + ck.band] || ck.band) + (ck.softened ? '，连着两轮夸张，降成干净' : '') + '）' +
      '<span class="hb-note">落点：' + esc(ck.anchor) + '</span>' + (others.length ? '<span class="hb-note">没拍的：' + others.map(esc).join(' / ') + '</span>' : '');
  }
  // 全公开时，还没生效的暗骰也显示在被看的那个人的卡片上
  function hiddenHtml(name) {
    if (cfg().判定显示 !== '全公开') return '';
    let list = [];
    try { list = (loadStore().meta.hidden || []).filter((h) => h && h.who === name && !h.revealed); } catch (e) { list = []; }
    return list.map((h) => '第 ' + h.floor + ' 楼：' + esc(h.by) + (h.seen ? '看出来了' : '没看出来') + '（阈值 ' + h.T + '，掷出 ' + h.roll + '）').join('；');
  }

  // floor：这一份状态挂的楼层（票根上写的号）
  function cardHtml(name, p, ch, shown, stable, floor) {
    const pills = [];
    const away = p.inScene === false && !shown;
    if (p.carried) pills.push('<span class="hb-pill warn">沿用上一轮</span>');
    if (p.inScene === false && shown) pills.push('<span class="hb-pill off">平行线</span>');
    if (away) pills.push('<span class="hb-pill off">不在场，没注入</span>');
    const unsaid = p.unsaid && p.unsaid.line
      ? '「' + esc(p.unsaid.line) + '」' + (p.unsaid.to ? '<span class="hb-to">对' + esc(p.unsaid.to) + '</span>' : '')
      : '';
    const busy = ui.redo.has(name);
    // 稳定人设：另一个人格、暗骰、压力、关系阶段都不算，也不交给正文，卡上跟着不写
    const dyn = !stable;
    const r = {
      sketch: rowHtml('简介', esc(p.sketch)),
      period: rowHtml('时期', esc(p.period || '')),
      persona: rowHtml('此刻之我', dyn && p.persona ? esc(p.persona) + '（替她出来的另一个人格）' : ''),
      doing: rowHtml('行动', esc(p.doing)),
      want: rowHtml('目标', esc(p.want)),
      unsaid: rowHtml('隐言', unsaid, 'unsaid'),
      afraid: rowHtml('顾虑', esc(p.afraid)),
      will: rowHtml('动向', esc(p.will)),
      check: rowHtml('判定', checkHtml(name, p.check)),
      fore: rowHtml('伏笔', dyn && p.foreshadow && p.foreshadow.by && cfg().判定显示 !== '全藏起' ? '第 ' + p.foreshadow.floor + ' 楼那次暗骰，现在生效：' + esc(p.foreshadow.by) + '看出来了' : ''),
      hidden: rowHtml('暗骰', dyn ? hiddenHtml(name) : ''),
      press: rowHtml('压力', dyn && ch && ch.level !== '平稳' ? esc(ch.level) : ''),
      rel: rowHtml('关系阶段', dyn && ch ? esc(relSummary(ch, 3, true)) : ''),
    };
    return ticketHtml(name, p, r, { pills, away, shown, busy, floor });
  }

  // ---------- 人物卡（DESIGN.md「BanG 皮肤「票根」」「原版改版：三套风格」） ----------
  // 左边人物色条；正文默认只露行动、动向，点一下展开其余几行和详情；右边那截写楼层号，下面是单独重算、删掉。
  // 手机上那一截收起，往左滑出来。分镜本楼层号写在左上角「CUT 楼层」，右边那截只有两个按钮
  const FLOOR_TAG = { bang: 'FLOOR', slate: 'SC', lamp: 'FLOOR', film: 'CUT' };
  function floorTag() { return FLOOR_TAG[ui.skin] || 'SC'; }
  function ticketHtml(name, p, r, o) {
    const f = faceOf(name);
    const open = ui.tkOpen.has(name);
    const par = p.inScene === false && o.shown;
    const film = ui.skin === 'film';
    const sw = ui.tkSwiped === name;
    // 窄屏点楼层号露出、收回右边那截（DESIGN.md「窄屏点楼层号、单独重算转圈」）
    const stubBtn = (cls, text) => '<button type="button" class="' + cls + '" data-act="stub" data-name="' + esc(name) + '" aria-expanded="' + (sw ? 'true' : 'false') +
      '" aria-label="' + (sw ? STUB_HIDE : STUB_SHOW) + '">' + esc(text) + '</button>';
    const stamp = o.floor != null && !film ? '<span class="hb-stamp"><b>' + o.floor + '</b><i>' + (par ? 'PARALLEL' : floorTag()) + '</i></span>' : '';
    return '<div class="hb-tk' + (o.away ? ' off' : '') + (open ? ' open' : '') + (sw ? ' swiped' : '') + '" data-tk="' + esc(name) + '" style="--pc:' + f.color + '">' +
      '<span class="hb-tk-band"></span>' +
      (film && o.floor != null ? stubBtn('hb-cut', 'CUT ' + o.floor) : '') +
      '<div class="hb-tk-main" data-act="tk" data-name="' + esc(name) + '" role="button" tabindex="0" aria-expanded="' + (open ? 'true' : 'false') + '">' +
      '<div class="hb-name"><span>' + esc(name) + '</span>' + o.pills.join('') + icon('chevron', 12) + '</div>' +
      '<div class="hb-rows">' + r.doing + r.will + '</div>' +
      '<div class="hb-tk-more"><div><div class="hb-rows">' + r.sketch + r.period + r.persona + r.want + r.unsaid + r.afraid +
      r.check + r.fore + r.hidden + r.press + r.rel + '</div>' + backstageHtml(name, p) + '</div></div></div>' +
      (o.floor != null && !film ? stubBtn('hb-tk-mini', '#' + o.floor) : '') +
      '<div class="hb-tk-stub">' + stamp +
      '<button type="button" class="hb-tk-btn' + (o.busy ? ' busy' : '') + '" data-act="redo" data-name="' + esc(name) + '"' + (o.busy ? ' disabled aria-busy="true"' : '') +
      ' title="' + (o.busy ? '重算中…' : '单独重算') + '" aria-label="' + (o.busy ? '正在重算 ' : '单独重算 ') + esc(name) + '">' + icon('refresh', 14) + '</button>' +
      '<button type="button" class="hb-tk-btn del" data-act="mute" data-name="' + esc(name) + '" title="删掉" aria-label="删掉 ' + esc(name) + '">' + icon('trash', 14) + '</button>' +
      '</div></div>';
  }
  // 主卡总控挂在酒馆主窗口上的只读名单（v、accent、people{主名:{avatar,color,team,aliases}}）。每次画都现读，不缓存
  function bangFace() {
    try {
      const f = TOP.__BANG_FACE__ || (TOP.top && TOP.top.__BANG_FACE__);
      return f && typeof f === 'object' && f.people && typeof f.people === 'object' ? f : null;
    } catch (e) { return null; }
  }
  // BanG 皮肤只跟 BanG 卡走：主卡挂了名单就用，外观里不另给选项
  function bangSkin() {
    return !!bangFace();
  }
  const BANG_ACCENT = '#3f7fd0';
  const BANG_PALETTE = ['#7f73c9', '#5b6fb8', '#e2a457', '#4fb3b0', '#d06a8a', '#6fb27a', '#c98a4a', '#6e93c6'];
  const HEX = /^#[0-9a-f]{6}$/i;
  // 名单里她的头像和应援色；没有的人按名字算一个固定的默认色，头像用名字第一个字
  function faceOf(name) {
    const f = bangFace();
    const ppl = (f && f.people) || {};
    let hit = ppl[name];
    if (!hit) {
      const k = Object.keys(ppl).find((x) => sameName(x, name) || (Array.isArray(ppl[x] && ppl[x].aliases) && ppl[x].aliases.some((a) => sameName(a, name))));
      if (k) hit = ppl[k];
    }
    let h = 0;
    String(name).split('').forEach((ch) => { h = (h * 31 + ch.charCodeAt(0)) >>> 0; });
    return {
      color: hit && HEX.test(String(hit.color || '')) ? hit.color : BANG_PALETTE[h % BANG_PALETTE.length],
      avatar: hit && /^https?:\/\//.test(String(hit.avatar || '')) ? String(hit.avatar) : '',
      initial: Array.from(String(name).replace(/[（(].*$/, '').trim())[0] || '?',
    };
  }
  function faceDot(name) {
    const f = faceOf(name);
    return '<i class="hb-face" style="--pc:' + f.color + '">' + esc(f.initial) +
      (f.avatar ? '<img alt="" loading="lazy" referrerpolicy="no-referrer" src="' + esc(f.avatar) + '" onerror="this.remove()">' : '') + '</i>';
  }
  // 顶栏下面一排人头胶囊：这一场的人在前，平行线上、没注入的人虚线；人头在左边那段里横着滚，「＋ 加上」固定在最右边
  function headsHtml(st, c) {
    if (!st) return '';
    const shown = shownPeople(st, c);
    const order = shown.concat((st.order || []).filter((n) => st.people[n] && shown.indexOf(n) === -1));
    return '<div class="hb-heads-list">' + order.map((n) => {
      const p = st.people[n];
      const away = p.inScene === false;
      return '<button type="button" class="hb-head' + (away ? ' away' : '') + '" data-act="jump" data-name="' + esc(n) + '">' + faceDot(n) + esc(n) + '</button>';
    }).join('') + '</div><button type="button" class="hb-head plus" data-act="addopen" aria-expanded="' + (ui.addOpen ? 'true' : 'false') + '">' + icon('plus', 12) + '加上</button>';
  }
  // 人头那一段左右还有没露出来的人时，边缘淡出（DESIGN.md「人头一排：「加上」固定、边缘淡出」）
  function fadeHeads(list) {
    if (!list) return;
    const max = list.scrollWidth - list.clientWidth;
    list.classList.toggle('fade-l', max > 1 && list.scrollLeft > 1);
    list.classList.toggle('fade-r', max > 1 && list.scrollLeft < max - 1);
  }
  const STUB_SHOW = '露出单独重算、删掉';
  const STUB_HIDE = '收起单独重算、删掉';
  // 露出这一张的右边那截（name 为空就全收回）：直接改 class，不整页重画（重画会把过渡动画冲掉）
  function setSwiped(name) {
    ui.tkSwiped = name || '';
    if (!ui.body) return;
    Array.from(ui.body.querySelectorAll('.hb-tk')).forEach((el) => {
      const on = !!name && el.dataset.tk === name;
      el.classList.toggle('swiped', on);
      el.querySelectorAll('[data-act="stub"]').forEach((b) => {
        b.setAttribute('aria-expanded', on ? 'true' : 'false');
        b.setAttribute('aria-label', on ? STUB_HIDE : STUB_SHOW);
      });
    });
  }
  // 点楼层号：只在窄屏起作用（宽屏那截一直露着）
  function toggleStub(name) {
    if (!name || !(TOP.matchMedia && TOP.matchMedia('(max-width: 600px)').matches)) return;
    setSwiped(ui.tkSwiped === name ? '' : name);
  }
  // 票根展开、收起：直接改这一张的 class，不整页重画（重画会把展开的过渡动画冲掉）
  function toggleTicket(name) {
    if (!name) return;
    const el = ui.body && Array.from(ui.body.querySelectorAll('.hb-tk')).find((x) => x.dataset.tk === name);
    const open = !ui.tkOpen.has(name);
    if (open) ui.tkOpen.add(name); else ui.tkOpen.delete(name);
    if (el) {
      el.classList.toggle('open', open);
      const m = el.querySelector('.hb-tk-main');
      if (m) m.setAttribute('aria-expanded', open ? 'true' : 'false');
    }
  }
  // 点人头胶囊：滚到她的票根并展开
  function jumpTicket(name) {
    const el = ui.body && Array.from(ui.body.querySelectorAll('.hb-tk')).find((x) => x.dataset.tk === name);
    if (!el) return;
    if (!ui.tkOpen.has(name)) toggleTicket(name);
    const reduce = TOP.matchMedia && TOP.matchMedia('(prefers-reduced-motion: reduce)').matches;
    const top = Math.max(0, ui.body.scrollTop + el.getBoundingClientRect().top - ui.body.getBoundingClientRect().top - 8);
    // 平滑滚动途中面板要是重画（回来一个人就重画一次），滚动会停在半路：重画时直接落到这里（renderPanel）
    ui.jumpTarget = { top, until: Date.now() + 800 };
    try { ui.body.scrollTo({ top, behavior: reduce ? 'auto' : 'smooth' }); } catch (e) { ui.body.scrollTop = top; }
  }
  function loadBangFonts() {
    const doc = TOP.document;
    if (!doc || doc.getElementById('hb-bang-fonts')) return;
    const l = doc.createElement('link');
    l.id = 'hb-bang-fonts';
    l.rel = 'stylesheet';
    l.href = 'https://fonts.googleapis.com/css2?family=Fredoka:wght@500;600;700&family=Noto+Sans+SC:wght@500;700;900&display=swap';
    doc.head.appendChild(l);
  }

  // 人物卡上的「单独重算」：只给这一个人重发一次，结果换进面板正在显示的那一楼（见 08_run.js 的 redoPerson）
  async function runRedo(name) {
    if (!name || ui.redo.has(name)) return;
    if (newestRun()) { toast('info', '这一轮还在记，等它回来再重算'); return; }
    ui.redo.add(name);
    renderPanel();
    try {
      const st = await redoPerson(name);
      toast('success', '重算好了：' + name + '（第 ' + st.floor + ' 楼）');
    } catch (e) {
      toast('warning', name + ' 重算没成：' + friendlyError((e && e.message) || String(e)));
    } finally {
      ui.redo.delete(name);
      renderPanel();
    }
  }

  // 此刻页人物卡下面：这一楼漏记的人，填名字点「加上」（见 08_run.js 的 addPerson）
  function addHtml() {
    const busy = !!ui.adding;
    return '<div class="hb-add"><div class="hb-add-row">' +
      '<input class="hb-input" type="text" data-addname="1" placeholder="名字" value="' + esc(ui.addName) + '" spellcheck="false" autocomplete="off"' + (busy ? ' disabled' : '') + '>' +
      '<button type="button" class="hb-btn" data-act="add"' + (busy ? ' disabled' : '') + '>' + (busy ? '正在记…' : '加上') + '</button></div>' +
      '<span class="hb-note">这一楼漏记的人：填名字点「加上」，只给她记这一楼，不占「每一场最多记几个人」的名额。</span></div>';
  }

  async function runAdd() {
    const text = String(ui.addName || '').trim();
    if (!text || ui.adding) return;
    if (newestRun()) { toast('info', '这一轮还在记，等它回来再加'); return; }
    const box = ui.body && ui.body.querySelector('[data-addname]');
    if (box) box.blur();                  // 焦点在框里时此刻页不重画，先让出来
    ui.adding = text;
    renderPanel();
    try {
      const st = await addPerson(text);
      ui.addName = '';
      toast('success', '加上了：' + st.order[st.order.length - 1] + '（第 ' + st.floor + ' 楼）');
    } catch (e) {
      toast('warning', text + ' 没加上：' + friendlyError((e && e.message) || String(e)));
    } finally {
      ui.adding = null;
      renderPanel();
    }
  }

  // 设置页「此聊天」组里的「不记的人」：这个聊天里删掉的人，一人一行，后面跟「恢复」
  function mutedField() {
    let list = [];
    try { list = Array.from(mutedNames()); } catch (e) { list = []; }
    return '<div class="hb-field"><span class="hb-flabel">不记的人</span>' +
      (list.length ? '<div class="hb-muted">' + list.map((n) => '<div class="hb-muted-row"><span>' + esc(n) + '</span>' +
        '<button type="button" class="hb-go" data-act="unmute" data-name="' + esc(n) + '">恢复</button></div>').join('') + '</div>' : '') +
      '<span class="hb-note">' + (list.length ? '点「恢复」，下一轮起照常记。' : '还没有。人物卡上点「删掉」的人列在这里。') + '</span></div>';
  }

  // 人物卡上的「删掉」：只管这个聊天，这个人以后不再记（见 08_run.js 的 mutePerson）；设置里「不记的人」点「恢复」放回来
  function runMute(name) {
    if (!name) return;
    try {
      mutePerson(name);
      ui.expanded.delete(name);
      toast('success', '删掉了：' + name + '。这个聊天不再记她，设置里「不记的人」能恢复');
    } catch (e) {
      toast('warning', name + ' 没删掉：' + ((e && e.message) || String(e)));
    }
    renderPanel();
  }
  function runUnmute(name) {
    if (name && unmutePerson(name)) toast('success', '恢复了：' + name + '，下一轮起照常记');
    renderPanel();
  }

  // ---------- 设置「性格模板」：选择性格模板、整理好的模板 ----------
  // 两栏顶上各一个筛选框，打字时只换下面那一块列表。名册超过 TPL_LIST_ALL 人时，没输字只列最新一楼记了状态的人、
  // 和她们用到的模板，其余靠筛选框找；「整理好的模板」筛选时搜整本模板书，没人用的也列出来，能先改好
  // （档案的读写见 09_templates.js 的 plainText / savePlainEdit / replain）
  const TPL_LIST_ALL = 20;
  const hitText = (s, f) => String(s || '').toLowerCase().indexOf(f) !== -1;

  // 用到的模板：names 里的人（不给就是名册里所有人），同一类只留一本
  function usedTemplates(R, c, tpl, names) {
    const out = [];
    (names || Array.from(R.people.keys())).forEach((n) => {
      const p = R.people.get(n);
      if (!p) return;
      templateSource(p.name, p.profile, c, tpl).list.forEach((t) => { if (!out.some((x) => x.kind === t.kind)) out.push(t); });
    });
    return out;
  }
  // 最新一楼记了状态的人，只留名册里有的
  function sceneNames(R) {
    let st = null;
    try { st = latestState(loadStore(), null); } catch (e) { st = null; }
    return st && st.people ? Object.keys(st.people).filter((n) => R.people.has(n)) : [];
  }
  // 「选择性格模板」列哪些人。输了字：名字、别名、她现在用的模板名里有这几个字的；没输字：名册不多全列，人多只列这一场的
  function tplPeopleView(R, c, tpl, query) {
    const all = Array.from(R.people.keys());
    const f = String(query || '').trim().toLowerCase();
    if (f) {
      const names = all.filter((n) => {
        const p = R.people.get(n);
        return hitText(n, f) || (p.aliases || []).some((a) => hitText(a, f)) ||
          templateSource(n, p.profile, c, tpl).list.some((t) => hitText(t.name, f) || hitText(t.kind, f));
      });
      return { names, note: names.length ? '' : '没有对得上的人。' };
    }
    if (all.length <= TPL_LIST_ALL) return { names: all, note: '' };
    const scene = sceneNames(R);
    return { names: scene, note: '名册 ' + all.length + ' 人，' + (scene.length ? '只列这一场的 ' + scene.length + ' 人，其余输名字找。' : '这一场没记到人，输名字找。') };
  }
  // 同一类有几本（同一本导了两次）时，先挑有人在用的那本，再挑开着的
  function kindTemplate(kind, used) {
    const u = (used || []).find((t) => t.kind === kind);
    if (u) return u;
    const hits = ((_tpl && _tpl.list) || []).filter((t) => t.kind === kind);
    return hits.find((t) => t.enabled) || hits[0] || null;
  }
  // 「整理好的模板」列哪些。输了字：搜整本模板书，有人用的排前面，没人用的标出来；没输字：names 里的人用到的
  function plainView(R, c, tpl, names, query) {
    const used = usedTemplates(R, c, tpl);
    const f = String(query || '').trim().toLowerCase();
    if (!f) {
      const list = usedTemplates(R, c, tpl, names);
      const more = new Set(tpl.list.map((t) => t.kind)).size > list.length;
      return { list: list.map((t) => ({ t, unused: false })), note: more ? '没列出来的模板，输模板名找；没人用的也能先改好。' : '' };
    }
    const seen = new Set();
    const list = [];
    used.concat(tpl.list).forEach((t) => {
      if (seen.has(t.kind) || !(hitText(t.kind, f) || hitText(t.name, f))) return;
      seen.add(t.kind);
      const unused = !used.some((u) => u.kind === t.kind);
      list.push({ t: unused ? kindTemplate(t.kind, used) : t, unused });
    });
    return { list, note: list.length ? '' : '没有对得上的模板。' };
  }
  // 一本一个折叠：开关文字是模板名，后面标整理中、改过、没人用、还没整理；展开是档案（能改）和「重新整理」
  function plainFold(t, unused) {
    const p = plainOf(t);
    const busy = plainBusy(t);
    const tag = busy ? '（整理中…）' : p && p.manual ? '（改过）' : unused ? '（没人用）' : !p ? '（还没整理）' : '';
    const open = ui.plainOpen.has(t.kind);
    let h = '<div class="hb-tpl"><button type="button" class="hb-fold-btn" data-act="plain" data-name="' + esc(t.kind) + '" aria-expanded="' +
      (open ? 'true' : 'false') + '">' + esc(t.kind + tag) + icon('chevron', 12) + '</button>';
    if (open) {
      h += '<div class="hb-tpl-body">' +
        '<textarea class="hb-input hb-plain" data-plain="' + esc(t.kind) + '" spellcheck="false" aria-label="' + esc(t.kind) + ' 整理好的档案"' +
        (busy ? ' disabled' : '') + '>' + esc(plainText(p)) + '</textarea>' +
        '<div class="hb-actions"><button type="button" class="hb-btn" data-act="replain" data-name="' + esc(t.kind) + '"' + (busy ? ' disabled' : '') +
        '>重新整理</button>' + resultHtml(ui.plainMsg[t.kind]) + '</div>' +
        '<span class="hb-note">改的是这本模板，用到它的人都跟着变。</span></div>';
    }
    return h + '</div>';
  }
  const noteHtml = (s) => (s ? '<span class="hb-note">' + esc(s) + '</span>' : '');
  function plainListHtml(R, c, tpl, names) {
    const v = plainView(R, c, tpl, names, ui.plainFilter);
    return v.list.map((x) => plainFold(x.t, x.unused)).join('') + noteHtml(v.note);
  }
  // 整栏。模板书里一本模板都没有就不出现
  function plainField(R, c, tpl, names) {
    if (!tpl || !tpl.list.length) return '';
    return '<div class="hb-field"><span class="hb-flabel">整理好的模板</span>' +
      '<input class="hb-input" type="text" data-plainfilter="1" value="' + esc(ui.plainFilter) + '" placeholder="筛选模板名，比如：三无" aria-label="筛选模板名" spellcheck="false" autocomplete="off">' +
      '<div class="hb-tpl-rows" data-plainlist="1">' + plainListHtml(R, c, tpl, names) + '</div></div>';
  }
  // 一个角色一行：折叠开关写着现在用的几本，展开是筛选框加勾选列表
  function pickerHtml(name, profile, c, tpl) {
    const src = templateSource(name, profile, c, tpl);
    const chosen = src.from === '手选';
    const sel = src.list.map((t) => t.name);
    const open = ui.tplOpen.has(name);
    const note = personNotes()[name] || '';
    const summary = (sel.length ? sel.join('、') + (chosen ? '' : src.from === '性格标签' ? '（按卡推荐）' : '（自动识别）')
      : (TPL_EMPTY[src.from] || '没有推荐')) + (note ? '（有补充）' : '');
    let h = '<div class="hb-tpl"><button type="button" class="hb-fold-btn" data-act="tpl" data-name="' + esc(name) + '" aria-expanded="' +
      (open ? 'true' : 'false') + '">' + esc(name) + '：' + esc(summary) + icon('chevron', 12) + '</button>';
    if (open) {
      h += '<div class="hb-tpl-body">' +
        '<input class="hb-input" type="text" data-tplfilter="' + esc(name) + '" value="' + esc(ui.tplFilter[name] || '') +
        '" placeholder="筛选，比如：三无" aria-label="筛选性格模板" spellcheck="false" autocomplete="off">' +
        '<div class="hb-tpl-list" data-tpllist="' + esc(name) + '">' + tplListHtml(name, sel, tpl) + '</div>' +
        '<span class="hb-note">最多选 3 本。和角色卡冲突时听角色卡。</span>' +
        (chosen ? '<div class="hb-actions"><button type="button" class="hb-btn" data-act="tplauto" data-name="' + esc(name) +
          '">改回自动</button></div>' : '') +
        // 补充：只对她、只管这个聊天；失焦时存
        '<label class="hb-field"><span class="hb-flabel">补充</span>' +
        '<textarea class="hb-input" data-pnote="' + esc(name) + '" spellcheck="false" aria-label="' + esc(name) + ' 的补充">' + esc(note) + '</textarea>' +
        '<span class="hb-note">只对她生效。和模板冲突时照这里。只管这个聊天。</span></label>' +
        // 时期：一句话，只管这个聊天；失焦时存
        periodFieldHtml(name) +
        relEditHtml(name) + '</div>';
    }
    return h + '</div>';
  }
  // 时期：世界书里她有几个时期的条目时是下拉框（自动，或者选一个），没有时手填一句
  function periodFieldHtml(name) {
    const R = rosterFull();
    const p = R && R.people.get(name);
    const typed = personPeriods()[name] || '';
    if (p && p.periods) {
      const cur = matchPeriod(p, typed);
      const st = latestState(loadStore(), null);
      const auto = st && st.people && st.people[name] ? st.people[name].period : '';
      return '<label class="hb-field"><span class="hb-flabel">时期</span>' +
        '<select class="hb-input" data-pperiod="' + esc(name) + '" aria-label="' + esc(name) + ' 的时期">' +
        '<option value=""' + (cur ? '' : ' selected') + '>自动（照剧情判断）</option>' +
        p.periods.map((v) => '<option' + (v.label === cur ? ' selected' : '') + '>' + esc(v.label) + '</option>').join('') + '</select>' +
        '<span class="hb-note">世界书里她有这几个时期的条目。选了就只用这个时期的那条，写正文时别的时期的条目不带；选自动，每轮照剧情判断' +
        (auto && !cur ? '，现在是「' + esc(auto) + '」' : '') + '。只管这个聊天。</span></label>';
    }
    return '<label class="hb-field"><span class="hb-flabel">时期</span>' +
      '<input class="hb-input" type="text" data-pperiod="' + esc(name) + '" value="' + esc(typed) + '" spellcheck="false" autocomplete="off" aria-label="' + esc(name) + ' 的时期">' +
      '<span class="hb-note">她现在处在剧情的哪个时期。卡里分时期写的，只用这个时期的。空着就不管。只管这个聊天。</span></label>';
  }
  // 关系：面板显示的那一楼里她对每个人的关系，阶段、好感底色、信任落点能直接改（见 08_run.js 的 setRelation）。稳定时不出现
  function relEditHtml(name) {
    if (isStable()) return '';
    const st = latestState(loadStore(), null);
    const ch = st && st.chars ? st.chars[name] : null;
    const tos = ch && ch.rel ? Object.keys(ch.rel) : [];
    if (!tos.length) return '';
    const attr = (to, f) => ' data-prel="' + esc(name) + '" data-pto="' + esc(to) + '" data-pf="' + f + '"';
    return '<div class="hb-field"><span class="hb-flabel">关系</span><div class="hb-rel-edit">' + tos.map((to) => {
      const r = ch.rel[to];
      return '<div class="hb-rel-row"><span class="hb-rel-to">对' + esc(to) + '</span>' +
        '<select class="hb-input"' + attr(to, 'stage') + ' aria-label="' + esc(name) + '对' + esc(to) + '的关系阶段">' +
        STAGES.map((sg) => '<option' + (sg === r.stage ? ' selected' : '') + '>' + esc(sg) + '</option>').join('') + '</select>' +
        '<input class="hb-input" type="text"' + attr(to, 'tone') + ' value="' + esc(r.tone || '') + '" placeholder="好感底色" spellcheck="false" autocomplete="off" aria-label="' + esc(name) + '对' + esc(to) + '的好感底色">' +
        '<input class="hb-input" type="text"' + attr(to, 'trust') + ' value="' + esc(r.trust || '') + '" placeholder="信任落点" spellcheck="false" autocomplete="off" aria-label="' + esc(name) + '对' + esc(to) + '的信任落点"></div>';
    }).join('') + '</div>' +
      '<span class="hb-note">面板显示的那一楼里她对每个人的关系。改了就存，下一轮起照这里。只管这个聊天。</span></div>';
  }
  function peopleListHtml(R, c, tpl) {
    const v = tplPeopleView(R, c, tpl, ui.tplPeople);
    return v.names.map((n) => pickerHtml(n, R.people.get(n).profile, c, tpl)).join('') + noteHtml(v.note);
  }
  function plainTemplate(kind) {
    const R = rosterFull();
    return kindTemplate(kind, R ? usedTemplates(R, cfg(), _tpl) : []);
  }
  // 文本框失焦时存：和现在的一样不动；清空就重新整理
  function onPlainChange(el) {
    const t = plainTemplate(el.dataset.plain);
    if (!t) return;
    if (!String(el.value || '').trim()) { runReplain(t.kind); return; }
    if (plainText(parsePlainText(el.value)) === plainText(plainOf(t))) return;
    savePlainEdit(t, el.value).then(() => {
      ui.plainMsg[t.kind] = { ok: true, text: '存好了，下一轮起照这份写' };
      scheduleBookWrite();
      renderPanel();
    });
  }
  async function runReplain(kind) {
    const t = plainTemplate(kind);
    if (!t || plainBusy(t)) return;
    ui.plainMsg[kind] = { busy: true, text: '正在重新整理…' };
    const job = replain(t, cfg());
    renderPanel();
    const p = await job;
    ui.plainMsg[kind] = p ? { ok: true, text: '整理好了' } : { ok: false, text: '没整理成：' + friendlyError(plainError(t) || '状态模型没有回应') };
    if (p) scheduleBookWrite();
    renderPanel();
  }

  // stable：此聊天选了稳定人设，状态条末尾挂一个「稳定」胶囊
  function statusHtml(s, stable) {
    return '<div class="hb-status ' + s.cls + '"><span class="hb-sdot"></span>' +
      '<span class="hb-stext">' + esc(s.text) + '</span>' +
      (s.act ? '<button type="button" class="hb-go" data-act="go">' + esc(s.act) + '</button>' : '') +
      (stable ? '<span class="hb-pill off">稳定</span>' : '') + '</div>';
  }

  function renderNow() {
    const c = cfg();
    const s = statusOf();
    const store = loadStore();
    const st = latestState(store, null);
    const stable = isStable(store);
    if (!st && s.empty) {
      return '<p class="hb-empty">还没开始记。发一句话，角色回话之前，这里会写下每个人此刻的状态。</p>';
    }
    // 换了一份状态（新的一轮、重算）才发一次卡片、盖章，同一份重画不再动
    const dk = st ? st.floor + '|' + (st.runKey || st.at || '') : '';
    const deal = dk && dk !== ui.dealKey;
    ui.dealKey = dk;
    let h = '<div class="hb-stack' + (deal ? ' hb-deal' : '') + '">' + statusHtml(s, stable);
    if (st) {
      if (ui.addOpen) h += addHtml();
      const sh = sceneHtml(st, c);
      const setNo = ui.skin === 'bang' ? 'SET · ' + st.floor : floorTag() + ' ' + st.floor;
      h += sh ? sh.replace('<div class="hb-scene">', '<div class="hb-scene"><span class="hb-set-no">' + setNo + '</span>') : sh;
      // 这一场的人在前，平行线上的人跟着，没注入的放最后
      const shown = shownPeople(st, c);
      const order = shown.concat((st.order || []).filter((n) => st.people[n] && shown.indexOf(n) === -1));
      order.forEach((n) => { h += cardHtml(n, st.people[n], st.chars && st.chars[n], shown.indexOf(n) !== -1, stable, st.floor); });
      h += briefHtml(c);
    } else {
      h += '<p class="hb-empty">还没开始记。发一句话，角色回话之前，这里会写下每个人此刻的状态。</p>';
    }
    return h + '</div>';
  }

  // ---------- 渲染：设置 ----------
  // 性格模板一行没有模板时写什么（按 templateSource 的 from）
  const TPL_EMPTY = {
    手选: '不用',
    自动识别: '自动识别过，没有合适的',
    识别中: '正在自动识别…',
    等识别: '等着自动识别',
    没识别成: '自动识别没成功，点「重新识别」再试',
    档案太短: '档案太短，认不出性格，不用管',
    没有模板: '模板书里的模板都关着',
  };

  const CHAT_MODES = ['稳定', '动态'];
  const CHAT_MODE_TIP = {
    稳定: '照角色卡和档案演，不用性格模板，不算压力、崩溃和关系阶段；记下发生的好事坏事和约定，交给正文。',
    动态: '记压力、崩溃和关系阶段，用性格模板，人物跟着剧情慢慢变。',
  };

  const MODE_TIP = {
    冲击轮: '只在要紧的一轮等它（点名、动手、告白、质问这类）。平常不等，这一轮的状态从下一次生成起生效。',
    每轮: '每一轮都等它算完再写正文。状态最新，但每轮都多等两三秒。',
    从不: '从来不等状态模型。正文读上一轮的状态，发送不会卡在这一步。开着导演稿时，写稿那一步照样要等。',
  };

  const DIRECTOR_TIP = {
    关: '数据库的记忆和剧情推进找回来的东西，照原样交给正文模型。',
    只接管记忆: '数据库写进世界书的记忆和剧情推进交出来的东西由手账本收走，写成一份导演稿，连同此刻状态放进玩家这一轮交给正文；聊天记录里玩家那条还原成原话。每轮要等它写完，最多等 600 秒；写不成就这一轮照原样交给正文。只对聊天补全接口有效。',
    连设定一起: '在「只接管记忆」的基础上，世界书里这一轮激活的设定条目也收走，一起写进导演稿（「按场景选设定」多挑的那几条也在内）。稿子更长、等得更久，设定也更容易写漏；设定多的卡建议用「只接管记忆」。',
  };

  // 导演稿上一次的结果，用设置页的结果提示那一套画
  function briefResult() {
    const b = briefNow();
    if (!b) return '';
    if (b.busy) return resultHtml({ busy: true, text: '正在写这一轮的导演稿' });
    if (!b.ok) return resultHtml({ ok: false, text: '上一次没写成，照原样交给了正文：' + b.why });
    return resultHtml({ ok: true, text: '上一次' + (b.cached ? '沿用了这一句写过的那份' : '写好了，用了 ' + Math.round(b.ms / 1000) + ' 秒') +
      '，收走 ' + b.cut + ' 条' + (b.missed.length ? '，有 ' + b.missed.length + ' 条没找到、留在了原处' : '') +
      (b.dropped && b.dropped.length ? '，有 ' + b.dropped.length + ' 条太长没进稿子、留在了原处' : '') +
      (b.plotCut ? '，剧情推进的内容太长，砍了约 ' + b.plotCut + ' 字' : '') +
      (b.restoreFailed ? '；玩家那条没能还原成原话，数据库这一轮填表可能会记错' : '') });
  }

  function resultHtml(t) {
    if (!t) return '';
    if (t.busy) return '<div class="hb-result busy" role="status">' + icon('spinner', 14, 'hb-spin') + '<span>' + esc(t.text) + '</span></div>';
    if (t.warn) return '<div class="hb-result warn" role="status">' + icon('warn', 14) + '<span>' + esc(t.text) + '</span></div>';
    return '<div class="hb-result ' + (t.ok ? 'ok' : 'bad') + '" role="status">' + icon(t.ok ? 'okCircle' : 'xCircle', 14) +
      '<span>' + esc(t.text) + '</span></div>';
  }

  // ---------- 渲染：提示词 ----------
  // 设置页顶上的切换：设置 / 提示词
  function subTabs() {
    return '<div class="hb-seg" role="group" aria-label="设置分页">' + [['settings', '设置'], ['prompts', '提示词']].map(([v, n]) =>
      '<button type="button" data-act="sub" data-val="' + v + '" aria-pressed="' + (ui.sub === v ? 'true' : 'false') + '">' + n + '</button>').join('') + '</div>';
  }

  const PROMPT_GROUPS = ['前置提示词', '给状态模型的', '给写稿模型的', '给正文模型的'];

  function debugKey(x) { return String(x.at) + '|' + x.label; }

  function renderPrompts() {
    let h = '<section class="hb-grp"><div class="hb-grp-hd"><h4>提示词预设</h4>' +
      '<p>下面每一段都是手账本发给模型的原文，点开就能改，也可以整段复制给别的 AI 改完再贴回来。改完点一下别处就存上。模型回答的格式由手账本定，改提示词改不了它。</p></div>' +
      '<div class="hb-actions"><button type="button" class="hb-btn" data-act="pexport">导出这一套</button>' +
      '<button type="button" class="hb-btn" data-act="pimport">导入预设</button>' +
      '<button type="button" class="hb-btn danger" data-act="presetall">全部恢复内置</button>' + resultHtml(ui.pMsg) + '</div></section>';
    PROMPT_GROUPS.forEach((g) => {
      h += '<section class="hb-grp"><div class="hb-grp-hd"><h4>' + esc(g) + '</h4></div>';
      PROMPT_DEFS.filter((d) => d.group === g).forEach((d) => {
        const st = promptState(d.id);
        const open = ui.pOpen.has(d.id);
        h += '<div class="hb-tpl"><button type="button" class="hb-fold-btn" data-act="pfold" data-name="' + esc(d.id) + '" aria-expanded="' +
          (open ? 'true' : 'false') + '">' + esc(d.id) + (st.custom ? '（改过）' : d.builtin() ? '（内置）' : '（空）') + icon('chevron', 12) + '</button>';
        if (open) {
          h += '<div class="hb-tpl-body"><span class="hb-note">' + esc(d.tip) +
