  // 复制到剪贴板：手机和旧浏览器没有 clipboard 接口时，退回选中再复制
  async function copyText(text) {
    try {
      if (TOP.navigator.clipboard && TOP.navigator.clipboard.writeText) { await TOP.navigator.clipboard.writeText(text); return true; }
    } catch (e) { /* 下面退回旧办法 */ }
    try {
      const doc = TOP.document;
      const ta = doc.createElement('textarea');
      ta.value = text;
      ta.setAttribute('readonly', '');
      ta.style.cssText = 'position:fixed;left:-9999px;top:0;';
      doc.body.appendChild(ta);
      ta.select();
      const ok = doc.execCommand('copy');
      ta.remove();
      return ok;
    } catch (e) {
      return false;
    }
  }

  function promptNote(ok, text) { ui.pMsg = { ok, text }; renderPanel(); }

  // 导出：点下去就给一个文件（在这一下点击里直接下载，浏览器才认）
  function exportPrompts() {
    try {
      const json = JSON.stringify(exportPromptPreset(), null, 2);
      const Blob_ = TOP.Blob || Blob;
      const URL_ = TOP.URL || URL;
      const url = URL_.createObjectURL(new Blob_([json], { type: 'application/json' }));
      const a = TOP.document.createElement('a');
      a.href = url;
      a.download = '常夜灯的手账本_提示词预设.json';
      TOP.document.body.appendChild(a);
      a.click();
      a.remove();
      setTimeout(() => URL_.revokeObjectURL(url), 60000);
      promptNote(true, '导出好了：常夜灯的手账本_提示词预设.json');
    } catch (e) {
      promptNote(false, '导出失败：' + ((e && e.message) || e));
    }
  }

  // 导入：选一个预设文件，换成这一套（文件里没有的段回到内置）
  function importPrompts() {
    const doc = TOP.document;
    const input = doc.createElement('input');
    input.type = 'file';
    input.accept = '.json,application/json';
    input.style.display = 'none';
    input.addEventListener('change', async () => {
      const f = input.files && input.files[0];
      input.remove();
      if (!f) return;
      try {
        const obj = JSON.parse(await f.text());
        const r = importPromptPreset(obj);
        ui.pOpen.clear();
        promptNote(true, '导入好了：' + r.changed + ' 段和内置不一样' + (r.unknown.length ? '；有 ' + r.unknown.length + ' 段认不出来，跳过了（' + r.unknown.join('、') + '）' : ''));
      } catch (e) {
        promptNote(false, '导入失败：' + ((e && e.message) || e));
      }
    });
    doc.body.appendChild(input);
    input.click();
  }

