      const mine = st.sheets.filter((s) => !isOwnSheet(s.name));
      const any = mine.some((s) => s.stitched);
      mine.forEach((s) => {
        const on = Object.prototype.hasOwnProperty.call(ui.stitchSel, s.name) ? ui.stitchSel[s.name] : stitchByDefault(s, any);
        const base = s.stitched ? (s.outdated ? '规则更新过，点「一键拼表」换成新的' : '已经拼上了') : stitchReads(s.name) ? '手账本读这张，还没拼' : '';
        // 表里有专门写认知、关系、心理的列：拼上以后那几列照它们自己的说明写，分工规则只管别的列
        const mind = s.mind && s.mind.length ? '有写心理、关系的列：' + s.mind.join('、') + '。这几列照列的说明写，分工规则管别的列' : '';
        const tip = [base, mind].filter(Boolean).join('。');
        h += '<label class="hb-check"><input type="checkbox" data-stitch="' + esc(s.name) + '"' + (on ? ' checked' : '') + '><span><b>' +
          esc(s.name) + '</b>' + (tip ? '<small>' + esc(tip) + '</small>' : '') + '</span></label>';
      });
      stitchMissing(st.sheets).forEach((n) => {
        h += '<label class="hb-check"><input type="checkbox" data-stitchadd="' + esc(n) + '"' + (ui.stitchAdd.has(n) ? ' checked' : '') +
          '><span><b>' + esc(n) + '</b><small>这个聊天没有这张表，勾上会补一张</small></span></label>';
      });
      h += '</div><div class="hb-actions"><button type="button" class="hb-btn" data-act="stitch"' + (ui.stitchMsg && ui.stitchMsg.busy ? ' disabled' : '') +
        '>一键拼表</button>' + resultHtml(ui.stitchMsg) + '</div>' +
        '<span class="hb-note">只改这个聊天。想让新聊天也用，拼完点「另存为预设」。换了表格模板以后要再点一次。</span>';
      // 拼过以后：另存为数据库的表格模板预设
      if (ui.stitchChat === currentChatId() && presetApi()) {
        if (ui.presetName == null) ui.presetName = defaultPresetName();
        const pm = ui.presetMsg;
        h += '<label class="hb-field"><span class="hb-flabel">预设名</span>' +
          '<input class="hb-input" type="text" data-presetname="1" value="' + esc(ui.presetName) + '" spellcheck="false" autocomplete="off"></label>' +
          '<label class="hb-check"><input type="checkbox" data-presetglobal="1"' + (ui.presetGlobal ? ' checked' : '') +
          '><span><b>同时设为全局默认</b><small>所有跟随全局的聊天都会换成这一套。</small></span></label>' +
          '<div class="hb-actions"><button type="button" class="hb-btn" data-act="presetsave"' + (pm && pm.busy ? ' disabled' : '') + '>另存为预设</button>' +
          (pm && pm.dup
            ? resultHtml({ warn: true, text: '已经有叫「' + pm.dup + '」的预设' }) +
              '<button type="button" class="hb-btn danger" data-act="presetover">覆盖</button>' +
              '<button type="button" class="hb-btn" data-act="presetrename">换个名字</button>'
            : resultHtml(pm)) + '</div>';
      }
      return h + repairHtml() + '</section>';
    };
    // 修坏档（DESIGN.md「修坏档」）：旧版另存的预设带着那个聊天的记录
    const repairHtml = () => {
      let h = '<div class="hb-field"><span class="hb-flabel">修坏档</span>' +
        '<span class="hb-note">旧版另存的预设可能带着那个聊天的记录，用它开的新聊天一开局就有旧记录。先清理预设，再到带了旧记录的聊天里清掉它们。</span></div>';
      const dp = ui.dirty;
      h += '<div class="hb-actions"><button type="button" class="hb-btn" data-act="dirtyfind"' + (dp && dp.busy ? ' disabled' : '') + '>查找带记录的预设</button>' +
        (dp && (dp.busy || dp.error) ? resultHtml(dp.busy ? { busy: true, text: '正在看每一份预设…' } : { ok: false, text: dp.error }) : '') + '</div>';
      if (dp && dp.list) {
        if (!dp.list.length) h += resultHtml(ui.cleanMsg || { ok: true, text: '没有带着记录的预设' });
        else {
          dp.list.forEach((x) => {
            h += '<label class="hb-check"><input type="checkbox" data-dirtypick="' + esc(x.name) + '"' + (ui.dirtySel.has(x.name) ? ' checked' : '') + '><span><b>' + esc(x.name) +
              '</b><small>带着 ' + x.rows + ' 行：' + esc(Object.keys(x.sheets).map((n) => n + ' ' + x.sheets[n]).join('、')) + '</small></span></label>';
          });
          h += '<div class="hb-actions"><button type="button" class="hb-btn" data-act="dirtyclean"' + (!ui.dirtySel.size || (ui.cleanMsg && ui.cleanMsg.busy) ? ' disabled' : '') +
            '>清理预设</button>' + resultHtml(ui.cleanMsg) + '</div>' +
            '<span class="hb-note">清理只留表的结构和说明，同名覆盖存回去。有的模板本来就带起始行，不是旧记录的别勾。</span>';
        }
      }
      const inh = ui.inh;
      h += '<div class="hb-actions"><button type="button" class="hb-btn" data-act="inhfind"' + (inh && inh.busy ? ' disabled' : '') + '>查找这个聊天的旧记录</button>' +
        (inh && (inh.busy || inh.error) ? resultHtml(inh.busy ? { busy: true, text: '正在比对…' } : { ok: false, text: inh.error }) : '') + '</div>';
      if (inh && inh.tables && inh.chatId === currentChatId()) {
        if (inh.noPrints) h += resultHtml({ warn: true, text: '还没有清理过预设，没有可比的旧记录：先用上面的「查找带记录的预设」清理，再来查' });
        else if (!inh.total && inh.seeds) h += resultHtml(ui.inhMsg || { warn: true, text: '旧记录还在数据库的起始数据里，没写进表：先聊一句，等数据库填完表再来查' });
        else if (!inh.total) h += resultHtml(ui.inhMsg || { ok: true, text: '这个聊天里没有从坏预设带过来的记录' });
        else {
          inh.tables.forEach((t) => {
            h += '<div class="hb-field"><span class="hb-flabel">' + esc(t.name) + ' · ' + t.rows.length + ' 行</span>' +
              t.rows.slice(0, 3).map((r) => '<span class="hb-note">· ' + esc(r.text || '（空）') + '</span>').join('') +
              (t.rows.length > 3 ? '<span class="hb-note">还有 ' + (t.rows.length - 3) + ' 行</span>' : '') + '</div>';
          });
          h += '<div class="hb-actions"><button type="button" class="hb-btn danger" data-act="inhclear"' + (ui.inhMsg && ui.inhMsg.busy ? ' disabled' : '') + '>清掉这 ' + inh.total + ' 行</button>' +
            '<button type="button" class="hb-btn" data-act="inhcancel">算了</button>' + resultHtml(ui.inhMsg) + '</div>' +
            '<span class="hb-note">当初存预设的那个聊天里别点，那里的是它自己的记录。</span>';
        }
      }
      return h;
    };

    if (ui.sub === 'prompts') return '<div class="hb-set">' + subTabs() + renderPrompts() + '</div>';
    const gLook = '<section class="hb-grp"><div class="hb-grp-hd"><h4>外观</h4><p>面板的样子、深浅色和悬浮球的大小，选了立刻生效。</p></div>' +
      '<div class="hb-field"><span class="hb-flabel">风格</span>' + seg('风格', ['场记板', '夜灯', '分镜本'], c.风格, '风格') +
      '<span class="hb-note">' + esc(STYLE_TIP[c.风格] || '') + '</span></div>' +
      '<div class="hb-field"><span class="hb-flabel">主题</span>' + seg('主题', ['跟随酒馆', '浅色', '深色'], c.主题, '主题') +
      (bangFace() ? '<span class="hb-note">BanG 卡上用 BanG 卡的样式，风格和主题在别的卡上生效。</span>' : '') + '</div>' +
      '<div class="hb-field"><span class="hb-flabel">悬浮球</span>' + seg('悬浮球', ['自动', '小', '大'], c.悬浮球, '悬浮球大小') +
      '<span class="hb-note">自动：手机上小，电脑上大。</span></div>' +
      '<div class="hb-field"><span class="hb-flabel">判定显示</span>' + seg('判定显示', ['按类型', '全公开', '全藏起'], c.判定显示, '判定显示') +
      '<span class="hb-note">' + esc(JUDGE_TIP[c.判定显示] || '') + '</span></div>' +
      '</section>';
    const gModel = '<section class="hb-grp"><div class="hb-grp-hd"><h4>状态模型</h4><p>手账本用它来记状态，和写正文的模型分开。</p></div>' +
      text('接口地址', '副API地址', c.副API地址) +
      modelField() +
      '<label class="hb-field"><span class="hb-flabel">密钥</span>' +
      '<input class="hb-input" type="password" data-key="1" value="' + esc(key) + '" placeholder="不填就用酒馆后端存的自定义接口密钥" autocomplete="off">' +
      '<span class="hb-note">只存在这台电脑的浏览器里，导出脚本不会带出去。</span></label>' +
      count('同时最多发几个请求', '同时最多发几个请求', c.同时最多发几个请求, 1, 6, '个', '公益站容易限流就调成 1；付费接口可以调高。') +
      '<div class="hb-actions"><button type="button" class="hb-btn" data-act="test"' + (test && test.busy ? ' disabled' : '') + '>测试连接</button>' +
      resultHtml(test) + '</div>' +
      '</section>' +
      '<section class="hb-grp"><div class="hb-grp-hd"><h4>发送的时候等不等它</h4><p>' + esc(MODE_TIP[c.阻塞方式] || '') + '</p></div>' +
      seg('阻塞方式', ['冲击轮', '每轮', '从不'], c.阻塞方式, '发送的时候等不等它') +
      num('最多等几秒', '阻塞上限毫秒', c.阻塞上限毫秒, 120, '到点还没回来就先写正文，回来的状态补给下一轮。') +
      check('连续重新生成时重算', '连续重新生成时重算', '同一句连续重新生成到第二次，先重算这一句的状态。关掉就沿用记好的那份，不多花请求。') +
      '</section>' +
      '<section class="hb-grp"><div class="hb-grp-hd"><h4>每一场最多记几个人</h4><p>人越多，记一轮要发的字越多。</p></div>' +
      '<div class="hb-field"><span class="hb-flabel">记状态的方式</span>' + seg('记状态的方式', ['每人一次', '一次记全场'], c.记状态的方式, '记状态的方式') +
      '<span class="hb-note">' + (c.记状态的方式 === '一次记全场'
        ? '这一场所有人放进一次调用（场面另外一次），规则和材料只发一遍：五六个人时发出去的字少一半左右。真模型盲评比每人一次略差一点，一轮也慢一些。'
        : '场面和每个人各发一次，并行跑，回来得快；每次都要把规则和材料重发一遍，人越多越费字数。') + '</span></div>' +
      count('最多记', '每场最多几人', c.每场最多几人, 1, 8, '人', '1 到 8 人。人多的时候，冲击轮更容易等到上限，没赶上的人补给下一轮。') +
      check('平行线安排', '平行线安排', '这一轮正文里没有平行线时，从名册里挑一个这一场不在、最近也没出场的人放到平行线上，给她记一份此刻状态交给正文；记过却「不在场，没注入」的人也放上去。每轮多记一个人。预设要开着平行线才写得出来。') +
      '</section>';
    const advInner = num('故事刚开头、还没有任何状态时，最多等几秒', '冷启动阻塞上限毫秒', c.冷启动阻塞上限毫秒, 20) +
        '<label class="hb-field"><span class="hb-flabel">附加请求体（YAML，原样并进请求）</span>' +
        '<textarea class="hb-input" data-field="附加请求体" spellcheck="false">' + esc(c.附加请求体) + '</textarea>' +
        '<span class="hb-note">豆包系要保留两行 thinking: 和缩进两格的 type: disabled 关掉思考，不然一次要等好几分钟。</span></label>' +
        '<label class="hb-field"><span class="hb-flabel">排除主体参数</span>' +
        '<textarea class="hb-input" data-field="排除主体参数" spellcheck="false" placeholder="比如：temperature, max_tokens">' + esc(c.排除主体参数) + '</textarea>' +
        '<span class="hb-note">要从请求里删掉的参数名，逗号或换行隔开。换的模型不收某些参数（temperature、max_tokens、response_format 这类）、一调就报错时用。</span></label>' +
        check('用JSON结构约束', '让状态模型按固定结构回答', '接口不支持 json_schema 时关掉。') +
        check('注入读法说明', '告诉正文模型怎么读当前状态', c.导演稿 === '关'
          ? '跟每一轮的状态放在一起，贴在玩家消息前面。你的预设里已经有同样的说明时可以关掉。'
          : '开着导演稿时，状态和导演稿都跟在玩家这一轮的消息里，这份说明（连同导演稿的读法）贴在玩家消息前面。你的预设里已经有同样的说明时可以关掉。') +
        '<label class="hb-field"><span class="hb-flabel">标签排除</span>' +
        '<input class="hb-input" type="text" data-field="标签排除" value="' + esc(c.标签排除) + '" spellcheck="false" autocomplete="off">' +
        '<span class="hb-note">正文里这些标签包着的内容不交给状态模型和写稿模型，比如绘图插件的关键词。标签名用顿号、逗号或空格隔开。</span></label>' +
        check('读数据库', '读数据库的纪要表和重要角色表', '只读，不写。') +
        check('按场景选设定', '按场景选设定', '正文生成时，按这一场在场的人和地点，从世界书里挑相关的设定条目一起带上（原文，不改写），最多 6 条。条目自己的关键词照样起作用。') +
        check('调试日志', '在浏览器控制台多打一些日志') +
        '<div class="hb-actions"><button type="button" class="hb-btn danger" data-act="wipe">清空这个聊天的状态</button></div>';
    // 四个页签，一次只看一页（DESIGN.md「票根」「三套风格」）
    const TABS = ['此聊天', '模板', '模型', '高级'];
    const tab = TABS.indexOf(ui.setTab) === -1 ? '此聊天' : ui.setTab;
    const pane = tab === '此聊天' ? chatGroup() + gLook : tab === '模板' ? tplGroup() + stitchGroup()
      : tab === '模型' ? gModel + directorGroup() : '<section class="hb-grp"><div class="hb-grp-hd"><h4>高级</h4></div><div class="hb-adv">' + advInner + '</div></section>';
    return '<div class="hb-set">' + subTabs() + '<div class="hb-tabs" role="tablist">' + TABS.map((t) => '<button type="button" role="tab" data-act="settab" data-val="' + t + '" aria-selected="' +
      (t === tab ? 'true' : 'false') + '">' + t + '</button>').join('') + '</div><div class="hb-tabpane" data-tab="' + tab + '">' + pane + '</div></div>';
  }

  // ---------- 模型列表 ----------
  // 地址或密钥变了才重新拉；拉不到就让玩家手填
  function ensureModelsLoaded(c) {
    const url = String(c.副API地址 || '').trim();
    const sig = url + '\n' + getApiKey();
    if (ui.models && ui.models.sig === sig) return;
    ui.models = { sig, loading: true };
    listSideModels(c)
      .then((r) => { if (ui.models && ui.models.sig === sig) ui.models = { sig, list: r.models || null, error: r.error || null }; })
      .catch((e) => { if (ui.models && ui.models.sig === sig) ui.models = { sig, error: String((e && e.message) || e) }; })
      .finally(() => renderPanel());
  }

  // 导演稿用的模型列表：接口、密钥和状态模型不一样时单独拉
  function ensureDirectorModelsLoaded(conn) {
    const sig = String(conn.副API地址 || '').trim() + '\n' + (conn._key || '');
    if (ui.dmodels && ui.dmodels.sig === sig) return;
    ui.dmodels = { sig, loading: true };
    listSideModels(conn)
      .then((r) => { if (ui.dmodels && ui.dmodels.sig === sig) ui.dmodels = { sig, list: r.models || null, error: r.error || null }; })
      .catch((e) => { if (ui.dmodels && ui.dmodels.sig === sig) ui.dmodels = { sig, error: String((e && e.message) || e) }; })
      .finally(() => renderPanel());
  }

  // ---------- 一键拼表 ----------
  // 表格模板每次进设置页都重读一遍（玩家可能刚在数据库里换过模板）；换了聊天，勾选和结果提示一起清掉
  function ensureStitchLoaded() {
    const chatId = currentChatId();
    if (ui.stitch && ui.stitch.chatId === chatId) return;
    if (ui.stitchLoading) return;
    if (ui.stitch && ui.stitch.chatId !== chatId) {
      ui.stitchSel = {};
      ui.stitchAdd = new Set();
      ui.ownSel = {};
      ui.stitchMsg = null;
    }
    ui.stitchLoading = true;
    readStitchTemplate()
      .then((r) => { ui.stitch = Object.assign({ chatId }, r); })
      .catch(() => { ui.stitch = { chatId, error: '读不到这个聊天的表格模板' }; })
      .finally(() => { ui.stitchLoading = false; renderPanel(); });
  }

  async function runDirtyFind() {
    ui.dirty = { busy: true };
    ui.cleanMsg = null;
    renderPanel();
    let r;
    try { r = await dirtyPresets(); } catch (e) { r = { error: String((e && e.message) || e) }; }
    ui.dirty = r;
    ui.dirtySel = new Set();
    renderPanel();
  }
  async function runDirtyClean() {
    if (!ui.dirtySel.size || (ui.cleanMsg && ui.cleanMsg.busy)) return;
    ui.cleanMsg = { busy: true, text: '正在清理…' };
    renderPanel();
    let r;
    try { r = await cleanPresets(Array.from(ui.dirtySel)); } catch (e) { r = { error: String((e && e.message) || e) }; }
    let msg;
    if (r.error) msg = { ok: false, text: '没清成：' + r.error };
    else if (r.failed.length) msg = { warn: true, text: '清了 ' + r.done.length + ' 份；没清成：' + r.failed.map((f) => '「' + f.name + '」' + f.why).join('、') };
    else msg = { ok: true, text: '清好了 ' + r.done.length + ' 份，拿掉 ' + r.dropped + ' 行' + (r.regloballed ? '；全局默认已换成清过的「' + r.regloballed + '」' : '') };
    let left;
    try { left = await dirtyPresets(); } catch (e) { left = null; }
    if (left && !left.error) ui.dirty = left;
    ui.dirtySel = new Set();
    ui.cleanMsg = msg;
    // 下面「查找这个聊天的旧记录」已经查过的（多半写着「还没有清理过预设」），清完顺手重查，免得留着旧结果
    if (ui.inh && !ui.inh.busy && r.done && r.done.length) {
      const chatId = currentChatId();
      let f;
      try { f = await inheritedRows(); } catch (e) { f = null; }
      if (f && !f.error && chatId === currentChatId()) { ui.inh = Object.assign({ chatId }, f); ui.inhMsg = null; }
    }
    renderPanel();
  }
  async function runInhFind() {
    const chatId = currentChatId();
    ui.inh = { busy: true, chatId };
    ui.inhMsg = null;
    renderPanel();
    let r;
    try { r = await inheritedRows(); } catch (e) { r = { error: String((e && e.message) || e) }; }
    ui.inh = Object.assign({ chatId }, r);
    renderPanel();
  }
  async function runInhClear() {
    const inh = ui.inh;
    if (!inh || !inh.total || inh.chatId !== currentChatId() || (ui.inhMsg && ui.inhMsg.busy)) return;
    ui.inhMsg = { busy: true, text: '正在删…' };
    renderPanel();
    let r;
    try { r = await clearInherited(inh); } catch (e) { r = { error: String((e && e.message) || e) }; }
    const msg = r.error ? { ok: false, text: '没删成：' + r.error }
      : r.left ? { warn: true, text: '删了 ' + r.deleted + ' 行，还有 ' + r.left + ' 行没删掉，再点一次试试' }
        : { ok: true, text: '删了 ' + r.deleted + ' 行' };
    let again;
    try { again = await inheritedRows(); } catch (e) { again = null; }
    if (again && !again.error) ui.inh = Object.assign({ chatId: inh.chatId }, again);
    ui.inhMsg = msg;
    renderPanel();
  }

  async function runSavePreset(overwrite) {
    if (ui.presetMsg && ui.presetMsg.busy) return;
    const inp = ui.body && ui.body.querySelector('[data-presetname]');
    if (inp) ui.presetName = inp.value;
    ui.presetMsg = { busy: true, text: '正在存预设…' };
    renderPanel();
    let r;
    try { r = await savePreset(ui.presetName, ui.presetGlobal, overwrite); } catch (e) { r = { error: String((e && e.message) || e) }; }
    if (r.dup) ui.presetMsg = { dup: r.dup };
    else if (r.error) ui.presetMsg = { ok: false, text: '没存上：' + r.error };
    else if (r.warning) ui.presetMsg = { warn: true, text: r.warning };
    else ui.presetMsg = { ok: true, text: '存好了：「' + r.name + '」' + (r.global ? '，已设为全局默认' : '。在数据库「管理表格模板预设」里能看到，那一页开着的话关掉重开一次') };
    renderPanel();
  }

  async function runStitch() {
    const st = ui.stitch;
    if (!st || st.error || (ui.stitchMsg && ui.stitchMsg.busy)) return;
    const want = {};
    const mine = st.sheets.filter((s) => !isOwnSheet(s.name));
    const any = mine.some((s) => s.stitched);
    mine.forEach((s) => {
      want[s.name] = Object.prototype.hasOwnProperty.call(ui.stitchSel, s.name) ? ui.stitchSel[s.name] : stitchByDefault(s, any);
    });
    // 缺的专属表默认要加，玩家取消勾选的不加
    const add = Array.from(ui.stitchAdd).concat(ownMissing(st.sheets).filter((n) => !Object.prototype.hasOwnProperty.call(ui.ownSel, n) || ui.ownSel[n]));
    // 已经有的专属表：玩家动过勾选的才管（接着填 / 不再填）
    const fill = {};
    st.sheets.filter((s) => isOwnSheet(s.name) && Object.prototype.hasOwnProperty.call(ui.ownSel, s.name)).forEach((s) => { fill[s.name] = ui.ownSel[s.name]; });
    ui.stitchMsg = { busy: true, text: '正在拼表…' };
    renderPanel();
    let r = null;
    try { r = await stitchTables(want, add, fill); } catch (e) { r = { error: String((e && e.message) || e) }; }
    if (r.error) ui.stitchMsg = { ok: false, text: '没拼上：' + r.error };
    else if (r.skipped) ui.stitchMsg = null;
    else if (r.unchanged) ui.stitchMsg = { ok: true, text: '本来就拼好了，没有要改的' };
    else {
      const parts = [];
      const addedOwn = r.added.filter(isOwnSheet);
      const addedStd = r.added.filter((n) => !isOwnSheet(n));
      if (addedOwn.length) parts.push('加了 ' + addedOwn.length + ' 张专属表');
      if (addedStd.length) parts.push('补了' + addedStd.join('、'));
      if (r.changed) parts.push('拼上 ' + r.changed + ' 张');
      if (r.removed) parts.push('拿掉 ' + r.removed + ' 张');
      if (r.refreshed) parts.push('更新了 ' + r.refreshed + ' 张专属表的说明');
      if (r.muted) parts.push(r.muted + ' 张专属表不再进正文提示词');
      if (r.paused) parts.push(r.paused + ' 张专属表不再填');
      if (r.resumed) parts.push(r.resumed + ' 张专属表接着填');
      ui.stitchMsg = { ok: true, text: '拼好了：' + parts.join('，') };
    }
    // 写成了（或本来就是这样）才清掉勾选；没拼上时留着，玩家直接再点一次就行
    if (!r.error && !r.skipped) { ui.stitchChat = currentChatId(); ui.presetMsg = null; }
    if (!r.error) {
      ui.stitchSel = {};
      ui.stitchAdd = new Set();
      ui.ownSel = {};
    }
    // 重读一遍，标签换成「已经拼上了」。读好了再重画：列表不先收成「正在读」，页面不往上跳，结果那行还在原处
    const chatId = currentChatId();
    try { ui.stitch = Object.assign({ chatId }, await readStitchTemplate()); } catch (e) { ui.stitch = null; }
    renderPanel();
  }


  // ---------- 性格模板 ----------
  // 勾选列表。筛选框打字时只换这一块，不重画整个面板（重画会把输入框的光标冲掉）
  function tplListHtml(name, sel, tpl) {
