  // 重绘前记下焦点在哪个控件上：按它身上的 data- 属性拼一个选择器，重绘后照着找回来
  const FOCUS_ATTRS = ['data-act', 'data-name', 'data-field', 'data-set', 'data-val', 'data-tplpick', 'data-tpl', 'data-tplfilter', 'data-pnote', 'data-pperiod', 'data-tplpeople', 'data-plainfilter', 'data-key', 'data-stitch', 'data-stitchadd', 'data-modelpick', 'data-ownadd', 'data-prompt', 'data-presetname', 'data-presetglobal', 'data-dirtypick', 'data-plain'];
  function focusSelector(el) {
    const esc2 = (v) => (TOP.CSS && TOP.CSS.escape ? TOP.CSS.escape(v) : String(v).replace(/["\\]/g, '\\$&'));
    const parts = FOCUS_ATTRS.filter((a) => el.hasAttribute(a)).map((a) => '[' + a + '="' + esc2(el.getAttribute(a)) + '"]');
    return parts.length ? el.tagName.toLowerCase() + parts.join('') : '';
  }

  // ---------- 外观 ----------
  // 酒馆现在是不是深色主题：看酒馆的正文颜色（--SmartThemeBodyColor），字是浅色就当是深色主题；读不到就看页面实际的字色
  function parseRgb(s) {
    const t = String(s || '').trim();
    let m = t.match(/^#([0-9a-f]{3}|[0-9a-f]{6})$/i);
    if (m) {
      const h = m[1].length === 3 ? m[1].split('').map((x) => x + x).join('') : m[1];
      return [0, 2, 4].map((i) => parseInt(h.slice(i, i + 2), 16));
    }
    m = t.match(/rgba?\(\s*([\d.]+)[\s,]+([\d.]+)[\s,]+([\d.]+)/i);
    return m ? [Number(m[1]), Number(m[2]), Number(m[3])] : null;
  }

  function tavernIsDark() {
    try {
      const cs = TOP.getComputedStyle(TOP.document.body);
      const rgb = parseRgb(cs.getPropertyValue('--SmartThemeBodyColor')) || parseRgb(cs.color);
      if (!rgb) return false;
      return (0.2126 * rgb[0] + 0.7152 * rgb[1] + 0.0722 * rgb[2]) / 255 > 0.5;
    } catch (e) {
      return false;
    }
  }

  const FAB_SIZE = { 自动: 'auto', 小: 'small', 大: 'big' };
  const STYLE_SKIN = { 场记板: 'slate', 夜灯: 'lamp', 分镜本: 'film' };
  const STYLE_TIP = { 场记板: '浅色毛玻璃、紫色，深浅色都有。', 夜灯: '深蓝夜色、暖黄灯光；浅色主题时换成米白。', 分镜本: '白纸黑框、红色记号笔，只有浅色。' };

  // 主题和悬浮球大小挂在两个根节点上（样式见 15_css.js）。每次画都看一眼，跟随酒馆时酒馆换了主题也能跟上
  function applyAppearance() {
    const c = cfg();
    const bang = bangSkin(c);
    ui.skin = bang ? 'bang' : STYLE_SKIN[c.风格] || 'slate';
    const theme = !bang && ui.skin !== 'film' && (c.主题 === '深色' || (c.主题 === '跟随酒馆' && tavernIsDark())) ? 'dark' : 'light';
    const face = bang ? bangFace() : null;
    const accent = face && HEX.test(String(face.accent || '')) ? face.accent : BANG_ACCENT;
    [ui.fab, ui.panel].forEach((el) => {
      if (!el) return;
      if (el.dataset.theme !== theme) el.dataset.theme = theme;
      if (el.dataset.skin !== ui.skin) el.dataset.skin = ui.skin;
      if (bang) el.style.setProperty('--bang-accent', accent); else el.style.removeProperty('--bang-accent');
    });
    if (bang) loadBangFonts();
    const size = FAB_SIZE[c.悬浮球] || 'auto';
    if (ui.fab && ui.fab.dataset.size !== size) ui.fab.dataset.size = size;
  }

  // ---------- 面板 ----------
  function renderPanel() {
    applyAppearance();
    if (!ui.panel || !ui.open) return;
    // 手指或鼠标正按在面板上：重画会把按着的那个元素换掉，这一下点击、左右滑就丢了。松开以后补画（见 bindPress）
    if (ui.pressing) { ui.renderPending = true; return; }
    const isSet = ui.view === 'settings';
    const running = !!newestRun();
    const hd = ui.panel.querySelector('.hb-hd');
    hd.querySelector('[data-act="rerun"]').disabled = running;
    const gear = hd.querySelector('[data-act="settings"]');
    gear.setAttribute('aria-pressed', isSet ? 'true' : 'false');
    gear.title = isSet ? '回到此刻' : '设置';
    gear.setAttribute('aria-label', gear.title);
    // 设置页正在输入时不重绘，免得把光标和没存的字冲掉；此刻页「加上」那一栏也一样
    const active = TOP.document.activeElement;
    if ((isSet || (active && active.dataset && active.dataset.addname != null)) && active && ui.body.contains(active) && /^(INPUT|TEXTAREA)$/.test(active.tagName) &&
      !/^(checkbox|radio)$/.test(active.type)) return;
    // 同一页重绘时保留滚动位置和键盘焦点；换页就从头开始
    const viewKey = ui.view + (isSet ? ':' + ui.sub : '');
    const y = ui.rendered === viewKey ? ui.body.scrollTop : 0;
    const refocus = ui.rendered === viewKey && active && ui.body.contains(active) ? focusSelector(active) : '';
    ui.body.innerHTML = isSet ? renderSettings() : renderNow();
    const heads = ui.panel.querySelector('.hb-heads');
    if (heads) {
      const showHeads = !isSet;
      heads.hidden = !showHeads;
      const old = heads.querySelector('.hb-heads-list');
      const x = old ? old.scrollLeft : 0;
      const hh = showHeads ? headsHtml(latestState(loadStore(), null), cfg()) : '';
      heads.hidden = !hh;
      heads.innerHTML = hh;
      const list = heads.querySelector('.hb-heads-list');
      if (list) { list.scrollLeft = x; list.addEventListener('scroll', () => fadeHeads(list), { passive: true }); fadeHeads(list); }
    }
    ui.body.scrollTop = !isSet && ui.jumpTarget && Date.now() < ui.jumpTarget.until ? ui.jumpTarget.top : y;
    if (refocus) {
      const el = ui.body.querySelector(refocus);
      if (el) { try { el.focus({ preventScroll: true }); } catch (e) { /* ignore */ } }
    }
    ui.rendered = viewKey;
    updatePerch();
  }

  function renderFab() {
    applyAppearance();
    const s = statusOf();
    ui.dot = s.cls;
    if (ui.fab) {
      ui.fab.classList.toggle('hb-busy', s.cls === 'busy');
      ['fresh', 'stale', 'error'].forEach((k) => ui.fab.classList.toggle('hb-' + k, s.cls === k));
      ui.fab.title = s.text;
    }
  }

  function refreshUi() { renderFab(); renderPanel(); }

  // 限流冷却中：每秒刷一次倒数。设置页不跟着刷，免得打断正在点的东西
  function startCoolTick() {
    if (ui.coolTick || reqCoolLeft() <= 0) return;
    ui.coolTick = setInterval(() => {
      if (reqCoolLeft() <= 0) { clearInterval(ui.coolTick); ui.coolTick = null; }
      renderFab();
      if (ui.view !== 'settings') renderPanel();
    }, 1000);
  }

  function setOpen(open) {
    ui.open = !!open;
    if (!ui.panel) return;
    ui.panel.classList.toggle('hb-open', ui.open);
    ui.fab.setAttribute('aria-expanded', ui.open ? 'true' : 'false');
    if (ui.open) {
      renderPanel();
      if (!ui.panelDrag.restore()) placePanelNearFab();
    }
    renderFab();
    writeUiPref();
  }

  // 酒馆顶上那一排导航图标的下沿。立绘按它算「离顶部够不够 110px」，不然帽子会压在导航图标上。
  function ceilingY() {
    let y = 0;
    ['top-bar', 'top-settings-holder'].forEach((id) => {
      const el = TOP.document.getElementById(id);
      if (!el) return;
      const r = el.getBoundingClientRect();
      if (r.height > 0 && r.top < 80) y = Math.max(y, r.bottom);
    });
    return y;
  }

  // 立绘趴在面板上沿外面：面板顶边离顶部不到 110px 时整张藏起来，不压缩
  function updatePerch() {
    if (!ui.panel || !ui.open) return;
    const top = ui.panel.getBoundingClientRect().top;
    ui.panel.classList.toggle('hb-no-perch', top - ceilingY() < PERCH_H);
  }

  // 面板没被拖过时，以悬浮球为锚点开：上面地方够就往上长（top 定在球的上沿，再整体上移自身高度），
  // 不够就往下长。内容多了自己撑开，不会被屏幕边截掉。不用 bottom，原因见样式表里悬浮球那一段。
  // 往上长的时候，如果空间够，顶上给立绘留出 110px。
  function placePanelNearFab() {
    const win = TOP;
    const s = ui.panel.style;
    if (win.innerWidth <= 600) { s.left = s.top = s.right = s.bottom = s.maxHeight = s.transform = ''; updatePerch(); return; }
    const f = ui.fab.getBoundingClientRect();
    const above = f.top - 12, below = win.innerHeight - f.bottom - 12;
    const cap = win.innerHeight * 0.78;
    s.bottom = 'auto';
    if (above >= 260 || above >= below) {
      const perchRoom = above - ceilingY() - (PERCH_H + 2);
      const room = perchRoom >= 320 ? perchRoom : above;
      s.top = (f.top - 8) + 'px';
      s.transform = 'translateY(-100%)';
      s.maxHeight = Math.max(160, Math.min(cap, room)) + 'px';
    } else {
      s.top = (f.bottom + 8) + 'px';
      s.transform = 'none';
      s.maxHeight = Math.max(160, Math.min(cap, below)) + 'px';
    }
    const w = ui.panel.offsetWidth || 340;
    s.right = 'auto';
    s.left = Math.max(4, Math.min(f.right - w, win.innerWidth - w - 4)) + 'px';
    updatePerch();
  }

  // ---------- 设置的读写 ----------
  function saveSetting(name, value) {
    try { insertOrAssignVariables({ [name]: value }, { type: 'script' }); } catch (e) { warn('设置没存上：', e); return; }
    backupSettings();
    if (name === '注入读法说明' || name === '每场最多几人' || name === '自动写入世界书') reinject();
    // 手动模式靠「手账本-名字」条目改关系阶段：一切换就把条目写出来（切回自动时收掉没模板的人的条目）
    if (name === '关系阶段调整') syncBook();
    if (name === '性格模板世界书') {
      _tpl = null;
      loadTemplates(true).then(() => refreshUi()).catch(() => {});
    }
    if (name === '主题' || name === '悬浮球' || name === '风格') applyAppearance();
    renderFab();
    if (/^导演稿/.test(name)) renderPanel();
  }

  function onFieldChange(el) {
    if (el.dataset.key === 'director') {
      setApiKey(el.value, DIRECTOR_KEY_STORE);
      renderPanel();
      return;
    }
    if (el.dataset.key) {
      setApiKey(el.value);
      clearIdentifyBlock();                 // 换了密钥：因为连不上停下的自动识别重新来
      ui.idMsg = null;
      renderFab();
      renderPanel();
      return;
    }
    const name = el.dataset.field;
    if (!name) return;
    let v;
    if (el.type === 'checkbox') v = el.checked;
    else if (el.dataset.sec) {
      const n = Number(el.value);
      if (!isFinite(n) || n <= 0) { el.value = cfg()[name] / 1000; return; }
      v = Math.round(n * 1000);
    } else if (el.dataset.int) {
      const n = Math.round(Number(el.value));
      const lo = el.min !== '' && isFinite(Number(el.min)) ? Number(el.min) : 1;
      if (el.value === '' || !isFinite(n) || n < lo) { el.value = cfg()[name]; return; }
      v = n;
    } else v = el.value;
    saveSetting(name, v);
    // 数字被 cfg() 夹过范围的话，把夹过的值回显出来
    if (el.dataset.sec) el.value = cfg()[name] / 1000;
    if (el.dataset.int) el.value = cfg()[name];
  }

  // kind：'side' 状态模型那一组的按钮，'director' 导演稿那一组的按钮。各测各的，结果也写在各自那一组
  async function runTest(kind) {
    const slot = kind === 'director' ? 'dtestMsg' : 'testMsg';
    const say = (msg) => { ui[slot] = msg; renderPanel(); };
    const cool = reqCoolLeft();
    if (cool > 0) {                          // 冷却期里不发：发了也是 429，还会把冷却拉长
      say({ ok: false, text: '限流中，' + Math.ceil(cool / 1000) + ' 秒后再试' });
      return;
    }
    const c = cfg();
    const targets = testTargets(c, kind);
    // 测通的用时（同一个模型测几种回答结构，取最慢的一次）；cut：回答写到一半被截断过
    let passed = 0;
    let cut = false;
    for (const t of targets) {
      say({ busy: true, text: '正在连接…' });
      const shape = { system: TEST_SYSTEM, user: '连接测试。', schema: t.schema, schemaName: t.name,
        maxTokens: t.maxTokens, hardTimeout: t.hardTimeout, label: '测试连接·' + t.who };
      const t0 = Date.now();
      try {
        // 只看接口收不收、模型回不回话；回的是不是 JSON 不管（排除了 response_format 的模型本来就不照结构回）
        const res = await callSide(shape.system, shape.user, shape.schema, shape.schemaName,
          { cfg: t.conn, maxTokens: shape.maxTokens, hardTimeout: shape.hardTimeout, raw: true, probe: true, label: shape.label });
        passed = Math.max(passed, res.ms);
        if (res.cut) cut = true;
        continue;
      } catch (e) {
        // 思考把字数用光、一个字也没写出来：接口收下了，和写了一半被截断一样算连上
        if (e && e.truncated) { cut = true; passed = Math.max(passed, Date.now() - t0); continue; }
        if (!isParamReject(e)) { say({ ok: false, text: '连接失败：' + friendlyError(e.message) }); return; }
      }
      say({ busy: true, text: '接口拒收了这次请求，正在试是哪个参数…' });
      const p = await probeParams(t.conn, shape);
      if (p.error) { say({ ok: false, text: '连接失败：' + friendlyError(p.error.message) }); return; }
      if (p.notParams) {
        say({ ok: false, text: '连接失败：接口拒收了请求（400），手账本加的参数全去掉也不行，问题不在参数。接口的原话在酒馆的后台窗口里' });
        return;
      }
      // 试出来的参数名并进这个模型用的排除主体参数（写稿模型写进导演稿那一栏；原来沿用状态模型的，连同沿用的一起写进去）
      const cur = String(t.conn.排除主体参数 || '');
      const keys = excludeKeys(cur);
      p.culprits.forEach((k) => { if (keys.indexOf(k) === -1) keys.push(k); });
      saveSetting(t.field, /^\s*-/.test(cur) ? keys.map((k) => '- ' + k).join('\n') : keys.join(', '));
      say({ warn: true, text: '不收 ' + p.culprits.join('、') + '：已经写进' + t.where + '的「排除主体参数」，再点一次测试连接确认' });
      return;
    }
    if (cut) {
      say({ warn: true, text: '连上了，但回答写到一半被截断：最多输出字数不够，会思考的模型思考也算字数。记状态时会加大字数重发一次，更慢也更费；换不思考的模型，或者在附加请求体里关掉思考' });
    } else {
      say({ ok: true, text: '连上了：' + (passed / 1000).toFixed(1) + ' 秒回话' });
    }
    if (kind === 'director') return;
    // 状态模型连上了：之前没识别成的人接着识别
    ui.idMsg = null;
    retryIdentify().catch(() => {}).finally(() => renderPanel());
  }

  // 测试连接照真实请求的样子发：同样的回答结构、同样的最多输出字数。
  // 只发一个小请求的话，接口不收大的 max_tokens 或回答结构时照样连得上，真记状态、写稿时才被拒
  const TEST_SYSTEM = '这是连接测试。只返回符合 schema 的 JSON，每一格填最短的值：字符串填空字符串，数组放一项或不放，数字填 0，布尔填 false。';

  // 状态模型真实会发的回答结构：冷启动（第一轮），加上「记状态方式」对应的那种——每人一次是单个人，
  // 一次记全场是定好人数、名字只能从名单里挑的一组人（名单用占位名，人数按上限）。
  // 写稿模型只有导演稿一种；和状态模型同一个接口、同一个模型也要单独测：回答结构和最多输出字数都不一样
  function testTargets(c, kind) {
    if (kind === 'director') {
      return [{ who: '写稿模型', conn: directorConn(c), field: '导演稿排除主体参数', where: '「导演稿」那一组', schema: DIRECTOR_SCHEMA,
        name: 'handbook_director', maxTokens: 16000, hardTimeout: 90000 }];
    }
    const max = c.每场最多几人;
    const rec = { who: '状态模型', conn: c, field: '排除主体参数', where: '「高级」里', hardTimeout: 60000 };
    const names = Array.from({ length: max }, (_, i) => '测试' + (i + 1));
    return [
      Object.assign({ schema: schemaFor('cold', max), name: 'handbook_cold', maxTokens: 700 * max }, rec),
      c.记状态的方式 === '一次记全场'
        ? Object.assign({ schema: schemaFor('group', max, names), name: 'handbook_group', maxTokens: 900 * max + 600 }, rec)
        : Object.assign({ schema: schemaFor('person', max), name: 'handbook_person', maxTokens: 700 }, rec),
    ];
  }

  // 没填密钥时接口回 401：直接说没填，比「密钥无效」好懂
  function blockedWhy(b) {
    if (!getApiKey() && /401|Unauthorized|authentication|invalid.{0,12}(key|token)/i.test(b.why)) return '还没填密钥';
    return friendlyError(b.why);
  }

  async function runIdRetry() {
    if (ui.idMsg && ui.idMsg.busy) return;
    ui.idMsg = { busy: true, text: '正在识别…' };
    renderPanel();
    let r = null;
    try { r = await retryIdentify(); } catch (e) { r = null; }
    const blocked = identifyBlocked();
    if (blocked) ui.idMsg = { ok: false, text: '没连上状态模型：' + blockedWhy(blocked) };
    else if (!r || !r.asked) ui.idMsg = { ok: true, text: '没有要识别的人' };
    else if (r.failed) ui.idMsg = { ok: false, text: '识别了 ' + r.done + ' 个人，' + r.failed + ' 个没识别成' };
    else ui.idMsg = { ok: true, text: '识别完了：' + r.done + ' 个人' };
    renderPanel();
  }

  async function wipeChat() {
    const ctx = getCtx();
    let ok = false;
    try {
      if (ctx && typeof ctx.callGenericPopup === 'function') {
        ok = await ctx.callGenericPopup('清空这个聊天里手账本记过的所有状态，删掉这个聊天世界书里的「手账本-」条目？<br>性格、不记的人、补充留着。下一次发送会重新开始记。',
          (ctx.POPUP_TYPE || {}).CONFIRM, '', { okButton: '清空', cancelButton: '算了' });
      } else {
        ok = TOP.confirm('清空这个聊天里手账本记过的所有状态，删掉这个聊天世界书里的「手账本-」条目？性格、不记的人、补充留着。');
      }
    } catch (e) { ok = false; }
    if (!ok) return;
    let r = null;
    try { r = await resetChat(); } catch (e) { warn('清空没做完：', e); }
    toast('success', '这个聊天的状态清空了' + (r && r.removed ? '，删掉了 ' + r.removed + ' 条「手账本-」条目' : ''));
    refreshUi();
  }

  // ---------- 搭起来 / 拆掉 ----------
  function buildUi() {
    const doc = TOP.document;
    if (!doc || !doc.body) return;
    destroyUi();
    injectCss();

    const fab = doc.createElement('button');
    fab.id = 'hb-fab';
    fab.type = 'button';
    fab.setAttribute('aria-label', '打开悬浮窗');
    fab.setAttribute('aria-haspopup', 'dialog');
    fab.setAttribute('aria-controls', 'hb-panel');
    fab.innerHTML = '<img class="hb-av" alt="" draggable="false" src="' + ASSET_AVATAR + '">' +
      '<span class="hb-pick" aria-hidden="true"><b>HB</b><small>NOTE</small></span>' + RING_SVG + '<span class="hb-dot"></span>';
    doc.body.appendChild(fab);

    const panel = doc.createElement('div');
    panel.id = 'hb-panel';
    panel.setAttribute('role', 'dialog');
    panel.setAttribute('aria-label', DISPLAY);
    panel.innerHTML =
      '<img class="hb-perch" alt="" draggable="false" src="' + ASSET_PERCH + '">' +
      '<div class="hb-shell"><div class="hb-slate" aria-hidden="true"></div>' +
      '<div class="hb-hd">' +
      '<span class="hb-hd-av" aria-hidden="true"><img alt="" draggable="false" src="' + ASSET_AVATAR + '"></span>' +
      '<div class="hb-title"><span class="hb-title-en">NOTEBOOK</span>' + esc(DISPLAY) + '</div>' +
      '<button type="button" class="hb-rerun" data-act="rerun" title="把最新这一楼重新记一遍">' + icon('refresh', 13) + '重算</button>' +
      '<button type="button" class="hb-ibtn" data-act="settings" title="设置" aria-label="设置" aria-pressed="false">' + icon('gear', 16) + '</button>' +
      '<button type="button" class="hb-ibtn" data-act="close" title="收起" aria-label="收起">' + icon('close', 16) + '</button>' +
      '</div><div class="hb-heads" role="group" aria-label="这一楼的人"></div><div class="hb-body"></div></div>';
    doc.body.appendChild(panel);

    ui.fab = fab;
    ui.panel = panel;
    ui.body = panel.querySelector('.hb-body');

    const fabDrag = makeDraggable(fab, fab, POS_FAB, { dragClass: 'hb-dragging' });
    fabDrag.restore();
    ui.panelDrag = makeDraggable(panel.querySelector('.hb-hd'), panel, POS_PANEL, { skipNarrow: true, fit: true, onPlace: updatePerch });

    const panelDragged = () => { try { return !!TOP.localStorage.getItem(POS_PANEL); } catch (e) { return false; } };
    fab.addEventListener('click', () => {
      if (fabDrag.consumeDrag()) {
        // 拖了悬浮球：面板没被单独拖过的话，跟着悬浮球走
        if (ui.open && !panelDragged()) placePanelNearFab();
        return;
      }
      setOpen(!ui.open);
    });
    const onWinResize = () => {
      if (ui.open && !panelDragged()) placePanelNearFab();
      else updatePerch();
    };
    TOP.addEventListener('resize', onWinResize);
    ui.offs.push(() => TOP.removeEventListener('resize', onWinResize));

    // 按着面板的时候不重画（renderPanel 开头），松开再补：手指看 touchstart / touchend，鼠标和触控笔看 pointerdown / pointerup。
    // 补画晚 300ms，让这一下的 click 先到；最多按 2.5 秒，过了照常画
    const press = () => {
      ui.pressing = true;
      clearTimeout(ui.pressTimer);
      ui.pressTimer = setTimeout(release, 2500);
    };
    const release = () => {
      if (!ui.pressing) return;
      ui.pressing = false;
      clearTimeout(ui.pressTimer);
      if (ui.renderPending) {
        ui.renderPending = false;
        setTimeout(() => { if (!ui.pressing) renderPanel(); else ui.renderPending = true; }, 300);
      }
    };
    panel.addEventListener('touchstart', press, { passive: true, capture: true });
    panel.addEventListener('touchend', (e) => { if (!e.touches || !e.touches.length) release(); }, { passive: true, capture: true });
    panel.addEventListener('touchcancel', (e) => { if (!e.touches || !e.touches.length) release(); }, { passive: true, capture: true });
    panel.addEventListener('pointerdown', (e) => { if (e.pointerType !== 'touch') press(); }, true);
    panel.addEventListener('pointerup', (e) => { if (e.pointerType !== 'touch') release(); }, true);
    panel.addEventListener('pointercancel', (e) => { if (e.pointerType !== 'touch') release(); }, true);

    // 鼠标滚轮在人头那一排上：竖着滚换成横着滚；这一排滚不动了就不拦，面板照常滚
    panel.addEventListener('wheel', (e) => {
      const list = e.target.closest && e.target.closest('.hb-heads-list');
      if (!list || !e.deltaY || Math.abs(e.deltaX) > Math.abs(e.deltaY)) return;
      const max = list.scrollWidth - list.clientWidth;
      if (max <= 1 || (e.deltaY < 0 && list.scrollLeft <= 0) || (e.deltaY > 0 && list.scrollLeft >= max - 1)) return;
      e.preventDefault();
      list.scrollLeft += e.deltaY;
    }, { passive: false });
    const onHeadsResize = () => fadeHeads(panel.querySelector('.hb-heads-list'));
    TOP.addEventListener('resize', onHeadsResize);
    ui.offs.push(() => TOP.removeEventListener('resize', onHeadsResize));

    // 人物卡左滑（手指、触控笔）：露出单独重算、删掉那一截；右滑收回。
    // 手指走 touch 事件：浏览器把这一划当成滚动或自己的手势接管时，pointer 事件会被取消（pointercancel，iPhone 上常见），
    // touchend 照样收得到；触控笔走 pointer 事件。卡片上另设 touch-action: pan-y（15_css.js），左右划不归浏览器
    let swipe = null;
    const swipeStart = (target, x, y) => {
      const el = target && target.nodeType === 3 ? target.parentNode : target;
      const tk = el && el.closest && el.closest('.hb-tk');
      swipe = tk ? { tk, x, y } : null;
    };
    const swipeEnd = (x, y) => {
      if (!swipe) return;
      const dx = x - swipe.x;
      const dy = y - swipe.y;
      if (Math.abs(dx) > 40 && Math.abs(dx) > Math.abs(dy) * 1.5) {
        setSwiped(dx < 0 ? swipe.tk.dataset.tk : '');
        ui.swipeEat = true;
        setTimeout(() => { ui.swipeEat = false; }, 400);
      }
      swipe = null;
    };
    panel.addEventListener('touchstart', (e) => {
      if (e.touches.length !== 1) { swipe = null; return; }
      swipeStart(e.target, e.touches[0].clientX, e.touches[0].clientY);
    }, { passive: true });
    panel.addEventListener('touchend', (e) => {
      const t = e.changedTouches && e.changedTouches[0];
      if (t) swipeEnd(t.clientX, t.clientY);
    }, { passive: true });
    panel.addEventListener('touchcancel', () => { swipe = null; }, { passive: true });
    panel.addEventListener('pointerdown', (e) => { if (e.pointerType === 'pen') swipeStart(e.target, e.clientX, e.clientY); });
    panel.addEventListener('pointerup', (e) => { if (e.pointerType === 'pen') swipeEnd(e.clientX, e.clientY); });
    panel.addEventListener('pointercancel', (e) => { if (e.pointerType === 'pen') swipe = null; });
    panel.addEventListener('click', (e) => {
      if (ui.swipeEat) { ui.swipeEat = false; return; }        // 刚在票根上左右滑过，这一下不算点
      const btn = e.target.closest('[data-act],[data-set]');
      if (!btn || !panel.contains(btn)) return;
      if (btn.dataset.set) {
        const raw = btn.dataset.val;
        saveSetting(btn.dataset.set, /^\d+$/.test(raw) ? Number(raw) : raw);
        renderPanel();
        return;
      }
      const act = btn.dataset.act;
      if (act === 'close') setOpen(false);
      else if (act === 'settings') { ui.view = ui.view === 'settings' ? 'now' : 'settings'; ui.stitch = null; writeUiPref(); renderPanel(); }
      else if (act === 'go') { ui.view = 'settings'; ui.sub = 'settings'; ui.setTab = '模型'; ui.stitch = null; writeUiPref(); renderPanel(); }
      else if (act === 'stitch') runStitch();
      else if (act === 'mute') runMute(btn.dataset.name);
      else if (act === 'unmute') runUnmute(btn.dataset.name);
      else if (act === 'chatmode') { if (CHAT_MODES.indexOf(btn.dataset.val) !== -1 && btn.dataset.val !== chatMode()) setChatMode(btn.dataset.val); renderPanel(); }
      else if (act === 'presetsave') runSavePreset(false);
      else if (act === 'dirtyfind') runDirtyFind();
      else if (act === 'dirtyclean') runDirtyClean();
      else if (act === 'inhfind') runInhFind();
      else if (act === 'inhclear') runInhClear();
      else if (act === 'inhcancel') { ui.inh = null; ui.inhMsg = null; renderPanel(); }
      else if (act === 'presetover') runSavePreset(true);
      else if (act === 'presetrename') { ui.presetName = freePresetName(ui.presetName); ui.presetMsg = null; renderPanel(); }
      else if (act === 'idretry') runIdRetry();
      else if (act === 'rerun') onRerun();
      else if (act === 'test') runTest('side');
      else if (act === 'dtest') runTest('director');
      else if (act === 'wipe') wipeChat();
      else if (act === 'adv') { ui.advOpen = !ui.advOpen; renderPanel(); }
      else if (act === 'tplfind') findTplBook();
      else if (act === 'tplauto') onTplAuto(btn.dataset.name);
      else if (act === 'plain') {
        const n = btn.dataset.name;
        if (ui.plainOpen.has(n)) ui.plainOpen.delete(n); else ui.plainOpen.add(n);
        renderPanel();
      }
      else if (act === 'replain') runReplain(btn.dataset.name);
      else if (act === 'tpl') {
        const n = btn.dataset.name;
        if (ui.tplOpen.has(n)) ui.tplOpen.delete(n); else ui.tplOpen.add(n);
        renderPanel();
        const again = Array.from(ui.body.querySelectorAll('[data-act="tpl"]')).find((x) => x.dataset.name === n);
        if (again) again.focus();
      }
      else if (act === 'flip') {
        ui.flipped.add(btn.dataset.key);
        renderPanel();
      }
      else if (act === 'redo') runRedo(btn.dataset.name);
      else if (act === 'tk') {
        // 在这张卡上选了字（要复制）时不收起
        const sel = TOP.getSelection && TOP.getSelection();
        if (!(sel && String(sel).trim() && sel.anchorNode && btn.contains(sel.anchorNode))) toggleTicket(btn.dataset.name);
      }
      else if (act === 'jump') jumpTicket(btn.dataset.name);
      else if (act === 'stub') toggleStub(btn.dataset.name);
      else if (act === 'addopen') {
        ui.addOpen = !ui.addOpen;
        renderPanel();
        const box = ui.addOpen && ui.body.querySelector('[data-addname]');
        if (box) box.focus();
      }
      else if (act === 'settab') { ui.setTab = btn.dataset.val; renderPanel(); }
      else if (act === 'add') runAdd();
      else if (act === 'bs') {
        const n = btn.dataset.name;
        if (ui.expanded.has(n)) ui.expanded.delete(n); else ui.expanded.add(n);
        renderPanel();
        const again = Array.from(ui.body.querySelectorAll('[data-act="bs"]')).find((x) => x.dataset.name === n);
        if (again) again.focus();
      }
      // 提示词页
      else if (act === 'sub') { ui.sub = btn.dataset.val === 'prompts' ? 'prompts' : 'settings'; ui.pMsg = null; writeUiPref(); renderPanel(); }
      else if (act === 'pfold' || act === 'dfold') {
        const set = act === 'pfold' ? ui.pOpen : ui.dOpen;
        const n = btn.dataset.name;
        if (set.has(n)) set.delete(n); else set.add(n);
        renderPanel();
        const again = Array.from(ui.body.querySelectorAll('[data-act="' + act + '"]')).find((x) => x.dataset.name === n);
        if (again) again.focus();
      }
      else if (act === 'pcopy') {
        const n = btn.dataset.name;
        const box = Array.from(ui.body.querySelectorAll('[data-prompt]')).find((x) => x.dataset.prompt === n);
        copyText(box ? box.value : promptText(n)).then((ok) => promptNote(ok, ok ? '「' + n + '」复制好了' : '复制不了：这个浏览器不让脚本碰剪贴板，手动全选复制'));
      }
      else if (act === 'preset') {
        const n = btn.dataset.name;
        savePrompt(n, '');
        promptNote(true, '「' + n + '」恢复成内置的了');
      }
      else if (act === 'presetall') {
        if (!btn.dataset.sure) { btn.dataset.sure = '1'; btn.textContent = '确定全部恢复？'; return; }   // 点两下才动，免得手滑
        resetAllPrompts();
        ui.pOpen.clear();
        promptNote(true, '全部恢复成内置的了');
      }
      else if (act === 'pexport') exportPrompts();
      else if (act === 'pimport') importPrompts();
      else if (act === 'dcopy') {
        const x = debugEntries().find((e) => debugKey(e) === btn.dataset.name);
        if (x) copyText(debugText(x)).then((ok) => promptNote(ok, ok ? '这一条复制好了' : '复制不了：手动全选复制'));
      }
      else if (act === 'dcopyall') {
        copyText(debugEntries().map(debugText).join('\n\n════════════\n\n')).then((ok) => promptNote(ok, ok ? '调试记录全部复制好了' : '复制不了：手动全选复制'));
      }
      else if (act === 'dclear') {
        if (!btn.dataset.sure) { btn.dataset.sure = '1'; btn.textContent = '确定清空？'; return; }
        ui.dOpen.clear();
        debugClear();
        promptNote(true, '调试记录清空了');
      }
    });
    // 文本框失焦 / 回车时存；勾选框、数字框改了就存
    panel.addEventListener('change', (e) => {
      const d = e.target.dataset || {};
      if (d.tplpick) onTplPick(e.target);
      else if (d.plain != null) onPlainChange(e.target);
      else if (d.pperiod != null) {                   // 同一块里的时期
        const before = personPeriods()[d.pperiod] || '';
        if (String(e.target.value || '').replace(/\s+/g, ' ').trim() !== before) {
          const t = setPersonPeriod(d.pperiod, e.target.value);
          toast('success', t ? '时期存好了：' + d.pperiod + '，下一轮起照这个时期写' : '时期删掉了：' + d.pperiod);
          setTimeout(renderPanel, 0);
        }
      }
      else if (d.prel != null) {                      // 同一块里的关系
        try {
          setRelation(d.prel, d.pto, { [d.pf]: e.target.value });
          toast('success', '关系改好了：' + d.prel + ' 对 ' + d.pto + '，下一轮起照这里');
        } catch (err) {
          toast('warning', '关系没改上：' + ((err && err.message) || String(err)));
        }
        setTimeout(renderPanel, 0);
      }
      else if (d.pnote != null) {                     // 「选择性格模板」里某个人的补充
        const before = personNotes()[d.pnote] || '';
        if (String(e.target.value || '').trim() !== before) {
          const t = setPersonNote(d.pnote, e.target.value);
          toast('success', t ? '补充存好了：' + d.pnote + '，下一轮起照这份写' : '补充删掉了：' + d.pnote);
          setTimeout(renderPanel, 0);                   // 失焦走完再重画（焦点还在输入框里时面板不重画）
        }
      }
      else if (d.modelpick) { if (e.target.value) { saveSetting(d.modelpick === 'director' ? '导演稿模型' : '副模型', e.target.value); renderPanel(); } }
      else if (d.prompt != null) {
        const n = d.prompt;
        if (savePrompt(n, e.target.value)) promptNote(true, promptState(n).custom ? '「' + n + '」存好了' : '「' + n + '」和内置的一样，按内置算');
        else promptNote(false, '「' + n + '」没存上');
      }
      else if (d.stitch != null) ui.stitchSel[d.stitch] = e.target.checked;
      else if (d.ownadd != null) { ui.ownSel[d.ownadd] = e.target.checked; renderPanel(); }
      else if (d.presetname != null) ui.presetName = e.target.value;
      else if (d.presetglobal != null) ui.presetGlobal = e.target.checked;
      else if (d.dirtypick != null) { if (e.target.checked) ui.dirtySel.add(d.dirtypick); else ui.dirtySel.delete(d.dirtypick); ui.cleanMsg = null; renderPanel(); }
      else if (d.stitchadd != null) { if (e.target.checked) ui.stitchAdd.add(d.stitchadd); else ui.stitchAdd.delete(d.stitchadd); }
      else onFieldChange(e.target);
    });
    panel.addEventListener('input', (e) => {
      const d = e.target.dataset || {};
      if (d.addname != null) { ui.addName = e.target.value; return; }
      // 「选择性格模板」「整理好的模板」顶上的筛选框：只换下面那一块列表
      if (d.tplpeople != null || d.plainfilter != null) {
        const R = rosterFull();
        if (!R || !_tpl) return;
        const c = cfg();
        if (d.tplpeople != null) {
          ui.tplPeople = e.target.value;
          const box = ui.body.querySelector('[data-tplpeoplelist]');
          if (box) box.innerHTML = peopleListHtml(R, c, _tpl);
        } else {
          ui.plainFilter = e.target.value;
          const box = ui.body.querySelector('[data-plainlist]');
          if (box) box.innerHTML = plainListHtml(R, c, _tpl, tplPeopleView(R, c, _tpl, '').names);
        }
        return;
      }
      const n = d.tplfilter;
      if (n == null) return;
      ui.tplFilter[n] = e.target.value;
      const box = Array.from(ui.body.querySelectorAll('[data-tpllist]')).find((x) => x.dataset.tpllist === n);
      if (box) box.innerHTML = tplListHtml(n, currentSel(n), _tpl);
    });
    panel.addEventListener('keydown', (e) => {
      if (e.key === 'Escape') { e.stopPropagation(); setOpen(false); fab.focus(); }
