  function 归一(字) {
    return String(字 == null ? '' : 字).normalize('NFKC').toLowerCase()
      .replace(/[\s·・\-–—_.,，。!！?？'"“”‘’「」『』()（）\[\]【】~～:：;；\/\\&*]+/g, '');
  }

  // 曲名对得上才算。以原唱为主：
  // 正文写了艺人，艺人要对得上（艺人栏或乐队，互相包含即可）；乐队翻唱别人的歌只在艺人对得上时才认，不顶替原唱。
  // 几首都对得上时：艺人对上的 > 曲名正好相同的（不是靠别名对上的）> 不是翻唱的。
  function 找曲(曲名, 艺人) {
    const 名 = 归一(曲名);
    if (!名) return null;
    const 手 = 归一(艺人);
    let 最好 = null, 最好分 = -1;
    for (const 条 of 对照表) {
      const 曲名对 = 归一(条.曲名) === 名;
      if (!曲名对 && !(条.别名 || []).some(n => 归一(n) === 名)) continue;
      const 名们 = [条.艺人, 条.乐队].map(归一).filter(Boolean);
      const 艺人对 = !!手 && 名们.some(表 => 表.includes(手) || 手.includes(表));
      if (手 && 名们.length && !艺人对) continue;
      if (条.翻唱 && !艺人对) continue;
      const 分 = (艺人对 ? 4 : 0) + (曲名对 ? 2 : 0) + (条.翻唱 ? 0 : 1);
      if (分 > 最好分) { 最好 = 条; 最好分 = 分; }
    }
    return 最好;
  }

