  // 只读 chat[i].mes 原文，不依赖页面上的小标签（玩家可以关掉小标签，记号会被预设的正则藏起来）。
  // 属性先后不限；自闭合、成对、漏写 / 都认；没写 title 的记号不算；artist 可以没有。
  function 读属性(标签, 名) {
    const m = new RegExp('\\s' + 名 + '\\s*=\\s*"([^"]*)"', 'i').exec(标签);
    return m ? m[1].trim() : '';
  }
  function 读记号(原文) {
    const 标签们 = String(原文 == null ? '' : 原文).match(/<bgm\b[^>]*>/gi) || [];
    const 出 = [];
    for (const 标签 of 标签们) {
      const 曲名 = 读属性(标签, 'title');
      if (曲名) 出.push({ 曲名, 艺人: 读属性(标签, 'artist') });
    }
    return 出;
  }
  // 一轮最多一行；万一有多行，取最后一行
  function 本楼的歌(原文) {
    const 全 = 读记号(原文);
    return 全.length ? 全[全.length - 1] : null;
  }

  // ---------- 网易云 ----------
  // 浏览器读不了网易云的接口（没有 CORS）：没有中转时 id 只来自对照表，免费歌走公开外链；<audio> 跨域播放不受影响。
  // 有中转（中转.js）时，搜索、播放地址、歌词由中转替浏览器去问。
  // 对照表里存的 fee / st 是整理表时查到的快照，用来决定提示文字；真正放不放得出来以中转和 <audio> 的结果为准。
  function 外链(id) { return 'https://music.163.com/song/media/outer/url?id=' + encodeURIComponent(id) + '.mp3'; }
  function 内嵌页(id) { return 'https://music.163.com/outchain/player?type=2&id=' + encodeURIComponent(id) + '&auto=1&height=66'; }
  function 搜索链接(曲名, 艺人) {
    return 'https://music.163.com/#/search/m/?type=1&s=' + encodeURIComponent((曲名 || '') + (艺人 ? ' ' + 艺人 : ''));
  }

  // fee：0 免费，8 免费音质可放，1 黑胶会员，4 单曲或数字专辑付费；st 小于 0 是下架或地区限制
  function 判状态(条) {
    const 云 = 条 && 条.网易云;
    if (!云 || !云.id) return '无来源';
    if (typeof 云.st === 'number' && 云.st < 0) return '放不了';
    if (云.fee === 4) return '付费';
    if (云.fee === 1) return '会员';
    return '可放';
  }

  // 选一个能放的版本：以原唱原版为主，原版能放就放原版。
  // 原版要会员、要购买或放不了时，可退（玩家设置）就放同一歌手的其他版本，对照表里已按 live 版 > 其他完整版本 > 短版排好
  function 选版本(条, 可退) {
    const 状态 = 判状态(条);
    if (状态 === '无来源') return { id: null, 状态, 版本: '' };
    if (状态 === '可放') return { id: 条.网易云.id, 状态, 版本: '' };
    const 备 = 可退 === false ? null : (条.网易云.备选 || [])[0];
    if (备) return { id: 备.id, 状态: '可放', 版本: 备.版本, 原状态: 状态 };
    return { id: 条.网易云.id, 状态, 版本: '' };
  }
  function 版本提示(选) {
    const 原 = 选.原状态 === '会员' ? '原版要网易云黑胶 VIP' : 选.原状态 === '付费' ? '原版要在网易云单独购买' : '原版在网易云放不了';
    return '放的是 ' + 选.版本 + ' · ' + 原;
  }

  // 播放器上那一行字；null 表示不用提示。
  // 会员歌：放的是试听就说试听；没填 cookie 时连试听都没有，告诉怎么能听整首；填了 cookie 还放不了，多半是账号没有会员或 cookie 失效
  function 提示字(状态, 有号) {
    if (状态 === '试听') return '试听 30 秒 · 听整首要网易云黑胶 VIP';
    if (状态 === '会员') return 有号 ? '这首要网易云黑胶 VIP，你填的账号放不了' : '这首在网易云放不了 · 填了带会员的账号 cookie 就能听整首';
    if (状态 === '付费') return '这首要在网易云单独购买';
    if (状态 === '放不了') return '这首在网易云放不了';
    return null;
  }
  // 中转给的音频地址是 http 的；酒馆开在 https 下时换成 https（网易云的音频服务器两种都给）
  const 换协议 = 地址 => (TOP.location && TOP.location.protocol === 'https:' ? String(地址).replace(/^http:\/\//, 'https://') : 地址);

  // ---------- 歌词：楼里的 ♪ 歌词行 → 放这首歌的哪一段；没写曲名时按歌词认歌 ----------
  // 时间轴和认歌索引放在 bangicon 仓库的 MUSIC/ 下，经 jsDelivr 取；里面只有时间和指纹，没有歌词原文。
  // 指纹的算法和 工具/指纹.py 一一对应，两边必须算得一样（测试/单元.mjs 拿 测试/指纹样例.json 核对）。
  // jsDelivr 的几个镜像依次试（国内 testingcf 通常最稳，和主卡一样先用它），记住最近能用的那个
  const 数据镜像 = ['testingcf', 'fastly', 'cdn'].map(h => 'https://' + h + '.jsdelivr.net/gh/yixipf784852-glitch/bangicon@main/MUSIC/');
  const 镜像 = { 好: 0 };
  const 基址们 = () => {
    if (TOP.__MUSIC_数据基址__) return [TOP.__MUSIC_数据基址__]; // 测试时换成本地地址
    return 数据镜像.slice(镜像.好).concat(数据镜像.slice(0, 镜像.好));
  };

  // NFKC、转小写，只留字母和数字（Unicode 的 L、N 两大类）
  function 指纹归一(字) {
    return String(字 == null ? '' : 字).normalize('NFKC').toLowerCase().replace(/[^\p{L}\p{N}]/gu, '');
  }
  function fnv(字) {
    let h = 0x811c9dc5;
    for (const b of new TextEncoder().encode(字)) { h ^= b; h = Math.imul(h, 16777619) >>> 0; }
    return h;
  }
  const 十六 = h => h.toString(16).padStart(8, '0');
  // 按字（码位）两两相邻取对；只有一个字时就是它自己
  function 字对(字) {
    const c = Array.from(字);
    if (c.length < 2) return c.length ? [c.join('')] : [];
    const 出 = [];
    for (let i = 0; i < c.length - 1; i++) 出.push(c[i] + c[i + 1]);
    return 出;
  }
  function 位置(对) {
    const h = fnv(对), 步 = (h >>> 16) | 1;
    return [0, 1, 2].map(i => (h + i * 步) % 128);
  }
  const 编码 = v => btoa(String.fromCharCode(...v)).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
  const 解码 = s => Uint8Array.from(atob(s.replace(/-/g, '+').replace(/_/g, '/') + '=='.slice(0, (4 - s.length % 4) % 4)), c => c.charCodeAt(0));
  function 位图(字) {
    const v = new Uint8Array(16);
    for (const 对 of 字对(指纹归一(字))) for (const p of 位置(对)) v[p >> 3] |= 1 << (p & 7);
    return 编码(v);
  }
  const 整行 = 字 => 十六(fnv(指纹归一(字)));

  // 带时间的歌词（中转现取的）→ 时间轴，和 工具/建时间轴.py 的 解析、时间轴 一一对应：署名行去掉，一行几个时间戳拆成几行，纯音乐不算
  const 时间戳 = /\[(\d+):(\d+)(?:[.:](\d+))?\]/g;
  const 署名 = /^\s*(?:作词|作曲|编曲|制作人|制作|混音|母带|吉他|贝斯|鼓|键盘|弦乐|合声|和声|监制|出品|发行|录音|人声|演唱|原唱|翻译|lyrics?|music|compose[rd]?|arrange[rd]?|producer|vocals?|guitar|bass|drums?|mix(?:ed)?|master(?:ed)?)[^:：]{0,12}[:：]/i;
  function 解析LRC(lrc) {
    const 行们 = [];
    for (const 原 of String(lrc == null ? '' : lrc).split(/\r?\n/)) {
      const 戳们 = [...原.matchAll(时间戳)];
      if (!戳们.length) continue;
      const 字 = 原.replace(时间戳, '').trim();
      if (署名.test(字)) continue;
      for (const m of 戳们) 行们.push([Number(m[1]) * 6000 + Number(m[2]) * 100 + Number(((m[3] || '0') + '00').slice(0, 2)), 字]);
    }
    return 行们.sort((a, b) => a[0] - b[0]);
  }
  function 建轴(lrc) {
    const 行们 = 解析LRC(lrc);
    if (行们.some(([, 字]) => ['纯音乐请欣赏', '纯音乐请您欣赏'].includes(指纹归一(字)))) return null;
    const b = 行们.map(([, 字]) => (指纹归一(字) ? 位图(字) : ''));
    return b.some(Boolean) ? { v: 1, t: 行们.map(x => x[0]), b } : null;
  }

  // 楼里的歌词：正文 <story_scene> 里以 ♪ 开头的独立一行；双语时原文在「☆‹♪ … ›」里，下一行的译文也拿去对（对不上就跳过）
  function 楼里歌词(原文) {
    let 字 = String(原文 == null ? '' : 原文);
    const 片 = /<story_scene>([\s\S]*?)<\/story_scene>/i.exec(字);
    if (片) 字 = 片[1];
    const 句们 = [];
    let 译文行 = false; // 双语时原文行（☆‹♪…›）的下一行是译文（♪ 可有可无）：不当歌词
    for (const 行 of 字.split(/\r?\n/)) {
      if (!行.trim()) continue;
      const 双 = /^[\s⁠-⁤​-‍﻿]*☆‹\s*♪\s*([^‹›]+?)\s*›/.exec(行);
      if (译文行 && !双) { 译文行 = false; continue; }
      译文行 = !!双;
      const 单 = /^[\s⁠-⁤​-‍﻿]*♪\s*(.+?)\s*$/.exec(行);
      const 句 = 双 ? 双[1] : 单 ? 单[1] : null;
      if (句 && Array.from(指纹归一(句)).length >= 2) 句们.push(句);
    }
    return 句们;
  }

  // ---------- 取数据（同一个文件只取一次；404 就当没有；连不上换下一个镜像，都连不上下次再试） ----------
  const 数据缓存 = new Map();
  async function 取一次(地址) {
    const c = new AbortController(), t = setTimeout(() => c.abort(), 4000);
    try {
      const r = await fetch(地址, { signal: c.signal });
      if (r.ok) return { 有: true, 值: await r.json() };
      return { 有: r.status === 404 ? false : null };
    } catch (e) {
      return { 有: null };
    } finally { clearTimeout(t); }
  }
  function 取数据(路径) {
    if (!数据缓存.has(路径)) {
      数据缓存.set(路径, (async () => {
        const 们 = 基址们();
        for (const 基 of 们) {
          const 结果 = await 取一次(基 + 路径);
          if (结果.有 === null) continue; // 连不上：换下一个镜像
          const i = 数据镜像.indexOf(基);
          if (i >= 0) 镜像.好 = i;
          return 结果.有 ? 结果.值 : null;
        }
        数据缓存.delete(路径); // 都连不上：下次再试
        return null;
      })());
    }
    return 数据缓存.get(路径);
  }
  const 取轴 = id => 取数据('时间轴/' + id + '.json');

  // ---------- 对段：楼里这几句是时间轴上的哪一段 ----------
  const 位在 = (图, ps) => ps.every(p => (图[p >> 3] >> (p & 7)) & 1);
  // 返回 { 起, 止 }（秒；止为 null 表示放到歌尾），对不上返回 null
  function 对段(轴, 句们) {
    if (!轴 || !Array.isArray(轴.t) || !Array.isArray(轴.b) || !句们.length) return null;
    const 图们 = 轴.b.map(s => (s ? 解码(s) : null));
    const 下一行 = j => { for (let k = j + 1; k < 图们.length; k++) if (图们[k]) return k; return -1; };
    // 每句的候选：字对有八成落在这一行（短句要全部落在里面）；一句跨两行时，这一行连同下一行一起算
    const 各句 = 句们.map(句 => {
      const 位们 = 字对(指纹归一(句)).map(位置);
      const 门 = 位们.length <= 3 ? 1 : 0.8;
      const 候选 = [];
      图们.forEach((图, j) => {
        if (!图) return;
        let 中 = 0, 合 = 0;
        const k = 下一行(j), 下 = k >= 0 ? 图们[k] : null;
        for (const ps of 位们) { if (位在(图, ps)) 中++; else if (下 && 位在(下, ps)) 合++; }
        if (中 / 位们.length >= 门) 候选.push({ j, 到: j });
        else if (中 > 0 && (中 + 合) / 位们.length >= 门) 候选.push({ j, 到: k });
      });
      return 候选;
    }).filter(候选 => 候选.length);
    if (!各句.length) return null;
    // 从第一句的每个候选出发，后面几句各取它之后最近的候选；取对上句数最多、跨度最小的
    let 最好 = null;
    for (const 起 of 各句[0]) {
      let 末 = 起, 数 = 1;
      for (const 候选 of 各句.slice(1)) {
        const 下 = 候选.find(x => x.j >= 末.j);
        if (下) { 末 = 下; 数++; }
      }
      const 跨 = 末.到 - 起.j;
      if (!最好 || 数 > 最好.数 || (数 === 最好.数 && 跨 < 最好.跨)) 最好 = { 起, 末, 数, 跨 };
    }
    const 止下标 = 最好.末.到 + 1;
    return { 起: 轴.t[最好.起.j] / 100, 止: 止下标 < 轴.t.length ? 轴.t[止下标] / 100 : null };
  }

  // ---------- 认歌：没写曲名时，拿楼里的歌词整行（或开头 8 个字）去索引里查，最多票的那首 ----------
  const 条按id = new Map(对照表.map(条 => [条.网易云.id, 条]));
  async function 认歌(句们) {
    const 票 = new Map();
    for (const 句 of 句们) {
      const c = Array.from(指纹归一(句));
      if (c.length < 4) continue;
      const 键们 = [十六(fnv(c.join('')))];
      if (c.length >= 8) 键们.push(十六(fnv(c.slice(0, 8).join(''))));
      const 中 = new Set();
      for (const 键 of 键们) {
        const 表 = await 取数据('索引/' + 键.slice(0, 2) + '.json');
        ((表 && 表[键]) || []).forEach(id => 中.add(id));
      }
      中.forEach(id => 票.set(id, (票.get(id) || 0) + 1));
    }
    let 最好 = null, 次 = 0;
    for (const [id, n] of 票) {
      if (!最好 || n > 最好[1]) { 次 = 最好 ? 最好[1] : 0; 最好 = [id, n]; } else if (n > 次) 次 = n;
    }
    if (!最好 || 最好[1] === 次) return null; // 没对上，或者几首一样多（比如只对上一句大家都有的「la la la」）
    return 条按id.get(最好[0]) || null;
  }

  // ---------- 中转：用玩家自己的网易云账号 ----------
  // 浏览器读不了网易云的接口：搜索、播放地址、带时间的歌词都请中转替它去问。中转是玩家自己的：
  // 本机的酒馆服务端插件 MUSIC（/api/plugins/music/）、这台手机上的安卓 App「MUSIC!!!!! 中转」（127.0.0.1），或者玩家自己部署的 Worker。
  // 不预填任何公共地址，不发给第三方。
  // 网易云的 cookie 只取 MUSIC_U 一项，存在这台设备的浏览器里（不进预设、角色卡、脚本变量、聊天变量），随每次请求交给中转。
  const 账号键 = 'MUSIC!!!!!:网易云账号';
  const 通行码键 = { worker: 'MUSIC!!!!!:Worker通行码', app: 'MUSIC!!!!!:App通行码' }; // App 和 Worker 各存各的
  const 搜到键 = 'MUSIC!!!!!:搜到'; // 表里没有、中转按曲名搜到的歌：曲名|艺人 → 网易云 id，同一首只搜一次
  const 码键 = 方式 => 通行码键[方式 || 取设置().中转方式] || '';
  function 取通行码(方式) { try { return 码键(方式) ? 存取().getItem(码键(方式)) || '' : ''; } catch (e) { return ''; } }
  function 存通行码(值, 方式) {
    const s = String(值 == null ? '' : 值).trim(), 键 = 码键(方式);
    if (!键) return false;
    try { if (s) 存取().setItem(键, s); else 存取().removeItem(键); return true; } catch (e) { return false; }
  }

  // 玩家贴的是整串 cookie 也只取 MUSIC_U；只贴了值也认
  function 取MUSIC_U(原文) {
    const s = String(原文 == null ? '' : 原文).trim();
    const m = /(?:^|;\s*)MUSIC_U=([^;\s]+)/.exec(s);
    return m ? m[1] : (/^[^\s;=]+$/.test(s) ? s : '');
  }
  function 取账号() { try { return 存取().getItem(账号键) || ''; } catch (e) { return ''; } }
  function 存账号(原文) {
    const u = 取MUSIC_U(原文);
    try { if (u) 存取().setItem(账号键, u); else 存取().removeItem(账号键); } catch (e) { return null; }
    return u;
  }
  function 清账号() { try { 存取().removeItem(账号键); } catch (e) { /* 存不了也就没存 */ } }

  const 中转 = { 通: null, 查时: 0, 安卓: false };
  const 中转开着 = () => 取设置().中转方式 !== '关';
  // 网址只认 http(s)://…。Worker：页面是 https 时 http 的会被浏览器拦，Cloudflare 给的本来就是 https；
  // 安卓 App 在 http://127.0.0.1 上，浏览器把本机地址当安全的，https 页面也能调
  function 中转根() {
    const s = 取设置();
    if (s.中转方式 === '插件') return TOP.location.origin + '/api/plugins/music';
    if (s.中转方式 === 'worker' || s.中转方式 === 'app') {
      const u = String((s.中转方式 === 'app' ? s.App地址 : s.Worker地址) || '').trim().replace(/\/+$/, '');
      return /^https?:\/\/[^\s/]+(\/[^\s]*)?$/i.test(u) ? u : null;
    }
    return null;
  }
  // 本机插件带酒馆的 CSRF 令牌；App 和 Worker 只带通行码（请求头里只能放英文字符，先做 URL 编码），不把酒馆的令牌发出去
  function 中转头() {
    if (取设置().中转方式 === '插件') return TOP.SillyTavern.getContext().getRequestHeaders();
    const 头 = { 'Content-Type': 'application/json' };
    const 码 = 取通行码();
    if (码) 头['X-Music-Key'] = encodeURIComponent(码);
    return 头;
  }
  // 插件装没装、开没开：查一次记 5 分钟（重新测试连接时强制再查）
  async function 中转可用(强制) {
    if (!中转根()) return false;
    if (!强制 && 中转.通 !== null && Date.now() - 中转.查时 < 5 * 60 * 1000) return 中转.通;
    try {
      const r = await fetch(中转根() + '/ping', { signal: AbortSignal.timeout(5000) });
      const 回 = r.ok ? await r.json() : {};
      中转.通 = !!回.名字;
      中转.安卓 = !!回.安卓;
    } catch (e) { 中转.通 = false; }
    中转.查时 = Date.now();
    return 中转.通;
  }
  async function 问中转(路径, 体) {
    const 根 = 中转根();
    if (!根) throw new Error('没开中转');
    const r = await fetch(根 + 路径, {
      method: 'POST',
      headers: 中转头(),
      body: JSON.stringify(Object.assign({ cookie: 取账号() }, 体 || {})),
      signal: AbortSignal.timeout(12000),
    });
    if (!r.ok) { const e = new Error('中转回了 ' + r.status); e.码 = r.status; throw e; }
    return r.json();
  }

  // ---------- 表里没有的歌：按曲名、歌手搜，以原唱为主挑一首 ----------
  const 不收 = /instrumental|inst\.|off ?vocal|karaoke|伴奏|カラオケ|backing track/i;
  const 翻唱字 = /cover|翻唱|カバー/i;
  const 版本尾 = /\s*(?:[(（\[【][^()（）\[\]【】]*[)）\]】]|\s[-–—]\s.*(?:ver|version|size|live|remix|mix|edit|take)[^-–—]*)\s*$/i;
  const 底名 = 字 => 归一(String(字 || '').replace(版本尾, ''));
  // 曲名（去掉版本后缀）要对上；正文写了歌手就要对上；伴奏不要；翻唱只在歌手对上时要。原版、歌手对上、这个账号能放的在前
  function 挑歌(们, 歌) {
    const 名 = 归一(歌.曲名), 名底 = 底名(歌.曲名), 手 = 归一(歌.艺人);
    let 最好 = null, 最好分 = -1;
    for (const s of 们 || []) {
      const 全名 = [s.曲名].concat(s.别名 || []);
      if (全名.some(n => 不收.test(n))) continue;
      const 正好 = 全名.some(n => 归一(n) === 名);
      if (!正好 && !全名.some(n => 底名(n) === 名底)) continue;
      const 艺们 = (s.艺人 || []).map(归一).filter(Boolean);
      const 艺对 = !!手 && 艺们.some(a => a.includes(手) || 手.includes(a));
      if (手 && !艺对) continue;
      if (全名.some(n => 翻唱字.test(n)) && !艺对) continue;
      const 分 = (艺对 ? 4 : 0) + (正好 ? 2 : 0) + (版本尾.test(s.曲名) ? 0 : 2) + (s.pl > 0 && s.st >= 0 ? 1 : 0);
      if (分 > 最好分) { 最好 = s; 最好分 = 分; }
    }
    return 最好;
  }
  function 读搜到() { try { return JSON.parse(存取().getItem(搜到键)) || {}; } catch (e) { return {}; } }
  async function 搜歌(歌) {
    const 键 = 归一(歌.曲名) + '|' + 归一(歌.艺人);
    const 记 = 读搜到();
    if (记[键]) return 记[键];
    const r = await 问中转('/search', { keywords: (歌.曲名 + ' ' + (歌.艺人 || '')).trim() }).catch(() => null);
    const 中 = 挑歌(r && r.歌们, 歌);
    if (!中) return null;
    记[键] = 中.id;
    try { 存取().setItem(搜到键, JSON.stringify(记)); } catch (e) { /* 存不了就下次再搜 */ }
    return 中.id;
  }

  // ---------- 找源：这首歌这一次从哪放 ----------
  // 有中转时：原唱原版先问中转要地址（会员账号能放整首）；只给试听或放不了时，先退到同一歌手的免费版本（玩家设置），再放试听。
  // 没有中转时照对照表（免费歌走公开外链）。结果：{ id, 状态（可放 / 试听 / 会员 / 付费 / 放不了 / 无来源）, 版本, 原状态, 地址 }
  const 源缓存 = new Map(); // 曲键 → 最近一次的结果（给播放器上那一行字用；地址会过期，放的时候重新要）
  const 中转状态 = fee => (fee === 1 ? '会员' : fee === 4 ? '付费' : '放不了');
  async function 找源(歌) {
    const 设置 = 取设置();
    const 表选 = 查来源(歌);
    if (!设置.来源.网易云 || !(await 中转可用())) return 表选;
    const 条 = 设置.来源.对照表 ? (歌.条 || 找曲(歌.曲名, 歌.艺人)) : null;
    const 原id = 条 ? 条.网易云.id : await 搜歌(歌);
    if (!原id) return 表选;
    const 原 = await 问中转('/url', { id: 原id }).catch(() => null);
    if (!原) return 表选; // 中转出错：照对照表
    if (原.地址 && !原.试听) return { id: 原id, 状态: '可放', 版本: '', 地址: 原.地址 };
    const 原状态 = 原.试听 ? '会员' : 中转状态(原.fee);
    const 备 = 设置.退版本 && 条 ? (条.网易云.备选 || [])[0] : null;
    if (备) return { id: 备.id, 状态: '可放', 版本: 备.版本, 原状态 };
    if (原.地址 && 原.试听) return { id: 原id, 状态: '试听', 版本: '', 地址: 原.地址 };
    return { id: 原id, 状态: 原状态, 版本: '' };
  }
  // 先在后台查一下，好让播放器上那一行字说得准（只查最近几楼的，免得一打开长聊天就问一大串）
  const 预查中 = new Set();
  function 预查(歌) {
    const 键 = 曲键(歌);
    if (源缓存.has(键) || 预查中.has(键)) return;
    预查中.add(键);
    找源(歌).then(源 => { 源缓存.set(键, Object.assign({}, 源, { 地址: undefined })); 刷新(); }, () => {}).finally(() => 预查中.delete(键));
  }

  // 时间轴：先取 bangicon 上整理好的；没有就请中转取带时间的歌词，在这里现算
  const 现算 = new Map();
  async function 取轴或现算(id) {
    const 轴 = await 取轴(id);
    if (轴) return 轴;
    if (!(await 中转可用())) return null;
    if (!现算.has(id)) 现算.set(id, 问中转('/lyric', { id }).then(r => 建轴(r && r.lrc), () => { 现算.delete(id); return null; }));
    return 现算.get(id);
  }

  // 设置面板「测试连接」：中转在不在、通行码对不对、账号登录没有、有没有会员（不显示昵称和账号 id）。
  // 账号以中转说的为准：安卓 App 里登录过的，浏览器里不用填 cookie 也算登录了
  async function 测试连接() {
    const 方式 = 取设置().中转方式;
    if (方式 === '关') return { 字: '没开中转：只放免费歌', 级: 'warn' };
    const 叫 = 方式 === 'worker' ? 'Worker' : 方式 === 'app' ? '安卓 App' : '本机中转';
    if ((方式 === 'worker' || 方式 === 'app') && !中转根()) return { 字: 叫 + '的地址不对：要 http:// 或 https:// 开头的完整网址', 级: 'bad' };
    if (!(await 中转可用(true))) {
      return 方式 === 'worker' ? { 字: '连不上 Worker：网址填错了，或者 Worker 还没部署好', 级: 'bad' }
        : 方式 === 'app' ? { 字: '连不上安卓 App：App 里「② 中转」打开了吗？地址和 App「③ 填进酒馆」上的一样吗？', 级: 'bad' }
        : { 字: '连不上本机中转：酒馆服务端插件 MUSIC 没装，或者 config.yaml 里 enableServerPlugins 没开', 级: 'bad' };
    }
    try {
      const s = await 问中转('/status');
      if (s.登录) return s.会员 ? { 字: '已登录 · 有黑胶 VIP，会员歌能放整首', 级: 'info' } : { 字: '已登录 · 没有会员：会员歌只有 30 秒试听', 级: 'warn' };
      if (方式 === 'app') return { 字: '安卓 App 能用；App 里还没登录网易云，只放免费歌', 级: 'info' };
      if (!取账号()) return { 字: 叫 + '能用；没填 cookie，只放免费歌', 级: 'info' };
      return { 字: '没登录上：cookie 填错了，或者已经失效，重新从网易云网页复制一次', 级: 'bad' };
    } catch (e) {
      if (e && e.码 === 403) {
        return { 字: 方式 === 'app' ? '通行码不对：要和 App「③ 填进酒馆」上的一样' : '通行码不对：要和 Worker 里设的 MUSIC_KEY 一样', 级: 'bad' };
      }
      return { 字: 叫 + '出错了：' + (e && e.message ? e.message : '没回应'), 级: 'bad' };
    }
  }

  // ---------- 播放：接管预设渲染出来的外观，一次只放一首 ----------
  // 预设在消息里画好外观（带 data-mu-style / data-mu-part），这里只找 data 属性（酒馆会给 class 加前缀，class 不可靠）。
  // 曲名、艺人以消息原文为准；外观关成「不显示」时，用页面底部的迷你条兜底。
  // 歌跟着楼层走：新的 AI 楼层有歌就自动放；AI 的新楼层开始出字时，正在放的歌渐弱停下；玩家写回复时照常听。
  // 楼里有 ♪ 歌词时只放那几句（从第一句开始，最后一句唱完渐弱停下）；没写曲名但有歌词时按歌词认歌，由迷你条来放。
  const 音频 = new Audio();
  音频.preload = 'none';
  const 播 = { 键: null, 歌: null, 止: null }; // 止：只放一段时，这一段在第几秒结束
  const 认出 = new Map(); // 楼 + 原文 → { 等: Promise, 条 }：按歌词认出来的歌，同一楼同样的原文只认一次
  const 点 = { 观察: null, 定时: 0 };
  const 等 = { 淡出: false, 新楼: false };
  const 渐 = { 定时: 0, 完: null, 进行: null, 代: 0 };
  const 上一首 = { 曲: '', 位置: 0, 时: 0 }; // 渐弱停下的那首；新楼层还是这首，就从停下的地方接着放
  const 失败录 = new Map(); // 歌键 → { 字, 级, 链接 }：放不出来的原因，重画时也留着
  const 回复类 = new Set(['normal', 'regenerate', 'swipe', 'group_chat']);
  const 淡出毫秒 = 2500, 淡入毫秒 = 800;
  // iPhone 的浏览器不让网页改音量：渐弱做不了，到点直接停
  const 能调音量 = (() => { try { const a = new Audio(); a.volume = 0.5; return Math.abs(a.volume - 0.5) < 0.01; } catch (e) { return false; } })();
  // 0.1 秒静音：玩家第一次点页面时放一下，手机浏览器才允许之后自动播放
  const 静音 = (() => {
    const n = 800, b = new Uint8Array(44 + n), v = new DataView(b.buffer);
    const 写 = (o, s) => { for (let i = 0; i < s.length; i++) b[o + i] = s.charCodeAt(i); };
    写(0, 'RIFF'); v.setUint32(4, 36 + n, true); 写(8, 'WAVEfmt '); v.setUint32(16, 16, true);
    v.setUint16(20, 1, true); v.setUint16(22, 1, true); v.setUint32(24, 8000, true); v.setUint32(28, 8000, true);
    v.setUint16(32, 1, true); v.setUint16(34, 8, true); 写(36, 'data'); v.setUint32(40, n, true);
    b.fill(128, 44);
    let s = '';
    b.forEach(x => { s += String.fromCharCode(x); });
    return 'data:audio/wav;base64,' + btoa(s);
  })();

  const 秒 = s => (isFinite(s) && s >= 0 ? Math.floor(s / 60) + ':' + String(Math.floor(s % 60)).padStart(2, '0') : '0:00');
  const 部分 = (根, 名) => 根.querySelector('[data-mu-part="' + 名 + '"]');
  const 写字 = (根, 名, 字) => {
    const el = 部分(根, 名);
    if (el && el.textContent !== 字) el.textContent = 字;
  };
  const 聊天记录 = () => { try { return 酒馆().chat || []; } catch (e) { return []; } };
  const 歌键 = 歌 => 歌.楼 + '|' + 歌.曲名; // 哪一楼的哪首
  const 曲键 = 歌 => 归一(歌.曲名) + '|' + 归一(歌.艺人); // 哪首，不管哪一楼

  // 这个外观属于哪一楼哪首歌：先看这楼的记号，没有记号就用按歌词认出来的（旁音那种只有歌词的外观也接得上）
  function 元素的歌(根) {
    if (根.__歌) return 根.__歌;
    const 楼 = 根.closest('.mes');
    const id = 楼 ? 楼.getAttribute('mesid') : null;
    if (id != null && 聊天记录()[id]) {
      const 一首 = 楼里的歌(id);
      if (一首) return 一首;
    }
    return 根.dataset.muTitle ? { 楼: id, 曲名: 根.dataset.muTitle, 艺人: 根.dataset.muArtist || '' } : null;
  }
  // 这一楼的歌：先看记号；没有记号、但已经按歌词认出来了，就用认出来的
  const 认键 = (id, 原文) => id + '|' + 原文.length + '|' + 原文.slice(-80);
  function 楼里的歌(id) {
    const 原文 = String((聊天记录()[id] || {}).mes || '');
    const 一首 = 本楼的歌(原文);
    if (一首) return Object.assign({ 楼: String(id) }, 一首);
    const 认 = 认出.get(认键(id, 原文));
    return 认 && 认.条 ? { 楼: String(id), 曲名: 认.条.曲名, 艺人: 认.条.艺人, 条: 认.条, 认出: true } : null;
  }
  // 按歌词认这一楼的歌；认出来以后重画
  function 去认(id) {
    const 原文 = String((聊天记录()[id] || {}).mes || '');
    if (!取设置().认歌 || 本楼的歌(原文)) return Promise.resolve(null);
    const 句们 = 楼里歌词(原文);
    if (!句们.length) return Promise.resolve(null);
    const 键 = 认键(id, 原文);
    if (!认出.has(键)) {
      const 认 = { 条: null };
      认.等 = 认歌(句们).then(条 => { 认.条 = 条; if (条) 刷新(); return 条; }, () => null);
      认出.set(键, 认);
    }
    return 认出.get(键).等;
  }

  // 这首歌现在能怎么放
  function 查来源(歌) {
    const 设置 = 取设置();
    const 条 = 设置.来源.对照表 && 设置.来源.网易云 ? (歌.条 || 找曲(歌.曲名, 歌.艺人)) : null;
    return 选版本(条, 设置.退版本);
  }
  // 播放器上那一行该写什么：有中转时用找源查到的结果；还没查完先不说（免得把会员能放的歌说成放不了）
  function 该说(歌) {
    const 败 = 失败录.get(歌键(歌));
    if (败) return 败;
    const 源 = 源缓存.get(曲键(歌));
    const 选 = 源 || 查来源(歌);
    if (!源 && 选.状态 !== '可放' && 中转开着() && 中转.通 !== false) return { 字: '', 级: '', 链接: false };
    if (选.状态 === '无来源') return { 字: '没有这首歌的来源', 级: 'warn', 链接: true };
    if (选.状态 === '试听') return { 字: 提示字('试听'), 级: 'warn', 链接: false };
    if (选.状态 === '可放') {
      if (选.版本) return { 字: 版本提示(选), 级: 'warn', 链接: false };
      return 歌.认出 ? { 字: '没写曲名，按歌词认出来的', 级: 'info', 链接: false } : { 字: '', 级: '', 链接: false };
    }
    return { 字: 提示字(选.状态, !!取账号()) || '', 级: 选.状态 === '付费' ? 'warn' : 'bad', 链接: true };
  }
  function 设提示(根, 说, 歌) {
    const el = 部分(根, 'note');
    if (!el) return;
    const 签 = [说.字, 说.级, 说.链接].join('|');
    if (el.__签 === 签) return;
    el.__签 = 签;
    el.textContent = 说.字 || '';
    if (说.字 && 说.链接) {
      const a = TOP.document.createElement('a');
      a.href = 搜索链接(歌.曲名, 歌.艺人);
      a.target = '_blank'; a.rel = 'noopener noreferrer';
      a.textContent = ' 在网易云搜索';
      el.appendChild(a);
    }
    if (说.字 && 说.级) el.dataset.muLevel = 说.级; else delete el.dataset.muLevel;
  }

  // 把一个外观画成当前状态（只在内容变了才写）
  function 画外观(根) {
    const 歌 = 元素的歌(根);
    if (!歌) return;
    // 告诉预设的样式「播放器接管了」：没有这个属性时，预设把播放钮和进度条藏起来（给没装播放器的人看）
    if (!根.hasAttribute('data-mu-ready')) 根.setAttribute('data-mu-ready', '');
    const 当前 = 播.键 === 歌键(歌);
    const 在放 = 当前 && !音频.paused;
    if (在放 !== 根.hasAttribute('data-mu-playing')) 根.toggleAttribute('data-mu-playing', 在放);
    写字(根, 'btn', 在放 ? '❚❚' : '▶');
    // 开着中转时，最近几楼的歌先在后台查一下来源
    if (中转开着() && 中转.通 !== false && Number(歌.楼) >= 聊天记录().length - 6) 预查(歌);
    const 源 = 源缓存.get(曲键(歌)) || 查来源(歌);
    写字(根, 'src', 源.id ? '网易云' : '');
    写字(根, 'state', 在放 ? (播.试听 ? '试听' : 'NOW PLAYING') : 'BGM');
    const 总 = 音频.duration;
    写字(根, 'time', 当前 ? 秒(音频.currentTime) + ' / ' + 秒(总) : '');
    const bar = 部分(根, 'bar');
    if (bar && bar.firstElementChild) {
      const 宽 = (当前 && 总 > 0 ? Math.min(100, 音频.currentTime / 总 * 100) : 0) + '%';
      if (bar.firstElementChild.style.width !== 宽) bar.firstElementChild.style.width = 宽;
    }
    // 旁音卡（正文里的 ♪ 歌词播放器）：同一楼有唱片卡时提示只写在唱片卡上，不重复
    const 楼 = 根.dataset.muStyle === 'lyric' ? 根.closest('.mes') : null;
    const 让给唱片卡 = 楼 && 楼.querySelector('[data-mu-style]:not([data-mu-style="lyric"])');
    设提示(根, 让给唱片卡 ? { 字: '', 级: '', 链接: false } : 该说(歌), 歌);
  }

  function 刷新() {
    clearTimeout(点.定时);
    点.定时 = setTimeout(() => {
      if (态.作废) return;
      if (点.观察) 点.观察.disconnect();
      try {
        TOP.document.querySelectorAll('#chat [data-mu-style]').forEach(画外观);
        画迷你条();
      } finally { 监听(); }
    }, 120);
  }
  function 监听() {
    const 聊天 = TOP.document.getElementById('chat');
    if (聊天 && 点.观察 && !态.作废) 点.观察.observe(聊天, { childList: true, subtree: true });
  }

  // ---------- 音量渐变 ----------
  function 停渐变() {
    clearInterval(渐.定时); 渐.定时 = 0;
    if (渐.完) { const 完 = 渐.完; 渐.完 = null; 完(); }
  }
  // 音量平滑变到目标值：变小先快后慢，变大先慢后快，听起来比较匀
  function 渐变(目标, 毫秒) {
    停渐变();
    if (!能调音量) return Promise.resolve();
    const 起 = 音频.volume, 始 = Date.now();
    return new Promise(完 => {
      渐.完 = 完;
      渐.定时 = setInterval(() => {
        const t = Math.min(1, (Date.now() - 始) / 毫秒);
        const v = 目标 < 起 ? 目标 + (起 - 目标) * (1 - t) * (1 - t) : 起 + (目标 - 起) * t * t;
        音频.volume = Math.max(0, Math.min(1, v));
        if (t >= 1) 停渐变();
      }, 40);
    });
  }
  function 取消淡出() {
    渐.代++;
    停渐变();
    渐.进行 = null;
    try { 音频.volume = 1; } catch (e) { /* 改不了音量的浏览器 */ }
  }
  // 正在放的歌渐弱停下；同时只有一次
  function 淡出停(毫秒) {
    if (渐.进行) return 渐.进行;
    if (!播.键 || 音频.paused) {
      if (播.键) { 播.键 = null; 播.歌 = null; 刷新(); }
      return Promise.resolve();
    }
    const 歌 = 播.歌, 代 = ++渐.代;
    渐.进行 = 渐变(0, 毫秒 == null ? 淡出毫秒 : 毫秒).then(() => {
      if (代 !== 渐.代) return; // 中途换了歌，不动新歌
      渐.进行 = null;
      // 整首放着被打断才记下位置（下一楼还是这首就接着放）；只放一段的放完了不记
      if (播.止 == null) { 上一首.曲 = 曲键(歌); 上一首.位置 = 音频.currentTime || 0; 上一首.时 = Date.now(); }
      音频.pause();
      try { 音频.volume = 1; } catch (e) { /* 同上 */ }
      if (播.歌 === 歌) { 播.键 = null; 播.歌 = null; 播.止 = null; }
      刷新();
    });
    return 渐.进行;
  }

  function 停() {
    取消淡出();
    音频.pause();
    音频.muted = false;
    播.键 = null; 播.歌 = null; 播.止 = null; 播.试听 = false;
    刷新();
  }

  // 跳到第几秒（还没读到时长就等读到再跳）
  function 跳到(秒数) {
    return new Promise(完 => {
      const 跳 = () => { try { 音频.currentTime = 秒数; } catch (e) { /* 拖不了就从头放 */ } 完(); };
      if (音频.readyState >= 1) 跳(); else 音频.addEventListener('loadedmetadata', 跳, { once: true });
    });
  }

  function 失败(根, 歌, e, 自动) {
    if (e && e.name === 'AbortError') return; // 放的途中换了歌，不算失败
    const 被拦 = !!(e && e.name === 'NotAllowedError');
    停();
    失败录.set(歌键(歌), 被拦
      ? { 字: 自动 ? '点一下播放' : '浏览器拦了播放，再点一下', 级: 'warn', 链接: false }
      : { 字: '这首在网易云放不了', 级: 'bad', 链接: true });
    if (根) 设提示(根, 失败录.get(歌键(歌)), 歌);
  }

  // 开始放一首。先找源（有中转时问中转要地址），自动：新楼层自动放的，音量渐入。
  // 楼里有歌词（而且设置里开着「只放那几句」）：先静音起放（不丢掉玩家这一下点击），取到时间轴、跳到第一句前一点再出声，最后一句唱完渐弱停下。
  // 没歌词时：上一首渐弱停下的正好是同一首，就从停下的地方接着放。试听只有 30 秒，不对段、不接着放。
  async function 开放(歌, 根, 自动) {
    if (根 && 根.__歌) 歌 = 根.__歌;
    const 键 = 歌键(歌);
    let 选;
    try { 选 = await 找源(歌); } catch (e) { 选 = 查来源(歌); }
    源缓存.set(曲键(歌), Object.assign({}, 选, { 地址: undefined }));
    失败录.delete(键);
    if (选.状态 !== '可放' && 选.状态 !== '试听') { 刷新(); return; }
    取消淡出();
    音频.pause();
    const 设置 = 取设置();
    const 试听 = 选.状态 === '试听';
    const 句们 = 设置.跟歌词 && !试听 && 歌.楼 != null ? 楼里歌词((聊天记录()[歌.楼] || {}).mes) : [];
    const 续 = !句们.length && !试听 && 自动 && 上一首.曲 === 曲键(歌) && Date.now() - 上一首.时 < 30 * 60 * 1000 ? 上一首.位置 : 0;
    上一首.曲 = '';
    播.键 = 键; 播.歌 = 歌; 播.止 = null; 播.试听 = 试听;
    音频.src = 选.地址 ? 换协议(选.地址) : 外链(选.id);
    if (续 > 0) 跳到(续);
    音频.muted = 句们.length > 0;
    if (自动 && 能调音量) 音频.volume = 0;
    刷新();
    try {
      await 音频.play();
    } catch (e) {
      音频.muted = false;
      try { 音频.volume = 1; } catch (x) { /* 同上 */ }
      if (播.键 === 键) 失败(根, 歌, e, 自动);
      return;
    }
    if (句们.length) {
      const 段 = 对段(await 取轴或现算(选.id), 句们);
      if (播.键 !== 键) return; // 等时间轴的时候换了歌
      if (段) {
        播.止 = 段.止;
        await 跳到(Math.max(0, 段.起 - 0.4));
      } else if (音频.currentTime < 10) {
        await 跳到(0); // 对不上就整首从头放（刚才静音那一小会儿不算）
      }
      if (能调音量) 音频.volume = 0;
      音频.muted = false;
      渐变(1, 段 ? 300 : 淡入毫秒);
      刷新();
      return;
    }
    if (自动 && 播.键 === 键) 渐变(1, 淡入毫秒);
  }

  // 点了播放钮
  function 切换(根) {
    const 歌 = 元素的歌(根);
    if (!歌) return;
    if (播.键 === 歌键(根.__歌 || 歌)) {
      // 正在渐弱时点一下：接着放，不再停（只放一段的也放下去）
      if (渐.进行) { 取消淡出(); 播.止 = null; 音频.play().catch(e => 失败(根, 歌, e, false)); return; }
      if (音频.paused) 音频.play().catch(e => 失败(根, 歌, e, false)); else 音频.pause();
      return;
    }
    开放(歌, 根, false);
  }

  function 找根(歌) {
    const 楼 = TOP.document.querySelector('#chat .mes[mesid="' + 歌.楼 + '"]');
    const 根 = 楼 && 楼.querySelector('[data-mu-style]');
    if (根) return 根;
    画迷你条();
    const 条 = TOP.document.getElementById('mu-dock');
    return 条 && 条.__歌 && 歌键(条.__歌) === 歌键(歌) ? 条 : null;
  }

  // 新楼层出来了：有歌就放（没写曲名就先按歌词认；上一首还在渐弱的话，等它停完）
  async function 自动放(id) {
    let 歌 = 楼里的歌(id);
    if (!歌 && await 去认(id)) 歌 = 楼里的歌(id);
    if (!歌) return;
    if (渐.进行) await 渐.进行;
    else if (播.键 && !音频.paused && 播.键 !== 歌键(歌)) await 淡出停(1200);
    if (播.键 === 歌键(歌) && !音频.paused) return;
    开放(歌, 找根(歌), true);
  }

  // 左右翻页（不生成新页时）：正在放的是这一楼的歌、翻过去换了歌，就渐弱停下；最新一楼翻到的页有歌就放
  function 换页(id) {
    if (等.新楼) return; // 这次翻页会生成新的一页，等生成完再说
    const 歌 = 楼里的歌(id);
    const 在这楼 = 播.歌 && String(播.歌.楼) === String(id);
    const 同一首 = 在这楼 && 歌 && 曲键(歌) === 曲键(播.歌);
    if (在这楼 && !同一首) 淡出停(1200);
    if (歌 && !同一首 && id === 聊天记录().length - 1 && 取设置().自动播放) 自动放(id);
    刷新();
  }

  // ---------- 迷你条：外观关成「不显示」时的兜底 ----------
  const 迷你样式 = `
#mu-dock{position:relative;margin:0 auto 6px;max-width:min(560px,100%);border-radius:16px;background:#2a1c3b;color:#f4ecff;padding:8px 12px 10px;display:none;gap:10px;align-items:center;box-shadow:0 6px 18px rgba(50,25,90,.4);font:14px/1.4 "Noto Sans SC","Microsoft YaHei",sans-serif}
#mu-dock.mu-on{display:flex}
#mu-dock .mu-d{flex:0 0 34px;height:34px;border-radius:50%;background:repeating-radial-gradient(circle,#2a1c3b 0 1.5px,#3b2858 1.5px 3px);box-shadow:0 0 0 2px rgba(255,255,255,.12)}
#mu-dock[data-mu-playing] .mu-d{animation:mu-dock-spin 6s linear infinite}
@keyframes mu-dock-spin{to{transform:rotate(360deg)}}
@media (prefers-reduced-motion:reduce){#mu-dock[data-mu-playing] .mu-d{animation:none}}
#mu-dock .mu-m{flex:1;min-width:0}#mu-dock .mu-t{font-weight:800;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
#mu-dock .mu-a{font-size:12px;color:#bfa8e6;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
#mu-dock .mu-a [data-mu-part="time"]:not(:empty)::before{content:" · "}
#mu-dock .mu-n{font-size:12px;color:#f0b27a}#mu-dock .mu-n:empty{display:none}#mu-dock .mu-n[data-mu-level="bad"]{color:#f29aa0}#mu-dock .mu-n[data-mu-level="info"]{color:#bfa8e6}
#mu-dock .mu-n a{color:inherit;text-decoration:underline}
#mu-dock .mu-b{flex:0 0 34px;height:34px;border-radius:50%;border:0;background:linear-gradient(135deg,#7b4fc0,#c4527f);color:#fff;cursor:pointer;font-size:13px;position:relative}
#mu-dock .mu-b::before{content:"";position:absolute;inset:-5px}
#mu-dock .mu-p{position:absolute;left:12px;right:12px;bottom:0;height:2px;background:rgba(255,255,255,.14)}#mu-dock .mu-p i{display:block;height:100%;width:0;background:linear-gradient(90deg,#7b4fc0,#c4527f)}`;

  function 迷你条() {
    const d = TOP.document;
    let 条 = d.getElementById('mu-dock');
    if (条) return 条;
    const 位 = d.getElementById('send_form');
    if (!位 || !位.parentNode) return null;
    条 = d.createElement('div');
    条.id = 'mu-dock';
    条.innerHTML = '<style>' + 迷你样式 + '</style><span class="mu-d"></span>'
      + '<span class="mu-m"><div class="mu-t" data-mu-part="title"></div><div class="mu-a"><span data-mu-part="artist"></span><span data-mu-part="time"></span></div><div class="mu-n" data-mu-part="note"></div></span>'
      + '<button class="mu-b" data-mu-part="btn" aria-label="播放">▶</button><span class="mu-p" data-mu-part="bar"><i></i></span>';
    条.querySelector('.mu-b').addEventListener('click', () => 切换(条));
    位.parentNode.insertBefore(条, 位);
    收尾.push(() => 条.remove());
    return 条;
  }
  // 迷你条显示最近一个「有歌但没有外观」的楼层；正在用迷你条放的歌优先
  function 画迷你条() {
    const d = TOP.document;
    const 聊 = 聊天记录();
    let 歌 = null;
    for (let i = 聊.length - 1; i >= 0; i--) {
      const 一首 = 楼里的歌(i);
      // 最近一个有歌的楼只有歌词、还没认出来：去认，认出来会重画
      if (!一首) { if (楼里歌词(聊[i] && 聊[i].mes).length) { 去认(i); break; } continue; }
      const 楼 = d.querySelector('#chat .mes[mesid="' + i + '"]');
      if (楼 && !楼.querySelector('[data-mu-style]')) 歌 = 一首;
      break;
    }
    if (播.歌 && 播.歌.迷你 && !音频.paused) 歌 = 播.歌;
    const 旧 = d.getElementById('mu-dock');
    if (!歌) { if (旧) 旧.classList.remove('mu-on'); return; }
    const 条 = 迷你条();
    if (!条) return;
    条.__歌 = Object.assign({}, 歌, { 迷你: true });
    条.classList.add('mu-on');
    写字(条, 'title', 歌.曲名);
    写字(条, 'artist', 歌.艺人);
    画外观(条);
  }

  // 排查用：现在在放什么、音量多少
  function 播放状态() {
    return { 歌: 播.歌 && { 楼: 播.歌.楼, 曲名: 播.歌.曲名, 艺人: 播.歌.艺人 }, 在放: !!播.键 && !音频.paused, 音量: 音频.volume, 静音: 音频.muted,
      位置: 音频.currentTime, 段尾: 播.止, 试听: !!播.试听, 渐弱中: !!渐.进行, 等: Object.assign({}, 等), 能调音量,
      地址: 播.键 ? String(音频.currentSrc || 音频.src).replace(/\?.*$/, '') : null, 中转: 中转.通 };
  }

  // ---------- 接线 ----------
  function 启动播放() {
    const d = TOP.document;
    // 点击：预设画的播放钮，或整枚小标签
    const 点击 = e => {
      const 根 = e.target.closest && e.target.closest('[data-mu-style]');
      if (!根 || 根.closest('#chat') === null) return;
      if (e.target.closest('a')) return; // 提示里的搜索链接照常打开
      const 钮 = e.target.closest('[data-mu-part="btn"]');
      if (钮 || 根.dataset.muStyle === 'tag') { e.preventDefault(); 切换(根); }
    };
    d.addEventListener('click', 点击, true);
    收尾.push(() => d.removeEventListener('click', 点击, true));

    // 第一次点页面：放一下静音，解锁手机浏览器的自动播放
    const 解锁 = () => {
      d.removeEventListener('pointerdown', 解锁, true);
      d.removeEventListener('keydown', 解锁, true);
      if (播.键 || !音频.paused) return;
      音频.src = 静音;
      音频.play().then(() => { if (!播.键 && 音频.src === 静音) 音频.pause(); }).catch(() => { /* 解锁失败就等玩家点播放 */ });
    };
    d.addEventListener('pointerdown', 解锁, true);
    d.addEventListener('keydown', 解锁, true);
    收尾.push(() => { d.removeEventListener('pointerdown', 解锁, true); d.removeEventListener('keydown', 解锁, true); });

    音频.addEventListener('play', 刷新);
    音频.addEventListener('pause', 刷新);
    音频.addEventListener('timeupdate', () => {
      if (!播.键) return;
      // 只放一段：最后一句快唱完时开始渐弱，正好在下一句开头前后停下
      if (播.止 != null && !渐.进行 && 音频.currentTime >= 播.止 - 0.5) 淡出停(900);
      刷新();
    });
    音频.addEventListener('ended', () => { if (播.键) { 播.键 = null; 播.歌 = null; 刷新(); } });
    音频.addEventListener('error', () => {
      if (!播.键 || !播.歌) return;
      const 歌 = 播.歌;
      失败(找根(歌), 歌, null, false);
    });
    收尾.push(() => { 取消淡出(); 音频.pause(); 音频.removeAttribute('src'); });
    // 脚本关掉或重载时撤掉接管标记，播放钮跟着藏回去
    收尾.push(() => d.querySelectorAll('#chat [data-mu-style]').forEach(el => {
      el.removeAttribute('data-mu-ready'); el.removeAttribute('data-mu-playing');
    }));

    点.观察 = new MutationObserver(刷新);
    收尾.push(() => { if (点.观察) 点.观察.disconnect(); clearTimeout(点.定时); });
    监听();

    const ie = typeof tavern_events !== 'undefined' ? tavern_events : {};
    const 接 = (名, fn) => {
      if (!名) return;
      const h = eventOn(名, fn);
      收尾.push(() => { if (h && typeof h.stop === 'function') h.stop(); });
    };
    // AI 要回复了（不算后台静默生成、试算、续写、代写）
    接(ie.GENERATION_STARTED || 'generation_started', (类型, 选项, 试算) => {
      if (试算 || !回复类.has(类型 || 'normal') || (选项 && 选项.quiet_prompt)) return;
      等.淡出 = true; 等.新楼 = true;
    });
    // AI 的新楼层开始出字（流式第一个字，或者不流式时整楼到达）：正在放的歌渐弱停下
    const 楼开始 = () => { if (等.淡出) { 等.淡出 = false; 淡出停(); } };
    接(ie.STREAM_TOKEN_RECEIVED || 'stream_token_received', 楼开始);
    接(ie.MESSAGE_RECEIVED || 'message_received', (id, 类型) => { if (回复类.has(类型 || 'normal')) 楼开始(); });
    // 新楼层画好：有歌就自动放
    接(ie.CHARACTER_MESSAGE_RENDERED || 'character_message_rendered', (id, 类型) => {
      刷新();
      if (!等.新楼 || !回复类.has(类型 || 'normal')) return;
      等.新楼 = false;
      if (取设置().自动播放) 自动放(Number(id));
    });
    接(ie.GENERATION_STOPPED || 'generation_stopped', () => { 等.淡出 = false; 等.新楼 = false; });
    接(ie.GENERATION_ENDED || 'generation_ended', () => { 等.淡出 = false; });
    接(ie.MESSAGE_SWIPED || 'message_swiped', id => setTimeout(() => 换页(Number(id)), 300));
    ['USER_MESSAGE_RENDERED', 'MESSAGE_UPDATED', 'MESSAGE_EDITED', 'MESSAGE_DELETED'].forEach(名 => 接(ie[名], 刷新));
    接(ie.CHAT_CHANGED || 'chat_id_changed', () => {
      等.淡出 = false; 等.新楼 = false;
      失败录.clear();
      淡出停(800);
    });
    刷新();
  }

  // ---------- 设置面板（单页分组） ----------
  // 遮罩直接写满屏的宽高，不用 inset:0：酒馆给 html 加了 translateZ(0)，固定定位就以 html 为准；
  // 手机版酒馆的 body 是 position:fixed，html 高度是 0，inset:0 会把遮罩和面板压成 0 高（面板整个看不见）。
  // 手机上点按区域偏小的（开关、关闭）用透明的 ::before 往外扩，样子不变。
  const 面板样式 = `
#mu-ov{position:fixed;top:0;left:0;width:100%;height:100vh;height:100dvh;z-index:99999;background:rgba(30,18,50,.45);display:flex;align-items:center;justify-content:center;padding:12px}
#mu-ov *{box-sizing:border-box}
#mu-ov .mu-set{width:min(420px,100%);max-height:min(86vh,100%);max-height:min(86dvh,100%);overflow:auto;overscroll-behavior:contain;background:#fff;color:#2d2438;border-radius:18px;box-shadow:0 8px 28px rgba(50,25,90,.28),0 0 0 1px rgba(120,80,170,.16);font:15px/1.6 "Noto Sans SC","Microsoft YaHei",sans-serif}
#mu-ov .mu-top{display:flex;justify-content:space-between;align-items:center;padding:12px 16px;background:linear-gradient(90deg,#7b4fc0,#c4527f);color:#fff;font-weight:800;letter-spacing:2px;position:sticky;top:0;z-index:1}
#mu-ov .mu-x{background:none;border:0;color:#fff;font-size:1.1rem;cursor:pointer;padding:4px 8px;position:relative}
#mu-ov .mu-x::before{content:"";position:absolute;inset:-6px -8px}
#mu-ov .mu-sec{padding:12px 16px;border-top:1px solid #eee5fb}
