#mu-ov .mu-row{display:flex;justify-content:space-between;align-items:center;gap:10px;font-size:.9rem;margin:8px 0}
#mu-ov .mu-row small{display:block;color:#7a6a96;font-size:.72rem;line-height:1.4}
#mu-ov .mu-sw{flex:0 0 38px;width:38px;height:22px;border-radius:11px;border:0;background:#bfb2d6;position:relative;cursor:pointer;padding:0;transition:background .2s}
#mu-ov .mu-sw::before{content:"";position:absolute;inset:-10px -6px}
#mu-ov .mu-sw::after{content:"";position:absolute;left:3px;top:3px;width:16px;height:16px;border-radius:50%;background:#fff;transition:left .2s}
#mu-ov .mu-sw[aria-checked="true"]{background:#7b4fc0}#mu-ov .mu-sw[aria-checked="true"]::after{left:19px}
