#mu-ov .mu-b{flex:0 0 auto;border:1px solid #bfb2d6;border-radius:14px;background:#fff;color:#7b4fc0;font:inherit;font-size:.78rem;font-weight:700;padding:4px 12px;cursor:pointer;position:relative}
