    var catalog = state.comm.catalog || [];
    return catalog.find(function (item) { return /^角色[：:]/.test(text(item.displayName)) && liBareName(item.displayName) === name; })
      || catalog.find(function (item) { return liBareName(item.displayName) === name; }) || null;
  }
  // 名单要用卡绑的那本书（主世界书）的条目；来源书是别的书时先切过去
  async function liEnsureCatalog() {
    var primary = text(currentWorldbooks().primary), select = q('[data-comm-source-wb]', state.nodes.overlay);
    if (!primary || !select) return false;
    if (state.comm.sourceEntriesBook === primary && (state.comm.catalog || []).length) return true;
    if (select.value !== primary) { select.value = primary; }
    state.comm.loaded = false; await refreshCommData();
    return state.comm.sourceEntriesBook === primary;
  }
  async function liSelectOnly(keys) {
    state.comm.selectedRefs = keys.slice();
    var search = q('[data-comm-entry-search]', state.nodes.overlay); if (search) search.value = '';
    renderEntryOptions('');
  }
  async function liAddMember(name) {
    if (state.busy || threadWriteBlocked()) return;
    var added = liAddedMap(); if (added[name]) { openContact(added[name]); return; }
    try {
      if (!await liEnsureCatalog()) { setStatus('comm', '卡里没有绑定的世界书，名单加不了好友。', true); return; }
      var candidate = liCandidateFor(name);
      if (!candidate) { setStatus('comm', '卡里的世界书没有「角色：' + name + '」这一条。', true); return; }
      await liSelectOnly([candidate.key]);
      var input = q('[data-comm-npc-name]', state.nodes.overlay); if (input) input.value = name;
      await bindSelectedContact();
    } catch (error) { setStatus('comm', error.message || String(error), true); }
    finally { liRenderRoster(); }
  }
  async function liAddBand(bandName) {
    if (state.busy || threadWriteBlocked()) return;
    var band = liBandByName(bandName); if (!band) return;
    try {
      if (!await liEnsureCatalog()) { setStatus('comm', '卡里没有绑定的世界书，建不了乐队群。', true); return; }
      var keys = band.members.map(function (member) { var candidate = liCandidateFor(member.name); return candidate ? candidate.key : ''; }).filter(Boolean);
      if (keys.length < 2) { setStatus('comm', '卡里的世界书找不到这支乐队的角色条目。', true); return; }
      await liSelectOnly(keys);
      var input = q('[data-comm-group-name]', state.nodes.overlay); if (input) input.value = band.name;
      await createGroupFromSelection();
    } catch (error) { setStatus('comm', error.message || String(error), true); }
    finally { liRenderRoster(); }
  }

  // 私聊顶上的「⋯」菜单
  function liSetMore(open) {
    var overlay = state.nodes.overlay; if (!overlay) return;
    if (open) overlay.dataset.liMore = '1'; else delete overlay.dataset.liMore;
    var button = q('[data-li-more]', overlay); if (button) button.setAttribute('aria-expanded', open ? 'true' : 'false');
  }

  // 通话页：头像、名字放中间，接通、挂断、按住说话做成大圆钮，其余的收成小钮
  var LI_CALL_ICONS = {
    mic: "data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='%23fff' stroke-width='2' stroke-linecap='round'%3E%3Crect x='9' y='3' width='6' height='11' rx='3'/%3E%3Cpath d='M5.5 11a6.5 6.5 0 0 0 13 0M12 17.5V21'/%3E%3C/svg%3E",
    hang: "data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='%23fff' stroke-width='2' stroke-linejoin='round'%3E%3Cpath d='M3 14c5-5 13-5 18 0l-2.5 2.5-3-1.5v-2.5a10 10 0 0 0-5 0V15l-3 1.5z'/%3E%3C/svg%3E",
    loop: "data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='%23fff' stroke-width='2' stroke-linecap='round' stroke-linejoin='round'%3E%3Cpath d='M4 12a8 8 0 0 1 14-5.3M20 12a8 8 0 0 1-14 5.3'/%3E%3Cpath d='M18 3v4h-4M6 21v-4h4'/%3E%3C/svg%3E"
  };
  function liBuildCall() {
    var panel = q('[data-call-panel]', state.nodes.overlay); if (!panel || panel.dataset.liBuilt) return;
    panel.dataset.liBuilt = '1';
    var head = q('.pct-call-head', panel), hang = q('[data-call-hangup]', panel), mic = q('[data-call-mic]', panel), loop = q('[data-call-continuous]', panel);
    var face = make('div', 'li-call-face'), avatar = make('span', 'pct-avatar'), name = make('strong', '', ''), clock = make('time', '', '未接通');
    face.append(make('small', '', 'VOICE CALL'), avatar, name, clock);
    // 通话时长：原版接通时标 connected，从那一刻起算，挂断后下一通重新算
    var tick = hostWin.setInterval(function () {
      if (panel.hidden) return;
      var call = state.voiceCall;
      if (!call || !call.connected) { clock.textContent = '未接通'; return; }
      if (!call.liStart) call.liStart = Date.now();
      var s = Math.floor((Date.now() - call.liStart) / 1000);
      clock.textContent = String(Math.floor(s / 60)).padStart(2, '0') + ':' + String(s % 60).padStart(2, '0');
    }, 1000);
    state.controller.signal.addEventListener('abort', function () { hostWin.clearInterval(tick); });
    if (head) head.after(face);
    var main = make('div', 'li-call-main');
    [[loop, LI_CALL_ICONS.loop], [mic, LI_CALL_ICONS.mic], [hang, LI_CALL_ICONS.hang]].forEach(function (pair) { if (pair[0]) { pair[0].style.setProperty('--ico', 'url("' + pair[1] + '")'); main.appendChild(pair[0]); } });
    if (hang) hang.textContent = '挂断';
    var input = q('.pct-call-input', panel); if (input) input.before(main); else panel.appendChild(main);
    var title = q('[data-call-name]', panel);
    var paint = function () {
      var who = text(title && title.textContent) || text(state.comm.npc);
      name.textContent = who;
      var record = state.comm.store && who ? state.comm.store.contacts[npcId(who)] : null, url = recordAvatarUrl(record) || liApi().avatarFor(who), hit = liPersonFor(record, who);
      avatar.style.setProperty('--ring', hit ? (hit.member.color || hit.band.color) : '');
      avatar.replaceChildren(url ? Object.assign(make('img', 'pct-avatar-img'), { alt: '', src: url }) : make('span', 'pct-avatar-txt', who.slice(0, 1) || '讯'));
    };
    if (title && typeof hostWin.MutationObserver === 'function') { var watch = new hostWin.MutationObserver(paint); watch.observe(title, { childList: true, characterData: true, subtree: true }); state.controller.signal.addEventListener('abort', function () { watch.disconnect(); }); }
    paint();
  }

  // 启动钮：GPT 跑的图标（嵌在脚本里）；没有时画一个粉色小手机
  function liTriggerFace(trigger) {
    trigger.textContent = '';
    if (LIPHONE_ICON) { var img = make('img'); img.alt = ''; img.src = LIPHONE_ICON; trigger.appendChild(img); return; }
    trigger.innerHTML = '<svg viewBox="0 0 34 34" aria-hidden="true"><defs><linearGradient id="li-g" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#ff8fab"/><stop offset="1" stop-color="#ff4d7d"/></linearGradient></defs><rect x="8" y="3" width="18" height="28" rx="5" fill="url(#li-g)"/><path d="M12.5 11.5h9a2.5 2.5 0 0 1 2.5 2.5v3.5a2.5 2.5 0 0 1-2.5 2.5h-5l-3.2 2.4v-2.4h-.8A2.5 2.5 0 0 1 10 17.5V14a2.5 2.5 0 0 1 2.5-2.5z" fill="#fff"/><path d="M27 4.5l.9 2 2 .9-2 .9-.9 2-.9-2-2-.9 2-.9z" fill="#ffd54f"/></svg>';
  }

  // 字体（面板同一套，Google Fonts）、强调色（推し的应援色）、GPT 图
  function liFonts() {
    if (doc.getElementById('liphone-fonts')) return;
    var link = make('link'); link.id = 'liphone-fonts'; link.rel = 'stylesheet';
    link.href = 'https://fonts.googleapis.com/css2?family=Fredoka:wght@500;600;700&family=Noto+Sans+SC:wght@500;700;900&display=swap';
    doc.head.appendChild(link);
  }
  function liAccent() {
    var overlay = state.nodes.overlay, face = liFace(); if (!overlay) return;
    var color = face && text(face.accent);
    if (color && /^#[0-9a-f]{3,8}$/i.test(color)) { overlay.style.setProperty('--accent', color); if (state.nodes.trigger) state.nodes.trigger.style.setProperty('--accent', color); }
  }
  function liArt() {
    var overlay = state.nodes.overlay; if (!overlay) return;
    [['wall', '--li-wall', 'liWall'], ['call', '--li-call', 'liCallImg'], ['empty', '--li-empty', 'liEmpty'], ['paper', '--li-paper', 'liPaper']].forEach(function (slot) {
      var url = text(LIPHONE_ART && LIPHONE_ART[slot[0]]); if (!url) return;
      var apply = function () { if (!state.nodes.overlay) return; state.nodes.overlay.style.setProperty(slot[1], 'url("' + url + '")'); state.nodes.overlay.dataset[slot[2]] = '1'; };
      if (liArtTried[url] === true) { apply(); return; }
      if (liArtTried[url] === false) return;
      var probe = new hostWin.Image(); probe.onload = function () { liArtTried[url] = true; apply(); }; probe.onerror = function () { liArtTried[url] = false; }; probe.src = url;
    });
  }

  // 挂上以后：图标、名单、「⋯」、通话页、点气泡露出工具
  function liInitUi() {
    var overlay = state.nodes.overlay, signal = state.controller.signal; if (!overlay) return;
    liFonts(); liAccent(); liArt();
    overlay.dataset.liTab = state.comm.filter || 'all'; overlay.dataset.liSeg = overlay.dataset.liSeg || 'roster';
    qa('[data-li-seg]', overlay).forEach(function (button) { button.addEventListener('click', function () { liSetSeg(button.dataset.liSeg); }, { signal: signal }); });
    var roster = q('[data-li-roster]', overlay);
    if (roster) roster.addEventListener('click', function (event) {
      var band = event.target.closest('[data-li-band]'); if (band) { liAddBand(band.dataset.liBand); return; }
      var member = event.target.closest('[data-li-member]'); if (member) liAddMember(member.dataset.liMember);
    }, { signal: signal });
    // 「通话」挪到顶栏（原版装在「⋯」那一排里），「⋯」开关菜单，点菜单里的任何一项也收起来
    var head = q('[data-comm-thread] .pct-thread-head', overlay), more = q('[data-li-more]', overlay), call = q('[data-call-open]', overlay);
    if (more) more.innerHTML = liSvg(LI_IC.more);
    if (head && more && call) { call.className = 'li-round'; call.innerHTML = liSvg(LI_IC.phone); call.setAttribute('aria-label', '通话'); head.insertBefore(call, more); }
    if (more) more.addEventListener('click', function () { liSetMore(overlay.dataset.liMore !== '1'); }, { signal: signal });
    var tags = q('[data-comm-thread] .pct-thread-tags', overlay);
    if (tags) tags.addEventListener('click', function (event) { if (event.target.closest('button')) liSetMore(false); }, { signal: signal });
    var mask = q('[data-li-more-mask]', overlay); if (mask) mask.addEventListener('click', function () { liSetMore(false); }, { signal: signal });
    // 点一下气泡露出这条的时间和工具（手机上没有悬停）
    var messages = q('[data-comm-messages]', overlay);
    if (messages) messages.addEventListener('click', function (event) {
      if (event.target.closest('button')) return;
      var row = event.target.closest('.pct-message'); if (!row) return;
      qa('.pct-message.li-tools', messages).forEach(function (other) { if (other !== row) other.classList.remove('li-tools'); });
      row.classList.toggle('li-tools');
    }, { signal: signal });
    liBuildCall();
    liOnFilter();
  }

  try {
    var eventFirstFn = resolveFunction('eventMakeFirst'), eventOnFn = resolveFunction('eventOn'), subscribe = eventFirstFn || eventOnFn, events = window.tavern_events || hostWin.tavern_events || {};
    if (subscribe) {
      state.eventStops.push(subscribe(events.CHAT_CHANGED || 'chat_id_changed', onChatChanged));
      state.eventStops.push(subscribe(events.GENERATION_AFTER_COMMANDS || 'GENERATION_AFTER_COMMANDS', beforeGeneration));
      state.eventStops.push(subscribe(events.MESSAGE_RECEIVED || 'message_received', onNarrativeReceived));
      state.eventStops.push(subscribe(events.MESSAGE_UPDATED || 'message_updated', onNarrativeUpdated));
      state.eventStops.push(subscribe(events.MESSAGE_DELETED || 'message_deleted', onNarrativeRemoved));
      state.eventStops.push(subscribe(events.MESSAGE_SWIPED || 'message_swiped', onNarrativeRemoved));
      state.eventStops.push(subscribe(events.MESSAGE_EDITED || 'message_edited', onNarrativeRemoved));
    }
  } catch (_) {}
  window.addEventListener('pagehide', destroy); if (shouldBeActive()) mount(); hostWin[GLOBAL_KEY] = { version: VERSION, liphone: liApi(), open: openPhone, close: closePhone, route: route, avatar: function () { return avatarDiagnostics(); }, setAvatarMode: function (mode) { state.settings.avatarMode = mode === 'custom' || mode === 'none' ? mode : 'persona'; persistSettings(); syncQqHeader(); return avatarDiagnostics(); }, refreshWorldbooks: refreshWorldbooks, refreshStoryClock: updateClock, storyTime: function () { return Object.assign({}, state.storyClock); }, privateContextDiagnostics: function () { return cloneData(state.comm.contextDiagnostics, null); }, previewPrivateContext: function (npc) { updateClock(); var bundle = buildPrivateContextBundle(text(npc || state.comm.npc)); return { npc: bundle.npc, storyTime: bundle.storyTime, narrative: bundle.narrative, groupChat: bundle.groupChat, database: bundle.database, history: bundle.history, diagnostics: cloneData(state.comm.contextDiagnostics, null) }; }, injections: function () { return { mode: injectionMode(), manual: !!state.settings.injectModeManual, depth: injectDepth(), role: injectRole(), status: state.comm.injectStatus, count: state.comm.injectedCount, source: state.comm.injectSource, error: state.comm.injectError, visibility: injectionDiagnostics() }; }, exportStore: function () { return privateStorePayload(); }, importStore: function (raw) { return importPrivateStore(raw); }, refreshInjections: function () { return refreshStrictInjections(); }, retryStrict: function () { state.comm.strictRetried = false; return retryStrictModeOnce(); }, groups: function () { return (state.comm.groups || []).map(function (item) { return { id: item.id, name: item.name, members: item.members.map(function (member) { return member.name; }), messages: item.messageCount }; }); }, proactive: function () { return generateProactive(); }, autoProactive: function () { return runAutoProactive(); }, syncPrivateProjections: function () { return ensureSaveScope(true); }, scanProjectionRepair: scanProjectionRepair, runProjectionRepair: runProjectionRepair, destroy: destroy };
  console.log('[LiPhone] v' + LIPHONE_VERSION + '（通用通讯终端 ' + VERSION + '）已加载');
})();

